module.exports = [{"id":"p7a-guan-cang-hai","title":"观沧海","subtitle":"东汉·曹操","grade":"7a","tags":["写景","言志","乐府"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"东汉·曹操"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"曹操（155—220），字孟德，小名阿瞒，沛国谯县（今安徽亳州）人，东汉末年政治家、军事家、诗人，与其子曹丕、曹植合称“三曹”。\n生平经历：他二十岁举孝廉入仕，曾任洛阳北部尉、济南相等职；汉末天下大乱，他散家财起兵讨伐董卓，后迎汉献帝到许都，先后击败吕布、袁绍等割据势力，统一了北方；建安十三年在赤壁之战中被孙刘联军击败，天下遂成三国鼎立之势；晚年进爵魏王，其子曹丕称帝后追尊他为魏武帝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本诗是曹操《步出夏门行》的第一章，写北征乌桓归途登碣石山观海所见。前六句实写：先写水“澹澹”、山岛“竦峙”，动静相衬；再写树木百草的生机与秋风洪波的气势，由近及远。后四句转为虚写，以“日月之行”“星汉灿烂”的想象与夸张，把大海写成能吞吐日月星辰的博大境界，这其实是诗人一统天下的胸襟与抱负的写照"},{"type":"list","title":"中考考点","items":["“日月之行，若出其中","星汉灿烂，若出其里”的想象夸张与借景抒情、虚实结合","“涌”“竦峙”“澹澹”等词的炼字效果","四言乐府质朴刚健的语言风格","末句“幸甚至哉，歌以咏志”是乐府合乐的套语，与正文并无直接关系，常作判断题设点。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"东临碣石，以观沧海。","n":"","cn":"向东登上碣石山，来观赏这苍茫的大海。","parts":[{"t":"东"},{"t":"临","k":14},{"t":"碣石","k":2},{"t":"，以观"},{"t":"沧海","k":7},{"t":"。"}]},{"t":"水何澹澹，山岛竦峙。","n":"","cn":"海水多么荡漾啊，海中的山岛高高地耸立着。","parts":[{"t":"水何澹澹","k":0},{"t":"，山岛"},{"t":"竦峙","k":4},{"t":"。"}]},{"t":"树木丛生，百草丰茂。","n":"","cn":"岛上的树木一丛丛地生长，各种草长得很茂盛。","parts":[{"t":"树木丛生，百草丰茂。"}]},{"t":"秋风萧瑟，洪波涌起。","n":"","cn":"秋风吹得树木瑟瑟作响，巨大的波涛汹涌而起。","parts":[{"t":"秋风"},{"t":"萧瑟","k":5},{"t":"，"},{"t":"洪波","k":11},{"t":"涌起。"}]},{"t":"日月之行，若出其中；","n":"","cn":"太阳和月亮的运行，好像都是从这大海里升起、又落回海里。","parts":[{"t":"日月之行，"},{"t":"若","k":15},{"t":"出其中；"}]},{"t":"星汉灿烂，若出其里。","n":"","cn":"银河光辉灿烂，也好像是从这大海里生出来的。","parts":[{"t":"星汉","k":6},{"t":"灿烂，"},{"t":"若","k":15},{"t":"出其里。"}]},{"t":"幸甚至哉，歌以咏志。","n":"","cn":"庆幸得很，好极了，让我用诗歌来抒发自己的志向。这是乐府合乐时所加的套语。","parts":[{"t":"幸甚至哉","k":1},{"t":"，歌以咏志。"}]}],"words":[{"w":"水何澹澹","e":"【易错】“水何澹澹”的“澹”是三点水，不写“淡”；“竦峙”二字不写“耸峙”。"},{"w":"幸甚至哉","e":"【易错】“星汉”指银河，不写“星河”；“幸甚至哉”的“哉”不写“栽”。"},{"w":"碣石","e":"山名，在今河北昌黎西北"},{"w":"澹澹","e":"水波荡漾的样子"},{"w":"竦峙","e":"耸立"},{"w":"萧瑟","e":"形容风吹树木的声音"},{"w":"星汉","e":"银河"},{"w":"沧海","e":"【易错】“碣石”的“碣”是石字旁，不写“竭”；“沧海”不写“苍海”。"},{"w":"苍海","e":"【易错】“碣石”的“碣”是石字旁，不写“竭”；“沧海”不写“苍海”。"},{"w":"耸峙","e":"【易错】“水何澹澹”的“澹”是三点水，不写“淡”；“竦峙”二字不写“耸峙”。"},{"w":"箫瑟","e":"【易错】“萧瑟”草字头，不写“箫瑟”；“洪波”不写“红波”。"},{"w":"洪波","e":"【易错】“萧瑟”草字头，不写“箫瑟”；“洪波”不写“红波”。"},{"w":"红波","e":"【易错】“萧瑟”草字头，不写“箫瑟”；“洪波”不写“红波”。"},{"w":"星河","e":"【易错】“星汉”指银河，不写“星河”；“幸甚至哉”的“哉”不写“栽”。"},{"w":"临","e":"登上"},{"w":"若","e":"好像"},{"w":"碣","e":"【易错】“碣石”的“碣”是石字旁，不写“竭”；“沧海”不写“苍海”。"},{"w":"竭","e":"【易错】“碣石”的“碣”是石字旁，不写“竭”；“沧海”不写“苍海”。"},{"w":"澹","e":"【易错】“水何澹澹”的“澹”是三点水，不写“淡”；“竦峙”二字不写“耸峙”。"},{"w":"淡","e":"【易错】“水何澹澹”的“澹”是三点水，不写“淡”；“竦峙”二字不写“耸峙”。"},{"w":"哉","e":"【易错】“星汉”指银河，不写“星河”；“幸甚至哉”的“哉”不写“栽”。"},{"w":"栽","e":"【易错】“星汉”指银河，不写“星河”；“幸甚至哉”的“哉”不写“栽”。"}]},{"type":"list","title":"名句","items":["日月之行，若出其中；星汉灿烂，若出其里。"]},{"type":"list","title":"背诵提示","items":["“碣石”的“碣”是石字旁，不写“竭”；“沧海”不写“苍海”。","“水何澹澹”的“澹”是三点水，不写“淡”；“竦峙”二字不写“耸峙”。","“萧瑟”草字头，不写“箫瑟”；“洪波”不写“红波”。","“星汉”指银河，不写“星河”；“幸甚至哉”的“哉”不写“栽”。"]}],"questions":[{"id":"p-p7a-guan-cang-hai-m0","type":"fill","stem":"默写填空：日月之行，______。","answer":"若出其中。","explain":"出自《观沧海》（东汉·曹操）：日月之行，若出其中；星汉灿烂，若出其里。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-guan-cang-hai-u","type":"fill","stem":"理解性默写：向东登上碣石山，来观赏这苍茫的大海。","answer":"东临碣石，以观沧海。","explain":"出自《观沧海》（东汉·曹操）。句意：向东登上碣石山，来观赏这苍茫的大海。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-wen-wang-changling-zuoqian-longbiao","title":"闻王昌龄左迁龙标遥有此寄","subtitle":"唐·李白","grade":"7a","tags":["赠友","抒情","意象"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李白"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李白（701—762），字太白，号青莲居士，唐代伟大的浪漫主义诗人，被后人尊称为“诗仙”，与杜甫并称“李杜”，是我国古典诗歌浪漫主义传统的杰出代表。\n生平经历：少年时博览群书、喜好剑术任侠；二十五岁“仗剑去国”出蜀漫游，足迹遍及大江南北；天宝元年奉诏入长安供奉翰林，因遭权贵谗毁仅三年便离京；安史之乱中因参与永王李璘幕府获罪被流放夜郎，途中遇赦东归，晚年漂泊，762年病逝于当涂。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是李白听说好友王昌龄被贬龙标后写下的赠友诗。首句以“杨花”“子规”两个典型意象点明时令，杨花飘零见漂泊之感，子规悲啼寓离别之痛，景中含情，为全诗定下哀愁基调。次句直叙友人贬谪之远，“过五溪”三字写出路途荒远，关切之情自见。后两句最见匠心：诗人无法相送，便以拟人、想象的手法把“愁心”托付给明月，让它代自己陪伴友人远行，想象奇特而情意深挚，“直到”二字更见情谊之厚"},{"type":"list","title":"中考考点","items":["“杨花”“子规”的意象作用及首句的写景抒情","“我寄愁心与明月”的拟人与想象手法","诗人对友人的同情、思念与关切之情。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"杨花落尽子规啼，闻道龙标过五溪。","n":"","cn":"杨花落尽、杜鹃悲啼的暮春时节，我听说你被贬为龙标尉，去龙标要经过五溪。","parts":[{"t":"杨花落尽","k":0},{"t":"子规","k":2},{"t":"啼，闻道龙标过五"},{"t":"溪","k":8},{"t":"。"}]},{"t":"我寄愁心与明月，随君直到夜郎西。","n":"","cn":"我把满腔的愁心托付给天上的明月，让它随着你一直走到夜郎以西。","parts":[{"t":"我寄愁心与明月，"},{"t":"随","k":10},{"t":"君直到"},{"t":"夜郎","k":3},{"t":"西。"}]}],"words":[{"w":"杨花落尽","e":"【易错】“杨花落尽”的“尽”不写“进”；“子规”不写“子归”。"},{"w":"左迁","e":"贬官"},{"w":"子规","e":"杜鹃鸟"},{"w":"夜郎","e":"古地名，泛指湖南西部、贵州东部一带"},{"w":"子归","e":"【易错】“杨花落尽”的“尽”不写“进”；“子规”不写“子归”。"},{"w":"夜朗","e":"【易错】“随君直到夜郎西”的“随”不写“隋”，“夜郎”不写“夜朗”。"},{"w":"尽","e":"【易错】“杨花落尽”的“尽”不写“进”；“子规”不写“子归”。"},{"w":"进","e":"【易错】“杨花落尽”的“尽”不写“进”；“子规”不写“子归”。"},{"w":"溪","e":"【易错】“闻道龙标过五溪”的“溪”是三点水，不写“奚”。"},{"w":"奚","e":"【易错】“闻道龙标过五溪”的“溪”是三点水，不写“奚”。"},{"w":"随","e":"【易错】“随君直到夜郎西”的“随”不写“隋”，“夜郎”不写“夜朗”。"},{"w":"隋","e":"【易错】“随君直到夜郎西”的“随”不写“隋”，“夜郎”不写“夜朗”。"}]},{"type":"list","title":"名句","items":["我寄愁心与明月，随君直到夜郎西。"]},{"type":"list","title":"背诵提示","items":["“杨花落尽”的“尽”不写“进”；“子规”不写“子归”。","“闻道龙标过五溪”的“溪”是三点水，不写“奚”。","“随君直到夜郎西”的“随”不写“隋”，“夜郎”不写“夜朗”。"]}],"questions":[{"id":"p-p7a-wen-wang-changling-zuoqian-longbiao-m0","type":"fill","stem":"默写填空：我寄愁心与明月，______。","answer":"随君直到夜郎西。","explain":"出自《闻王昌龄左迁龙标遥有此寄》（唐·李白）：我寄愁心与明月，随君直到夜郎西。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-wen-wang-changling-zuoqian-longbiao-u","type":"fill","stem":"理解性默写：杨花落尽、杜鹃悲啼的暮春时节，我听说你被贬为龙标尉，去龙标要经过五溪。","answer":"杨花落尽子规啼，闻道龙标过五溪。","explain":"出自《闻王昌龄左迁龙标遥有此寄》（唐·李白）。句意：杨花落尽、杜鹃悲啼的暮春时节，我听说你被贬为龙标尉，去龙标要经过五溪。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-ci-beigushan-xia","title":"次北固山下","subtitle":"唐·王湾","grade":"7a","tags":["思乡","写景","律诗"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·王湾"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"王湾，唐代诗人，洛阳（今河南洛阳）人，生卒年不详，约活动于唐玄宗先天至开元年间，以一首《次北固山下》名垂后世。\n生平经历：先天年间考中进士，曾任荥阳主簿，后任洛阳尉；他仕途不显，曾往来于江东、吴楚一带，沿途写景抒怀。他存诗数量很少，却因《次北固山下》为当时文人所推重。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首五律写诗人客游江南、泊舟北固山下的所见所感。首联以“客路”“行舟”点出羁旅漂泊；颔联写江面开阔、帆影高悬，境界壮阔，一个“阔”字写尽春潮水势，一个“悬”字见帆影之端直，也暗写风顺船稳。颈联是千古名句：“生”“入”二字炼字极工，将海日、江春拟人化，写出时序交替、新事物必将取代旧事物的哲理，境界开阔而充满生机。尾联借“归雁”传书的传统意象，把羁旅之思、思乡之情落到实处"},{"type":"list","title":"中考考点","items":["“海日生残夜，江春入旧年”的炼字、哲理与名句默写","颔联写景的角度与“阔”“悬”的表达效果","全诗借景抒情、由景入情的结构，抒写诗人客游他乡的思乡之情。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"客路青山外，行舟绿水前。","n":"","cn":"我要走的旅途还在青山之外，乘船前行在碧绿的江水之上。","parts":[{"t":"客路","k":0},{"t":"青山外，行舟绿水前。"}]},{"t":"潮平两岸阔，风正一帆悬。","n":"","cn":"潮水涨满，两岸之间水面宽阔；顺风行驶，一叶白帆高高地悬挂着。","parts":[{"t":"潮平两岸"},{"t":"阔","k":10},{"t":"，"},{"t":"风正","k":1},{"t":"一帆"},{"t":"悬","k":7},{"t":"。"}]},{"t":"海日生残夜，江春入旧年。","n":"","cn":"夜色还没有褪尽，红日已从海上升起；旧年尚未过去，江上已有春意。","parts":[{"t":"海日"},{"t":"生","k":8},{"t":"残夜","k":5},{"t":"，江春"},{"t":"入","k":9},{"t":"旧年。"}]},{"t":"乡书何处达？归雁洛阳边。","n":"","cn":"家信什么时候才能送到呢？希望北归的大雁把它捎到洛阳去。","parts":[{"t":"乡书","k":2},{"t":"何处达？"},{"t":"归雁","k":3},{"t":"洛阳边。"}]}],"words":[{"w":"客路","e":"旅人前行的路"},{"w":"风正","e":"风顺"},{"w":"乡书","e":"家信"},{"w":"归雁","e":"北归的大雁"},{"w":"客露","e":"【易错】“客路青山外”的“客路”不写“客露”；“潮平两岸阔”的“阔”是门字框，不写“扩”。"},{"w":"残夜","e":"【易错】“海日生残夜”是“生”（升起），不能写成“升”；“残夜”不写“残叶”。"},{"w":"残叶","e":"【易错】“海日生残夜”是“生”（升起），不能写成“升”；“残夜”不写“残叶”。"},{"w":"悬","e":"端端直直地高挂着"},{"w":"生","e":"升起"},{"w":"入","e":"闯入、来到"},{"w":"阔","e":"【易错】“客路青山外”的“客路”不写“客露”；“潮平两岸阔”的“阔”是门字框，不写“扩”。"},{"w":"扩","e":"【易错】“客路青山外”的“客路”不写“客露”；“潮平两岸阔”的“阔”是门字框，不写“扩”。"},{"w":"心","e":"【易错】“风正一帆悬”的“悬”下面是“心”，不写“县”。"},{"w":"县","e":"【易错】“风正一帆悬”的“悬”下面是“心”，不写“县”。"},{"w":"升","e":"【易错】“海日生残夜”是“生”（升起），不能写成“升”；“残夜”不写“残叶”。"},{"w":"雁","e":"【易错】“归雁洛阳边”的“雁”不写“燕”。"},{"w":"燕","e":"【易错】“归雁洛阳边”的“雁”不写“燕”。"}]},{"type":"list","title":"名句","items":["海日生残夜，江春入旧年。","潮平两岸阔，风正一帆悬。"]},{"type":"list","title":"背诵提示","items":["“客路青山外”的“客路”不写“客露”；“潮平两岸阔”的“阔”是门字框，不写“扩”。","“风正一帆悬”的“悬”下面是“心”，不写“县”。","“海日生残夜”是“生”（升起），不能写成“升”；“残夜”不写“残叶”。","“归雁洛阳边”的“雁”不写“燕”。"]}],"questions":[{"id":"p-p7a-ci-beigushan-xia-m0","type":"fill","stem":"默写填空：海日生残夜，______。","answer":"江春入旧年。","explain":"出自《次北固山下》（唐·王湾）：海日生残夜，江春入旧年。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-ci-beigushan-xia-m1","type":"fill","stem":"默写填空：潮平两岸阔，______。","answer":"风正一帆悬。","explain":"出自《次北固山下》（唐·王湾）：潮平两岸阔，风正一帆悬。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-ci-beigushan-xia-u","type":"fill","stem":"理解性默写：我要走的旅途还在青山之外，乘船前行在碧绿的江水之上。","answer":"客路青山外，行舟绿水前。","explain":"出自《次北固山下》（唐·王湾）。句意：我要走的旅途还在青山之外，乘船前行在碧绿的江水之上。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-tian-jing-sha-qiu-si","title":"天净沙·秋思","subtitle":"元·马致远","grade":"7a","tags":["思乡","羁旅","写景","元曲"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"元·马致远"},{"k":"体裁","v":"曲"}]},{"type":"note","title":"作者简介","text":"马致远（约1250—约1321），号东篱，大都（今北京）人，元代杂剧家、散曲家，与关汉卿、白朴、郑光祖并称“元曲四大家”。\n生平经历：他早年热心功名而仕途失意，长期在大都一带漂泊；中年以后曾任江浙行省务官一类的小官，晚年退隐林泉，以“东篱”为号，寄托追慕陶渊明归隐田园之意；一生把失意与漂泊之感写进杂剧与散曲，作品数量多、流传广，被时人称为“曲状元”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首小令被誉为“秋思之祖”。前三句纯用白描，把“枯藤、老树、昏鸦、小桥、流水、人家、古道、西风、瘦马”九个名词性意象叠加成一幅深秋晚景图，不着一个“愁”字而愁绪满纸；其中“小桥流水人家”写温馨安适，与前后萧瑟之景形成对比，以乐景衬哀情，更显游子漂泊无依。末句“断肠人在天涯”卒章显志，直接点明主旨，情与景高度融合"},{"type":"list","title":"中考考点","items":["意象叠加、白描手法的赏析及其营造的凄凉气氛","“小桥流水人家”的对比衬托作用","“断肠人”所指与全曲抒发的天涯羁旅之愁。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"枯藤老树昏鸦，小桥流水人家，古道西风瘦马。","n":"","cn":"枯萎的藤蔓缠着老树，树上落着黄昏归巢的乌鸦；小桥下流水潺潺，旁边是几户农家；荒凉的古道上，西风阵阵，一匹瘦马载着我前行。","parts":[{"t":"枯藤","k":2},{"t":"老树"},{"t":"昏鸦","k":1},{"t":"，小"},{"t":"桥","k":9},{"t":"流水人家，古道西风瘦马。"}]},{"t":"夕阳西下，断肠人在天涯。","n":"","cn":"太阳就要落山了，我这极度悲伤的游子还漂泊在天涯。","parts":[{"t":"夕阳西下，"},{"t":"断肠人","k":0},{"t":"在"},{"t":"天涯","k":4},{"t":"。"}]}],"words":[{"w":"断肠人","e":"形容悲伤到极点的人"},{"w":"昏鸦","e":"黄昏时归巢的乌鸦"},{"w":"枯藤","e":"【易错】“枯藤”的“藤”是草字头，不写“滕”；“黄昏”的“昏”不写“晕”。"},{"w":"黄昏","e":"【易错】“枯藤”的“藤”是草字头，不写“滕”；“黄昏”的“昏”不写“晕”。"},{"w":"天涯","e":"【易错】“断肠人”的“肠”是月字旁，不写“扬”；“天涯”的“涯”是三点水，不写“崖”。"},{"w":"藤","e":"【易错】“枯藤”的“藤”是草字头，不写“滕”；“黄昏”的“昏”不写“晕”。"},{"w":"滕","e":"【易错】“枯藤”的“藤”是草字头，不写“滕”；“黄昏”的“昏”不写“晕”。"},{"w":"昏","e":"【易错】“枯藤”的“藤”是草字头，不写“滕”；“黄昏”的“昏”不写“晕”。"},{"w":"晕","e":"【易错】“枯藤”的“藤”是草字头，不写“滕”；“黄昏”的“昏”不写“晕”。"},{"w":"桥","e":"【易错】“小桥流水人家”的“桥”是木字旁，不写“侨”。"},{"w":"侨","e":"【易错】“小桥流水人家”的“桥”是木字旁，不写“侨”。"},{"w":"肠","e":"【易错】“断肠人”的“肠”是月字旁，不写“扬”；“天涯”的“涯”是三点水，不写“崖”。"},{"w":"扬","e":"【易错】“断肠人”的“肠”是月字旁，不写“扬”；“天涯”的“涯”是三点水，不写“崖”。"},{"w":"涯","e":"【易错】“断肠人”的“肠”是月字旁，不写“扬”；“天涯”的“涯”是三点水，不写“崖”。"},{"w":"崖","e":"【易错】“断肠人”的“肠”是月字旁，不写“扬”；“天涯”的“涯”是三点水，不写“崖”。"},{"w":"·","e":"【易错】曲牌名与题目之间用间隔号“·”，写作“天净沙·秋思”。"}]},{"type":"list","title":"名句","items":["夕阳西下，断肠人在天涯。"]},{"type":"list","title":"背诵提示","items":["“枯藤”的“藤”是草字头，不写“滕”；“黄昏”的“昏”不写“晕”。","“小桥流水人家”的“桥”是木字旁，不写“侨”。","“断肠人”的“肠”是月字旁，不写“扬”；“天涯”的“涯”是三点水，不写“崖”。","曲牌名与题目之间用间隔号“·”，写作“天净沙·秋思”。"]}],"questions":[{"id":"p-p7a-tian-jing-sha-qiu-si-m0","type":"fill","stem":"默写填空：夕阳西下，______。","answer":"断肠人在天涯。","explain":"出自《天净沙·秋思》（元·马致远）：夕阳西下，断肠人在天涯。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-tian-jing-sha-qiu-si-u","type":"fill","stem":"理解性默写：枯萎的藤蔓缠着老树，树上落着黄昏归巢的乌鸦；小桥下流水潺潺，旁边是几户农家；荒凉的古道上，西风阵阵，一匹瘦马载着我前行。","answer":"枯藤老树昏鸦，小桥流水人家，古道西风瘦马。","explain":"出自《天净沙·秋思》（元·马致远）。句意：枯萎的藤蔓缠着老树，树上落着黄昏归巢的乌鸦；小桥下流水潺潺，旁边是几户农家；荒凉的古道上，西风阵阵，一匹瘦马载着我前行。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-emei-shan-yue-ge","title":"峨眉山月歌","subtitle":"唐·李白","grade":"7a","tags":["写景","思乡","记游"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李白"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李白（701—762），字太白，号青莲居士，唐代伟大的浪漫主义诗人，被后人尊称为“诗仙”，与杜甫并称“李杜”，是我国古典诗歌浪漫主义传统的杰出代表。\n生平经历：少年时博览群书、喜好剑术任侠；二十五岁“仗剑去国”出蜀漫游，足迹遍及大江南北；天宝元年奉诏入长安供奉翰林，因遭权贵谗毁仅三年便离京；安史之乱中因参与永王李璘幕府获罪被流放夜郎，途中遇赦东归，晚年漂泊，762年病逝于当涂。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是李白初离蜀地时写的绝句，写月夜行舟的见闻与情思。前两句写景：以“半轮秋”写月，状其形而不言其圆缺之憾；“影入平羌江水流”中“入”“流”二字写出月影随江水而动的动态之美，静景动写，江月相映。后两句叙事抒情，连用清溪、三峡、渝州三个地名，一句一转，舟行迅疾、行程渐远之感全出。“思君不见”既是思月，也是思乡思友，山月与人情交织，含蓄深婉。全诗二十八字中嵌入峨眉山、平羌江、清溪、三峡、渝州五个地名而不觉堆砌，是李白绝句的妙处"},{"type":"list","title":"中考考点","items":["“影入平羌江水流”的动静结合与炼字","诗中地名连用的表达效果","“思君”所指的多重理解及全诗所抒发的依依惜别、思念故乡之情。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"峨眉山月半轮秋，影入平羌江水流。","n":"","cn":"峨眉山头高悬着半轮秋月，月影映入平羌江中，随着江水流动。","parts":[{"t":"峨眉","k":3},{"t":"山月"},{"t":"半轮","k":1},{"t":"秋，影入平"},{"t":"羌","k":8},{"t":"江水流。"}]},{"t":"夜发清溪向三峡，思君不见下渝州。","n":"","cn":"夜里我从清溪驿出发，驶向三峡；思念你却又见不到你，只好顺流直下渝州。","parts":[{"t":"夜发清溪","k":0},{"t":"向三峡，思"},{"t":"君","k":4},{"t":"不见下"},{"t":"渝州","k":2},{"t":"。"}]}],"words":[{"w":"夜发清溪","e":"【易错】“夜发清溪”的“溪”是三点水；“渝州”的“渝”是三点水，不写“愉”。"},{"w":"半轮","e":"指上弦月或下弦月"},{"w":"渝州","e":"今重庆一带"},{"w":"峨眉","e":"【易错】“峨眉”的“峨”是山字旁，不写“娥”或“鹅”。"},{"w":"君","e":"指峨眉山月，也指故乡的友人"},{"w":"峨","e":"【易错】“峨眉”的“峨”是山字旁，不写“娥”或“鹅”。"},{"w":"娥","e":"【易错】“峨眉”的“峨”是山字旁，不写“娥”或“鹅”。"},{"w":"鹅","e":"【易错】“峨眉”的“峨”是山字旁，不写“娥”或“鹅”。"},{"w":"羌","e":"【易错】“影入平羌江水流”的“羌”不写“姜”或“腔”。"},{"w":"姜","e":"【易错】“影入平羌江水流”的“羌”不写“姜”或“腔”。"},{"w":"腔","e":"【易错】“影入平羌江水流”的“羌”不写“姜”或“腔”。"},{"w":"溪","e":"【易错】“夜发清溪”的“溪”是三点水；“渝州”的“渝”是三点水，不写“愉”。"},{"w":"渝","e":"【易错】“夜发清溪”的“溪”是三点水；“渝州”的“渝”是三点水，不写“愉”。"},{"w":"愉","e":"【易错】“夜发清溪”的“溪”是三点水；“渝州”的“渝”是三点水，不写“愉”。"}]},{"type":"list","title":"名句","items":["峨眉山月半轮秋，影入平羌江水流。"]},{"type":"list","title":"背诵提示","items":["“峨眉”的“峨”是山字旁，不写“娥”或“鹅”。","“影入平羌江水流”的“羌”不写“姜”或“腔”。","“夜发清溪”的“溪”是三点水；“渝州”的“渝”是三点水，不写“愉”。"]}],"questions":[{"id":"p-p7a-emei-shan-yue-ge-m0","type":"fill","stem":"默写填空：峨眉山月半轮秋，______。","answer":"影入平羌江水流。","explain":"出自《峨眉山月歌》（唐·李白）：峨眉山月半轮秋，影入平羌江水流。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-emei-shan-yue-ge-u","type":"fill","stem":"理解性默写：峨眉山头高悬着半轮秋月，月影映入平羌江中，随着江水流动。","answer":"峨眉山月半轮秋，影入平羌江水流。","explain":"出自《峨眉山月歌》（唐·李白）。句意：峨眉山头高悬着半轮秋月，月影映入平羌江中，随着江水流动。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-jiang-nan-feng-li-gui-nian","title":"江南逢李龟年","subtitle":"唐·杜甫","grade":"7a","tags":["感怀","伤时","绝句"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·杜甫"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"杜甫（712—770），字子美，自号少陵野老，唐代伟大的现实主义诗人，被后人尊称为“诗圣”，他的诗广泛而深刻地反映了唐代由盛转衰时期的社会现实，被称为“诗史”。\n生平经历：青年时曾漫游吴越齐赵，并与李白相识；后困居长安十年，屡试不第；安史之乱中被叛军俘获，逃出后任左拾遗，又因直言进谏被贬；晚年流寓成都，在浣花溪畔建草堂，后又漂泊于夔州、湖湘一带，770年病逝于湘江舟中。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首绝句是杜甫晚年的名作。前两句追忆当年在长安与李龟年的交往，“岐王宅里”“崔九堂前”写出开元盛世时歌舞升平的景象，也写出两人昔日的身价与风光，语调从容而含追念。后两句折回眼前：江南风景正好，却偏在“落花时节”重逢。“落花时节”一语双关，既是暮春时令，又暗喻大唐由盛转衰、两人身世飘零，一个“又”字把四十年的沧桑之感压于纸上。全诗以乐景写哀，不着一字感慨而感慨无穷，被誉为“以盛衰之感，写兴亡之痛”的绝唱"},{"type":"list","title":"中考考点","items":["“落花时节”的双关含义","今昔对比、以乐景写哀情的写法","诗人对国事凋零、人生飘零的深沉感慨。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"岐王宅里寻常见，崔九堂前几度闻。","n":"","cn":"当年在岐王的府邸里常常能见到你，在崔九的厅堂前也多次听过你的歌唱。","parts":[{"t":"岐王","k":2},{"t":"宅里寻常见，"},{"t":"崔九堂前","k":1},{"t":"几度闻。"}]},{"t":"正是江南好风景，落花时节又逢君。","n":"","cn":"如今正是江南风景大好的时候，在这落花时节又遇见了你。","parts":[{"t":"正是江南好风景，"},{"t":"落花时节","k":0},{"t":"又"},{"t":"逢","k":8},{"t":"君。"}]}],"words":[{"w":"落花时节","e":"暮春，也暗喻国家的衰败与身世的飘零"},{"w":"崔九堂前","e":"【易错】“崔九堂前”的“堂”不写“棠”。"},{"w":"岐王","e":"唐玄宗的弟弟李范"},{"w":"崔九","e":"殿中监崔涤"},{"w":"岐","e":"【易错】“岐王”的“岐”是山字旁，不写“歧”。"},{"w":"歧","e":"【易错】“岐王”的“岐”是山字旁，不写“歧”。"},{"w":"堂","e":"【易错】“崔九堂前”的“堂”不写“棠”。"},{"w":"棠","e":"【易错】“崔九堂前”的“堂”不写“棠”。"},{"w":"逢","e":"【易错】“落花时节又逢君”的“逢”不写“缝”。"},{"w":"缝","e":"【易错】“落花时节又逢君”的“逢”不写“缝”。"}]},{"type":"list","title":"名句","items":["正是江南好风景，落花时节又逢君。"]},{"type":"list","title":"背诵提示","items":["“岐王”的“岐”是山字旁，不写“歧”。","“崔九堂前”的“堂”不写“棠”。","“落花时节又逢君”的“逢”不写“缝”。"]}],"questions":[{"id":"p-p7a-jiang-nan-feng-li-gui-nian-m0","type":"fill","stem":"默写填空：正是江南好风景，______。","answer":"落花时节又逢君。","explain":"出自《江南逢李龟年》（唐·杜甫）：正是江南好风景，落花时节又逢君。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-jiang-nan-feng-li-gui-nian-u","type":"fill","stem":"理解性默写：当年在岐王的府邸里常常能见到你，在崔九的厅堂前也多次听过你的歌唱。","answer":"岐王宅里寻常见，崔九堂前几度闻。","explain":"出自《江南逢李龟年》（唐·杜甫）。句意：当年在岐王的府邸里常常能见到你，在崔九的厅堂前也多次听过你的歌唱。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-xing-jun-jiu-ri-si-chang-an-gu-yuan","title":"行军九日思长安故园","subtitle":"唐·岑参","grade":"7a","tags":["思乡","忧国","重阳"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·岑参"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"岑参（约715—770），荆州江陵（今湖北江陵）人，唐代边塞诗派代表诗人。他与高适并称“高岑”，因官至嘉州刺史，世称“岑嘉州”。\n生平经历：天宝年间中进士，曾两次出塞，先后在安西节度使高仙芝、封常清幕府中任职，长年往来于轮台、雪海之间；安史之乱后回朝任右补阙等职，后出任嘉州刺史，罢官后客死成都。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"此诗写于安史之乱中诗人随军行军之际，借重阳登高生发情思。首句“强欲”二字，写出无心登高又不得不应节的矛盾与苦涩；次句化用陶渊明重阳无酒、王弘送酒的典故，写乱世行军之萧条，暗含无人相慰的孤寂。后两句由己及物、由眼前到故园：“遥怜”直抒怜惜之情，故园的菊花本应开在庭院篱边，如今却“应傍战场开”，一个“应”字是设想之词，把个人思乡与家国残破、战乱未平融为一体，含蓄沉痛"},{"type":"list","title":"中考考点","items":["“强”“遥怜”“应傍”等词的表达效果","虚写（想象故园菊花）与实写行军处境的结合","借重阳登高抒写思乡之情与忧国伤时之感。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"强欲登高去，无人送酒来。","n":"","cn":"重阳节勉强想去登高，可是没有人送酒来。","parts":[{"t":"强","k":4},{"t":"欲登高去，无人送酒来。"}]},{"t":"遥怜故园菊，应傍战场开。","n":"","cn":"我在远方怜惜长安故园里的菊花，它们应该正挨着战场开放吧。","parts":[{"t":"遥"},{"t":"怜","k":6},{"t":"故园","k":2},{"t":"菊，应"},{"t":"傍","k":5},{"t":"战场开。"}]}],"words":[{"w":"九日","e":"指重阳节，有登高、饮菊花酒的习俗"},{"w":"怜惜","e":"【易错】“遥怜故园菊”的“怜”是“怜惜”，不写“莲”；“故园”不写“故圆”。"},{"w":"故园","e":"【易错】“遥怜故园菊”的“怜”是“怜惜”，不写“莲”；“故园”不写“故圆”。"},{"w":"故圆","e":"【易错】“遥怜故园菊”的“怜”是“怜惜”，不写“莲”；“故园”不写“故圆”。"},{"w":"强","e":"勉强"},{"w":"傍","e":"靠近"},{"w":"怜","e":"【易错】“遥怜故园菊”的“怜”是“怜惜”，不写“莲”；“故园”不写“故圆”。"},{"w":"莲","e":"【易错】“遥怜故园菊”的“怜”是“怜惜”，不写“莲”；“故园”不写“故圆”。"},{"w":"旁","e":"【易错】“应傍战场开”的“傍”读 bàng，单人旁，不写“旁”。"}]},{"type":"list","title":"名句","items":["遥怜故园菊，应傍战场开。"]},{"type":"list","title":"背诵提示","items":["“强欲登高去”的“强”读 qiǎng，意为勉强。","“遥怜故园菊”的“怜”是“怜惜”，不写“莲”；“故园”不写“故圆”。","“应傍战场开”的“傍”读 bàng，单人旁，不写“旁”。"]}],"questions":[{"id":"p-p7a-xing-jun-jiu-ri-si-chang-an-gu-yuan-m0","type":"fill","stem":"默写填空：遥怜故园菊，______。","answer":"应傍战场开。","explain":"出自《行军九日思长安故园》（唐·岑参）：遥怜故园菊，应傍战场开。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-xing-jun-jiu-ri-si-chang-an-gu-yuan-u","type":"fill","stem":"理解性默写：重阳节勉强想去登高，可是没有人送酒来。","answer":"强欲登高去，无人送酒来。","explain":"出自《行军九日思长安故园》（唐·岑参）。句意：重阳节勉强想去登高，可是没有人送酒来。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-ye-shang-shou-xiang-cheng-wen-di","title":"夜上受降城闻笛","subtitle":"唐·李益","grade":"7a","tags":["边塞","思乡","写景"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李益"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李益（约750—约830），字君虞，陇西姑臧（今甘肃武威）人，唐代诗人，中唐边塞诗的代表人物之一，尤以七言绝句著称。\n生平经历：大历年间中进士，因仕途不得意，曾长期在幽州、邠宁等北方边地节度使的幕府中任职，前后在军中近二十年；他熟悉边塞风光与士卒生活，所写多真切感人；后官至礼部尚书，约卒于文宗大和年间。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首边塞绝句写戍边将士的思乡之情。前两句写景，由远及近：上句写“沙似雪”，下句写“月如霜”，两个比喻把边塞月夜的凄寒、荒凉写足，色彩冷白，境界苍茫，为下文抒情渲染了气氛。“沙似雪”“月如霜”皆因月光而生，句中不见“月”字以外的亮色，却满纸寒意。第三句转写听觉，“不知何处”四字写笛声忽起、来处不明，更添苍凉悠远。末句最见功力：“一夜”写听笛之久、不寐之状，“尽”字写思乡之情的普遍与深重，不言悲而悲意盈篇，含蓄有力"},{"type":"list","title":"中考考点","items":["“沙似雪”“月如霜”两个比喻的写景作用","由视觉到听觉、由景到情的思路层次","“尽”“一夜”等词的表现力与全诗戍边思乡的主旨。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"回乐烽前沙似雪，受降城外月如霜。","n":"","cn":"回乐烽前面的沙地在月光下白得像雪，受降城外的月色清冷得如同寒霜。","parts":[{"t":"回乐烽","k":0},{"t":"前沙似雪，"},{"t":"受降城","k":1},{"t":"外月如霜。"}]},{"t":"不知何处吹芦管，一夜征人尽望乡。","n":"","cn":"不知从哪里传来吹芦管的声音，整整一夜，戍边的征人都望着故乡的方向。","parts":[{"t":"不知何处"},{"t":"吹芦管","k":2},{"t":"，一夜"},{"t":"征人","k":4},{"t":"尽望乡。"}]}],"words":[{"w":"回乐烽","e":"烽火台名"},{"w":"受降城","e":"唐时为防御突厥所筑"},{"w":"吹芦管","e":"【易错】“吹芦管”的“芦”是草字头，不写“卢”；“征人”不写“争人”。"},{"w":"芦管","e":"即胡笳一类的管乐器"},{"w":"征人","e":"戍边的将士"},{"w":"争人","e":"【易错】“吹芦管”的“芦”是草字头，不写“卢”；“征人”不写“争人”。"},{"w":"烽","e":"【易错】“回乐烽”的“烽”是火字旁，教材作“烽”，不写“峰”或“锋”。"},{"w":"峰","e":"【易错】“回乐烽”的“烽”是火字旁，教材作“烽”，不写“峰”或“锋”。"},{"w":"锋","e":"【易错】“回乐烽”的“烽”是火字旁，教材作“烽”，不写“峰”或“锋”。"},{"w":"降","e":"【易错】“受降城”的“降”读 xiáng（使敌人投降），不读 jiàng。"},{"w":"芦","e":"【易错】“吹芦管”的“芦”是草字头，不写“卢”；“征人”不写“争人”。"},{"w":"卢","e":"【易错】“吹芦管”的“芦”是草字头，不写“卢”；“征人”不写“争人”。"}]},{"type":"list","title":"名句","items":["不知何处吹芦管，一夜征人尽望乡。"]},{"type":"list","title":"背诵提示","items":["“回乐烽”的“烽”是火字旁，教材作“烽”，不写“峰”或“锋”。","“受降城”的“降”读 xiáng（使敌人投降），不读 jiàng。","“吹芦管”的“芦”是草字头，不写“卢”；“征人”不写“争人”。"]}],"questions":[{"id":"p-p7a-ye-shang-shou-xiang-cheng-wen-di-m0","type":"fill","stem":"默写填空：不知何处吹芦管，______。","answer":"一夜征人尽望乡。","explain":"出自《夜上受降城闻笛》（唐·李益）：不知何处吹芦管，一夜征人尽望乡。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-ye-shang-shou-xiang-cheng-wen-di-u","type":"fill","stem":"理解性默写：回乐烽前面的沙地在月光下白得像雪，受降城外的月色清冷得如同寒霜。","answer":"回乐烽前沙似雪，受降城外月如霜。","explain":"出自《夜上受降城闻笛》（唐·李益）。句意：回乐烽前面的沙地在月光下白得像雪，受降城外的月色清冷得如同寒霜。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-qiu-ci-qi-yi","title":"秋词（其一）","subtitle":"唐·刘禹锡","grade":"7a","tags":["言志","写景","秋景"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·刘禹锡"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"刘禹锡（772—842），字梦得，洛阳（今河南洛阳）人，唐代文学家、哲学家。他与柳宗元并称“刘柳”，与白居易并称“刘白”；因其诗风豪迈刚健，白居易称他为“诗豪”。\n生平经历：贞元年间与柳宗元同榜进士，后一同参与永贞革新；革新失败后先被贬为朗州司马，此后又辗转连州、夔州、和州等地，前后贬谪二十三年；晚年回到洛阳任太子宾客，世称“刘宾客”，加检校礼部尚书，卒于洛阳。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首七绝一反古人悲秋的传统，唱出昂扬奋发的秋之歌。首句先立“悲秋”之旧调，次句以“我言”直接反驳，“胜春朝”三字斩钉截铁，写出诗人豪迈乐观、不随流俗的个性。后两句由议论转为写景：秋日天高气爽，“一鹤排云”这一独特意象矫健昂扬，既是实景，又是诗人不屈不挠、奋发向上的自我写照；“便引诗情到碧霄”将无形的诗情随鹤引向青天，想象奇特，境界开阔"},{"type":"list","title":"中考考点","items":["与“悲秋”传统对比、借景抒情的写法","“排”字的炼字效果（写出白鹤冲破云层的力量与气势）","“鹤”与“碧霄”意象寄托的诗人豪情及全诗乐观向上的主旨。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"自古逢秋悲寂寥，我言秋日胜春朝。","n":"","cn":"自古以来，人们一到秋天就悲叹冷清萧条，我却说秋天的景色胜过春天。","parts":[{"t":"自古逢秋"},{"t":"悲寂寥","k":1},{"t":"，我言秋日胜"},{"t":"春朝","k":3},{"t":"。"}]},{"t":"晴空一鹤排云上，便引诗情到碧霄。","n":"","cn":"万里晴空中一只白鹤推开云层直冲而上，便把我的诗兴诗情也带到了碧蓝的天空。","parts":[{"t":"晴空一鹤","k":0},{"t":"排","k":5},{"t":"云上，便引诗情到"},{"t":"碧霄","k":4},{"t":"。"}]}],"words":[{"w":"晴空一鹤","e":"【易错】“晴空一鹤”的“鹤”左边是“隺”，不写“鹳”；“碧霄”是雨字头的“霄”，不写“宵”。"},{"w":"悲寂寥","e":"【易错】“悲寂寥”的“寥”是宝盖头，不写“廖”或“谬”。"},{"w":"寂寥","e":"冷清萧条"},{"w":"春朝","e":"春天的早晨，这里泛指春天"},{"w":"碧霄","e":"青天"},{"w":"排","e":"推开"},{"w":"寥","e":"【易错】“悲寂寥”的“寥”是宝盖头，不写“廖”或“谬”。"},{"w":"廖","e":"【易错】“悲寂寥”的“寥”是宝盖头，不写“廖”或“谬”。"},{"w":"谬","e":"【易错】“悲寂寥”的“寥”是宝盖头，不写“廖”或“谬”。"},{"w":"朝","e":"【易错】“春朝”的“朝”读 zhāo，指早晨。"},{"w":"鹤","e":"【易错】“晴空一鹤”的“鹤”左边是“隺”，不写“鹳”；“碧霄”是雨字头的“霄”，不写“宵”。"},{"w":"隺","e":"【易错】“晴空一鹤”的“鹤”左边是“隺”，不写“鹳”；“碧霄”是雨字头的“霄”，不写“宵”。"},{"w":"鹳","e":"【易错】“晴空一鹤”的“鹤”左边是“隺”，不写“鹳”；“碧霄”是雨字头的“霄”，不写“宵”。"},{"w":"霄","e":"【易错】“晴空一鹤”的“鹤”左边是“隺”，不写“鹳”；“碧霄”是雨字头的“霄”，不写“宵”。"},{"w":"宵","e":"【易错】“晴空一鹤”的“鹤”左边是“隺”，不写“鹳”；“碧霄”是雨字头的“霄”，不写“宵”。"}]},{"type":"list","title":"名句","items":["晴空一鹤排云上，便引诗情到碧霄。"]},{"type":"list","title":"背诵提示","items":["“悲寂寥”的“寥”是宝盖头，不写“廖”或“谬”。","“春朝”的“朝”读 zhāo，指早晨。","“晴空一鹤”的“鹤”左边是“隺”，不写“鹳”；“碧霄”是雨字头的“霄”，不写“宵”。"]}],"questions":[{"id":"p-p7a-qiu-ci-qi-yi-m0","type":"fill","stem":"默写填空：晴空一鹤排云上，______。","answer":"便引诗情到碧霄。","explain":"出自《秋词（其一）》（唐·刘禹锡）：晴空一鹤排云上，便引诗情到碧霄。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-qiu-ci-qi-yi-u","type":"fill","stem":"理解性默写：自古以来，人们一到秋天就悲叹冷清萧条，我却说秋天的景色胜过春天。","answer":"自古逢秋悲寂寥，我言秋日胜春朝。","explain":"出自《秋词（其一）》（唐·刘禹锡）。句意：自古以来，人们一到秋天就悲叹冷清萧条，我却说秋天的景色胜过春天。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-ye-yu-ji-bei","title":"夜雨寄北","subtitle":"唐·李商隐","grade":"7a","tags":["思念","羁旅","抒情"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李商隐"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李商隐（约813—约858），字义山，号玉谿生，又号樊南生，怀州河内（今河南沁阳）人，晚唐诗人，与杜牧并称“小李杜”。\n生平经历：他少年时得到天平军节度使令狐楚的赏识，二十五岁考中进士；后来入泾原节度使王茂元幕府并成为其女婿，因而卷入牛李党争，被两方猜忌，一生只做过校书郎、县尉一类小官，长期辗转于各地幕府；妻子去世后他更加郁郁寡欢，四十余岁便在郑州病逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗以问答起笔，写客居巴蜀的羁旅之愁与对亲友的深切思念。首句“问归期”与“未有期”一问答，写出归期难定的怅惘；次句以“巴山夜雨涨秋池”的眼前实景作答，雨声与愁绪俱涨，景中含情，一个“涨”字既写雨水又写愁思之深。后两句笔锋一转，由今夜的孤苦想象未来重逢的温馨：“共剪西窗烛”画面温暖，与眼前的孤灯夜雨形成鲜明对照。全诗“巴山夜雨”两见，一实一虚，今夜的凄凉与来日的欢聚相互映照，回环往复，含蓄深婉"},{"type":"list","title":"中考考点","items":["“巴山夜雨”重复出现的深意及时空交错（虚实相生）的写法","“涨”字的炼字效果","想象重逢、以未来的欢聚反衬今夜孤独的抒情方式。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"君问归期未有期，巴山夜雨涨秋池。","n":"","cn":"你问我什么时候回家，我还没有确定的日期；今夜巴山大雨滂沱，雨水涨满了秋天的池塘。","parts":[{"t":"君问归期未有期，"},{"t":"巴山","k":2},{"t":"夜雨"},{"t":"涨秋池","k":0},{"t":"。"}]},{"t":"何当共剪西窗烛，却话巴山夜雨时。","n":"","cn":"什么时候我们才能一起坐在西窗下，剪着烛花谈心，回头再说起今夜巴山夜雨中的思念呢？何当：什么时候","parts":[{"t":"何当共"},{"t":"剪","k":8},{"t":"西窗"},{"t":"烛","k":11},{"t":"，"},{"t":"却话","k":3},{"t":"巴山","k":2},{"t":"夜雨时。"}]}],"words":[{"w":"涨秋池","e":"【易错】“涨秋池”的“涨”是三点水，不写“帐”或“胀”。"},{"w":"回头说","e":"【易错】“却话巴山夜雨时”的“却话”是“回头说”，不写“却说”。"},{"w":"巴山","e":"泛指巴蜀地区"},{"w":"却话","e":"回头说、追溯往事"},{"w":"却说","e":"【易错】“却话巴山夜雨时”的“却话”是“回头说”，不写“却说”。"},{"w":"涨","e":"【易错】“涨秋池”的“涨”是三点水，不写“帐”或“胀”。"},{"w":"帐","e":"【易错】“涨秋池”的“涨”是三点水，不写“帐”或“胀”。"},{"w":"胀","e":"【易错】“涨秋池”的“涨”是三点水，不写“帐”或“胀”。"},{"w":"剪","e":"【易错】“共剪西窗烛”的“剪”下面是“刀”，不写“箭”；“烛”是火字旁，不写“浊”。"},{"w":"刀","e":"【易错】“共剪西窗烛”的“剪”下面是“刀”，不写“箭”；“烛”是火字旁，不写“浊”。"},{"w":"箭","e":"【易错】“共剪西窗烛”的“剪”下面是“刀”，不写“箭”；“烛”是火字旁，不写“浊”。"},{"w":"烛","e":"【易错】“共剪西窗烛”的“剪”下面是“刀”，不写“箭”；“烛”是火字旁，不写“浊”。"},{"w":"浊","e":"【易错】“共剪西窗烛”的“剪”下面是“刀”，不写“箭”；“烛”是火字旁，不写“浊”。"}]},{"type":"list","title":"名句","items":["何当共剪西窗烛，却话巴山夜雨时。"]},{"type":"list","title":"背诵提示","items":["“涨秋池”的“涨”是三点水，不写“帐”或“胀”。","“共剪西窗烛”的“剪”下面是“刀”，不写“箭”；“烛”是火字旁，不写“浊”。","“却话巴山夜雨时”的“却话”是“回头说”，不写“却说”。"]}],"questions":[{"id":"p-p7a-ye-yu-ji-bei-m0","type":"fill","stem":"默写填空：何当共剪西窗烛，______。","answer":"却话巴山夜雨时。","explain":"出自《夜雨寄北》（唐·李商隐）：何当共剪西窗烛，却话巴山夜雨时。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-ye-yu-ji-bei-u","type":"fill","stem":"理解性默写：你问我什么时候回家，我还没有确定的日期；今夜巴山大雨滂沱，雨水涨满了秋天的池塘。","answer":"君问归期未有期，巴山夜雨涨秋池。","explain":"出自《夜雨寄北》（唐·李商隐）。句意：你问我什么时候回家，我还没有确定的日期；今夜巴山大雨滂沱，雨水涨满了秋天的池塘。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-shi-yi-yue-si-ri-feng-yu-da-zuo-qi-er","title":"十一月四日风雨大作（其二）","subtitle":"宋·陆游","grade":"7a","tags":["爱国","言志","梦境"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·陆游"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"陆游（1125—1210），字务观，号放翁，越州山阴（今浙江绍兴）人，南宋爱国诗人，一生力主抗金，现存诗作九千余首，是我国古代存诗最多的诗人之一。\n生平经历：他出生在北宋灭亡前夕，少年时便立下抗金报国之志；二十九岁参加锁厅考试名列第一，却因名次排在秦桧之孙的前面而遭排挤；孝宗时赐进士出身，曾入四川宣抚使王炎幕府，亲历南郑前线的军旅生活；此后因坚持抗金屡遭贬黜，长期闲居山阴故里，八十五岁临终仍写下《示儿》，嘱咐“王师北定中原日，家祭无忘告乃翁”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"此诗写于陆游六十八岁闲居山阴之时，是诗人爱国情怀的集中体现。前两句直抒胸臆：“僵卧孤村”写境遇之衰病孤苦，“不自哀”三字一转，见其志不衰；“尚思为国戍轮台”以“尚”字写老而弥坚的报国之心，个人困顿与家国大义形成强烈反差。后两句由现实转入梦境：夜阑风雨本是眼前实景，却因“风吹雨”的声音勾起诗人往昔铁马冰河的征战记忆，化实为虚，由听觉引出梦境。以梦境写现实，正是现实壮志难酬的曲折反映，读来悲壮感人"},{"type":"list","title":"中考考点","items":["“僵卧”“尚思”所表现的人物形象与思想感情","由风雨声到“铁马冰河”的虚实相生、借梦抒怀的写法","全诗爱国报国、壮志未酬的主旨与名句默写。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"僵卧孤村不自哀，尚思为国戍轮台。","n":"","cn":"我僵直地躺在孤寂的村落里，并不为自己的处境而感到悲哀，心中还想着替国家戍守边疆。","parts":[{"t":"僵卧","k":2},{"t":"孤村不自哀，尚思为国"},{"t":"戍轮台","k":1},{"t":"。"}]},{"t":"夜阑卧听风吹雨，铁马冰河入梦来。","n":"","cn":"夜深了，我躺在床上听着风吹雨打的声音，披着铁甲的战马、跨过冰河的征战场景就闯入了我的梦中。","parts":[{"t":"夜阑","k":3},{"t":"卧听风吹雨，"},{"t":"铁马冰河","k":0},{"t":"入梦来。"}]}],"words":[{"w":"铁马冰河","e":"【易错】“夜阑”的“阑”是门字框，不写“澜”；“铁马冰河”不写“冰合”。"},{"w":"戍轮台","e":"指戍守边疆，轮台在今新疆"},{"w":"僵卧","e":"躺卧不起"},{"w":"夜阑","e":"夜深"},{"w":"铁马","e":"披着铁甲的战马"},{"w":"冰合","e":"【易错】“夜阑”的“阑”是门字框，不写“澜”；“铁马冰河”不写“冰合”。"},{"w":"僵","e":"【易错】“僵卧”的“僵”是单人旁，不写“缰”或“疆”。"},{"w":"缰","e":"【易错】“僵卧”的“僵”是单人旁，不写“缰”或“疆”。"},{"w":"疆","e":"【易错】“僵卧”的“僵”是单人旁，不写“缰”或“疆”。"},{"w":"戍","e":"【易错】“戍轮台”的“戍”是“戊”中一点（点、横、撇、戈），不写“戌”“戊”或“戎”。"},{"w":"戊","e":"【易错】“戍轮台”的“戍”是“戊”中一点（点、横、撇、戈），不写“戌”“戊”或“戎”。"},{"w":"戌","e":"【易错】“戍轮台”的“戍”是“戊”中一点（点、横、撇、戈），不写“戌”“戊”或“戎”。"},{"w":"戎","e":"【易错】“戍轮台”的“戍”是“戊”中一点（点、横、撇、戈），不写“戌”“戊”或“戎”。"},{"w":"阑","e":"【易错】“夜阑”的“阑”是门字框，不写“澜”；“铁马冰河”不写“冰合”。"},{"w":"澜","e":"【易错】“夜阑”的“阑”是门字框，不写“澜”；“铁马冰河”不写“冰合”。"}]},{"type":"list","title":"名句","items":["夜阑卧听风吹雨，铁马冰河入梦来。"]},{"type":"list","title":"背诵提示","items":["“僵卧”的“僵”是单人旁，不写“缰”或“疆”。","“戍轮台”的“戍”是“戊”中一点（点、横、撇、戈），不写“戌”“戊”或“戎”。","“夜阑”的“阑”是门字框，不写“澜”；“铁马冰河”不写“冰合”。"]}],"questions":[{"id":"p-p7a-shi-yi-yue-si-ri-feng-yu-da-zuo-qi-er-m0","type":"fill","stem":"默写填空：夜阑卧听风吹雨，______。","answer":"铁马冰河入梦来。","explain":"出自《十一月四日风雨大作（其二）》（宋·陆游）：夜阑卧听风吹雨，铁马冰河入梦来。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-shi-yi-yue-si-ri-feng-yu-da-zuo-qi-er-u","type":"fill","stem":"理解性默写：我僵直地躺在孤寂的村落里，并不为自己的处境而感到悲哀，心中还想着替国家戍守边疆。","answer":"僵卧孤村不自哀，尚思为国戍轮台。","explain":"出自《十一月四日风雨大作（其二）》（宋·陆游）。句意：我僵直地躺在孤寂的村落里，并不为自己的处境而感到悲哀，心中还想着替国家戍守边疆。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-tong-guan","title":"潼关","subtitle":"清·谭嗣同","grade":"7a","tags":["言志","写景","雄浑"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"清·谭嗣同"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"谭嗣同（1865—1898），字复生，号壮飞，湖南浏阳人，近代维新派政治家、思想家、诗人。\n生平经历：他少年时随父亲宦游各地，喜好剑术、性情任侠，曾远游西北与江南，见识广博；甲午中日战争后他愤于国势危亡，转而潜心西学，投身维新变法，在湖南倡办时务学堂、南学会，宣传民权与变法主张；光绪二十四年（1898）他入京参与戊戌变法，变法失败后拒绝出逃，甘愿为变法流血，于当年九月二十八日在北京菜市口就义，年仅三十三岁。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是少年谭嗣同过潼关时所作，写景中寄寓着冲决罗网的少年意气。首句写潼关地势之高峻，以“终古高云簇此城”写出雄关的历史感与磅礴气势；次句写秋风骏马，声入云霄，境界开阔。后两句由实景转为拟人：黄河本已奔流大野，却“犹嫌束”，山势本已连绵，却“不解平”，诗人把自己的主观感受赋予山水，借黄河的奔涌、山峦的桀骜，表现少年诗人渴望摆脱束缚、追求自由与平等的宏大抱负，气势雄浑"},{"type":"list","title":"中考考点","items":["“簇”“嫌”“不解”等词的表达效果","拟人手法与借景抒情、以景写志的写法","诗中表现的少年豪情与渴望冲破束缚、勇往直前的精神。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"终古高云簇此城，秋风吹散马蹄声。","n":"","cn":"自古以来，高天的云层就簇拥着这座雄关；秋风阵阵，把清脆的马蹄声吹散了。","parts":[{"t":"终古","k":3},{"t":"高云"},{"t":"簇","k":4},{"t":"此城，秋风吹散"},{"t":"马蹄声","k":1},{"t":"。"}]},{"t":"河流大野犹嫌束，山入潼关不解平。","n":"","cn":"黄河奔流在广阔的原野上，还嫌受到束缚；山脉进入潼关以后，就不知道什么叫平坦了。","parts":[{"t":"河流大野"},{"t":"犹嫌束","k":2},{"t":"，山入潼关"},{"t":"不解平","k":0},{"t":"。"}]}],"words":[{"w":"不解平","e":"不懂得什么是平坦"},{"w":"马蹄声","e":"【易错】“马蹄声”的“蹄”是足字旁，不写“啼”。"},{"w":"犹嫌束","e":"【易错】“犹嫌束”的“嫌”是女字旁，“束”不写“朿”。"},{"w":"终古","e":"久远"},{"w":"簇","e":"簇拥"},{"w":"束","e":"约束、束缚"},{"w":"族","e":"【易错】“终古高云簇此城”的“簇”是竹字头，不写“族”。"},{"w":"蹄","e":"【易错】“马蹄声”的“蹄”是足字旁，不写“啼”。"},{"w":"啼","e":"【易错】“马蹄声”的“蹄”是足字旁，不写“啼”。"},{"w":"嫌","e":"【易错】“犹嫌束”的“嫌”是女字旁，“束”不写“朿”。"},{"w":"朿","e":"【易错】“犹嫌束”的“嫌”是女字旁，“束”不写“朿”。"}]},{"type":"list","title":"名句","items":["河流大野犹嫌束，山入潼关不解平。"]},{"type":"list","title":"背诵提示","items":["“终古高云簇此城”的“簇”是竹字头，不写“族”。","“马蹄声”的“蹄”是足字旁，不写“啼”。","“犹嫌束”的“嫌”是女字旁，“束”不写“朿”。"]}],"questions":[{"id":"p-p7a-tong-guan-m0","type":"fill","stem":"默写填空：河流大野犹嫌束，______。","answer":"山入潼关不解平。","explain":"出自《潼关》（清·谭嗣同）：河流大野犹嫌束，山入潼关不解平。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-tong-guan-u","type":"fill","stem":"理解性默写：自古以来，高天的云层就簇拥着这座雄关；秋风阵阵，把清脆的马蹄声吹散了。","answer":"终古高云簇此城，秋风吹散马蹄声。","explain":"出自《潼关》（清·谭嗣同）。句意：自古以来，高天的云层就簇拥着这座雄关；秋风阵阵，把清脆的马蹄声吹散了。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-lun-yu-shi-er-zhang","title":"《论语》十二章（节选）","subtitle":"先秦·孔子及其弟子","grade":"7a","tags":["文言文","儒家","学习方法","修身"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·孔子及其弟子"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"孔子名丘，字仲尼，春秋末期鲁国陬邑人，我国古代伟大的思想家、教育家，儒家学派的创始人，后世尊为“至圣先师”；他首创私学，主张“有教无类”，相传弟子三千、身通六艺者七十二人。《论语》所记，正是孔子及其弟子的言行。\n成书背景：《论语》不是孔子本人的著作，而是由孔子的弟子及再传弟子在孔子去世后陆续编纂而成的语录体散文集，主要记录孔子及其弟子的言行，全书二十篇，是儒家经典之一。南宋时朱熹把它与《大学》《中庸》《孟子》合编作注，称为“四书”，此后长期是读书人必读的经典。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"《论语》是记录孔子及其弟子言行的语录体散文集，为儒家经典。课文所选十二章涉及学习方法、学习态度与修身做人三类内容：“温故而知新”“学而不思则罔，思而不学则殆”谈学习方法；“知之者不如好之者，好之者不如乐之者”“三人行，必有我师焉”谈学习态度；“人不知而不愠”“吾日三省吾身”“三军可夺帅也，匹夫不可夺志也”谈修身立志。语言简练含蓄，多用反问、对偶、排比，富有哲理与感染力"},{"type":"list","title":"中考考点","items":["“说”同“悦”、“有”同“又”等通假字","“三省”“好”“乐”“饭”“肱”等词的意思与“日”“时”等名词作状语的用法","各章所谈的道理及分类归并","“三人行，必有我师焉”“逝者如斯夫”等名句默写与理解。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"子曰：“学而时习之，不亦说乎？有朋自远方来，不亦乐乎？人不知而不愠，不亦君子乎？”","n":"孔子说：“学了知识然后按时温习它，不也是很愉快吗？有志同道合的人从远方来，不也是很快乐吗？人家不了解我，我却不恼怒，不也是有才德的人吗？”时习：按时温习；说：同“悦”，愉快。","cn":"","parts":[{"t":"子曰：“学而时习之，"},{"t":"不亦说乎","k":0},{"t":"？"},{"t":"有","k":25},{"t":"朋自远方来，不亦"},{"t":"乐","k":17},{"t":"乎？人不知而不"},{"t":"愠","k":22},{"t":"，不亦君子乎？”"}]},{"t":"曾子曰：“吾日三省吾身：为人谋而不忠乎？与朋友交而不信乎？传不习乎？”","n":"曾子说：“我每天多次进行自我检查：替别人办事是不是尽心竭力呢？同朋友交往是不是诚信呢？老师传授的知识是不是复习了呢？”三省：多次自我检查；传：老师传授的知识。","cn":"","parts":[{"t":"曾子曰：“吾日"},{"t":"三省","k":10},{"t":"吾身：为人谋而不忠乎？与朋友交而不信乎？"},{"t":"传","k":13},{"t":"不习乎？”"}]},{"t":"子曰：“吾十有五而志于学，三十而立，四十而不惑，五十而知天命，六十而耳顺，七十而从心所欲，不逾矩。”","n":"孔子说：“我十五岁就有志于做学问，三十岁能有所成就，四十岁能不为外物所迷惑，五十岁懂得什么是天命，六十岁能听得进不同意见，七十岁能随心所欲，又不越过法度。”有：同“又”；逾矩：越过法度。","cn":"","parts":[{"t":"子曰：“"},{"t":"吾十有五","k":1},{"t":"而志于学，三十而立，四十而不惑，五十而知天命，六十而耳顺，七十而从心所欲，"},{"t":"不逾矩","k":5},{"t":"。”"}]},{"t":"子曰：“温故而知新，可以为师矣。”","n":"孔子说：“温习学过的知识，进而获得新的理解和体会，就可以做老师了。”故：学过的知识；新：新的理解与体会。","cn":"","parts":[{"t":"子曰：“"},{"t":"温","k":23},{"t":"故而知"},{"t":"新","k":14},{"t":"，可以为师矣。”"}]},{"t":"子曰：“学而不思则罔，思而不学则殆。”","n":"孔子说：“只读书却不思考，就会迷惑而无所得；只空想却不读书，就会疑惑不解。”罔：迷惑，意思是感到迷茫而无所适从；殆：疑惑。","cn":"","parts":[{"t":"子曰：“学而不思则"},{"t":"罔","k":31},{"t":"，思而不学则"},{"t":"殆","k":15},{"t":"。”"}]},{"t":"子曰：“贤哉，回也！一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐。贤哉，回也！”","n":"孔子说：“颜回多么贤德啊！一竹筐饭，一瓢水，住在简陋的小巷子里，别人都受不了那穷困的忧愁，颜回却不改变他自有的快乐。颜回多么贤德啊！”箪：古代盛饭的圆形竹器；堪：能忍受。","cn":"","parts":[{"t":"子曰：“贤哉，回也！"},{"t":"一箪食","k":6},{"t":"，一瓢饮，在陋巷，人不"},{"t":"堪","k":16},{"t":"其忧，回也不改其"},{"t":"乐","k":17},{"t":"。贤哉，回也！”"}]},{"t":"子曰：“知之者不如好之者，好之者不如乐之者。”","n":"孔子说：“对于学问，懂得它的人不如喜爱它的人，喜爱它的人不如以它为快乐的人。”好：喜爱，爱好；乐：以……为快乐。","cn":"","parts":[{"t":"子曰：“知之者不如好之者，好之者不如"},{"t":"乐","k":17},{"t":"之者。”"}]},{"t":"子曰：“饭疏食，饮水，曲肱而枕之，乐亦在其中矣。不义而富且贵，于我如浮云。”","n":"孔子说：“吃粗粮，喝冷水，弯着胳膊当枕头，乐趣也就在其中了。用不正当的手段得来的富贵，对于我来说就像天上的浮云一样。”饭：吃；肱：胳膊。","cn":"","parts":[{"t":"子曰：“饭疏食，饮水，"},{"t":"曲肱","k":11},{"t":"而枕之，"},{"t":"乐","k":17},{"t":"亦在其中矣。不义而富且贵，于我如浮云。”"}]},{"t":"子曰：“三人行，必有我师焉。择其善者而从之，其不善者而改之。”","n":"孔子说：“几个人一起走路，其中必定有可以做我老师的人。选择他们的优点来学习，看到他们的缺点就对照自己加以改正。”焉：于此，在其中。","cn":"","parts":[{"t":"子曰：“三人行，必"},{"t":"有","k":25},{"t":"我师焉。择其善者而从之，其不善者而改之。”"}]},{"t":"子在川上曰：“逝者如斯夫，不舍昼夜。”","n":"孔子在河边感叹说：“时光就像这流水一样消逝，日夜不停。”逝：往、离去；斯：这，指河水；夫：读 fú，语气词。","cn":"","parts":[{"t":"子在川上曰：“逝者如"},{"t":"斯","k":19},{"t":"夫","k":20},{"t":"，不舍昼夜。”"}]},{"t":"子曰：“三军可夺帅也，匹夫不可夺志也。”","n":"孔子说：“军队可以改变主帅，普通人的志向却不可以被改变。”三军：军队；匹夫：指平民中的男子，这里泛指普通人。","cn":"","parts":[{"t":"子曰：“三军可夺帅也，"},{"t":"匹夫","k":8},{"t":"不可夺志也。”"}]},{"t":"子夏曰：“博学而笃志，切问而近思，仁在其中矣。”","n":"子夏说：“广泛地学习，坚守自己的志向，恳切地提问，多思考当前的事，仁德就在其中了。”笃：坚定；切问：恳切地发问。","cn":"","parts":[{"t":"子夏曰：“博学而"},{"t":"笃","k":36},{"t":"志，"},{"t":"切问","k":9},{"t":"而近思，仁在其中矣。”"}]}],"words":[{"w":"不亦说乎","e":"【易错】“不亦说乎”的“说”同“悦”，读 yuè，不写“悦”。"},{"w":"吾十有五","e":"【易错】“吾十有五”的“有”同“又”，读 yòu，不写“又”。"},{"w":"孔子说","e":"“学了知识然后按时温习它，不也是很愉快吗？有志同道合的人从远方来，不也是很快乐吗？人家不了解我，我却不恼怒，不也是有才德的人吗？”时习：按时温习"},{"w":"曾子说","e":"“我每天多次进行自我检查：替别人办事是不是尽心竭力呢？同朋友交往是不是诚信呢？老师传授的知识是不是复习了呢？”三省：多次自我检查"},{"w":"子夏说","e":"“广泛地学习，坚守自己的志向，恳切地提问，多思考当前的事，仁德就在其中了"},{"w":"不逾矩","e":"【易错】“不逾矩”的“逾”是走之旁，不写“愉”；“矩”不写“距”。"},{"w":"一箪食","e":"【易错】“一箪食”的“箪”是竹字头，不写“单”；“曲肱”的“肱”是月字旁。"},{"w":"逾矩","e":"越过法度"},{"w":"匹夫","e":"指平民中的男子，这里泛指普通人"},{"w":"切问","e":"恳切地发问"},{"w":"三省","e":"【易错】“人不知而不愠”的“愠”是竖心旁，不写“温”；“三省”的“省”读 xǐng。"},{"w":"曲肱","e":"【易错】“一箪食”的“箪”是竹字头，不写“单”；“曲肱”的“肱”是月字旁。"},{"w":"说","e":"同“悦”，愉快"},{"w":"传","e":"老师传授的知识"},{"w":"新","e":"新的理解与体会"},{"w":"殆","e":"疑惑"},{"w":"堪","e":"能忍受"},{"w":"乐","e":"以……为快乐"},{"w":"肱","e":"胳膊"},{"w":"斯","e":"这，指河水"},{"w":"夫","e":"读 fú，语气词"},{"w":"悦","e":"【易错】“不亦说乎”的“说”同“悦”，读 yuè，不写“悦”。"},{"w":"愠","e":"【易错】“人不知而不愠”的“愠”是竖心旁，不写“温”；“三省”的“省”读 xǐng。"},{"w":"温","e":"【易错】“人不知而不愠”的“愠”是竖心旁，不写“温”；“三省”的“省”读 xǐng。"},{"w":"省","e":"【易错】“人不知而不愠”的“愠”是竖心旁，不写“温”；“三省”的“省”读 xǐng。"},{"w":"有","e":"【易错】“吾十有五”的“有”同“又”，读 yòu，不写“又”。"},{"w":"又","e":"【易错】“吾十有五”的“有”同“又”，读 yòu，不写“又”。"},{"w":"逾","e":"【易错】“不逾矩”的“逾”是走之旁，不写“愉”；“矩”不写“距”。"},{"w":"愉","e":"【易错】“不逾矩”的“逾”是走之旁，不写“愉”；“矩”不写“距”。"},{"w":"矩","e":"【易错】“不逾矩”的“逾”是走之旁，不写“愉”；“矩”不写“距”。"},{"w":"距","e":"【易错】“不逾矩”的“逾”是走之旁，不写“愉”；“矩”不写“距”。"},{"w":"罔","e":"【易错】“学而不思则罔”的“罔”不写“惘”；“思而不学则殆”的“殆”不写“怠”。"},{"w":"惘","e":"【易错】“学而不思则罔”的“罔”不写“惘”；“思而不学则殆”的“殆”不写“怠”。"},{"w":"怠","e":"【易错】“学而不思则罔”的“罔”不写“惘”；“思而不学则殆”的“殆”不写“怠”。"},{"w":"箪","e":"【易错】“一箪食”的“箪”是竹字头，不写“单”；“曲肱”的“肱”是月字旁。"},{"w":"单","e":"【易错】“一箪食”的“箪”是竹字头，不写“单”；“曲肱”的“肱”是月字旁。"},{"w":"笃","e":"【易错】“博学而笃志”的“笃”是竹字头，不写“督”。"},{"w":"督","e":"【易错】“博学而笃志”的“笃”是竹字头，不写“督”。"}]},{"type":"h","text":"译文"},{"type":"p","text":"孔子说：“学了知识按时温习，不也很愉快吗？有志同道合的人从远方来，不也很快乐吗？别人不了解我，我却不恼怒，不也是君子吗？”曾子说：“我每天多次反省自己：替人办事是否尽心？与朋友交往是否诚信？老师传授的知识是否复习过？”孔子说：“我十五岁立志于学问，三十岁有所成就，四十岁不再迷惑，五十岁懂得天命，六十岁能听进不同意见，七十岁能随心所欲而不越出规矩。”孔子说：“温习旧知识而有新体会，就可以做老师了。”孔子说：“只学不思考就会迷惑，只思考不学习就会疑惑。”孔子赞叹颜回安贫乐道：一竹筐饭、一瓢水、住在陋巷，别人受不了那份忧愁，颜回却不改其乐。又说：懂得学问的人不如喜爱它的人，喜爱它的人不如以它为乐的人。孔子说：吃粗粮、喝冷水、弯着胳膊作枕头，乐趣也在其中；不正当的富贵对我如同浮云。孔子说：几个人同行，其中必有可做我老师的人，择其善者而从之，见其不善者而改之。孔子在河边感叹：时光如流水，日夜不停地逝去。孔子说：军队可夺主帅，匹夫不可夺志。子夏说：广泛学习、坚守志向、恳切提问、多思当前之事，仁德就在其中了。"},{"type":"list","title":"名句","items":["学而不思则罔，思而不学则殆。","三人行，必有我师焉。","三军可夺帅也，匹夫不可夺志也。","逝者如斯夫，不舍昼夜。"]},{"type":"list","title":"背诵提示","items":["“不亦说乎”的“说”同“悦”，读 yuè，不写“悦”。","“人不知而不愠”的“愠”是竖心旁，不写“温”；“三省”的“省”读 xǐng。","“吾十有五”的“有”同“又”，读 yòu，不写“又”。","“不逾矩”的“逾”是走之旁，不写“愉”；“矩”不写“距”。","“学而不思则罔”的“罔”不写“惘”；“思而不学则殆”的“殆”不写“怠”。","“一箪食”的“箪”是竹字头，不写“单”；“曲肱”的“肱”是月字旁。","“博学而笃志”的“笃”是竹字头，不写“督”。"]}],"questions":[{"id":"p-p7a-lun-yu-shi-er-zhang-m0","type":"fill","stem":"默写填空：学而不思则罔，______。","answer":"思而不学则殆。","explain":"出自《《论语》十二章（节选）》（先秦·孔子及其弟子）：学而不思则罔，思而不学则殆。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-lun-yu-shi-er-zhang-m1","type":"fill","stem":"默写填空：三人行，______。","answer":"必有我师焉。","explain":"出自《《论语》十二章（节选）》（先秦·孔子及其弟子）：三人行，必有我师焉。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]}]},{"id":"p7a-jie-zi-shu","title":"诫子书","subtitle":"三国·诸葛亮","grade":"7a","tags":["文言文","家书","修身","议论"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"三国·诸葛亮"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"诸葛亮（181—234），字孔明，号卧龙，琅琊阳都（今山东沂南）人，三国时期蜀汉丞相，杰出的政治家、军事家；因封武乡侯，谥号忠武，后世尊称“武侯”。\n生平经历：他早年隐居隆中躬耕陇亩，自比管仲、乐毅；建安十二年（207）刘备三顾茅庐，他提出占据荆益、联孙抗曹的方略，从此出山辅佐刘备建立蜀汉；章武三年（223）刘备白帝城托孤，他辅佐后主刘禅，先后五次北伐（小说戏曲中称为“六出祁山”），建兴十二年（234）病逝于五丈原军中，一生“鞠躬尽瘁，死而后已”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是诸葛亮写给儿子诸葛瞻的家书，仅八十余字却是修身立志的名篇。文章以“静以修身，俭以养德”为纲，围绕“静”“俭”“志”“学”层层展开：先以“非淡泊无以明志，非宁静无以致远”的双重否定申说志向与宁静的关系，再从“学须静”“才须学”阐述治学之道，然后以“淫慢”“险躁”从反面警示，最后以“年与时驰，意与日去”的感慨收束。全文多用对偶，骈散结合，说理精警"},{"type":"list","title":"中考考点","items":["“淡泊”“宁静”“淫慢”“险躁”“治性”等词释义","“非……无以……”句式的理解与翻译","名句“非淡泊无以明志，非宁静无以致远”的默写与哲理分析","劝勉儿子修身养德、立志勤学的主旨。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"夫君子之行，静以修身，俭以养德。","n":"","cn":"君子的品行，用宁静专一来修养身心，用节俭来培养品德。","parts":[{"t":"夫","k":15},{"t":"君子之行，静以修身，俭以养德。"}]},{"t":"非淡泊无以明志，非宁静无以致远。","n":"","cn":"不看轻世俗的名利就不能明确自己的志向，不宁静专一就不能达到远大的目标。","parts":[{"t":"非"},{"t":"淡泊","k":2},{"t":"无以"},{"t":"明志","k":12},{"t":"，非宁静无以"},{"t":"致远","k":3},{"t":"。"}]},{"t":"夫学须静也，才须学也，非学无以广才，非志无以成学。","n":"","cn":"学习必须静心专一，而才干来自学习；不学习就无法增长才干，没有志向就无法使学习有所成就。","parts":[{"t":"夫","k":15},{"t":"学须静也，才须学也，非学无以"},{"t":"广才","k":4},{"t":"，非志无以"},{"t":"成学","k":5},{"t":"。"}]},{"t":"淫慢则不能励精，险躁则不能治性。","n":"","cn":"放纵懈怠就不能振奋精神，轻薄浮躁就不能修养性情。","parts":[{"t":"淫慢","k":6},{"t":"则不能"},{"t":"励精","k":7},{"t":"，"},{"t":"险躁","k":8},{"t":"则不能"},{"t":"治性","k":9},{"t":"。"}]},{"t":"年与时驰，意与日去，遂成枯落，多不接世，悲守穷庐，将复何及！","n":"","cn":"年纪随时间飞驰，意志随岁月流逝，最终会像枯枝落叶一样凋落，大多不能对社会有所贡献，只能悲哀地守着穷困的屋舍，那时再悔恨又怎么来得及呢！驰：疾行，指迅速逝去","parts":[{"t":"年与时驰","k":0},{"t":"，意与日去，遂成枯落，多不接世，"},{"t":"悲守穷庐","k":1},{"t":"，将复何及！"}]}],"words":[{"w":"年与时驰","e":"【易错】“年与时驰”的“驰”是马字旁，不写“弛”；“悲守穷庐”的“庐”是广字头，不写“芦”。"},{"w":"悲守穷庐","e":"【易错】“年与时驰”的“驰”是马字旁，不写“弛”；“悲守穷庐”的“庐”是广字头，不写“芦”。"},{"w":"淡泊","e":"内心恬淡，不慕名利"},{"w":"致远","e":"达到远大目标"},{"w":"广才","e":"增长才干"},{"w":"成学","e":"成就学业"},{"w":"淫慢","e":"放纵懈怠"},{"w":"励精","e":"振奋精神"},{"w":"险躁","e":"轻薄浮躁"},{"w":"治性","e":"修养性情"},{"w":"穷庐","e":"穷困潦倒之人住的陋室"},{"w":"淡薄","e":"【易错】“淡泊”是三点水的“泊”，不写“淡薄”；“明志”不写“名志”。"},{"w":"明志","e":"【易错】“淡泊”是三点水的“泊”，不写“淡薄”；“明志”不写“名志”。"},{"w":"名志","e":"【易错】“淡泊”是三点水的“泊”，不写“淡薄”；“明志”不写“名志”。"},{"w":"制性","e":"【易错】“险躁则不能治性”的“躁”是足字旁，不写“燥”；“治性”不写“制性”。"},{"w":"夫","e":"读 fú，助词，用于句首，无实义"},{"w":"泊","e":"【易错】“淡泊”是三点水的“泊”，不写“淡薄”；“明志”不写“名志”。"},{"w":"励","e":"【易错】“淫慢则不能励精”的“励”是力字旁，不写“厉”；“慢”不写“漫”。"},{"w":"厉","e":"【易错】“淫慢则不能励精”的“励”是力字旁，不写“厉”；“慢”不写“漫”。"},{"w":"慢","e":"【易错】“淫慢则不能励精”的“励”是力字旁，不写“厉”；“慢”不写“漫”。"},{"w":"漫","e":"【易错】“淫慢则不能励精”的“励”是力字旁，不写“厉”；“慢”不写“漫”。"},{"w":"躁","e":"【易错】“险躁则不能治性”的“躁”是足字旁，不写“燥”；“治性”不写“制性”。"},{"w":"燥","e":"【易错】“险躁则不能治性”的“躁”是足字旁，不写“燥”；“治性”不写“制性”。"},{"w":"驰","e":"【易错】“年与时驰”的“驰”是马字旁，不写“弛”；“悲守穷庐”的“庐”是广字头，不写“芦”。"},{"w":"弛","e":"【易错】“年与时驰”的“驰”是马字旁，不写“弛”；“悲守穷庐”的“庐”是广字头，不写“芦”。"},{"w":"庐","e":"【易错】“年与时驰”的“驰”是马字旁，不写“弛”；“悲守穷庐”的“庐”是广字头，不写“芦”。"},{"w":"芦","e":"【易错】“年与时驰”的“驰”是马字旁，不写“弛”；“悲守穷庐”的“庐”是广字头，不写“芦”。"}]},{"type":"list","title":"名句","items":["非淡泊无以明志，非宁静无以致远。"]},{"type":"list","title":"背诵提示","items":["“夫君子之行”的“夫”读 fú，是句首语气词，不能漏写。","“淡泊”是三点水的“泊”，不写“淡薄”；“明志”不写“名志”。","“淫慢则不能励精”的“励”是力字旁，不写“厉”；“慢”不写“漫”。","“险躁则不能治性”的“躁”是足字旁，不写“燥”；“治性”不写“制性”。","“年与时驰”的“驰”是马字旁，不写“弛”；“悲守穷庐”的“庐”是广字头，不写“芦”。"]}],"questions":[{"id":"p-p7a-jie-zi-shu-m0","type":"fill","stem":"默写填空：非淡泊无以明志，______。","answer":"非宁静无以致远。","explain":"出自《诫子书》（三国·诸葛亮）：非淡泊无以明志，非宁静无以致远。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-jie-zi-shu-u","type":"fill","stem":"理解性默写：君子的品行，用宁静专一来修养身心，用节俭来培养品德。","answer":"夫君子之行，静以修身，俭以养德。","explain":"出自《诫子书》（三国·诸葛亮）。句意：君子的品行，用宁静专一来修养身心，用节俭来培养品德。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-lang","title":"狼（节选）","subtitle":"清·蒲松龄","grade":"7a","tags":["文言文","小说","寓意"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"清·蒲松龄"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"蒲松龄（1640—1715），字留仙，一字剑臣，号柳泉居士，世称聊斋先生，淄川（今山东淄博）人，清代文学家。他一生科举失意、生活清贫，却以一部《聊斋志异》在中国文言小说史上占据了极高的地位。\n生平经历：他十九岁初应童子试，接连取得县、府、道三个第一，此后却屡试不第，直到七十一岁才援例补为岁贡生，一生大部分时间在乡间做塾师，靠坐馆教书维持生计；科举的失意与生活的困顿，使他对科举弊端与社会黑暗有深切体会，也为《聊斋志异》的创作积累了丰富素材。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文选自蒲松龄《聊斋志异》，是一则寓意深刻的文言短篇小说。文章以“狼”为题，按“遇狼—惧狼—御狼—杀狼—议狼”的顺序展开，情节曲折紧张：屠户先因“惧”而妥协投骨，反使两狼“并驱如故”，继而“窘”极而“奔倚”“弛担持刀”，最终抓住时机“暴起”杀狼。写法上，一是以动作、神态描写刻画形象；二是以“一狼径去，其一犬坐于前”“一狼洞其中”写狼的狡诈，为下文“乃悟”埋下伏笔，前后照应；三是篇末议论点明主旨：对待像狼一样的恶势力，必须敢于斗争、善于斗争"},{"type":"list","title":"中考考点","items":["“止”“窘”“尻”“股”“黠”等词释义","“洞”“隧”“犬坐”等词类活用","形象分析与主旨","“缀行甚远”的伏笔与照应。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"一屠晚归，担中肉尽，止有剩骨。","n":"","cn":"一个屠户天晚回家，担子里的肉已经卖完了，只剩下一些骨头。","parts":[{"t":"一屠晚归，担中肉尽，"},{"t":"止有剩骨","k":4},{"t":"。"}]},{"t":"途中两狼，缀行甚远。","n":"","cn":"路上遇到两只狼，紧跟着他走了很远。","parts":[{"t":"途中两狼，"},{"t":"缀行甚远","k":0},{"t":"。"}]},{"t":"屠惧，投以骨。一狼得骨止，一狼仍从。","n":"","cn":"屠户害怕了，把骨头扔给它们。一只狼得到骨头就停下了，另一只狼仍旧跟从。","parts":[{"t":"屠惧，投以骨。一狼得骨"},{"t":"止","k":18},{"t":"，一狼仍从。"}]},{"t":"复投之，后狼止而前狼又至。","n":"","cn":"屠户又扔骨头，后面那只狼停住了，前面那只狼又跟上来了。","parts":[{"t":"复投之，后狼"},{"t":"止","k":18},{"t":"而前狼又至。"}]},{"t":"骨已尽矣，而两狼之并驱如故。","n":"","cn":"骨头已经扔完了，可是两只狼像原来一样一起追赶。","parts":[{"t":"骨已尽矣，而两狼之"},{"t":"并驱如故","k":1},{"t":"。"}]},{"t":"屠大窘，恐前后受其敌。","n":"","cn":"屠户非常窘迫，担心前后遭受它们的攻击。","parts":[{"t":"屠大窘","k":10},{"t":"，恐前后受其"},{"t":"敌","k":20},{"t":"。"}]},{"t":"顾野有麦场，场主积薪其中，苫蔽成丘。","n":"","cn":"他回头看田野里有个打麦场，场主人把柴草堆在里面，覆盖成小山似的。","parts":[{"t":"顾野有麦场，场主积薪其中，"},{"t":"苫蔽成丘","k":2},{"t":"。"}]},{"t":"屠乃奔倚其下，弛担持刀。","n":"","cn":"屠户就跑过去靠在柴草堆下面，卸下担子拿起刀。","parts":[{"t":"屠乃奔倚其下，"},{"t":"弛担持刀","k":7},{"t":"。"}]},{"t":"狼不敢前，眈眈相向。","n":"","cn":"两只狼不敢上前，瞪眼朝着屠户。","parts":[{"t":"狼不敢前，"},{"t":"眈眈相向","k":3},{"t":"。"}]},{"t":"少时，一狼径去，其一犬坐于前。","n":"","cn":"一会儿，一只狼径直走开了，另一只狼像狗似的蹲坐在前面。","parts":[{"t":"少时，一狼径去，其一"},{"t":"犬坐","k":14},{"t":"于前。"}]},{"t":"久之，目似瞑，意暇甚。","n":"","cn":"过了很久，那只狼的眼睛好像闭上了，神情很悠闲。","parts":[{"t":"久之，"},{"t":"目似瞑","k":11},{"t":"，"},{"t":"意暇甚","k":9},{"t":"。"}]},{"t":"屠暴起，以刀劈狼首，又数刀毙之。","n":"","cn":"屠户突然跳起来，用刀劈狼的脑袋，又砍了几刀把狼杀死。","parts":[{"t":"屠"},{"t":"暴","k":22},{"t":"起，以刀劈狼首，又数刀毙之。"}]},{"t":"方欲行，转视积薪后，一狼洞其中，意将隧入以攻其后也。","n":"","cn":"正要走，转身看柴草堆后面，另一只狼正在其中打洞，想要从通道进入来攻击屠户的背后。","parts":[{"t":"方欲行，转视积薪后，一狼"},{"t":"洞","k":23},{"t":"其中，意将"},{"t":"隧","k":24},{"t":"入以攻其后也。"}]},{"t":"身已半入，止露尻尾。屠自后断其股，亦毙之。","n":"","cn":"狼的身子已经钻进去一半，只露出屁股和尾巴。屠户从后面砍断了它的大腿，也把它杀死了。","parts":[{"t":"身已半入，"},{"t":"止露尻尾","k":5},{"t":"。屠自后"},{"t":"断其股","k":12},{"t":"，亦毙之。"}]},{"t":"乃悟前狼假寐，盖以诱敌。","n":"","cn":"这才明白前面的那只狼是假装睡觉，原来是用来诱惑敌方的。","parts":[{"t":"乃悟前狼"},{"t":"假寐","k":15},{"t":"，"},{"t":"盖","k":27},{"t":"以诱"},{"t":"敌","k":20},{"t":"。"}]},{"t":"狼亦黠矣，而顷刻两毙，禽兽之变诈几何哉？止增笑耳。","n":"","cn":"狼也太狡猾了，可是一会儿两只狼都被杀死，禽兽的欺骗手段能有多少呢？只是增加笑料罢了。","parts":[{"t":"狼亦黠矣","k":8},{"t":"，而顷刻两毙，禽兽之"},{"t":"变诈","k":16},{"t":"几何","k":17},{"t":"哉？"},{"t":"止增笑耳","k":6},{"t":"。"}]}],"words":[{"w":"缀行甚远","e":"连接着走，走了很远"},{"w":"并驱如故","e":"一起追赶，像原来一样"},{"w":"苫蔽成丘","e":"覆盖、遮盖成小山"},{"w":"眈眈相向","e":"瞪眼朝着对方"},{"w":"止有剩骨","e":"【易错】“止有剩骨”“止露尻尾”“止增笑耳”中的“止”同“只”，不要改写为“只”。"},{"w":"止露尻尾","e":"【易错】“止有剩骨”“止露尻尾”“止增笑耳”中的“止”同“只”，不要改写为“只”。"},{"w":"止增笑耳","e":"【易错】“止有剩骨”“止露尻尾”“止增笑耳”中的“止”同“只”，不要改写为“只”。"},{"w":"弛担持刀","e":"【易错】“苫蔽成丘”的“苫”是草字头；“弛担持刀”的“弛”是弓字旁（放松），不写“驰”。"},{"w":"狼亦黠矣","e":"【易错】“狼亦黠矣”的“黠”是黑字旁，不写“侠”。"},{"w":"意暇甚","e":"神情很悠闲"},{"w":"屠大窘","e":"【易错】“缀行甚远”的“缀”是绞丝旁，不写“辍”；“屠大窘”的“窘”是穴宝盖，不写“君”。"},{"w":"目似瞑","e":"【易错】“眈眈相向”的“眈”是目字旁，不写“耽”；“目似瞑”的“瞑”是目字旁，不写“暝”。"},{"w":"断其股","e":"【易错】“止露尻尾”的“尻”读 kāo，不写“屁”；“断其股”的“股”指大腿。"},{"w":"弛担","e":"卸下担子"},{"w":"犬坐","e":"像狗一样蹲坐"},{"w":"假寐","e":"假装睡觉"},{"w":"变诈","e":"巧变诡诈"},{"w":"几何","e":"多少"},{"w":"止","e":"同“只”，仅仅"},{"w":"窘","e":"处境困迫，为难"},{"w":"敌","e":"攻击"},{"w":"瞑","e":"闭眼"},{"w":"暴","e":"突然"},{"w":"洞","e":"名词用作动词，挖洞"},{"w":"隧","e":"名词作状语，从通道"},{"w":"尻","e":"屁股"},{"w":"股","e":"大腿"},{"w":"盖","e":"原来是"},{"w":"黠","e":"狡猾"},{"w":"只","e":"【易错】“止有剩骨”“止露尻尾”“止增笑耳”中的“止”同“只”，不要改写为“只”。"},{"w":"缀","e":"【易错】“缀行甚远”的“缀”是绞丝旁，不写“辍”；“屠大窘”的“窘”是穴宝盖，不写“君”。"},{"w":"辍","e":"【易错】“缀行甚远”的“缀”是绞丝旁，不写“辍”；“屠大窘”的“窘”是穴宝盖，不写“君”。"},{"w":"君","e":"【易错】“缀行甚远”的“缀”是绞丝旁，不写“辍”；“屠大窘”的“窘”是穴宝盖，不写“君”。"},{"w":"苫","e":"【易错】“苫蔽成丘”的“苫”是草字头；“弛担持刀”的“弛”是弓字旁（放松），不写“驰”。"},{"w":"弛","e":"【易错】“苫蔽成丘”的“苫”是草字头；“弛担持刀”的“弛”是弓字旁（放松），不写“驰”。"},{"w":"驰","e":"【易错】“苫蔽成丘”的“苫”是草字头；“弛担持刀”的“弛”是弓字旁（放松），不写“驰”。"},{"w":"眈","e":"【易错】“眈眈相向”的“眈”是目字旁，不写“耽”；“目似瞑”的“瞑”是目字旁，不写“暝”。"},{"w":"耽","e":"【易错】“眈眈相向”的“眈”是目字旁，不写“耽”；“目似瞑”的“瞑”是目字旁，不写“暝”。"},{"w":"暝","e":"【易错】“眈眈相向”的“眈”是目字旁，不写“耽”；“目似瞑”的“瞑”是目字旁，不写“暝”。"},{"w":"屁","e":"【易错】“止露尻尾”的“尻”读 kāo，不写“屁”；“断其股”的“股”指大腿。"},{"w":"侠","e":"【易错】“狼亦黠矣”的“黠”是黑字旁，不写“侠”。"}]},{"type":"list","title":"名句","items":["狼亦黠矣，而顷刻两毙，禽兽之变诈几何哉？止增笑耳。"]},{"type":"list","title":"背诵提示","items":["“止有剩骨”“止露尻尾”“止增笑耳”中的“止”同“只”，不要改写为“只”。","“缀行甚远”的“缀”是绞丝旁，不写“辍”；“屠大窘”的“窘”是穴宝盖，不写“君”。","“苫蔽成丘”的“苫”是草字头；“弛担持刀”的“弛”是弓字旁（放松），不写“驰”。","“眈眈相向”的“眈”是目字旁，不写“耽”；“目似瞑”的“瞑”是目字旁，不写“暝”。","“止露尻尾”的“尻”读 kāo，不写“屁”；“断其股”的“股”指大腿。","“狼亦黠矣”的“黠”是黑字旁，不写“侠”。"]}],"questions":[{"id":"p-p7a-lang-m0","type":"fill","stem":"默写填空：狼亦黠矣，______。","answer":"而顷刻两毙。","explain":"出自《狼（节选）》（清·蒲松龄）：狼亦黠矣，而顷刻两毙，禽兽之变诈几何哉？止增笑耳。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-lang-u","type":"fill","stem":"理解性默写：一个屠户天晚回家，担子里的肉已经卖完了，只剩下一些骨头。","answer":"一屠晚归，担中肉尽，止有剩骨。","explain":"出自《狼（节选）》（清·蒲松龄）。句意：一个屠户天晚回家，担子里的肉已经卖完了，只剩下一些骨头。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-yong-xue","title":"咏雪","subtitle":"南朝宋·刘义庆","grade":"7a","tags":["文言文","笔记小说","家庭生活"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"南朝宋·刘义庆"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"刘义庆（403—444），彭城人，南朝宋宗室，宋武帝刘裕的侄子，袭封临川王，曾任荆州刺史、江州刺史等职。他生性简素，喜好文学，门下聚集了一批文士，是《世说新语》的主持编纂者。\n成书背景：《世说新语》是南朝宋时产生的一部笔记小说，主要记述汉末至东晋士人的言行轶事。一般认为它由刘义庆组织门下文士采集旧闻、分类编撰而成，并非一人一时之作，全书按德行、言语、政事、文学、方正、雅量等三十六门编排。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文选自《世说新语》，是一则写家庭雅趣的笔记小说。全文仅七十余字，却叙事完整、人物鲜明。写法上主要有三妙：一是以“寒雪日内集”“讲论文义”交代背景，营造出和睦、高雅的书香家庭氛围；二是以“撒盐空中”与“柳絮因风起”两个比喻作对比，前者重形似而少神韵，后者兼得轻盈飘飞之态与春意盎然的神似，故“公大笑乐”暗含赞赏；三是结尾补叙谢道韫的身份，暗示作者对其才华的肯定，含蓄而有余味"},{"type":"list","title":"中考考点","items":["“俄而”“欣然”“拟”“未若”“因”等词释义，古今异义词“儿女”","两个比喻的优劣比较及咏雪名句“未若柳絮因风起”的赏析","文章表现的古代家庭生活情趣与谢道韫的聪慧才气。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"谢太傅寒雪日内集，与儿女讲论文义。","n":"","cn":"一个寒冷的雪天，谢太傅把家里人聚集在一起，跟子侄辈谈论文章的义理。","parts":[{"t":"谢太"},{"t":"傅","k":5},{"t":"寒雪日"},{"t":"内集","k":2},{"t":"，与"},{"t":"儿女","k":3},{"t":"讲论文义。"}]},{"t":"俄而雪骤，公欣然曰：“白雪纷纷何所似？”","n":"","cn":"不久雪下得急了，谢太傅高兴地说：“这纷纷扬扬的白雪像什么呢？”俄而：不久，一会儿","parts":[{"t":"俄而雪骤","k":0},{"t":"，公欣然曰：“白雪纷纷何所似？”"}]},{"t":"兄子胡儿曰：“撒盐空中差可拟。”","n":"","cn":"他哥哥的儿子谢朗说：“跟把盐撒在空中差不多可以相比。”胡儿：谢朗的小名","parts":[{"t":"兄子胡儿曰：“"},{"t":"撒","k":12},{"t":"盐空中"},{"t":"差可拟","k":1},{"t":"。”"}]},{"t":"兄女曰：“未若柳絮因风起。”","n":"","cn":"他哥哥的女儿谢道韫说：“不如比作柳絮乘风飞舞。”未若：不如，不及","parts":[{"t":"兄女曰：“未若柳"},{"t":"絮","k":15},{"t":"因风","k":4},{"t":"起。”"}]},{"t":"公大笑乐。即公大兄无奕女，左将军王凝之妻也。","n":"","cn":"谢太傅高兴得大笑起来。她就是谢太傅大哥谢无奕的女儿，左将军王凝之的妻子。","parts":[{"t":"公大笑乐。即公大兄无奕女，左将军王凝之妻也。"}]}],"words":[{"w":"俄而雪骤","e":"【易错】“俄而雪骤”的“俄”不写“娥”，“骤”是马字旁，不写“聚”。"},{"w":"差可拟","e":"差不多可以相比"},{"w":"内集","e":"家庭聚会"},{"w":"儿女","e":"子侄辈"},{"w":"因风","e":"乘风"},{"w":"傅","e":"【易错】“谢太傅寒雪日内集”的“傅”是单人旁，不写“传”或“付”。"},{"w":"传","e":"【易错】“谢太傅寒雪日内集”的“傅”是单人旁，不写“传”或“付”。"},{"w":"付","e":"【易错】“谢太傅寒雪日内集”的“傅”是单人旁，不写“传”或“付”。"},{"w":"俄","e":"【易错】“俄而雪骤”的“俄”不写“娥”，“骤”是马字旁，不写“聚”。"},{"w":"娥","e":"【易错】“俄而雪骤”的“俄”不写“娥”，“骤”是马字旁，不写“聚”。"},{"w":"骤","e":"【易错】“俄而雪骤”的“俄”不写“娥”，“骤”是马字旁，不写“聚”。"},{"w":"聚","e":"【易错】“俄而雪骤”的“俄”不写“娥”，“骤”是马字旁，不写“聚”。"},{"w":"撒","e":"【易错】“撒盐空中差可拟”的“撒”“拟”不要漏写；“差可拟”的“差”读 chā。"},{"w":"拟","e":"【易错】“撒盐空中差可拟”的“撒”“拟”不要漏写；“差可拟”的“差”读 chā。"},{"w":"差","e":"【易错】“撒盐空中差可拟”的“撒”“拟”不要漏写；“差可拟”的“差”读 chā。"},{"w":"絮","e":"【易错】“未若柳絮因风起”的“絮”是糸字底，不写“恕”；“因风”的“因”是“乘、趁”。"},{"w":"恕","e":"【易错】“未若柳絮因风起”的“絮”是糸字底，不写“恕”；“因风”的“因”是“乘、趁”。"},{"w":"因","e":"【易错】“未若柳絮因风起”的“絮”是糸字底，不写“恕”；“因风”的“因”是“乘、趁”。"}]},{"type":"list","title":"名句","items":["未若柳絮因风起。"]},{"type":"list","title":"背诵提示","items":["“谢太傅寒雪日内集”的“傅”是单人旁，不写“传”或“付”。","“俄而雪骤”的“俄”不写“娥”，“骤”是马字旁，不写“聚”。","“撒盐空中差可拟”的“撒”“拟”不要漏写；“差可拟”的“差”读 chā。","“未若柳絮因风起”的“絮”是糸字底，不写“恕”；“因风”的“因”是“乘、趁”。"]}],"questions":[{"id":"p-p7a-yong-xue-u","type":"fill","stem":"理解性默写：一个寒冷的雪天，谢太傅把家里人聚集在一起，跟子侄辈谈论文章的义理。","answer":"谢太傅寒雪日内集，与儿女讲论文义。","explain":"出自《咏雪》（南朝宋·刘义庆）。句意：一个寒冷的雪天，谢太傅把家里人聚集在一起，跟子侄辈谈论文章的义理。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7a-chen-tai-qiu-yu-you-qi-xing","title":"陈太丘与友期行","subtitle":"南朝宋·刘义庆","grade":"7a","tags":["文言文","笔记小说","诚信"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"南朝宋·刘义庆"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"刘义庆（403—444），彭城人，南朝宋宗室，宋武帝刘裕的侄子，袭封临川王，曾任荆州刺史、江州刺史等职。他生性简素，喜好文学，门下聚集了一批文士，是《世说新语》的主持编纂者。\n成书背景：《世说新语》是南朝宋时产生的一部笔记小说，主要记述汉末至东晋士人的言行轶事。一般认为它由刘义庆组织门下文士采集旧闻、分类编撰而成，并非一人一时之作，全书按德行、言语、政事、文学、方正、雅量等三十六门编排。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文选自《世说新语》，写七岁孩童陈元方驳斥失信无礼之客的故事，是一篇短小精悍的写人叙事之作。文章以“期行”起笔，用“过中不至”“太丘舍去”交代矛盾起因；再以客人的“怒”与元方的“答”正面交锋，元方以“无信”“无礼”两条理由层层驳斥，有理有据，一个明理聪慧的儿童形象跃然纸上。结尾“友人惭，下车引之”写客人知错，而“元方入门不顾”以动作作结，既显其率真与自尊"},{"type":"list","title":"中考考点","items":["“期”“舍去”“乃”“委”“顾”等词释义和“不”同“否”的通假字","“尊君”“家君”等称谓语的区别","元方的人物形象与“守信知礼”的主旨","结尾“入门不顾”的开放性理解。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"陈太丘与友期行，期日中。过中不至，太丘舍去，去后乃至。","n":"","cn":"陈太丘与朋友约好同行，约定的时间是正午。过了正午朋友还没有到，陈太丘便丢下他自己走了，走后朋友才到。","parts":[{"t":"陈太丘与友"},{"t":"期行","k":5},{"t":"，"},{"t":"期","k":18},{"t":"日中","k":6},{"t":"。过中"},{"t":"不","k":14},{"t":"至，太丘"},{"t":"舍去","k":7},{"t":"，去后乃至。"}]},{"t":"元方时年七岁，门外戏。","n":"","cn":"元方当时七岁，正在门外玩耍。","parts":[{"t":"元方","k":8},{"t":"时年七岁，门外戏。"}]},{"t":"客问元方：“尊君在不？”答曰：“待君久不至，已去。”","n":"客人问元方：“你父亲在家吗？”元方回答说：“等您很久都没到，他已经走了。”尊君在不：你父亲在不在，“不”同“否”。","cn":"","parts":[{"t":"客问"},{"t":"元方","k":8},{"t":"：“"},{"t":"尊君在不","k":1},{"t":"？”答曰：“待君久"},{"t":"不","k":14},{"t":"至，已去。”"}]},{"t":"友人便怒曰：“非人哉！与人期行，相委而去。”","n":"那位朋友便发怒说：“真不是人啊！跟人约好同行，却丢下我先走了。”相委而去：丢下我走了；委：舍弃。","cn":"","parts":[{"t":"友人便怒曰：“非人哉！与人"},{"t":"期行","k":5},{"t":"，"},{"t":"相委而去","k":2},{"t":"。”"}]},{"t":"元方曰：“君与家君期日中。日中不至，则是无信；对子骂父，则是无礼。”","n":"元方说：“您与我父亲约在正午。正午了您不到，就是不讲信用；对着人家的儿子骂他的父亲，就是没有礼貌。”家君：对人称自己的父亲；则：就。","cn":"","parts":[{"t":"元方","k":8},{"t":"曰：“君与"},{"t":"家君","k":12},{"t":"期","k":18},{"t":"日中","k":6},{"t":"。"},{"t":"日中","k":6},{"t":"不","k":14},{"t":"至，则是无信；对子骂父，则是无礼。”"}]},{"t":"友人惭，下车引之。元方入门不顾。","n":"","cn":"那位朋友感到惭愧，下车来拉元方。元方头也不回地进了门。","parts":[{"t":"友人惭，下车"},{"t":"引","k":16},{"t":"之。"},{"t":"元方","k":8},{"t":"入门"},{"t":"不","k":14},{"t":"顾","k":17},{"t":"。"}]}],"words":[{"w":"客人问元方","e":"“你父亲在家吗？”元方回答说：“等您很久都没到，他已经走了"},{"w":"尊君在不","e":"【易错】“尊君在不”的“不”同“否”，读 fǒu，不能写成“否”以外的字。"},{"w":"相委而去","e":"【易错】“相委而去”的“委”是“舍弃”，不是“委托”。"},{"w":"元方说","e":"“您与我父亲约在正午"},{"w":"回头看","e":"【易错】“元方入门不顾”的“顾”是“回头看”，不写“雇”。"},{"w":"期行","e":"相约同行"},{"w":"日中","e":"正午时分"},{"w":"舍去","e":"丢下（他）离开"},{"w":"元方","e":"陈太丘的儿子陈纪"},{"w":"约定","e":"【易错】“陈太丘与友期行”的“期”是“约定”，不写“其”。"},{"w":"舍弃","e":"【易错】“相委而去”的“委”是“舍弃”，不是“委托”。"},{"w":"委托","e":"【易错】“相委而去”的“委”是“舍弃”，不是“委托”。"},{"w":"家君","e":"【易错】“家君”是谦称自己的父亲，“尊君”是敬称对方的父亲，二者不可混用。"},{"w":"尊君","e":"【易错】“家君”是谦称自己的父亲，“尊君”是敬称对方的父亲，二者不可混用。"},{"w":"不","e":"同“否”"},{"w":"委","e":"舍弃"},{"w":"引","e":"拉，这里是表示友好的动作"},{"w":"顾","e":"回头看"},{"w":"期","e":"【易错】“陈太丘与友期行”的“期”是“约定”，不写“其”。"},{"w":"其","e":"【易错】“陈太丘与友期行”的“期”是“约定”，不写“其”。"},{"w":"否","e":"【易错】“尊君在不”的“不”同“否”，读 fǒu，不能写成“否”以外的字。"},{"w":"雇","e":"【易错】“元方入门不顾”的“顾”是“回头看”，不写“雇”。"}]},{"type":"h","text":"译文"},{"type":"p","text":"陈太丘和朋友约好一同出行，约定在正午。过了正午朋友还没来，陈太丘便丢下他先走了，走后朋友才到。元方当时七岁，正在门外玩耍。客人问元方：“你父亲在家吗？”元方回答：“等您很久都不来，他已经走了。”朋友便发怒说：“真不是人啊！和人约好一起走，却丢下我自己走了。”元方说：“您和我父亲约定在正午。正午您不来，就是不讲信用；对着人家的儿子骂他的父亲，就是没有礼貌。”朋友感到惭愧，下车来拉他，元方头也不回地进了门。"},{"type":"list","title":"名句","items":["日中不至，则是无信；对子骂父，则是无礼。"]},{"type":"list","title":"背诵提示","items":["“陈太丘与友期行”的“期”是“约定”，不写“其”。","“尊君在不”的“不”同“否”，读 fǒu，不能写成“否”以外的字。","“相委而去”的“委”是“舍弃”，不是“委托”。","“家君”是谦称自己的父亲，“尊君”是敬称对方的父亲，二者不可混用。","“元方入门不顾”的“顾”是“回头看”，不写“雇”。"]}],"questions":[{"id":"p-p7a-chen-tai-qiu-yu-you-qi-xing-m0","type":"fill","stem":"默写填空：日中不至，______。","answer":"则是无信。","explain":"出自《陈太丘与友期行》（南朝宋·刘义庆）：日中不至，则是无信；对子骂父，则是无礼。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7a-chen-tai-qiu-yu-you-qi-xing-u","type":"fill","stem":"理解性默写：陈太丘与朋友约好同行，约定的时间是正午。过了正午朋友还没有到，陈太丘便丢下他自己走了，走后朋友才到。","answer":"陈太丘与友期行，期日中。过中不至，太丘舍去，去后乃至。","explain":"出自《陈太丘与友期行》（南朝宋·刘义庆）。句意：陈太丘与朋友约好同行，约定的时间是正午。过了正午朋友还没有到，陈太丘便丢下他自己走了，走后朋友才到。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-mu-lan-shi","title":"木兰诗","subtitle":"北朝·佚名","grade":"7b","tags":["文言文","乐府民歌","叙事诗","人物形象"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"北朝·佚名"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者与出处","text":"北朝佚名作品，作者与生平不详。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"《木兰诗》是北朝乐府民歌的代表作，与《孔雀东南飞》并称“乐府双璧”。全诗以木兰替父从军为线索，依次写代父从军、奔赴战场、征战归来、辞官还乡，详写从军前的决定、出征途中的思亲与还乡的欢聚，略写十年征战，详略得当。艺术上，“东市买骏马”四句排比铺陈渲染；“不闻爷娘唤女声”以反复、对比写思亲；“将军百战死，壮士十年归”用互文，语言凝练；结尾以双兔作喻，机智幽默"},{"type":"list","title":"中考考点","items":["“市”“著”“帖”“火”“策勋”“安”等词释义与“帖”同“贴”的通假","详略安排的作用","排比、互文、对偶、比喻的辨析","木兰孝顺勇敢、不慕荣华的形象及诗歌主旨。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"唧唧复唧唧，木兰当户织。","n":"","cn":"叹息声一声接着一声，木兰对着门在织布。","parts":[{"t":"唧唧","k":3},{"t":"复"},{"t":"唧唧","k":3},{"t":"，木兰"},{"t":"当户织","k":0},{"t":"。"}]},{"t":"不闻机杼声，唯闻女叹息。","n":"","cn":"听不到织布机的声音，只听到木兰的叹息声。","parts":[{"t":"不闻"},{"t":"机杼","k":4},{"t":"声，"},{"t":"唯闻","k":28},{"t":"女叹息。"}]},{"t":"问女何所思，问女何所忆。","n":"","cn":"问木兰在想什么，问木兰在思念什么。","parts":[{"t":"问女何所思，问女何所"},{"t":"忆","k":32},{"t":"。"}]},{"t":"女亦无所思，女亦无所忆。","n":"","cn":"木兰没有什么想的，木兰也没有什么思念的。","parts":[{"t":"女亦无所思，女亦无所"},{"t":"忆","k":32},{"t":"。"}]},{"t":"昨夜见军帖，可汗大点兵，军书十二卷，卷卷有爷名。","n":"","cn":"昨夜看到军中的文告，可汗大规模征兵，征兵的名册有很多卷，每一卷上都有父亲的名字。","parts":[{"t":"昨夜见"},{"t":"军帖","k":5},{"t":"，"},{"t":"可汗","k":6},{"t":"大点兵，军书"},{"t":"十二","k":7},{"t":"卷，卷卷有爷名。"}]},{"t":"阿爷无大儿，木兰无长兄，愿为市鞍马，从此替爷征。","n":"","cn":"父亲没有成年的儿子，木兰没有兄长，我愿意为此去买鞍马，从此替父亲出征。","parts":[{"t":"阿爷无大儿，木兰无长兄，愿为市"},{"t":"鞍马","k":8},{"t":"，从此替爷征。"}]},{"t":"东市买骏马，西市买鞍鞯，南市买辔头，北市买长鞭。","n":"","cn":"到东边的集市买骏马，到西边的集市买马鞍和鞍下的垫子，到南边的集市买马嚼子和缰绳，到北边的集市买长马鞭。","parts":[{"t":"东市买骏马，西市买"},{"t":"鞍鞯","k":30},{"t":"，南市买"},{"t":"辔头","k":9},{"t":"，北市买长鞭。"}]},{"t":"旦辞爷娘去，暮宿黄河边，不闻爷娘唤女声，但闻黄河流水鸣溅溅。","n":"","cn":"早晨辞别父母上路，晚上宿营在黄河边，听不到父母呼唤女儿的声音，只听到黄河流水哗哗的声响。","parts":[{"t":"旦","k":33},{"t":"辞爷娘去，暮宿黄河边，不闻爷娘唤女声，但闻黄河流水"},{"t":"鸣溅溅","k":2},{"t":"。"}]},{"t":"旦辞黄河去，暮至黑山头，不闻爷娘唤女声，但闻燕山胡骑鸣啾啾。","n":"","cn":"早晨辞别黄河上路，晚上到达黑山头，听不到父母呼唤女儿的声音，只听到燕山胡人战马的嘶鸣声。","parts":[{"t":"旦","k":33},{"t":"辞黄河去，暮至黑山头，不闻爷娘唤女声，但闻"},{"t":"燕","k":48},{"t":"山"},{"t":"胡骑","k":11},{"t":"鸣"},{"t":"啾啾","k":12},{"t":"。"}]},{"t":"万里赴戎机，关山度若飞。","n":"","cn":"万里迢迢奔赴战场，像飞一样越过一道道关塞山岭。","parts":[{"t":"万里赴"},{"t":"戎机","k":13},{"t":"，关山"},{"t":"度","k":34},{"t":"若飞。"}]},{"t":"朔气传金柝，寒光照铁衣。","n":"","cn":"北方的寒气传送着打更的声音，清冷的月光照着战士们的铠甲。","parts":[{"t":"朔","k":35},{"t":"气传"},{"t":"金柝","k":14},{"t":"，寒光照"},{"t":"铁衣","k":15},{"t":"。"}]},{"t":"将军百战死，壮士十年归。","n":"","cn":"将军和壮士们征战多年，许多人战死沙场，幸存者胜利归来。百战、十年：均非确指，形容战事频繁、时间长久。","parts":[{"t":"将军百战死，壮士十年归。"}]},{"t":"归来见天子，天子坐明堂。","n":"","cn":"归来朝见天子，天子坐在殿堂上。","parts":[{"t":"归来见"},{"t":"天子","k":16},{"t":"，"},{"t":"天子","k":16},{"t":"坐"},{"t":"明堂","k":17},{"t":"。"}]},{"t":"策勋十二转，赏赐百千强。","n":"","cn":"给木兰记了很多次功，赏赐了很多财物。","parts":[{"t":"策勋","k":18},{"t":"十二","k":7},{"t":"转","k":36},{"t":"，赏赐百千"},{"t":"强","k":37},{"t":"。"}]},{"t":"可汗问所欲，木兰不用尚书郎，愿驰千里足，送儿还故乡。","n":"","cn":"天子问木兰想要什么，木兰不愿意做尚书郎，只希望骑上千里马，送我回故乡。","parts":[{"t":"可汗","k":6},{"t":"问所欲，木兰"},{"t":"不用","k":19},{"t":"尚书郎，愿驰"},{"t":"千里足","k":1},{"t":"，送儿还故乡。"}]},{"t":"爷娘闻女来，出郭相扶将；阿姊闻妹来，当户理红妆；","n":"","cn":"父母听说女儿回来了，互相搀扶着到城外迎接；姐姐听说妹妹回来了，对着门梳理红妆。","parts":[{"t":"爷娘闻女来，出"},{"t":"郭","k":38},{"t":"相"},{"t":"扶将","k":20},{"t":"；阿姊闻妹来，当户理"},{"t":"红妆","k":21},{"t":"；"}]},{"t":"小弟闻姊来，磨刀霍霍向猪羊。","n":"","cn":"弟弟听说姐姐回来了，忙着霍霍地磨刀，准备杀猪宰羊。","parts":[{"t":"小弟闻姊来，磨刀"},{"t":"霍霍","k":22},{"t":"向猪羊。"}]},{"t":"开我东阁门，坐我西阁床。","n":"","cn":"打开我东屋的闺门，坐在我西屋的床上。","parts":[{"t":"开我东"},{"t":"阁","k":39},{"t":"门，坐我西"},{"t":"阁","k":39},{"t":"床。"}]},{"t":"脱我战时袍，著我旧时裳。","n":"","cn":"脱下我打仗时穿的战袍，穿上我以前的女儿装。","parts":[{"t":"脱我战时袍，"},{"t":"著","k":52},{"t":"我旧时"},{"t":"裳","k":40},{"t":"。"}]},{"t":"当窗理云鬓，对镜帖花黄。","n":"","cn":"对着窗户梳理如云的鬓发，对着镜子贴上花黄。","parts":[{"t":"当窗理"},{"t":"云鬓","k":23},{"t":"，对镜"},{"t":"帖","k":41},{"t":"花黄","k":24},{"t":"。"}]},{"t":"出门看火伴，火伴皆惊忙：同行十二年，不知木兰是女郎。","n":"","cn":"出门去看同行的战友，战友们都很吃惊：同行这么多年，竟然不知道木兰是个女子。","parts":[{"t":"出门看"},{"t":"火伴","k":25},{"t":"，"},{"t":"火伴","k":25},{"t":"皆惊忙：同行"},{"t":"十二","k":7},{"t":"年，不知木兰是女郎。"}]},{"t":"雄兔脚扑朔，雌兔眼迷离；","n":"","cn":"提着兔子的耳朵悬在半空时，雄兔两只前脚时时动弹，雌兔两只眼睛时常眯着。","parts":[{"t":"雄兔脚"},{"t":"扑朔","k":26},{"t":"，雌兔眼"},{"t":"迷离","k":27},{"t":"；"}]},{"t":"双兔傍地走，安能辨我是雄雌？","n":"","cn":"雄雌两兔贴着地面跑，怎么能辨别哪只是雄兔，哪只是雌兔呢？傍地走：贴近地面跑","parts":[{"t":"双兔傍地走，"},{"t":"安","k":42},{"t":"能辨我是雄雌？"}]}],"words":[{"w":"当户织","e":"对着门织布"},{"w":"千里足","e":"指千里马"},{"w":"鸣溅溅","e":"【易错】“但闻燕山胡骑鸣啾啾”的“燕”读 yān；“鸣溅溅”的“溅”读 jiān。"},{"w":"唧唧","e":"叹息声"},{"w":"机杼","e":"织布机"},{"w":"军帖","e":"军中的文告"},{"w":"可汗","e":"古代西北地区民族对君主的称呼"},{"w":"十二","e":"表示多数，不是确指"},{"w":"鞍马","e":"泛指马和马具"},{"w":"辔头","e":"驾驭牲口用的嚼子和缰绳"},{"w":"溅溅","e":"水流声"},{"w":"胡骑","e":"胡人的战马"},{"w":"啾啾","e":"马叫的声音"},{"w":"戎机","e":"战事"},{"w":"金柝","e":"古时军中白天用来烧饭、夜里用来打更的器具"},{"w":"铁衣","e":"铠甲"},{"w":"天子","e":"指上文的“可汗”"},{"w":"明堂","e":"古代帝王举行大典的朝堂"},{"w":"策勋","e":"记功"},{"w":"不用","e":"不愿做"},{"w":"扶将","e":"扶持"},{"w":"红妆","e":"女子的艳丽装束"},{"w":"霍霍","e":"磨刀的声音"},{"w":"云鬓","e":"像云那样的鬓发"},{"w":"花黄","e":"古代妇女的一种面部装饰物"},{"w":"火伴","e":"同伍的士兵"},{"w":"扑朔","e":"动弹"},{"w":"迷离","e":"眯着眼"},{"w":"唯闻","e":"【易错】“唯闻女叹息”教材作“唯闻”，不写“惟闻”。"},{"w":"惟闻","e":"【易错】“唯闻女叹息”教材作“唯闻”，不写“惟闻”。"},{"w":"鞍鞯","e":"【易错】“鞍鞯”“辔头”都是马具，字形不可写错，“辔”下面是“口”。"},{"w":"伙伴","e":"【易错】“对镜帖花黄”的“帖”同“贴”；“火伴”同“伙伴”。"},{"w":"忆","e":"思念"},{"w":"旦","e":"早晨"},{"w":"度","e":"越过"},{"w":"朔","e":"北方"},{"w":"转","e":"勋位每升一级叫一转"},{"w":"强","e":"有余"},{"w":"郭","e":"外城"},{"w":"阁","e":"古代女子的卧房"},{"w":"裳","e":"古代下身穿的衣服"},{"w":"帖","e":"同“贴”"},{"w":"安","e":"怎么"},{"w":"唧","e":"【易错】“唧唧复唧唧”的“唧”是口字旁，不写“即”；“机杼”的“杼”是木字旁。"},{"w":"即","e":"【易错】“唧唧复唧唧”的“唧”是口字旁，不写“即”；“机杼”的“杼”是木字旁。"},{"w":"杼","e":"【易错】“唧唧复唧唧”的“唧”是口字旁，不写“即”；“机杼”的“杼”是木字旁。"},{"w":"辔","e":"【易错】“鞍鞯”“辔头”都是马具，字形不可写错，“辔”下面是“口”。"},{"w":"口","e":"【易错】“鞍鞯”“辔头”都是马具，字形不可写错，“辔”下面是“口”。"},{"w":"燕","e":"【易错】“但闻燕山胡骑鸣啾啾”的“燕”读 yān；“鸣溅溅”的“溅”读 jiān。"},{"w":"溅","e":"【易错】“但闻燕山胡骑鸣啾啾”的“燕”读 yān；“鸣溅溅”的“溅”读 jiān。"},{"w":"柝","e":"【易错】“朔气传金柝”的“朔”是北方，“柝”是木字旁，不写“拆”。"},{"w":"拆","e":"【易错】“朔气传金柝”的“朔”是北方，“柝”是木字旁，不写“拆”。"},{"w":"著","e":"【易错】“著我旧时裳”的“著”同“着”，读 zhuó；“裳”读 cháng。"},{"w":"着","e":"【易错】“著我旧时裳”的“著”同“着”，读 zhuó；“裳”读 cháng。"},{"w":"贴","e":"【易错】“对镜帖花黄”的“帖”同“贴”；“火伴”同“伙伴”。"}]},{"type":"list","title":"名句","items":["万里赴戎机，关山度若飞。","将军百战死，壮士十年归。","双兔傍地走，安能辨我是雄雌？"]},{"type":"list","title":"背诵提示","items":["“唧唧复唧唧”的“唧”是口字旁，不写“即”；“机杼”的“杼”是木字旁。","“唯闻女叹息”教材作“唯闻”，不写“惟闻”。","“可汗大点兵”的“可汗”读 kè hán；军书十二卷的“十二”是虚指。","“鞍鞯”“辔头”都是马具，字形不可写错，“辔”下面是“口”。","“但闻燕山胡骑鸣啾啾”的“燕”读 yān；“鸣溅溅”的“溅”读 jiān。","“朔气传金柝”的“朔”是北方，“柝”是木字旁，不写“拆”。","“著我旧时裳”的“著”同“着”，读 zhuó；“裳”读 cháng。","“对镜帖花黄”的“帖”同“贴”；“火伴”同“伙伴”。","“雄兔脚扑朔，雌兔眼迷离”中的“扑朔”“迷离”不可前后颠倒。"]}],"questions":[{"id":"p-p7b-mu-lan-shi-m0","type":"fill","stem":"默写填空：万里赴戎机，______。","answer":"关山度若飞。","explain":"出自《木兰诗》（北朝·佚名）：万里赴戎机，关山度若飞。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-mu-lan-shi-m1","type":"fill","stem":"默写填空：将军百战死，______。","answer":"壮士十年归。","explain":"出自《木兰诗》（北朝·佚名）：将军百战死，壮士十年归。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-mu-lan-shi-u","type":"fill","stem":"理解性默写：叹息声一声接着一声，木兰对着门在织布。","answer":"唧唧复唧唧，木兰当户织。","explain":"出自《木兰诗》（北朝·佚名）。句意：叹息声一声接着一声，木兰对着门在织布。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-deng-you-zhou-tai-ge","title":"登幽州台歌","subtitle":"唐·陈子昂","grade":"7b","tags":["言志","怀才不遇","登临"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·陈子昂"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"陈子昂（661—702），字伯玉，梓州射洪（今四川射洪）人，唐代文学家、诗人，初唐诗文革新的先驱。因曾任右拾遗，后世称他为“陈拾遗”。\n生平经历：少年时行侠仗义，十七八岁后才发愤读书，博览经史；后中进士，因上书论政受到武则天赏识；他曾两次随军出征，对边塞军民的疾苦与朝政弊端多有陈言；解官还乡后被人罗织罪名下狱，冤死狱中，年仅四十余岁。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗写于陈子昂随军北征、屡谏不被采纳之后，登幽州台慷慨悲吟。前两句纵贯古今，“前不见”“后不见”以两个否定构成时间的无垠，写出诗人怀才不遇、知音难觅的深沉孤独；第三句“念天地之悠悠”转入空间，由时间到空间，天地辽阔而个人渺小，孤独感被推向极致；末句“独怆然而涕下”直抒胸臆，一个“独”字点明孤独的核心。全诗不假雕饰，以苍劲奔放的语言、抑扬顿挫的节奏，塑造出一位胸怀大志却报国无门的诗人形象，被誉为“千古绝唱”"},{"type":"list","title":"中考考点","items":["“悠悠”“怆然”“涕”等词释义","前两句的时空对照（古今对比）与“独”字的表现力","诗歌所抒发的孤独悲愤、壮志难酬之情及对后世的影响。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"前不见古人，后不见来者。","n":"","cn":"往前看不到古代那些礼贤下士的贤明君主，往后也看不到后世这样的君主。","parts":[{"t":"前不见"},{"t":"古人","k":2},{"t":"，后不见"},{"t":"来者","k":3},{"t":"。"}]},{"t":"念天地之悠悠，独怆然而涕下！","n":"","cn":"想到天地这样辽阔、时间这样久远，我独自悲伤，泪水潸然而下！悠悠：形容时间的久远和空间的广大","parts":[{"t":"念天地之"},{"t":"悠悠","k":5},{"t":"，独"},{"t":"怆然","k":4},{"t":"而"},{"t":"涕","k":7},{"t":"下！"}]}],"words":[{"w":"幽州台","e":"【易错】诗题中的“幽州台”不写“幽洲台”。"},{"w":"幽洲台","e":"【易错】诗题中的“幽州台”不写“幽洲台”。"},{"w":"古人","e":"指古代礼贤下士的统治者"},{"w":"来者","e":"后世重视人才的贤明君主"},{"w":"怆然","e":"悲伤的样子"},{"w":"悠悠","e":"【易错】“念天地之悠悠”的“悠悠”指时间久远、空间广大，不写“幽幽”。"},{"w":"幽幽","e":"【易错】“念天地之悠悠”的“悠悠”指时间久远、空间广大，不写“幽幽”。"},{"w":"涕","e":"眼泪"},{"w":"怆","e":"【易错】“独怆然而涕下”的“怆”是竖心旁，不写“苍”；“涕”是眼泪，不写“悌”。"},{"w":"苍","e":"【易错】“独怆然而涕下”的“怆”是竖心旁，不写“苍”；“涕”是眼泪，不写“悌”。"},{"w":"悌","e":"【易错】“独怆然而涕下”的“怆”是竖心旁，不写“苍”；“涕”是眼泪，不写“悌”。"}]},{"type":"list","title":"名句","items":["念天地之悠悠，独怆然而涕下！"]},{"type":"list","title":"背诵提示","items":["“念天地之悠悠”的“悠悠”指时间久远、空间广大，不写“幽幽”。","“独怆然而涕下”的“怆”是竖心旁，不写“苍”；“涕”是眼泪，不写“悌”。","诗题中的“幽州台”不写“幽洲台”。"]}],"questions":[{"id":"p-p7b-deng-you-zhou-tai-ge-m0","type":"fill","stem":"默写填空：念天地之悠悠，______。","answer":"独怆然而涕下！。","explain":"出自《登幽州台歌》（唐·陈子昂）：念天地之悠悠，独怆然而涕下！","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-deng-you-zhou-tai-ge-u","type":"fill","stem":"理解性默写：往前看不到古代那些礼贤下士的贤明君主，往后也看不到后世这样的君主。","answer":"前不见古人，后不见来者。","explain":"出自《登幽州台歌》（唐·陈子昂）。句意：往前看不到古代那些礼贤下士的贤明君主，往后也看不到后世这样的君主。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-wang-yue","title":"望岳","subtitle":"唐·杜甫","grade":"7b","tags":["写景","言志","登临","律诗"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·杜甫"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"杜甫（712—770），字子美，自号少陵野老，唐代伟大的现实主义诗人，被后人尊称为“诗圣”，他的诗广泛而深刻地反映了唐代由盛转衰时期的社会现实，被称为“诗史”。\n生平经历：青年时曾漫游吴越齐赵，并与李白相识；后困居长安十年，屡试不第；安史之乱中被叛军俘获，逃出后任左拾遗，又因直言进谏被贬；晚年流寓成都，在浣花溪畔建草堂，后又漂泊于夔州、湖湘一带，770年病逝于湘江舟中。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是杜甫青年时期漫游齐赵时所作，全诗以“望”字统摄，句句在望。首联设问起笔，以“齐鲁青未了”写远望之阔，借齐鲁两地衬托泰山之高大绵延；颔联“钟”“割”二字最见炼字之功：“钟”写大自然之偏爱，“割”字写泰山遮天蔽日的分割之势，奇险有力；颈联由景入情，写细望山中云起、归鸟投林，“荡胸”写胸怀为之激荡；尾联由望岳而生登岳之志，“会当”“凌”写决心，“一览众山小”化用孔子“登泰山而小天下”，表现诗人不怕困难、勇于攀登的雄心壮志"},{"type":"list","title":"中考考点","items":["“钟”“割”“会当”“凌”等词的赏析与炼字","由远望、近望、细望到愿望的思路层次","“会当凌绝顶，一览众山小”的哲理名句默写及诗人雄心壮志","“曾”同“层”的通假。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"岱宗夫如何？齐鲁青未了。","n":"","cn":"泰山到底怎么样呢？在齐鲁大地上，那青翠的山色望不到尽头。","parts":[{"t":"岱宗","k":1},{"t":"夫","k":9},{"t":"如何？齐鲁"},{"t":"青未了","k":0},{"t":"。"}]},{"t":"造化钟神秀，阴阳割昏晓。","n":"","cn":"大自然把神奇秀丽的景色都聚集在这里，山的南北两面，一面明亮一面昏暗，截然不同。","parts":[{"t":"造化","k":2},{"t":"钟","k":10},{"t":"神秀，"},{"t":"阴阳","k":3},{"t":"割","k":18},{"t":"昏晓","k":7},{"t":"。"}]},{"t":"荡胸生曾云，决眦入归鸟。","n":"","cn":"山中层出不穷的云气使心胸震荡，张大眼睛望着归鸟飞回山中。","parts":[{"t":"荡胸生"},{"t":"曾","k":11},{"t":"云，"},{"t":"决眦","k":4},{"t":"入归鸟。"}]},{"t":"会当凌绝顶，一览众山小。","n":"","cn":"终要登上泰山顶峰，俯瞰群山，那时众山都会显得很渺小。","parts":[{"t":"会当","k":5},{"t":"凌","k":12},{"t":"绝顶，一览众"},{"t":"山","k":15},{"t":"小。"}]}],"words":[{"w":"青未了","e":"指郁苍苍的山色不尽"},{"w":"岱宗","e":"泰山的别称，居五岳之首"},{"w":"造化","e":"指大自然"},{"w":"阴阳","e":"山的北面为阴，南面为阳"},{"w":"决眦","e":"眼眶睁裂，形容极力张大眼睛"},{"w":"会当","e":"终当，终要"},{"w":"聚集","e":"【易错】“造化钟神秀”的“钟”是“聚集”，不写“中”或“衷”。"},{"w":"昏晓","e":"【易错】“阴阳割昏晓”的“割”是立刀旁，不写“割”以外的字；“昏晓”不写“昏小”。"},{"w":"昏小","e":"【易错】“阴阳割昏晓”的“割”是立刀旁，不写“割”以外的字；“昏晓”不写“昏小”。"},{"w":"夫","e":"读 fú，语气词"},{"w":"钟","e":"聚集"},{"w":"曾","e":"同“层”"},{"w":"凌","e":"登上"},{"w":"岱","e":"【易错】“岱宗夫如何”的“岱”是“代”下加“山”，“夫”读 fú。"},{"w":"代","e":"【易错】“岱宗夫如何”的“岱”是“代”下加“山”，“夫”读 fú。"},{"w":"山","e":"【易错】“岱宗夫如何”的“岱”是“代”下加“山”，“夫”读 fú。"},{"w":"中","e":"【易错】“造化钟神秀”的“钟”是“聚集”，不写“中”或“衷”。"},{"w":"衷","e":"【易错】“造化钟神秀”的“钟”是“聚集”，不写“中”或“衷”。"},{"w":"割","e":"【易错】“阴阳割昏晓”的“割”是立刀旁，不写“割”以外的字；“昏晓”不写“昏小”。"},{"w":"层","e":"【易错】“荡胸生曾云”的“曾”同“层”，不写“层”；“决眦”的“眦”是目字旁。"},{"w":"眦","e":"【易错】“荡胸生曾云”的“曾”同“层”，不写“层”；“决眦”的“眦”是目字旁。"},{"w":"陵","e":"【易错】“会当凌绝顶”的“凌”是两点水，不写“陵”。"}]},{"type":"list","title":"名句","items":["会当凌绝顶，一览众山小。"]},{"type":"list","title":"背诵提示","items":["“岱宗夫如何”的“岱”是“代”下加“山”，“夫”读 fú。","“造化钟神秀”的“钟”是“聚集”，不写“中”或“衷”。","“阴阳割昏晓”的“割”是立刀旁，不写“割”以外的字；“昏晓”不写“昏小”。","“荡胸生曾云”的“曾”同“层”，不写“层”；“决眦”的“眦”是目字旁。","“会当凌绝顶”的“凌”是两点水，不写“陵”。"]}],"questions":[{"id":"p-p7b-wang-yue-m0","type":"fill","stem":"默写填空：会当凌绝顶，______。","answer":"一览众山小。","explain":"出自《望岳》（唐·杜甫）：会当凌绝顶，一览众山小。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-wang-yue-u","type":"fill","stem":"理解性默写：泰山到底怎么样呢？在齐鲁大地上，那青翠的山色望不到尽头。","answer":"岱宗夫如何？齐鲁青未了。","explain":"出自《望岳》（唐·杜甫）。句意：泰山到底怎么样呢？在齐鲁大地上，那青翠的山色望不到尽头。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-deng-fei-lai-feng","title":"登飞来峰","subtitle":"宋·王安石","grade":"7b","tags":["言志","哲理","登临"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·王安石"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"王安石（1021—1086），字介甫，号半山，北宋政治家、文学家、思想家，抚州临川（今江西抚州）人，因封荆国公而被后人称为“王荆公”。\n生平经历：庆历二年中进士，此后长期在地方任职，深知民间疾苦；熙宁年间两度拜相，主持变法，推行青苗法、募役法、方田均税法等，史称“王安石变法”，因遭守旧派反对而屡起屡罢；晚年退居江宁半山园，元祐元年病逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗是王安石初任地方官时所作，借登塔望远的感受抒写胸襟。前两句写登临之高：“千寻塔”极言塔高，“闻说鸡鸣见日升”以虚写之笔烘托塔之峻拔、视野之开阔，为下文议论作铺垫。后两句转入议论抒情，“浮云”既是实景，又暗喻保守势力与重重障碍；“自缘身在最高层”点明能高瞻远瞩是因为站位高远，既含哲理，又表现诗人变法革新的抱负与无畏精神。全诗借景抒情、以理入诗，气势不凡"},{"type":"list","title":"中考考点","items":["“千寻”“缘”等词释义","“浮云”的比喻义与象征手法","名句默写及其蕴含的“站得高才能看得远”的道理，与苏轼“不识庐山真面目，只缘身在此山中”的比较","诗人变法图强的雄心与自信。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"飞来山上千寻塔，闻说鸡鸣见日升。","n":"","cn":"登上飞来峰顶那高耸入云的宝塔，听说在这里鸡鸣时就能看到太阳升起。","parts":[{"t":"飞来山上"},{"t":"千寻","k":2},{"t":"塔，"},{"t":"闻说","k":3},{"t":"鸡鸣见日升。"}]},{"t":"不畏浮云遮望眼，自缘身在最高层。","n":"","cn":"不怕浮云遮住我远望的视线，只因为我站在最高处。","parts":[{"t":"不畏","k":4},{"t":"浮云遮望眼，"},{"t":"自缘","k":5},{"t":"身在"},{"t":"最高层","k":0},{"t":"。"}]}],"words":[{"w":"最高层","e":"最高处"},{"w":"千层塔","e":"【易错】“飞来山上千寻塔”的“寻”是古代长度单位，不写“千层塔”。"},{"w":"千寻","e":"形容很高，古代八尺为一寻"},{"w":"闻说","e":"听说"},{"w":"不畏","e":"不怕"},{"w":"自缘","e":"【易错】“自缘身在最高层”教材作“自缘”，不写“只缘”。"},{"w":"只缘","e":"【易错】“自缘身在最高层”教材作“自缘”，不写“只缘”。"},{"w":"缘","e":"因为"},{"w":"寻","e":"【易错】“飞来山上千寻塔”的“寻”是古代长度单位，不写“千层塔”。"},{"w":"畏","e":"【易错】“不畏浮云遮望眼”的“畏”下面是“衣”的变形，不写“慰”。"},{"w":"衣","e":"【易错】“不畏浮云遮望眼”的“畏”下面是“衣”的变形，不写“慰”。"},{"w":"慰","e":"【易错】“不畏浮云遮望眼”的“畏”下面是“衣”的变形，不写“慰”。"}]},{"type":"list","title":"名句","items":["不畏浮云遮望眼，自缘身在最高层。"]},{"type":"list","title":"背诵提示","items":["“飞来山上千寻塔”的“寻”是古代长度单位，不写“千层塔”。","“自缘身在最高层”教材作“自缘”，不写“只缘”。","“不畏浮云遮望眼”的“畏”下面是“衣”的变形，不写“慰”。"]}],"questions":[{"id":"p-p7b-deng-fei-lai-feng-m0","type":"fill","stem":"默写填空：不畏浮云遮望眼，______。","answer":"自缘身在最高层。","explain":"出自《登飞来峰》（宋·王安石）：不畏浮云遮望眼，自缘身在最高层。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-deng-fei-lai-feng-u","type":"fill","stem":"理解性默写：登上飞来峰顶那高耸入云的宝塔，听说在这里鸡鸣时就能看到太阳升起。","answer":"飞来山上千寻塔，闻说鸡鸣见日升。","explain":"出自《登飞来峰》（宋·王安石）。句意：登上飞来峰顶那高耸入云的宝塔，听说在这里鸡鸣时就能看到太阳升起。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-you-shan-xi-cun","title":"游山西村","subtitle":"宋·陆游","grade":"7b","tags":["写景","哲理","田园","律诗"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·陆游"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"陆游（1125—1210），字务观，号放翁，越州山阴（今浙江绍兴）人，南宋爱国诗人，一生力主抗金，现存诗作九千余首，是我国古代存诗最多的诗人之一。\n生平经历：他出生在北宋灭亡前夕，少年时便立下抗金报国之志；二十九岁参加锁厅考试名列第一，却因名次排在秦桧之孙的前面而遭排挤；孝宗时赐进士出身，曾入四川宣抚使王炎幕府，亲历南郑前线的军旅生活；此后因坚持抗金屡遭贬黜，长期闲居山阴故里，八十五岁临终仍写下《示儿》，嘱咐“王师北定中原日，家祭无忘告乃翁”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗写诗人罢官闲居山阴时游访山西村的见闻感受。首联写农家热情好客，“莫笑”“足鸡豚”写出丰年之乐与淳朴民风。颔联是千古名句：“山重水复”写山水迂回，“疑无路”写心情之疑惧，“柳暗花明又一村”则境界顿开，既写景又寓理——困境中往往蕴含着希望，只要坚持前行就会出现转机，因此成为后世激励人们克服困难的名句。颈联写春社临近、箫鼓喧闹与民风古朴，表现诗人对乡村生活的热爱。尾联以“闲乘月”“夜叩门”写与村民的亲密无间。全诗写景、叙事、说理融为一体"},{"type":"list","title":"中考考点","items":["“腊酒”“豚”“春社”“无时”等词释义","颔联景物描写与哲理内涵（“疑无路”与“又一村”的对比）","诗人对乡村淳朴民风的赞美与热爱。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"莫笑农家腊酒浑，丰年留客足鸡豚。","n":"","cn":"不要笑话农家腊月里酿的酒浑浊，丰收的年景里他们待客的菜肴十分丰盛。","parts":[{"t":"莫笑农家"},{"t":"腊酒浑","k":4},{"t":"，丰年留客"},{"t":"足鸡豚","k":1},{"t":"。"}]},{"t":"山重水复疑无路，柳暗花明又一村。","n":"","cn":"山峦重重、溪水淙淙，正怀疑前面没有路了，忽然柳荫深深、鲜花明艳，又出现了一个村庄。","parts":[{"t":"山重水复疑无路，"},{"t":"柳暗花明","k":0},{"t":"又一村。"}]},{"t":"箫鼓追随春社近，衣冠简朴古风存。","n":"","cn":"箫声鼓声接连不断，春社的日子已经临近；村民们衣冠简朴，古老的习俗仍然保存着。","parts":[{"t":"箫","k":18},{"t":"鼓追随"},{"t":"春社","k":6},{"t":"近，衣冠简朴"},{"t":"古风存","k":2},{"t":"。"}]},{"t":"从今若许闲乘月，拄杖无时夜叩门。","n":"","cn":"今后如果允许我趁着月色闲游，我将拄着拐杖随时来敲门拜访。","parts":[{"t":"从今"},{"t":"若许","k":7},{"t":"闲乘月","k":3},{"t":"，"},{"t":"拄","k":20},{"t":"杖"},{"t":"无时","k":8},{"t":"夜"},{"t":"叩","k":21},{"t":"门。"}]}],"words":[{"w":"柳暗花明","e":"柳色深绿，花色红艳"},{"w":"足鸡豚","e":"鸡豚等菜肴充足，豚指小猪，这里指猪肉"},{"w":"古风存","e":"保留着淳朴的古代风俗"},{"w":"闲乘月","e":"趁着月明来闲游"},{"w":"腊酒浑","e":"【易错】“腊酒浑”的“腊”是月字旁，不写“蜡”；“浑”是三点水，不写“混”。"},{"w":"腊酒","e":"腊月里酿造的酒"},{"w":"春社","e":"古代祭祀土神的日子，在立春后第五个戊日"},{"w":"若许","e":"如果这样"},{"w":"无时","e":"没有固定的时间，即随时"},{"w":"深绿","e":"【易错】“柳暗花明又一村”的“暗”是“深绿”，不写“岸”。"},{"w":"浑","e":"浑浊"},{"w":"腊","e":"【易错】“腊酒浑”的“腊”是月字旁，不写“蜡”；“浑”是三点水，不写“混”。"},{"w":"蜡","e":"【易错】“腊酒浑”的“腊”是月字旁，不写“蜡”；“浑”是三点水，不写“混”。"},{"w":"混","e":"【易错】“腊酒浑”的“腊”是月字旁，不写“蜡”；“浑”是三点水，不写“混”。"},{"w":"豚","e":"【易错】“足鸡豚”的“豚”读 tún，指小猪，不写“逐”。"},{"w":"逐","e":"【易错】“足鸡豚”的“豚”读 tún，指小猪，不写“逐”。"},{"w":"暗","e":"【易错】“柳暗花明又一村”的“暗”是“深绿”，不写“岸”。"},{"w":"岸","e":"【易错】“柳暗花明又一村”的“暗”是“深绿”，不写“岸”。"},{"w":"箫","e":"【易错】“箫鼓追随春社近”的“箫”是竹字头，不写“萧”。"},{"w":"萧","e":"【易错】“箫鼓追随春社近”的“箫”是竹字头，不写“萧”。"},{"w":"拄","e":"【易错】“拄杖无时夜叩门”的“拄”是提手旁，“叩”是“口”加“卩”，不写“扣”。"},{"w":"叩","e":"【易错】“拄杖无时夜叩门”的“拄”是提手旁，“叩”是“口”加“卩”，不写“扣”。"},{"w":"口","e":"【易错】“拄杖无时夜叩门”的“拄”是提手旁，“叩”是“口”加“卩”，不写“扣”。"},{"w":"卩","e":"【易错】“拄杖无时夜叩门”的“拄”是提手旁，“叩”是“口”加“卩”，不写“扣”。"},{"w":"扣","e":"【易错】“拄杖无时夜叩门”的“拄”是提手旁，“叩”是“口”加“卩”，不写“扣”。"}]},{"type":"list","title":"名句","items":["山重水复疑无路，柳暗花明又一村。"]},{"type":"list","title":"背诵提示","items":["“腊酒浑”的“腊”是月字旁，不写“蜡”；“浑”是三点水，不写“混”。","“足鸡豚”的“豚”读 tún，指小猪，不写“逐”。","“柳暗花明又一村”的“暗”是“深绿”，不写“岸”。","“箫鼓追随春社近”的“箫”是竹字头，不写“萧”。","“拄杖无时夜叩门”的“拄”是提手旁，“叩”是“口”加“卩”，不写“扣”。"]}],"questions":[{"id":"p-p7b-you-shan-xi-cun-m0","type":"fill","stem":"默写填空：山重水复疑无路，______。","answer":"柳暗花明又一村。","explain":"出自《游山西村》（宋·陆游）：山重水复疑无路，柳暗花明又一村。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-you-shan-xi-cun-u","type":"fill","stem":"理解性默写：不要笑话农家腊月里酿的酒浑浊，丰收的年景里他们待客的菜肴十分丰盛。","answer":"莫笑农家腊酒浑，丰年留客足鸡豚。","explain":"出自《游山西村》（宋·陆游）。句意：不要笑话农家腊月里酿的酒浑浊，丰收的年景里他们待客的菜肴十分丰盛。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-ji-hai-za-shi-qi-wu","title":"己亥杂诗（其五）","subtitle":"清·龚自珍","grade":"7b","tags":["言志","离别","奉献"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"清·龚自珍"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"龚自珍（1792—1841），字璱人，又字尔玉，号定盦（也作定庵），清代思想家、文学家，浙江仁和（今浙江杭州）人。\n生平经历：道光九年中进士，官至礼部主事；他主张革除弊政、变法图强，是近代思想启蒙的先驱；道光十九年辞官南归，往返途中写成《己亥杂诗》三百一十五首，两年后病逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗写于诗人辞官南归途中。前两句叙事抒情：“浩荡离愁白日斜”既写离京的无限愁绪，又以“白日斜”点明时间、渲染苍茫氛围；“吟鞭东指即天涯”写去京之远，一个“即”字含无限惆怅，愁中又见洒脱。后两句是全诗精华，以“落红”自比：“落红不是无情物，化作春泥更护花”由落花归根的自然现象生发联想，表明自己虽脱离官场，仍要为国为民尽心尽力的心志。比喻巧妙，情中寓理，格调昂扬，成为历代传诵的名句"},{"type":"list","title":"中考考点","items":["“浩荡”“吟鞭”“落红”等词释义","“落红”的比喻义与托物言志（借落花自喻）的手法","名句默写及其所表现的奉献精神与不甘沉沦的报国之志。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"浩荡离愁白日斜，吟鞭东指即天涯。","n":"","cn":"离别的愁绪浩荡无边，向着日落的方向延伸；我挥动马鞭向东而去，离开京城便是天涯。","parts":[{"t":"浩荡离愁","k":0},{"t":"白日斜，"},{"t":"吟鞭","k":3},{"t":"东指即"},{"t":"天涯","k":4},{"t":"。"}]},{"t":"落红不是无情物，化作春泥更护花。","n":"","cn":"落花并不是没有感情的事物，它化作春天的泥土，反而更能滋养新的花朵。","parts":[{"t":"落红","k":5},{"t":"不是无情物，化"},{"t":"作","k":13},{"t":"春泥更护花。"}]}],"words":[{"w":"浩荡离愁","e":"【易错】“浩荡离愁”的“浩”是三点水，不写“皓”；“荡”是草字头。"},{"w":"红色的花","e":"【易错】“落红”指落花，不是“红色的花”；“化作春泥更护花”的“作”不写“做”。"},{"w":"浩荡","e":"形容愁绪无边无际"},{"w":"吟鞭","e":"诗人的马鞭"},{"w":"天涯","e":"指远离京城的地方"},{"w":"落红","e":"落花，诗人以落花自比"},{"w":"浩","e":"【易错】“浩荡离愁”的“浩”是三点水，不写“皓”；“荡”是草字头。"},{"w":"皓","e":"【易错】“浩荡离愁”的“浩”是三点水，不写“皓”；“荡”是草字头。"},{"w":"荡","e":"【易错】“浩荡离愁”的“浩”是三点水，不写“皓”；“荡”是草字头。"},{"w":"鞭","e":"【易错】“吟鞭东指即天涯”的“鞭”是革字旁，不写“便”；“涯”是三点水，不写“崖”。"},{"w":"便","e":"【易错】“吟鞭东指即天涯”的“鞭”是革字旁，不写“便”；“涯”是三点水，不写“崖”。"},{"w":"涯","e":"【易错】“吟鞭东指即天涯”的“鞭”是革字旁，不写“便”；“涯”是三点水，不写“崖”。"},{"w":"崖","e":"【易错】“吟鞭东指即天涯”的“鞭”是革字旁，不写“便”；“涯”是三点水，不写“崖”。"},{"w":"作","e":"【易错】“落红”指落花，不是“红色的花”；“化作春泥更护花”的“作”不写“做”。"},{"w":"做","e":"【易错】“落红”指落花，不是“红色的花”；“化作春泥更护花”的“作”不写“做”。"}]},{"type":"list","title":"名句","items":["落红不是无情物，化作春泥更护花。"]},{"type":"list","title":"背诵提示","items":["“浩荡离愁”的“浩”是三点水，不写“皓”；“荡”是草字头。","“吟鞭东指即天涯”的“鞭”是革字旁，不写“便”；“涯”是三点水，不写“崖”。","“落红”指落花，不是“红色的花”；“化作春泥更护花”的“作”不写“做”。"]}],"questions":[{"id":"p-p7b-ji-hai-za-shi-qi-wu-m0","type":"fill","stem":"默写填空：落红不是无情物，______。","answer":"化作春泥更护花。","explain":"出自《己亥杂诗（其五）》（清·龚自珍）：落红不是无情物，化作春泥更护花。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-ji-hai-za-shi-qi-wu-u","type":"fill","stem":"理解性默写：离别的愁绪浩荡无边，向着日落的方向延伸；我挥动马鞭向东而去，离开京城便是天涯。","answer":"浩荡离愁白日斜，吟鞭东指即天涯。","explain":"出自《己亥杂诗（其五）》（清·龚自珍）。句意：离别的愁绪浩荡无边，向着日落的方向延伸；我挥动马鞭向东而去，离开京城便是天涯。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-lou-shi-ming","title":"陋室铭","subtitle":"唐·刘禹锡","grade":"7b","tags":["文言文","托物言志","铭"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·刘禹锡"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"刘禹锡（772—842），字梦得，洛阳（今河南洛阳）人，唐代文学家、哲学家。他与柳宗元并称“刘柳”，与白居易并称“刘白”；因其诗风豪迈刚健，白居易称他为“诗豪”。\n生平经历：贞元年间与柳宗元同榜进士，后一同参与永贞革新；革新失败后先被贬为朗州司马，此后又辗转连州、夔州、和州等地，前后贬谪二十三年；晚年回到洛阳任太子宾客，世称“刘宾客”，加检校礼部尚书，卒于洛阳。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文是刘禹锡的托物言志之作。开篇以“山不在高”“水不在深”类比起兴，用“仙”“龙”引出“斯是陋室，惟吾德馨”的主旨。接着从三方面写“不陋”：环境幽雅（“苔痕上阶绿，草色入帘青”）、交往雅致（“谈笑有鸿儒，往来无白丁”）、情趣高雅（“调素琴，阅金经”“无案牍之劳形”）；再以诸葛庐、子云亭作类比，并以孔子“何陋之有”的反问收束，含不尽之意。全文短小精悍，多用对偶押韵，音韵和谐，表现作者安贫乐道、高洁傲岸的节操"},{"type":"list","title":"中考考点","items":["“名”“灵”“馨”“鸿儒”“白丁”“劳形”等词释义","托物言志的写法与“惟吾德馨”这一主旨句","“何陋之有”宾语前置句式及类比、对偶的修辞。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"山不在高，有仙则名。水不在深，有龙则灵。","n":"","cn":"山不一定要高，有了仙人就著名了；水不一定要深，有了龙就成为灵异的水了。","parts":[{"t":"山不在高，有仙则"},{"t":"名","k":14},{"t":"。水不在深，有龙则"},{"t":"灵","k":15},{"t":"。"}]},{"t":"斯是陋室，惟吾德馨。","n":"","cn":"这是简陋的屋舍，只是我（住屋的人）的品德高尚（就不感到简陋了）。","parts":[{"t":"斯是陋室，"},{"t":"惟吾德馨","k":0},{"t":"。"}]},{"t":"苔痕上阶绿，草色入帘青。","n":"","cn":"苔藓痕迹蔓延到台阶上，一片碧绿；草色映入竹帘，满目青翠。","parts":[{"t":"苔","k":27},{"t":"痕"},{"t":"上","k":17},{"t":"阶绿，草色"},{"t":"入","k":18},{"t":"帘青。"}]},{"t":"谈笑有鸿儒，往来无白丁。","n":"","cn":"说笑谈笑的都是博学的人，来往的没有平民。","parts":[{"t":"谈笑有"},{"t":"鸿儒","k":4},{"t":"，往来无"},{"t":"白丁","k":5},{"t":"。"}]},{"t":"可以调素琴，阅金经。","n":"","cn":"可以弹奏不加装饰的琴，阅读佛经。","parts":[{"t":"可以"},{"t":"调","k":19},{"t":"素琴","k":6},{"t":"，阅"},{"t":"金经","k":7},{"t":"。"}]},{"t":"无丝竹之乱耳，无案牍之劳形。","n":"","cn":"没有奏乐的声音扰乱耳朵，没有官府的公文使身体劳累。","parts":[{"t":"无"},{"t":"丝竹","k":8},{"t":"之乱耳，无"},{"t":"案牍","k":9},{"t":"之"},{"t":"劳形","k":10},{"t":"。"}]},{"t":"南阳诸葛庐，西蜀子云亭。","n":"","cn":"南阳诸葛亮的草庐，西蜀扬子云的亭子。","parts":[{"t":"南阳"},{"t":"诸葛庐","k":1},{"t":"，西蜀"},{"t":"子云亭","k":2},{"t":"。"}]},{"t":"孔子云：何陋之有？","n":"孔子说：有什么简陋的呢？何陋之有：即“有何陋”，宾语前置。","cn":"","parts":[{"t":"孔"},{"t":"子云","k":12},{"t":"：何陋之有？"}]}],"words":[{"w":"惟吾德馨","e":"【易错】“惟吾德馨”的“惟”是“只”，不写“唯”也可通，但教材作“惟吾德馨”。"},{"w":"诸葛庐","e":"诸葛亮隐居南阳时的草庐"},{"w":"子云亭","e":"扬雄的亭子，扬雄字子云"},{"w":"孔子说","e":"有什么简陋的呢？何陋之有：即“有何陋”，宾语前置"},{"w":"鸿儒","e":"博学的人"},{"w":"白丁","e":"平民，这里指没有学问的人"},{"w":"素琴","e":"不加装饰的琴"},{"w":"金经","e":"指佛经"},{"w":"丝竹","e":"琴瑟、箫管等乐器，这里指奏乐的声音"},{"w":"案牍","e":"官府文书"},{"w":"劳形","e":"使身体劳累"},{"w":"德馨","e":"【易错】“德馨”的“馨”是“声”下加“香”，不写“罄”或“磬”。"},{"w":"子云","e":"【易错】“西蜀子云亭”的“子云”指扬雄，不写“杨雄”。"},{"w":"杨雄","e":"【易错】“西蜀子云亭”的“子云”指扬雄，不写“杨雄”。"},{"w":"名","e":"出名，著名"},{"w":"灵","e":"灵异"},{"w":"馨","e":"能散布很远的香气，这里指德行美好"},{"w":"上","e":"长上"},{"w":"入","e":"映入"},{"w":"调","e":"调弄，这里指弹（琴）"},{"w":"惟","e":"【易错】“惟吾德馨”的“惟”是“只”，不写“唯”也可通，但教材作“惟吾德馨”。"},{"w":"只","e":"【易错】“惟吾德馨”的“惟”是“只”，不写“唯”也可通，但教材作“惟吾德馨”。"},{"w":"唯","e":"【易错】“惟吾德馨”的“惟”是“只”，不写“唯”也可通，但教材作“惟吾德馨”。"},{"w":"声","e":"【易错】“德馨”的“馨”是“声”下加“香”，不写“罄”或“磬”。"},{"w":"香","e":"【易错】“德馨”的“馨”是“声”下加“香”，不写“罄”或“磬”。"},{"w":"罄","e":"【易错】“德馨”的“馨”是“声”下加“香”，不写“罄”或“磬”。"},{"w":"磬","e":"【易错】“德馨”的“馨”是“声”下加“香”，不写“罄”或“磬”。"},{"w":"苔","e":"【易错】“苔痕上阶绿”的“苔”是草字头，不写“台”。"},{"w":"台","e":"【易错】“苔痕上阶绿”的“苔”是草字头，不写“台”。"},{"w":"鸿","e":"【易错】“谈笑有鸿儒”的“鸿”是“大”的意思，不写“红”；“儒”是单人旁，不写“孺”。"},{"w":"大","e":"【易错】“谈笑有鸿儒”的“鸿”是“大”的意思，不写“红”；“儒”是单人旁，不写“孺”。"},{"w":"红","e":"【易错】“谈笑有鸿儒”的“鸿”是“大”的意思，不写“红”；“儒”是单人旁，不写“孺”。"},{"w":"儒","e":"【易错】“谈笑有鸿儒”的“鸿”是“大”的意思，不写“红”；“儒”是单人旁，不写“孺”。"},{"w":"孺","e":"【易错】“谈笑有鸿儒”的“鸿”是“大”的意思，不写“红”；“儒”是单人旁，不写“孺”。"},{"w":"牍","e":"【易错】“可以调素琴”的“调”读 tiáo；“无案牍之劳形”的“牍”是片字旁，不写“读”。"},{"w":"读","e":"【易错】“可以调素琴”的“调”读 tiáo；“无案牍之劳形”的“牍”是片字旁，不写“读”。"}]},{"type":"h","text":"译文"},{"type":"p","text":"山不在于高，有仙人居住就著名；水不在于深，有蛟龙潜藏就显得灵异。这是一间简陋的屋子，只因我的品德美好（而不觉得简陋）。苔痕蔓延到台阶上，一片碧绿；草色映入竹帘，满眼青翠。说笑的都是博学多识的人，来往的没有浅薄无学之人。可以弹弹素琴，读读佛经；没有嘈杂的乐声扰乱耳朵，没有繁杂的公文使身体劳累。就像南阳诸葛亮的草庐、西蜀扬子云的亭子一样。孔子说过：有什么简陋的呢？"},{"type":"list","title":"名句","items":["山不在高，有仙则名。","斯是陋室，惟吾德馨。","苔痕上阶绿，草色入帘青。"]},{"type":"list","title":"背诵提示","items":["“惟吾德馨”的“惟”是“只”，不写“唯”也可通，但教材作“惟吾德馨”。","“德馨”的“馨”是“声”下加“香”，不写“罄”或“磬”。","“苔痕上阶绿”的“苔”是草字头，不写“台”。","“谈笑有鸿儒”的“鸿”是“大”的意思，不写“红”；“儒”是单人旁，不写“孺”。","“可以调素琴”的“调”读 tiáo；“无案牍之劳形”的“牍”是片字旁，不写“读”。","“西蜀子云亭”的“子云”指扬雄，不写“杨雄”。"]}],"questions":[{"id":"p-p7b-lou-shi-ming-m0","type":"fill","stem":"默写填空：山不在高，______。","answer":"有仙则名。","explain":"出自《陋室铭》（唐·刘禹锡）：山不在高，有仙则名。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-lou-shi-ming-m1","type":"fill","stem":"默写填空：斯是陋室，______。","answer":"惟吾德馨。","explain":"出自《陋室铭》（唐·刘禹锡）：斯是陋室，惟吾德馨。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-lou-shi-ming-u","type":"fill","stem":"理解性默写：山不一定要高，有了仙人就著名了；水不一定要深，有了龙就成为灵异的水了。","answer":"山不在高，有仙则名。水不在深，有龙则灵。","explain":"出自《陋室铭》（唐·刘禹锡）。句意：山不一定要高，有了仙人就著名了；水不一定要深，有了龙就成为灵异的水了。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-ai-lian-shuo","title":"爱莲说","subtitle":"宋·周敦颐","grade":"7b","tags":["文言文","托物言志","说"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·周敦颐"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"周敦颐（1017—1073），字茂叔，世称濂溪先生，道州营道（今湖南道县）人，北宋哲学家、文学家，是宋明理学的开山鼻祖，程颢、程颐兄弟曾向他问学，朱熹对他推崇备至；因他晚年在庐山莲花峰下建濂溪书堂讲学，学者便称他濂溪先生。\n生平经历：他一生主要担任地方官，历任分宁主簿、南昌知县、虔州通判、广南东路提点刑狱等职，为官清廉、秉公执法，曾因坚持依法断案而与上司反复争辩，甚至准备辞官；晚年定居庐山莲花峰下讲学著述，1073年病逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文是周敦颐的托物言志名篇。文章以“可爱者甚蕃”总起，用菊、牡丹正衬反衬莲花：“晋陶渊明独爱菊”是正衬隐逸，“世人甚爱牡丹”是反衬富贵，突出作者“独爱莲”的与众不同。第二段集中描写莲的形象：从生长环境（“出淤泥而不染，濯清涟而不妖”）、体态（“中通外直，不蔓不枝”）、香气与风度（“香远益清”“亭亭净植，可远观而不可亵玩”）刻画，并以菊喻隐士、牡丹喻富贵者、莲喻君子，托物言志，表现作者洁身自好、不慕名利的品格。结尾一“噫”字含慨叹，含蓄批判追名逐利的世风"},{"type":"list","title":"中考考点","items":["“蕃”“濯”“妖”“亭亭”“宜”“鲜”等词释义","托物言志与正衬、反衬手法的分析","“出淤泥而不染”等名句默写及莲的象征意义。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"水陆草木之花，可爱者甚蕃。","n":"","cn":"水上、陆地上各种草木的花，值得喜爱的很多。","parts":[{"t":"水陆草木之花，可爱者甚"},{"t":"蕃","k":14},{"t":"。"}]},{"t":"晋陶渊明独爱菊。自李唐来，世人甚爱牡丹。","n":"","cn":"晋代的陶渊明只喜爱菊花。自唐朝以来，世上的人很喜爱牡丹。","parts":[{"t":"晋陶渊明独爱菊。自"},{"t":"李唐","k":4},{"t":"来，"},{"t":"世人甚爱牡丹","k":0},{"t":"。"}]},{"t":"予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远益清，亭亭净植，可远观而不可亵玩焉。","n":"","cn":"我唯独喜爱莲花从淤泥里生长出来却不沾染污秽，经过清水洗涤但不显得妖艳；茎干内部贯通、外形笔直，不横生藤蔓、不旁生枝茎；香气传播得越远就越清芬；它洁净地挺立着，可以远远地观赏却不可以靠近玩弄。","parts":[{"t":"予独爱莲之出"},{"t":"淤","k":16},{"t":"泥而不"},{"t":"染","k":10},{"t":"，"},{"t":"濯","k":18},{"t":"清"},{"t":"涟","k":19},{"t":"而不"},{"t":"妖","k":11},{"t":"，中通外直，"},{"t":"不蔓不枝","k":1},{"t":"，香远益清，"},{"t":"亭亭净植","k":2},{"t":"，可远观而不可"},{"t":"亵玩","k":6},{"t":"焉。"}]},{"t":"予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。","n":"","cn":"我认为菊花是花中的隐士；牡丹是花中的富贵者；莲花是花中的君子。","parts":[{"t":"予"},{"t":"谓","k":12},{"t":"菊，花之"},{"t":"隐逸","k":7},{"t":"者也；牡丹，花之富贵者也；莲，花之君子者也。"}]},{"t":"噫！菊之爱，陶后鲜有闻。莲之爱，同予者何人？牡丹之爱，宜乎众矣。","n":"","cn":"唉！对于菊花的喜爱，陶渊明以后很少听到了。对于莲花的喜爱，像我一样的还有什么人呢？对于牡丹的喜爱，当然人很多了。","parts":[{"t":"噫","k":13},{"t":"！菊之爱，陶后"},{"t":"鲜","k":26},{"t":"有闻。莲之爱，同予者何人？牡丹之爱，"},{"t":"宜乎众矣","k":3},{"t":"。"}]}],"words":[{"w":"世人甚爱牡丹","e":"是反衬富贵"},{"w":"不蔓不枝","e":"【易错】“不蔓不枝”的“蔓”是草字头，不写“漫”。"},{"w":"亭亭净植","e":"【易错】“亭亭净植”的“亭亭”不写“婷婷”。"},{"w":"宜乎众矣","e":"【易错】“陶后鲜有闻”的“鲜”读 xiǎn，意为少；“宜乎众矣”的“宜”是“应当、当然”。"},{"w":"李唐","e":"指唐朝，皇帝姓李"},{"w":"亭亭","e":"耸立的样子"},{"w":"亵玩","e":"靠近玩弄"},{"w":"隐逸","e":"隐居避世"},{"w":"宜乎","e":"当然"},{"w":"婷婷","e":"【易错】“亭亭净植”的“亭亭”不写“婷婷”。"},{"w":"染","e":"沾染（污秽）"},{"w":"妖","e":"艳丽"},{"w":"谓","e":"认为"},{"w":"噫","e":"叹词，表示感慨"},{"w":"蕃","e":"【易错】“可爱者甚蕃”的“蕃”读 fán，意为多，不写“繁”。"},{"w":"繁","e":"【易错】“可爱者甚蕃”的“蕃”读 fán，意为多，不写“繁”。"},{"w":"淤","e":"【易错】“出淤泥而不染”的“淤”是三点水，不写“於”。"},{"w":"於","e":"【易错】“出淤泥而不染”的“淤”是三点水，不写“於”。"},{"w":"濯","e":"【易错】“濯清涟而不妖”的“濯”是三点水，“涟”是三点水，都不写偏旁。"},{"w":"涟","e":"【易错】“濯清涟而不妖”的“濯”是三点水，“涟”是三点水，都不写偏旁。"},{"w":"蔓","e":"【易错】“不蔓不枝”的“蔓”是草字头，不写“漫”。"},{"w":"漫","e":"【易错】“不蔓不枝”的“蔓”是草字头，不写“漫”。"},{"w":"亵","e":"【易错】“可远观而不可亵玩焉”的“亵”是“衣”字中间一个“执”，不写“衰”。"},{"w":"衣","e":"【易错】“可远观而不可亵玩焉”的“亵”是“衣”字中间一个“执”，不写“衰”。"},{"w":"执","e":"【易错】“可远观而不可亵玩焉”的“亵”是“衣”字中间一个“执”，不写“衰”。"},{"w":"衰","e":"【易错】“可远观而不可亵玩焉”的“亵”是“衣”字中间一个“执”，不写“衰”。"},{"w":"鲜","e":"【易错】“陶后鲜有闻”的“鲜”读 xiǎn，意为少；“宜乎众矣”的“宜”是“应当、当然”。"},{"w":"宜","e":"【易错】“陶后鲜有闻”的“鲜”读 xiǎn，意为少；“宜乎众矣”的“宜”是“应当、当然”。"}]},{"type":"list","title":"名句","items":["予独爱莲之出淤泥而不染，濯清涟而不妖。"]},{"type":"list","title":"背诵提示","items":["“可爱者甚蕃”的“蕃”读 fán，意为多，不写“繁”。","“出淤泥而不染”的“淤”是三点水，不写“於”。","“濯清涟而不妖”的“濯”是三点水，“涟”是三点水，都不写偏旁。","“不蔓不枝”的“蔓”是草字头，不写“漫”。","“亭亭净植”的“亭亭”不写“婷婷”。","“可远观而不可亵玩焉”的“亵”是“衣”字中间一个“执”，不写“衰”。","“陶后鲜有闻”的“鲜”读 xiǎn，意为少；“宜乎众矣”的“宜”是“应当、当然”。"]}],"questions":[{"id":"p-p7b-ai-lian-shuo-m0","type":"fill","stem":"默写填空：予独爱莲之出淤泥而不染，______。","answer":"濯清涟而不妖。","explain":"出自《爱莲说》（宋·周敦颐）：予独爱莲之出淤泥而不染，濯清涟而不妖。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-ai-lian-shuo-u","type":"fill","stem":"理解性默写：水上、陆地上各种草木的花，值得喜爱的很多。","answer":"水陆草木之花，可爱者甚蕃。","explain":"出自《爱莲说》（宋·周敦颐）。句意：水上、陆地上各种草木的花，值得喜爱的很多。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-he-zhong-shi-shou","title":"河中石兽（节选）","subtitle":"清·纪昀","grade":"7b","tags":["文言文","说理","实践"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"清·纪昀"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"纪昀（1724—1805），字晓岚，一字春帆，晚号石云，直隶献县（今河北献县）人，清代学者、文学家；官至礼部尚书、协办大学士，死后谥号文达，世称纪文达公。他学识淹博，尤长于典籍的整理与考订。\n生平经历：他自幼聪颖，乾隆十九年（1754）中进士，入翰林院；乾隆三十八年（1773）起任《四库全书》总纂官，历时十余年，主持编成这部我国古代规模最大的丛书，并审定《四库全书总目提要》；其间曾因向姻亲通风报信而被革职，遣戍乌鲁木齐两年，赦还后复官，晚年官位渐高，1805年去世。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文选自纪昀《阅微草堂笔记》，是一则寓意深刻的笔记体散文。文章按“寻石兽—讲学家论理—老河兵释疑—得石兽—议论作结”的思路展开：讲学家空谈事理、脱离实际，老河兵因长期实践而深知水沙石的关系，其推断被证实。全文以讲学家与老河兵的“笑”及两种相反结论形成对比，人物语言个性鲜明，叙议结合，最后以“然则天下之事……可据理臆断欤”的反问作结，点明主旨：做事不能只凭主观臆断，实践出真知"},{"type":"list","title":"中考考点","items":["“临”“圮”“阅”“棹”“曳”“湮”“啮”“臆断”等词释义和“棹”的名词作动词用法","讲学家与老河兵观点对立的对比手法及人物形象","末段议论句的含义与文章主旨","“尔辈不能究物理”中“物理”的古今异义。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"沧州南一寺临河干，山门圮于河，二石兽并沉焉。","n":"","cn":"沧州南边有一座寺庙靠近河岸，佛寺的外门倒塌在河里，两只石兽一起沉入水中。","parts":[{"t":"沧州南一寺临"},{"t":"河干","k":2},{"t":"，山门"},{"t":"圮","k":12},{"t":"于河，二石兽"},{"t":"并","k":13},{"t":"沉焉。"}]},{"t":"阅十余岁，僧募金重修，求二石兽于水中，竟不可得，以为顺流下矣。","n":"","cn":"经过了十多年，僧人募集钱财重修寺庙，在河中寻找两只石兽，最后没能找到，认为它们顺着水流流到下游了。","parts":[{"t":"阅","k":14},{"t":"十余岁，僧募金重修，求二石兽于水中，"},{"t":"竟","k":15},{"t":"不可得，以为顺流下矣。"}]},{"t":"棹数小舟，曳铁钯，寻十余里无迹。","n":"","cn":"划着几只小船，拖着铁钯，找了十多里也没有找到石兽的踪迹。","parts":[{"t":"棹","k":16},{"t":"数小舟，"},{"t":"曳","k":22},{"t":"铁钯","k":3},{"t":"，寻十余里无迹。"}]},{"t":"一讲学家设帐寺中，闻之笑曰：“尔辈不能究物理。是非木杮，岂能为暴涨携之去？”","n":"","cn":"一位讲学家在寺庙里设帐讲学，听说了这件事笑着说：“你们这些人不能探求事物的道理。这不是木片，怎么能被大水带走呢？”设帐：设馆授徒","parts":[{"t":"一讲学家设帐寺中，闻之笑曰：“"},{"t":"尔辈","k":4},{"t":"不能"},{"t":"究","k":17},{"t":"物理","k":5},{"t":"。"},{"t":"是非木杮","k":0},{"t":"，岂能为暴涨携之去？”"}]},{"t":"“乃石性坚重，沙性松浮，湮于沙上，渐沉渐深耳。沿河求之，不亦颠乎？”","n":"","cn":"“石头的性质坚硬沉重，沙的性质松软浮动，石兽埋在沙里，越沉越深罢了。顺着河流寻找它们是荒谬的。”湮：埋没","parts":[{"t":"“乃石性坚重，沙性松浮，"},{"t":"湮于沙上","k":1},{"t":"，渐沉渐深耳。沿河求之，不亦"},{"t":"颠","k":18},{"t":"乎？”"}]},{"t":"众服为确论。","n":"","cn":"大家都很信服，认为是正确的言论。","parts":[{"t":"众服为"},{"t":"确论","k":7},{"t":"。"}]},{"t":"一老河兵闻之，又笑曰：“凡河中失石，当求之于上流。”","n":"","cn":"一位老河兵听说了讲学家的观点，又笑着说：“凡是落入河中的石头，都应当在河的上游寻找它。”河兵：巡河、护河的士兵。","parts":[{"t":"一老河兵闻之，又笑曰：“凡河中失石，当求之于上流。”"}]},{"t":"“盖石性坚重，沙性松浮，水不能冲石，其反激之力，必于石下迎水处啮沙为坎穴。”","n":"","cn":"“正因为石头的性质坚硬沉重，沙的性质松软浮动，水冲不走石头，它的反冲力一定在石头下面迎水的地方冲刷沙子，形成坑洞。”啮：咬，这里是侵蚀、冲刷的意思","parts":[{"t":"“盖石性坚重，沙性松浮，水不能冲石，其反激之力，必于石下迎水处"},{"t":"啮","k":28},{"t":"沙为"},{"t":"坎穴","k":8},{"t":"。”"}]},{"t":"“渐激渐深，至石之半，石必倒掷坎穴中。如是再啮，石又再转。”","n":"","cn":"“越冲越深，冲到石头底部的一半时，石头必定倒在坑洞里。像这样再冲刷，石头又会再一次翻转。”倒掷：倾倒","parts":[{"t":"“渐激渐深，至石之半，石必倒掷"},{"t":"坎穴","k":8},{"t":"中。"},{"t":"如是","k":9},{"t":"再"},{"t":"啮","k":28},{"t":"，石又再转。”"}]},{"t":"“转转不已，遂反溯流逆上矣。求之下流，固颠；求之地中，不更颠乎？”","n":"","cn":"“不停地翻转，于是反而逆流而上了。到下游去寻找石兽固然荒谬，在原地沙中寻找它们，不是更荒谬吗？”已：停止","parts":[{"t":"“转转不已，遂反"},{"t":"溯流","k":10},{"t":"逆上矣。求之下流，固"},{"t":"颠","k":18},{"t":"；求之地中，不更"},{"t":"颠","k":18},{"t":"乎？”"}]},{"t":"如其言，果得于数里外。","n":"","cn":"按照他的话去寻找，果然在几里之外找到了石兽。","parts":[{"t":"如","k":19},{"t":"其言，果得于数里外。"}]},{"t":"然则天下之事，但知其一，不知其二者多矣，可据理臆断欤？","n":"","cn":"既然这样，那么天下的事，只了解其一、不了解其二的情况太多了，怎么能只根据某个道理就主观判断呢？然则：既然这样，那么","parts":[{"t":"然则天下之事，但知其一，不知其二者多矣，可据理"},{"t":"臆断","k":11},{"t":"欤","k":20},{"t":"？"}]}],"words":[{"w":"是非木杮","e":"【易错】“是非木杮”的“杮”读 fèi，指削下的木片，注意与“柿”字形区别。"},{"w":"湮于沙上","e":"【易错】“湮于沙上”的“湮”是三点水，不写“淹”。"},{"w":"河干","e":"河岸"},{"w":"铁钯","e":"农具，用于除草、平土"},{"w":"尔辈","e":"你们这些人"},{"w":"物理","e":"事物的道理、规律"},{"w":"木杮","e":"削下的木片"},{"w":"确论","e":"正确的言论"},{"w":"坎穴","e":"坑洞"},{"w":"如是","e":"像这样"},{"w":"溯流","e":"逆流"},{"w":"臆断","e":"主观地判断"},{"w":"圮","e":"倒塌"},{"w":"并","e":"一起"},{"w":"阅","e":"经过，经历"},{"w":"竟","e":"终于，到底"},{"w":"棹","e":"名词用作动词，划（船）"},{"w":"究","e":"探求"},{"w":"颠","e":"精神失常，引申为荒谬"},{"w":"如","e":"按照"},{"w":"欤","e":"语气词，表反问"},{"w":"圯","e":"【易错】“山门圮于河”的“圮”读 pǐ，意为倒塌，土字旁，不写“圯”。"},{"w":"曳","e":"【易错】“棹数小舟，曳铁钯”的“棹”是木字旁，“曳”不写“拽”。"},{"w":"拽","e":"【易错】“棹数小舟，曳铁钯”的“棹”是木字旁，“曳”不写“拽”。"},{"w":"杮","e":"【易错】“是非木杮”的“杮”读 fèi，指削下的木片，注意与“柿”字形区别。"},{"w":"柿","e":"【易错】“是非木杮”的“杮”读 fèi，指削下的木片，注意与“柿”字形区别。"},{"w":"湮","e":"【易错】“湮于沙上”的“湮”是三点水，不写“淹”。"},{"w":"淹","e":"【易错】“湮于沙上”的“湮”是三点水，不写“淹”。"},{"w":"啮","e":"【易错】“啮沙为坎穴”的“啮”是口字旁，不写“噬”或“齿”。"},{"w":"噬","e":"【易错】“啮沙为坎穴”的“啮”是口字旁，不写“噬”或“齿”。"},{"w":"齿","e":"【易错】“啮沙为坎穴”的“啮”是口字旁，不写“噬”或“齿”。"},{"w":"臆","e":"【易错】“可据理臆断欤”的“臆”是月字旁，不写“意”；“欤”是语气词，不写“与”。"},{"w":"意","e":"【易错】“可据理臆断欤”的“臆”是月字旁，不写“意”；“欤”是语气词，不写“与”。"},{"w":"与","e":"【易错】“可据理臆断欤”的“臆”是月字旁，不写“意”；“欤”是语气词，不写“与”。"}]},{"type":"list","title":"名句","items":["然则天下之事，但知其一，不知其二者多矣，可据理臆断欤？"]},{"type":"list","title":"背诵提示","items":["“山门圮于河”的“圮”读 pǐ，意为倒塌，土字旁，不写“圯”。","“棹数小舟，曳铁钯”的“棹”是木字旁，“曳”不写“拽”。","“是非木杮”的“杮”读 fèi，指削下的木片，注意与“柿”字形区别。","“湮于沙上”的“湮”是三点水，不写“淹”。","“啮沙为坎穴”的“啮”是口字旁，不写“噬”或“齿”。","“可据理臆断欤”的“臆”是月字旁，不写“意”；“欤”是语气词，不写“与”。"]}],"questions":[{"id":"p-p7b-he-zhong-shi-shou-m0","type":"fill","stem":"默写填空：然则天下之事，______。","answer":"但知其一。","explain":"出自《河中石兽（节选）》（清·纪昀）：然则天下之事，但知其一，不知其二者多矣，可据理臆断欤？","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-he-zhong-shi-shou-u","type":"fill","stem":"理解性默写：沧州南边有一座寺庙靠近河岸，佛寺的外门倒塌在河里，两只石兽一起沉入水中。","answer":"沧州南一寺临河干，山门圮于河，二石兽并沉焉。","explain":"出自《河中石兽（节选）》（清·纪昀）。句意：沧州南边有一座寺庙靠近河岸，佛寺的外门倒塌在河里，两只石兽一起沉入水中。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-zhu-li-guan","title":"竹里馆","subtitle":"唐·王维","grade":"7b","tags":["山水田园","写景","闲适"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·王维"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"王维（701—761），字摩诘，号摩诘居士，唐代诗人、画家，因官至尚书右丞，世称“王右丞”；他的名与字同取佛教居士“维摩诘”之名，因而又被后人称为“诗佛”。\n生平经历：他少年时便以诗、画与音乐闻名，二十出头便考中进士，早年仕途较为顺利，曾任太乐丞、右拾遗等职；安史之乱中他被迫接受安禄山的伪职，乱平后因此获罪，经人营救才得以宽免；此后他逐渐疏离政治，长期半官半隐于辋川别业，过着亦官亦隐的生活。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗写诗人月夜独坐竹林的闲适生活。前两句以“独坐”“弹琴”“长啸”三个动作写人的活动，“幽篁”点出环境之幽深，琴声与啸声在竹林中回荡，雅趣自生。后两句“深林人不知，明月来相照”以“人不知”与“月来照”相对：无人知晓本有孤寂之意，而明月来照则化孤寂为自得。诗人运用拟人手法，把明月写成知音，人与月相伴，物我交融，营造出清幽、宁静、高雅的意境，表现诗人宁静淡泊、超然物外的心境"},{"type":"list","title":"中考考点","items":["“幽篁”“长啸”“相照”等词释义","“明月来相照”的拟人手法及其表达效果","以声衬静、动静相衬的写法","诗歌所表现的诗人的闲适心境与高雅情趣，以及与《山居秋暝》一类山水田园诗风格的比较。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"独坐幽篁里，弹琴复长啸。","n":"","cn":"我独自坐在幽深的竹林里，一边弹琴，一边又发出长长的啸声。","parts":[{"t":"独坐"},{"t":"幽篁","k":2},{"t":"里，弹琴复长"},{"t":"啸","k":5},{"t":"。"}]},{"t":"深林人不知，明月来相照。","n":"","cn":"深林中没有别人知道我在这里，只有天上的明月来照耀我。","parts":[{"t":"深林","k":3},{"t":"人不知，明月来"},{"t":"相照","k":4},{"t":"。"}]}],"words":[{"w":"照耀我","e":"【易错】“明月来相照”的“相照”是“照耀我”，不写“相照看”。"},{"w":"相照看","e":"【易错】“明月来相照”的“相照”是“照耀我”，不写“相照看”。"},{"w":"幽篁","e":"幽深的竹林"},{"w":"深林","e":"这里指竹林深处"},{"w":"相照","e":"照耀我"},{"w":"啸","e":"撮口发出长而清脆的声音"},{"w":"篁","e":"【易错】“独坐幽篁里”的“篁”是竹字头，指竹林，不写“皇”或“凰”。"},{"w":"皇","e":"【易错】“独坐幽篁里”的“篁”是竹字头，指竹林，不写“皇”或“凰”。"},{"w":"凰","e":"【易错】“独坐幽篁里”的“篁”是竹字头，指竹林，不写“皇”或“凰”。"},{"w":"萧","e":"【易错】“弹琴复长啸”的“啸”是口字旁，不写“萧”。"}]},{"type":"list","title":"名句","items":["深林人不知，明月来相照。"]},{"type":"list","title":"背诵提示","items":["“独坐幽篁里”的“篁”是竹字头，指竹林，不写“皇”或“凰”。","“弹琴复长啸”的“啸”是口字旁，不写“萧”。","“明月来相照”的“相照”是“照耀我”，不写“相照看”。"]}],"questions":[{"id":"p-p7b-zhu-li-guan-m0","type":"fill","stem":"默写填空：深林人不知，______。","answer":"明月来相照。","explain":"出自《竹里馆》（唐·王维）：深林人不知，明月来相照。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-zhu-li-guan-u","type":"fill","stem":"理解性默写：我独自坐在幽深的竹林里，一边弹琴，一边又发出长长的啸声。","answer":"独坐幽篁里，弹琴复长啸。","explain":"出自《竹里馆》（唐·王维）。句意：我独自坐在幽深的竹林里，一边弹琴，一边又发出长长的啸声。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-chun-ye-luo-cheng-wen-di","title":"春夜洛城闻笛","subtitle":"唐·李白","grade":"7b","tags":["思乡","写景","音乐"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李白"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李白（701—762），字太白，号青莲居士，唐代伟大的浪漫主义诗人，被后人尊称为“诗仙”，与杜甫并称“李杜”，是我国古典诗歌浪漫主义传统的杰出代表。\n生平经历：少年时博览群书、喜好剑术任侠；二十五岁“仗剑去国”出蜀漫游，足迹遍及大江南北；天宝元年奉诏入长安供奉翰林，因遭权贵谗毁仅三年便离京；安史之乱中因参与永王李璘幕府获罪被流放夜郎，途中遇赦东归，晚年漂泊，762年病逝于当涂。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗写诗人客居洛阳时春夜闻笛而生乡思。首句“谁家玉笛暗飞声”以问句起笔，“暗”字写笛声不知从何处传来，凭空而至，也暗示夜色之深；“飞”字写笛声轻盈飘荡。次句“散入春风满洛城”用“散”“满”二字，写笛声随风扩散、充盈全城，以夸张手法极写笛声之悠远，也以声写春夜的静谧。第三句由声入情，所闻之曲是《折杨柳》，此曲本寓离别之意，自然触发乡愁。末句以反问收束，“何人不起”三字把一己乡思推及所有游子，情味深长"},{"type":"list","title":"中考考点","items":["“暗”“飞”“散”“满”等词的表达效果与夸张手法","“折柳”的文化含义（古人折柳送别的习俗）","由听觉描写转为抒情及全诗思乡主旨的名句默写。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"谁家玉笛暗飞声，散入春风满洛城。","n":"","cn":"是谁家的玉笛在暗中飞出悠扬的笛声？它随着春风飘散，传遍了整个洛阳城。","parts":[{"t":"谁家玉"},{"t":"笛","k":5},{"t":"暗飞声","k":0},{"t":"，散入春风满"},{"t":"洛城","k":2},{"t":"。"}]},{"t":"此夜曲中闻折柳，何人不起故园情。","n":"","cn":"在这客居的夜晚，听到曲中有《折杨柳》，哪一个游子能不生出思念家乡的感情呢？折柳：指《折杨柳》曲，古人折柳送别","parts":[{"t":"此夜曲中闻"},{"t":"折","k":9},{"t":"柳，何人不起"},{"t":"故园情","k":1},{"t":"。"}]}],"words":[{"w":"暗飞声","e":"笛声在暗中飞出"},{"w":"故园情","e":"思念家乡的情感"},{"w":"洛城","e":"洛阳城"},{"w":"故园","e":"【易错】“何人不起故园情”的“故园”不写“故圆”。"},{"w":"故圆","e":"【易错】“何人不起故园情”的“故园”不写“故圆”。"},{"w":"笛","e":"【易错】“谁家玉笛暗飞声”的“笛”是竹字头，不写“迪”。"},{"w":"迪","e":"【易错】“谁家玉笛暗飞声”的“笛”是竹字头，不写“迪”。"},{"w":"洛","e":"【易错】“散入春风满洛城”的“洛”是三点水，不写“落”。"},{"w":"落","e":"【易错】“散入春风满洛城”的“洛”是三点水，不写“落”。"},{"w":"折","e":"【易错】“此夜曲中闻折柳”的“折”是提手旁，不写“拆”。"},{"w":"拆","e":"【易错】“此夜曲中闻折柳”的“折”是提手旁，不写“拆”。"}]},{"type":"list","title":"名句","items":["此夜曲中闻折柳，何人不起故园情。"]},{"type":"list","title":"背诵提示","items":["“谁家玉笛暗飞声”的“笛”是竹字头，不写“迪”。","“散入春风满洛城”的“洛”是三点水，不写“落”。","“此夜曲中闻折柳”的“折”是提手旁，不写“拆”。","“何人不起故园情”的“故园”不写“故圆”。"]}],"questions":[{"id":"p-p7b-chun-ye-luo-cheng-wen-di-m0","type":"fill","stem":"默写填空：此夜曲中闻折柳，______。","answer":"何人不起故园情。","explain":"出自《春夜洛城闻笛》（唐·李白）：此夜曲中闻折柳，何人不起故园情。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-chun-ye-luo-cheng-wen-di-u","type":"fill","stem":"理解性默写：是谁家的玉笛在暗中飞出悠扬的笛声？它随着春风飘散，传遍了整个洛阳城。","answer":"谁家玉笛暗飞声，散入春风满洛城。","explain":"出自《春夜洛城闻笛》（唐·李白）。句意：是谁家的玉笛在暗中飞出悠扬的笛声？它随着春风飘散，传遍了整个洛阳城。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-feng-ru-jing-shi","title":"逢入京使","subtitle":"唐·岑参","grade":"7b","tags":["思乡","边塞","叙事"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·岑参"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"岑参（约715—770），荆州江陵（今湖北江陵）人，唐代边塞诗派代表诗人。他与高适并称“高岑”，因官至嘉州刺史，世称“岑嘉州”。\n生平经历：天宝年间中进士，曾两次出塞，先后在安西节度使高仙芝、封常清幕府中任职，长年往来于轮台、雪海之间；安史之乱后回朝任右补阙等职，后出任嘉州刺史，罢官后客死成都。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗写诗人赴安西途中与入京使者在马上相逢的情景。前两句写思乡之情：“故园东望”点明方向，“路漫漫”写距离之遥，归期难料；“双袖龙钟泪不干”以细节刻画，用袖子拭泪而泪仍不干，把思乡之切写得真切动人，虽夸张而不失真实。后两句写相逢的仓促与无可奈何：“马上相逢无纸笔”写出行旅匆匆，一个“马上”点出情境；“凭君传语报平安”以“传语”代替家书，语浅情深。全诗不事雕琢，于平易处见深情，既写思乡念亲之柔情，又含有诗人赴边报国的豪迈气概"},{"type":"list","title":"中考考点","items":["“漫漫”“龙钟”“凭”“传语”等词释义","细节描写与夸张手法的表达效果","“凭君传语报平安”一句所表现的复杂情感（思乡与报国的统一）","名句默写。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"故园东望路漫漫，双袖龙钟泪不干。","n":"","cn":"回头东望故乡，路途遥远漫长；两只袖子已经被泪水沾湿，泪水还止不住地流。","parts":[{"t":"故园","k":0},{"t":"东望路"},{"t":"漫漫","k":1},{"t":"，双袖"},{"t":"龙钟","k":2},{"t":"泪不干。"}]},{"t":"马上相逢无纸笔，凭君传语报平安。","n":"","cn":"在马上与你相遇，没有纸笔写信，只好托你带个口信，向家人报个平安。","parts":[{"t":"马上相逢无纸笔，"},{"t":"凭","k":7},{"t":"君"},{"t":"传语","k":3},{"t":"报"},{"t":"平","k":8},{"t":"安。"}]}],"words":[{"w":"故园","e":"指长安的家"},{"w":"漫漫","e":"路途遥远的样子"},{"w":"龙钟","e":"沾湿的样子"},{"w":"传语","e":"捎口信"},{"w":"慢慢","e":"【易错】“故园东望路漫漫”的“漫漫”是三点水，不写“慢慢”。"},{"w":"胧肿","e":"【易错】“双袖龙钟泪不干”的“龙钟”指沾湿，不写“胧肿”。"},{"w":"传话","e":"【易错】“凭君传语报平安”的“凭”是几字底，不写“平”；“传语”不写“传话”。"},{"w":"凭","e":"请求，烦劳"},{"w":"平","e":"【易错】“凭君传语报平安”的“凭”是几字底，不写“平”；“传语”不写“传话”。"}]},{"type":"list","title":"名句","items":["马上相逢无纸笔，凭君传语报平安。"]},{"type":"list","title":"背诵提示","items":["“故园东望路漫漫”的“漫漫”是三点水，不写“慢慢”。","“双袖龙钟泪不干”的“龙钟”指沾湿，不写“胧肿”。","“凭君传语报平安”的“凭”是几字底，不写“平”；“传语”不写“传话”。"]}],"questions":[{"id":"p-p7b-feng-ru-jing-shi-m0","type":"fill","stem":"默写填空：马上相逢无纸笔，______。","answer":"凭君传语报平安。","explain":"出自《逢入京使》（唐·岑参）：马上相逢无纸笔，凭君传语报平安。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-feng-ru-jing-shi-u","type":"fill","stem":"理解性默写：回头东望故乡，路途遥远漫长；两只袖子已经被泪水沾湿，泪水还止不住地流。","answer":"故园东望路漫漫，双袖龙钟泪不干。","explain":"出自《逢入京使》（唐·岑参）。句意：回头东望故乡，路途遥远漫长；两只袖子已经被泪水沾湿，泪水还止不住地流。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-wan-chun","title":"晚春","subtitle":"唐·韩愈","grade":"7b","tags":["写景","春景","拟人"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·韩愈"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"韩愈（768—824），字退之，河南河阳（今河南孟州）人，因祖籍昌黎而世称韩昌黎，又因谥号为“文”而称韩文公，唐代文学家、思想家、教育家。\n生平经历：他幼年丧父，由兄嫂抚养成人，读书极为刻苦，二十五岁考中进士；任监察御史时因上疏言事被贬为阳山令，后来因上《论佛骨表》触怒宪宗，被贬为潮州刺史，仕途几度沉浮；他一生以复兴儒学为己任，反对六朝以来浮华空疏的骈文，提倡写内容充实、文从字顺的散文。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗写暮春景色，立意新颖，充满谐趣。前两句用拟人手法，说草树“知”春将归，于是“百般红紫斗芳菲”，一个“斗”字把花草争艳的情态写得生动活泼，仿佛它们在为春天做最后的努力。后两句写杨花、榆荚：“无才思”是调侃之语，说它们不能开出艳丽的花朵，只知如雪般漫天飞舞。这既是暮春实景，也可看作诗人的自嘲或对平凡者的调侃，于戏谑中见情趣。全诗一反惜春伤感之常调，而以积极、幽默的态度看待春去，别具一格"},{"type":"list","title":"中考考点","items":["“斗”“惟解”等词的赏析与拟人手法","“杨花榆荚”的形象及其寓意（不同的理解：嘲讽无才者、或赞其尽力而为）","诗歌景物描写的层次与“珍惜春光、积极进取”的启示。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"草树知春不久归，百般红紫斗芳菲。","n":"","cn":"花草树木知道春天不久就要归去，于是万紫千红，争芳斗艳。","parts":[{"t":"草树知春"},{"t":"不久归","k":1},{"t":"，"},{"t":"百般红紫","k":0},{"t":"斗芳菲","k":2},{"t":"。"}]},{"t":"杨花榆荚无才思，惟解漫天作雪飞。","n":"","cn":"只有那杨花和榆荚没有才思，只知道像雪花一样漫天飞舞。","parts":[{"t":"杨花"},{"t":"榆荚","k":4},{"t":"无才思","k":3},{"t":"，"},{"t":"惟解","k":5},{"t":"漫天","k":9},{"t":"作雪飞。"}]}],"words":[{"w":"百般红紫","e":"形容万紫千红"},{"w":"不久归","e":"即将结束"},{"w":"斗芳菲","e":"争芳斗艳"},{"w":"无才思","e":"是调侃之语"},{"w":"榆荚","e":"榆树的果实，俗称榆钱"},{"w":"惟解","e":"只知道"},{"w":"芳菲","e":"【易错】“百般红紫斗芳菲”的“芳菲”是草字头，不写“芳非”。"},{"w":"芳非","e":"【易错】“百般红紫斗芳菲”的“芳菲”是草字头，不写“芳非”。"},{"w":"唯解","e":"【易错】“惟解漫天作雪飞”教材作“惟解”，不写“唯解”；“漫天”不写“慢天”。"},{"w":"漫天","e":"【易错】“惟解漫天作雪飞”教材作“惟解”，不写“唯解”；“漫天”不写“慢天”。"},{"w":"慢天","e":"【易错】“惟解漫天作雪飞”教材作“惟解”，不写“唯解”；“漫天”不写“慢天”。"},{"w":"荚","e":"【易错】“杨花榆荚无才思”的“榆荚”的“荚”是草字头，不写“夹”。"},{"w":"夹","e":"【易错】“杨花榆荚无才思”的“榆荚”的“荚”是草字头，不写“夹”。"}]},{"type":"list","title":"名句","items":["草树知春不久归，百般红紫斗芳菲。"]},{"type":"list","title":"背诵提示","items":["“百般红紫斗芳菲”的“芳菲”是草字头，不写“芳非”。","“杨花榆荚无才思”的“榆荚”的“荚”是草字头，不写“夹”。","“惟解漫天作雪飞”教材作“惟解”，不写“唯解”；“漫天”不写“慢天”。"]}],"questions":[{"id":"p-p7b-wan-chun-m0","type":"fill","stem":"默写填空：草树知春不久归，______。","answer":"百般红紫斗芳菲。","explain":"出自《晚春》（唐·韩愈）：草树知春不久归，百般红紫斗芳菲。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-wan-chun-u","type":"fill","stem":"理解性默写：花草树木知道春天不久就要归去，于是万紫千红，争芳斗艳。","answer":"草树知春不久归，百般红紫斗芳菲。","explain":"出自《晚春》（唐·韩愈）。句意：花草树木知道春天不久就要归去，于是万紫千红，争芳斗艳。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-bo-qin-huai","title":"泊秦淮","subtitle":"唐·杜牧","grade":"7b","tags":["怀古","忧国","写景"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·杜牧"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"杜牧（803—约852），字牧之，号樊川居士，京兆万年（今陕西西安）人，晚唐诗人，与李商隐并称“小李杜”；因晚年居樊川别墅，后人又称他“杜樊川”。\n生平经历：他出身名门，祖父杜佑曾任宰相；少年时便有济世之志，喜好谈兵论政，曾为《孙子》作注；二十六岁考中进士，此后长期在朝廷与地方任职，曾任黄州、池州、睦州刺史；晚年回到长安，官至中书舍人，居樊川别墅而终。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗写诗人夜泊秦淮的所见所感。首句两个“笼”字连用，把烟、水、月、沙四种景物融为一体，绘出朦胧清冷的秦淮夜景，暗含诗人内心的忧思；次句叙事点题，交代地点与时间，也为下文听歌作铺垫。后两句由景入情、由听歌而生感慨：“不知”二字是反语，表面责怪歌女，实则讽刺那些醉生梦死、沉溺声色的晚唐统治者；“犹唱”二字更揭出历史的沉痛：陈朝因此而亡，今日又唱此曲，亡国之忧尽在其中。全诗借古讽今，含蓄深沉"},{"type":"list","title":"中考考点","items":["“笼”“犹唱”“后庭花”的含义与借古讽今手法","“两个‘笼’字”写景的妙处","“商女不知亡国恨”的讽刺对象与借古讽今的写法","诗歌表现的忧国忧民之情及名句默写。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"烟笼寒水月笼沙，夜泊秦淮近酒家。","n":"","cn":"轻烟笼罩着寒凉的江水，月光笼罩着岸边的白沙；夜晚我停船在秦淮河上，靠近岸边的酒家。","parts":[{"t":"烟"},{"t":"笼","k":4},{"t":"寒水月"},{"t":"笼","k":4},{"t":"沙，夜"},{"t":"泊","k":5},{"t":"秦淮","k":2},{"t":"近酒家。"}]},{"t":"商女不知亡国恨，隔江犹唱后庭花。","n":"","cn":"卖唱的歌女不懂得亡国的悲恨，还隔着江水唱着《玉树后庭花》这支亡国之音。","parts":[{"t":"商女","k":3},{"t":"不知亡国恨，隔江犹唱"},{"t":"后庭花","k":0},{"t":"。"}]}],"words":[{"w":"后庭花","e":"即《玉树后庭花》，南朝陈后主所作，后人称其为亡国之音"},{"w":"后亭花","e":"【易错】“商女”指卖唱的歌女，不写“商女”以外的字；“后庭花”不写“后亭花”。"},{"w":"秦淮","e":"秦淮河，流经南京"},{"w":"商女","e":"卖唱的歌女"},{"w":"笼","e":"笼罩"},{"w":"泊","e":"停泊"},{"w":"淮","e":"【易错】“夜泊秦淮近酒家”的“泊”是三点水，读 bó；“淮”是三点水，不写“准”。"},{"w":"准","e":"【易错】“夜泊秦淮近酒家”的“泊”是三点水，读 bó；“淮”是三点水，不写“准”。"}]},{"type":"list","title":"名句","items":["商女不知亡国恨，隔江犹唱后庭花。"]},{"type":"list","title":"背诵提示","items":["“烟笼寒水月笼沙”两个“笼”字不能漏写一个。","“夜泊秦淮近酒家”的“泊”是三点水，读 bó；“淮”是三点水，不写“准”。","“商女”指卖唱的歌女，不写“商女”以外的字；“后庭花”不写“后亭花”。"]}],"questions":[{"id":"p-p7b-bo-qin-huai-m0","type":"fill","stem":"默写填空：商女不知亡国恨，______。","answer":"隔江犹唱后庭花。","explain":"出自《泊秦淮》（唐·杜牧）：商女不知亡国恨，隔江犹唱后庭花。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-bo-qin-huai-u","type":"fill","stem":"理解性默写：轻烟笼罩着寒凉的江水，月光笼罩着岸边的白沙；夜晚我停船在秦淮河上，靠近岸边的酒家。","answer":"烟笼寒水月笼沙，夜泊秦淮近酒家。","explain":"出自《泊秦淮》（唐·杜牧）。句意：轻烟笼罩着寒凉的江水，月光笼罩着岸边的白沙；夜晚我停船在秦淮河上，靠近岸边的酒家。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-jia-sheng","title":"贾生","subtitle":"唐·李商隐","grade":"7b","tags":["咏史","讽刺","怀古"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李商隐"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李商隐（约813—约858），字义山，号玉谿生，又号樊南生，怀州河内（今河南沁阳）人，晚唐诗人，与杜牧并称“小李杜”。\n生平经历：他少年时得到天平军节度使令狐楚的赏识，二十五岁考中进士；后来入泾原节度使王茂元幕府并成为其女婿，因而卷入牛李党争，被两方猜忌，一生只做过校书郎、县尉一类小官，长期辗转于各地幕府；妻子去世后他更加郁郁寡欢，四十余岁便在郑州病逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是一首咏史讽时之作。前两句以“求贤”“访逐臣”和“才调更无伦”写汉文帝的求贤姿态与贾谊的出众才华，先扬一笔，为下文转折蓄势。后两句一转而下：“可怜”二字直抒作者的惋惜与讽刺；“虚前席”写文帝深夜移席倾听似极重视，所问竟是鬼神之事而非“苍生”，一“虚”字点出召见徒劳无用。诗人借汉文帝与贾谊的旧事，讽刺晚唐统治者迷信鬼神、不关心民生、不重视人才的现实，借古讽今，也寓含自己怀才不遇之感"},{"type":"list","title":"中考考点","items":["“宣室”“逐臣”“才调”“可怜”“虚”“苍生”等词释义","欲抑先扬（先扬后抑）的写法与“虚”字的表达效果","诗歌借古讽今的写法与讽刺对象","对统治者不重人才、不恤民生的不满及诗人自身的感慨。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"宣室求贤访逐臣，贾生才调更无伦。","n":"","cn":"汉文帝在宣室寻求贤才，征召被放逐的臣子贾谊；贾谊的才华更是无人能比。","parts":[{"t":"宣室","k":1},{"t":"求贤访"},{"t":"逐臣","k":2},{"t":"，贾生"},{"t":"才调","k":3},{"t":"更"},{"t":"无伦","k":4},{"t":"。"}]},{"t":"可怜夜半虚前席，不问苍生问鬼神。","n":"","cn":"可惜半夜里白白地挪动身子靠近他，皇上问的不是国计民生，而是鬼神之事。","parts":[{"t":"可怜","k":5},{"t":"夜半"},{"t":"虚","k":12},{"t":"前席","k":6},{"t":"，不问"},{"t":"苍生","k":7},{"t":"问鬼神。"}]}],"words":[{"w":"无人能比","e":"【易错】“贾生才调更无伦”的“调”读 diào；“无伦”是“无人能比”，不写“无论”。"},{"w":"宣室","e":"汉代未央宫前殿正室"},{"w":"逐臣","e":"被放逐的臣子，指贾谊"},{"w":"才调","e":"才华"},{"w":"无伦","e":"无人能比"},{"w":"可怜","e":"可惜"},{"w":"前席","e":"把坐席往前移，表示听得入神"},{"w":"苍生","e":"百姓"},{"w":"宣事","e":"【易错】“宣室求贤访逐臣”的“宣室”不写“宣事”；“逐臣”不写“遂臣”。"},{"w":"遂臣","e":"【易错】“宣室求贤访逐臣”的“宣室”不写“宣事”；“逐臣”不写“遂臣”。"},{"w":"无论","e":"【易错】“贾生才调更无伦”的“调”读 diào；“无伦”是“无人能比”，不写“无论”。"},{"w":"仓生","e":"【易错】“不问苍生问鬼神”的“苍生”指百姓，不写“仓生”。"},{"w":"虚","e":"徒然、白白地"},{"w":"调","e":"【易错】“贾生才调更无伦”的“调”读 diào；“无伦”是“无人能比”，不写“无论”。"},{"w":"需","e":"【易错】“可怜夜半虚前席”的“虚”是“徒然、白白地”，不写“需”。"}]},{"type":"list","title":"名句","items":["可怜夜半虚前席，不问苍生问鬼神。"]},{"type":"list","title":"背诵提示","items":["“宣室求贤访逐臣”的“宣室”不写“宣事”；“逐臣”不写“遂臣”。","“贾生才调更无伦”的“调”读 diào；“无伦”是“无人能比”，不写“无论”。","“可怜夜半虚前席”的“虚”是“徒然、白白地”，不写“需”。","“不问苍生问鬼神”的“苍生”指百姓，不写“仓生”。"]}],"questions":[{"id":"p-p7b-jia-sheng-m0","type":"fill","stem":"默写填空：可怜夜半虚前席，______。","answer":"不问苍生问鬼神。","explain":"出自《贾生》（唐·李商隐）：可怜夜半虚前席，不问苍生问鬼神。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-jia-sheng-u","type":"fill","stem":"理解性默写：汉文帝在宣室寻求贤才，征召被放逐的臣子贾谊；贾谊的才华更是无人能比。","answer":"宣室求贤访逐臣，贾生才调更无伦。","explain":"出自《贾生》（唐·李商隐）。句意：汉文帝在宣室寻求贤才，征召被放逐的臣子贾谊；贾谊的才华更是无人能比。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-sun-quan-quan-xue","title":"孙权劝学","subtitle":"宋·司马光","grade":"7b","tags":["文言文","学习","对话描写"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·司马光"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"司马光（1019—1086），字君实，号迂叟，陕州夏县（今山西夏县）涑水乡人，世称涑水先生，北宋史学家、政治家；他历仕仁宗、英宗、神宗、哲宗四朝，官至尚书左仆射兼门下侍郎，死后赠太师、温国公，谥文正，故又称司马温公。\n生平经历：他自幼好学，七岁时同伴落水，他持石击瓮救人，这就是“司马光砸缸”的故事，见于《宋史》本传；宝元元年（1038）中进士；因反对王安石变法，他自请离京，在洛阳闲居十五年，专心主持编修史书；元丰八年（1085）神宗去世后被召还朝，次年病逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文选自《资治通鉴》，写孙权劝吕蒙学习、吕蒙学有所成的故事。文章按“劝学—就学—论议—结友”展开，脉络清晰。写法上以对话推动情节、塑造人物：孙权先指出“不可不学”，再以“孤岂欲卿治经为博士邪”打消顾虑，又现身说法“卿言多务，孰若孤”，言辞恳切；吕蒙由“辞以军中多务”到“乃始就学”，知错能改；鲁肃的“大惊”“结友”则侧面烘托吕蒙进步之大"},{"type":"list","title":"中考考点","items":["“谓”“当涂”“辞”“涉猎”“及”“非复”“遂”等词释义","“孤”“卿”等称谓语的含义","人物形象分析与对话描写的作用","开卷有益、学能长才的主旨及“士别三日，当刮目相待”的启示。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"初，权谓吕蒙曰：“卿今当涂掌事，不可不学！”蒙辞以军中多务。","n":"","cn":"当初，孙权对吕蒙说：“你现在当权管事了，不可不学习！”吕蒙用军中事务繁多来推辞。","parts":[{"t":"初","k":17},{"t":"，权"},{"t":"谓","k":18},{"t":"吕蒙曰：“"},{"t":"卿","k":19},{"t":"今"},{"t":"当涂","k":6},{"t":"掌事，不可不学！”蒙"},{"t":"辞以军中多务","k":0},{"t":"。"}]},{"t":"权曰：“孤岂欲卿治经为博士邪！但当涉猎，见往事耳。”","n":"孙权说：“我难道想要你研究儒家经典成为专掌经学传授的学官吗！只是应当粗略地阅读，了解历史罢了。”孤：古时王侯的自称；治经：研究儒家经典；博士：专掌经学传授的学官；涉猎：粗略地阅读；见往事：了解历史。","cn":"","parts":[{"t":"权曰：“孤岂欲"},{"t":"卿","k":19},{"t":"治经","k":7},{"t":"为"},{"t":"博士","k":8},{"t":"邪","k":28},{"t":"！但当"},{"t":"涉猎","k":9},{"t":"，"},{"t":"见往事","k":3},{"t":"耳。”"}]},{"t":"“卿言多务，孰若孤？孤常读书，自以为大有所益。”","n":"","cn":"“你说事务多，比起我来怎么样？我经常读书，自认为大有益处。”孰若：与……相比怎么样","parts":[{"t":"“"},{"t":"卿","k":19},{"t":"言多务，"},{"t":"孰若孤","k":5},{"t":"？孤常读书，自"},{"t":"以为","k":10},{"t":"大有所益。”"}]},{"t":"蒙乃始就学。及鲁肃过寻阳，与蒙论议，大惊曰：“卿今者才略，非复吴下阿蒙！”","n":"","cn":"吕蒙于是开始学习。等到鲁肃经过寻阳，与吕蒙议论事情，十分吃惊地说：“你现在的才干谋略，不再是过去那个吴县的阿蒙了！”乃：于是","parts":[{"t":"蒙乃始就学。"},{"t":"及","k":20},{"t":"鲁肃"},{"t":"过","k":21},{"t":"寻阳，与蒙论议，大惊曰：“"},{"t":"卿","k":19},{"t":"今者才略，"},{"t":"非复","k":11},{"t":"吴下阿蒙！”"}]},{"t":"蒙曰：“士别三日，即更刮目相待，大兄何见事之晚乎！”","n":"吕蒙说：“士别三日，就要用新的眼光看待，长兄你认清事物怎么这么晚呢！”士别三日：指读书人分别几天；即更：就要重新；刮目相待：擦拭眼睛，用新的眼光看待；见事：认清事物。","cn":"","parts":[{"t":"蒙曰：“士别三日，"},{"t":"即更","k":12},{"t":"刮目相待","k":1},{"t":"，大兄何"},{"t":"见事","k":13},{"t":"之晚乎！”"}]},{"t":"肃遂拜蒙母，结友而别。","n":"","cn":"鲁肃于是拜见了吕蒙的母亲，与吕蒙结为朋友后告别。","parts":[{"t":"肃"},{"t":"遂","k":22},{"t":"拜","k":23},{"t":"蒙母，"},{"t":"结友","k":14},{"t":"而别。"}]}],"words":[{"w":"辞以军中多务","e":"用军中事务多来推托"},{"w":"刮目相待","e":"擦拭眼睛，用新的眼光看待"},{"w":"孙权说","e":"“我难道想要你研究儒家经典成为专掌经学传授的学官吗！只是应当粗略地阅读，了解历史罢了"},{"w":"见往事","e":"了解历史"},{"w":"吕蒙说","e":"“士别三日，就要用新的眼光看待，长兄你认清事物怎么这么晚呢！”士别三日：指读书人分别几天"},{"w":"孰若孤","e":"【易错】“孰若孤”的“孰”是“谁、哪个”的意思，不写“熟”。"},{"w":"当涂","e":"当道，当权"},{"w":"治经","e":"研究儒家经典"},{"w":"博士","e":"专掌经学传授的学官"},{"w":"涉猎","e":"粗略地阅读"},{"w":"以为","e":"认为"},{"w":"非复","e":"不再是"},{"w":"即更","e":"就要重新"},{"w":"见事","e":"认清事物"},{"w":"结友","e":"结为朋友"},{"w":"刮目","e":"【易错】“即更刮目相待”的“更”读 gēng，意为重新；“刮目”不写“聒目”。"},{"w":"聒目","e":"【易错】“即更刮目相待”的“更”读 gēng，意为重新；“刮目”不写“聒目”。"},{"w":"初","e":"当初"},{"w":"谓","e":"对……说"},{"w":"卿","e":"古代君对臣的爱称"},{"w":"及","e":"到了……的时候"},{"w":"过","e":"经过"},{"w":"遂","e":"于是"},{"w":"拜","e":"拜见"},{"w":"卯","e":"【易错】“卿今当涂掌事”的“卿”是“卯”旁，不写“聊”。"},{"w":"聊","e":"【易错】“卿今当涂掌事”的“卿”是“卯”旁，不写“聊”。"},{"w":"辞","e":"【易错】“蒙辞以军中多务”的“辞”是推托，不写“词”。"},{"w":"词","e":"【易错】“蒙辞以军中多务”的“辞”是推托，不写“词”。"},{"w":"邪","e":"【易错】“孤岂欲卿治经为博士邪”的“邪”同“耶”，读 yé，表反问。"},{"w":"耶","e":"【易错】“孤岂欲卿治经为博士邪”的“邪”同“耶”，读 yé，表反问。"},{"w":"涉","e":"【易错】“但当涉猎，见往事耳”的“涉”是三点水，不写“陟”。"},{"w":"陟","e":"【易错】“但当涉猎，见往事耳”的“涉”是三点水，不写“陟”。"},{"w":"孰","e":"【易错】“孰若孤”的“孰”是“谁、哪个”的意思，不写“熟”。"},{"w":"熟","e":"【易错】“孰若孤”的“孰”是“谁、哪个”的意思，不写“熟”。"},{"w":"更","e":"【易错】“即更刮目相待”的“更”读 gēng，意为重新；“刮目”不写“聒目”。"}]},{"type":"h","text":"译文"},{"type":"p","text":"当初，孙权对吕蒙说：“你现在当权管事，不可以不学习！”吕蒙用军中事务繁多为借口推辞。孙权说：“我难道要你研究儒家经典去做博士吗？只是应当粗略地阅读，了解历史罢了。你说事务多，谁比得上我呢？我常常读书，自认为大有好处。”吕蒙于是开始学习。等到鲁肃经过寻阳，与吕蒙议论，大为吃惊地说：“你如今的才干谋略，已不再是当年吴县的阿蒙了！”吕蒙说：“读书人分别几天，就该用新眼光看待，大哥认清事物怎么这样晚呢！”鲁肃于是拜见吕蒙的母亲，与吕蒙结为好友才告别。"},{"type":"list","title":"名句","items":["士别三日，即更刮目相待。"]},{"type":"list","title":"背诵提示","items":["“卿今当涂掌事”的“卿”是“卯”旁，不写“聊”。","“蒙辞以军中多务”的“辞”是推托，不写“词”。","“孤岂欲卿治经为博士邪”的“邪”同“耶”，读 yé，表反问。","“但当涉猎，见往事耳”的“涉”是三点水，不写“陟”。","“孰若孤”的“孰”是“谁、哪个”的意思，不写“熟”。","“即更刮目相待”的“更”读 gēng，意为重新；“刮目”不写“聒目”。"]}],"questions":[{"id":"p-p7b-sun-quan-quan-xue-m0","type":"fill","stem":"默写填空：士别三日，______。","answer":"即更刮目相待。","explain":"出自《孙权劝学》（宋·司马光）：士别三日，即更刮目相待。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-sun-quan-quan-xue-u","type":"fill","stem":"理解性默写：当初，孙权对吕蒙说：你现在当权管事了，不可不学习！吕蒙用军中事务繁多来推辞。","answer":"初，权谓吕蒙曰：“卿今当涂掌事，不可不学！”蒙辞以军中多务。","explain":"出自《孙权劝学》（宋·司马光）。句意：当初，孙权对吕蒙说：“你现在当权管事了，不可不学习！”吕蒙用军中事务繁多来推辞。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-mai-you-weng","title":"卖油翁","subtitle":"宋·欧阳修","grade":"7b","tags":["文言文","说理","人物描写"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·欧阳修"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"欧阳修（1007—1072），字永叔，号醉翁，晚年又号六一居士，吉州永丰（今江西永丰）人，北宋文学家、史学家、政治家，谥号“文忠”。\n生平经历：他四岁丧父，家境贫寒，母亲郑氏以芦荻画地教他识字，“画荻教子”传为佳话；天圣八年考中进士，为官刚直敢言，因支持范仲淹新政而屡遭贬谪，先后任滁州、扬州、颍州等地知州；晚年官至参知政事，主持编修《新唐书》，并独自撰写《新五代史》。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文选自欧阳修《归田录》，是一篇寓理于事的短文。文章以“自矜”的陈尧咨与卖油翁构成对比：陈尧咨因“十中八九”而“自矜”，卖油翁却“但微颔之”；陈尧咨“忿然”责问，卖油翁则以“酌油”的实际演示作答。文中“睨之”“微颔”“徐以杓酌油沥之”等细节描写极为传神。全文以“无他，但手熟尔”点明主旨：熟能生巧，技艺再高也不过是勤练的结果，因而不能恃技自矜、骄傲自满"},{"type":"list","title":"中考考点","items":["“矜”“睨”“颔”“忿然”“安”“轻”“酌”“覆”“徐”“遣”等词释义","“尔”同“耳”、“杓”同“勺”的通假字","细节描写与对比手法的作用","“熟能生巧，不可骄傲自满”的寓意及人物形象分析。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"陈康肃公善射，当世无双，公亦以此自矜。","n":"","cn":"陈尧咨善于射箭，世上没有第二个人能跟他相媲美，他也因此自夸。","parts":[{"t":"陈康肃公","k":2},{"t":"善射","k":6},{"t":"，当世无双，公亦以此"},{"t":"自矜","k":7},{"t":"。"}]},{"t":"尝射于家圃，有卖油翁释担而立，睨之久而不去。","n":"","cn":"他曾在自家的园子里射箭，有个卖油的老翁放下担子站在一旁，斜着眼睛看他射箭，很久也不离开。","parts":[{"t":"尝射于"},{"t":"家圃","k":8},{"t":"，有卖油翁"},{"t":"释担而立","k":3},{"t":"，"},{"t":"睨","k":15},{"t":"之久而不"},{"t":"去","k":16},{"t":"。"}]},{"t":"见其发矢十中八九，但微颔之。","n":"","cn":"老翁看他射出的箭十支能中八九支，只是微微地点头。","parts":[{"t":"见其"},{"t":"发矢","k":10},{"t":"十中八九，"},{"t":"但微颔之","k":4},{"t":"。"}]},{"t":"康肃问曰：“汝亦知射乎？吾射不亦精乎？”","n":"陈尧咨问道：“你也懂得射箭吗？我的射箭技艺不也是很精湛吗？”汝：你；精：精湛。","cn":"","parts":[{"t":"康肃问曰：“汝亦知射乎？吾射不亦"},{"t":"精","k":18},{"t":"乎？”"}]},{"t":"翁曰：“无他，但手熟尔。”","n":"老翁说：“没有别的（奥妙），只不过手熟罢了。”无他：没有别的奥妙；尔：同“耳”，罢了。","cn":"","parts":[{"t":"翁曰：“无他，但手熟"},{"t":"尔","k":19},{"t":"。”"}]},{"t":"康肃忿然曰：“尔安敢轻吾射！”","n":"陈尧咨气愤地说：“你怎么敢轻视我的射箭本领！”忿然：气愤的样子；安：怎么；轻：轻视。","cn":"","parts":[{"t":"康肃忿然曰：“"},{"t":"尔","k":19},{"t":"安","k":20},{"t":"敢"},{"t":"轻","k":21},{"t":"吾射！”"}]},{"t":"翁曰：“以我酌油知之。”乃取一葫芦置于地，以钱覆其口，徐以杓酌油沥之，自钱孔入，而钱不湿。","n":"老翁说：“凭我倒油的经验知道这个道理。”于是拿出一个葫芦放在地上，用一枚铜钱盖住葫芦口，慢慢地用勺子舀油滴入葫芦，油从铜钱的方孔中注入，铜钱却没有沾湿。酌：舀取，这里指倒油；覆：盖；徐：慢慢地；杓：同“勺”；沥之：滴入葫芦。","cn":"","parts":[{"t":"翁曰：“以我"},{"t":"酌","k":22},{"t":"油知之。”乃取一葫芦置于地，以钱覆其口，"},{"t":"徐","k":23},{"t":"以"},{"t":"杓","k":24},{"t":"酌","k":22},{"t":"油"},{"t":"沥之","k":11},{"t":"，自钱孔入，而钱不湿。"}]},{"t":"因曰：“我亦无他，惟手熟尔。”康肃笑而遣之。","n":"老翁接着说：“我也没有别的奥妙，只是手熟罢了。”陈尧咨笑着把他打发走了。因：接着；惟：只；遣：打发。","cn":"","parts":[{"t":"因","k":25},{"t":"曰：“我亦无他，惟手熟"},{"t":"尔","k":19},{"t":"。”康肃笑而"},{"t":"遣","k":26},{"t":"之。"}]}],"words":[{"w":"陈尧咨问道","e":"“你也懂得射箭吗？我的射箭技艺不也是很精湛吗？”汝：你"},{"w":"老翁接着说","e":"“我也没有别的奥妙，只是手熟罢了"},{"w":"陈康肃公","e":"陈尧咨，谥号康肃，北宋人"},{"w":"释担而立","e":"【易错】“释担而立”的“释”是放下，不写“择”；“睨之久而不去”的“睨”是目字旁。"},{"w":"但微颔之","e":"【易错】“但微颔之”的“颔”是页字旁，不写“含”。"},{"w":"老翁说","e":"“没有别的（奥妙），只不过手熟罢了"},{"w":"善射","e":"擅长射箭"},{"w":"自矜","e":"自夸"},{"w":"家圃","e":"家里（射箭的）场地"},{"w":"释担","e":"放下担子"},{"w":"发矢","e":"射箭"},{"w":"沥之","e":"滴入葫芦"},{"w":"擅长","e":"【易错】“陈康肃公善射”的“善”是“擅长”，不写“擅”以外的字；“自矜”的“矜”是“自夸”。"},{"w":"自夸","e":"【易错】“陈康肃公善射”的“善”是“擅长”，不写“擅”以外的字；“自矜”的“矜”是“自夸”。"},{"w":"怎么","e":"【易错】“尔安敢轻吾射”的“安”是“怎么”，不写“按”。"},{"w":"睨","e":"斜着眼看，形容不在意的样子"},{"w":"去","e":"离开"},{"w":"颔","e":"点头"},{"w":"精","e":"精湛"},{"w":"尔","e":"同“耳”，罢了"},{"w":"安","e":"怎么"},{"w":"轻","e":"轻视"},{"w":"酌","e":"舀取，这里指倒油"},{"w":"徐","e":"慢慢地"},{"w":"杓","e":"同“勺”"},{"w":"因","e":"接着"},{"w":"遣","e":"打发"},{"w":"善","e":"【易错】“陈康肃公善射”的“善”是“擅长”，不写“擅”以外的字；“自矜”的“矜”是“自夸”。"},{"w":"擅","e":"【易错】“陈康肃公善射”的“善”是“擅长”，不写“擅”以外的字；“自矜”的“矜”是“自夸”。"},{"w":"矜","e":"【易错】“陈康肃公善射”的“善”是“擅长”，不写“擅”以外的字；“自矜”的“矜”是“自夸”。"},{"w":"释","e":"【易错】“释担而立”的“释”是放下，不写“择”；“睨之久而不去”的“睨”是目字旁。"},{"w":"择","e":"【易错】“释担而立”的“释”是放下，不写“择”；“睨之久而不去”的“睨”是目字旁。"},{"w":"含","e":"【易错】“但微颔之”的“颔”是页字旁，不写“含”。"},{"w":"按","e":"【易错】“尔安敢轻吾射”的“安”是“怎么”，不写“按”。"},{"w":"勺","e":"【易错】“徐以杓酌油沥之”的“杓”同“勺”，“沥”是三点水，不写“历”。"},{"w":"沥","e":"【易错】“徐以杓酌油沥之”的“杓”同“勺”，“沥”是三点水，不写“历”。"},{"w":"历","e":"【易错】“徐以杓酌油沥之”的“杓”同“勺”，“沥”是三点水，不写“历”。"},{"w":"遗","e":"【易错】“康肃笑而遣之”的“遣”是走之旁，不写“遗”。"}]},{"type":"h","text":"译文"},{"type":"p","text":"陈尧咨擅长射箭，当时世上没有第二个人比得上，他也凭这一点自夸。他曾在自己家的园子里射箭，有个卖油的老翁放下担子站在一旁，斜着眼看他，很久不离开。见他射出的箭十支能中八九支，只是微微点头。陈尧咨问：“你也懂射箭吗？我的箭术不也很精湛吗？”老翁说：“没有别的奥妙，只是手熟罢了。”陈尧咨气愤地说：“你怎么敢轻视我的箭术！”老翁说：“凭我倒油就知道这个道理。”于是取来一个葫芦放在地上，用铜钱盖住葫芦口，慢慢地用勺子舀油滴入葫芦，油从钱孔中穿过，而铜钱不湿。接着说：“我也没有别的奥妙，只是手熟罢了。”陈尧咨笑着把他打发走了。"},{"type":"list","title":"名句","items":["无他，但手熟尔。"]},{"type":"list","title":"背诵提示","items":["“陈康肃公善射”的“善”是“擅长”，不写“擅”以外的字；“自矜”的“矜”是“自夸”。","“释担而立”的“释”是放下，不写“择”；“睨之久而不去”的“睨”是目字旁。","“但微颔之”的“颔”是页字旁，不写“含”。","“尔安敢轻吾射”的“安”是“怎么”，不写“按”。","“徐以杓酌油沥之”的“杓”同“勺”，“沥”是三点水，不写“历”。","“康肃笑而遣之”的“遣”是走之旁，不写“遗”。"]}],"questions":[{"id":"p-p7b-mai-you-weng-m0","type":"fill","stem":"默写填空：无他，______。","answer":"但手熟尔。","explain":"出自《卖油翁》（宋·欧阳修）：无他，但手熟尔。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-mai-you-weng-u","type":"fill","stem":"理解性默写：陈尧咨善于射箭，世上没有第二个人能跟他相媲美，他也因此自夸。","answer":"陈康肃公善射，当世无双，公亦以此自矜。","explain":"出自《卖油翁》（宋·欧阳修）。句意：陈尧咨善于射箭，世上没有第二个人能跟他相媲美，他也因此自夸。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-ye-wang","title":"野望","subtitle":"唐·王绩","grade":"8a","tags":["写景","归隐","秋景","借典抒情"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·王绩"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"王绩（约589—644），字无功，号东皋子，绛州龙门（今山西河津）人，隋末唐初诗人，因弃官归隐东皋而自号“东皋子”。\n生平经历：他生活在隋唐易代之际，少年时游历长安，被人称为“神仙童子”；隋末曾任秘书省正字、六合县丞，因不喜官场拘束而弃官归隐；唐初又曾待诏门下省，因嗜酒被时人戏称为“斗酒学士”，最终辞官回到东皋，躬耕自适。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗是王绩归隐故乡后所作。首联点明时间、地点与心境，「徙倚」「欲何依」透出诗人彷徨无依的孤独；中间两联写景兼写人：颔联以「皆」「唯」二字铺开满目秋色，境界阔大而苍凉；颈联写牧人、猎马暮归，一「返」一「归」反衬出诗人无所归依的处境。尾联直抒胸臆，用伯夷、叔齐采薇的典故表明归隐之志。中考常考「树树皆秋色，山山唯落晖」的炼字与写景作用，以及借典抒情的手法，注意「徙倚」「唯」「采薇」的字形。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"东皋薄暮望，徙倚欲何依。","n":"","cn":"傍晚时分站在东皋纵目远望，我徘徊不定，不知何处可以依托。","parts":[{"t":"东皋薄暮望，"},{"t":"徙倚","k":0},{"t":"欲何依。"}]},{"t":"树树皆秋色，山山唯落晖。","n":"","cn":"层层树林都染上了秋天枯黄的颜色，重重山岭都披着落日的余晖。","parts":[{"t":"树树皆秋色，山山"},{"t":"唯","k":5},{"t":"落晖","k":1},{"t":"。"}]},{"t":"牧人驱犊返，猎马带禽归。","n":"","cn":"牧人驱赶着牛群返回村庄，猎人骑着马带着猎获的鸟兽归来。","parts":[{"t":"牧人驱犊返，猎马带禽归。"}]},{"t":"相顾无相识，长歌怀采薇。","n":"","cn":"彼此相望却互不相识，我只好长声歌唱，追怀那采薇隐居的古人。","parts":[{"t":"相顾无相识，长歌怀"},{"t":"采薇","k":2},{"t":"。"}]}],"words":[{"w":"徙倚","e":"【易错】「徙倚」的「徙」读 xǐ，不写作「徒」，注意与「徒」的区别。"},{"w":"落晖","e":"【易错】「落晖」的「晖」是日字旁，不写作「辉」。"},{"w":"采薇","e":"【易错】「采薇」的「薇」是草字头，不写作「微」。"},{"w":"徙","e":"【易错】「徙倚」的「徙」读 xǐ，不写作「徒」，注意与「徒」的区别。"},{"w":"徒","e":"【易错】「徙倚」的「徙」读 xǐ，不写作「徒」，注意与「徒」的区别。"},{"w":"唯","e":"【易错】「山山唯落晖」教材作「唯」，不写作「惟」。"},{"w":"惟","e":"【易错】「山山唯落晖」教材作「唯」，不写作「惟」。"},{"w":"晖","e":"【易错】「落晖」的「晖」是日字旁，不写作「辉」。"},{"w":"辉","e":"【易错】「落晖」的「晖」是日字旁，不写作「辉」。"},{"w":"薇","e":"【易错】「采薇」的「薇」是草字头，不写作「微」。"},{"w":"微","e":"【易错】「采薇」的「薇」是草字头，不写作「微」。"}]},{"type":"list","title":"名句","items":["树树皆秋色，山山唯落晖。"]},{"type":"list","title":"背诵提示","items":["「徙倚」的「徙」读 xǐ，不写作「徒」，注意与「徒」的区别。","「山山唯落晖」教材作「唯」，不写作「惟」。","「落晖」的「晖」是日字旁，不写作「辉」。","「采薇」的「薇」是草字头，不写作「微」。"]}],"questions":[{"id":"p-p8a-ye-wang-m0","type":"fill","stem":"默写填空：树树皆秋色，______。","answer":"山山唯落晖。","explain":"出自《野望》（唐·王绩）：树树皆秋色，山山唯落晖。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-ye-wang-u","type":"fill","stem":"理解性默写：傍晚时分站在东皋纵目远望，我徘徊不定，不知何处可以依托。","answer":"东皋薄暮望，徙倚欲何依。","explain":"出自《野望》（唐·王绩）。句意：傍晚时分站在东皋纵目远望，我徘徊不定，不知何处可以依托。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-huang-he-lou","title":"黄鹤楼","subtitle":"唐·崔颢","grade":"8a","tags":["怀古","思乡","登临","虚实结合"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·崔颢"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"崔颢（约704—754），汴州（今河南开封）人，唐代诗人，官终司勋员外郎，因此后人称他为“崔司勋”。\n生平经历：他早年作诗多写闺情，语意浮艳，曾被时人讥为轻薄；后来他漫游边塞，足迹远及东北与西北，亲见塞外风光与军旅生活，笔力为之一变，写出不少慷慨豪迈之作；他一生仕途平平，长期在外奔走，晚年才回到长安任职。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"此诗为崔颢登楼吊古怀乡之作。前两联从传说落笔，三个「黄鹤」回环往复，「不复返」与「空悠悠」写尽岁月不再、世事茫茫的感慨，虚实相生。颈联转写眼前明丽之景，「历历」「萋萋」两个叠词相对，树影可数、芳草茂盛，以乐景反衬尾联的乡愁。尾联以「愁」字收束，把「日暮」与「烟波」融成一片苍茫，抒发了深沉的思乡之情。中考常考虚实结合、以景结情（由景生情）的手法与叠词的表达效果，注意「萋」「鹦鹉」「历历」的字形，理解「愁」字所寄的羁旅之思。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"昔人已乘黄鹤去，此地空余黄鹤楼。","n":"","cn":"传说中的仙人早已乘着黄鹤飞走了，这里只剩下空荡荡的黄鹤楼。","parts":[{"t":"昔人已乘黄鹤去，此地空余黄鹤楼。"}]},{"t":"黄鹤一去不复返，白云千载空悠悠。","n":"","cn":"黄鹤一去就再也没有回来，千百年来只有白云在空中飘飘荡荡。","parts":[{"t":"黄鹤一去不复返，白云"},{"t":"千载","k":5},{"t":"空悠悠。"}]},{"t":"晴川历历汉阳树，芳草萋萋鹦鹉洲。","n":"","cn":"晴日照耀下的平原上，汉阳的树木清清楚楚，鹦鹉洲上芳草长得极为茂盛。","parts":[{"t":"晴川"},{"t":"历历","k":3},{"t":"汉阳树，"},{"t":"芳草萋萋","k":0},{"t":"鹦鹉洲","k":1},{"t":"。"}]},{"t":"日暮乡关何处是？烟波江上使人愁。","n":"","cn":"天色已晚，我的故乡在哪里呢？江上烟波浩渺，令人愁绪满怀。","parts":[{"t":"日暮"},{"t":"乡关","k":6},{"t":"何处是？烟波江上使人愁。"}]}],"words":[{"w":"芳草萋萋","e":"【易错】「芳草萋萋」的「萋」是草字头，不写作「凄凄」。"},{"w":"鹦鹉洲","e":"【易错】「鹦鹉洲」三字笔画多，注意「鹦」「鹉」都是鸟字旁。"},{"w":"凄凄","e":"【易错】「芳草萋萋」的「萋」是草字头，不写作「凄凄」。"},{"w":"历历","e":"【易错】「历历」不写作「沥沥」；「千载」的「载」读 zǎi。"},{"w":"沥沥","e":"【易错】「历历」不写作「沥沥」；「千载」的「载」读 zǎi。"},{"w":"千载","e":"【易错】「历历」不写作「沥沥」；「千载」的「载」读 zǎi。"},{"w":"乡关","e":"【易错】「乡关」指故乡，不写「乡官」。"},{"w":"乡官","e":"【易错】「乡关」指故乡，不写「乡官」。"},{"w":"萋","e":"【易错】「芳草萋萋」的「萋」是草字头，不写作「凄凄」。"},{"w":"鹦","e":"【易错】「鹦鹉洲」三字笔画多，注意「鹦」「鹉」都是鸟字旁。"},{"w":"鹉","e":"【易错】「鹦鹉洲」三字笔画多，注意「鹦」「鹉」都是鸟字旁。"},{"w":"载","e":"【易错】「历历」不写作「沥沥」；「千载」的「载」读 zǎi。"}]},{"type":"list","title":"名句","items":["日暮乡关何处是？烟波江上使人愁。"]},{"type":"list","title":"背诵提示","items":["「芳草萋萋」的「萋」是草字头，不写作「凄凄」。","「鹦鹉洲」三字笔画多，注意「鹦」「鹉」都是鸟字旁。","「历历」不写作「沥沥」；「千载」的「载」读 zǎi。","「乡关」指故乡，不写「乡官」。"]}],"questions":[{"id":"p-p8a-huang-he-lou-u","type":"fill","stem":"理解性默写：传说中的仙人早已乘着黄鹤飞走了，这里只剩下空荡荡的黄鹤楼。","answer":"昔人已乘黄鹤去，此地空余黄鹤楼。","explain":"出自《黄鹤楼》（唐·崔颢）。句意：传说中的仙人早已乘着黄鹤飞走了，这里只剩下空荡荡的黄鹤楼。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-shi-zhi-sai-shang","title":"使至塞上","subtitle":"唐·王维","grade":"8a","tags":["边塞","写景","炼字","羁旅"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·王维"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"王维（701—761），字摩诘，号摩诘居士，唐代诗人、画家，因官至尚书右丞，世称“王右丞”；他的名与字同取佛教居士“维摩诘”之名，因而又被后人称为“诗佛”。\n生平经历：他少年时便以诗、画与音乐闻名，二十出头便考中进士，早年仕途较为顺利，曾任太乐丞、右拾遗等职；安史之乱中他被迫接受安禄山的伪职，乱平后因此获罪，经人营救才得以宽免；此后他逐渐疏离政治，长期半官半隐于辋川别业，过着亦官亦隐的生活。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是王维奉命出使边塞途中所作。首联叙事，「单车」「属国」暗含轻车简从的孤单。颔联以「征蓬」「归雁」自比，既是写景，又暗写被排挤出朝廷的漂泊之感。颈联「大漠孤烟直，长河落日圆」为千古名句：一「直」一「圆」，以极简的线条勾勒出边塞的雄浑壮阔，画面开阔、意境雄浑，被王国维赞为「千古壮观」。尾联借「燕然」的典故，暗写前线战事，表达对边塞将士的赞美。中考常考颈联的画面描述与「直」「圆」的炼字赏析，注意「征蓬」「候骑」「燕然」的字形与读音。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"单车欲问边，属国过居延。","n":"","cn":"我轻车简从，要去慰问边关，途中经过了属国居延。","parts":[{"t":"单车欲问边，"},{"t":"属","k":8},{"t":"国过居延。"}]},{"t":"征蓬出汉塞，归雁入胡天。","n":"","cn":"我像随风飘飞的蓬草一样出了汉家边塞，又像北归的大雁一样飞进胡人的天空。","parts":[{"t":"征蓬","k":0},{"t":"出汉塞，归雁入胡天。"}]},{"t":"大漠孤烟直，长河落日圆。","n":"","cn":"浩瀚沙漠中一股孤烟直上，长长的黄河上落日正圆。","parts":[{"t":"大漠孤烟直，长河落日圆。"}]},{"t":"萧关逢候骑，都护在燕然。","n":"","cn":"走到萧关恰好遇上侦察骑兵，得知都护正在燕然前线。","parts":[{"t":"萧关逢"},{"t":"候骑","k":1},{"t":"，都护在"},{"t":"燕","k":7},{"t":"然。"}]}],"words":[{"w":"征蓬","e":"【易错】「征蓬」的「蓬」是草字头，比喻漂泊无定，不写作「篷」（船篷）。"},{"w":"候骑","e":"【易错】「候骑」的「候」不写作「侯」；「骑」读 jì，指骑兵。"},{"w":"蓬","e":"【易错】「征蓬」的「蓬」是草字头，比喻漂泊无定，不写作「篷」（船篷）。"},{"w":"篷","e":"【易错】「征蓬」的「蓬」是草字头，比喻漂泊无定，不写作「篷」（船篷）。"},{"w":"候","e":"【易错】「候骑」的「候」不写作「侯」；「骑」读 jì，指骑兵。"},{"w":"侯","e":"【易错】「候骑」的「候」不写作「侯」；「骑」读 jì，指骑兵。"},{"w":"骑","e":"【易错】「候骑」的「候」不写作「侯」；「骑」读 jì，指骑兵。"},{"w":"燕","e":"【易错】「都护在燕然」的「燕」读 yān，不读 yàn。"},{"w":"属","e":"【易错】「属国过居延」的「属」读 shǔ。"}]},{"type":"list","title":"名句","items":["大漠孤烟直，长河落日圆。"]},{"type":"list","title":"背诵提示","items":["「征蓬」的「蓬」是草字头，比喻漂泊无定，不写作「篷」（船篷）。","「候骑」的「候」不写作「侯」；「骑」读 jì，指骑兵。","「都护在燕然」的「燕」读 yān，不读 yàn。","「属国过居延」的「属」读 shǔ。"]}],"questions":[{"id":"p-p8a-shi-zhi-sai-shang-m0","type":"fill","stem":"默写填空：大漠孤烟直，______。","answer":"长河落日圆。","explain":"出自《使至塞上》（唐·王维）：大漠孤烟直，长河落日圆。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-shi-zhi-sai-shang-u","type":"fill","stem":"理解性默写：我轻车简从，要去慰问边关，途中经过了属国居延。","answer":"单车欲问边，属国过居延。","explain":"出自《使至塞上》（唐·王维）。句意：我轻车简从，要去慰问边关，途中经过了属国居延。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-du-jing-men-song-bie","title":"渡荆门送别","subtitle":"唐·李白","grade":"8a","tags":["送别","思乡","写景","炼字"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李白"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李白（701—762），字太白，号青莲居士，唐代伟大的浪漫主义诗人，被后人尊称为“诗仙”，与杜甫并称“李杜”，是我国古典诗歌浪漫主义传统的杰出代表。\n生平经历：少年时博览群书、喜好剑术任侠；二十五岁“仗剑去国”出蜀漫游，足迹遍及大江南北；天宝元年奉诏入长安供奉翰林，因遭权贵谗毁仅三年便离京；安史之乱中因参与永王李璘幕府获罪被流放夜郎，途中遇赦东归，晚年漂泊，762年病逝于当涂。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是李白出蜀东下时所作。首联点明远游的行踪。颔联「山随平野尽，江入大荒流」写船出三峡后视野顿开，一「随」一「入」化静为动，写尽江水奔涌、原野辽阔的气势，成为千古名句。颈联以「天镜」喻水中月影，以「海楼」状云霞变幻，想象奇特，体现李白浪漫飘逸的诗风。尾联「仍怜故乡水，万里送行舟」移情于水，不言自己思念故乡，却说故乡之水远送行舟，含蓄深婉。中考常考颔联的写景角度与「随」「入」的炼字，以及尾联拟人（移情）手法所抒发的思乡之情。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"渡远荆门外，来从楚国游。","n":"","cn":"我乘船远行，经过荆门山之外，来到楚地游览。","parts":[{"t":"渡远荆门外，来"},{"t":"从","k":5},{"t":"楚国游。"}]},{"t":"山随平野尽，江入大荒流。","n":"","cn":"山峦随着平坦的原野的出现而渐渐消失，江水奔入辽远无际的原野中。","parts":[{"t":"山随平野尽，江入"},{"t":"大荒","k":1},{"t":"流。"}]},{"t":"月下飞天镜，云生结海楼。","n":"","cn":"月亮映入江水，好像飞下的天上明镜；云霞兴起，结成海市蜃楼般的奇景。","parts":[{"t":"月下飞天镜，云生"},{"t":"结海楼","k":0},{"t":"。"}]},{"t":"仍怜故乡水，万里送行舟。","n":"","cn":"我还是怜爱故乡的水，它不远万里送我的行舟远行。","parts":[{"t":"仍"},{"t":"怜","k":3},{"t":"故乡水，万里送行舟。"}]}],"words":[{"w":"结海楼","e":"【易错】「结海楼」的「结」不写「接」。"},{"w":"大荒","e":"【易错】「大荒」指广阔的原野，不写「大慌」。"},{"w":"大慌","e":"【易错】「大荒」指广阔的原野，不写「大慌」。"},{"w":"怜","e":"【易错】「仍怜故乡水」的「怜」是「喜爱、怜爱」之意，不写「连」。"},{"w":"连","e":"【易错】「仍怜故乡水」的「怜」是「喜爱、怜爱」之意，不写「连」。"},{"w":"从","e":"【易错】「来从楚国游」的「从」意为「向、往」，不写「丛」。"},{"w":"丛","e":"【易错】「来从楚国游」的「从」意为「向、往」，不写「丛」。"},{"w":"结","e":"【易错】「结海楼」的「结」不写「接」。"},{"w":"接","e":"【易错】「结海楼」的「结」不写「接」。"}]},{"type":"list","title":"名句","items":["山随平野尽，江入大荒流。"]},{"type":"list","title":"背诵提示","items":["「仍怜故乡水」的「怜」是「喜爱、怜爱」之意，不写「连」。","「来从楚国游」的「从」意为「向、往」，不写「丛」。","「结海楼」的「结」不写「接」。","「大荒」指广阔的原野，不写「大慌」。"]}],"questions":[{"id":"p-p8a-du-jing-men-song-bie-m0","type":"fill","stem":"默写填空：山随平野尽，______。","answer":"江入大荒流。","explain":"出自《渡荆门送别》（唐·李白）：山随平野尽，江入大荒流。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-du-jing-men-song-bie-u","type":"fill","stem":"理解性默写：我乘船远行，经过荆门山之外，来到楚地游览。","answer":"渡远荆门外，来从楚国游。","explain":"出自《渡荆门送别》（唐·李白）。句意：我乘船远行，经过荆门山之外，来到楚地游览。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-qian-tang-hu-chun-xing","title":"钱塘湖春行","subtitle":"唐·白居易","grade":"8a","tags":["写景","春景","游记","炼字"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·白居易"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"白居易（772—846），字乐天，晚年号香山居士，又号醉吟先生，唐代伟大的现实主义诗人，新乐府运动的倡导者。他与元稹并称“元白”，诗歌数量在唐代诗人中首屈一指。\n生平经历：少年时因战乱颠沛流离，读书极刻苦，据他自己说曾“口舌成疮”；贞元年间中进士，曾任翰林学士、左拾遗，因直言进谏、上书言事被贬为江州司马；后历任杭州、苏州刺史，在杭州修堤蓄水，颇有惠政；晚年闲居洛阳香山，卒赠尚书右仆射，谥号“文”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是白居易任杭州刺史时所作的写景名篇，处处紧扣「早春」二字。首联点明行踪与湖面初平、云脚低垂的景象。颔联写仰视所见：「早莺」「新燕」是报春的使者，「争暖树」「啄春泥」以动写静，生机盎然。颈联写俯视所见：「乱花」「浅草」写出花初盛、草初生的早春特征，「渐欲」「才能」用词准确传神。尾联直抒胸臆，「行不足」写出流连忘返之情。中考常考颔联、颈联写了哪些早春景物及其作用，注意「啄」「没（mò）」「堤」的字形与「行不足」的炼字效果。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"孤山寺北贾亭西，水面初平云脚低。","n":"","cn":"从孤山寺的北面到贾公亭的西面，湖水初涨，与堤岸相平，白云重重叠叠，同湖面上的波澜连成一片。","parts":[{"t":"孤山寺北贾亭西，水面初平"},{"t":"云脚低","k":0},{"t":"。"}]},{"t":"几处早莺争暖树，谁家新燕啄春泥。","n":"","cn":"几处早来的黄莺争着飞向向阳的树木，谁家新来的燕子啄着春泥筑巢。","parts":[{"t":"几处早莺争暖树，谁家"},{"t":"新燕","k":1},{"t":"啄","k":2},{"t":"春泥。"}]},{"t":"乱花渐欲迷人眼，浅草才能没马蹄。","n":"","cn":"繁花渐渐要使人眼花缭乱，浅浅的春草刚刚能没过马蹄。","parts":[{"t":"乱花渐欲迷人眼，浅草才能"},{"t":"没","k":4},{"t":"马蹄。"}]},{"t":"最爱湖东行不足，绿杨阴里白沙堤。","n":"","cn":"我最喜爱湖东的景色，总是游赏不够，绿杨树荫下便是那白沙堤。","parts":[{"t":"最爱湖东行不足，绿杨"},{"t":"阴","k":5},{"t":"里白沙"},{"t":"堤","k":7},{"t":"。"}]}],"words":[{"w":"云脚低","e":"【易错】「云脚低」的「脚」不写「角」。"},{"w":"新燕","e":"是报春的使者"},{"w":"啄","e":"【易错】「谁家新燕啄春泥」的「啄」有一点，不写「琢」或「啄」漏点。"},{"w":"琢","e":"【易错】「谁家新燕啄春泥」的「啄」有一点，不写「琢」或「啄」漏点。"},{"w":"没","e":"【易错】「浅草才能没马蹄」的「没」读 mò，意为「掩盖、遮没」。"},{"w":"阴","e":"【易错】「绿杨阴里白沙堤」的「阴」不写「荫」，「堤」是土字旁，不写「提」。"},{"w":"荫","e":"【易错】「绿杨阴里白沙堤」的「阴」不写「荫」，「堤」是土字旁，不写「提」。"},{"w":"堤","e":"【易错】「绿杨阴里白沙堤」的「阴」不写「荫」，「堤」是土字旁，不写「提」。"},{"w":"提","e":"【易错】「绿杨阴里白沙堤」的「阴」不写「荫」，「堤」是土字旁，不写「提」。"},{"w":"脚","e":"【易错】「云脚低」的「脚」不写「角」。"},{"w":"角","e":"【易错】「云脚低」的「脚」不写「角」。"}]},{"type":"list","title":"名句","items":["几处早莺争暖树，谁家新燕啄春泥。","乱花渐欲迷人眼，浅草才能没马蹄。"]},{"type":"list","title":"背诵提示","items":["「谁家新燕啄春泥」的「啄」有一点，不写「琢」或「啄」漏点。","「浅草才能没马蹄」的「没」读 mò，意为「掩盖、遮没」。","「绿杨阴里白沙堤」的「阴」不写「荫」，「堤」是土字旁，不写「提」。","「云脚低」的「脚」不写「角」。"]}],"questions":[{"id":"p-p8a-qian-tang-hu-chun-xing-m0","type":"fill","stem":"默写填空：几处早莺争暖树，______。","answer":"谁家新燕啄春泥。","explain":"出自《钱塘湖春行》（唐·白居易）：几处早莺争暖树，谁家新燕啄春泥。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-qian-tang-hu-chun-xing-m1","type":"fill","stem":"默写填空：乱花渐欲迷人眼，______。","answer":"浅草才能没马蹄。","explain":"出自《钱塘湖春行》（唐·白居易）：乱花渐欲迷人眼，浅草才能没马蹄。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-qian-tang-hu-chun-xing-u","type":"fill","stem":"理解性默写：从孤山寺的北面到贾公亭的西面，湖水初涨，与堤岸相平，白云重重叠叠，同湖面上的波澜连成一片。","answer":"孤山寺北贾亭西，水面初平云脚低。","explain":"出自《钱塘湖春行》（唐·白居易）。句意：从孤山寺的北面到贾公亭的西面，湖水初涨，与堤岸相平，白云重重叠叠，同湖面上的波澜连成一片。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-ting-zhong-you-qi-shu","title":"庭中有奇树","subtitle":"汉·《古诗十九首》","grade":"8a","tags":["思妇","相思","借物抒情","古诗十九首"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"汉·《古诗十九首》"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"《古诗十九首》是东汉末年一批文人五言诗的总称，因南朝梁昭明太子萧统编《文选》时把它们编收在一起并题为“古诗十九首”而得名；它代表了汉代文人五言诗的最高成就，也是五言诗从汉代乐府民歌走向文人自觉创作的成熟标志。\n来历与体例：这十九首诗不是官府采集的民歌，而是东汉中后期文人学习乐府民歌之后自铸新词的创作成果；它们并非一时一人之作，作者姓名都已失传，旧说或以为枚乘、曹植、王粲等人所作，都无确证，因此只能笼统称之为“古诗”；体例上全是整齐的五言，多写游子思妇的离愁别绪与士人的失意感伤，短者八句、长者二十句，语言浅近自然而含蓄深婉，善用比兴与景物烘托。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是《古诗十九首》中的一首思妇怀远之作。前四句写树开花盛，妇人攀枝折花，想要赠给远方的思念之人；五六句一转，花香满袖却路远难送，以「盈」与「莫致」形成落差；末两句自问自答，说这花并不足贵，只是离别太久、感伤难耐。全诗由折花赠人这一细节生发，借物抒情，情致委婉深挚，「以乐景写哀」的味道含蓄不尽。中考常考「攀条折其荣，将以遗所思」的表达作用与「遗」的读音（wèi），以及末两句所抒发的相思别离之情，注意「华」同「花」、「馨」「遗」的写法。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"庭中有奇树，绿叶发华滋。","n":"","cn":"庭院里有一株美好的树，绿叶间开出了繁盛的花朵。","parts":[{"t":"庭中有奇树，绿叶发"},{"t":"华","k":1},{"t":"滋","k":3},{"t":"。"}]},{"t":"攀条折其荣，将以遗所思。","n":"","cn":"我攀着枝条折下一枝花，想把它送给心中思念的人。","parts":[{"t":"攀条折其荣，将以"},{"t":"遗","k":5},{"t":"所思。"}]},{"t":"馨香盈怀袖，路远莫致之。","n":"","cn":"花的香气充满了我的襟怀衣袖，可是路途太远无法送到。","parts":[{"t":"馨","k":6},{"t":"香","k":8},{"t":"盈怀袖，路远莫致之。"}]},{"t":"此物何足贵，但感别经时。","n":"","cn":"这花哪里值得珍贵呢，只是感慨分别得太久了。","parts":[{"t":"此物何足"},{"t":"贵","k":9},{"t":"，但感别经时。"}]}],"words":[{"w":"赠送","e":"【易错】「将以遗所思」的「遗」读 wèi，意为「赠送」，不读 yí。"},{"w":"华","e":"同「花」、「馨」「遗」的写法"},{"w":"花","e":"【易错】「绿叶发华滋」的「华」同「花」，「滋」是繁盛之意，不写「兹」。"},{"w":"滋","e":"【易错】「绿叶发华滋」的「华」同「花」，「滋」是繁盛之意，不写「兹」。"},{"w":"兹","e":"【易错】「绿叶发华滋」的「华」同「花」，「滋」是繁盛之意，不写「兹」。"},{"w":"遗","e":"【易错】「将以遗所思」的「遗」读 wèi，意为「赠送」，不读 yí。"},{"w":"馨","e":"【易错】「馨香盈怀袖」的「馨」是「声」下加「香」，注意字形。"},{"w":"声","e":"【易错】「馨香盈怀袖」的「馨」是「声」下加「香」，注意字形。"},{"w":"香","e":"【易错】「馨香盈怀袖」的「馨」是「声」下加「香」，注意字形。"},{"w":"贵","e":"【易错】「此物何足贵」教材作「贵」，不写作「贡」。"},{"w":"贡","e":"【易错】「此物何足贵」教材作「贵」，不写作「贡」。"}]},{"type":"list","title":"名句","items":["馨香盈怀袖，路远莫致之。"]},{"type":"list","title":"背诵提示","items":["「绿叶发华滋」的「华」同「花」，「滋」是繁盛之意，不写「兹」。","「将以遗所思」的「遗」读 wèi，意为「赠送」，不读 yí。","「馨香盈怀袖」的「馨」是「声」下加「香」，注意字形。","「此物何足贵」教材作「贵」，不写作「贡」。"]}],"questions":[{"id":"p-p8a-ting-zhong-you-qi-shu-m0","type":"fill","stem":"默写填空：馨香盈怀袖，______。","answer":"路远莫致之。","explain":"出自《庭中有奇树》（汉·《古诗十九首》）：馨香盈怀袖，路远莫致之。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-ting-zhong-you-qi-shu-u","type":"fill","stem":"理解性默写：庭院里有一株美好的树，绿叶间开出了繁盛的花朵。","answer":"庭中有奇树，绿叶发华滋。","explain":"出自《庭中有奇树》（汉·《古诗十九首》）。句意：庭院里有一株美好的树，绿叶间开出了繁盛的花朵。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-gui-sui-shou","title":"龟虽寿","subtitle":"东汉·曹操","grade":"8a","tags":["言志","励志","生命哲理","乐府"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"东汉·曹操"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"曹操（155—220），字孟德，小名阿瞒，沛国谯县（今安徽亳州）人，东汉末年政治家、军事家、诗人，与其子曹丕、曹植合称“三曹”。\n生平经历：他二十岁举孝廉入仕，曾任洛阳北部尉、济南相等职；汉末天下大乱，他散家财起兵讨伐董卓，后迎汉献帝到许都，先后击败吕布、袁绍等割据势力，统一了北方；建安十三年在赤壁之战中被孙刘联军击败，天下遂成三国鼎立之势；晚年进爵魏王，其子曹丕称帝后追尊他为魏武帝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是曹操《步出夏门行》的末章，写于北征乌桓凯旋之后。开头以「神龟」「腾蛇」起兴，说明生命有限，为下文作反衬。接着以「老骥伏枥，志在千里；烈士暮年，壮心不已」直抒胸臆，用比喻表明虽已暮年而雄心不减，成为千古名句。继而指出「盈缩之期，不但在天；养怡之福，可得永年」，体现诗人积极进取、不迷信天命的乐观精神。末二句是乐府合乐的套语。中考常考「老骥伏枥」四句的比喻义与所抒发的情怀，注意「骥」「枥」「壮心不已」「养怡」的字形与「竟时」的释义。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"神龟虽寿，犹有竟时。","n":"","cn":"神龟虽然长寿，但终究还有死去的时候。","parts":[{"t":"神龟虽寿，"},{"t":"犹有竟时","k":0},{"t":"。"}]},{"t":"腾蛇乘雾，终为土灰。","n":"","cn":"腾蛇能乘云驾雾，最终也会化为泥土灰烬。","parts":[{"t":"腾蛇","k":5},{"t":"乘雾，终为土灰。"}]},{"t":"老骥伏枥，志在千里。","n":"","cn":"年老的千里马虽然伏在马槽旁，雄心壮志仍是驰骋千里。","parts":[{"t":"老骥伏枥","k":1},{"t":"，志在千里。"}]},{"t":"烈士暮年，壮心不已。","n":"","cn":"壮志凌云的人到了晚年，奋发进取的雄心也不会停止。","parts":[{"t":"烈士暮年，"},{"t":"壮心不已","k":3},{"t":"。"}]},{"t":"盈缩之期，不但在天；","n":"","cn":"人寿命长短的期限，并不完全由上天决定；","parts":[{"t":"盈缩之期，不但在天；"}]},{"t":"养怡之福，可得永年。","n":"","cn":"保养身心、使之愉快的福分，可以使人长寿。","parts":[{"t":"养怡之福","k":2},{"t":"，可得永年。"}]},{"t":"幸甚至哉，歌以咏志。","n":"","cn":"幸运得很，好极了，就用这首诗歌来抒发我的志向吧。","parts":[{"t":"幸甚至哉，歌以咏志。"}]}],"words":[{"w":"犹有竟时","e":"【易错】「犹有竟时」的「竟」意为「终结」，不写作「尽」。"},{"w":"老骥伏枥","e":"【易错】「老骥伏枥」的「骥」是千里马，「枥」是马槽，注意偏旁，不写「砺」「历」。"},{"w":"养怡之福","e":"【易错】「养怡之福」的「怡」是竖心旁，不写「贻」。"},{"w":"壮心不已","e":"【易错】「壮心不已」的「已」不写「己」「巳」。"},{"w":"终结","e":"【易错】「犹有竟时」的「竟」意为「终结」，不写作「尽」。"},{"w":"腾蛇","e":"【易错】「腾蛇」教材作「腾」，不写「滕」；理解为传说中能腾云驾雾的神蛇。"},{"w":"竟","e":"【易错】「犹有竟时」的「竟」意为「终结」，不写作「尽」。"},{"w":"尽","e":"【易错】「犹有竟时」的「竟」意为「终结」，不写作「尽」。"},{"w":"骥","e":"【易错】「老骥伏枥」的「骥」是千里马，「枥」是马槽，注意偏旁，不写「砺」「历」。"},{"w":"枥","e":"【易错】「老骥伏枥」的「骥」是千里马，「枥」是马槽，注意偏旁，不写「砺」「历」。"},{"w":"砺","e":"【易错】「老骥伏枥」的「骥」是千里马，「枥」是马槽，注意偏旁，不写「砺」「历」。"},{"w":"历","e":"【易错】「老骥伏枥」的「骥」是千里马，「枥」是马槽，注意偏旁，不写「砺」「历」。"},{"w":"腾","e":"【易错】「腾蛇」教材作「腾」，不写「滕」；理解为传说中能腾云驾雾的神蛇。"},{"w":"滕","e":"【易错】「腾蛇」教材作「腾」，不写「滕」；理解为传说中能腾云驾雾的神蛇。"},{"w":"怡","e":"【易错】「养怡之福」的「怡」是竖心旁，不写「贻」。"},{"w":"贻","e":"【易错】「养怡之福」的「怡」是竖心旁，不写「贻」。"},{"w":"已","e":"【易错】「壮心不已」的「已」不写「己」「巳」。"},{"w":"己","e":"【易错】「壮心不已」的「已」不写「己」「巳」。"},{"w":"巳","e":"【易错】「壮心不已」的「已」不写「己」「巳」。"}]},{"type":"list","title":"名句","items":["老骥伏枥，志在千里。","烈士暮年，壮心不已。"]},{"type":"list","title":"背诵提示","items":["「犹有竟时」的「竟」意为「终结」，不写作「尽」。","「老骥伏枥」的「骥」是千里马，「枥」是马槽，注意偏旁，不写「砺」「历」。","「腾蛇」教材作「腾」，不写「滕」；理解为传说中能腾云驾雾的神蛇。","「养怡之福」的「怡」是竖心旁，不写「贻」。","「壮心不已」的「已」不写「己」「巳」。"]}],"questions":[{"id":"p-p8a-gui-sui-shou-m0","type":"fill","stem":"默写填空：老骥伏枥，______。","answer":"志在千里。","explain":"出自《龟虽寿》（东汉·曹操）：老骥伏枥，志在千里。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-gui-sui-shou-m1","type":"fill","stem":"默写填空：烈士暮年，______。","answer":"壮心不已。","explain":"出自《龟虽寿》（东汉·曹操）：烈士暮年，壮心不已。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-gui-sui-shou-u","type":"fill","stem":"理解性默写：神龟虽然长寿，但终究还有死去的时候。","answer":"神龟虽寿，犹有竟时。","explain":"出自《龟虽寿》（东汉·曹操）。句意：神龟虽然长寿，但终究还有死去的时候。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-zeng-cong-di-qi-er","title":"赠从弟（其二）","subtitle":"东汉·刘桢","grade":"8a","tags":["咏物","托物言志","励志","松柏"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"东汉·刘桢"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"刘桢（186—217），字公干，东平（今山东东平）人，东汉末年诗人，“建安七子”之一，后人常把他与曹植并称“曹刘”。\n生平经历：他少年时便以才学知名，后被曹操召为丞相掾属；他性格刚直，不拘礼法，相传曾因在宴席上平视曹丕之妻而获罪，被罚作苦役，不久遇赦，改任五官将文学；建安二十二年疫病流行，他与陈琳、徐干、应玚等同年病逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是刘桢赠给堂弟的咏物诗。开头两句以「山上松」与「谷中风」对举，一静一动，境界开阔。「一何盛」「一何劲」用两个「一何」反复咏叹，以风之猛烈反衬松之刚劲。五、六句写冰霜严寒之中松树终岁端正，进一步突出其坚贞。结尾设为问答，「岂不罹凝寒，松柏有本性」点明主旨：松柏因本性坚贞，才能不畏严寒。全诗托物言志，借松柏勉励堂弟（也是自勉）坚守节操。中考常考托物言志的手法与「一何」「劲」的表达效果，注意「罹」「凝寒」的字形与「劲」读 jìng。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"亭亭山上松，瑟瑟谷中风。","n":"","cn":"高山上挺拔耸立的松树，迎着山谷间瑟瑟呼啸的狂风。","parts":[{"t":"亭亭","k":0},{"t":"山上松，瑟瑟谷中风。"}]},{"t":"风声一何盛，松枝一何劲。","n":"","cn":"风声是多么猛烈，松枝又是多么刚劲。","parts":[{"t":"风声一何盛，松枝一何"},{"t":"劲","k":3},{"t":"。"}]},{"t":"冰霜正惨凄，终岁常端正。","n":"","cn":"任凭冰霜一片凄寒惨淡，松树却终年端正不斜。","parts":[{"t":"冰霜正惨"},{"t":"凄","k":6},{"t":"，终岁常端正。"}]},{"t":"岂不罹凝寒，松柏有本性。","n":"","cn":"难道松树没有遭受严寒的侵袭吗？只因为松柏自有坚贞的本性。","parts":[{"t":"岂不"},{"t":"罹","k":4},{"t":"凝寒，松柏有本性。"}]}],"words":[{"w":"亭亭","e":"【易错】「亭亭山上松」的「亭亭」不写「停停」。"},{"w":"停停","e":"【易错】「亭亭山上松」的「亭亭」不写「停停」。"},{"w":"遭受","e":"【易错】「岂不罹凝寒」的「罹」读 lí，意为「遭受」，注意上面是「罒」。"},{"w":"劲","e":"【易错】「松枝一何劲」的「劲」读 jìng，意为「刚劲、坚强有力」，不读 jìn。"},{"w":"罹","e":"【易错】「岂不罹凝寒」的「罹」读 lí，意为「遭受」，注意上面是「罒」。"},{"w":"罒","e":"【易错】「岂不罹凝寒」的「罹」读 lí，意为「遭受」，注意上面是「罒」。"},{"w":"凄","e":"【易错】「冰霜正惨凄」的「凄」是两点水，不写「悽」。"},{"w":"悽","e":"【易错】「冰霜正惨凄」的「凄」是两点水，不写「悽」。"}]},{"type":"list","title":"名句","items":["岂不罹凝寒，松柏有本性。"]},{"type":"list","title":"背诵提示","items":["「亭亭山上松」的「亭亭」不写「停停」。","「松枝一何劲」的「劲」读 jìng，意为「刚劲、坚强有力」，不读 jìn。","「岂不罹凝寒」的「罹」读 lí，意为「遭受」，注意上面是「罒」。","「冰霜正惨凄」的「凄」是两点水，不写「悽」。"]}],"questions":[{"id":"p-p8a-zeng-cong-di-qi-er-m0","type":"fill","stem":"默写填空：岂不罹凝寒，______。","answer":"松柏有本性。","explain":"出自《赠从弟（其二）》（东汉·刘桢）：岂不罹凝寒，松柏有本性。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-zeng-cong-di-qi-er-u","type":"fill","stem":"理解性默写：高山上挺拔耸立的松树，迎着山谷间瑟瑟呼啸的狂风。","answer":"亭亭山上松，瑟瑟谷中风。","explain":"出自《赠从弟（其二）》（东汉·刘桢）。句意：高山上挺拔耸立的松树，迎着山谷间瑟瑟呼啸的狂风。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-liang-fu-xing","title":"梁甫行","subtitle":"东汉·曹植","grade":"8a","tags":["民生疾苦","讽喻","乐府","写景"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"东汉·曹植"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"曹植（192—232），字子建，沛国谯县（今安徽亳州）人，三国时期魏国诗人，曹操第三子，与父亲曹操、兄长曹丕合称“三曹”，是建安文学的代表作家。\n生平经历：他少年时才华出众、文思敏捷，深得曹操宠爱，几乎被立为太子；曹丕称帝后，他备受猜忌打压，屡遭贬徙，封地一再迁改，形同囚徒；曹叡即位后处境仍未改观，最后在忧郁中病逝，年仅四十一岁。因最后封地在陈，谥号“思”，后世称他为“陈思王”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"《梁甫行》是曹植借乐府旧题反映民生疾苦的诗作。开头两句写各地气候风土不同，为下文写边海之民作铺垫。「剧哉边海民，寄身于草野」直陈其苦。中间写百姓「妻子象禽兽」，长年依山林险阻而居，过着非人的生活。结尾以「柴门何萧条，狐兔翔我宇」的荒凉景象收束，一幅破败图景中饱含诗人对百姓的深切同情，也隐含对乱世的批判。中考常考「妻子」「象」的古今异义与「狐兔翔我宇」的写景作用，注意「剧哉」「草野」「翔」的字形，体会作者悲天悯人的情怀。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"八方各异气，千里殊风雨。","n":"","cn":"八方的气候各不相同，千里之内的风雨形态也不一样。","parts":[{"t":"八方各异气，千里殊风雨。"}]},{"t":"剧哉边海民，寄身于草野。","n":"","cn":"海边的百姓生活多么艰难啊，他们只能栖身在野外的草屋中。","parts":[{"t":"剧","k":8},{"t":"哉边海民，寄身于草野。"}]},{"t":"妻子象禽兽，行止依林阻。","n":"","cn":"妻子儿女像禽兽一样（衣不蔽体），行动起居都依靠山林险阻之地。","parts":[{"t":"妻子","k":0},{"t":"象","k":4},{"t":"禽兽，"},{"t":"行止","k":1},{"t":"依林阻。"}]},{"t":"柴门何萧条，狐兔翔我宇。","n":"","cn":"柴门何等冷落萧条，狐狸野兔在我的屋宇下自由穿行。","parts":[{"t":"柴门何萧条，狐兔"},{"t":"翔","k":6},{"t":"我宇。"}]}],"words":[{"w":"妻子","e":"【易错】「妻子象禽兽」的「妻子」指妻子儿女，与今义不同；「象」教材作「象」，不写「像」。"},{"w":"行止","e":"【易错】「行止依林阻」的「行止」指行动起居，不写「行址」。"},{"w":"行址","e":"【易错】「行止依林阻」的「行止」指行动起居，不写「行址」。"},{"w":"艰难","e":"【易错】「剧哉边海民」的「剧」意为「艰难」，不写「据」。"},{"w":"象","e":"【易错】「妻子象禽兽」的「妻子」指妻子儿女，与今义不同；「象」教材作「象」，不写「像」。"},{"w":"像","e":"【易错】「妻子象禽兽」的「妻子」指妻子儿女，与今义不同；「象」教材作「象」，不写「像」。"},{"w":"翔","e":"【易错】「狐兔翔我宇」的「翔」是「穿行、出没」之意，不写「祥」。"},{"w":"祥","e":"【易错】「狐兔翔我宇」的「翔」是「穿行、出没」之意，不写「祥」。"},{"w":"剧","e":"【易错】「剧哉边海民」的「剧」意为「艰难」，不写「据」。"},{"w":"据","e":"【易错】「剧哉边海民」的「剧」意为「艰难」，不写「据」。"}]},{"type":"list","title":"名句","items":["柴门何萧条，狐兔翔我宇。"]},{"type":"list","title":"背诵提示","items":["「妻子象禽兽」的「妻子」指妻子儿女，与今义不同；「象」教材作「象」，不写「像」。","「行止依林阻」的「行止」指行动起居，不写「行址」。","「狐兔翔我宇」的「翔」是「穿行、出没」之意，不写「祥」。","「剧哉边海民」的「剧」意为「艰难」，不写「据」。"]}],"questions":[{"id":"p-p8a-liang-fu-xing-m0","type":"fill","stem":"默写填空：柴门何萧条，______。","answer":"狐兔翔我宇。","explain":"出自《梁甫行》（东汉·曹植）：柴门何萧条，狐兔翔我宇。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-liang-fu-xing-u","type":"fill","stem":"理解性默写：八方的气候各不相同，千里之内的风雨形态也不一样。","answer":"八方各异气，千里殊风雨。","explain":"出自《梁甫行》（东汉·曹植）。句意：八方的气候各不相同，千里之内的风雨形态也不一样。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-san-xia","title":"三峡","subtitle":"北魏·郦道元","grade":"8a","tags":["山水","写景","游记","夸张"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"北魏·郦道元"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"郦道元（约470—527），字善长，范阳涿县人，北魏地理学家、散文家。他历任御史中尉、东荆州刺史等职，为官刚正，注重实地考察，又好学博览，一生以著述地理之学著称。\n成书背景：《水经》是一部记载全国水道的地理书，旧题汉代桑钦所作，内容简略；郦道元以它为底本，广引前人著作，并结合自己的见闻加以补充考订，写成《水经注》。此书名为注释，实则注文篇幅远胜原文，兼记两岸山川景物、风土人情、历史掌故与神话传说，自成一部地理巨著。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文是郦道元《水经注》中描写三峡的著名段落，按「山—水—景—情」的顺序展开。先写山：以「略无阙处」「隐天蔽日」突出山的连绵高峻；再写水：夏季水势浩大、流速惊人，「虽乘奔御风，不以疾也」用夸张与对比极写其快；写春冬之景，「素湍绿潭，回清倒影」动静相衬、色彩清丽；写秋景则以「高猿长啸」「哀转久绝」渲染凄凉，并以渔歌作结。中考常考正面描写与侧面描写相结合、夸张手法及「自非」「虽乘奔御风」「属引」等词句的翻译，注意「阙」「曦」「溯」「巘」「漱」「属引」的字形与读音。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"自三峡七百里中，两岸连山，略无阙处。","n":"","cn":"在三峡七百里中，两岸都是连绵的高山，完全没有中断的地方。","parts":[{"t":"自三峡七百里中，两岸连山，"},{"t":"略无阙处","k":0},{"t":"。"}]},{"t":"重岩叠嶂，隐天蔽日。","n":"","cn":"层层的悬崖、排排的峭壁，遮蔽了天空和太阳。","parts":[{"t":"重岩叠嶂，隐天蔽"},{"t":"日","k":10},{"t":"。"}]},{"t":"自非亭午夜分，不见曦月。","n":"","cn":"如果不是正午和半夜，就看不见太阳和月亮。","parts":[{"t":"自非亭午夜分，"},{"t":"不见曦月","k":1},{"t":"。"}]},{"t":"至于夏水襄陵，沿溯阻绝。","n":"","cn":"到了夏天江水漫上山陵的时候，上行和下行的航道都被阻断了。","parts":[{"t":"至于夏水襄陵，"},{"t":"沿溯阻绝","k":2},{"t":"。"}]},{"t":"或王命急宣，有时朝发白帝，暮到江陵，其间千二百里，虽乘奔御风，不以疾也。","n":"","cn":"有时皇帝的命令要紧急传达，就早晨从白帝城出发，傍晚到达江陵，这中间有一千二百里，即使骑着飞奔的快马、驾着疾风，也没有这样快。","parts":[{"t":"或王命急宣，有时朝发白帝，暮到江陵，其间千二百里，虽乘"},{"t":"奔","k":13},{"t":"御风，不以疾也。"}]},{"t":"春冬之时，则素湍绿潭，回清倒影。","n":"","cn":"春冬季节，白色的急流回旋着清波，碧绿的深潭倒映着各种景物的影子。","parts":[{"t":"春冬之时，则素湍绿潭，回清倒影。"}]},{"t":"绝巘多生怪柏，悬泉瀑布，飞漱其间，清荣峻茂，良多趣味。","n":"","cn":"极高的山峰上多生长着奇形怪状的柏树，悬泉瀑布飞速地冲荡在山峰之间，水清、树荣、山高、草盛，实在有很多趣味。","parts":[{"t":"绝巘多生怪柏，悬泉瀑布，"},{"t":"飞漱其间","k":3},{"t":"，清荣峻茂，良多趣味。"}]},{"t":"每至晴初霜旦，林寒涧肃，常有高猿长啸，属引凄异，空谷传响，哀转久绝。","n":"","cn":"每到天刚放晴的时候或下霜的早晨，树林和山涧一片清凉寂静，常有高处的猿猴拉长声音啼叫，声音接连不断，凄凉怪异，空旷的山谷传来回声，悲哀婉转，很久才消失。","parts":[{"t":"每至晴初霜旦，林寒涧肃，常有高猿长啸，"},{"t":"属引凄异","k":4},{"t":"，空谷传响，哀转久绝。"}]},{"t":"故渔者歌曰：“巴东三峡巫峡长，猿鸣三声泪沾裳。”","n":"所以打鱼的人唱道：“巴东三峡巫峡长，猿鸣三声泪沾裳。”","cn":"","parts":[{"t":"故渔者歌曰：“巴东三峡巫峡长，猿鸣三声泪沾裳。”"}]}],"words":[{"w":"略无阙处","e":"【易错】「略无阙处」的「阙」同「缺」，指中断、空缺，不写「阕」。"},{"w":"不见曦月","e":"【易错】「不见曦月」的「曦」指日光，左边是「日」，笔画易错。"},{"w":"沿溯阻绝","e":"【易错】「沿溯阻绝」的「溯」是三点水，意为逆流而上，不写「朔」。"},{"w":"飞漱其间","e":"【易错】「飞漱其间」的「漱」是三点水，不写「嗽」。"},{"w":"属引凄异","e":"【易错】「属引凄异」的「属」读 zhǔ，意为「连接」。"},{"w":"连接","e":"【易错】「属引凄异」的「属」读 zhǔ，意为「连接」。"},{"w":"阙","e":"【易错】「略无阙处」的「阙」同「缺」，指中断、空缺，不写「阕」。"},{"w":"缺","e":"【易错】「略无阙处」的「阙」同「缺」，指中断、空缺，不写「阕」。"},{"w":"阕","e":"【易错】「略无阙处」的「阙」同「缺」，指中断、空缺，不写「阕」。"},{"w":"曦","e":"【易错】「不见曦月」的「曦」指日光，左边是「日」，笔画易错。"},{"w":"日","e":"【易错】「不见曦月」的「曦」指日光，左边是「日」，笔画易错。"},{"w":"溯","e":"【易错】「沿溯阻绝」的「溯」是三点水，意为逆流而上，不写「朔」。"},{"w":"朔","e":"【易错】「沿溯阻绝」的「溯」是三点水，意为逆流而上，不写「朔」。"},{"w":"奔","e":"【易错】「虽乘奔御风」的「奔」指飞奔的马，是动词用作名词，不写「犇」。"},{"w":"犇","e":"【易错】「虽乘奔御风」的「奔」指飞奔的马，是动词用作名词，不写「犇」。"},{"w":"漱","e":"【易错】「飞漱其间」的「漱」是三点水，不写「嗽」。"},{"w":"嗽","e":"【易错】「飞漱其间」的「漱」是三点水，不写「嗽」。"},{"w":"属","e":"【易错】「属引凄异」的「属」读 zhǔ，意为「连接」。"}]},{"type":"h","text":"译文"},{"type":"p","text":"在三峡七百里当中，两岸都是连绵的高山，完全没有中断的地方；层层悬崖、排排峭壁，遮蔽了天空和太阳。若不是正午和半夜，就看不见太阳和月亮。到了夏天江水漫上山陵，上行下行的航道都被阻断；有时皇帝的命令急需传达，就早晨从白帝城出发，傍晚到江陵，其间一千二百里，即使骑快马、驾疾风，也没有这样快。春冬时节，白色的急流回旋着清波，碧绿的深潭倒映着景物的影子；极高的山峰上生长着许多奇形怪状的柏树，悬泉瀑布飞泻冲荡其间，水清树荣、山高草盛，实在趣味无穷。每到天刚晴或下霜的早晨，树林山涧清冷寂静，常有高猿长啼，声音连续不断、凄凉怪异，空谷回声哀婉，久久才消失。所以渔人唱道：“巴东三峡巫峡长，猿鸣三声泪沾裳。”"},{"type":"list","title":"名句","items":["自非亭午夜分，不见曦月。","清荣峻茂，良多趣味。"]},{"type":"list","title":"背诵提示","items":["「略无阙处」的「阙」同「缺」，指中断、空缺，不写「阕」。","「不见曦月」的「曦」指日光，左边是「日」，笔画易错。","「沿溯阻绝」的「溯」是三点水，意为逆流而上，不写「朔」。","「虽乘奔御风」的「奔」指飞奔的马，是动词用作名词，不写「犇」。","「飞漱其间」的「漱」是三点水，不写「嗽」。","「属引凄异」的「属」读 zhǔ，意为「连接」。"]}],"questions":[{"id":"p-p8a-san-xia-m0","type":"fill","stem":"默写填空：自非亭午夜分，______。","answer":"不见曦月。","explain":"出自《三峡》（北魏·郦道元）：自非亭午夜分，不见曦月。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-san-xia-m1","type":"fill","stem":"默写填空：清荣峻茂，______。","answer":"良多趣味。","explain":"出自《三峡》（北魏·郦道元）：清荣峻茂，良多趣味。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-san-xia-u","type":"fill","stem":"理解性默写：在三峡七百里中，两岸都是连绵的高山，完全没有中断的地方。","answer":"自三峡七百里中，两岸连山，略无阙处。","explain":"出自《三峡》（北魏·郦道元）。句意：在三峡七百里中，两岸都是连绵的高山，完全没有中断的地方。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-da-xie-zhong-shu-shu","title":"答谢中书书","subtitle":"南朝·陶弘景","grade":"8a","tags":["山水小品","写景","动静结合","书信"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"南朝·陶弘景"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"陶弘景（456—536），字通明，自号华阳隐居，南朝梁时丹阳秣陵人，道教思想家、医药学家、文学家。他博学多才，精通天文、历算、山川地理与医药，长期隐居句曲山修道，梁武帝遇有国家大事常去咨询，时人因此称他为“山中宰相”。\n成书背景：《答谢中书书》是陶弘景写给朋友谢中书（谢徵）的一封回信，信中描绘江南山川之美。它本是书信的一部分，属骈体写景小品，后来被收入《全梁文》而独立成篇，题目中第二个“书”即书信。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是陶弘景写给谢中书的一封书信，也是一篇清丽的山水小品。开头「山川之美，古来共谈」总领全篇。接着分层描摹：先写仰观俯察的高峰与清流，再写平视的石壁、青林翠竹，然后以「晓雾」「夕日」写晨昏变化；动静相衬、色彩相映，「猿鸟乱鸣」「沉鳞竞跃」中一「乱」一「竞」，把生机写活。结尾以「欲界之仙都」极力赞叹，并以谢灵运自比，抒发了怡情山水、自得而自豪之情。中考常考写景顺序、动静结合与「乱」「竞」的炼字，注意「交辉」「沉鳞」「与（yù）其奇者」的解释与字形。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"山川之美，古来共谈。","n":"","cn":"山川景色的美丽，自古以来就是人们共同谈论赞叹的。","parts":[{"t":"山川之美，古来共谈。"}]},{"t":"高峰入云，清流见底。","n":"","cn":"高高的山峰耸入云端，清澈的溪流可以看见水底。","parts":[{"t":"高峰入云，清流见底。"}]},{"t":"两岸石壁，五色交辉。","n":"","cn":"两岸的石壁色彩斑斓，交相辉映。","parts":[{"t":"两岸石壁，"},{"t":"五色交辉","k":0},{"t":"。"}]},{"t":"青林翠竹，四时俱备。","n":"","cn":"青翠的树林、碧绿的竹丛，四季都有。","parts":[{"t":"青林翠竹，"},{"t":"四时俱备","k":2},{"t":"。"}]},{"t":"晓雾将歇，猿鸟乱鸣；","n":"","cn":"清晨的薄雾将要消散的时候，猿猴和鸟儿此起彼伏地鸣叫；","parts":[{"t":"晓雾将歇，"},{"t":"猿鸟乱鸣","k":3},{"t":"；"}]},{"t":"夕日欲颓，沉鳞竞跃。","n":"","cn":"夕阳快要落山的时候，潜游在水中的鱼争相跳出水面。","parts":[{"t":"夕日欲颓，"},{"t":"沉鳞竞跃","k":1},{"t":"。"}]},{"t":"实是欲界之仙都。","n":"","cn":"这里实在是人间的仙境啊。","parts":[{"t":"实是欲界之仙都。"}]},{"t":"自康乐以来，未复有能与其奇者。","n":"","cn":"自从南朝谢灵运以来，就再也没有能够欣赏、领悟这种奇丽景色的人了。","parts":[{"t":"自康乐以来，未复有能"},{"t":"与","k":13},{"t":"其奇者。"}]}],"words":[{"w":"五色交辉","e":"【易错】「五色交辉」的「辉」是光字旁，不写「晖」（晖指日光）。"},{"w":"沉鳞竞跃","e":"【易错】「沉鳞竞跃」的「竞」是「竞争」的「竞」，不写「竟」。"},{"w":"四时俱备","e":"【易错】「四时俱备」的「俱」是单人旁，不写「具」。"},{"w":"猿鸟乱鸣","e":"【易错】「猿鸟乱鸣」的「乱」指此起彼伏，不写「滥」。"},{"w":"竞争","e":"【易错】「沉鳞竞跃」的「竞」是「竞争」的「竞」，不写「竟」。"},{"w":"辉","e":"【易错】「五色交辉」的「辉」是光字旁，不写「晖」（晖指日光）。"},{"w":"晖","e":"【易错】「五色交辉」的「辉」是光字旁，不写「晖」（晖指日光）。"},{"w":"竞","e":"【易错】「沉鳞竞跃」的「竞」是「竞争」的「竞」，不写「竟」。"},{"w":"竟","e":"【易错】「沉鳞竞跃」的「竞」是「竞争」的「竞」，不写「竟」。"},{"w":"俱","e":"【易错】「四时俱备」的「俱」是单人旁，不写「具」。"},{"w":"具","e":"【易错】「四时俱备」的「俱」是单人旁，不写「具」。"},{"w":"乱","e":"【易错】「猿鸟乱鸣」的「乱」指此起彼伏，不写「滥」。"},{"w":"滥","e":"【易错】「猿鸟乱鸣」的「乱」指此起彼伏，不写「滥」。"},{"w":"与","e":"【易错】「未复有能与其奇者」的「与」读 yù，意为「参与，这里指欣赏、领悟」。"}]},{"type":"list","title":"名句","items":["高峰入云，清流见底。","夕日欲颓，沉鳞竞跃。"]},{"type":"list","title":"背诵提示","items":["「五色交辉」的「辉」是光字旁，不写「晖」（晖指日光）。","「沉鳞竞跃」的「竞」是「竞争」的「竞」，不写「竟」。","「四时俱备」的「俱」是单人旁，不写「具」。","「猿鸟乱鸣」的「乱」指此起彼伏，不写「滥」。","「未复有能与其奇者」的「与」读 yù，意为「参与，这里指欣赏、领悟」。"]}],"questions":[{"id":"p-p8a-da-xie-zhong-shu-shu-m0","type":"fill","stem":"默写填空：高峰入云，______。","answer":"清流见底。","explain":"出自《答谢中书书》（南朝·陶弘景）：高峰入云，清流见底。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-da-xie-zhong-shu-shu-m1","type":"fill","stem":"默写填空：夕日欲颓，______。","answer":"沉鳞竞跃。","explain":"出自《答谢中书书》（南朝·陶弘景）：夕日欲颓，沉鳞竞跃。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-da-xie-zhong-shu-shu-u","type":"fill","stem":"理解性默写：山川景色的美丽，自古以来就是人们共同谈论赞叹的。","answer":"山川之美，古来共谈。","explain":"出自《答谢中书书》（南朝·陶弘景）。句意：山川景色的美丽，自古以来就是人们共同谈论赞叹的。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-ji-cheng-tian-si-ye-you","title":"记承天寺夜游","subtitle":"宋·苏轼","grade":"8a","tags":["游记","写景","贬谪","比喻"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·苏轼"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"苏轼（1037—1101），字子瞻，号东坡居士，北宋著名文学家、书画家，眉州眉山（今四川眉山）人。他与父亲苏洵、弟弟苏辙合称“三苏”，父子三人同列“唐宋八大家”。\n生平经历：嘉祐二年中进士，因反对王安石变法的某些做法而自请外任，先后任杭州、密州、徐州、湖州等地知州；“乌台诗案”后被贬黄州，写下大量名篇；此后又相继被贬惠州、儋州，遇赦北归途中病逝于常州。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文写于苏轼被贬黄州期间，全文仅八十余字而层次分明。先叙事，点明时间、缘由与同游者，「欣然起行」写出见月色而生的雅兴。再写景，用「庭下如积水空明，水中藻、荇交横」的比喻，以水写月光、以藻荇写竹柏之影，动静相生，境界空灵澄澈，是写月的名笔。结尾连发两问，以「但少闲人如吾两人者耳」收束，「闲人」既有贬谪的悲凉自嘲，又含自我排遣、自赏自慰之意，情感复杂。中考常考比喻的妙用与「闲人」的深层含义，注意「藻」「荇」「盖」的解释与「寝」「相与」的意思。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。","n":"","cn":"元丰六年十月十二日夜晚，我脱下衣服准备睡觉，恰好看见月光照进门里，于是高兴地起来走动。","parts":[{"t":"元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。"}]},{"t":"念无与为乐者，遂至承天寺寻张怀民。","n":"","cn":"想到没有可以共同游乐的人，就到承天寺去找张怀民。","parts":[{"t":"念无与为乐者，遂至承天寺寻张怀民。"}]},{"t":"怀民亦未寝，相与步于中庭。","n":"","cn":"张怀民也没有睡，我们便一同在庭院中散步。","parts":[{"t":"怀民亦未"},{"t":"寝","k":8},{"t":"，"},{"t":"相与","k":3},{"t":"步于中庭。"}]},{"t":"庭下如积水空明，水中藻、荇交横，盖竹柏影也。","n":"","cn":"庭院中的月光如同积水一般清澈透明，水中的水藻、荇菜交错纵横，原来是竹子和柏树的影子。","parts":[{"t":"庭下如积水空明，水中藻、"},{"t":"荇","k":4},{"t":"交横，"},{"t":"盖","k":6},{"t":"竹柏影也。"}]},{"t":"何夜无月？何处无竹柏？但少闲人如吾两人者耳。","n":"","cn":"哪一个夜晚没有月光？哪个地方没有竹子和柏树？只是缺少像我们两个这样的闲人罢了。","parts":[{"t":"何夜无月？何处无竹柏？但少闲人如吾两人者"},{"t":"耳","k":10},{"t":"。"}]}],"words":[{"w":"大概是","e":"【易错】「盖竹柏影也」的「盖」表推测，意为「大概是」，不写「概」。"},{"w":"睡觉","e":"【易错】「怀民亦未寝」的「寝」是「睡觉」之意，不写「侵」。"},{"w":"罢了","e":"【易错】「但少闲人如吾两人者耳」的「耳」是语气词「罢了」，不写「尔」。"},{"w":"相与","e":"【易错】「相与步于中庭」的「相与」意为「共同、一起」。"},{"w":"荇","e":"【易错】「水中藻、荇交横」的「荇」读 xìng，是草字头，不写「杏」。"},{"w":"杏","e":"【易错】「水中藻、荇交横」的「荇」读 xìng，是草字头，不写「杏」。"},{"w":"盖","e":"【易错】「盖竹柏影也」的「盖」表推测，意为「大概是」，不写「概」。"},{"w":"概","e":"【易错】「盖竹柏影也」的「盖」表推测，意为「大概是」，不写「概」。"},{"w":"寝","e":"【易错】「怀民亦未寝」的「寝」是「睡觉」之意，不写「侵」。"},{"w":"侵","e":"【易错】「怀民亦未寝」的「寝」是「睡觉」之意，不写「侵」。"},{"w":"耳","e":"【易错】「但少闲人如吾两人者耳」的「耳」是语气词「罢了」，不写「尔」。"},{"w":"尔","e":"【易错】「但少闲人如吾两人者耳」的「耳」是语气词「罢了」，不写「尔」。"}]},{"type":"list","title":"名句","items":["庭下如积水空明，水中藻、荇交横，盖竹柏影也。"]},{"type":"list","title":"背诵提示","items":["「水中藻、荇交横」的「荇」读 xìng，是草字头，不写「杏」。","「盖竹柏影也」的「盖」表推测，意为「大概是」，不写「概」。","「怀民亦未寝」的「寝」是「睡觉」之意，不写「侵」。","「但少闲人如吾两人者耳」的「耳」是语气词「罢了」，不写「尔」。","「相与步于中庭」的「相与」意为「共同、一起」。"]}],"questions":[{"id":"p-p8a-ji-cheng-tian-si-ye-you-m0","type":"fill","stem":"默写填空：庭下如积水空明，______。","answer":"水中藻、荇交横。","explain":"出自《记承天寺夜游》（宋·苏轼）：庭下如积水空明，水中藻、荇交横，盖竹柏影也。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-ji-cheng-tian-si-ye-you-u","type":"fill","stem":"理解性默写：元丰六年十月十二日夜晚，我脱下衣服准备睡觉，恰好看见月光照进门里，于是高兴地起来走动。","answer":"元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。","explain":"出自《记承天寺夜游》（宋·苏轼）。句意：元丰六年十月十二日夜晚，我脱下衣服准备睡觉，恰好看见月光照进门里，于是高兴地起来走动。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-yu-zhu-yuan-si-shu","title":"与朱元思书","subtitle":"南朝·吴均","grade":"8a","tags":["山水小品","写景","骈文","书信","拟人"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"南朝·吴均"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"吴均（469—520），字叔庠，南朝梁吴兴故鄣人，史学家、文学家。他出身寒微而好学有俊才，曾因私撰《齐春秋》触怒梁武帝被免职，后又奉诏撰写《通史》，未成而卒；其文体清拔有古气，时人多加效仿，称为“吴均体”。\n成书背景：《与朱元思书》是吴均写给友人朱元思的一封信，现存部分以写景为主，描绘自富阳至桐庐一百许里的富春江风光。它本是书信体的骈文，因长期被选入教材而独立成篇，选本中收在《吴均集校注》。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是吴均写给朱元思的一封书信，也是一篇骈体写景名作。开头「风烟俱净，天山共色」总写富春江的明净，以「奇山异水，天下独绝」领起下文。写水，以「千丈见底」「直视无碍」写其清，以「急湍甚箭，猛浪若奔」写其急；写山，用「负势竞上」「争高直指」的拟人手法写群山竞秀之态。接着以泉响、鸟鸣、蝉转、猿叫写山林之音，境界幽美；末以「鸢飞戾天者，望峰息心」抒厌弃尘俗、向往自然之情。中考常考动静结合、拟人与「竞」「上」的炼字，注意通假字「反」（返）、「转」（啭）。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"风烟俱净，天山共色。","n":"","cn":"风和烟都散尽了，天空和远山是同样的颜色。","parts":[{"t":"风烟俱净，天山共色。"}]},{"t":"从流飘荡，任意东西。","n":"","cn":"我乘船随着江流飘荡，任凭船儿向东或向西。","parts":[{"t":"从流飘荡，任意东西。"}]},{"t":"自富阳至桐庐一百许里，奇山异水，天下独绝。","n":"","cn":"从富阳到桐庐一百来里，奇异的山水，是天下独一无二的。","parts":[{"t":"自富阳至桐庐一百许里，奇山异水，天下独绝。"}]},{"t":"水皆缥碧，千丈见底。","n":"","cn":"水都是青白色的，千丈深处也能看到水底。","parts":[{"t":"水皆缥碧","k":0},{"t":"，千丈见底。"}]},{"t":"游鱼细石，直视无碍。","n":"","cn":"水中的游鱼和细小的石子，一直看下去可以看得很清楚，毫无障碍。","parts":[{"t":"游鱼细石，直视无碍。"}]},{"t":"急湍甚箭，猛浪若奔。","n":"","cn":"湍急的水流比箭还快，凶猛的浪头像飞奔的马。","parts":[{"t":"急湍甚箭，猛浪若奔。"}]},{"t":"夹岸高山，皆生寒树，负势竞上，互相轩邈，争高直指，千百成峰。","n":"","cn":"江两岸的高山上都生长着阴森森的树；（高山）凭借高峻的地势，争着向上，它们互相比高比远，争着往高处和远处伸展，笔直地向上，直插云天，形成千百座山峰。","parts":[{"t":"夹岸高山，皆生寒树，负势竞上，互相轩邈，争高直指，千百成峰。"}]},{"t":"泉水激石，泠泠作响；好鸟相鸣，嘤嘤成韵。","n":"","cn":"泉水冲击着石头，发出泠泠的清响；美丽的鸟儿互相和鸣，鸣声嘤嘤，和谐动听。","parts":[{"t":"泉水激石，"},{"t":"泠泠作响","k":1},{"t":"；好鸟相鸣，"},{"t":"嘤嘤成韵","k":2},{"t":"。"}]},{"t":"蝉则千转不穷，猿则百叫无绝。","n":"","cn":"蝉长久不断地叫，猿猴也不停地啼。","parts":[{"t":"蝉则千"},{"t":"转","k":11},{"t":"不穷，猿则百叫无绝。"}]},{"t":"鸢飞戾天者，望峰息心；经纶世务者，窥谷忘反。","n":"","cn":"那些像鸢鸟一样极力追求高位的人，看到这些雄奇的山峰，就会平息热衷于功名利禄的心；那些治理政务的人，看到这些幽美的山谷，就会流连忘返。","parts":[{"t":"鸢","k":16},{"t":"飞"},{"t":"戾","k":14},{"t":"天者，望峰息心；经纶世务者，"},{"t":"窥谷忘反","k":3},{"t":"。"}]},{"t":"横柯上蔽，在昼犹昏；疏条交映，有时见日。","n":"","cn":"横斜的树枝在上面遮蔽着，即使在白天也像黄昏时那样昏暗；稀疏的枝条互相掩映，有时能见到阳光。","parts":[{"t":"横柯上蔽","k":4},{"t":"，在昼犹昏；疏条交映，有时见日。"}]}],"words":[{"w":"水皆缥碧","e":"【易错】「水皆缥碧」的「缥」是绞丝旁，不写「漂」。"},{"w":"泠泠作响","e":"【易错】「泠泠作响」的「泠」是三点水，不写作「冷」。"},{"w":"嘤嘤成韵","e":"【易错】「嘤嘤成韵」的「嘤」是口字旁，不写「樱」。"},{"w":"窥谷忘反","e":"【易错】「窥谷忘反」的「反」同「返」，指返回，不写「返」之外的字。"},{"w":"横柯上蔽","e":"【易错】「横柯上蔽」的「柯」是木字旁，指树枝，不写「轲」。"},{"w":"缥","e":"【易错】「水皆缥碧」的「缥」是绞丝旁，不写「漂」。"},{"w":"漂","e":"【易错】「水皆缥碧」的「缥」是绞丝旁，不写「漂」。"},{"w":"泠","e":"【易错】「泠泠作响」的「泠」是三点水，不写作「冷」。"},{"w":"冷","e":"【易错】「泠泠作响」的「泠」是三点水，不写作「冷」。"},{"w":"嘤","e":"【易错】「嘤嘤成韵」的「嘤」是口字旁，不写「樱」。"},{"w":"樱","e":"【易错】「嘤嘤成韵」的「嘤」是口字旁，不写「樱」。"},{"w":"转","e":"【易错】「蝉则千转不穷」的「转」同「啭」，指鸟鸣声，不写「传」。"},{"w":"啭","e":"【易错】「蝉则千转不穷」的「转」同「啭」，指鸟鸣声，不写「传」。"},{"w":"传","e":"【易错】「蝉则千转不穷」的「转」同「啭」，指鸟鸣声，不写「传」。"},{"w":"戾","e":"【易错】「鸢飞戾天者」的「戾」意为「至、到达」，不写「唳」；「鸢」读 yuān。"},{"w":"唳","e":"【易错】「鸢飞戾天者」的「戾」意为「至、到达」，不写「唳」；「鸢」读 yuān。"},{"w":"鸢","e":"【易错】「鸢飞戾天者」的「戾」意为「至、到达」，不写「唳」；「鸢」读 yuān。"},{"w":"反","e":"【易错】「窥谷忘反」的「反」同「返」，指返回，不写「返」之外的字。"},{"w":"返","e":"【易错】「窥谷忘反」的「反」同「返」，指返回，不写「返」之外的字。"},{"w":"柯","e":"【易错】「横柯上蔽」的「柯」是木字旁，指树枝，不写「轲」。"},{"w":"轲","e":"【易错】「横柯上蔽」的「柯」是木字旁，指树枝，不写「轲」。"}]},{"type":"list","title":"名句","items":["风烟俱净，天山共色。","急湍甚箭，猛浪若奔。","鸢飞戾天者，望峰息心；经纶世务者，窥谷忘反。"]},{"type":"list","title":"背诵提示","items":["「水皆缥碧」的「缥」是绞丝旁，不写「漂」。","「泠泠作响」的「泠」是三点水，不写作「冷」。","「嘤嘤成韵」的「嘤」是口字旁，不写「樱」。","「蝉则千转不穷」的「转」同「啭」，指鸟鸣声，不写「传」。","「鸢飞戾天者」的「戾」意为「至、到达」，不写「唳」；「鸢」读 yuān。","「窥谷忘反」的「反」同「返」，指返回，不写「返」之外的字。","「横柯上蔽」的「柯」是木字旁，指树枝，不写「轲」。"]}],"questions":[{"id":"p-p8a-yu-zhu-yuan-si-shu-m0","type":"fill","stem":"默写填空：风烟俱净，______。","answer":"天山共色。","explain":"出自《与朱元思书》（南朝·吴均）：风烟俱净，天山共色。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-yu-zhu-yuan-si-shu-m1","type":"fill","stem":"默写填空：急湍甚箭，______。","answer":"猛浪若奔。","explain":"出自《与朱元思书》（南朝·吴均）：急湍甚箭，猛浪若奔。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-yu-zhu-yuan-si-shu-u","type":"fill","stem":"理解性默写：风和烟都散尽了，天空和远山是同样的颜色。","answer":"风烟俱净，天山共色。","explain":"出自《与朱元思书》（南朝·吴均）。句意：风和烟都散尽了，天空和远山是同样的颜色。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-fu-gui-bu-neng-yin","title":"富贵不能淫","subtitle":"先秦·孟子","grade":"8a","tags":["议论","孟子","人格操守","排比","文言文"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·孟子"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"孟子（约前372—前289），名轲，字子舆，战国时期邹国（今山东邹城）人，儒家学派的代表人物，与孔子并称“孔孟”，后世尊为“亚圣”。\n生平经历：他幼年丧父，由母亲教养成人，相传“孟母三迁”“断机教子”讲的就是他幼时受教的故事；他师承子思一派，曾游说齐、宋、滕、魏等国，宣扬“仁政”“王道”，但当时诸侯忙于攻战，他的主张被视为迂阔而不被采纳；晚年退居乡里，与弟子一起著书立说。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文节选自《孟子·滕文公下》，是孟子论「大丈夫」的著名段落。开篇借景春之问引出论题，孟子先以「是焉得为大丈夫乎」断然否定，再用「妾妇之道」作比，指出公孙衍、张仪一味顺从君王、毫无原则，算不上大丈夫。接着正面立论：「居天下之广居，立天下之正位，行天下之大道」写大丈夫的立身行事；「得志，与民由之；不得志，独行其道」写其守道不阿；「富贵不能淫，贫贱不能移，威武不能屈」三句排比，从三个角度揭示大丈夫的品格，成为千古名句。中考常考比喻论证、排比的作用与「淫」「移」「屈」的使动用法，注意「大丈夫」的评判标准与「女」「冠」的读音。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"景春曰：“公孙衍、张仪岂不诚大丈夫哉？一怒而诸侯惧，安居而天下熄。”","n":"景春说：“公孙衍、张仪难道不是真正的有志气、有作为的男子吗？他们一发怒，诸侯就害怕；他们安静下来，天下便太平无战事。”","cn":"","parts":[{"t":"景春曰：“公孙衍、张仪岂不诚大丈夫哉？一怒而诸侯惧，安居而"},{"t":"天下熄","k":3},{"t":"。”"}]},{"t":"孟子曰：“是焉得为大丈夫乎？子未学礼乎？","n":"孟子说：“这怎么能算是大丈夫呢？你没有学过礼吗？","cn":"","parts":[{"t":"孟子曰：“是焉得为大丈夫乎？子未学礼乎？"}]},{"t":"丈夫之冠也，父命之；女子之嫁也，母命之，往送之门，戒之曰：‘往之女家，必敬必戒，无违夫子！’","n":"","cn":"男子成年举行冠礼时，父亲给以训导；女子出嫁时，母亲给以训导，送她到门口，告诫她说：到了你丈夫家里，一定要恭敬，一定要谨慎，不要违背你的丈夫！","parts":[{"t":"丈夫之"},{"t":"冠","k":6},{"t":"也，父命之；"},{"t":"女","k":4},{"t":"子之嫁也，母命之，往送之门，戒之曰：‘"},{"t":"往之女家","k":0},{"t":"，必敬必戒，无违夫子！’"}]},{"t":"以顺为正者，妾妇之道也。","n":"","cn":"以顺从为准则的，是妇女遵循的规则。","parts":[{"t":"以顺为正者，"},{"t":"妾","k":9},{"t":"妇之道也。"}]},{"t":"居天下之广居，立天下之正位，行天下之大道。","n":"","cn":"（大丈夫应该）住在天下最宽广的住宅「仁」里，站在天下最正确的位置「礼」上，走着天下最光明的大道「义」。","parts":[{"t":"居天下之广居，"},{"t":"立","k":10},{"t":"天下之正位，行天下之大道。"}]},{"t":"得志，与民由之；不得志，独行其道。","n":"","cn":"能实现志向时，与百姓一同遵循正道而行；不能实现志向时，就独自走自己的道路。","parts":[{"t":"得志，与民由之；不得志，独行其道。"}]},{"t":"富贵不能淫，贫贱不能移，威武不能屈。此之谓大丈夫。”","n":"","cn":"富贵不能使他迷惑，贫贱不能使他动摇，威武不能使他屈服。这样的人才称得上大丈夫。”","parts":[{"t":"富贵不能"},{"t":"淫","k":7},{"t":"，贫贱不能移，威武不能屈。此之谓大丈夫。”"}]}],"words":[{"w":"往之女家","e":"【易错】「往之女家」的「女」同「汝」，指你，读 rǔ，不读 nǚ。"},{"w":"景春说","e":"“公孙衍、张仪难道不是真正的有志气、有作为的男子吗？他们一发怒，诸侯就害怕"},{"w":"孟子说","e":"“这怎么能算是大丈夫呢？你没有学过礼吗？"},{"w":"天下熄","e":"【易错】「天下熄」的「熄」是火字旁，意为「太平无战事」。"},{"w":"女","e":"【易错】「往之女家」的「女」同「汝」，指你，读 rǔ，不读 nǚ。"},{"w":"汝","e":"【易错】「往之女家」的「女」同「汝」，指你，读 rǔ，不读 nǚ。"},{"w":"冠","e":"【易错】「丈夫之冠也」的「冠」读 guàn，指行冠礼，不读 guān。"},{"w":"淫","e":"【易错】「富贵不能淫」的「淫」意为「使……迷惑」，是使动用法，不写「谣」。"},{"w":"谣","e":"【易错】「富贵不能淫」的「淫」意为「使……迷惑」，是使动用法，不写「谣」。"},{"w":"妾","e":"【易错】「妾妇之道也」的「妾」是「立」下加「女」，注意字形。"},{"w":"立","e":"【易错】「妾妇之道也」的「妾」是「立」下加「女」，注意字形。"},{"w":"熄","e":"【易错】「天下熄」的「熄」是火字旁，意为「太平无战事」。"}]},{"type":"h","text":"译文"},{"type":"p","text":"景春说：“公孙衍、张仪难道不是真正的大丈夫吗？他们一发怒，诸侯就害怕；他们安静下来，天下就太平无事。”孟子说：“这怎么能算大丈夫呢？你没有学过礼吗？男子行冠礼时，父亲训导他；女子出嫁时，母亲训导她，送她到门口，告诫说：到了你丈夫家，一定要恭敬谨慎，不要违背丈夫！把顺从当作准则的，是妾妇之道。大丈夫应住在天下最宽广的住宅「仁」里，站在天下最正确的位置「礼」上，走天下最光明的大道「义」；得志时与百姓一同循道而行，不得志时独自坚持自己的原则。富贵不能使他迷惑，贫贱不能使他动摇，威武不能使他屈服，这样才叫大丈夫。”"},{"type":"list","title":"名句","items":["富贵不能淫，贫贱不能移，威武不能屈。","得志，与民由之；不得志，独行其道。"]},{"type":"list","title":"背诵提示","items":["「往之女家」的「女」同「汝」，指你，读 rǔ，不读 nǚ。","「丈夫之冠也」的「冠」读 guàn，指行冠礼，不读 guān。","「富贵不能淫」的「淫」意为「使……迷惑」，是使动用法，不写「谣」。","「妾妇之道也」的「妾」是「立」下加「女」，注意字形。","「天下熄」的「熄」是火字旁，意为「太平无战事」。"]}],"questions":[{"id":"p-p8a-fu-gui-bu-neng-yin-m0","type":"fill","stem":"默写填空：富贵不能淫，______。","answer":"贫贱不能移。","explain":"出自《富贵不能淫》（先秦·孟子）：富贵不能淫，贫贱不能移，威武不能屈。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-fu-gui-bu-neng-yin-m1","type":"fill","stem":"默写填空：得志，______。","answer":"与民由之。","explain":"出自《富贵不能淫》（先秦·孟子）：得志，与民由之；不得志，独行其道。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-fu-gui-bu-neng-yin-u","type":"fill","stem":"理解性默写：男子成年举行冠礼时，父亲给以训导；女子出嫁时，母亲给以训导，送她到门口，告诫她说：到了你丈夫家里，一定要恭敬，一定要谨慎，不要违背你的丈夫！","answer":"丈夫之冠也，父命之；女子之嫁也，母命之，往送之门，戒之曰：‘往之女家，必敬必戒，无违夫子！’","explain":"出自《富贵不能淫》（先秦·孟子）。句意：男子成年举行冠礼时，父亲给以训导；女子出嫁时，母亲给以训导，送她到门口，告诫她说：到了你丈夫家里，一定要恭敬，一定要谨慎，不要违背你的丈夫！","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-sheng-yu-you-huan","title":"生于忧患，死于安乐","subtitle":"先秦·孟子","grade":"8a","tags":["议论","孟子","逆境成才","使动用法","文言文"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·孟子"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"孟子（约前372—前289），名轲，字子舆，战国时期邹国（今山东邹城）人，儒家学派的代表人物，与孔子并称“孔孟”，后世尊为“亚圣”。\n生平经历：他幼年丧父，由母亲教养成人，相传“孟母三迁”“断机教子”讲的就是他幼时受教的故事；他师承子思一派，曾游说齐、宋、滕、魏等国，宣扬“仁政”“王道”，但当时诸侯忙于攻战，他的主张被视为迂阔而不被采纳；晚年退居乡里，与弟子一起著书立说。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文节选自《孟子·告子下》，是孟子论述人才成长与国家兴亡的名篇。开头连举六位出身卑微而终成大业的历史人物，运用排比与举例论证，说明人才须在艰苦环境中造就。接着以「故天将降大任于是人也」领起，用「苦」「劳」「饿」「空乏」「拂乱」一组使动句，写逆境对人的磨炼，并以「动心忍性，曾益其所不能」点出磨炼的意义。第三层由个人推及国家：「入则无法家拂士，出则无敌国外患者，国恒亡」，从反面论证忧患的必要。结尾以「生于忧患而死于安乐」收束，点明中心论点。中考常考举例论证、正反对比论证与使动用法的翻译，注意通假字「曾」「衡」「拂」。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"舜发于畎亩之中，傅说举于版筑之间，胶鬲举于鱼盐之中，管夷吾举于士，孙叔敖举于海，百里奚举于市。","n":"","cn":"舜从田地耕作之中被起用，傅说从筑墙的劳作之中被选拔，胶鬲从贩卖鱼盐中被举用，管夷吾从狱官手中被释放并举用，孙叔敖从隐居的海滨被举用，百里奚从集市中被赎回而举用。","parts":[{"t":"舜发于"},{"t":"畎亩","k":2},{"t":"之中，傅"},{"t":"说","k":7},{"t":"举于版筑之间，"},{"t":"胶鬲","k":3},{"t":"举于鱼盐之中，管夷吾举于士，孙叔敖举于海，百里奚举于市。"}]},{"t":"故天将降大任于是人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身，行拂乱其所为，所以动心忍性，曾益其所不能。","n":"","cn":"所以上天将要下达重大使命给这样的人，一定先要使他的内心痛苦，使他的筋骨劳累，使他经受饥饿之苦，使他身处贫困之中，使他做事不顺，用这些来使他的心受到震撼，使他的性格坚忍起来，增加他所不具备的才能。","parts":[{"t":"故天将降大任于"},{"t":"是人","k":4},{"t":"也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身，行"},{"t":"拂","k":13},{"t":"乱其所为，所以动心忍性，"},{"t":"曾","k":9},{"t":"益其所不能。"}]},{"t":"人恒过，然后能改；","n":"","cn":"一个人常常犯错误，然后才能改正；","parts":[{"t":"人恒过，然后能改；"}]},{"t":"困于心，衡于虑，而后作；","n":"","cn":"内心忧困，思虑堵塞，然后才能奋发有为；","parts":[{"t":"困于心，"},{"t":"衡于虑","k":1},{"t":"，而后作；"}]},{"t":"征于色，发于声，而后喻。","n":"","cn":"（一个人的想法）显露在脸色上，流露在言谈中，才能被人了解。","parts":[{"t":"征于色，发于声，而后喻。"}]},{"t":"入则无法家拂士，出则无敌国外患者，国恒亡。","n":"","cn":"（一个国家）在国内如果没有坚守法度的大臣和辅佐君王的贤士，在国外如果没有势力、地位相当的国家和外来的祸患，国家常常会灭亡。","parts":[{"t":"入则无"},{"t":"法家拂士","k":0},{"t":"，出则无敌国外患者，国恒亡。"}]},{"t":"然后知生于忧患而死于安乐也。","n":"","cn":"这样以后才知道，忧患使人生存发展，安逸享乐使人萎靡死亡。","parts":[{"t":"然后知生于忧患而死于安乐也。"}]}],"words":[{"w":"法家拂士","e":"【易错】「法家拂士」的「拂」同「弼」，读 bì，指辅佐。"},{"w":"衡于虑","e":"【易错】「衡于虑」的「衡」同「横」，指梗塞、不顺。"},{"w":"畎亩","e":"【易错】「畎亩」的「畎」读 quǎn，指田间小沟，注意字形。"},{"w":"胶鬲","e":"【易错】「傅说举于版筑之间」的「说」读 yuè；「胶鬲」的「鬲」读 gé。"},{"w":"是人","e":"【易错】教材作「故天将降大任于是人也」，注意「是人」不写「斯人」。"},{"w":"斯人","e":"【易错】教材作「故天将降大任于是人也」，注意「是人」不写「斯人」。"},{"w":"畎","e":"【易错】「畎亩」的「畎」读 quǎn，指田间小沟，注意字形。"},{"w":"说","e":"【易错】「傅说举于版筑之间」的「说」读 yuè；「胶鬲」的「鬲」读 gé。"},{"w":"鬲","e":"【易错】「傅说举于版筑之间」的「说」读 yuè；「胶鬲」的「鬲」读 gé。"},{"w":"曾","e":"【易错】「曾益其所不能」的「曾」同「增」，指增加，不写「增」以外易混字。"},{"w":"增","e":"【易错】「曾益其所不能」的「曾」同「增」，指增加，不写「增」以外易混字。"},{"w":"衡","e":"【易错】「衡于虑」的「衡」同「横」，指梗塞、不顺。"},{"w":"横","e":"【易错】「衡于虑」的「衡」同「横」，指梗塞、不顺。"},{"w":"拂","e":"【易错】「法家拂士」的「拂」同「弼」，读 bì，指辅佐。"},{"w":"弼","e":"【易错】「法家拂士」的「拂」同「弼」，读 bì，指辅佐。"}]},{"type":"list","title":"名句","items":["故天将降大任于是人也，必先苦其心志，劳其筋骨。","生于忧患而死于安乐。"]},{"type":"list","title":"背诵提示","items":["「畎亩」的「畎」读 quǎn，指田间小沟，注意字形。","「傅说举于版筑之间」的「说」读 yuè；「胶鬲」的「鬲」读 gé。","「曾益其所不能」的「曾」同「增」，指增加，不写「增」以外易混字。","「衡于虑」的「衡」同「横」，指梗塞、不顺。","「法家拂士」的「拂」同「弼」，读 bì，指辅佐。","教材作「故天将降大任于是人也」，注意「是人」不写「斯人」。"]}],"questions":[{"id":"p-p8a-sheng-yu-you-huan-m0","type":"fill","stem":"默写填空：故天将降大任于是人也，______。","answer":"必先苦其心志。","explain":"出自《生于忧患，死于安乐》（先秦·孟子）：故天将降大任于是人也，必先苦其心志，劳其筋骨。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-sheng-yu-you-huan-u","type":"fill","stem":"理解性默写：舜从田地耕作之中被起用，傅说从筑墙的劳作之中被选拔，胶鬲从贩卖鱼盐中被举用，管夷吾从狱官手中被释放并举用，孙叔敖从隐居的海滨被举用，百里奚从集市中被赎回而举用。","answer":"舜发于畎亩之中，傅说举于版筑之间，胶鬲举于鱼盐之中，管夷吾举于士，孙叔敖举于海，百里奚举于市。","explain":"出自《生于忧患，死于安乐》（先秦·孟子）。句意：舜从田地耕作之中被起用，傅说从筑墙的劳作之中被选拔，胶鬲从贩卖鱼盐中被举用，管夷吾从狱官手中被释放并举用，孙叔敖从隐居的海滨被举用，百里奚从集市中被赎回而举用。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-yin-jiu-qi-wu","title":"饮酒（其五）","subtitle":"东晋·陶渊明","grade":"8a","tags":["田园","归隐","哲理","炼字"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"东晋·陶渊明"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"陶渊明（约365—427），一名潜，字元亮，一说字渊明，世称靖节先生，自号五柳先生，东晋浔阳柴桑（今江西九江）人，是我国古代第一位大量写作田园诗的诗人，被后世尊为田园诗派的开创者，又被称为“古今隐逸诗人之宗”。\n生平经历：他出身于没落的官宦之家，少有高趣，为谋生曾几度出仕，做过江州祭酒、参军一类小官；义熙元年（405）任彭泽令仅八十余日，因不愿“为五斗米折腰”向督邮屈膝，毅然辞官归田，写下《归去来兮辞》；此后躬耕隐居二十余年，晚年贫病交加而终。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是陶渊明归隐后所作《饮酒》组诗中的第五首。前四句以设问自答，点出「心远地自偏」的哲理：只要内心超脱尘俗，居处自然幽静。五、六句「采菊东篱下，悠然见南山」是千古名句，写采菊之际偶然与南山相遇，「悠然」写心境的闲适自得，「见」字不着力而境界全出，境与意会，妙在无我。七、八句写山气、飞鸟之「还」，正与诗人归隐田园的心境相合。末二句说「此中有真意，欲辨已忘言」，写会意而不可言传的妙处。中考常考「心远」「见」字的赏析与全诗闲适淡泊、返璞归真的情怀，注意「辨」不写「辩」。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"结庐在人境，而无车马喧。","n":"","cn":"我把房屋建造在人来人往的地方，却听不到车马的喧闹。","parts":[{"t":"结庐在人境，而无车马"},{"t":"喧","k":6},{"t":"。"}]},{"t":"问君何能尔？心远地自偏。","n":"","cn":"问我为什么能这样？只要内心远离尘俗，所居之处自然就偏僻安静了。","parts":[{"t":"问君何能尔？心远地自偏。"}]},{"t":"采菊东篱下，悠然见南山。","n":"","cn":"在东篱之下采摘菊花，不经意间望见了远处的南山。","parts":[{"t":"采菊东篱下，悠然"},{"t":"见","k":4},{"t":"南山。"}]},{"t":"山气日夕佳，飞鸟相与还。","n":"","cn":"山中的气息与傍晚的景色都十分美好，飞鸟结伴飞回山林。","parts":[{"t":"山气日夕佳，飞鸟"},{"t":"相与","k":1},{"t":"还","k":8},{"t":"。"}]},{"t":"此中有真意，欲辨已忘言。","n":"","cn":"这里边有人生的真正意趣，想要分辨清楚却已忘了怎样用语言表达。","parts":[{"t":"此中有真意，欲"},{"t":"辨","k":2},{"t":"已忘言。"}]}],"words":[{"w":"看见","e":"【易错】「悠然见南山」的「见」读 jiàn，意为「看见」，不必写作「现」。"},{"w":"相与","e":"【易错】「飞鸟相与还」的「相与」意为「一起、结伴」；「还」读 huán。"},{"w":"辨","e":"【易错】「欲辨已忘言」的「辨」意为「分辨、辨明」，不写「辩」（辩论）。"},{"w":"辩","e":"【易错】「欲辨已忘言」的「辨」意为「分辨、辨明」，不写「辩」（辩论）。"},{"w":"见","e":"【易错】「悠然见南山」的「见」读 jiàn，意为「看见」，不必写作「现」。"},{"w":"现","e":"【易错】「悠然见南山」的「见」读 jiàn，意为「看见」，不必写作「现」。"},{"w":"喧","e":"【易错】「而无车马喧」的「喧」是口字旁，不写「暄」。"},{"w":"暄","e":"【易错】「而无车马喧」的「喧」是口字旁，不写「暄」。"},{"w":"还","e":"【易错】「飞鸟相与还」的「相与」意为「一起、结伴」；「还」读 huán。"}]},{"type":"list","title":"名句","items":["采菊东篱下，悠然见南山。"]},{"type":"list","title":"背诵提示","items":["「欲辨已忘言」的「辨」意为「分辨、辨明」，不写「辩」（辩论）。","「悠然见南山」的「见」读 jiàn，意为「看见」，不必写作「现」。","「而无车马喧」的「喧」是口字旁，不写「暄」。","「飞鸟相与还」的「相与」意为「一起、结伴」；「还」读 huán。"]}],"questions":[{"id":"p-p8a-yin-jiu-qi-wu-m0","type":"fill","stem":"默写填空：采菊东篱下，______。","answer":"悠然见南山。","explain":"出自《饮酒（其五）》（东晋·陶渊明）：采菊东篱下，悠然见南山。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-yin-jiu-qi-wu-u","type":"fill","stem":"理解性默写：我把房屋建造在人来人往的地方，却听不到车马的喧闹。","answer":"结庐在人境，而无车马喧。","explain":"出自《饮酒（其五）》（东晋·陶渊明）。句意：我把房屋建造在人来人往的地方，却听不到车马的喧闹。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-chun-wang","title":"春望","subtitle":"唐·杜甫","grade":"8a","tags":["忧国","思乡","战乱","情景交融"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·杜甫"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"杜甫（712—770），字子美，自号少陵野老，唐代伟大的现实主义诗人，被后人尊称为“诗圣”，他的诗广泛而深刻地反映了唐代由盛转衰时期的社会现实，被称为“诗史”。\n生平经历：青年时曾漫游吴越齐赵，并与李白相识；后困居长安十年，屡试不第；安史之乱中被叛军俘获，逃出后任左拾遗，又因直言进谏被贬；晚年流寓成都，在浣花溪畔建草堂，后又漂泊于夔州、湖湘一带，770年病逝于湘江舟中。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是杜甫在安史之乱中被困长安时所作。首联以「国破」与「山河在」、「城春」与「草木深」对举，以荒芜之景写国破之痛，一「破」一「深」触目惊心。颔联移情于物：「花溅泪」「鸟惊心」，以乐景写哀情，感时伤别，情景交融，为千古名句。颈联「烽火连三月，家书抵万金」直写战乱之久与思亲之切。尾联以「白头搔更短，浑欲不胜簪」的自我形象收束，把忧国思家之情推向极致。中考常考颔联的拟人（移情）手法与「溅」「惊」的表达效果，注意「簪」「抵」的字形与「胜」读 shēng。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"国破山河在，城春草木深。","n":"","cn":"长安沦陷，国家破碎，只有山河依旧；春天来了，长安城里草木茂密。","parts":[{"t":"国破山河在，城春草木深。"}]},{"t":"感时花溅泪，恨别鸟惊心。","n":"","cn":"感伤时局，看到花开而溅泪；怅恨离别，听到鸟鸣而心惊。","parts":[{"t":"感时"},{"t":"花溅泪","k":0},{"t":"，恨别鸟惊心。"}]},{"t":"烽火连三月，家书抵万金。","n":"","cn":"战火接连不断，已经延续了几个月；一封家书抵得上万两黄金。","parts":[{"t":"烽","k":5},{"t":"火连三月，家书"},{"t":"抵","k":8},{"t":"万金。"}]},{"t":"白头搔更短，浑欲不胜簪。","n":"","cn":"满头白发越搔越短，简直要插不住簪子了。","parts":[{"t":"白头搔更短，浑欲不"},{"t":"胜","k":3},{"t":"簪","k":4},{"t":"。"}]}],"words":[{"w":"花溅泪","e":"【易错】「花溅泪」的「溅」是三点水，不写「浅」。"},{"w":"溅","e":"【易错】「花溅泪」的「溅」是三点水，不写「浅」。"},{"w":"浅","e":"【易错】「花溅泪」的「溅」是三点水，不写「浅」。"},{"w":"胜","e":"【易错】「浑欲不胜簪」的「胜」读 shēng，意为「承受、禁受」；「簪」是竹字头。"},{"w":"簪","e":"【易错】「浑欲不胜簪」的「胜」读 shēng，意为「承受、禁受」；「簪」是竹字头。"},{"w":"烽","e":"【易错】「烽火连三月」的「烽」是火字旁，不写「峰」「锋」。"},{"w":"峰","e":"【易错】「烽火连三月」的「烽」是火字旁，不写「峰」「锋」。"},{"w":"锋","e":"【易错】「烽火连三月」的「烽」是火字旁，不写「峰」「锋」。"},{"w":"抵","e":"【易错】「家书抵万金」的「抵」是提手旁，不写「低」。"},{"w":"低","e":"【易错】「家书抵万金」的「抵」是提手旁，不写「低」。"}]},{"type":"list","title":"名句","items":["烽火连三月，家书抵万金。","感时花溅泪，恨别鸟惊心。"]},{"type":"list","title":"背诵提示","items":["「花溅泪」的「溅」是三点水，不写「浅」。","「浑欲不胜簪」的「胜」读 shēng，意为「承受、禁受」；「簪」是竹字头。","「烽火连三月」的「烽」是火字旁，不写「峰」「锋」。","「家书抵万金」的「抵」是提手旁，不写「低」。"]}],"questions":[{"id":"p-p8a-chun-wang-m0","type":"fill","stem":"默写填空：烽火连三月，______。","answer":"家书抵万金。","explain":"出自《春望》（唐·杜甫）：烽火连三月，家书抵万金。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-chun-wang-m1","type":"fill","stem":"默写填空：感时花溅泪，______。","answer":"恨别鸟惊心。","explain":"出自《春望》（唐·杜甫）：感时花溅泪，恨别鸟惊心。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-chun-wang-u","type":"fill","stem":"理解性默写：长安沦陷，国家破碎，只有山河依旧；春天来了，长安城里草木茂密。","answer":"国破山河在，城春草木深。","explain":"出自《春望》（唐·杜甫）。句意：长安沦陷，国家破碎，只有山河依旧；春天来了，长安城里草木茂密。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-yan-men-tai-shou-xing","title":"雁门太守行","subtitle":"唐·李贺","grade":"8a","tags":["边塞","战争","色彩","用典"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李贺"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李贺（790—816），字长吉，福昌（今河南宜阳）人，唐代诗人，唐宗室后裔。因其诗想象奇特、辞采瑰丽，后人称他为“诗鬼”，他又与李白、李商隐并称“唐代三李”。\n生平经历：他少年时才华出众，很早就受到韩愈赏识；因父亲名“晋肃”，“晋”与“进”同音，被人以避讳为由阻挠，终身未能应进士试，只做过奉礼郎一类小官；他体弱多病，又郁郁不得志，二十七岁便英年早逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是李贺用乐府旧题写的边塞诗，全篇色彩浓烈、想象奇特。首句「黑云压城城欲摧」以比喻写敌军压境的危势，一「压」一「摧」气势逼人；次句「甲光向日金鳞开」写守军披甲迎战、金光闪耀，一暗一明，对比强烈。三、四句写号角满天、燕脂凝紫，从听觉与色彩渲染战场的悲壮。五、六句写夜半出袭、霜重鼓寒，暗示战斗的惨烈。结尾以「报君黄金台上意，提携玉龙为君死」直抒将士报国捐躯之志。中考常考色彩词的妙用与「压」「摧」的炼字及结尾所抒发的思想感情，注意「摧」「燕脂」「提携」的字形。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"黑云压城城欲摧，甲光向日金鳞开。","n":"","cn":"敌军像黑云一样压向城头，城墙仿佛要被摧毁；我军铠甲映着日光，闪耀着金子般的鳞光。","parts":[{"t":"黑云压城"},{"t":"城欲摧","k":2},{"t":"，甲光向日金鳞开。"}]},{"t":"角声满天秋色里，塞上燕脂凝夜紫。","n":"","cn":"号角声响彻秋日的天空，塞上将士的血迹在夜色中凝成紫色。","parts":[{"t":"角声满天秋色里，塞上"},{"t":"燕脂","k":4},{"t":"凝夜紫。"}]},{"t":"半卷红旗临易水，霜重鼓寒声不起。","n":"","cn":"半卷着红旗奔赴易水，寒霜浓重，战鼓声低沉得几乎响不起来。","parts":[{"t":"半卷红旗临易水，"},{"t":"霜重鼓寒","k":0},{"t":"声不起。"}]},{"t":"报君黄金台上意，提携玉龙为君死。","n":"","cn":"为了报答君王在黄金台上招揽贤才的厚意，我愿提起宝剑，为国捐躯。","parts":[{"t":"报君黄金台上"},{"t":"意","k":14},{"t":"，"},{"t":"提携玉龙","k":1},{"t":"为君死。"}]}],"words":[{"w":"霜重鼓寒","e":"【易错】「霜重鼓寒」的「重」读 zhòng，意为「厚重、浓重」。"},{"w":"提携玉龙","e":"【易错】「提携玉龙」的「携」是提手旁，不写「挟」；「玉龙」指宝剑。"},{"w":"城欲摧","e":"【易错】「城欲摧」的「摧」是「摧毁」之意，不写「催」。"},{"w":"摧毁","e":"【易错】「城欲摧」的「摧」是「摧毁」之意，不写「催」。"},{"w":"燕脂","e":"【易错】「塞上燕脂凝夜紫」的「燕脂」同「胭脂」，指血色，不写「胭」「脂」的异形写法。"},{"w":"胭脂","e":"【易错】「塞上燕脂凝夜紫」的「燕脂」同「胭脂」，指血色，不写「胭」「脂」的异形写法。"},{"w":"玉龙","e":"【易错】「提携玉龙」的「携」是提手旁，不写「挟」；「玉龙」指宝剑。"},{"w":"摧","e":"【易错】「城欲摧」的「摧」是「摧毁」之意，不写「催」。"},{"w":"催","e":"【易错】「城欲摧」的「摧」是「摧毁」之意，不写「催」。"},{"w":"胭","e":"【易错】「塞上燕脂凝夜紫」的「燕脂」同「胭脂」，指血色，不写「胭」「脂」的异形写法。"},{"w":"脂","e":"【易错】「塞上燕脂凝夜紫」的「燕脂」同「胭脂」，指血色，不写「胭」「脂」的异形写法。"},{"w":"重","e":"【易错】「霜重鼓寒」的「重」读 zhòng，意为「厚重、浓重」。"},{"w":"携","e":"【易错】「提携玉龙」的「携」是提手旁，不写「挟」；「玉龙」指宝剑。"},{"w":"挟","e":"【易错】「提携玉龙」的「携」是提手旁，不写「挟」；「玉龙」指宝剑。"},{"w":"意","e":"【易错】「黄金台上意」的「意」指厚意、恩遇，不写「义」。"},{"w":"义","e":"【易错】「黄金台上意」的「意」指厚意、恩遇，不写「义」。"}]},{"type":"list","title":"名句","items":["黑云压城城欲摧，甲光向日金鳞开。","报君黄金台上意，提携玉龙为君死。"]},{"type":"list","title":"背诵提示","items":["「城欲摧」的「摧」是「摧毁」之意，不写「催」。","「塞上燕脂凝夜紫」的「燕脂」同「胭脂」，指血色，不写「胭」「脂」的异形写法。","「霜重鼓寒」的「重」读 zhòng，意为「厚重、浓重」。","「提携玉龙」的「携」是提手旁，不写「挟」；「玉龙」指宝剑。","「黄金台上意」的「意」指厚意、恩遇，不写「义」。"]}],"questions":[{"id":"p-p8a-yan-men-tai-shou-xing-m0","type":"fill","stem":"默写填空：黑云压城城欲摧，______。","answer":"甲光向日金鳞开。","explain":"出自《雁门太守行》（唐·李贺）：黑云压城城欲摧，甲光向日金鳞开。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-yan-men-tai-shou-xing-m1","type":"fill","stem":"默写填空：报君黄金台上意，______。","answer":"提携玉龙为君死。","explain":"出自《雁门太守行》（唐·李贺）：报君黄金台上意，提携玉龙为君死。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-yan-men-tai-shou-xing-u","type":"fill","stem":"理解性默写：敌军像黑云一样压向城头，城墙仿佛要被摧毁；我军铠甲映着日光，闪耀着金子般的鳞光。","answer":"黑云压城城欲摧，甲光向日金鳞开。","explain":"出自《雁门太守行》（唐·李贺）。句意：敌军像黑云一样压向城头，城墙仿佛要被摧毁；我军铠甲映着日光，闪耀着金子般的鳞光。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-chi-bi","title":"赤壁","subtitle":"唐·杜牧","grade":"8a","tags":["咏史","怀古","以小见大","借物起兴"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·杜牧"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"杜牧（803—约852），字牧之，号樊川居士，京兆万年（今陕西西安）人，晚唐诗人，与李商隐并称“小李杜”；因晚年居樊川别墅，后人又称他“杜樊川”。\n生平经历：他出身名门，祖父杜佑曾任宰相；少年时便有济世之志，喜好谈兵论政，曾为《孙子》作注；二十六岁考中进士，此后长期在朝廷与地方任职，曾任黄州、池州、睦州刺史；晚年回到长安，官至中书舍人，居樊川别墅而终。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是杜牧咏史抒怀的名篇。前两句借一件古物——折戟——兴起对前朝人事的感慨，「折戟沉沙」而「铁未销」，由「磨洗」而「认前朝」，叙事中含沧桑之感，为下文议论作铺垫。后两句从反面假设：倘若当年东风不助周瑜，胜者便是曹操，二乔就要被掳入铜雀台了。诗人以二乔的命运暗写国家的命运，以小见大，含蓄而有情致，并在假设中寄寓自己生不逢时、才不得展的抑郁不平。中考常考以小见大、借物起兴与「东风」的含义，注意「销」不写「消」。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"折戟沉沙铁未销，自将磨洗认前朝。","n":"","cn":"一支折断的铁戟沉埋在沙里，还没有完全锈蚀，我把它拿起来磨洗，辨认出是前朝赤壁之战的遗物。","parts":[{"t":"折戟","k":2},{"t":"沉沙"},{"t":"铁未销","k":1},{"t":"，"},{"t":"自将磨洗","k":0},{"t":"认前朝。"}]},{"t":"东风不与周郎便，铜雀春深锁二乔。","n":"","cn":"倘若当年东风不给周瑜方便，赤壁之战的结局就会改写，大乔小乔就要被曹操锁进铜雀台中了。","parts":[{"t":"东风不与周郎便，铜雀春深"},{"t":"锁","k":8},{"t":"二乔。"}]}],"words":[{"w":"自将磨洗","e":"【易错】「自将磨洗」的「将」读 jiāng，意为「拿、取」。"},{"w":"铁未销","e":"【易错】「铁未销」的「销」意为「锈蚀、销蚀」，不写「消」。"},{"w":"折戟","e":"【易错】「折戟」的「戟」右边是「戈」，注意字形，不写「戟」缺笔。"},{"w":"销","e":"【易错】「铁未销」的「销」意为「锈蚀、销蚀」，不写「消」。"},{"w":"消","e":"【易错】「铁未销」的「销」意为「锈蚀、销蚀」，不写「消」。"},{"w":"戟","e":"【易错】「折戟」的「戟」右边是「戈」，注意字形，不写「戟」缺笔。"},{"w":"戈","e":"【易错】「折戟」的「戟」右边是「戈」，注意字形，不写「戟」缺笔。"},{"w":"将","e":"【易错】「自将磨洗」的「将」读 jiāng，意为「拿、取」。"},{"w":"锁","e":"【易错】「铜雀春深锁二乔」的「锁」是金字旁，不写「琐」。"},{"w":"琐","e":"【易错】「铜雀春深锁二乔」的「锁」是金字旁，不写「琐」。"}]},{"type":"list","title":"名句","items":["东风不与周郎便，铜雀春深锁二乔。"]},{"type":"list","title":"背诵提示","items":["「铁未销」的「销」意为「锈蚀、销蚀」，不写「消」。","「折戟」的「戟」右边是「戈」，注意字形，不写「戟」缺笔。","「自将磨洗」的「将」读 jiāng，意为「拿、取」。","「铜雀春深锁二乔」的「锁」是金字旁，不写「琐」。"]}],"questions":[{"id":"p-p8a-chi-bi-m0","type":"fill","stem":"默写填空：东风不与周郎便，______。","answer":"铜雀春深锁二乔。","explain":"出自《赤壁》（唐·杜牧）：东风不与周郎便，铜雀春深锁二乔。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-chi-bi-u","type":"fill","stem":"理解性默写：一支折断的铁戟沉埋在沙里，还没有完全锈蚀，我把它拿起来磨洗，辨认出是前朝赤壁之战的遗物。","answer":"折戟沉沙铁未销，自将磨洗认前朝。","explain":"出自《赤壁》（唐·杜牧）。句意：一支折断的铁戟沉埋在沙里，还没有完全锈蚀，我把它拿起来磨洗，辨认出是前朝赤壁之战的遗物。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-yu-jia-ao","title":"渔家傲","subtitle":"宋·李清照","grade":"8a","tags":["记梦","豪放","言志","用典","婉约"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·李清照"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"李清照（1084—约1155），号易安居士，齐州章丘（今山东济南）人，宋代婉约词派的代表词人，她在《词论》中提出词“别是一家”之说，与辛弃疾并称“济南二安”。\n生平经历：她出身书香门第，早年与丈夫赵明诚共同收藏金石书画，生活优裕，词作多写闺中生活与离情别绪；靖康之变后中原沦陷，她随夫南渡，不久丈夫病逝，此后辗转江浙一带，晚境孤苦凄凉。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是李清照词中别具一格的一首，以记梦的方式写理想与现实的矛盾。上片写梦中海天相接、星河欲转的壮阔景象，「仿佛梦魂归帝所」引入天帝，「殷勤问我归何处」以对话推进。下片写词人的回答：「路长嗟日暮」化用《离骚》语意，写才华难展、知音难遇的慨叹；「学诗谩有惊人句」既是自负也是自伤。结尾「九万里风鹏正举。风休住，蓬舟吹取三山去」化用《庄子》大鹏形象，表达对自由与光明的追求，气概豪迈，一扫婉约之风。中考常考本词与作者婉约词风的差异，注意「谩」「嗟」「蓬舟」的字形与「谩」的释义。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"天接云涛连晓雾，","n":"","cn":"天空连接着云涛，又连接着晨雾，","parts":[{"t":"天接云涛连晓雾，"}]},{"t":"星河欲转千帆舞。","n":"","cn":"银河欲转，千帆如梭般在浪涛中飞舞。","parts":[{"t":"星河欲转千帆舞。"}]},{"t":"仿佛梦魂归帝所。","n":"","cn":"梦魂仿佛回到了天帝的居所。","parts":[{"t":"仿佛梦魂归帝所。"}]},{"t":"闻天语，殷勤问我归何处。","n":"","cn":"听到天帝在说话，情意恳切地问我归向何处。","parts":[{"t":"闻天语，"},{"t":"殷勤","k":0},{"t":"问我归何"},{"t":"处","k":8},{"t":"。"}]},{"t":"我报路长嗟日暮，","n":"","cn":"我回答说路途漫长而天色已晚，","parts":[{"t":"我报路长"},{"t":"嗟","k":4},{"t":"日暮，"}]},{"t":"学诗谩有惊人句。","n":"","cn":"学习作诗，空有惊人的佳句（却无处施展）。","parts":[{"t":"学诗"},{"t":"谩","k":2},{"t":"有惊人句。"}]},{"t":"九万里风鹏正举。","n":"","cn":"九万里长风之中，大鹏正展翅高飞。","parts":[{"t":"九万里风鹏正举。"}]},{"t":"风休住，蓬舟吹取三山去！","n":"","cn":"风啊不要停下，把我的小船吹到三座仙山上去吧！","parts":[{"t":"风休住，"},{"t":"蓬","k":6},{"t":"舟吹取三山去！"}]}],"words":[{"w":"殷勤","e":"【易错】「殷勤问我归何处」的「殷勤」不写「殷切」；「处」读 chù。"},{"w":"殷切","e":"【易错】「殷勤问我归何处」的「殷勤」不写「殷切」；「处」读 chù。"},{"w":"谩","e":"【易错】「学诗谩有惊人句」的「谩」读 màn，意为「空、徒然」，不写「漫」。"},{"w":"漫","e":"【易错】「学诗谩有惊人句」的「谩」读 màn，意为「空、徒然」，不写「漫」。"},{"w":"嗟","e":"【易错】「我报路长嗟日暮」的「嗟」是口字旁，不写「磋」。"},{"w":"磋","e":"【易错】「我报路长嗟日暮」的「嗟」是口字旁，不写「磋」。"},{"w":"蓬","e":"【易错】「蓬舟吹取三山去」的「蓬」是草字头，不写「篷」。"},{"w":"篷","e":"【易错】「蓬舟吹取三山去」的「蓬」是草字头，不写「篷」。"},{"w":"处","e":"【易错】「殷勤问我归何处」的「殷勤」不写「殷切」；「处」读 chù。"}]},{"type":"list","title":"名句","items":["九万里风鹏正举。风休住，蓬舟吹取三山去！"]},{"type":"list","title":"背诵提示","items":["「学诗谩有惊人句」的「谩」读 màn，意为「空、徒然」，不写「漫」。","「我报路长嗟日暮」的「嗟」是口字旁，不写「磋」。","「蓬舟吹取三山去」的「蓬」是草字头，不写「篷」。","「殷勤问我归何处」的「殷勤」不写「殷切」；「处」读 chù。"]}],"questions":[{"id":"p-p8a-yu-jia-ao-m0","type":"fill","stem":"默写填空：九万里风鹏正举。风休住，______。","answer":"蓬舟吹取三山去！。","explain":"出自《渔家傲》（宋·李清照）：九万里风鹏正举。风休住，蓬舟吹取三山去！","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-yu-jia-ao-u","type":"fill","stem":"理解性默写：天空连接着云涛，又连接着晨雾，","answer":"天接云涛连晓雾，","explain":"出自《渔家傲》（宋·李清照）。句意：天空连接着云涛，又连接着晨雾，","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-tao-hua-yuan-ji","title":"桃花源记（节选）","subtitle":"东晋·陶渊明","grade":"8b","tags":["文言文","记叙","理想社会","世外桃源"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"东晋·陶渊明"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"陶渊明（约365—427），一名潜，字元亮，一说字渊明，世称靖节先生，自号五柳先生，东晋浔阳柴桑（今江西九江）人，是我国古代第一位大量写作田园诗的诗人，被后世尊为田园诗派的开创者，又被称为“古今隐逸诗人之宗”。\n生平经历：他出身于没落的官宦之家，少有高趣，为谋生曾几度出仕，做过江州祭酒、参军一类小官；义熙元年（405）任彭泽令仅八十余日，因不愿“为五斗米折腰”向督邮屈膝，毅然辞官归田，写下《归去来兮辞》；此后躬耕隐居二十余年，晚年贫病交加而终。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文节选自陶渊明的《桃花源记》，是全文最著名的段落。作者以渔人行踪为线索，先写桃花林与山洞之奇，「才通人」「豁然开朗」一收一放，引出世外乐土。接着写桃花源内的景象：「土地平旷，屋舍俨然」「阡陌交通，鸡犬相闻」写环境之美，「往来种作」「怡然自乐」写生活之安，一幅安宁祥和的图景，与外面战乱频仍的世界形成鲜明对照。结尾写村人「设酒杀鸡作食」的淳朴好客与「不足为外人道也」的叮嘱，为后文不可复寻埋下伏笔。中考常考虚实相生的写法、以渔人行踪为线索的叙事顺序，以及「俨然」「阡陌」「黄发垂髫」「要」「语」等词的解释。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"林尽水源，便得一山，山有小口，仿佛若有光。","n":"","cn":"桃林在溪水发源的地方就到头了，（渔人）便看到一座山，山上有个小洞口，里面隐隐约约好像有光亮。","parts":[{"t":"林尽水源，便得一山，山有小口，仿佛若有光。"}]},{"t":"便舍船，从口入。初极狭，才通人。复行数十步，豁然开朗。","n":"","cn":"（渔人）就丢下船，从洞口进去。起初洞口很狭窄，仅容一个人通过。又往前走了几十步，眼前突然变得开阔明亮了。","parts":[{"t":"便舍船，从口入。初极狭，才通人。复行数十步，豁然开朗。"}]},{"t":"土地平旷，屋舍俨然，有良田、美池、桑竹之属。","n":"","cn":"（这里）土地平坦开阔，房屋整整齐齐，还有肥沃的田地、美丽的池塘和桑树竹子之类。","parts":[{"t":"土地平旷，"},{"t":"屋舍俨然","k":1},{"t":"，有良田、美池、桑竹之属。"}]},{"t":"阡陌交通，鸡犬相闻。","n":"","cn":"田间小路交错相通，村落间鸡鸣狗吠之声处处可以听到。","parts":[{"t":"阡陌交通","k":2},{"t":"，鸡犬相闻。"}]},{"t":"其中往来种作，男女衣着，悉如外人。","n":"","cn":"人们在田间来来往往耕种劳作，男女的穿戴完全像桃花源以外的世人。","parts":[{"t":"其中往来种作，男女衣着，悉如外人。"}]},{"t":"黄发垂髫，并怡然自乐。","n":"","cn":"老人和小孩都安适愉快，自得其乐。","parts":[{"t":"黄发垂髫","k":3},{"t":"，并怡然自乐。"}]},{"t":"见渔人，乃大惊，问所从来。具答之。便要还家，设酒杀鸡作食。","n":"","cn":"（村中人）看见渔人，竟然大为惊奇，问他从哪里来。（渔人）详细地回答了他们。（有人）就邀请他到自己家里去，摆酒杀鸡做饭来款待他。","parts":[{"t":"见渔人，乃大惊，问所从来。具答之。"},{"t":"便要还家","k":4},{"t":"，设酒杀鸡作食。"}]},{"t":"村中闻有此人，咸来问讯。","n":"","cn":"村里的人听说来了这样一个人，都来打听消息。","parts":[{"t":"村中闻有此人，咸来问讯。"}]},{"t":"自云先世避秦时乱，率妻子邑人来此绝境，不复出焉，遂与外人间隔。","n":"","cn":"他们自己说祖先为了躲避秦时的战乱，带领妻子儿女和乡邻来到这个与世隔绝的地方，不再出去，于是就同外面的人断绝了来往。","parts":[{"t":"自云先世避秦时乱，率妻子邑人来此绝境，不复出焉，遂与外人间隔。"}]},{"t":"问今是何世，乃不知有汉，无论魏晋。","n":"","cn":"（他们）问现在是什么朝代，竟然不知道有过汉朝，更不必说魏朝和晋朝了。","parts":[{"t":"问今是何世，乃不知有汉，无论魏晋。"}]},{"t":"此人一一为具言所闻，皆叹惋。余人各复延至其家，皆出酒食。停数日，辞去。","n":"","cn":"渔人把自己知道的事一一向他们详细说出，（听的人）都感叹惋惜。其余的人各自又邀请渔人到自己家中，都拿出酒食来招待他。（渔人）停留了几天，就告辞离去。","parts":[{"t":"此人一一为具言所闻，"},{"t":"皆叹惋","k":5},{"t":"。余人各复延至其家，皆出酒食。停数日，辞去。"}]},{"t":"此中人语云：“不足为外人道也。”","n":"村里人对他说：“（这里的情况）不值得对外面的人说啊。”","cn":"","parts":[{"t":"此中人"},{"t":"语","k":14},{"t":"云：“不足为外人道也。”"}]}],"words":[{"w":"村里人对他说","e":"“（这里的情况）不值得对外面的人说啊"},{"w":"屋舍俨然","e":"【易错】「屋舍俨然」的「俨」读 yǎn，是单人旁，指整齐的样子。"},{"w":"阡陌交通","e":"【易错】「阡陌交通」的「阡陌」指田间小路，「交通」是交错相通，古今异义。"},{"w":"黄发垂髫","e":"【易错】「黄发垂髫」的「髫」读 tiáo，指小孩垂下的头发，注意字形。"},{"w":"便要还家","e":"【易错】「便要还家」的「要」读 yāo，同「邀」，指邀请。"},{"w":"皆叹惋","e":"【易错】「皆叹惋」的「惋」是竖心旁，指惊叹惋惜，不写「婉」。"},{"w":"阡陌","e":"【易错】「阡陌交通」的「阡陌」指田间小路，「交通」是交错相通，古今异义。"},{"w":"交通","e":"【易错】「阡陌交通」的「阡陌」指田间小路，「交通」是交错相通，古今异义。"},{"w":"俨","e":"【易错】「屋舍俨然」的「俨」读 yǎn，是单人旁，指整齐的样子。"},{"w":"髫","e":"【易错】「黄发垂髫」的「髫」读 tiáo，指小孩垂下的头发，注意字形。"},{"w":"要","e":"【易错】「便要还家」的「要」读 yāo，同「邀」，指邀请。"},{"w":"邀","e":"【易错】「便要还家」的「要」读 yāo，同「邀」，指邀请。"},{"w":"惋","e":"【易错】「皆叹惋」的「惋」是竖心旁，指惊叹惋惜，不写「婉」。"},{"w":"婉","e":"【易错】「皆叹惋」的「惋」是竖心旁，指惊叹惋惜，不写「婉」。"},{"w":"语","e":"【易错】「此中人语云」的「语」读 yù，指告诉，不读 yǔ。"}]},{"type":"h","text":"译文"},{"type":"p","text":"桃林到溪水源头就尽了，渔人便看到一座山，山边有个小洞口，里面仿佛有光亮。他丢下船，从洞口进去。起初洞口很窄，仅容一人通过，又走几十步，眼前豁然开朗。这里土地平坦开阔，房舍整整齐齐，有肥沃的田地、美丽的池塘和桑竹之类；田间小路交错相通，鸡犬之声相闻。人们往来耕作，男女衣着全像外面的人，老人小孩都安适快乐。村人见到渔人十分惊奇，问他从哪里来，渔人一一回答。有人便邀请他回家，杀鸡摆酒款待。村中人听说后都来打听消息，说祖先为避秦时战乱，带妻子儿女乡邻来到这绝境，不再出去，于是与外人隔绝。他们问如今是什么朝代，竟不知有汉，更不必说魏晋。渔人一一告诉他们，大家都感叹惋惜，其余人又各自邀他到家中，拿出酒食。住了几天，渔人告辞，村中人叮嘱说：“这里的情况不值得对外人说啊。”"},{"type":"list","title":"名句","items":["阡陌交通，鸡犬相闻。","黄发垂髫，并怡然自乐。"]},{"type":"list","title":"背诵提示","items":["「屋舍俨然」的「俨」读 yǎn，是单人旁，指整齐的样子。","「阡陌交通」的「阡陌」指田间小路，「交通」是交错相通，古今异义。","「黄发垂髫」的「髫」读 tiáo，指小孩垂下的头发，注意字形。","「便要还家」的「要」读 yāo，同「邀」，指邀请。","「皆叹惋」的「惋」是竖心旁，指惊叹惋惜，不写「婉」。","「此中人语云」的「语」读 yù，指告诉，不读 yǔ。"]}],"questions":[{"id":"p-p8b-tao-hua-yuan-ji-m0","type":"fill","stem":"默写填空：阡陌交通，______。","answer":"鸡犬相闻。","explain":"出自《桃花源记（节选）》（东晋·陶渊明）：阡陌交通，鸡犬相闻。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-tao-hua-yuan-ji-m1","type":"fill","stem":"默写填空：黄发垂髫，______。","answer":"并怡然自乐。","explain":"出自《桃花源记（节选）》（东晋·陶渊明）：黄发垂髫，并怡然自乐。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-tao-hua-yuan-ji-u","type":"fill","stem":"理解性默写：桃林在溪水发源的地方就到头了，（渔人）便看到一座山，山上有个小洞口，里面隐隐约约好像有光亮。","answer":"林尽水源，便得一山，山有小口，仿佛若有光。","explain":"出自《桃花源记（节选）》（东晋·陶渊明）。句意：桃林在溪水发源的地方就到头了，（渔人）便看到一座山，山上有个小洞口，里面隐隐约约好像有光亮。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-xiao-shi-tan-ji","title":"小石潭记","subtitle":"唐·柳宗元","grade":"8b","tags":["文言文","游记","写景","贬谪","比喻"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·柳宗元"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"柳宗元（773—819），字子厚，河东（今山西运城）人，世称“柳河东”，又因官终柳州刺史而称“柳柳州”，唐代文学家、哲学家。\n生平经历：他二十一岁考中进士，与刘禹锡同榜，二人后来一同参与王叔文集团的永贞革新；革新失败后被贬为永州司马，在永州度过了十年的谪居生活；此后改任柳州刺史，在任上兴办教育、释放奴婢，颇有政绩，最终卒于柳州任所。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文是柳宗元《永州八记》之一，以游踪为序，移步换景。第一段写发现小潭：由水声写到小潭，写出石底、石岸的奇特，并点出竹树环合的清幽。第二段写潭水与游鱼，是全文最精彩处：以「皆若空游无所依」侧面写水之清澈，「日光下澈，影布石上」写光影，「佁然」「俶尔」「翕忽」写鱼的动静变化，并以「似与游者相乐」移情于鱼。第三段以「斗折蛇行」「犬牙差互」两个比喻写溪身与岸势。末段以「凄神寒骨，悄怆幽邃」收束，由乐转悲，含蓄写出作者被贬后的孤寂凄凉。中考常考侧面描写、比喻与情景交融的写法，注意「冽」「珮」「嵁」「佁」「俶」「翕」「邃」的字形与读音。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"从小丘西行百二十步，隔篁竹，闻水声，如鸣珮环，心乐之。","n":"","cn":"从小丘向西走一百二十步，隔着竹林，听到了水声，好像玉珮玉环相碰发出的声音，心里为之高兴。","parts":[{"t":"从小丘西行百二十步，隔篁竹，闻水声，"},{"t":"如鸣珮环","k":1},{"t":"，心乐之。"}]},{"t":"伐竹取道，下见小潭，水尤清冽。","n":"","cn":"（于是）砍倒竹子开辟道路，向下走看见一个小潭，潭水格外清凉。","parts":[{"t":"伐竹取道，下见小潭，"},{"t":"水尤清冽","k":0},{"t":"。"}]},{"t":"全石以为底，近岸，卷石底以出，为坻，为屿，为嵁，为岩。","n":"","cn":"小潭以整块石头为底，靠近岸边，石底有些部分翻卷过来露出水面，成为坻、屿、嵁、岩等各种不同的形状。","parts":[{"t":"全石以为底，近岸，卷石底以出，为坻，为屿，为"},{"t":"嵁","k":11},{"t":"，为岩。"}]},{"t":"青树翠蔓，蒙络摇缀，参差披拂。","n":"","cn":"青葱的树木，翠绿的藤蔓，覆盖缠绕、摇动连结，参差不齐，随风飘拂。","parts":[{"t":"青树翠蔓，"},{"t":"蒙络摇缀","k":2},{"t":"，参差披拂。"}]},{"t":"潭中鱼可百许头，皆若空游无所依，日光下澈，影布石上。","n":"","cn":"潭中的鱼大约有一百来条，都好像在空中游动，什么依托也没有，阳光直照到水底，鱼的影子映在石上。","parts":[{"t":"潭中鱼可百许头，皆若空游无所依，日光下澈，影布石上。"}]},{"t":"佁然不动，俶尔远逝，往来翕忽，似与游者相乐。","n":"","cn":"（鱼儿）呆呆地一动不动，忽然向远处游去，来来往往，轻快敏捷，好像和游人相互取乐。","parts":[{"t":"佁然不动","k":3},{"t":"，"},{"t":"俶尔远逝","k":4},{"t":"，往来"},{"t":"翕忽","k":6},{"t":"，似与游者相乐。"}]},{"t":"潭西南而望，斗折蛇行，明灭可见。","n":"","cn":"向小石潭的西南方望去，（溪水）像北斗星那样曲折，像蛇那样蜿蜒前行，时隐时现。","parts":[{"t":"潭西南而望，斗折蛇行，明灭可见。"}]},{"t":"其岸势犬牙差互，不可知其源。","n":"","cn":"溪岸的形状像狗的牙齿那样交错不齐，不能知道溪水的源头在哪里。","parts":[{"t":"其岸势犬牙差互，不可知其源。"}]},{"t":"坐潭上，四面竹树环合，寂寥无人，凄神寒骨，悄怆幽邃。","n":"","cn":"坐在潭边，四面被竹子和树木环绕合抱，寂静寥落，没有旁人，让人感到心神凄凉、寒气透骨，幽静深远，弥漫着忧伤的气息。","parts":[{"t":"坐潭上，四面竹树环合，寂寥无人，凄神寒骨，"},{"t":"悄怆幽邃","k":5},{"t":"。"}]},{"t":"以其境过清，不可久居，乃记之而去。","n":"","cn":"因为这里的环境过于凄清，不能长时间停留，于是记下这番景致就离开了。","parts":[{"t":"以其境过清，不可久居，乃记之而去。"}]}],"words":[{"w":"水尤清冽","e":"【易错】「水尤清冽」的「冽」是两点水，指清凉，不写「洌」。"},{"w":"如鸣珮环","e":"【易错】「如鸣珮环」的「珮」是玉字旁，教材作「珮」，注意不同于「佩」。"},{"w":"蒙络摇缀","e":"【易错】「蒙络摇缀」的「缀」是绞丝旁，不写「辍」。"},{"w":"佁然不动","e":"【易错】「佁然不动」的「佁」读 yǐ；「俶尔远逝」的「俶」读 chù；「翕忽」的「翕」读 xī。"},{"w":"俶尔远逝","e":"【易错】「佁然不动」的「佁」读 yǐ；「俶尔远逝」的「俶」读 chù；「翕忽」的「翕」读 xī。"},{"w":"悄怆幽邃","e":"【易错】「悄怆幽邃」的「怆」是竖心旁，「邃」是走之底，注意字形。"},{"w":"翕忽","e":"【易错】「佁然不动」的「佁」读 yǐ；「俶尔远逝」的「俶」读 chù；「翕忽」的「翕」读 xī。"},{"w":"冽","e":"【易错】「水尤清冽」的「冽」是两点水，指清凉，不写「洌」。"},{"w":"洌","e":"【易错】「水尤清冽」的「冽」是两点水，指清凉，不写「洌」。"},{"w":"珮","e":"【易错】「如鸣珮环」的「珮」是玉字旁，教材作「珮」，注意不同于「佩」。"},{"w":"佩","e":"【易错】「如鸣珮环」的「珮」是玉字旁，教材作「珮」，注意不同于「佩」。"},{"w":"嵁","e":"【易错】「为坻，为屿，为嵁，为岩」的「嵁」读 kān，指不平的岩石，字形易错。"},{"w":"缀","e":"【易错】「蒙络摇缀」的「缀」是绞丝旁，不写「辍」。"},{"w":"辍","e":"【易错】「蒙络摇缀」的「缀」是绞丝旁，不写「辍」。"},{"w":"佁","e":"【易错】「佁然不动」的「佁」读 yǐ；「俶尔远逝」的「俶」读 chù；「翕忽」的「翕」读 xī。"},{"w":"俶","e":"【易错】「佁然不动」的「佁」读 yǐ；「俶尔远逝」的「俶」读 chù；「翕忽」的「翕」读 xī。"},{"w":"翕","e":"【易错】「佁然不动」的「佁」读 yǐ；「俶尔远逝」的「俶」读 chù；「翕忽」的「翕」读 xī。"},{"w":"怆","e":"【易错】「悄怆幽邃」的「怆」是竖心旁，「邃」是走之底，注意字形。"},{"w":"邃","e":"【易错】「悄怆幽邃」的「怆」是竖心旁，「邃」是走之底，注意字形。"}]},{"type":"list","title":"名句","items":["潭中鱼可百许头，皆若空游无所依。","凄神寒骨，悄怆幽邃。"]},{"type":"list","title":"背诵提示","items":["「水尤清冽」的「冽」是两点水，指清凉，不写「洌」。","「如鸣珮环」的「珮」是玉字旁，教材作「珮」，注意不同于「佩」。","「为坻，为屿，为嵁，为岩」的「嵁」读 kān，指不平的岩石，字形易错。","「蒙络摇缀」的「缀」是绞丝旁，不写「辍」。","「佁然不动」的「佁」读 yǐ；「俶尔远逝」的「俶」读 chù；「翕忽」的「翕」读 xī。","「悄怆幽邃」的「怆」是竖心旁，「邃」是走之底，注意字形。"]}],"questions":[{"id":"p-p8b-xiao-shi-tan-ji-m0","type":"fill","stem":"默写填空：潭中鱼可百许头，______。","answer":"皆若空游无所依。","explain":"出自《小石潭记》（唐·柳宗元）：潭中鱼可百许头，皆若空游无所依。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-xiao-shi-tan-ji-m1","type":"fill","stem":"默写填空：凄神寒骨，______。","answer":"悄怆幽邃。","explain":"出自《小石潭记》（唐·柳宗元）：凄神寒骨，悄怆幽邃。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-xiao-shi-tan-ji-u","type":"fill","stem":"理解性默写：从小丘向西走一百二十步，隔着竹林，听到了水声，好像玉珮玉环相碰发出的声音，心里为之高兴。","answer":"从小丘西行百二十步，隔篁竹，闻水声，如鸣珮环，心乐之。","explain":"出自《小石潭记》（唐·柳宗元）。句意：从小丘向西走一百二十步，隔着竹林，听到了水声，好像玉珮玉环相碰发出的声音，心里为之高兴。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-he-zhou-ji","title":"核舟记（节选）","subtitle":"明·魏学洢","grade":"8b","tags":["文言文","说明文","空间顺序","工艺"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"明·魏学洢"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"魏学洢（1596—1625），字子敬，明末嘉善（今浙江嘉善）人，散文家，是东林党人魏大中的长子，著有《茅檐集》。\n生平经历：他自幼好学，工于文章，以文才知名；明天启年间宦官魏忠贤专权，其父魏大中因上疏弹劾魏忠贤而被逮入京，魏学洢暗中随行、多方营救；父亲冤死狱中后，他扶柩南归，悲愤成疾，不久去世，年仅三十岁左右。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文是一篇说明文，采用「总—分—总」结构，按照空间顺序介绍核舟。选段先总说王叔远技艺之「奇巧」：以「径寸之木」为宫室器皿、鸟兽木石，「罔不因势象形」一句点出其技艺高超，并以「盖大苏泛赤壁云」交代核舟的主题。接着写舟的形制：「长约八分有奇，高可二黍许」用具体数字写其小，与所刻内容之丰富形成对比；「箬篷」「小窗八扇」及窗上对联，可见雕刻之精细。中考常考空间顺序、数字说明与「奇巧」「因势象形」的翻译，注意「洢」「贻」「有奇（jī）」「黍」「箬」「糁」的字形与读音。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"明有奇巧人曰王叔远，能以径寸之木，为宫室、器皿、人物，以至鸟兽、木石，罔不因势象形，各具情态。","n":"","cn":"明朝有个手艺奇妙精巧的人叫王叔远，他能用直径一寸的木头，雕刻成宫室、器具、人物，甚至鸟兽、树木、石头，全都是就着木头原来的样子模拟那些东西的形状，各有各的神情姿态。","parts":[{"t":"明"},{"t":"有","k":9},{"t":"奇","k":11},{"t":"巧人曰王叔远，能以径寸之木，为宫室、器皿、人物，以至鸟兽、木石，"},{"t":"罔","k":5},{"t":"不因势象形，各具情态。"}]},{"t":"尝贻余核舟一，盖大苏泛赤壁云。","n":"","cn":"他曾经赠送给我一只用桃核雕刻成的小船，刻的是苏轼游赤壁的情景。","parts":[{"t":"尝"},{"t":"贻","k":7},{"t":"余核舟一，盖大苏泛赤壁云。"}]},{"t":"舟首尾长约八分有奇，高可二黍许。","n":"","cn":"小船从头到尾长约八分多一点，大约有两个黄米粒那么高。","parts":[{"t":"舟首尾长约八分"},{"t":"有","k":9},{"t":"奇","k":11},{"t":"，高可二"},{"t":"黍","k":12},{"t":"许。"}]},{"t":"中轩敞者为舱，箬篷覆之。","n":"","cn":"中间高起而宽敞的部分是船舱，用箬竹叶做的船篷覆盖着它。","parts":[{"t":"中轩敞者为舱，"},{"t":"箬篷覆之","k":0},{"t":"。"}]},{"t":"旁开小窗，左右各四，共八扇。","n":"","cn":"船舱旁边开有小窗，左右各四扇，一共八扇。","parts":[{"t":"旁开小窗，左右各四，共八扇。"}]},{"t":"启窗而观，雕栏相望焉。","n":"","cn":"打开窗户来看，雕刻着花纹的栏杆左右相对。","parts":[{"t":"启窗而观，雕栏相望焉。"}]},{"t":"闭之，则右刻“山高月小，水落石出”，左刻“清风徐来，水波不兴”，石青糁之。","n":"","cn":"关上窗户，就看到右边刻着“山高月小，水落石出”，左边刻着“清风徐来，水波不兴”，用石青涂在刻着字的凹处。","parts":[{"t":"闭之，则右刻“山高月小，"},{"t":"水","k":13},{"t":"落石出”，左刻“清风徐来，"},{"t":"水","k":13},{"t":"波不兴”，"},{"t":"石青糁之","k":1},{"t":"。"}]},{"t":"船头坐三人，中峨冠而多髯者为东坡，佛印居右，鲁直居左。","n":"","cn":"船头坐着三个人，中间戴着高高的帽子、长着浓密胡须的是苏东坡，佛印坐在右边，黄鲁直坐在左边。","parts":[{"t":"船头坐三人，中峨冠而多髯者为东坡，佛印居右，鲁直居左。"}]}],"words":[{"w":"箬篷覆之","e":"【易错】「箬篷覆之」的「箬」是竹字头；「石青糁之」的「糁」读 shǎn，指涂抹。"},{"w":"石青糁之","e":"【易错】「箬篷覆之」的「箬」是竹字头；「石青糁之」的「糁」读 shǎn，指涂抹。"},{"w":"魏学洢","e":"【易错】作者「魏学洢」的「洢」读 yī，是三点水，注意字形。"},{"w":"无不","e":"【易错】「罔不因势象形」的「罔」意为「无不」，不写「网」。"},{"w":"洢","e":"【易错】作者「魏学洢」的「洢」读 yī，是三点水，注意字形。"},{"w":"罔","e":"【易错】「罔不因势象形」的「罔」意为「无不」，不写「网」。"},{"w":"网","e":"【易错】「罔不因势象形」的「罔」意为「无不」，不写「网」。"},{"w":"贻","e":"【易错】「尝贻余核舟一」的「贻」是贝字旁，指赠送，不写「遗」。"},{"w":"遗","e":"【易错】「尝贻余核舟一」的「贻」是贝字旁，指赠送，不写「遗」。"},{"w":"有","e":"【易错】「长约八分有奇」的「有」同「又」，「奇」读 jī，指零数、余数。"},{"w":"又","e":"【易错】「长约八分有奇」的「有」同「又」，「奇」读 jī，指零数、余数。"},{"w":"奇","e":"【易错】「长约八分有奇」的「有」同「又」，「奇」读 jī，指零数、余数。"},{"w":"黍","e":"【易错】「高可二黍许」的「黍」是黄米，注意下面是「水」的变形，不写「黎」。"},{"w":"水","e":"【易错】「高可二黍许」的「黍」是黄米，注意下面是「水」的变形，不写「黎」。"},{"w":"黎","e":"【易错】「高可二黍许」的「黍」是黄米，注意下面是「水」的变形，不写「黎」。"},{"w":"箬","e":"【易错】「箬篷覆之」的「箬」是竹字头；「石青糁之」的「糁」读 shǎn，指涂抹。"},{"w":"糁","e":"【易错】「箬篷覆之」的「箬」是竹字头；「石青糁之」的「糁」读 shǎn，指涂抹。"}]},{"type":"list","title":"名句","items":["罔不因势象形，各具情态。"]},{"type":"list","title":"背诵提示","items":["作者「魏学洢」的「洢」读 yī，是三点水，注意字形。","「罔不因势象形」的「罔」意为「无不」，不写「网」。","「尝贻余核舟一」的「贻」是贝字旁，指赠送，不写「遗」。","「长约八分有奇」的「有」同「又」，「奇」读 jī，指零数、余数。","「高可二黍许」的「黍」是黄米，注意下面是「水」的变形，不写「黎」。","「箬篷覆之」的「箬」是竹字头；「石青糁之」的「糁」读 shǎn，指涂抹。"]}],"questions":[{"id":"p-p8b-he-zhou-ji-m0","type":"fill","stem":"默写填空：罔不因势象形，______。","answer":"各具情态。","explain":"出自《核舟记（节选）》（明·魏学洢）：罔不因势象形，各具情态。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-he-zhou-ji-u","type":"fill","stem":"理解性默写：明朝有个手艺奇妙精巧的人叫王叔远，他能用直径一寸的木头，雕刻成宫室、器具、人物，甚至鸟兽、树木、石头，全都是就着木头原来的样子模拟那些东西的形状，各有各的神情姿态。","answer":"明有奇巧人曰王叔远，能以径寸之木，为宫室、器皿、人物，以至鸟兽、木石，罔不因势象形，各具情态。","explain":"出自《核舟记（节选）》（明·魏学洢）。句意：明朝有个手艺奇妙精巧的人叫王叔远，他能用直径一寸的木头，雕刻成宫室、器具、人物，甚至鸟兽、树木、石头，全都是就着木头原来的样子模拟那些东西的形状，各有各的神情姿态。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-guan-ju","title":"关雎","subtitle":"先秦·《诗经》","grade":"8b","tags":["诗经","爱情","比兴","重章叠句"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·《诗经》"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者与出处","text":"选自《诗经》，作者不详。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"《关雎》是《诗经》的第一篇，也是「国风」中爱情诗的代表。全诗五章，以「关关雎鸠，在河之洲」起兴，由雎鸠和鸣联想到「窈窕淑女，君子好逑」，引出对美好爱情的追求。第二、三章写男子对淑女的思念：「寤寐求之」「求之不得」「辗转反侧」，写出思慕之深与煎熬之苦；第四、五章写想象中的美满：「琴瑟友之」「钟鼓乐之」，以礼相待，欢愉而庄重。全诗重章叠句、一唱三叹，语言质朴而情感真挚。中考常考比兴手法、重章叠句的作用与「窈窕」「好逑」「寤寐」「芼」等词的解释及「乐」的读音。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"关关雎鸠，在河之洲。窈窕淑女，君子好逑。","n":"","cn":"雎鸠鸟关关地鸣叫，停在河中的小洲上。文静美好善良的姑娘，是君子的好配偶。","parts":[{"t":"关关雎鸠，在河之洲。"},{"t":"窈窕","k":5},{"t":"淑女，君子好"},{"t":"逑","k":7},{"t":"。"}]},{"t":"参差荇菜，左右流之。窈窕淑女，寤寐求之。","n":"","cn":"长短不齐的荇菜，在船的左右两边捞取。文静美好的姑娘，我日日夜夜都在追求她。","parts":[{"t":"参差荇菜","k":0},{"t":"，左右流之。"},{"t":"窈窕","k":5},{"t":"淑女，"},{"t":"寤寐求之","k":1},{"t":"。"}]},{"t":"求之不得，寤寐思服。悠哉悠哉，辗转反侧。","n":"","cn":"追求不到，我日日夜夜思念她。思念绵绵不尽啊，翻来覆去睡不着觉。","parts":[{"t":"求之不得，"},{"t":"寤","k":10},{"t":"寐","k":11},{"t":"思服。悠哉悠哉，"},{"t":"辗转反侧","k":2},{"t":"。"}]},{"t":"参差荇菜，左右采之。窈窕淑女，琴瑟友之。","n":"","cn":"长短不齐的荇菜，在船的左右两边采摘。文静美好的姑娘，我弹琴鼓瑟来亲近她。","parts":[{"t":"参差荇菜","k":0},{"t":"，左右采之。"},{"t":"窈窕","k":5},{"t":"淑女，琴瑟友之。"}]},{"t":"参差荇菜，左右芼之。窈窕淑女，钟鼓乐之。","n":"","cn":"长短不齐的荇菜，在船的左右两边挑选。文静美好的姑娘，我敲钟击鼓使她快乐。","parts":[{"t":"参差荇菜","k":0},{"t":"，"},{"t":"左右芼之","k":3},{"t":"。"},{"t":"窈窕","k":5},{"t":"淑女，"},{"t":"钟鼓乐之","k":4},{"t":"。"}]}],"words":[{"w":"参差荇菜","e":"【易错】「参差荇菜」的「荇」是草字头，读 xìng，不写「杏」。"},{"w":"寤寐求之","e":"【易错】「寤寐求之」的「寤」指醒，「寐」指睡，注意偏旁。"},{"w":"辗转反侧","e":"【易错】「辗转反侧」的「辗」是车字旁，教材作「辗」，不写「展转」。"},{"w":"左右芼之","e":"【易错】「左右芼之」的「芼」读 mào，是草字头，指挑选。"},{"w":"钟鼓乐之","e":"【易错】「钟鼓乐之」的「乐」读 lè，意为「使……快乐」。"},{"w":"窈窕","e":"【易错】「窈窕」二字都是穴字头，不写「窈窕」的形近字；「逑」是走之底，指配偶。"},{"w":"展转","e":"【易错】「辗转反侧」的「辗」是车字旁，教材作「辗」，不写「展转」。"},{"w":"逑","e":"【易错】「窈窕」二字都是穴字头，不写「窈窕」的形近字；「逑」是走之底，指配偶。"},{"w":"荇","e":"【易错】「参差荇菜」的「荇」是草字头，读 xìng，不写「杏」。"},{"w":"杏","e":"【易错】「参差荇菜」的「荇」是草字头，读 xìng，不写「杏」。"},{"w":"寤","e":"【易错】「寤寐求之」的「寤」指醒，「寐」指睡，注意偏旁。"},{"w":"寐","e":"【易错】「寤寐求之」的「寤」指醒，「寐」指睡，注意偏旁。"},{"w":"辗","e":"【易错】「辗转反侧」的「辗」是车字旁，教材作「辗」，不写「展转」。"},{"w":"芼","e":"【易错】「左右芼之」的「芼」读 mào，是草字头，指挑选。"},{"w":"乐","e":"【易错】「钟鼓乐之」的「乐」读 lè，意为「使……快乐」。"}]},{"type":"list","title":"名句","items":["关关雎鸠，在河之洲。窈窕淑女，君子好逑。"]},{"type":"list","title":"背诵提示","items":["「窈窕」二字都是穴字头，不写「窈窕」的形近字；「逑」是走之底，指配偶。","「参差荇菜」的「荇」是草字头，读 xìng，不写「杏」。","「寤寐求之」的「寤」指醒，「寐」指睡，注意偏旁。","「辗转反侧」的「辗」是车字旁，教材作「辗」，不写「展转」。","「左右芼之」的「芼」读 mào，是草字头，指挑选。","「钟鼓乐之」的「乐」读 lè，意为「使……快乐」。"]}],"questions":[{"id":"p-p8b-guan-ju-m0","type":"fill","stem":"默写填空：关关雎鸠，______。","answer":"在河之洲。窈窕淑女。","explain":"出自《关雎》（先秦·《诗经》）：关关雎鸠，在河之洲。窈窕淑女，君子好逑。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-guan-ju-u","type":"fill","stem":"理解性默写：雎鸠鸟关关地鸣叫，停在河中的小洲上。文静美好善良的姑娘，是君子的好配偶。","answer":"关关雎鸠，在河之洲。窈窕淑女，君子好逑。","explain":"出自《关雎》（先秦·《诗经》）。句意：雎鸠鸟关关地鸣叫，停在河中的小洲上。文静美好善良的姑娘，是君子的好配偶。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-jian-jia","title":"蒹葭","subtitle":"先秦·《诗经》","grade":"8b","tags":["诗经","思慕","起兴","重章叠句","朦胧美"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·《诗经》"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者与出处","text":"选自《诗经》，作者不详。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"《蒹葭》是《诗经·秦风》中的名篇。全诗三章，每章以「蒹葭苍苍，白露为霜」起兴，用秋日芦苇、白露凝霜的凄清景象烘托氛围，为「伊人」的出现营造朦胧意境。接着写追寻的过程：「溯洄」「溯游」反复，「道阻且长」「且跻」「且右」层层推进，写出路途的艰险；而「宛在水中央」「宛在水中坻」「宛在水中沚」又写「伊人」可望而不可即。重章叠句、一唱三叹，含蓄地抒发了对美好事物的执著追求与求而不得的惆怅。中考常考起兴手法、重章叠句的表达效果与「伊人」的多重理解，注意「晞」「湄」「跻」「涘」「沚」的字形。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"蒹葭苍苍，白露为霜。所谓伊人，在水一方。","n":"","cn":"河边芦苇青苍苍，清晨的露水凝结成霜。我所思念的那个人，就在河水的那一边。","parts":[{"t":"蒹葭","k":4},{"t":"苍苍，白露为霜。所谓伊人，在水一方。"}]},{"t":"溯洄从之，道阻且长。溯游从之，宛在水中央。","n":"","cn":"逆流而上去追寻她，道路险阻又漫长。顺流而下去追寻她，（她）仿佛就在水的中央。","parts":[{"t":"溯洄从之，道阻且长。溯游从之，宛在水中央。"}]},{"t":"蒹葭萋萋，白露未晞。所谓伊人，在水之湄。","n":"","cn":"河边芦苇茂盛，清晨的露水还没有干。我所思念的那个人，就在河岸的水边。","parts":[{"t":"蒹葭","k":4},{"t":"萋萋，"},{"t":"白露未晞","k":0},{"t":"。所谓伊人，"},{"t":"在水之湄","k":1},{"t":"。"}]},{"t":"溯洄从之，道阻且跻。溯游从之，宛在水中坻。","n":"","cn":"逆流而上去追寻她，道路险阻又高陡。顺流而下去追寻她，（她）仿佛就在水中的小洲上。","parts":[{"t":"溯洄从之，"},{"t":"道阻且跻","k":2},{"t":"。溯游从之，宛在水中坻。"}]},{"t":"蒹葭采采，白露未已。所谓伊人，在水之涘。","n":"","cn":"河边芦苇繁茂，清晨的露水还没有干透。我所思念的那个人，就在河岸的水边。","parts":[{"t":"蒹葭","k":4},{"t":"采采，白露未已。所谓伊人，"},{"t":"在水之涘","k":3},{"t":"。"}]},{"t":"溯洄从之，道阻且右。溯游从之，宛在水中沚。","n":"","cn":"逆流而上去追寻她，道路险阻又迂回曲折。顺流而下去追寻她，（她）仿佛就在水中的小块陆地上。","parts":[{"t":"溯洄从之，道阻且右。溯游从之，宛在水中"},{"t":"沚","k":13},{"t":"。"}]}],"words":[{"w":"白露未晞","e":"【易错】「白露未晞」的「晞」读 xī，是日字旁，指干，不写「稀」。"},{"w":"在水之湄","e":"【易错】「在水之湄」的「湄」是三点水，指水边，不写「眉」。"},{"w":"道阻且跻","e":"【易错】「道阻且跻」的「跻」读 jī，是足字旁，指升高、登上。"},{"w":"在水之涘","e":"【易错】「在水之涘」的「涘」读 sì，是三点水，指水边。"},{"w":"蒹葭","e":"【易错】「蒹葭」二字都是草字头，读 jiān jiā，不写「兼」「佳」。"},{"w":"兼","e":"【易错】「蒹葭」二字都是草字头，读 jiān jiā，不写「兼」「佳」。"},{"w":"佳","e":"【易错】「蒹葭」二字都是草字头，读 jiān jiā，不写「兼」「佳」。"},{"w":"晞","e":"【易错】「白露未晞」的「晞」读 xī，是日字旁，指干，不写「稀」。"},{"w":"稀","e":"【易错】「白露未晞」的「晞」读 xī，是日字旁，指干，不写「稀」。"},{"w":"湄","e":"【易错】「在水之湄」的「湄」是三点水，指水边，不写「眉」。"},{"w":"眉","e":"【易错】「在水之湄」的「湄」是三点水，指水边，不写「眉」。"},{"w":"跻","e":"【易错】「道阻且跻」的「跻」读 jī，是足字旁，指升高、登上。"},{"w":"涘","e":"【易错】「在水之涘」的「涘」读 sì，是三点水，指水边。"},{"w":"沚","e":"【易错】「宛在水中沚」的「沚」读 zhǐ，是三点水，指水中的小块陆地。"}]},{"type":"list","title":"名句","items":["蒹葭苍苍，白露为霜。所谓伊人，在水一方。"]},{"type":"list","title":"背诵提示","items":["「蒹葭」二字都是草字头，读 jiān jiā，不写「兼」「佳」。","「白露未晞」的「晞」读 xī，是日字旁，指干，不写「稀」。","「在水之湄」的「湄」是三点水，指水边，不写「眉」。","「道阻且跻」的「跻」读 jī，是足字旁，指升高、登上。","「在水之涘」的「涘」读 sì，是三点水，指水边。","「宛在水中沚」的「沚」读 zhǐ，是三点水，指水中的小块陆地。"]}],"questions":[{"id":"p-p8b-jian-jia-m0","type":"fill","stem":"默写填空：蒹葭苍苍，______。","answer":"白露为霜。所谓伊人。","explain":"出自《蒹葭》（先秦·《诗经》）：蒹葭苍苍，白露为霜。所谓伊人，在水一方。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-jian-jia-u","type":"fill","stem":"理解性默写：河边芦苇青苍苍，清晨的露水凝结成霜。我所思念的那个人，就在河水的那一边。","answer":"蒹葭苍苍，白露为霜。所谓伊人，在水一方。","explain":"出自《蒹葭》（先秦·《诗经》）。句意：河边芦苇青苍苍，清晨的露水凝结成霜。我所思念的那个人，就在河水的那一边。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-bei-ming-you-yu","title":"北冥有鱼","subtitle":"先秦·庄子","grade":"8b","tags":["文言文","寓言","想象","夸张","庄子"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·庄子"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"庄子名周，战国时期宋国蒙人，道家学派的代表人物，与老子并称“老庄”。他继承并发展了老子的思想，主张顺应自然、逍遥无待，鄙视功名利禄，是先秦诸子中最富想象力的散文家之一。\n成书背景：《庄子》一书为庄周及其后学所作，并非出自一人之手；今本三十三篇，分内篇、外篇、杂篇，一般认为内篇是庄周本人的作品。《北冥有鱼》节选自《庄子·逍遥游》，写鲲化为鹏、鹏徙南冥的奇幻景象。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文节选自《庄子·逍遥游》，以奇幻的想象塑造了鲲鹏形象。开篇写鲲之大「不知其几千里」，鲲化为鹏，鹏之背亦「不知其几千里」，「怒而飞，其翼若垂天之云」，极尽夸张，境界雄奇。接着借《齐谐》之言写鹏徙南冥的壮观：「水击三千里，抟扶摇而上者九万里」，气势磅礴。末以「野马」「尘埃」作比，说明万物皆有所待；又连发两问写天之色与天之高远，并以「其视下也，亦若是则已矣」设想大鹏俯视下界的景象。中考常考夸张与想象的写法、借寓言说理的特点，以及「冥」「抟」「野马」「邪」等词的解释与通假。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"北冥有鱼，其名为鲲。","n":"","cn":"北海有一条鱼，它的名字叫鲲。","parts":[{"t":"北冥有鱼","k":0},{"t":"，"},{"t":"其名为鲲","k":1},{"t":"。"}]},{"t":"鲲之大，不知其几千里也；化而为鸟，其名为鹏。","n":"","cn":"鲲非常大，不知道有几千里；它变化为鸟，名字叫鹏。","parts":[{"t":"鲲","k":8},{"t":"之大，不知其几千里也；化而为鸟，其名为鹏。"}]},{"t":"鹏之背，不知其几千里也；怒而飞，其翼若垂天之云。","n":"","cn":"鹏的脊背，不知道有几千里；它奋起而飞时，翅膀就像悬挂在天空的云。","parts":[{"t":"鹏之背，不知其几千里也；怒而飞，其翼若"},{"t":"垂","k":12},{"t":"天之云。"}]},{"t":"是鸟也，海运则将徙于南冥。南冥者，天池也。","n":"","cn":"这只鸟，海水运动时就将迁往南海。南海是天然形成的水池。","parts":[{"t":"是鸟也，海运则将徙于南"},{"t":"冥","k":5},{"t":"。南"},{"t":"冥","k":5},{"t":"者，天池也。"}]},{"t":"《齐谐》者，志怪者也。","n":"","cn":"《齐谐》是一部专门记载怪异事情的书。","parts":[{"t":"《齐谐》"},{"t":"者，志怪者也。"}]},{"t":"《谐》之言曰：“鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里，去以六月息者也。”","n":"","cn":"《齐谐》上记载说：“鹏鸟迁徙到南海时，翅膀拍击水面激起三千里的波涛，乘着旋风盘旋飞至九万里的高空，它是凭借着六月的大风离开的。”","parts":[{"t":"《谐》"},{"t":"之言曰：“鹏之徙于南"},{"t":"冥","k":5},{"t":"也，水击三千里，"},{"t":"抟","k":9},{"t":"扶摇而上者九万里，去以六月息者也。”"}]},{"t":"野马也，尘埃也，生物之以息相吹也。","n":"","cn":"山野中的雾气、空气中的尘埃，都是生物用气息吹拂的结果。","parts":[{"t":"野马也","k":3},{"t":"，尘埃也，生物之以息相吹也。"}]},{"t":"天之苍苍，其正色邪？其远而无所至极邪？其视下也，亦若是则已矣。","n":"","cn":"天色湛蓝，是它真正的颜色吗？还是因为天空高远而看不到尽头呢？大鹏从天空往下看，也不过像人在地面上看天一样罢了。","parts":[{"t":"天之苍苍，"},{"t":"其正色邪","k":2},{"t":"？其远而无所至极"},{"t":"邪","k":10},{"t":"？其视下也，亦若是则已矣。"}]}],"words":[{"w":"北冥有鱼","e":"【易错】「北冥有鱼」的「冥」同「溟」，指大海，不写「暝」。"},{"w":"其名为鲲","e":"【易错】「其名为鲲」的「鲲」是鱼字旁，注意字形。"},{"w":"其正色邪","e":"【易错】「其正色邪」的「邪」同「耶」，是句末语气词，读 yé。"},{"w":"野马也","e":"【易错】「野马也」的「野马」指山野中的雾气，不可按今义理解。"},{"w":"野马","e":"【易错】「野马也」的「野马」指山野中的雾气，不可按今义理解。"},{"w":"冥","e":"【易错】「北冥有鱼」的「冥」同「溟」，指大海，不写「暝」。"},{"w":"溟","e":"【易错】「北冥有鱼」的「冥」同「溟」，指大海，不写「暝」。"},{"w":"暝","e":"【易错】「北冥有鱼」的「冥」同「溟」，指大海，不写「暝」。"},{"w":"鲲","e":"【易错】「其名为鲲」的「鲲」是鱼字旁，注意字形。"},{"w":"抟","e":"【易错】「抟扶摇而上者九万里」的「抟」读 tuán，是提手旁，指盘旋飞翔。"},{"w":"邪","e":"【易错】「其正色邪」的「邪」同「耶」，是句末语气词，读 yé。"},{"w":"耶","e":"【易错】「其正色邪」的「邪」同「耶」，是句末语气词，读 yé。"},{"w":"垂","e":"【易错】「其翼若垂天之云」的「垂」指悬挂，不写「陲」。"},{"w":"陲","e":"【易错】「其翼若垂天之云」的「垂」指悬挂，不写「陲」。"}]},{"type":"list","title":"名句","items":["水击三千里，抟扶摇而上者九万里。","其翼若垂天之云。"]},{"type":"list","title":"背诵提示","items":["「北冥有鱼」的「冥」同「溟」，指大海，不写「暝」。","「其名为鲲」的「鲲」是鱼字旁，注意字形。","「抟扶摇而上者九万里」的「抟」读 tuán，是提手旁，指盘旋飞翔。","「野马也」的「野马」指山野中的雾气，不可按今义理解。","「其正色邪」的「邪」同「耶」，是句末语气词，读 yé。","「其翼若垂天之云」的「垂」指悬挂，不写「陲」。"]}],"questions":[{"id":"p-p8b-bei-ming-you-yu-m0","type":"fill","stem":"默写填空：水击三千里，______。","answer":"抟扶摇而上者九万里。","explain":"出自《北冥有鱼》（先秦·庄子）：水击三千里，抟扶摇而上者九万里。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-bei-ming-you-yu-u","type":"fill","stem":"理解性默写：北海有一条鱼，它的名字叫鲲。","answer":"北冥有鱼，其名为鲲。","explain":"出自《北冥有鱼》（先秦·庄子）。句意：北海有一条鱼，它的名字叫鲲。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-sui-you-jia-yao","title":"虽有嘉肴","subtitle":"先秦·《礼记》","grade":"8b","tags":["文言文","议论","教育","类比论证","礼记"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·《礼记》"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者与出处","text":"选自《礼记》，作者不详。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文节选自《礼记·学记》，是一篇短小精悍的议论文。作者先以「虽有嘉肴，弗食，不知其旨」作类比，引出「虽有至道，弗学，不知其善」，说明学习的重要性；接着提出「学然后知不足，教然后知困」，并进一步指出「知不足，然后能自反也；知困，然后能自强也」，层层推进，最后以「故曰：教学相长也」点明中心论点，并以《兑命》「学学半」加以印证。全文多用对偶与排比，句式整齐，说理透彻。中考常考类比论证、引用论证与中心论点的概括，注意「嘉肴」「弗」「旨」「自强（qiǎng）」「长（zhǎng）」「兑（yuè）」的字形与读音。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"虽有嘉肴，弗食，不知其旨也；虽有至道，弗学，不知其善也。","n":"","cn":"即使有美味的菜肴，不去品尝，就不知道它的味美；即使有最好的道理，不去学习，就不知道它的好处。","parts":[{"t":"虽有嘉肴","k":0},{"t":"，弗食，不知其"},{"t":"旨","k":9},{"t":"也；虽有至道，弗"},{"t":"学","k":15},{"t":"，不知其善也。"}]},{"t":"是故学然后知不足，教然后知困。","n":"","cn":"所以学习之后才知道自己的不足，教人之后才知道自己有困惑不通的地方。","parts":[{"t":"是故"},{"t":"学","k":15},{"t":"然后知不足，教然后知困。"}]},{"t":"知不足，然后能自反也；知困，然后能自强也。","n":"","cn":"知道了自己的不足，然后才能自我反思；知道了自己有困惑不通的地方，然后才能自我勉励。","parts":[{"t":"知不足，然后能自反也；知困，然后能自"},{"t":"强","k":11},{"t":"也。"}]},{"t":"故曰：教学相长也。","n":"所以说：教和学是互相推动、互相促进的。","cn":"","parts":[{"t":"故曰：教"},{"t":"学","k":15},{"t":"相"},{"t":"长","k":12},{"t":"也。"}]},{"t":"《兑命》曰“学学半”，其此之谓乎！","n":"","cn":"《兑命》说“教人是学习的一半”，大概说的就是这个道理吧！","parts":[{"t":"《兑命》"},{"t":"曰“"},{"t":"学学半","k":2},{"t":"”，其此之谓乎！"}]}],"words":[{"w":"虽有嘉肴","e":"【易错】「虽有嘉肴」的「嘉」是「美好」之意，「肴」是月字旁，不写「佳」「淆」。"},{"w":"所以说","e":"教和学是互相推动、互相促进的"},{"w":"学学半","e":"【易错】「学学半」前一个「学」同「敩」，读 xiào，指教导。"},{"w":"美好","e":"【易错】「虽有嘉肴」的「嘉」是「美好」之意，「肴」是月字旁，不写「佳」「淆」。"},{"w":"勉励","e":"【易错】「然后能自强也」的「强」读 qiǎng，意为「勉励」。"},{"w":"嘉","e":"【易错】「虽有嘉肴」的「嘉」是「美好」之意，「肴」是月字旁，不写「佳」「淆」。"},{"w":"肴","e":"【易错】「虽有嘉肴」的「嘉」是「美好」之意，「肴」是月字旁，不写「佳」「淆」。"},{"w":"佳","e":"【易错】「虽有嘉肴」的「嘉」是「美好」之意，「肴」是月字旁，不写「佳」「淆」。"},{"w":"淆","e":"【易错】「虽有嘉肴」的「嘉」是「美好」之意，「肴」是月字旁，不写「佳」「淆」。"},{"w":"旨","e":"【易错】「不知其旨也」的「旨」指味美，不写「指」。"},{"w":"指","e":"【易错】「不知其旨也」的「旨」指味美，不写「指」。"},{"w":"强","e":"【易错】「然后能自强也」的「强」读 qiǎng，意为「勉励」。"},{"w":"长","e":"【易错】「教学相长也」的「长」读 zhǎng，意为「增长、促进」。"},{"w":"兑","e":"【易错】「《兑命》」的「兑」读 yuè，同「说」，指《说命》。"},{"w":"说","e":"【易错】「《兑命》」的「兑」读 yuè，同「说」，指《说命》。"},{"w":"学","e":"【易错】「学学半」前一个「学」同「敩」，读 xiào，指教导。"},{"w":"敩","e":"【易错】「学学半」前一个「学」同「敩」，读 xiào，指教导。"}]},{"type":"h","text":"译文"},{"type":"p","text":"即使有美味的菜肴，不吃就不知其味美；即使有最好的道理，不学就不知它的好处。所以学习之后才知道自己的不足，教人之后才知道自己有困惑不通之处。知道不足，才能自我反省；知道困惑，才能自我勉励。所以说：教与学是相互促进的。《兑命》说“教人是学习的一半”，大概说的就是这个道理吧！"},{"type":"list","title":"名句","items":["教学相长也。","学然后知不足，教然后知困。"]},{"type":"list","title":"背诵提示","items":["「虽有嘉肴」的「嘉」是「美好」之意，「肴」是月字旁，不写「佳」「淆」。","「不知其旨也」的「旨」指味美，不写「指」。","「然后能自强也」的「强」读 qiǎng，意为「勉励」。","「教学相长也」的「长」读 zhǎng，意为「增长、促进」。","「《兑命》」的「兑」读 yuè，同「说」，指《说命》。","「学学半」前一个「学」同「敩」，读 xiào，指教导。"]}],"questions":[{"id":"p-p8b-sui-you-jia-yao-m0","type":"fill","stem":"默写填空：学然后知不足，______。","answer":"教然后知困。","explain":"出自《虽有嘉肴》（先秦·《礼记》）：学然后知不足，教然后知困。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-sui-you-jia-yao-u","type":"fill","stem":"理解性默写：即使有美味的菜肴，不去品尝，就不知道它的味美；即使有最好的道理，不去学习，就不知道它的好处。","answer":"虽有嘉肴，弗食，不知其旨也；虽有至道，弗学，不知其善也。","explain":"出自《虽有嘉肴》（先秦·《礼记》）。句意：即使有美味的菜肴，不去品尝，就不知道它的味美；即使有最好的道理，不去学习，就不知道它的好处。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-da-dao-zhi-xing-ye","title":"大道之行也","subtitle":"先秦·《礼记》","grade":"8b","tags":["文言文","议论","理想社会","排比","礼记"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·《礼记》"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者与出处","text":"选自《礼记》，作者不详。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文节选自《礼记·礼运》，是儒家关于「大同」社会的经典论述。开篇「大道之行也，天下为公」总提纲领；接着从三个方面展开：「选贤与能，讲信修睦」写用人制度与社会风尚，「人不独亲其亲，不独子其子」及「老有所终，壮有所用，幼有所长」写人人得到关爱与安置，「货恶其弃于地也」「力恶其不出于身也」写人尽其力、物尽其用；最后以「谋闭而不兴」「外户而不闭」写社会安定，并以「是谓大同」收束。中考常考总分总结构、排比句的作用与「与」「矜」「分」「恶」的读音及通假，注意「睦」「矜」「寡」「废疾」「盗窃乱贼」的字形。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"大道之行也，天下为公。","n":"","cn":"在大道施行的时候，天下是天下人所共有的。","parts":[{"t":"大道之行也，天下为公。"}]},{"t":"选贤与能，讲信修睦。","n":"","cn":"把品德高尚的人、有才能的人选拔出来（为大家办事），（人人）讲求诚信，培养和睦（气氛）。","parts":[{"t":"选贤与能","k":0},{"t":"，"},{"t":"讲信修睦","k":1},{"t":"。"}]},{"t":"故人不独亲其亲，不独子其子，使老有所终，壮有所用，幼有所长，矜、寡、孤、独、废疾者皆有所养，男有分，女有归。","n":"","cn":"因此人们不只是以自己的亲人为亲，不只是以自己的子女为子女，要使老年人能颐养天年，中年人能为社会效力，幼童能顺利成长，使老而无妻的人、老而无夫的人、幼年丧父的人、老而无子的人、有残疾而不能做事的人都能得到供养，男子有职业，女子有归宿。","parts":[{"t":"故人不独亲其亲，不独子其子，使老有所终，壮有所用，幼有所长，"},{"t":"矜","k":9},{"t":"、寡、孤、独、废疾者皆有所养，"},{"t":"男有分","k":2},{"t":"，女有归。"}]},{"t":"货恶其弃于地也，不必藏于己；","n":"","cn":"对于财货，人们憎恶把它扔在地上的行为，（却）不一定要自己私藏；","parts":[{"t":"货"},{"t":"恶","k":12},{"t":"其弃于地也，不必藏于己；"}]},{"t":"力恶其不出于身也，不必为己。","n":"","cn":"对于力气，人们憎恶它不出于自己，（却）不一定是为了自己谋私利。","parts":[{"t":"力"},{"t":"恶","k":12},{"t":"其不出于身也，不必为己。"}]},{"t":"是故谋闭而不兴，盗窃乱贼而不作，故外户而不闭。","n":"","cn":"因此（奸诈之心）被遏制而不会兴起，盗窃、造反和害人的事情不会发生，所以（家家户户）都不用关大门了。","parts":[{"t":"是故谋闭而不兴，盗窃"},{"t":"乱贼","k":4},{"t":"而不"},{"t":"作","k":13},{"t":"，故外户而不闭。"}]},{"t":"是谓大同。","n":"","cn":"这就叫做「大同」。","parts":[{"t":"是谓大同。"}]}],"words":[{"w":"选贤与能","e":"【易错】「选贤与能」的「与」同「举」，指推举，读 jǔ。"},{"w":"讲信修睦","e":"【易错】「讲信修睦」的「睦」是目字旁，指和睦，不写「穆」。"},{"w":"男有分","e":"【易错】「男有分」的「分」读 fèn，指职分、职业。"},{"w":"憎恶","e":"【易错】「货恶其弃于地也」的「恶」读 wù，意为「憎恶」。"},{"w":"乱贼","e":"【易错】「盗窃乱贼而不作」的「乱贼」指造反害人的人，「作」指兴起。"},{"w":"与","e":"【易错】「选贤与能」的「与」同「举」，指推举，读 jǔ。"},{"w":"举","e":"【易错】「选贤与能」的「与」同「举」，指推举，读 jǔ。"},{"w":"睦","e":"【易错】「讲信修睦」的「睦」是目字旁，指和睦，不写「穆」。"},{"w":"穆","e":"【易错】「讲信修睦」的「睦」是目字旁，指和睦，不写「穆」。"},{"w":"矜","e":"【易错】「矜、寡、孤、独」的「矜」同「鳏」，读 guān，指老而无妻的人。"},{"w":"鳏","e":"【易错】「矜、寡、孤、独」的「矜」同「鳏」，读 guān，指老而无妻的人。"},{"w":"分","e":"【易错】「男有分」的「分」读 fèn，指职分、职业。"},{"w":"恶","e":"【易错】「货恶其弃于地也」的「恶」读 wù，意为「憎恶」。"},{"w":"作","e":"【易错】「盗窃乱贼而不作」的「乱贼」指造反害人的人，「作」指兴起。"}]},{"type":"list","title":"名句","items":["大道之行也，天下为公。","老有所终，壮有所用，幼有所长。"]},{"type":"list","title":"背诵提示","items":["「选贤与能」的「与」同「举」，指推举，读 jǔ。","「讲信修睦」的「睦」是目字旁，指和睦，不写「穆」。","「矜、寡、孤、独」的「矜」同「鳏」，读 guān，指老而无妻的人。","「男有分」的「分」读 fèn，指职分、职业。","「货恶其弃于地也」的「恶」读 wù，意为「憎恶」。","「盗窃乱贼而不作」的「乱贼」指造反害人的人，「作」指兴起。"]}],"questions":[{"id":"p-p8b-da-dao-zhi-xing-ye-m0","type":"fill","stem":"默写填空：大道之行也，______。","answer":"天下为公。","explain":"出自《大道之行也》（先秦·《礼记》）：大道之行也，天下为公。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-da-dao-zhi-xing-ye-m1","type":"fill","stem":"默写填空：老有所终，______。","answer":"壮有所用。","explain":"出自《大道之行也》（先秦·《礼记》）：老有所终，壮有所用，幼有所长。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-da-dao-zhi-xing-ye-u","type":"fill","stem":"理解性默写：在大道施行的时候，天下是天下人所共有的。","answer":"大道之行也，天下为公。","explain":"出自《大道之行也》（先秦·《礼记》）。句意：在大道施行的时候，天下是天下人所共有的。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-ma-shuo","title":"马说","subtitle":"唐·韩愈","grade":"8b","tags":["文言文","议论","托物寓意","人才","韩愈"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·韩愈"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"韩愈（768—824），字退之，河南河阳（今河南孟州）人，因祖籍昌黎而世称韩昌黎，又因谥号为“文”而称韩文公，唐代文学家、思想家、教育家。\n生平经历：他幼年丧父，由兄嫂抚养成人，读书极为刻苦，二十五岁考中进士；任监察御史时因上疏言事被贬为阳山令，后来因上《论佛骨表》触怒宪宗，被贬为潮州刺史，仕途几度沉浮；他一生以复兴儒学为己任，反对六朝以来浮华空疏的骈文，提倡写内容充实、文从字顺的散文。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文是韩愈托物寓意的名篇。第一段以「世有伯乐，然后有千里马」开篇，提出「千里马常有，而伯乐不常有」的论断，为全文立论；接着写千里马「祇辱于奴隶人之手，骈死于槽枥之间」的悲惨遭遇。第二段从「食」与「力」入手，写食马者不知其能千里而食，致使「食不饱，力不足，才美不外见」，连常马都不如，并以反问痛斥不识人才者；第三段写食马者「策之不以其道，食之不能尽其材，鸣之而不能通其意」，却大呼「天下无马」，最后以「其真无马邪？其真不知马也」作结。全文托物寓意，借千里马被埋没讽刺统治者不能识别、重用人才。中考常考托物寓意的写法与「食」「见」「策」「材」「邪」的读音与通假，注意「祇」「骈」「槽枥」的字形。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"世有伯乐，然后有千里马。","n":"","cn":"世上有了伯乐，然后才会有千里马。","parts":[{"t":"世有伯乐，然后有千里马。"}]},{"t":"千里马常有，而伯乐不常有。","n":"","cn":"千里马经常有，可是伯乐却不常有。","parts":[{"t":"千里马常有，而伯乐不常有。"}]},{"t":"故虽有名马，祇辱于奴隶人之手，骈死于槽枥之间，不以千里称也。","n":"","cn":"所以即使有名贵的马，也只能在仆役的手下受屈辱，和普通的马一同死在马槽之间，不能凭借日行千里的能力而著称。","parts":[{"t":"故虽有名马，"},{"t":"祇","k":2},{"t":"辱于奴隶人之手，"},{"t":"骈","k":3},{"t":"死于"},{"t":"槽枥","k":1},{"t":"之间，不以千里称也。"}]},{"t":"马之千里者，一食或尽粟一石。","n":"","cn":"日行千里的马，一顿有时能吃完一石粮食。","parts":[{"t":"马之千里者，一"},{"t":"食","k":5},{"t":"或尽粟一"},{"t":"石","k":6},{"t":"。"}]},{"t":"食马者不知其能千里而食也。","n":"","cn":"喂马的人不知道它能日行千里，把它当作普通马来喂养。","parts":[{"t":"食马者","k":0},{"t":"不知其能千里而"},{"t":"食","k":5},{"t":"也。"}]},{"t":"是马也，虽有千里之能，食不饱，力不足，才美不外见，且欲与常马等不可得，安求其能千里也？","n":"","cn":"这样的马，虽然有日行千里的能力，却吃不饱，力气不足，才能和美好的素质不能表现在外面，想要和普通的马一样尚且办不到，怎么能要求它日行千里呢？","parts":[{"t":"是马也，虽有千里之能，"},{"t":"食","k":5},{"t":"不饱，力不足，"},{"t":"才","k":9},{"t":"美不外"},{"t":"见","k":10},{"t":"，且欲与常马等不可得，安求其能千里也？"}]},{"t":"策之不以其道，食之不能尽其材，鸣之而不能通其意，执策而临之，曰：“天下无马！”","n":"","cn":"驱使它，不按照驱使千里马的正确方法；喂养它，不能使它充分发挥才能；听它鸣叫，却不能通晓它的意思。（反而）拿着鞭子站在它面前说：“天下没有千里马！”","parts":[{"t":"策之不以其道，"},{"t":"食","k":5},{"t":"之不能尽其"},{"t":"材","k":8},{"t":"，鸣之而不能通其意，执策而临之，曰：“天下无马！”"}]},{"t":"呜呼！其真无马邪？其真不知马也！","n":"","cn":"唉！难道真的没有千里马吗？恐怕是他们真不认识千里马吧！","parts":[{"t":"呜呼！其真无马"},{"t":"邪","k":12},{"t":"？其真不知马也！"}]}],"words":[{"w":"食马者","e":"【易错】「食马者」的「食」同「饲」，读 sì，指喂养；「食之不能尽其材」的「材」同「才」。"},{"w":"槽枥","e":"【易错】「骈死于槽枥之间」的「骈」是马字旁，指并列；「槽枥」的「枥」是木字旁，指马槽。"},{"w":"祇","e":"【易错】「祇辱于奴隶人之手」的「祇」读 zhǐ，教材作「祇」，意为「只、仅」。"},{"w":"骈","e":"【易错】「骈死于槽枥之间」的「骈」是马字旁，指并列；「槽枥」的「枥」是木字旁，指马槽。"},{"w":"枥","e":"【易错】「骈死于槽枥之间」的「骈」是马字旁，指并列；「槽枥」的「枥」是木字旁，指马槽。"},{"w":"食","e":"【易错】「一食或尽粟一石」的「食」读 shí，指吃；「石」读 dàn，是容量单位。"},{"w":"石","e":"【易错】「一食或尽粟一石」的「食」读 shí，指吃；「石」读 dàn，是容量单位。"},{"w":"饲","e":"【易错】「食马者」的「食」同「饲」，读 sì，指喂养；「食之不能尽其材」的「材」同「才」。"},{"w":"材","e":"【易错】「食马者」的「食」同「饲」，读 sì，指喂养；「食之不能尽其材」的「材」同「才」。"},{"w":"才","e":"【易错】「食马者」的「食」同「饲」，读 sì，指喂养；「食之不能尽其材」的「材」同「才」。"},{"w":"见","e":"【易错】「才美不外见」的「见」同「现」，读 xiàn，指表现。"},{"w":"现","e":"【易错】「才美不外见」的「见」同「现」，读 xiàn，指表现。"},{"w":"邪","e":"【易错】「其真无马邪」的「邪」同「耶」，是句末语气词，读 yé。"},{"w":"耶","e":"【易错】「其真无马邪」的「邪」同「耶」，是句末语气词，读 yé。"}]},{"type":"list","title":"名句","items":["世有伯乐，然后有千里马。","其真无马邪？其真不知马也！"]},{"type":"list","title":"背诵提示","items":["「祇辱于奴隶人之手」的「祇」读 zhǐ，教材作「祇」，意为「只、仅」。","「骈死于槽枥之间」的「骈」是马字旁，指并列；「槽枥」的「枥」是木字旁，指马槽。","「一食或尽粟一石」的「食」读 shí，指吃；「石」读 dàn，是容量单位。","「食马者」的「食」同「饲」，读 sì，指喂养；「食之不能尽其材」的「材」同「才」。","「才美不外见」的「见」同「现」，读 xiàn，指表现。","「其真无马邪」的「邪」同「耶」，是句末语气词，读 yé。"]}],"questions":[{"id":"p-p8b-ma-shuo-m0","type":"fill","stem":"默写填空：世有伯乐，______。","answer":"然后有千里马。","explain":"出自《马说》（唐·韩愈）：世有伯乐，然后有千里马。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-ma-shuo-u","type":"fill","stem":"理解性默写：世上有了伯乐，然后才会有千里马。","answer":"世有伯乐，然后有千里马。","explain":"出自《马说》（唐·韩愈）。句意：世上有了伯乐，然后才会有千里马。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-mao-wu-wei-qiu-feng-suo-po-ge","title":"茅屋为秋风所破歌","subtitle":"唐·杜甫","grade":"8b","tags":["忧国忧民","叙事诗","歌行体","杜甫","推己及人"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·杜甫"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"杜甫（712—770），字子美，自号少陵野老，唐代伟大的现实主义诗人，被后人尊称为“诗圣”，他的诗广泛而深刻地反映了唐代由盛转衰时期的社会现实，被称为“诗史”。\n生平经历：青年时曾漫游吴越齐赵，并与李白相识；后困居长安十年，屡试不第；安史之乱中被叛军俘获，逃出后任左拾遗，又因直言进谏被贬；晚年流寓成都，在浣花溪畔建草堂，后又漂泊于夔州、湖湘一带，770年病逝于湘江舟中。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本诗是杜甫寓居成都草堂时所作的歌行体诗。第一节写秋风破屋：以「怒号」写风声，「卷」「飞」「洒」「挂罥」「飘转」连用动词，写出茅草漫天飞舞的惨状，画面感极强。第二节写群童抱茅，以「欺我老无力」写老病的无奈与「倚杖自叹息」的悲凉。第三节写夜雨之苦：「布衾多年冷似铁」「床头屋漏无干处，雨脚如麻未断绝」，由风雨之苦写到「自经丧乱少睡眠」的身世之痛。第四节由己及人，高声呼告「安得广厦千万间，大庇天下寒士俱欢颜」，甚至愿「吾庐独破受冻死亦足」，表现了推己及人、忧国忧民的博大胸怀。中考常考动词连用的表达效果与结尾所抒发的情感，注意「号（háo）」「重（chóng）」「罥」「衾」「厦」「庇」的字形与读音。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"八月秋高风怒号，卷我屋上三重茅。","n":"","cn":"八月秋深，狂风怒号，卷走了我屋顶上好几层茅草。","parts":[{"t":"八月秋高"},{"t":"风怒号","k":0},{"t":"，卷我屋上"},{"t":"三重茅","k":1},{"t":"。"}]},{"t":"茅飞渡江洒江郊，高者挂罥长林梢，下者飘转沉塘坳。","n":"","cn":"茅草飞过江去，散落在江边，高的挂在高高的树梢上，低的飘转到水塘洼地里。","parts":[{"t":"茅飞渡江洒江郊，高者挂"},{"t":"罥","k":5},{"t":"长林梢，下者飘转沉"},{"t":"塘坳","k":2},{"t":"。"}]},{"t":"南村群童欺我老无力，忍能对面为盗贼。","n":"","cn":"南村的一群儿童欺负我年老无力，竟然忍心当面做起盗贼来。","parts":[{"t":"南村群童欺我老无力，忍能对面为盗贼。"}]},{"t":"公然抱茅入竹去，唇焦口燥呼不得，归来倚杖自叹息。","n":"","cn":"（他们）公然抱着茅草跑进竹林里去，我喊得嘴唇焦干、口干舌燥也没有用，回来拄着拐杖独自叹息。","parts":[{"t":"公然抱茅入竹去，唇焦口燥呼不得，归来倚杖自叹息。"}]},{"t":"俄顷风定云墨色，秋天漠漠向昏黑。","n":"","cn":"一会儿风停了，天空的云黑得像墨一样，秋季的天空阴沉沉的，天色渐渐黑了下来。","parts":[{"t":"俄顷风定云墨色，秋天漠漠向昏黑。"}]},{"t":"布衾多年冷似铁，娇儿恶卧踏里裂。","n":"","cn":"布被子用了多年，又冷又硬，像铁板一样；孩子睡相不好，把被里蹬破了。","parts":[{"t":"布"},{"t":"衾","k":7},{"t":"多年冷似铁，娇儿恶卧踏里裂。"}]},{"t":"床头屋漏无干处，雨脚如麻未断绝。","n":"","cn":"床头屋漏，没有一处干燥的地方，雨点像麻线一样不停地往下漏。","parts":[{"t":"床头屋漏无干处，雨脚如麻未断绝。"}]},{"t":"自经丧乱少睡眠，长夜沾湿何由彻！","n":"","cn":"自安史之乱以来，我就很少睡眠，这漫漫长夜，到处湿漉漉的，如何挨到天亮呢！","parts":[{"t":"自经丧乱少睡眠，长夜沾湿何由彻！"}]},{"t":"安得广厦千万间，大庇天下寒士俱欢颜！风雨不动安如山。","n":"","cn":"怎么才能得到千万间宽敞高大的房子，广泛地遮蔽天下贫寒的士人，让他们个个都欢天喜地！即使风雨大作也不动摇，安稳得像山一样。","parts":[{"t":"安得广厦千万间，大"},{"t":"庇","k":9},{"t":"天下寒士俱欢颜！风雨不动安如山。"}]},{"t":"呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足！","n":"","cn":"唉！什么时候眼前能突然出现这样高大的房屋，到那时即使我的茅屋被吹破、自己受冻而死也心甘情愿！","parts":[{"t":"呜呼！何时眼前突兀"},{"t":"见","k":11},{"t":"此屋，吾庐独破受冻死亦足！"}]}],"words":[{"w":"风怒号","e":"【易错】「风怒号」的「号」读 háo，指大声吼叫，不读 hào。"},{"w":"三重茅","e":"【易错】「三重茅」的「重」读 chóng，指层。"},{"w":"塘坳","e":"【易错】「下者飘转沉塘坳」的「塘坳」指水塘洼地，「坳」是土字旁。"},{"w":"号","e":"【易错】「风怒号」的「号」读 háo，指大声吼叫，不读 hào。"},{"w":"重","e":"【易错】「三重茅」的「重」读 chóng，指层。"},{"w":"罥","e":"【易错】「高者挂罥长林梢」的「罥」读 juàn，指缠绕、挂住，字形易错。"},{"w":"坳","e":"【易错】「下者飘转沉塘坳」的「塘坳」指水塘洼地，「坳」是土字旁。"},{"w":"衾","e":"【易错】「布衾多年冷似铁」的「衾」读 qīn，指被子，注意上面是「今」。"},{"w":"今","e":"【易错】「布衾多年冷似铁」的「衾」读 qīn，指被子，注意上面是「今」。"},{"w":"庇","e":"【易错】「大庇天下寒士」的「庇」是广字头，指遮蔽、保护，不写「敝」。"},{"w":"敝","e":"【易错】「大庇天下寒士」的「庇」是广字头，指遮蔽、保护，不写「敝」。"},{"w":"见","e":"【易错】「突兀见此屋」的「见」同「现」，读 xiàn。"},{"w":"现","e":"【易错】「突兀见此屋」的「见」同「现」，读 xiàn。"}]},{"type":"list","title":"名句","items":["安得广厦千万间，大庇天下寒士俱欢颜！","床头屋漏无干处，雨脚如麻未断绝。"]},{"type":"list","title":"背诵提示","items":["「风怒号」的「号」读 háo，指大声吼叫，不读 hào。","「三重茅」的「重」读 chóng，指层。","「高者挂罥长林梢」的「罥」读 juàn，指缠绕、挂住，字形易错。","「下者飘转沉塘坳」的「塘坳」指水塘洼地，「坳」是土字旁。","「布衾多年冷似铁」的「衾」读 qīn，指被子，注意上面是「今」。","「大庇天下寒士」的「庇」是广字头，指遮蔽、保护，不写「敝」。","「突兀见此屋」的「见」同「现」，读 xiàn。"]}],"questions":[{"id":"p-p8b-mao-wu-wei-qiu-feng-suo-po-ge-m0","type":"fill","stem":"默写填空：安得广厦千万间，______。","answer":"大庇天下寒士俱欢颜！。","explain":"出自《茅屋为秋风所破歌》（唐·杜甫）：安得广厦千万间，大庇天下寒士俱欢颜！","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-mao-wu-wei-qiu-feng-suo-po-ge-m1","type":"fill","stem":"默写填空：床头屋漏无干处，______。","answer":"雨脚如麻未断绝。","explain":"出自《茅屋为秋风所破歌》（唐·杜甫）：床头屋漏无干处，雨脚如麻未断绝。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-mao-wu-wei-qiu-feng-suo-po-ge-u","type":"fill","stem":"理解性默写：八月秋深，狂风怒号，卷走了我屋顶上好几层茅草。","answer":"八月秋高风怒号，卷我屋上三重茅。","explain":"出自《茅屋为秋风所破歌》（唐·杜甫）。句意：八月秋深，狂风怒号，卷走了我屋顶上好几层茅草。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-mai-tan-weng","title":"卖炭翁","subtitle":"唐·白居易","grade":"8b","tags":["讽喻诗","民生疾苦","对比","心理描写","新乐府"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·白居易"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"白居易（772—846），字乐天，晚年号香山居士，又号醉吟先生，唐代伟大的现实主义诗人，新乐府运动的倡导者。他与元稹并称“元白”，诗歌数量在唐代诗人中首屈一指。\n生平经历：少年时因战乱颠沛流离，读书极刻苦，据他自己说曾“口舌成疮”；贞元年间中进士，曾任翰林学士、左拾遗，因直言进谏、上书言事被贬为江州司马；后历任杭州、苏州刺史，在杭州修堤蓄水，颇有惠政；晚年闲居洛阳香山，卒赠尚书右仆射，谥号“文”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本诗是白居易《新乐府》中的名篇，是一首叙事讽喻诗，原题下注「苦宫市也」。第一节写卖炭翁的贫苦：以「满面尘灰烟火色，两鬓苍苍十指黑」写外貌，「卖炭得钱何所营？身上衣裳口中食」写处境；「可怜身上衣正单，心忧炭贱愿天寒」是千古名句，以矛盾的复杂心理写尽生活的艰辛。第二节写运炭之苦：「一尺雪」「辗冰辙」「牛困人饥」，写尽劳苦。第三节写宫使掠夺：「翩翩」二句写使者之骄横，「手把文书口称敕」「回车叱牛」写其仗势欺人，「半匹红纱一丈绫」与「一车炭，千余斤」形成强烈对比，揭露宫市的掠夺本质。中考常考人物形象、对比手法与「可怜」二句的心理描写，注意「辗」「敕」「叱」「系（jì）」「直（值）」的字形与释义。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"卖炭翁，伐薪烧炭南山中。","n":"","cn":"卖炭的老翁，在南山中砍柴烧炭。","parts":[{"t":"卖炭翁，伐薪烧炭南山中。"}]},{"t":"满面尘灰烟火色，两鬓苍苍十指黑。","n":"","cn":"他满脸灰尘，显出被烟熏火燎的颜色，两鬓花白，十个手指被炭染得乌黑。","parts":[{"t":"满面尘灰烟火色，"},{"t":"两鬓苍苍","k":0},{"t":"十指黑。"}]},{"t":"卖炭得钱何所营？身上衣裳口中食。","n":"","cn":"卖炭得到的钱做什么用呢？是为了换身上穿的衣裳和口中吃的食物。","parts":[{"t":"卖炭得钱何所营？身上衣裳口中食。"}]},{"t":"可怜身上衣正单，心忧炭贱愿天寒。","n":"","cn":"可怜他身上衣裳单薄，心里却忧虑炭贱卖不出好价钱，反而希望天气更寒冷些。","parts":[{"t":"可怜身上衣正单，心忧炭贱愿天寒。"}]},{"t":"夜来城外一尺雪，晓驾炭车辗冰辙。","n":"","cn":"夜里城外下了一尺厚的大雪，清晨他驾着炭车碾过冰冻的车辙赶路。","parts":[{"t":"夜来城外一尺雪，晓驾炭车"},{"t":"辗","k":6},{"t":"冰"},{"t":"辙","k":8},{"t":"。"}]},{"t":"牛困人饥日已高，市南门外泥中歇。","n":"","cn":"牛累了，人饿了，太阳已经升得很高了，他就在集市南门外的泥泞中歇息。","parts":[{"t":"牛困人饥日已高，市南门外泥中歇。"}]},{"t":"翩翩两骑来是谁？黄衣使者白衫儿。","n":"","cn":"那两个轻快骑马而来的人是谁呢？是穿着黄衣的太监和穿着白衫的爪牙。","parts":[{"t":"翩翩两骑来是谁？黄衣使者白衫儿。"}]},{"t":"手把文书口称敕，回车叱牛牵向北。","n":"","cn":"（他们）手里拿着公文，嘴里说是皇帝的命令，拉转车头、吆喝着牛往北面（皇宫方向）去了。","parts":[{"t":"手把文书"},{"t":"口称敕","k":2},{"t":"，"},{"t":"回车叱牛","k":1},{"t":"牵向北。"}]},{"t":"一车炭，千余斤，宫使驱将惜不得。","n":"","cn":"一车炭，一千多斤，宫使硬是赶着车走了，老翁舍不得也没有办法。","parts":[{"t":"一车炭，千余斤，宫使驱"},{"t":"将","k":13},{"t":"惜不得。"}]},{"t":"半匹红纱一丈绫，系向牛头充炭直。","n":"","cn":"（他们）把半匹红纱和一丈绫，朝牛头上一挂，就充当一车炭的价钱了。","parts":[{"t":"半匹红纱一丈绫，"},{"t":"系","k":14},{"t":"向牛头充炭"},{"t":"直","k":15},{"t":"。"}]}],"words":[{"w":"两鬓苍苍","e":"【易错】「两鬓苍苍」的「鬓」是「髟」字头，指鬓发，不写「宾」。"},{"w":"回车叱牛","e":"【易错】「回车叱牛」的「叱」是口字旁，指大声呵斥，不写「斥」。"},{"w":"口称敕","e":"【易错】「口称敕」的「敕」读 chì，指皇帝的命令，不写「刺」。"},{"w":"鬓","e":"【易错】「两鬓苍苍」的「鬓」是「髟」字头，指鬓发，不写「宾」。"},{"w":"髟","e":"【易错】「两鬓苍苍」的「鬓」是「髟」字头，指鬓发，不写「宾」。"},{"w":"宾","e":"【易错】「两鬓苍苍」的「鬓」是「髟」字头，指鬓发，不写「宾」。"},{"w":"辗","e":"【易错】「晓驾炭车辗冰辙」的「辗」是车字旁，教材作「辗」，不写「碾」以外的形近字；「辙」是车字旁。"},{"w":"碾","e":"【易错】「晓驾炭车辗冰辙」的「辗」是车字旁，教材作「辗」，不写「碾」以外的形近字；「辙」是车字旁。"},{"w":"辙","e":"【易错】「晓驾炭车辗冰辙」的「辗」是车字旁，教材作「辗」，不写「碾」以外的形近字；「辙」是车字旁。"},{"w":"敕","e":"【易错】「口称敕」的「敕」读 chì，指皇帝的命令，不写「刺」。"},{"w":"刺","e":"【易错】「口称敕」的「敕」读 chì，指皇帝的命令，不写「刺」。"},{"w":"叱","e":"【易错】「回车叱牛」的「叱」是口字旁，指大声呵斥，不写「斥」。"},{"w":"斥","e":"【易错】「回车叱牛」的「叱」是口字旁，指大声呵斥，不写「斥」。"},{"w":"将","e":"【易错】「宫使驱将惜不得」的「将」读 jiāng，是动词后的助词。"},{"w":"系","e":"【易错】「系向牛头充炭直」的「系」读 jì，指打结、挂；「直」同「值」，指价钱。"},{"w":"直","e":"【易错】「系向牛头充炭直」的「系」读 jì，指打结、挂；「直」同「值」，指价钱。"},{"w":"值","e":"【易错】「系向牛头充炭直」的「系」读 jì，指打结、挂；「直」同「值」，指价钱。"}]},{"type":"list","title":"名句","items":["可怜身上衣正单，心忧炭贱愿天寒。"]},{"type":"list","title":"背诵提示","items":["「两鬓苍苍」的「鬓」是「髟」字头，指鬓发，不写「宾」。","「晓驾炭车辗冰辙」的「辗」是车字旁，教材作「辗」，不写「碾」以外的形近字；「辙」是车字旁。","「口称敕」的「敕」读 chì，指皇帝的命令，不写「刺」。","「回车叱牛」的「叱」是口字旁，指大声呵斥，不写「斥」。","「宫使驱将惜不得」的「将」读 jiāng，是动词后的助词。","「系向牛头充炭直」的「系」读 jì，指打结、挂；「直」同「值」，指价钱。"]}],"questions":[{"id":"p-p8b-mai-tan-weng-m0","type":"fill","stem":"默写填空：可怜身上衣正单，______。","answer":"心忧炭贱愿天寒。","explain":"出自《卖炭翁》（唐·白居易）：可怜身上衣正单，心忧炭贱愿天寒。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-mai-tan-weng-u","type":"fill","stem":"理解性默写：卖炭的老翁，在南山中砍柴烧炭。","answer":"卖炭翁，伐薪烧炭南山中。","explain":"出自《卖炭翁》（唐·白居易）。句意：卖炭的老翁，在南山中砍柴烧炭。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-ti-po-shan-si-hou-chan-yuan","title":"题破山寺后禅院","subtitle":"唐·常建","grade":"8b","tags":["写景","禅意","炼字","题壁诗"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·常建"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"常建，唐代诗人，生卒年不详，约活动于唐玄宗开元、天宝年间，其诗多写山水田园与隐逸情怀，以《题破山寺后禅院》最为著名。\n生平经历：开元十五年与王昌龄同榜进士，曾任盱眙尉；因仕途失意，他放浪山水，后隐居鄂渚一带，一生沉沦下僚，而在当时的诗名却很盛。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是一首题壁诗，写诗人清晨游寺的所见所感。首联「清晨入古寺，初日照高林」点明时间并写高林沐浴晨光之景，气氛清幽。颔联「曲径通幽处，禅房花木深」写后禅院的环境：曲径通往幽深之处，禅房深藏于繁茂花木之中，以「幽」「深」二字写出远离尘嚣的境界，是千古名句。颈联「山光悦鸟性，潭影空人心」由景入情：山光使鸟性欢悦，潭影使人心空明，「悦」「空」二字是炼字妙笔，为形容词的使动用法。尾联「万籁此都寂，但余钟磬音」以有声写无声，余韵悠长。中考常考颔联的意境与「悦」「空」的赏析，注意「磬」「籁」的字形与「都」的写法。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"清晨入古寺，初日照高林。","n":"","cn":"清晨我走进这座古老的寺院，初升的太阳照耀着高高的树林。","parts":[{"t":"清晨入古寺，初日照高林。"}]},{"t":"曲径通幽处，禅房花木深。","n":"","cn":"弯弯曲曲的小路通向幽深的地方，禅房深藏在繁茂的花木丛中。","parts":[{"t":"曲径通幽处，禅房花木深。"}]},{"t":"山光悦鸟性，潭影空人心。","n":"","cn":"山中的风光使鸟儿的性情得到愉悦，潭中的倒影使人心中杂念顿消。","parts":[{"t":"山光"},{"t":"悦","k":7},{"t":"鸟性，潭影"},{"t":"空","k":8},{"t":"人心。"}]},{"t":"万籁此都寂，但余钟磬音。","n":"","cn":"此时万物都沉寂了，只留下敲钟击磬的声音在耳边回响。","parts":[{"t":"万"},{"t":"籁","k":0},{"t":"此"},{"t":"都","k":9},{"t":"寂，但余钟"},{"t":"磬","k":2},{"t":"音。"}]}],"words":[{"w":"籁","e":"【易错】「万籁此都寂」的「籁」是竹字头，指声音，不写「赖」。"},{"w":"赖","e":"【易错】「万籁此都寂」的「籁」是竹字头，指声音，不写「赖」。"},{"w":"磬","e":"【易错】「但余钟磬音」的「磬」是「声」下加「殳」下「石」，指石制乐器，不写「罄」。"},{"w":"声","e":"【易错】「但余钟磬音」的「磬」是「声」下加「殳」下「石」，指石制乐器，不写「罄」。"},{"w":"殳","e":"【易错】「但余钟磬音」的「磬」是「声」下加「殳」下「石」，指石制乐器，不写「罄」。"},{"w":"石","e":"【易错】「但余钟磬音」的「磬」是「声」下加「殳」下「石」，指石制乐器，不写「罄」。"},{"w":"罄","e":"【易错】「但余钟磬音」的「磬」是「声」下加「殳」下「石」，指石制乐器，不写「罄」。"},{"w":"悦","e":"【易错】「山光悦鸟性」的「悦」是使动用法，意为「使……愉悦」。"},{"w":"空","e":"【易错】「潭影空人心」的「空」是使动用法，意为「使……空明」。"},{"w":"都","e":"【易错】教材作「万籁此都寂」，注意「都」字的写法，不写「俱」。"},{"w":"俱","e":"【易错】教材作「万籁此都寂」，注意「都」字的写法，不写「俱」。"}]},{"type":"list","title":"名句","items":["曲径通幽处，禅房花木深。","山光悦鸟性，潭影空人心。"]},{"type":"list","title":"背诵提示","items":["「万籁此都寂」的「籁」是竹字头，指声音，不写「赖」。","「但余钟磬音」的「磬」是「声」下加「殳」下「石」，指石制乐器，不写「罄」。","「山光悦鸟性」的「悦」是使动用法，意为「使……愉悦」。","「潭影空人心」的「空」是使动用法，意为「使……空明」。","教材作「万籁此都寂」，注意「都」字的写法，不写「俱」。"]}],"questions":[{"id":"p-p8b-ti-po-shan-si-hou-chan-yuan-m0","type":"fill","stem":"默写填空：曲径通幽处，______。","answer":"禅房花木深。","explain":"出自《题破山寺后禅院》（唐·常建）：曲径通幽处，禅房花木深。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-ti-po-shan-si-hou-chan-yuan-m1","type":"fill","stem":"默写填空：山光悦鸟性，______。","answer":"潭影空人心。","explain":"出自《题破山寺后禅院》（唐·常建）：山光悦鸟性，潭影空人心。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-ti-po-shan-si-hou-chan-yuan-u","type":"fill","stem":"理解性默写：清晨我走进这座古老的寺院，初升的太阳照耀着高高的树林。","answer":"清晨入古寺，初日照高林。","explain":"出自《题破山寺后禅院》（唐·常建）。句意：清晨我走进这座古老的寺院，初升的太阳照耀着高高的树林。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-song-you-ren","title":"送友人","subtitle":"唐·李白","grade":"8b","tags":["送别","友情","对偶","比喻","情景交融"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李白"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李白（701—762），字太白，号青莲居士，唐代伟大的浪漫主义诗人，被后人尊称为“诗仙”，与杜甫并称“李杜”，是我国古典诗歌浪漫主义传统的杰出代表。\n生平经历：少年时博览群书、喜好剑术任侠；二十五岁“仗剑去国”出蜀漫游，足迹遍及大江南北；天宝元年奉诏入长安供奉翰林，因遭权贵谗毁仅三年便离京；安史之乱中因参与永王李璘幕府获罪被流放夜郎，途中遇赦东归，晚年漂泊，762年病逝于当涂。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是李白一首情意深长的送别诗。首联「青山横北郭，白水绕东城」用工整的对偶写送别之地，「横」与「绕」一静一动，山水相依，色彩明丽。颔联「此地一为别，孤蓬万里征」点明送别，以「孤蓬」比喻游子飘零无定，情感由景入情。颈联「浮云游子意，落日故人情」尤为精妙：以「浮云」比游子漂泊无依，以「落日」比自己眷恋不舍，情景交融，含蓄深挚。尾联「挥手自兹去，萧萧班马鸣」以马鸣之声作结，借马写人，烘托离别的怅惘，余味无穷。中考常考对偶、比喻与颈联的赏析，注意「孤蓬」不写「篷」，「萧萧班马鸣」的「班」不写「斑」。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"青山横北郭，白水绕东城。","n":"","cn":"青山横亘在城郭的北面，清澈的白水绕着城的东边流过。","parts":[{"t":"青山横北"},{"t":"郭","k":5},{"t":"，白水绕东城。"}]},{"t":"此地一为别，孤蓬万里征。","n":"","cn":"我们在这里一分别，你就要像孤蓬一样随风飘转，踏上万里征程。","parts":[{"t":"此地一为别，孤"},{"t":"蓬","k":1},{"t":"万里征。"}]},{"t":"浮云游子意，落日故人情。","n":"","cn":"浮云飘忽不定，就像游子的心意；落日迟迟不走，正如老朋友依依惜别之情。","parts":[{"t":"浮云游子意，落日故人情。"}]},{"t":"挥手自兹去，萧萧班马鸣。","n":"","cn":"我们挥手从此分别，那两匹马也萧萧长鸣，似有无限不舍。","parts":[{"t":"挥手自"},{"t":"兹","k":7},{"t":"去，萧萧"},{"t":"班","k":3},{"t":"马鸣。"}]}],"words":[{"w":"分别的","e":"【易错】「萧萧班马鸣」的「班」意为「分别的」，班马即离群的马，不写「斑」。"},{"w":"蓬","e":"【易错】「孤蓬万里征」的「蓬」是草字头，比喻漂泊的游子，不写「篷」。"},{"w":"篷","e":"【易错】「孤蓬万里征」的「蓬」是草字头，比喻漂泊的游子，不写「篷」。"},{"w":"班","e":"【易错】「萧萧班马鸣」的「班」意为「分别的」，班马即离群的马，不写「斑」。"},{"w":"斑","e":"【易错】「萧萧班马鸣」的「班」意为「分别的」，班马即离群的马，不写「斑」。"},{"w":"郭","e":"【易错】「青山横北郭」的「郭」指外城，不写「廓」。"},{"w":"廓","e":"【易错】「青山横北郭」的「郭」指外城，不写「廓」。"},{"w":"兹","e":"【易错】「挥手自兹去」的「兹」指此，不写「滋」。"},{"w":"滋","e":"【易错】「挥手自兹去」的「兹」指此，不写「滋」。"}]},{"type":"list","title":"名句","items":["浮云游子意，落日故人情。","挥手自兹去，萧萧班马鸣。"]},{"type":"list","title":"背诵提示","items":["「孤蓬万里征」的「蓬」是草字头，比喻漂泊的游子，不写「篷」。","「萧萧班马鸣」的「班」意为「分别的」，班马即离群的马，不写「斑」。","「青山横北郭」的「郭」指外城，不写「廓」。","「挥手自兹去」的「兹」指此，不写「滋」。"]}],"questions":[{"id":"p-p8b-song-you-ren-m0","type":"fill","stem":"默写填空：浮云游子意，______。","answer":"落日故人情。","explain":"出自《送友人》（唐·李白）：浮云游子意，落日故人情。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-song-you-ren-m1","type":"fill","stem":"默写填空：挥手自兹去，______。","answer":"萧萧班马鸣。","explain":"出自《送友人》（唐·李白）：挥手自兹去，萧萧班马鸣。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-song-you-ren-u","type":"fill","stem":"理解性默写：青山横亘在城郭的北面，清澈的白水绕着城的东边流过。","answer":"青山横北郭，白水绕东城。","explain":"出自《送友人》（唐·李白）。句意：青山横亘在城郭的北面，清澈的白水绕着城的东边流过。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-bu-suan-zi-huang-zhou-ding-hui-yuan","title":"卜算子·黄州定慧院寓居作","subtitle":"宋·苏轼","grade":"8b","tags":["词","托物言志","贬谪","孤鸿","苏轼"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·苏轼"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"苏轼（1037—1101），字子瞻，号东坡居士，北宋著名文学家、书画家，眉州眉山（今四川眉山）人。他与父亲苏洵、弟弟苏辙合称“三苏”，父子三人同列“唐宋八大家”。\n生平经历：嘉祐二年中进士，因反对王安石变法的某些做法而自请外任，先后任杭州、密州、徐州、湖州等地知州；“乌台诗案”后被贬黄州，写下大量名篇；此后又相继被贬惠州、儋州，遇赦北归途中病逝于常州。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是苏轼被贬黄州时所作的一首词。上片写景：以「缺月」「疏桐」「漏断」营造夜深人静、凄清冷寂的氛围，「谁见幽人独往来」写无人理解的孤独，「缥缈孤鸿影」以孤鸿自比，人、鸿合一，孤独中见高洁。下片写孤鸿：「惊起却回头，有恨无人省」写惊恐与幽怨，「拣尽寒枝不肯栖，寂寞沙洲冷」写虽无枝可依也不肯苟合，宁可独处寒沙。全词借孤鸿自况，托物言志，含蓄地表达了作者遭贬后孤傲高洁、不肯随俗的心志。中考常考借物抒怀（托物言志）的手法与「无人省」「不肯栖」的含义，注意「缥缈」「省（xǐng）」「拣」的字形与读音。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"缺月挂疏桐，漏断人初静。","n":"","cn":"一弯残月挂在稀疏的梧桐树上，漏壶水尽，人声刚刚静下来。","parts":[{"t":"缺月挂"},{"t":"疏","k":6},{"t":"桐，"},{"t":"漏","k":8},{"t":"断人初静。"}]},{"t":"谁见幽人独往来，缥缈孤鸿影。","n":"","cn":"有谁看见幽居的人独自往来呢？只有那缥缈的孤雁身影。","parts":[{"t":"谁见幽人独往来，"},{"t":"缥缈","k":0},{"t":"孤鸿影。"}]},{"t":"惊起却回头，有恨无人省。","n":"","cn":"（孤雁）惊起回头，心中有恨却无人理解。","parts":[{"t":"惊起却回头，有恨无人"},{"t":"省","k":3},{"t":"。"}]},{"t":"拣尽寒枝不肯栖，寂寞沙洲冷。","n":"","cn":"它挑遍了寒冷的树枝也不肯栖息，宁愿独自忍受沙洲的寂寞清冷。","parts":[{"t":"拣","k":4},{"t":"尽寒枝不肯栖，寂寞沙洲冷。"}]}],"words":[{"w":"缥缈","e":"【易错】「缥缈孤鸿影」的「缥缈」都是绞丝旁，不写「漂渺」。"},{"w":"漂渺","e":"【易错】「缥缈孤鸿影」的「缥缈」都是绞丝旁，不写「漂渺」。"},{"w":"稀疏","e":"【易错】「缺月挂疏桐」的「疏」是「稀疏」之意，不写「梳」。"},{"w":"省","e":"【易错】「有恨无人省」的「省」读 xǐng，意为「理解、明白」，不读 shěng。"},{"w":"拣","e":"【易错】「拣尽寒枝不肯栖」的「拣」是提手旁，指挑选，不写「捡」。"},{"w":"捡","e":"【易错】「拣尽寒枝不肯栖」的「拣」是提手旁，指挑选，不写「捡」。"},{"w":"疏","e":"【易错】「缺月挂疏桐」的「疏」是「稀疏」之意，不写「梳」。"},{"w":"梳","e":"【易错】「缺月挂疏桐」的「疏」是「稀疏」之意，不写「梳」。"},{"w":"漏","e":"【易错】「漏断人初静」的「漏」指漏壶，是古代计时器，不写「露」。"},{"w":"露","e":"【易错】「漏断人初静」的「漏」指漏壶，是古代计时器，不写「露」。"}]},{"type":"list","title":"名句","items":["拣尽寒枝不肯栖，寂寞沙洲冷。"]},{"type":"list","title":"背诵提示","items":["「缥缈孤鸿影」的「缥缈」都是绞丝旁，不写「漂渺」。","「有恨无人省」的「省」读 xǐng，意为「理解、明白」，不读 shěng。","「拣尽寒枝不肯栖」的「拣」是提手旁，指挑选，不写「捡」。","「缺月挂疏桐」的「疏」是「稀疏」之意，不写「梳」。","「漏断人初静」的「漏」指漏壶，是古代计时器，不写「露」。"]}],"questions":[{"id":"p-p8b-bu-suan-zi-huang-zhou-ding-hui-yuan-m0","type":"fill","stem":"默写填空：拣尽寒枝不肯栖，______。","answer":"寂寞沙洲冷。","explain":"出自《卜算子·黄州定慧院寓居作》（宋·苏轼）：拣尽寒枝不肯栖，寂寞沙洲冷。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-bu-suan-zi-huang-zhou-ding-hui-yuan-u","type":"fill","stem":"理解性默写：一弯残月挂在稀疏的梧桐树上，漏壶水尽，人声刚刚静下来。","answer":"缺月挂疏桐，漏断人初静。","explain":"出自《卜算子·黄州定慧院寓居作》（宋·苏轼）。句意：一弯残月挂在稀疏的梧桐树上，漏壶水尽，人声刚刚静下来。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-bu-suan-zi-yong-mei","title":"卜算子·咏梅","subtitle":"宋·陆游","grade":"8b","tags":["咏物","托物言志","梅花","陆游","坚贞"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·陆游"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"陆游（1125—1210），字务观，号放翁，越州山阴（今浙江绍兴）人，南宋爱国诗人，一生力主抗金，现存诗作九千余首，是我国古代存诗最多的诗人之一。\n生平经历：他出生在北宋灭亡前夕，少年时便立下抗金报国之志；二十九岁参加锁厅考试名列第一，却因名次排在秦桧之孙的前面而遭排挤；孝宗时赐进士出身，曾入四川宣抚使王炎幕府，亲历南郑前线的军旅生活；此后因坚持抗金屡遭贬黜，长期闲居山阴故里，八十五岁临终仍写下《示儿》，嘱咐“王师北定中原日，家祭无忘告乃翁”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是陆游的一首咏物词。上片写梅的处境：「驿外断桥边，寂寞开无主」写梅生于荒僻之地、无人欣赏；「已是黄昏独自愁，更著风和雨」以黄昏与风雨加倍渲染其孤苦，梅的遭遇正是词人仕途坎坷的写照。下片写梅的品格：「无意苦争春，一任群芳妒」写梅不争春、不与群芳争艳，任凭嫉妒；「零落成泥碾作尘，只有香如故」为千古名句，写梅即使零落成泥，清香依旧，象征坚贞自守、至死不渝的节操。全词托物言志，以梅喻人。中考常考托物言志的写法、「只有香如故」的象征意义与「更著」「一任」等词的表达效果，注意「著（zhuó）」「妒」「碾」的字形与读音。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"驿外断桥边，寂寞开无主。","n":"","cn":"驿站之外的断桥边，梅花寂寞地开着，无人过问。","parts":[{"t":"驿","k":6},{"t":"外断桥边，寂"},{"t":"寞","k":8},{"t":"开无主。"}]},{"t":"已是黄昏独自愁，更著风和雨。","n":"","cn":"已是黄昏时分，它独自忧愁，又遭受风吹雨打。","parts":[{"t":"已是黄昏独自愁，更"},{"t":"著","k":0},{"t":"风和雨。"}]},{"t":"无意苦争春，一任群芳妒。","n":"","cn":"它无心苦苦争春，任凭百花嫉妒。","parts":[{"t":"无意苦争春，一任群芳"},{"t":"妒","k":2},{"t":"。"}]},{"t":"零落成泥碾作尘，只有香如故。","n":"","cn":"即使凋零飘落、被碾作尘土，只有那清香依旧如故。","parts":[{"t":"零落成泥"},{"t":"碾","k":4},{"t":"作尘，只有香如故。"}]}],"words":[{"w":"著","e":"【易错】「更著风和雨」的「著」读 zhuó，同「着」，意为「遭受、加上」。"},{"w":"着","e":"【易错】「更著风和雨」的「著」读 zhuó，同「着」，意为「遭受、加上」。"},{"w":"妒","e":"【易错】「一任群芳妒」的「妒」是女字旁，不写「忌」。"},{"w":"忌","e":"【易错】「一任群芳妒」的「妒」是女字旁，不写「忌」。"},{"w":"碾","e":"【易错】「零落成泥碾作尘」的「碾」是石字旁，指轧、压，不写「辗」。"},{"w":"辗","e":"【易错】「零落成泥碾作尘」的「碾」是石字旁，指轧、压，不写「辗」。"},{"w":"驿","e":"【易错】「驿外断桥边」的「驿」是马字旁，指驿站，不写「择」。"},{"w":"择","e":"【易错】「驿外断桥边」的「驿」是马字旁，指驿站，不写「择」。"},{"w":"寞","e":"【易错】「寂寞开无主」的「寞」是宝盖头，不写「漠」。"},{"w":"漠","e":"【易错】「寂寞开无主」的「寞」是宝盖头，不写「漠」。"}]},{"type":"list","title":"名句","items":["零落成泥碾作尘，只有香如故。"]},{"type":"list","title":"背诵提示","items":["「更著风和雨」的「著」读 zhuó，同「着」，意为「遭受、加上」。","「一任群芳妒」的「妒」是女字旁，不写「忌」。","「零落成泥碾作尘」的「碾」是石字旁，指轧、压，不写「辗」。","「驿外断桥边」的「驿」是马字旁，指驿站，不写「择」。","「寂寞开无主」的「寞」是宝盖头，不写「漠」。"]}],"questions":[{"id":"p-p8b-bu-suan-zi-yong-mei-m0","type":"fill","stem":"默写填空：零落成泥碾作尘，______。","answer":"只有香如故。","explain":"出自《卜算子·咏梅》（宋·陆游）：零落成泥碾作尘，只有香如故。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-bu-suan-zi-yong-mei-u","type":"fill","stem":"理解性默写：驿站之外的断桥边，梅花寂寞地开着，无人过问。","answer":"驿外断桥边，寂寞开无主。","explain":"出自《卜算子·咏梅》（宋·陆游）。句意：驿站之外的断桥边，梅花寂寞地开着，无人过问。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-qin-yuan-chun-xue","title":"沁园春·雪","subtitle":"现代·毛泽东","grade":"9a","tags":["写景","豪情","咏史"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"现代·毛泽东"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"毛泽东（1893—1976），字润之，湖南湘潭韶山人，伟大的无产阶级革命家、战略家、理论家，中国共产党、中国人民解放军和中华人民共和国的主要缔造者之一；同时也是一位成就卓越的诗人与书法家。\n诗词代表作：《沁园春·雪》（1936年作，1945年重庆谈判期间发表，轰动一时）、《沁园春·长沙》《七律·长征》《忆秦娥·娄山关》《清平乐·六盘山》《卜算子·咏梅》《水调歌头·游泳》《浪淘沙·北戴河》。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"上片写景，以「千里」「万里」总写北国雪景的雄阔，再用「望」字领起，以「山舞银蛇，原驰蜡象」的比喻与化静为动之笔，把冰封雪盖的群山高原写得生气勃勃；「须晴日」三句由实入虚，红装素裹，想象奇丽。下片以「江山如此多娇」承上启下，用一个「惜」字统摄，评点秦皇汉武、唐宗宋祖、成吉思汗，抑中见扬，最后以「数风流人物，还看今朝」收束全篇，抒发了革命英雄的豪情壮志与坚定自信。中考常考：动静结合与比喻拟人的写景手法、「望」「惜」两个领字的作用、上下片的过渡句，以及全词借景抒情、议论与描写相结合的表达方式。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"北国风光，千里冰封，万里雪飘。","n":"","cn":"北方的风光，千里大地都被冰封冻，万里长空雪花飘舞。","parts":[{"t":"北国风光，千里冰封，万里雪飘。"}]},{"t":"望长城内外，惟余莽莽；大河上下，顿失滔滔。","n":"","cn":"远望长城内外，只剩下白茫茫一片；黄河上下游，顿时失去了波涛滚滚的气势。","parts":[{"t":"望长城内外，"},{"t":"惟余莽莽","k":0},{"t":"；大河上下，"},{"t":"顿失滔滔","k":4},{"t":"。"}]},{"t":"山舞银蛇，原驰蜡象，欲与天公试比高。","n":"","cn":"群山像银蛇一样蜿蜒舞动，高原像白象一样奔驰向前，都想同老天爷比一比高低。","parts":[{"t":"山舞银蛇，原驰蜡象，欲与天公试比高。"}]},{"t":"须晴日，看红装素裹，分外妖娆。","n":"","cn":"等到雪后放晴，看红日与白雪交相辉映，景象格外娇艳美好。","parts":[{"t":"须晴日，看"},{"t":"红装素裹","k":2},{"t":"，分外妖娆。"}]},{"t":"江山如此多娇，引无数英雄竞折腰。","n":"","cn":"祖国的江山如此娇美，引得无数英雄为之倾倒。","parts":[{"t":"江山如此多"},{"t":"娇","k":14},{"t":"，引无数英雄"},{"t":"竞折腰","k":7},{"t":"。"}]},{"t":"惜秦皇汉武，略输文采；唐宗宋祖，稍逊风骚。","n":"","cn":"可惜秦始皇、汉武帝，文学才华略差一些；唐太宗、宋太祖，文治功业也稍逊一筹。","parts":[{"t":"惜秦皇汉武，略输文采；唐宗宋祖，"},{"t":"稍逊风骚","k":6},{"t":"。"}]},{"t":"一代天骄，成吉思汗，只识弯弓射大雕。","n":"","cn":"称雄一代的成吉思汗，也只懂得拉弓射大雕而已。","parts":[{"t":"一代天骄","k":5},{"t":"，成吉思汗，"},{"t":"只","k":10},{"t":"识弯弓射大雕。"}]},{"t":"俱往矣，数风流人物，还看今朝。","n":"","cn":"这些人物都已经过去了，要数真正的英雄人物，还得看今天的人民。","parts":[{"t":"俱往矣","k":8},{"t":"，数风流人物，还看今朝。"}]}],"words":[{"w":"惟余莽莽","e":"【易错】「惟余莽莽」的「惟」是「只」，不要写成「唯余莽莽」。"},{"w":"唯余莽莽","e":"【易错】「惟余莽莽」的「惟」是「只」，不要写成「唯余莽莽」。"},{"w":"红装素裹","e":"【易错】「红装素裹」的「装」指装束，不要写成「红妆素裹」。"},{"w":"红妆素裹","e":"【易错】「红装素裹」的「装」指装束，不要写成「红妆素裹」。"},{"w":"顿失滔滔","e":"【易错】「顿失滔滔」的「滔」是三点水，不要漏写。"},{"w":"一代天骄","e":"【易错】「一代天骄」的「骄」不要写成「娇」（「娇」用于娇美）。"},{"w":"稍逊风骚","e":"【易错】「稍逊风骚」的「骚」左旁是「马」，右上「叉」下「虫」不要写错。"},{"w":"竞折腰","e":"【易错】「竞折腰」的「竞」是争着、争相，不要写成「竟」。"},{"w":"俱往矣","e":"【易错】「俱往矣」的「俱」是「都」，不要写成「具」。"},{"w":"惟","e":"【易错】「惟余莽莽」的「惟」是「只」，不要写成「唯余莽莽」。"},{"w":"只","e":"【易错】「惟余莽莽」的「惟」是「只」，不要写成「唯余莽莽」。"},{"w":"装","e":"【易错】「红装素裹」的「装」指装束，不要写成「红妆素裹」。"},{"w":"滔","e":"【易错】「顿失滔滔」的「滔」是三点水，不要漏写。"},{"w":"骄","e":"【易错】「一代天骄」的「骄」不要写成「娇」（「娇」用于娇美）。"},{"w":"娇","e":"【易错】「一代天骄」的「骄」不要写成「娇」（「娇」用于娇美）。"},{"w":"竞","e":"【易错】「竞折腰」的「竞」是争着、争相，不要写成「竟」。"},{"w":"竟","e":"【易错】「竞折腰」的「竞」是争着、争相，不要写成「竟」。"},{"w":"骚","e":"【易错】「稍逊风骚」的「骚」左旁是「马」，右上「叉」下「虫」不要写错。"},{"w":"马","e":"【易错】「稍逊风骚」的「骚」左旁是「马」，右上「叉」下「虫」不要写错。"},{"w":"叉","e":"【易错】「稍逊风骚」的「骚」左旁是「马」，右上「叉」下「虫」不要写错。"},{"w":"虫","e":"【易错】「稍逊风骚」的「骚」左旁是「马」，右上「叉」下「虫」不要写错。"},{"w":"俱","e":"【易错】「俱往矣」的「俱」是「都」，不要写成「具」。"},{"w":"都","e":"【易错】「俱往矣」的「俱」是「都」，不要写成「具」。"},{"w":"具","e":"【易错】「俱往矣」的「俱」是「都」，不要写成「具」。"}]},{"type":"list","title":"名句","items":["山舞银蛇，原驰蜡象，欲与天公试比高。","俱往矣，数风流人物，还看今朝。"]},{"type":"list","title":"背诵提示","items":["「惟余莽莽」的「惟」是「只」，不要写成「唯余莽莽」。","「红装素裹」的「装」指装束，不要写成「红妆素裹」。","「顿失滔滔」的「滔」是三点水，不要漏写。","「一代天骄」的「骄」不要写成「娇」（「娇」用于娇美）。","「竞折腰」的「竞」是争着、争相，不要写成「竟」。","「稍逊风骚」的「骚」左旁是「马」，右上「叉」下「虫」不要写错。","「俱往矣」的「俱」是「都」，不要写成「具」。"]}],"questions":[{"id":"p-p9a-qin-yuan-chun-xue-m0","type":"fill","stem":"默写填空：山舞银蛇，______。","answer":"原驰蜡象。","explain":"出自《沁园春·雪》（现代·毛泽东）：山舞银蛇，原驰蜡象，欲与天公试比高。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-qin-yuan-chun-xue-m1","type":"fill","stem":"默写填空：俱往矣，______。","answer":"数风流人物。","explain":"出自《沁园春·雪》（现代·毛泽东）：俱往矣，数风流人物，还看今朝。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-qin-yuan-chun-xue-u","type":"fill","stem":"理解性默写：北方的风光，千里大地都被冰封冻，万里长空雪花飘舞。","answer":"北国风光，千里冰封，万里雪飘。","explain":"出自《沁园春·雪》（现代·毛泽东）。句意：北方的风光，千里大地都被冰封冻，万里长空雪花飘舞。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-wo-ai-zhe-tu-di","title":"我爱这土地","subtitle":"现代·艾青","grade":"9a","tags":["爱国","现代诗","象征"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"现代·艾青"},{"k":"体裁","v":"现代诗"}]},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"全诗以「假如我是一只鸟」设想虚拟形象，用「嘶哑的喉咙」歌唱土地、河流、风、黎明四个意象，层层推进，把苦难中的祖国与人民的悲愤、抗争、希望全部纳入一个比喻之中；「然后我死了，连羽毛也腐烂在土地里面」写鸟的献身，实为诗人的自我献身，情感由激越转入深沉。结尾两句一问一答，直抒胸臆，是全诗的情感凝聚点，也是中考高频考点。常见考法：土地、河流、风、黎明四个意象的象征义（苦难、悲愤、抗争、光明希望）；「嘶哑」一词的表达效果（历经磨难却依然歌唱的执着）；结尾设问句式直抒胸臆的作用；语言上散文式自由体与「深沉」抒情基调的统一。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"假如我是一只鸟，","n":"","cn":"假如我是一只鸟，","parts":[{"t":"假如我是一只鸟，"}]},{"t":"我也应该用嘶哑的喉咙歌唱：","n":"","cn":"我也要用已经嘶哑的喉咙为祖国歌唱：","parts":[{"t":"我也应该用"},{"t":"嘶哑","k":6},{"t":"的喉咙歌唱："}]},{"t":"这被暴风雨所打击着的土地，","n":"","cn":"歌唱这正遭受暴风雨般苦难打击的土地，","parts":[{"t":"这被暴风雨所打击着的土地，"}]},{"t":"这永远汹涌着我们的悲愤的河流，","n":"","cn":"歌唱这永远奔涌着我们悲愤的河流，","parts":[{"t":"这永远"},{"t":"汹涌","k":7},{"t":"着我们的悲愤的河流，"}]},{"t":"这无止息地吹刮着的激怒的风，","n":"","cn":"歌唱这无休无止地吹刮着的令人激怒的风，","parts":[{"t":"这"},{"t":"无止息","k":4},{"t":"地吹刮着的激怒的风，"}]},{"t":"和那来自林间的无比温柔的黎明……","n":"","cn":"以及那从林间升起、无比温柔的黎明……","parts":[{"t":"和那来自林间的无比温柔的黎明……"}]},{"t":"——然后我死了，","n":"","cn":"——唱到力竭，然后我死了，","parts":[{"t":"——然后我死了，"}]},{"t":"连羽毛也腐烂在土地里面。","n":"","cn":"连羽毛也腐烂在这土地里面。","parts":[{"t":"连羽毛也"},{"t":"腐烂","k":8},{"t":"在土地里面。"}]},{"t":"为什么我的眼里常含泪水？","n":"","cn":"为什么我的眼里常常含着泪水？","parts":[{"t":"为什么我的眼里"},{"t":"常含泪水","k":0},{"t":"？"}]},{"t":"因为我对这土地爱得深沉……","n":"","cn":"因为我对这土地爱得那样深沉……","parts":[{"t":"因为我对这土地"},{"t":"爱得深沉","k":2},{"t":"……"}]}],"words":[{"w":"常含泪水","e":"【易错】「常含泪水」的「常」是「常常」，不要写成「长含泪水」。"},{"w":"长含泪水","e":"【易错】「常含泪水」的「常」是「常常」，不要写成「长含泪水」。"},{"w":"爱得深沉","e":"【易错】「爱得深沉」的「得」是补语标志，不要写成「爱的深沉」。"},{"w":"爱的深沉","e":"【易错】「爱得深沉」的「得」是补语标志，不要写成「爱的深沉」。"},{"w":"无止息","e":"【易错】「无止息」不要写成「无休止」。"},{"w":"无休止","e":"【易错】「无止息」不要写成「无休止」。"},{"w":"嘶哑","e":"【易错】「嘶哑」两字都是口字旁，「嘶」不要写成「撕」。"},{"w":"汹涌","e":"【易错】「汹涌」的「汹」是三点水，不要写成「凶」。"},{"w":"腐烂","e":"【易错】「腐烂」的「腐」下面是「肉」，不要写成「府」。"},{"w":"常常","e":"【易错】「常含泪水」的「常」是「常常」，不要写成「长含泪水」。"},{"w":"嘶","e":"【易错】「嘶哑」两字都是口字旁，「嘶」不要写成「撕」。"},{"w":"撕","e":"【易错】「嘶哑」两字都是口字旁，「嘶」不要写成「撕」。"},{"w":"汹","e":"【易错】「汹涌」的「汹」是三点水，不要写成「凶」。"},{"w":"凶","e":"【易错】「汹涌」的「汹」是三点水，不要写成「凶」。"},{"w":"腐","e":"【易错】「腐烂」的「腐」下面是「肉」，不要写成「府」。"},{"w":"肉","e":"【易错】「腐烂」的「腐」下面是「肉」，不要写成「府」。"},{"w":"府","e":"【易错】「腐烂」的「腐」下面是「肉」，不要写成「府」。"},{"w":"常","e":"【易错】「常含泪水」的「常」是「常常」，不要写成「长含泪水」。"},{"w":"得","e":"【易错】「爱得深沉」的「得」是补语标志，不要写成「爱的深沉」。"}]},{"type":"list","title":"名句","items":["为什么我的眼里常含泪水？因为我对这土地爱得深沉……"]},{"type":"list","title":"背诵提示","items":["「嘶哑」两字都是口字旁，「嘶」不要写成「撕」。","「汹涌」的「汹」是三点水，不要写成「凶」。","「无止息」不要写成「无休止」。","「腐烂」的「腐」下面是「肉」，不要写成「府」。","「常含泪水」的「常」是「常常」，不要写成「长含泪水」。","「爱得深沉」的「得」是补语标志，不要写成「爱的深沉」。"]}],"questions":[{"id":"p-p9a-wo-ai-zhe-tu-di-u","type":"fill","stem":"理解性默写：假如我是一只鸟，","answer":"假如我是一只鸟，","explain":"出自《我爱这土地》（现代·艾青）。句意：假如我是一只鸟，","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-xiang-chou","title":"乡愁","subtitle":"现代·余光中","grade":"9a","tags":["思乡","现代诗","意象"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"现代·余光中"},{"k":"体裁","v":"现代诗"}]},{"type":"note","title":"作者简介","text":"余光中（1928—2017），当代诗人、散文家、翻译家、学者，生于江苏南京，祖籍福建永春，青年时代随家人迁居台湾，毕业于台湾大学外文系。\n生平经历：他曾赴美国进修，并在台湾、香港多所高校任教，后任台湾中山大学教授；一生笔耕不辍，诗、散文、评论、翻译均有建树，被称为“乡愁诗人”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗以时间顺序结构全篇，用「小时候」「长大后」「后来啊」「而现在」四个人生阶段串起四组意象：邮票、船票、坟墓、海峡，把抽象的乡愁化为可触可感的具体事物，层层递进，由个人的母子之思、夫妻之恋扩展到对祖国大陆的深切怀念，「浅浅的海峡」以浅衬深，成为全诗情感的高峰。四个诗节字数、句式大致相同，回环往复，形成音乐美与建筑美。中考常考：四个意象各自寄托的情感；时间顺序与情感递进的关系；「小小的」「窄窄的」「矮矮的」「浅浅的」这组叠词的表达效果（反衬乡愁之重、之深）；托物寄情与反复咏叹的手法。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"小时候，","n":"","cn":"小时候，","parts":[{"t":"小时候，"}]},{"t":"乡愁是一枚小小的邮票，","n":"","cn":"乡愁是一枚小小的邮票，","parts":[{"t":"乡愁是"},{"t":"一枚","k":3},{"t":"小小的邮票，"}]},{"t":"我在这头，","n":"","cn":"我在这头，","parts":[{"t":"我在这头，"}]},{"t":"母亲在那头。","n":"","cn":"母亲在那头。","parts":[{"t":"母亲在那头。"}]},{"t":"长大后，","n":"","cn":"长大以后，","parts":[{"t":"长大后，"}]},{"t":"乡愁是一张窄窄的船票，","n":"","cn":"乡愁是一张窄窄的船票，","parts":[{"t":"乡愁是"},{"t":"一张","k":4},{"t":"窄窄的船票，"}]},{"t":"我在这头，","n":"","cn":"我在这头，","parts":[{"t":"我在这头，"}]},{"t":"新娘在那头。","n":"","cn":"新娘在那头。","parts":[{"t":"新娘在那头。"}]},{"t":"后来啊，","n":"","cn":"后来啊，","parts":[{"t":"后来啊","k":1},{"t":"，"}]},{"t":"乡愁是一方矮矮的坟墓，","n":"","cn":"乡愁是一方矮矮的坟墓，","parts":[{"t":"乡愁是"},{"t":"一方","k":5},{"t":"矮矮的"},{"t":"坟墓","k":7},{"t":"，"}]},{"t":"我在外头，","n":"","cn":"我在外头，","parts":[{"t":"我在外头，"}]},{"t":"母亲在里头。","n":"","cn":"母亲在里头。","parts":[{"t":"母亲在里头。"}]},{"t":"而现在，","n":"","cn":"而如今，","parts":[{"t":"而现在，"}]},{"t":"乡愁是一湾浅浅的海峡，","n":"","cn":"乡愁是一湾浅浅的海峡，","parts":[{"t":"乡愁是"},{"t":"一湾","k":6},{"t":"浅浅的"},{"t":"海峡","k":8},{"t":"，"}]},{"t":"我在这头，","n":"","cn":"我在这头，","parts":[{"t":"我在这头，"}]},{"t":"大陆在那头。","n":"","cn":"大陆在那头。","parts":[{"t":"大陆","k":9},{"t":"在那头。"}]}],"words":[{"w":"一枚邮票","e":"【易错】「一枚邮票」的「枚」是量词，不要写成「一玫」。"},{"w":"后来啊","e":"【易错】「后来啊」的「啊」不要漏写，「大陆」的「陆」左耳旁不要写成「阝」右置。"},{"w":"一玫","e":"【易错】「一枚邮票」的「枚」是量词，不要写成「一玫」。"},{"w":"一枚","e":"【易错】「一枚」「一张」「一方」「一湾」四个量词各不相同，默写时容易互换致错。"},{"w":"一张","e":"【易错】「一枚」「一张」「一方」「一湾」四个量词各不相同，默写时容易互换致错。"},{"w":"一方","e":"【易错】「一枚」「一张」「一方」「一湾」四个量词各不相同，默写时容易互换致错。"},{"w":"一湾","e":"【易错】「一枚」「一张」「一方」「一湾」四个量词各不相同，默写时容易互换致错。"},{"w":"坟墓","e":"【易错】「坟墓」的「墓」下面是「土」，不要写成「暮」「幕」。"},{"w":"海峡","e":"【易错】「海峡」的「峡」是山字旁，不要写成「夹」或「侠」。"},{"w":"大陆","e":"【易错】「后来啊」的「啊」不要漏写，「大陆」的「陆」左耳旁不要写成「阝」右置。"},{"w":"枚","e":"【易错】「一枚邮票」的「枚」是量词，不要写成「一玫」。"},{"w":"墓","e":"【易错】「坟墓」的「墓」下面是「土」，不要写成「暮」「幕」。"},{"w":"土","e":"【易错】「坟墓」的「墓」下面是「土」，不要写成「暮」「幕」。"},{"w":"暮","e":"【易错】「坟墓」的「墓」下面是「土」，不要写成「暮」「幕」。"},{"w":"幕","e":"【易错】「坟墓」的「墓」下面是「土」，不要写成「暮」「幕」。"},{"w":"峡","e":"【易错】「海峡」的「峡」是山字旁，不要写成「夹」或「侠」。"},{"w":"夹","e":"【易错】「海峡」的「峡」是山字旁，不要写成「夹」或「侠」。"},{"w":"侠","e":"【易错】「海峡」的「峡」是山字旁，不要写成「夹」或「侠」。"},{"w":"啊","e":"【易错】「后来啊」的「啊」不要漏写，「大陆」的「陆」左耳旁不要写成「阝」右置。"},{"w":"陆","e":"【易错】「后来啊」的「啊」不要漏写，「大陆」的「陆」左耳旁不要写成「阝」右置。"},{"w":"阝","e":"【易错】「后来啊」的「啊」不要漏写，「大陆」的「陆」左耳旁不要写成「阝」右置。"}]},{"type":"list","title":"名句","items":["而现在，乡愁是一湾浅浅的海峡，我在这头，大陆在那头。"]},{"type":"list","title":"背诵提示","items":["「一枚邮票」的「枚」是量词，不要写成「一玫」。","「一枚」「一张」「一方」「一湾」四个量词各不相同，默写时容易互换致错。","「坟墓」的「墓」下面是「土」，不要写成「暮」「幕」。","「海峡」的「峡」是山字旁，不要写成「夹」或「侠」。","「后来啊」的「啊」不要漏写，「大陆」的「陆」左耳旁不要写成「阝」右置。"]}],"questions":[{"id":"p-p9a-xiang-chou-m0","type":"fill","stem":"默写填空：而现在，______。","answer":"乡愁是一湾浅浅的海峡。","explain":"出自《乡愁》（现代·余光中）：而现在，乡愁是一湾浅浅的海峡，我在这头，大陆在那头。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-xiang-chou-u","type":"fill","stem":"理解性默写：乡愁是一枚小小的邮票，","answer":"乡愁是一枚小小的邮票，","explain":"出自《乡愁》（现代·余光中）。句意：乡愁是一枚小小的邮票，","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-ni-shi-ren-jian-de-si-yue-tian","title":"你是人间的四月天——一句爱的赞颂","subtitle":"现代·林徽因","grade":"9a","tags":["抒情","现代诗","意象"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"现代·林徽因"},{"k":"体裁","v":"现代诗"}]},{"type":"note","title":"作者简介","text":"林徽因（1904—1955），原名林徽音，福建闽县（今福州）人，现代建筑师、诗人、作家，中国现代建筑学的奠基人之一。\n生平经历：她少年时随父亲游历欧洲，受到建筑与文学的双重熏陶；1924年赴美国宾夕法尼亚大学学习美术与建筑，后与梁思成结婚；回国后两人一同走遍山西、河北等地考察测绘中国古代建筑，并参与创办东北大学建筑系、执教于清华大学建筑系；她还参与了中华人民共和国国徽与人民英雄纪念碑的部分设计工作，同时写下大量诗歌、散文与小说，1955年因病在北京逝世。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"全诗以「你是人间的四月天」一句反复呼应，用四月春光里的云烟、软风、星子、细雨、百花、月圆、鹅黄、新绿、白莲、花开、燕语等一连串明净柔美的意象，把所赞颂的对象写得轻盈、温润而庄严。诗人善用通感（「笑响点亮了四面风」）与比喻叠加，句式长短错落，节奏跳脱，读来如春风拂面。结尾「你是爱，是暖，是希望」由具体意象升华为情感与哲思，点明主旨。中考常考：意象群的作用、通感与比喻的辨析、第二人称「你」的抒情效果、「四月天」的象征意义（爱与希望、生命的美好），以及反复咏叹所形成的音乐美。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"我说你是人间的四月天；","n":"","cn":"我说你是这人间的四月天；","parts":[{"t":"我说你是人间的四月天；"}]},{"t":"笑响点亮了四面风；轻灵在春的光艳中交舞着变。","n":"","cn":"你的笑语像回声点亮了四面来风；轻灵的身姿在春光艳色中交织飞舞、变幻不停。","parts":[{"t":"笑响点亮了四面风；轻灵在春的光"},{"t":"艳","k":12},{"t":"中交舞着变。"}]},{"t":"你是四月早天里的云烟，","n":"","cn":"你是四月清晨天空里的云烟，","parts":[{"t":"你是四月早天里的云烟，"}]},{"t":"黄昏吹着风的软，星子在无意中闪，细雨点洒在花前。","n":"","cn":"黄昏里吹着柔软的风，星子在无意间闪烁，细雨点点洒落在花瓣之前。","parts":[{"t":"黄昏吹着风的软，星子在无意中闪，细雨点洒在花前。"}]},{"t":"那轻，那娉婷，你是，鲜妍百花的冠冕你戴着，","n":"","cn":"那轻盈、那美好的姿态，就是你；鲜妍美丽的花冠，由你戴着，","parts":[{"t":"那轻，那"},{"t":"娉婷","k":0},{"t":"，你是，"},{"t":"鲜妍","k":2},{"t":"百花的"},{"t":"冠冕","k":3},{"t":"你戴着，"}]},{"t":"你是天真，庄严，你是夜夜的月圆。","n":"","cn":"你是天真，是庄严，你是夜夜圆满的明月。","parts":[{"t":"你是天真，庄严，你是夜夜的月圆。"}]},{"t":"雪化后那片鹅黄，你像；新鲜初放芽的绿，你是；","n":"","cn":"雪融化后那一片鹅黄，像你；新枝初放嫩芽的绿，就是你；","parts":[{"t":"雪化后那片"},{"t":"鹅黄","k":5},{"t":"，你像；新鲜初放芽的绿，你是；"}]},{"t":"柔嫩喜悦水光浮动着你梦期待中白莲。","n":"","cn":"柔嫩而喜悦的水光中，浮动着你梦中所期待的白莲。","parts":[{"t":"柔嫩","k":8},{"t":"喜悦水光浮动着你梦期待中白莲。"}]},{"t":"你是一树一树的花开，是燕在梁间呢喃，","n":"","cn":"你是一树一树盛开的花，是燕子在梁间呢喃细语，","parts":[{"t":"你是一树一树的花"},{"t":"开","k":10},{"t":"，是燕在梁间"},{"t":"呢喃","k":6},{"t":"，"}]},{"t":"——你是爱，是暖，是希望，你是人间的四月天！","n":"","cn":"——你是爱，是暖，是希望，你就是这人间最美的四月天！","parts":[{"t":"——你是爱，是暖，是希望，你是人间的四月天！"}]}],"words":[{"w":"娉婷","e":"【易错】「娉婷」两字都是女字旁，不要写成「聘婷」。"},{"w":"聘婷","e":"【易错】「娉婷」两字都是女字旁，不要写成「聘婷」。"},{"w":"鲜妍","e":"【易错】「鲜妍」的「妍」是女字旁加「开」，不要写成「研」「艳」。"},{"w":"冠冕","e":"【易错】「冠冕」的「冕」上面是「冂」内两横，不要写成「免冠」。"},{"w":"免冠","e":"【易错】「冠冕」的「冕」上面是「冂」内两横，不要写成「免冠」。"},{"w":"鹅黄","e":"【易错】「鹅黄」的「鹅」左旁是「鸟」，不要写成「俄」。"},{"w":"呢喃","e":"【易错】「呢喃」两字都是口字旁，不要写成「泥南」。"},{"w":"泥南","e":"【易错】「呢喃」两字都是口字旁，不要写成「泥南」。"},{"w":"柔嫩","e":"【易错】「柔嫩」的「嫩」中间是「束」，不要写成「懒」的右旁。"},{"w":"妍","e":"【易错】「鲜妍」的「妍」是女字旁加「开」，不要写成「研」「艳」。"},{"w":"开","e":"【易错】「鲜妍」的「妍」是女字旁加「开」，不要写成「研」「艳」。"},{"w":"研","e":"【易错】「鲜妍」的「妍」是女字旁加「开」，不要写成「研」「艳」。"},{"w":"艳","e":"【易错】「鲜妍」的「妍」是女字旁加「开」，不要写成「研」「艳」。"},{"w":"冕","e":"【易错】「冠冕」的「冕」上面是「冂」内两横，不要写成「免冠」。"},{"w":"冂","e":"【易错】「冠冕」的「冕」上面是「冂」内两横，不要写成「免冠」。"},{"w":"鹅","e":"【易错】「鹅黄」的「鹅」左旁是「鸟」，不要写成「俄」。"},{"w":"鸟","e":"【易错】「鹅黄」的「鹅」左旁是「鸟」，不要写成「俄」。"},{"w":"俄","e":"【易错】「鹅黄」的「鹅」左旁是「鸟」，不要写成「俄」。"},{"w":"嫩","e":"【易错】「柔嫩」的「嫩」中间是「束」，不要写成「懒」的右旁。"},{"w":"束","e":"【易错】「柔嫩」的「嫩」中间是「束」，不要写成「懒」的右旁。"},{"w":"懒","e":"【易错】「柔嫩」的「嫩」中间是「束」，不要写成「懒」的右旁。"}]},{"type":"list","title":"名句","items":["你是爱，是暖，是希望，你是人间的四月天！"]},{"type":"list","title":"背诵提示","items":["「娉婷」两字都是女字旁，不要写成「聘婷」。","「鲜妍」的「妍」是女字旁加「开」，不要写成「研」「艳」。","「冠冕」的「冕」上面是「冂」内两横，不要写成「免冠」。","「鹅黄」的「鹅」左旁是「鸟」，不要写成「俄」。","「呢喃」两字都是口字旁，不要写成「泥南」。","「柔嫩」的「嫩」中间是「束」，不要写成「懒」的右旁。"]}],"questions":[{"id":"p-p9a-ni-shi-ren-jian-de-si-yue-tian-m0","type":"fill","stem":"默写填空：你是爱，______。","answer":"是暖。","explain":"出自《你是人间的四月天——一句爱的赞颂》（现代·林徽因）：你是爱，是暖，是希望，你是人间的四月天！","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-ni-shi-ren-jian-de-si-yue-tian-u","type":"fill","stem":"理解性默写：我说你是这人间的四月天；","answer":"我说你是人间的四月天；","explain":"出自《你是人间的四月天——一句爱的赞颂》（现代·林徽因）。句意：我说你是这人间的四月天；","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-yue-yang-lou-ji","title":"岳阳楼记","subtitle":"宋·范仲淹","grade":"9a","tags":["文言文","写景","抱负"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·范仲淹"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"范仲淹（989—1052），字希文，谥号“文正”，苏州吴县（今江苏苏州）人，北宋政治家、文学家，后人尊称他为“范文正公”。\n生平经历：他两岁丧父，少年时家贫而刻苦读书，“划粥断齑”的苦读故事流传至今；考中进士后历任地方与朝廷官职，为官清正敢言，曾因直言进谏而多次被贬；庆历年间官至参知政事，主持“庆历新政”，推行整顿吏治、改革科举等主张，因守旧派反对而失败；晚年出任地方官，在赴颍州途中病逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文是范仲淹应滕子京之请为重修岳阳楼所写的记。文中先叙修楼缘由，再总写洞庭湖的雄伟气象，然后用「若夫」「至若」两段分写阴雨与春和两种景象下迁客骚人「以物喜」「以己悲」的不同心情，最后以「嗟夫」一转，借古仁人之心提出「不以物喜，不以己悲」的旷达胸襟与「先天下之忧而忧，后天下之乐而乐」的政治抱负。写法上叙事、写景、抒情、议论融为一体，骈散结合，音韵铿锵；「先天下之忧而忧，后天下之乐而乐」是千古名句，也是中考默写与主旨鉴赏的核心考点。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"庆历四年春，滕子京谪守巴陵郡。越明年，政通人和，百废具兴，乃重修岳阳楼，增其旧制，刻唐贤今人诗赋于其上，属予作文以记之。","n":"","cn":"庆历四年春天，滕子京被贬到巴陵郡做太守。到了第二年，政务顺利、百姓和乐，各种荒废的事业都兴办起来了，于是重新修建岳阳楼，扩大它原来的规模，把唐代和当代名人的诗赋刻在上面，嘱托我写篇文章来记述这件事。","parts":[{"t":"庆历四年春，滕子京谪守巴陵郡。越明年，政通人和，"},{"t":"百废具兴","k":0},{"t":"，乃重修岳阳楼，增其旧制，刻唐贤今人诗赋于其上，"},{"t":"属","k":10},{"t":"予作文以记之。"}]},{"t":"予观夫巴陵胜状，在洞庭一湖。衔远山，吞长江，浩浩汤汤，横无际涯，朝晖夕阴，气象万千，此则岳阳楼之大观也，前人之述备矣。","n":"","cn":"我看那巴陵郡的美景，全在洞庭湖上。它连接着远山，吞纳着长江，水势浩大，宽阔无边，清晨阳光照耀、傍晚阴气凝结，景象千变万化，这就是岳阳楼的雄伟景象，前人的记述已经很详尽了。","parts":[{"t":"予观夫巴陵胜状，在洞庭一湖。衔远山，吞长江，"},{"t":"浩浩汤汤","k":1},{"t":"，"},{"t":"横无际涯","k":4},{"t":"，"},{"t":"朝晖夕阴","k":3},{"t":"，气象万千，此则岳阳楼之大观也，前人之述备矣。"}]},{"t":"然则北通巫峡，南极潇湘，迁客骚人，多会于此，览物之情，得无异乎？","n":"","cn":"既然如此，那么洞庭湖向北通往巫峡，向南直到潇水湘水，降职远调的官员和不得志的诗人，大多在这里聚会，他们观赏景物的心情，大概会有所不同吧？","parts":[{"t":"然则北通巫峡，南极潇湘，迁客骚人，多会于此，览物之情，得无异乎？"}]},{"t":"嗟夫！予尝求古仁人之心，或异二者之为，何哉？","n":"","cn":"唉！我曾探求古代品德高尚的人的心境，也许不同于（上面）这两种表现，为什么呢？","parts":[{"t":"嗟夫！予尝求古仁人之心，或异二者之为，何哉？"}]},{"t":"不以物喜，不以己悲，居庙堂之高则忧其民，处江湖之远则忧其君。","n":"","cn":"他们不因外物好坏和自己得失而或喜或悲；在朝廷做官就为百姓忧虑，被贬到边远地区就为君主担忧。","parts":[{"t":"不以物喜，不以己悲，居庙堂之高则"},{"t":"忧","k":19},{"t":"其民，处江湖之远则"},{"t":"忧","k":19},{"t":"其君。"}]},{"t":"是进亦忧，退亦忧。然则何时而乐耶？","n":"","cn":"这样看来，进朝廷做官也忧虑，退处江湖也忧虑。那么什么时候才快乐呢？","parts":[{"t":"是进亦"},{"t":"忧","k":19},{"t":"，退亦"},{"t":"忧","k":19},{"t":"。然则何时而"},{"t":"乐","k":20},{"t":"耶？"}]},{"t":"其必曰“先天下之忧而忧，后天下之乐而乐”乎！","n":"","cn":"他们一定会说“在天下人忧虑之前先忧虑，在天下人快乐之后才快乐”吧！","parts":[{"t":"其必曰“先天下之"},{"t":"忧","k":19},{"t":"而"},{"t":"忧","k":19},{"t":"，后天下之"},{"t":"乐","k":20},{"t":"而"},{"t":"乐","k":20},{"t":"”乎！"}]},{"t":"噫！微斯人，吾谁与归？","n":"","cn":"唉！如果没有这样的人，我还能同谁一道呢？","parts":[{"t":"噫！微斯人，吾谁与归？"}]}],"words":[{"w":"百废具兴","e":"【易错】「百废具兴」的「具」通「俱」，是「全、都」的意思，不要写成「俱」。"},{"w":"浩浩汤汤","e":"【易错】「浩浩汤汤」读 hào hào shāng shāng，不要写成「浩浩荡荡」。"},{"w":"浩浩荡荡","e":"【易错】「浩浩汤汤」读 hào hào shāng shāng，不要写成「浩浩荡荡」。"},{"w":"朝晖夕阴","e":"【易错】「朝晖夕阴」的「晖」是日字旁，不要写成「辉」。"},{"w":"横无际涯","e":"【易错】「横无际涯」的「涯」是三点水，不要写成「崖」。"},{"w":"薄暮冥冥","e":"【易错】「薄暮冥冥」的「冥」不要写成「暝」；「岸芷汀兰」的「汀」是三点水。"},{"w":"岸芷汀兰","e":"【易错】「薄暮冥冥」的「冥」不要写成「暝」；「岸芷汀兰」的「汀」是三点水。"},{"w":"嘱予","e":"【易错】「属予作文以记之」的「属」通「嘱」，读 zhǔ，不要写成「嘱予」。"},{"w":"具","e":"【易错】「百废具兴」的「具」通「俱」，是「全、都」的意思，不要写成「俱」。"},{"w":"俱","e":"【易错】「百废具兴」的「具」通「俱」，是「全、都」的意思，不要写成「俱」。"},{"w":"属","e":"【易错】「属予作文以记之」的「属」通「嘱」，读 zhǔ，不要写成「嘱予」。"},{"w":"嘱","e":"【易错】「属予作文以记之」的「属」通「嘱」，读 zhǔ，不要写成「嘱予」。"},{"w":"晖","e":"【易错】「朝晖夕阴」的「晖」是日字旁，不要写成「辉」。"},{"w":"辉","e":"【易错】「朝晖夕阴」的「晖」是日字旁，不要写成「辉」。"},{"w":"涯","e":"【易错】「横无际涯」的「涯」是三点水，不要写成「崖」。"},{"w":"崖","e":"【易错】「横无际涯」的「涯」是三点水，不要写成「崖」。"},{"w":"冥","e":"【易错】「薄暮冥冥」的「冥」不要写成「暝」；「岸芷汀兰」的「汀」是三点水。"},{"w":"暝","e":"【易错】「薄暮冥冥」的「冥」不要写成「暝」；「岸芷汀兰」的「汀」是三点水。"},{"w":"汀","e":"【易错】「薄暮冥冥」的「冥」不要写成「暝」；「岸芷汀兰」的「汀」是三点水。"},{"w":"忧","e":"【易错】「先天下之忧而忧」两句中两个「忧」「乐」的位置不要颠倒。"},{"w":"乐","e":"【易错】「先天下之忧而忧」两句中两个「忧」「乐」的位置不要颠倒。"}]},{"type":"list","title":"名句","items":["先天下之忧而忧，后天下之乐而乐。","不以物喜，不以己悲。"]},{"type":"list","title":"背诵提示","items":["「百废具兴」的「具」通「俱」，是「全、都」的意思，不要写成「俱」。","「属予作文以记之」的「属」通「嘱」，读 zhǔ，不要写成「嘱予」。","「浩浩汤汤」读 hào hào shāng shāng，不要写成「浩浩荡荡」。","「朝晖夕阴」的「晖」是日字旁，不要写成「辉」。","「横无际涯」的「涯」是三点水，不要写成「崖」。","「薄暮冥冥」的「冥」不要写成「暝」；「岸芷汀兰」的「汀」是三点水。","「先天下之忧而忧」两句中两个「忧」「乐」的位置不要颠倒。"]}],"questions":[{"id":"p-p9a-yue-yang-lou-ji-m0","type":"fill","stem":"默写填空：先天下之忧而忧，______。","answer":"后天下之乐而乐。","explain":"出自《岳阳楼记》（宋·范仲淹）：先天下之忧而忧，后天下之乐而乐。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-yue-yang-lou-ji-m1","type":"fill","stem":"默写填空：不以物喜，______。","answer":"不以己悲。","explain":"出自《岳阳楼记》（宋·范仲淹）：不以物喜，不以己悲。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-yue-yang-lou-ji-u","type":"fill","stem":"理解性默写：庆历四年春天，滕子京被贬到巴陵郡做太守。到了第二年，政务顺利、百姓和乐，各种荒废的事业都兴办起来了，于是重新修建岳阳楼，扩大它原来的规模，把唐代和当代名人的诗赋刻在上面，嘱托我写篇文章来记述这件事。","answer":"庆历四年春，滕子京谪守巴陵郡。越明年，政通人和，百废具兴，乃重修岳阳楼，增其旧制，刻唐贤今人诗赋于其上，属予作文以记之。","explain":"出自《岳阳楼记》（宋·范仲淹）。句意：庆历四年春天，滕子京被贬到巴陵郡做太守。到了第二年，政务顺利、百姓和乐，各种荒废的事业都兴办起来了，于是重新修建岳阳楼，扩大它原来的规模，把唐代和当代名人的诗赋刻在上面，嘱托我写篇文章来记述这件事。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-zui-weng-ting-ji","title":"醉翁亭记","subtitle":"宋·欧阳修","grade":"9a","tags":["文言文","写景","与民同乐"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·欧阳修"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"欧阳修（1007—1072），字永叔，号醉翁，晚年又号六一居士，吉州永丰（今江西永丰）人，北宋文学家、史学家、政治家，谥号“文忠”。\n生平经历：他四岁丧父，家境贫寒，母亲郑氏以芦荻画地教他识字，“画荻教子”传为佳话；天圣八年考中进士，为官刚直敢言，因支持范仲淹新政而屡遭贬谪，先后任滁州、扬州、颍州等地知州；晚年官至参知政事，主持编修《新唐书》，并独自撰写《新五代史》。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"全文以「乐」字贯穿，先写亭的环境与得名，次写山间朝暮四时的景物之乐，再写滁人游、太守宴、众宾欢、太守醉的游乐场面，最后以禽鸟之乐、众人之乐层层衬托太守「乐其乐」的境界，点出与民同乐的主旨。艺术上最突出的是「也」字句的反复运用，二十一个「也」字一韵到底，骈散相间，从容舒缓，如行云流水；写景则动静结合、四时有序。中考常考：写景顺序（空间顺序与时间顺序）、「醉翁之意不在酒」的原意与成语义、层层衬托的写法，以及「林霏开」的「霏」、「云归而岩穴暝」的「暝」等易错字。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"环滁皆山也。其西南诸峰，林壑尤美，望之蔚然而深秀者，琅琊也。","n":"","cn":"环绕滁州城的都是山。它西南方的各个山峰，树林和山谷尤其秀美，远望那树木茂盛、又幽深又秀丽的，是琅琊山。","parts":[{"t":"环滁皆山也。其西南诸峰，"},{"t":"林壑尤美","k":0},{"t":"，望之"},{"t":"蔚","k":10},{"t":"然"},{"t":"而","k":24},{"t":"深秀者，琅琊也。"}]},{"t":"山行六七里，渐闻水声潺潺，而泻出于两峰之间者，酿泉也。","n":"","cn":"沿着山路走六七里，渐渐听到潺潺的水声，从两座山峰之间倾泻而出的，是酿泉。","parts":[{"t":"山行六七里，渐闻"},{"t":"水声潺潺","k":1},{"t":"，"},{"t":"而","k":24},{"t":"泻出于两峰之间者，酿泉也。"}]},{"t":"峰回路转，有亭翼然临于泉上者，醉翁亭也。","n":"","cn":"山势回环、道路转弯，有一座亭子四角翘起、像鸟张开翅膀一样高踞在泉水之上的，是醉翁亭。","parts":[{"t":"峰回路转，"},{"t":"有亭翼然","k":2},{"t":"临于泉上者，醉翁亭也。"}]},{"t":"作亭者谁？山之僧智仙也。名之者谁？太守自谓也。","n":"","cn":"建造亭子的是谁？是山里的和尚智仙。给它命名的是谁？是太守用自己的别号来命名的。","parts":[{"t":"作亭者谁？山之僧智仙也。名之者谁？太守自谓也。"}]},{"t":"太守与客来饮于此，饮少辄醉，而年又最高，故自号曰醉翁也。","n":"","cn":"太守同宾客到这里来饮酒，喝很少就醉了，而且年纪又最大，所以给自己取号叫醉翁。","parts":[{"t":"太守与客来饮于此，"},{"t":"饮少辄醉","k":3},{"t":"，"},{"t":"而","k":24},{"t":"年又最高，故自号曰醉翁也。"}]},{"t":"醉翁之意不在酒，在乎山水之间也。山水之乐，得之心而寓之酒也。","n":"","cn":"醉翁的情趣不在于喝酒，而在于山水之间。欣赏山水的乐趣，领会在心里，寄托在酒上。","parts":[{"t":"醉翁之意不在酒，在乎山水之间也。山水之乐，得之心"},{"t":"而","k":24},{"t":"寓之酒也。"}]},{"t":"若夫日出而林霏开，云归而岩穴暝，晦明变化者，山间之朝暮也。","n":"","cn":"像那太阳出来，树林里的雾气散开；云雾聚拢，山谷岩穴就昏暗了；这明暗交替变化的，是山间的早晨和傍晚。","parts":[{"t":"若夫日出"},{"t":"而","k":24},{"t":"林霏开","k":5},{"t":"，云归"},{"t":"而","k":24},{"t":"岩穴暝","k":6},{"t":"，晦明变化者，山间之朝暮也。"}]},{"t":"野芳发而幽香，佳木秀而繁阴，风霜高洁，水落而石出者，山间之四时也。","n":"","cn":"野花开放而散发出清幽的香气，美好的树木枝叶繁茂而形成浓荫，天高气爽、霜色洁白，水位下降而石头露出，这是山间的四季。","parts":[{"t":"野芳发"},{"t":"而","k":24},{"t":"幽香，佳木秀"},{"t":"而","k":24},{"t":"繁阴，风霜高洁，水落"},{"t":"而","k":24},{"t":"石出者，山间之四时也。"}]},{"t":"已而夕阳在山，人影散乱，太守归而宾客从也。","n":"","cn":"不久太阳落到西山上，人影纷乱，太守回去而宾客跟随着。","parts":[{"t":"已"},{"t":"而","k":24},{"t":"夕阳在山，人影散乱，太守归"},{"t":"而","k":24},{"t":"宾客从也。"}]},{"t":"然而禽鸟知山林之乐，而不知人之乐；人知从太守游而乐，而不知太守之乐其乐也。","n":"","cn":"然而鸟儿只知道山林的乐趣，却不知道人的乐趣；人们只知道跟着太守游玩的乐趣，却不知道太守以他们的快乐为快乐。","parts":[{"t":"然"},{"t":"而","k":24},{"t":"禽鸟知山林之乐，"},{"t":"而","k":24},{"t":"不知人之乐；人知从太守游"},{"t":"而","k":24},{"t":"乐，"},{"t":"而","k":24},{"t":"不知太守之乐其乐也。"}]}],"words":[{"w":"林壑尤美","e":"【易错】「林壑尤美」的「壑」上面是「睿」的变体，不要漏写下面「土」。"},{"w":"水声潺潺","e":"【易错】「水声潺潺」的「潺」是三点水，不要写成「孱」。"},{"w":"有亭翼然","e":"【易错】「有亭翼然」的「翼」不要写成「冀」。"},{"w":"饮少辄醉","e":"【易错】「饮少辄醉」的「辄」是「车」加「取」，不要写成「辙」。"},{"w":"水落石出","e":"【易错】「水落而石出」不要写成「水落石出」而漏掉虚词（课文原句有「而」）。"},{"w":"林霏开","e":"【易错】「林霏开」的「霏」是雨字头，不要写成「菲」。"},{"w":"岩穴暝","e":"【易错】「岩穴暝」的「暝」是日字旁，表示昏暗，不要写成「冥」。"},{"w":"壑","e":"【易错】「林壑尤美」的「壑」上面是「睿」的变体，不要漏写下面「土」。"},{"w":"睿","e":"【易错】「林壑尤美」的「壑」上面是「睿」的变体，不要漏写下面「土」。"},{"w":"土","e":"【易错】「林壑尤美」的「壑」上面是「睿」的变体，不要漏写下面「土」。"},{"w":"蔚","e":"【易错】「蔚然而深秀」的「蔚」是草字头，不要写成「慰」。"},{"w":"慰","e":"【易错】「蔚然而深秀」的「蔚」是草字头，不要写成「慰」。"},{"w":"潺","e":"【易错】「水声潺潺」的「潺」是三点水，不要写成「孱」。"},{"w":"孱","e":"【易错】「水声潺潺」的「潺」是三点水，不要写成「孱」。"},{"w":"翼","e":"【易错】「有亭翼然」的「翼」不要写成「冀」。"},{"w":"冀","e":"【易错】「有亭翼然」的「翼」不要写成「冀」。"},{"w":"辄","e":"【易错】「饮少辄醉」的「辄」是「车」加「取」，不要写成「辙」。"},{"w":"车","e":"【易错】「饮少辄醉」的「辄」是「车」加「取」，不要写成「辙」。"},{"w":"取","e":"【易错】「饮少辄醉」的「辄」是「车」加「取」，不要写成「辙」。"},{"w":"辙","e":"【易错】「饮少辄醉」的「辄」是「车」加「取」，不要写成「辙」。"},{"w":"霏","e":"【易错】「林霏开」的「霏」是雨字头，不要写成「菲」。"},{"w":"菲","e":"【易错】「林霏开」的「霏」是雨字头，不要写成「菲」。"},{"w":"暝","e":"【易错】「岩穴暝」的「暝」是日字旁，表示昏暗，不要写成「冥」。"},{"w":"冥","e":"【易错】「岩穴暝」的「暝」是日字旁，表示昏暗，不要写成「冥」。"},{"w":"而","e":"【易错】「水落而石出」不要写成「水落石出」而漏掉虚词（课文原句有「而」）。"}]},{"type":"list","title":"名句","items":["醉翁之意不在酒，在乎山水之间也。","野芳发而幽香，佳木秀而繁阴。"]},{"type":"list","title":"背诵提示","items":["「林壑尤美」的「壑」上面是「睿」的变体，不要漏写下面「土」。","「蔚然而深秀」的「蔚」是草字头，不要写成「慰」。","「水声潺潺」的「潺」是三点水，不要写成「孱」。","「有亭翼然」的「翼」不要写成「冀」。","「饮少辄醉」的「辄」是「车」加「取」，不要写成「辙」。","「林霏开」的「霏」是雨字头，不要写成「菲」。","「岩穴暝」的「暝」是日字旁，表示昏暗，不要写成「冥」。","「水落而石出」不要写成「水落石出」而漏掉虚词（课文原句有「而」）。"]}],"questions":[{"id":"p-p9a-zui-weng-ting-ji-m0","type":"fill","stem":"默写填空：醉翁之意不在酒，______。","answer":"在乎山水之间也。","explain":"出自《醉翁亭记》（宋·欧阳修）：醉翁之意不在酒，在乎山水之间也。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-zui-weng-ting-ji-m1","type":"fill","stem":"默写填空：野芳发而幽香，______。","answer":"佳木秀而繁阴。","explain":"出自《醉翁亭记》（宋·欧阳修）：野芳发而幽香，佳木秀而繁阴。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-zui-weng-ting-ji-u","type":"fill","stem":"理解性默写：环绕滁州城的都是山。它西南方的各个山峰，树林和山谷尤其秀美，远望那树木茂盛、又幽深又秀丽的，是琅琊山。","answer":"环滁皆山也。其西南诸峰，林壑尤美，望之蔚然而深秀者，琅琊也。","explain":"出自《醉翁亭记》（宋·欧阳修）。句意：环绕滁州城的都是山。它西南方的各个山峰，树林和山谷尤其秀美，远望那树木茂盛、又幽深又秀丽的，是琅琊山。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-hu-xin-ting-kan-xue","title":"湖心亭看雪","subtitle":"明·张岱","grade":"9a","tags":["文言文","写景","白描"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"明·张岱"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"张岱（1597—约1689），字宗子，又字石公，号陶庵，别号蝶庵居士，山阴（今浙江绍兴）人，明末清初文学家、史学家。他出身官宦世家，早年生活优裕，自称“少为纨绔子弟，极爱繁华”。\n生平经历：他家中藏书极富，自幼读书广博，又喜好山水、音乐、戏曲，多才多艺，却科举失意、屡试不第，未曾入仕；明朝灭亡后，他避兵隐居剡溪山中，生活贫困，专意著书，在追忆前朝繁华中寄托故国之思。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文是张岱追忆往昔的忆旧小品，写雪夜独往湖心亭看雪的雅兴与奇遇。写景最见功力：「雾凇沆砀，天与云与山与水，上下一白」以大写意渲染天地皆白的浑茫境界；「一痕」「一点」「一芥」「两三粒」用极小的量词与极简的笔触，与天地之白形成强烈对比，宛如一幅水墨白描，也暗含人在天地间的渺小与孤高。叙事上「独往」与「两人对坐」相映，结尾借舟子之口说「痴」，既写痴迷山水的雅趣，也寄寓故国之思与遗世独立的情怀。中考常考：白描手法与量词的妙用、动静与大小对比、「痴」字的多重含义、作者孤高自赏的情感。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"崇祯五年十二月，余住西湖。大雪三日，湖中人鸟声俱绝。","n":"","cn":"崇祯五年十二月，我住在西湖边。大雪下了三天，湖中行人、飞鸟的声音都消失了。","parts":[{"t":"崇祯","k":4},{"t":"五年十二月，余住西湖。大雪三日，湖中人鸟声俱绝。"}]},{"t":"是日更定矣，余拏一小舟，拥毳衣炉火，独往湖心亭看雪。","n":"","cn":"这一天初更时分，我撑着一叶小舟，裹着裘皮衣服、带着火炉，独自前往湖心亭看雪。","parts":[{"t":"是日更定矣，余"},{"t":"拏","k":10},{"t":"一小舟，拥"},{"t":"毳衣","k":5},{"t":"炉火，独往湖心亭看雪。"}]},{"t":"雾凇沆砀，天与云与山与水，上下一白。","n":"","cn":"冰花周围弥漫着白汽，天空、云层、山峦和湖水，上上下下一片雪白。","parts":[{"t":"雾凇沆砀","k":0},{"t":"，天与云与山与水，上下一"},{"t":"白","k":22},{"t":"。"}]},{"t":"湖上影子，惟长堤一痕、湖心亭一点、与余舟一芥、舟中人两三粒而已。","n":"","cn":"湖上的影子，只有长堤的一道痕迹、湖心亭的一个点、和我的一叶小舟、舟中的两三个人影罢了。","parts":[{"t":"湖上影子，惟"},{"t":"长堤一痕","k":1},{"t":"、湖心亭一点、与"},{"t":"余舟一芥","k":2},{"t":"、舟中人两三粒而已。"}]},{"t":"到亭上，有两人铺毡对坐，一童子烧酒炉正沸。","n":"","cn":"到了亭子上，看见有两个人铺着毡子相对而坐，一个童子正把酒炉烧得滚沸。","parts":[{"t":"到亭上，有两人铺毡对坐，一童子烧酒炉正沸。"}]},{"t":"见余大喜曰：“湖中焉得更有此人！”拉余同饮。余强饮三大白而别。","n":"","cn":"他们看见我非常高兴地说：“湖中哪能还有这样的人呢！”拉着我一同饮酒。我痛饮了三大杯就告辞了。","parts":[{"t":"见余大喜曰：“湖中焉得更有此人！”拉余同饮。余"},{"t":"强","k":21},{"t":"饮三大"},{"t":"白","k":22},{"t":"而别。"}]},{"t":"问其姓氏，是金陵人，客此。","n":"","cn":"问他们的姓氏，得知是金陵人，客居在这里。","parts":[{"t":"问其姓氏，是金陵人，客此。"}]},{"t":"及下船，舟子喃喃曰：“莫说相公痴，更有痴似相公者。”","n":"","cn":"等到下船时，船夫喃喃自语地说：“不要说相公您痴，还有像您一样痴的人呢。”","parts":[{"t":"及下船，"},{"t":"舟子喃喃","k":3},{"t":"曰：“莫说相公痴，更有痴似相公者。”"}]}],"words":[{"w":"雾凇沆砀","e":"【易错】「雾凇沆砀」四个字都是生僻字，其中「凇」是两点水，「沆砀」都是三点水，不要写错偏旁。"},{"w":"长堤一痕","e":"【易错】「长堤一痕」的「堤」是土字旁，不要写成「提」。"},{"w":"余舟一芥","e":"【易错】「余舟一芥」的「芥」是草字头，本指小草，不要写成「芥」以外的字形。"},{"w":"舟子喃喃","e":"【易错】「舟子喃喃」的「喃」是口字旁，不要写成「楠」。"},{"w":"崇祯","e":"【易错】「崇祯」的「祯」是示字旁，不要写成「侦」「桢」。"},{"w":"毳衣","e":"【易错】「拥毳衣炉火」的「毳」读 cuì，是三个「毛」，不要写成「毳衣」以外的字形。"},{"w":"沆砀","e":"【易错】「雾凇沆砀」四个字都是生僻字，其中「凇」是两点水，「沆砀」都是三点水，不要写错偏旁。"},{"w":"祯","e":"【易错】「崇祯」的「祯」是示字旁，不要写成「侦」「桢」。"},{"w":"侦","e":"【易错】「崇祯」的「祯」是示字旁，不要写成「侦」「桢」。"},{"w":"桢","e":"【易错】「崇祯」的「祯」是示字旁，不要写成「侦」「桢」。"},{"w":"拏","e":"【易错】「余拏一小舟」的「拏」是「奴」加「手」，读 ná，不要写成「拿」「挚」。"},{"w":"奴","e":"【易错】「余拏一小舟」的「拏」是「奴」加「手」，读 ná，不要写成「拿」「挚」。"},{"w":"手","e":"【易错】「余拏一小舟」的「拏」是「奴」加「手」，读 ná，不要写成「拿」「挚」。"},{"w":"拿","e":"【易错】「余拏一小舟」的「拏」是「奴」加「手」，读 ná，不要写成「拿」「挚」。"},{"w":"挚","e":"【易错】「余拏一小舟」的「拏」是「奴」加「手」，读 ná，不要写成「拿」「挚」。"},{"w":"毳","e":"【易错】「拥毳衣炉火」的「毳」读 cuì，是三个「毛」，不要写成「毳衣」以外的字形。"},{"w":"毛","e":"【易错】「拥毳衣炉火」的「毳」读 cuì，是三个「毛」，不要写成「毳衣」以外的字形。"},{"w":"凇","e":"【易错】「雾凇沆砀」四个字都是生僻字，其中「凇」是两点水，「沆砀」都是三点水，不要写错偏旁。"},{"w":"堤","e":"【易错】「长堤一痕」的「堤」是土字旁，不要写成「提」。"},{"w":"提","e":"【易错】「长堤一痕」的「堤」是土字旁，不要写成「提」。"},{"w":"芥","e":"【易错】「余舟一芥」的「芥」是草字头，本指小草，不要写成「芥」以外的字形。"},{"w":"强","e":"【易错】「强饮三大白」的「强」读 qiǎng，是「勉强、痛快地」，「白」指酒杯，不要理解为白色。"},{"w":"白","e":"【易错】「强饮三大白」的「强」读 qiǎng，是「勉强、痛快地」，「白」指酒杯，不要理解为白色。"},{"w":"喃","e":"【易错】「舟子喃喃」的「喃」是口字旁，不要写成「楠」。"},{"w":"楠","e":"【易错】「舟子喃喃」的「喃」是口字旁，不要写成「楠」。"}]},{"type":"list","title":"名句","items":["雾凇沆砀，天与云与山与水，上下一白。"]},{"type":"list","title":"背诵提示","items":["「崇祯」的「祯」是示字旁，不要写成「侦」「桢」。","「余拏一小舟」的「拏」是「奴」加「手」，读 ná，不要写成「拿」「挚」。","「拥毳衣炉火」的「毳」读 cuì，是三个「毛」，不要写成「毳衣」以外的字形。","「雾凇沆砀」四个字都是生僻字，其中「凇」是两点水，「沆砀」都是三点水，不要写错偏旁。","「长堤一痕」的「堤」是土字旁，不要写成「提」。","「余舟一芥」的「芥」是草字头，本指小草，不要写成「芥」以外的字形。","「强饮三大白」的「强」读 qiǎng，是「勉强、痛快地」，「白」指酒杯，不要理解为白色。","「舟子喃喃」的「喃」是口字旁，不要写成「楠」。"]}],"questions":[{"id":"p-p9a-hu-xin-ting-kan-xue-m0","type":"fill","stem":"默写填空：雾凇沆砀，______。","answer":"天与云与山与水。","explain":"出自《湖心亭看雪》（明·张岱）：雾凇沆砀，天与云与山与水，上下一白。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-hu-xin-ting-kan-xue-u","type":"fill","stem":"理解性默写：崇祯五年十二月，我住在西湖边。大雪下了三天，湖中行人、飞鸟的声音都消失了。","answer":"崇祯五年十二月，余住西湖。大雪三日，湖中人鸟声俱绝。","explain":"出自《湖心亭看雪》（明·张岱）。句意：崇祯五年十二月，我住在西湖边。大雪下了三天，湖中行人、飞鸟的声音都消失了。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-xing-lu-nan-qi-yi","title":"行路难（其一）","subtitle":"唐·李白","grade":"9a","tags":["抒情","言志","用典"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李白"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李白（701—762），字太白，号青莲居士，唐代伟大的浪漫主义诗人，被后人尊称为“诗仙”，与杜甫并称“李杜”，是我国古典诗歌浪漫主义传统的杰出代表。\n生平经历：少年时博览群书、喜好剑术任侠；二十五岁“仗剑去国”出蜀漫游，足迹遍及大江南北；天宝元年奉诏入长安供奉翰林，因遭权贵谗毁仅三年便离京；安史之乱中因参与永王李璘幕府获罪被流放夜郎，途中遇赦东归，晚年漂泊，762年病逝于当涂。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本诗是李白被「赐金放还」、离开长安时所作，写仕途受阻的苦闷与不甘沉沦的豪迈。前四句以「金樽清酒」「玉盘珍羞」的盛宴反衬「停杯投箸」「拔剑四顾」的苦闷，乐景写哀，跌宕有力；「欲渡黄河冰塞川，将登太行雪满山」用比兴（象征）手法写世路艰难；「垂钓碧溪」「乘舟梦日」连用姜尚、伊尹两个典故，表明对前途仍抱希望；末句「长风破浪会有时，直挂云帆济沧海」化用宗悫之语，境界壮阔，是全诗名句与中考默写重点。考点还涉及：通假字「羞」通「馐」、「直」通「值」；四联情绪的起伏变化（苦闷—追求—彷徨—自信）。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"金樽清酒斗十千，玉盘珍羞直万钱。","n":"","cn":"金杯里的清酒一斗值万钱，玉盘里的珍贵菜肴价值万钱。","parts":[{"t":"金樽清酒斗十千，"},{"t":"玉盘珍羞","k":0},{"t":"直万钱","k":3},{"t":"。"}]},{"t":"停杯投箸不能食，拔剑四顾心茫然。","n":"","cn":"可我放下酒杯、丢开筷子吃不下去，拔剑环顾四周，心里一片茫然。","parts":[{"t":"停杯投箸","k":1},{"t":"不能食，拔剑四顾心茫然。"}]},{"t":"欲渡黄河冰塞川，将登太行雪满山。","n":"","cn":"想渡黄河，冰雪堵塞了河川；要登太行山，大雪堆满了山岭。","parts":[{"t":"欲渡黄河"},{"t":"冰塞川","k":5},{"t":"，将登太行雪满山。"}]},{"t":"闲来垂钓碧溪上，忽复乘舟梦日边。","n":"","cn":"闲来学姜太公在碧溪上垂钓，忽然又梦见自己乘舟从太阳旁边经过。","parts":[{"t":"闲来垂钓碧溪上，忽复乘舟梦日边。"}]},{"t":"行路难！行路难！多歧路，今安在？","n":"","cn":"行路难啊，行路难！岔路这么多，如今我身在何处？","parts":[{"t":"行路难！行路难！多"},{"t":"歧路","k":7},{"t":"，今安在？"}]},{"t":"长风破浪会有时，直挂云帆济沧海。","n":"","cn":"总有一天能乘长风破万里浪，高高挂起云帆，横渡沧海。","parts":[{"t":"长风破浪会有时，"},{"t":"直挂云帆","k":2},{"t":"济沧海","k":6},{"t":"。"}]}],"words":[{"w":"玉盘珍羞","e":"【易错】「玉盘珍羞」的「羞」通「馐」，指珍奇菜肴，不要写成「馐」（课文作「羞」）。"},{"w":"停杯投箸","e":"【易错】「停杯投箸」的「箸」是竹字头，不要写成「著」。"},{"w":"直挂云帆","e":"【易错】末句「直挂云帆」不要写成「直挂云帆济苍海」。"},{"w":"直万钱","e":"【易错】「直万钱」的「直」通「值」，不要写成「值万钱」。"},{"w":"值万钱","e":"【易错】「直万钱」的「直」通「值」，不要写成「值万钱」。"},{"w":"冰塞川","e":"【易错】「冰塞川」的「塞」读 sè，不要写成「赛」。"},{"w":"济沧海","e":"【易错】「济沧海」的「沧」是三点水，不要写成「苍」。"},{"w":"歧路","e":"【易错】「歧路」的「歧」是「止」旁加「支」，不要写成「岐」。"},{"w":"羞","e":"通「馐」、「直」通「值」"},{"w":"馐","e":"【易错】「玉盘珍羞」的「羞」通「馐」，指珍奇菜肴，不要写成「馐」（课文作「羞」）。"},{"w":"直","e":"【易错】「直万钱」的「直」通「值」，不要写成「值万钱」。"},{"w":"值","e":"【易错】「直万钱」的「直」通「值」，不要写成「值万钱」。"},{"w":"箸","e":"【易错】「停杯投箸」的「箸」是竹字头，不要写成「著」。"},{"w":"著","e":"【易错】「停杯投箸」的「箸」是竹字头，不要写成「著」。"},{"w":"塞","e":"【易错】「冰塞川」的「塞」读 sè，不要写成「赛」。"},{"w":"赛","e":"【易错】「冰塞川」的「塞」读 sè，不要写成「赛」。"},{"w":"歧","e":"【易错】「歧路」的「歧」是「止」旁加「支」，不要写成「岐」。"},{"w":"止","e":"【易错】「歧路」的「歧」是「止」旁加「支」，不要写成「岐」。"},{"w":"支","e":"【易错】「歧路」的「歧」是「止」旁加「支」，不要写成「岐」。"},{"w":"岐","e":"【易错】「歧路」的「歧」是「止」旁加「支」，不要写成「岐」。"},{"w":"沧","e":"【易错】「济沧海」的「沧」是三点水，不要写成「苍」。"},{"w":"苍","e":"【易错】「济沧海」的「沧」是三点水，不要写成「苍」。"}]},{"type":"list","title":"名句","items":["长风破浪会有时，直挂云帆济沧海。"]},{"type":"list","title":"背诵提示","items":["「玉盘珍羞」的「羞」通「馐」，指珍奇菜肴，不要写成「馐」（课文作「羞」）。","「直万钱」的「直」通「值」，不要写成「值万钱」。","「停杯投箸」的「箸」是竹字头，不要写成「著」。","「冰塞川」的「塞」读 sè，不要写成「赛」。","「歧路」的「歧」是「止」旁加「支」，不要写成「岐」。","「济沧海」的「沧」是三点水，不要写成「苍」。","末句「直挂云帆」不要写成「直挂云帆济苍海」。"]}],"questions":[{"id":"p-p9a-xing-lu-nan-qi-yi-m0","type":"fill","stem":"默写填空：长风破浪会有时，______。","answer":"直挂云帆济沧海。","explain":"出自《行路难（其一）》（唐·李白）：长风破浪会有时，直挂云帆济沧海。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-xing-lu-nan-qi-yi-u","type":"fill","stem":"理解性默写：金杯里的清酒一斗值万钱，玉盘里的珍贵菜肴价值万钱。","answer":"金樽清酒斗十千，玉盘珍羞直万钱。","explain":"出自《行路难（其一）》（唐·李白）。句意：金杯里的清酒一斗值万钱，玉盘里的珍贵菜肴价值万钱。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-chou-le-tian-yang-zhou-chu-feng-xi-shang-jian-zeng","title":"酬乐天扬州初逢席上见赠","subtitle":"唐·刘禹锡","grade":"9a","tags":["酬赠","言志","哲理"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·刘禹锡"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"刘禹锡（772—842），字梦得，洛阳（今河南洛阳）人，唐代文学家、哲学家。他与柳宗元并称“刘柳”，与白居易并称“刘白”；因其诗风豪迈刚健，白居易称他为“诗豪”。\n生平经历：贞元年间与柳宗元同榜进士，后一同参与永贞革新；革新失败后先被贬为朗州司马，此后又辗转连州、夔州、和州等地，前后贬谪二十三年；晚年回到洛阳任太子宾客，世称“刘宾客”，加检校礼部尚书，卒于洛阳。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是刘禹锡在扬州初逢白居易（乐天）时的酬答之作。首联直写被贬二十三年的凄凉身世，一「弃」字沉痛；颔联连用向秀《思旧赋》和王质烂柯两个典故，抒发对故友的怀念与人事沧桑之感；颈联「沉舟侧畔千帆过，病树前头万木春」以自然景物为喻，把个人的不幸放在历史前进的长河中审视，格调由低沉转为昂扬，成为千古名句，常被引用来说明新事物必将取代旧事物；尾联回应诗题，感谢友人并自我振作。中考常考：颈联的哲理与妙处、典故的作用、全诗情感的转折，以及「烂柯人」「长精神」等词语的理解。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"巴山楚水凄凉地，二十三年弃置身。","n":"","cn":"巴山楚水这些凄凉的地方，我已被弃置在那里二十三年。","parts":[{"t":"巴山楚水"},{"t":"凄凉地","k":1},{"t":"，二十三年"},{"t":"弃置身","k":2},{"t":"。"}]},{"t":"怀旧空吟闻笛赋，到乡翻似烂柯人。","n":"","cn":"怀念故友只能空自吟诵《思旧赋》，回到家乡反而像那烂柯之人，人事全非。","parts":[{"t":"怀旧空吟"},{"t":"闻笛赋","k":3},{"t":"，到乡翻似烂"},{"t":"柯","k":12},{"t":"人。"}]},{"t":"沉舟侧畔千帆过，病树前头万木春。","n":"","cn":"沉没的船只旁边，千帆竞相驶过；枯萎的病树前面，万木争相逢春。","parts":[{"t":"沉舟侧畔","k":0},{"t":"千帆过，病树前头万木春。"}]},{"t":"今日听君歌一曲，暂凭杯酒长精神。","n":"","cn":"今天听到你为我吟唱一首诗，暂且凭借这杯酒来振作精神。","parts":[{"t":"今日听君歌一曲，暂凭杯酒"},{"t":"长","k":18},{"t":"精神。"}]}],"words":[{"w":"沉舟侧畔","e":"【易错】「沉舟侧畔」的「畔」是田字旁，不要写成「判」「叛」。"},{"w":"凄凉地","e":"【易错】「凄凉地」的「凄」是两点水，不要写成「淒」「萋」。"},{"w":"弃置身","e":"【易错】「弃置身」的「置」下面是「直」，不要写成「致」。"},{"w":"闻笛赋","e":"【易错】「闻笛赋」的「赋」是贝字旁，不要写成「斌」。"},{"w":"凄","e":"【易错】「凄凉地」的「凄」是两点水，不要写成「淒」「萋」。"},{"w":"淒","e":"【易错】「凄凉地」的「凄」是两点水，不要写成「淒」「萋」。"},{"w":"萋","e":"【易错】「凄凉地」的「凄」是两点水，不要写成「淒」「萋」。"},{"w":"置","e":"【易错】「弃置身」的「置」下面是「直」，不要写成「致」。"},{"w":"直","e":"【易错】「弃置身」的「置」下面是「直」，不要写成「致」。"},{"w":"致","e":"【易错】「弃置身」的「置」下面是「直」，不要写成「致」。"},{"w":"赋","e":"【易错】「闻笛赋」的「赋」是贝字旁，不要写成「斌」。"},{"w":"斌","e":"【易错】「闻笛赋」的「赋」是贝字旁，不要写成「斌」。"},{"w":"柯","e":"【易错】「翻似烂柯人」的「柯」是木字旁，不要写成「轲」「坷」。"},{"w":"轲","e":"【易错】「翻似烂柯人」的「柯」是木字旁，不要写成「轲」「坷」。"},{"w":"坷","e":"【易错】「翻似烂柯人」的「柯」是木字旁，不要写成「轲」「坷」。"},{"w":"畔","e":"【易错】「沉舟侧畔」的「畔」是田字旁，不要写成「判」「叛」。"},{"w":"判","e":"【易错】「沉舟侧畔」的「畔」是田字旁，不要写成「判」「叛」。"},{"w":"叛","e":"【易错】「沉舟侧畔」的「畔」是田字旁，不要写成「判」「叛」。"},{"w":"长","e":"【易错】「暂凭杯酒长精神」的「长」读 zhǎng，是振作、增长，不要写成「常」。"},{"w":"常","e":"【易错】「暂凭杯酒长精神」的「长」读 zhǎng，是振作、增长，不要写成「常」。"}]},{"type":"list","title":"名句","items":["沉舟侧畔千帆过，病树前头万木春。"]},{"type":"list","title":"背诵提示","items":["「凄凉地」的「凄」是两点水，不要写成「淒」「萋」。","「弃置身」的「置」下面是「直」，不要写成「致」。","「闻笛赋」的「赋」是贝字旁，不要写成「斌」。","「翻似烂柯人」的「柯」是木字旁，不要写成「轲」「坷」。","「沉舟侧畔」的「畔」是田字旁，不要写成「判」「叛」。","「暂凭杯酒长精神」的「长」读 zhǎng，是振作、增长，不要写成「常」。"]}],"questions":[{"id":"p-p9a-chou-le-tian-yang-zhou-chu-feng-xi-shang-jian-zeng-m0","type":"fill","stem":"默写填空：沉舟侧畔千帆过，______。","answer":"病树前头万木春。","explain":"出自《酬乐天扬州初逢席上见赠》（唐·刘禹锡）：沉舟侧畔千帆过，病树前头万木春。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-chou-le-tian-yang-zhou-chu-feng-xi-shang-jian-zeng-u","type":"fill","stem":"理解性默写：巴山楚水这些凄凉的地方，我已被弃置在那里二十三年。","answer":"巴山楚水凄凉地，二十三年弃置身。","explain":"出自《酬乐天扬州初逢席上见赠》（唐·刘禹锡）。句意：巴山楚水这些凄凉的地方，我已被弃置在那里二十三年。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-shui-diao-ge-tou-ming-yue-ji-shi-you","title":"水调歌头（明月几时有）","subtitle":"宋·苏轼","grade":"9a","tags":["中秋","怀人","哲理"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·苏轼"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"苏轼（1037—1101），字子瞻，号东坡居士，北宋著名文学家、书画家，眉州眉山（今四川眉山）人。他与父亲苏洵、弟弟苏辙合称“三苏”，父子三人同列“唐宋八大家”。\n生平经历：嘉祐二年中进士，因反对王安石变法的某些做法而自请外任，先后任杭州、密州、徐州、湖州等地知州；“乌台诗案”后被贬黄州，写下大量名篇；此后又相继被贬惠州、儋州，遇赦北归途中病逝于常州。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本词是苏轼中秋怀弟之作，被后人誉为「中秋词自东坡一出，余词尽废」。上片写把酒问月、欲乘风归去又留恋人间的矛盾，表现他既向往超脱又热爱人生的情怀；下片由月转入对人生的思索，「转朱阁，低绮户，照无眠」写月光的移动与时间的推移，「人有悲欢离合，月有阴晴圆缺」以月喻人，把个人愁思升华为对宇宙人生的通达之悟，结句「但愿人长久，千里共婵娟」由悲转达，成为千古祝颂之词。中考常考：小序的作用、想象的层次（问月—欲归—起舞）、「不应有恨」两句的拟人与反问、哲理句的理解与默写。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"丙辰中秋，欢饮达旦，大醉，作此篇，兼怀子由。","n":"","cn":"丙辰年中秋节，我畅饮到天亮，喝得大醉，写下这首词，同时怀念弟弟子由。","parts":[{"t":"丙辰中秋，"},{"t":"欢饮达旦","k":0},{"t":"，大醉，作此篇，兼怀子由。"}]},{"t":"明月几时有？把酒问青天。","n":"","cn":"明月是什么时候开始有的？我端起酒杯询问青天。","parts":[{"t":"明月几时有？把酒"},{"t":"问","k":12},{"t":"青天。"}]},{"t":"不知天上宫阙，今夕是何年。","n":"","cn":"不知道天上的宫殿里，今晚是何年何月。","parts":[{"t":"不知天上宫阙，今夕是何年。"}]},{"t":"我欲乘风归去，又恐琼楼玉宇，高处不胜寒。","n":"","cn":"我想乘风回到天上去，又恐怕那美玉砌成的楼宇太高，经受不住寒冷。","parts":[{"t":"我欲乘风归去，又恐"},{"t":"琼楼玉宇","k":1},{"t":"，高处"},{"t":"不胜寒","k":2},{"t":"。"}]},{"t":"起舞弄清影，何似在人间。","n":"","cn":"起身舞蹈，戏弄着清朗的影子，哪里比得上人间呢。","parts":[{"t":"起舞弄清影，何似在人间。"}]},{"t":"转朱阁，低绮户，照无眠。","n":"","cn":"月光转过朱红的楼阁，低低地照进雕花的窗户，照着不能入睡的人。","parts":[{"t":"转朱阁，"},{"t":"低绮户","k":3},{"t":"，照无眠。"}]},{"t":"不应有恨，何事长向别时圆？","n":"","cn":"月亮对人不该有什么怨恨，为什么总在人们离别时才圆呢？","parts":[{"t":"不应有恨，何事"},{"t":"长","k":22},{"t":"向","k":13},{"t":"别时圆？"}]},{"t":"人有悲欢离合，月有阴晴圆缺，此事古难全。","n":"","cn":"人有悲欢离合，月有阴晴圆缺，这种事自古以来就难以两全。","parts":[{"t":"人有悲欢离合，月有阴晴圆缺，此事古难全。"}]},{"t":"但愿人长久，千里共婵娟。","n":"","cn":"只希望人能够长长久久，即使相隔千里也能共享这美好的月光。","parts":[{"t":"但","k":11},{"t":"愿人"},{"t":"长","k":22},{"t":"久，千里共"},{"t":"婵娟","k":7},{"t":"。"}]}],"words":[{"w":"欢饮达旦","e":"【易错】「欢饮达旦」的「旦」是「天亮」，不要写成「但」。"},{"w":"琼楼玉宇","e":"【易错】「琼楼玉宇」的「琼」是王字旁，不要写成「穷」「穹」。"},{"w":"不胜寒","e":"【易错】「不胜寒」的「胜」读 shēng，是「承受」，不要写成「盛」。"},{"w":"低绮户","e":"【易错】「低绮户」的「绮」是绞丝旁，不要写成「奇」「倚」。"},{"w":"天亮","e":"【易错】「欢饮达旦」的「旦」是「天亮」，不要写成「但」。"},{"w":"承受","e":"【易错】「不胜寒」的「胜」读 shēng，是「承受」，不要写成「盛」。"},{"w":"常常","e":"【易错】「长向别时圆」的「长」是「常常」，不要写成「常」。"},{"w":"婵娟","e":"【易错】「婵娟」两字都是女字旁，不要写成「蝉娟」「婵鹃」。"},{"w":"蝉娟","e":"【易错】「婵娟」两字都是女字旁，不要写成「蝉娟」「婵鹃」。"},{"w":"婵鹃","e":"【易错】「婵娟」两字都是女字旁，不要写成「蝉娟」「婵鹃」。"},{"w":"旦","e":"【易错】「欢饮达旦」的「旦」是「天亮」，不要写成「但」。"},{"w":"但","e":"【易错】「欢饮达旦」的「旦」是「天亮」，不要写成「但」。"},{"w":"问","e":"【易错】「把酒问青天」不要写成「把酒问青天」以外的语序（注意是「问」不是「向」）。"},{"w":"向","e":"【易错】「把酒问青天」不要写成「把酒问青天」以外的语序（注意是「问」不是「向」）。"},{"w":"琼","e":"【易错】「琼楼玉宇」的「琼」是王字旁，不要写成「穷」「穹」。"},{"w":"穷","e":"【易错】「琼楼玉宇」的「琼」是王字旁，不要写成「穷」「穹」。"},{"w":"穹","e":"【易错】「琼楼玉宇」的「琼」是王字旁，不要写成「穷」「穹」。"},{"w":"胜","e":"【易错】「不胜寒」的「胜」读 shēng，是「承受」，不要写成「盛」。"},{"w":"盛","e":"【易错】「不胜寒」的「胜」读 shēng，是「承受」，不要写成「盛」。"},{"w":"绮","e":"【易错】「低绮户」的「绮」是绞丝旁，不要写成「奇」「倚」。"},{"w":"奇","e":"【易错】「低绮户」的「绮」是绞丝旁，不要写成「奇」「倚」。"},{"w":"倚","e":"【易错】「低绮户」的「绮」是绞丝旁，不要写成「奇」「倚」。"},{"w":"长","e":"【易错】「长向别时圆」的「长」是「常常」，不要写成「常」。"},{"w":"常","e":"【易错】「长向别时圆」的「长」是「常常」，不要写成「常」。"}]},{"type":"list","title":"名句","items":["人有悲欢离合，月有阴晴圆缺，此事古难全。","但愿人长久，千里共婵娟。"]},{"type":"list","title":"背诵提示","items":["「欢饮达旦」的「旦」是「天亮」，不要写成「但」。","「把酒问青天」不要写成「把酒问青天」以外的语序（注意是「问」不是「向」）。","「琼楼玉宇」的「琼」是王字旁，不要写成「穷」「穹」。","「不胜寒」的「胜」读 shēng，是「承受」，不要写成「盛」。","「低绮户」的「绮」是绞丝旁，不要写成「奇」「倚」。","「长向别时圆」的「长」是「常常」，不要写成「常」。","「婵娟」两字都是女字旁，不要写成「蝉娟」「婵鹃」。"]}],"questions":[{"id":"p-p9a-shui-diao-ge-tou-ming-yue-ji-shi-you-m0","type":"fill","stem":"默写填空：人有悲欢离合，______。","answer":"月有阴晴圆缺。","explain":"出自《水调歌头（明月几时有）》（宋·苏轼）：人有悲欢离合，月有阴晴圆缺，此事古难全。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-shui-diao-ge-tou-ming-yue-ji-shi-you-m1","type":"fill","stem":"默写填空：但愿人长久，______。","answer":"千里共婵娟。","explain":"出自《水调歌头（明月几时有）》（宋·苏轼）：但愿人长久，千里共婵娟。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-shui-diao-ge-tou-ming-yue-ji-shi-you-u","type":"fill","stem":"理解性默写：丙辰年中秋节，我畅饮到天亮，喝得大醉，写下这首词，同时怀念弟弟子由。","answer":"丙辰中秋，欢饮达旦，大醉，作此篇，兼怀子由。","explain":"出自《水调歌头（明月几时有）》（宋·苏轼）。句意：丙辰年中秋节，我畅饮到天亮，喝得大醉，写下这首词，同时怀念弟弟子由。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-yue-ye-yi-she-di","title":"月夜忆舍弟","subtitle":"唐·杜甫","grade":"9a","tags":["思亲","战乱","怀乡"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·杜甫"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"杜甫（712—770），字子美，自号少陵野老，唐代伟大的现实主义诗人，被后人尊称为“诗圣”，他的诗广泛而深刻地反映了唐代由盛转衰时期的社会现实，被称为“诗史”。\n生平经历：青年时曾漫游吴越齐赵，并与李白相识；后困居长安十年，屡试不第；安史之乱中被叛军俘获，逃出后任左拾遗，又因直言进谏被贬；晚年流寓成都，在浣花溪畔建草堂，后又漂泊于夔州、湖湘一带，770年病逝于湘江舟中。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗写于安史之乱中，杜甫听闻弟弟们失散、生死未卜，因月生感。首联以「戍鼓」「雁声」点出边塞秋夜的荒凉与战乱气氛，为全诗定下悲凉基调；颔联「露从今夜白，月是故乡明」写景兼抒情，「月是故乡明」以主观感受写思乡之切，是千古名句；颈联直陈兄弟离散、家已无存之痛；尾联以「未休兵」作结，把个人悲苦与时代战乱联系，忧国与思亲融为一体。中考常考：颔联看似不合常理却更见深情的写法（以主观感受强化情感）、「雁声」的象征意义、由个人离散到国家战乱的以小见大手法。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"戍鼓断人行，边秋一雁声。","n":"","cn":"戍楼上的更鼓声断绝了人们的来往，边塞的秋天里传来一声孤雁的鸣叫。","parts":[{"t":"戍鼓","k":2},{"t":"断人行","k":0},{"t":"，边秋一"},{"t":"雁","k":8},{"t":"声。"}]},{"t":"露从今夜白，月是故乡明。","n":"","cn":"从今夜起就进入了白露节气，月亮还是故乡的最明亮。","parts":[{"t":"露"},{"t":"从","k":12},{"t":"今夜白，月是故乡明。"}]},{"t":"有弟皆分散，无家问死生。","n":"","cn":"虽有兄弟，却都离散在各地，没有家可以探问他们的生死。","parts":[{"t":"有弟皆分散，无家问死生。"}]},{"t":"寄书长不达，况乃未休兵。","n":"","cn":"寄出的书信常常不能送到，何况战乱还没有停息。","parts":[{"t":"寄书"},{"t":"长","k":14},{"t":"不达，"},{"t":"况","k":16},{"t":"乃","k":17},{"t":"未休兵。"}]}],"words":[{"w":"断人行","e":"【易错】「断人行」读 xíng，指《行人》，不要写成「断人衡」。"},{"w":"断人衡","e":"【易错】「断人行」读 xíng，指《行人》，不要写成「断人衡」。"},{"w":"戍鼓","e":"【易错】「戍鼓」的「戍」是「点、横、撇」加「戈」，不要写成「戌」「戍」以外的「戊」。"},{"w":"况且","e":"【易错】「况乃未休兵」的「况」是两点水，不要写成「况且」而漏写「乃」。"},{"w":"戍","e":"【易错】「戍鼓」的「戍」是「点、横、撇」加「戈」，不要写成「戌」「戍」以外的「戊」。"},{"w":"戈","e":"【易错】「戍鼓」的「戍」是「点、横、撇」加「戈」，不要写成「戌」「戍」以外的「戊」。"},{"w":"戌","e":"【易错】「戍鼓」的「戍」是「点、横、撇」加「戈」，不要写成「戌」「戍」以外的「戊」。"},{"w":"戊","e":"【易错】「戍鼓」的「戍」是「点、横、撇」加「戈」，不要写成「戌」「戍」以外的「戊」。"},{"w":"雁","e":"【易错】「边秋一雁声」的「雁」是「厂」内「倠」，不要写成「燕」。"},{"w":"厂","e":"【易错】「边秋一雁声」的「雁」是「厂」内「倠」，不要写成「燕」。"},{"w":"倠","e":"【易错】「边秋一雁声」的「雁」是「厂」内「倠」，不要写成「燕」。"},{"w":"燕","e":"【易错】「边秋一雁声」的「雁」是「厂」内「倠」，不要写成「燕」。"},{"w":"从","e":"【易错】「露从今夜白」不要倒写作「露从今夜白」以外的语序（注意「从」，不是「逢」）。"},{"w":"逢","e":"【易错】「露从今夜白」不要倒写作「露从今夜白」以外的语序（注意「从」，不是「逢」）。"},{"w":"长","e":"【易错】「寄书长不达」的「长」意为「一直、常常」，不要写成「常」。"},{"w":"常","e":"【易错】「寄书长不达」的「长」意为「一直、常常」，不要写成「常」。"},{"w":"况","e":"【易错】「况乃未休兵」的「况」是两点水，不要写成「况且」而漏写「乃」。"},{"w":"乃","e":"【易错】「况乃未休兵」的「况」是两点水，不要写成「况且」而漏写「乃」。"}]},{"type":"list","title":"名句","items":["露从今夜白，月是故乡明。"]},{"type":"list","title":"背诵提示","items":["「戍鼓」的「戍」是「点、横、撇」加「戈」，不要写成「戌」「戍」以外的「戊」。","「断人行」读 xíng，指《行人》，不要写成「断人衡」。","「边秋一雁声」的「雁」是「厂」内「倠」，不要写成「燕」。","「露从今夜白」不要倒写作「露从今夜白」以外的语序（注意「从」，不是「逢」）。","「寄书长不达」的「长」意为「一直、常常」，不要写成「常」。","「况乃未休兵」的「况」是两点水，不要写成「况且」而漏写「乃」。"]}],"questions":[{"id":"p-p9a-yue-ye-yi-she-di-m0","type":"fill","stem":"默写填空：露从今夜白，______。","answer":"月是故乡明。","explain":"出自《月夜忆舍弟》（唐·杜甫）：露从今夜白，月是故乡明。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-yue-ye-yi-she-di-u","type":"fill","stem":"理解性默写：戍楼上的更鼓声断绝了人们的来往，边塞的秋天里传来一声孤雁的鸣叫。","answer":"戍鼓断人行，边秋一雁声。","explain":"出自《月夜忆舍弟》（唐·杜甫）。句意：戍楼上的更鼓声断绝了人们的来往，边塞的秋天里传来一声孤雁的鸣叫。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-chang-sha-guo-jia-yi-zhai","title":"长沙过贾谊宅","subtitle":"唐·刘长卿","grade":"9a","tags":["怀古","贬谪","伤己"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·刘长卿"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"刘长卿（约726—约786），字文房，唐代诗人，官终随州刺史，世称“刘随州”。\n生平经历：他早年读书应举，天宝年间登进士第；安史之乱后辗转江南，先后任长洲县尉、南巴尉、睦州司马等职；因性情刚直，他一生两度遭贬，长期屈居下僚，晚年才做到随州刺史；仕途的失意与漂泊，使他的诗多写贬谪之悲、离别羁旅与山水隐逸之趣。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是刘长卿遭贬后经过长沙凭吊贾谊故宅所作，名为吊古，实为自伤。首联写贾谊谪居长沙三年的遭遇，一「悲」字统摄全篇；颔联以「秋草」「寒林」「日斜」等萧瑟意象渲染荒凉气氛，「独寻」「空见」写尽寂寞；颈联「汉文有道恩犹薄」明写汉文帝，暗讽当世君主，「湘水无情吊岂知」把悲愤推向深处，是名句；尾联「怜君何事到天涯」既怜贾谊，又自怜身世，古今相映。中考常考：借古讽今（怀古伤今）的手法、景中含情的写法、颈联的双关与反问语气、「怜君」的双重含义。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"三年谪宦此栖迟，万古惟留楚客悲。","n":"","cn":"你被贬官在此地滞留三年，万古以来只留下楚客的悲哀。","parts":[{"t":"三年"},{"t":"谪宦","k":0},{"t":"此"},{"t":"栖迟","k":1},{"t":"，万古"},{"t":"惟","k":9},{"t":"留楚客悲。"}]},{"t":"秋草独寻人去后，寒林空见日斜时。","n":"","cn":"秋草凄清，我独自在你去世之后来寻访；寒林中空自看到夕阳西斜。","parts":[{"t":"秋草独寻人去后，寒林空见日"},{"t":"斜","k":12},{"t":"时。"}]},{"t":"汉文有道恩犹薄，湘水无情吊岂知？","n":"","cn":"汉文帝算是明君，对你的恩情尚且如此刻薄；湘水无情，我凭吊你的心意它哪里知道？","parts":[{"t":"汉文有道恩犹薄，湘水无情"},{"t":"吊","k":14},{"t":"岂知？"}]},{"t":"寂寂江山摇落处，怜君何事到天涯！","n":"","cn":"在这寂寞冷落、草木摇落的时节，可怜你为什么要被贬到天涯呢！","parts":[{"t":"寂寂","k":2},{"t":"江山摇落处，怜君何事到天"},{"t":"涯","k":16},{"t":"！"}]}],"words":[{"w":"谪宦","e":"【易错】「谪宦」的「谪」是言字旁，不要写成「摘」「滴」。"},{"w":"栖迟","e":"【易错】「栖迟」的「栖」是木字旁，不要写成「凄」。"},{"w":"寂寂","e":"【易错】「寂寂江山摇落处」不要漏写「寂寂」，也不要写成「寞寞」。"},{"w":"寞寞","e":"【易错】「寂寂江山摇落处」不要漏写「寂寂」，也不要写成「寞寞」。"},{"w":"谪","e":"【易错】「谪宦」的「谪」是言字旁，不要写成「摘」「滴」。"},{"w":"摘","e":"【易错】「谪宦」的「谪」是言字旁，不要写成「摘」「滴」。"},{"w":"滴","e":"【易错】「谪宦」的「谪」是言字旁，不要写成「摘」「滴」。"},{"w":"栖","e":"【易错】「栖迟」的「栖」是木字旁，不要写成「凄」。"},{"w":"凄","e":"【易错】「栖迟」的「栖」是木字旁，不要写成「凄」。"},{"w":"惟","e":"【易错】「惟留楚客悲」的「惟」是「只」，不要写成「唯」。"},{"w":"只","e":"【易错】「惟留楚客悲」的「惟」是「只」，不要写成「唯」。"},{"w":"唯","e":"【易错】「惟留楚客悲」的「惟」是「只」，不要写成「唯」。"},{"w":"斜","e":"【易错】「寒林空见日斜时」的「斜」读 xiá 押韵，不要写成「邪」。"},{"w":"邪","e":"【易错】「寒林空见日斜时」的「斜」读 xiá 押韵，不要写成「邪」。"},{"w":"吊","e":"【易错】「湘水无情吊岂知」的「吊」是凭吊，不要写成「钓」。"},{"w":"钓","e":"【易错】「湘水无情吊岂知」的「吊」是凭吊，不要写成「钓」。"},{"w":"涯","e":"【易错】「怜君何事到天涯」的「涯」是三点水，不要写成「崖」。"},{"w":"崖","e":"【易错】「怜君何事到天涯」的「涯」是三点水，不要写成「崖」。"}]},{"type":"list","title":"名句","items":["汉文有道恩犹薄，湘水无情吊岂知？"]},{"type":"list","title":"背诵提示","items":["「谪宦」的「谪」是言字旁，不要写成「摘」「滴」。","「栖迟」的「栖」是木字旁，不要写成「凄」。","「惟留楚客悲」的「惟」是「只」，不要写成「唯」。","「寒林空见日斜时」的「斜」读 xiá 押韵，不要写成「邪」。","「湘水无情吊岂知」的「吊」是凭吊，不要写成「钓」。","「寂寂江山摇落处」不要漏写「寂寂」，也不要写成「寞寞」。","「怜君何事到天涯」的「涯」是三点水，不要写成「崖」。"]}],"questions":[{"id":"p-p9a-chang-sha-guo-jia-yi-zhai-m0","type":"fill","stem":"默写填空：汉文有道恩犹薄，______。","answer":"湘水无情吊岂知？。","explain":"出自《长沙过贾谊宅》（唐·刘长卿）：汉文有道恩犹薄，湘水无情吊岂知？","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-chang-sha-guo-jia-yi-zhai-u","type":"fill","stem":"理解性默写：你被贬官在此地滞留三年，万古以来只留下楚客的悲哀。","answer":"三年谪宦此栖迟，万古惟留楚客悲。","explain":"出自《长沙过贾谊宅》（唐·刘长卿）。句意：你被贬官在此地滞留三年，万古以来只留下楚客的悲哀。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-zuo-qian-zhi-lan-guan-shi-zhi-sun-xiang","title":"左迁至蓝关示侄孙湘","subtitle":"唐·韩愈","grade":"9a","tags":["贬谪","言志","悲壮"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·韩愈"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"韩愈（768—824），字退之，河南河阳（今河南孟州）人，因祖籍昌黎而世称韩昌黎，又因谥号为“文”而称韩文公，唐代文学家、思想家、教育家。\n生平经历：他幼年丧父，由兄嫂抚养成人，读书极为刻苦，二十五岁考中进士；任监察御史时因上疏言事被贬为阳山令，后来因上《论佛骨表》触怒宪宗，被贬为潮州刺史，仕途几度沉浮；他一生以复兴儒学为己任，反对六朝以来浮华空疏的骈文，提倡写内容充实、文从字顺的散文。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"韩愈因上《论佛骨表》谏迎佛骨而触怒宪宗，被贬潮州，此诗写于赴贬所途经蓝关之时。首联以「朝奏」「夕贬」对举，一「朝」一「夕」见获罪之速、贬所之远，看似平淡而愤慨自见；颔联直抒胸臆，「肯将衰朽惜残年」表现刚正不阿、为国除弊的骨气；颈联「云横秦岭家何在？雪拥蓝关马不前」以景写情，前路茫茫、进退失据之悲与英雄失路的慷慨交织，是千古名句；尾联嘱托侄孙收骨，语极沉痛。中考常考：颔联的抒情方式、颈联对偶与情景交融的妙处、「横」「拥」二字的表现力及全诗悲壮的感情基调。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"一封朝奏九重天，夕贬潮州路八千。","n":"","cn":"早晨我把一封奏章呈给皇帝，傍晚就被贬往八千里外的潮州。","parts":[{"t":"一封"},{"t":"朝奏","k":5},{"t":"九重天","k":2},{"t":"，"},{"t":"夕贬潮州","k":0},{"t":"路八千。"}]},{"t":"欲为圣明除弊事，肯将衰朽惜残年！","n":"","cn":"本来想替圣明的朝廷革除弊政，哪能因衰老就吝惜这残余的生命！","parts":[{"t":"欲为圣明"},{"t":"除弊事","k":3},{"t":"，肯将"},{"t":"衰朽","k":7},{"t":"惜残年！"}]},{"t":"云横秦岭家何在？雪拥蓝关马不前。","n":"","cn":"阴云横亘在秦岭之上，我的家在哪里？大雪拥塞蓝关，连马也不肯前行。","parts":[{"t":"云横秦岭","k":1},{"t":"家何在？雪拥蓝关马不前。"}]},{"t":"知汝远来应有意，好收吾骨瘴江边。","n":"","cn":"我知道你远道而来一定是有用意的，正好在瘴气弥漫的江边收拾我的尸骨吧。","parts":[{"t":"知汝远来应有意，好收吾骨"},{"t":"瘴江边","k":4},{"t":"。"}]}],"words":[{"w":"夕贬潮州","e":"【易错】「夕贬潮州」的「贬」是贝字旁，不要写成「眨」「泛」。"},{"w":"云横秦岭","e":"【易错】「云横秦岭」的「秦」下面是「禾」，不要写成「泰」。"},{"w":"九重天","e":"【易错】「九重天」的「重」读 chóng，不要写成「九从」。"},{"w":"除弊事","e":"【易错】「除弊事」的「弊」下面不是「币」，不要写成「敝」「毙」。"},{"w":"瘴江边","e":"【易错】「瘴江边」的「瘴」是病字旁，不要写成「障」。"},{"w":"朝奏","e":"【易错】「朝奏」的「朝」读 zhāo，指早晨，不要读成 cháo。"},{"w":"九从","e":"【易错】「九重天」的「重」读 chóng，不要写成「九从」。"},{"w":"衰朽","e":"【易错】「衰朽」的「朽」是木字旁，不要写成「巧」。"},{"w":"朝","e":"【易错】「朝奏」的「朝」读 zhāo，指早晨，不要读成 cháo。"},{"w":"重","e":"【易错】「九重天」的「重」读 chóng，不要写成「九从」。"},{"w":"贬","e":"【易错】「夕贬潮州」的「贬」是贝字旁，不要写成「眨」「泛」。"},{"w":"眨","e":"【易错】「夕贬潮州」的「贬」是贝字旁，不要写成「眨」「泛」。"},{"w":"泛","e":"【易错】「夕贬潮州」的「贬」是贝字旁，不要写成「眨」「泛」。"},{"w":"弊","e":"【易错】「除弊事」的「弊」下面不是「币」，不要写成「敝」「毙」。"},{"w":"币","e":"【易错】「除弊事」的「弊」下面不是「币」，不要写成「敝」「毙」。"},{"w":"敝","e":"【易错】「除弊事」的「弊」下面不是「币」，不要写成「敝」「毙」。"},{"w":"毙","e":"【易错】「除弊事」的「弊」下面不是「币」，不要写成「敝」「毙」。"},{"w":"朽","e":"【易错】「衰朽」的「朽」是木字旁，不要写成「巧」。"},{"w":"巧","e":"【易错】「衰朽」的「朽」是木字旁，不要写成「巧」。"},{"w":"秦","e":"【易错】「云横秦岭」的「秦」下面是「禾」，不要写成「泰」。"},{"w":"禾","e":"【易错】「云横秦岭」的「秦」下面是「禾」，不要写成「泰」。"},{"w":"泰","e":"【易错】「云横秦岭」的「秦」下面是「禾」，不要写成「泰」。"},{"w":"瘴","e":"【易错】「瘴江边」的「瘴」是病字旁，不要写成「障」。"},{"w":"障","e":"【易错】「瘴江边」的「瘴」是病字旁，不要写成「障」。"}]},{"type":"list","title":"名句","items":["云横秦岭家何在？雪拥蓝关马不前。"]},{"type":"list","title":"背诵提示","items":["「朝奏」的「朝」读 zhāo，指早晨，不要读成 cháo。","「九重天」的「重」读 chóng，不要写成「九从」。","「夕贬潮州」的「贬」是贝字旁，不要写成「眨」「泛」。","「除弊事」的「弊」下面不是「币」，不要写成「敝」「毙」。","「衰朽」的「朽」是木字旁，不要写成「巧」。","「云横秦岭」的「秦」下面是「禾」，不要写成「泰」。","「瘴江边」的「瘴」是病字旁，不要写成「障」。"]}],"questions":[{"id":"p-p9a-zuo-qian-zhi-lan-guan-shi-zhi-sun-xiang-u","type":"fill","stem":"理解性默写：早晨我把一封奏章呈给皇帝，傍晚就被贬往八千里外的潮州。","answer":"一封朝奏九重天，夕贬潮州路八千。","explain":"出自《左迁至蓝关示侄孙湘》（唐·韩愈）。句意：早晨我把一封奏章呈给皇帝，傍晚就被贬往八千里外的潮州。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-shang-shan-zao-xing","title":"商山早行","subtitle":"唐·温庭筠","grade":"9a","tags":["羁旅","思乡","写景"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·温庭筠"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"温庭筠（约812—约866），本名岐，字飞卿，太原祁（今山西祁县）人，唐代诗人、词人。他才思敏捷，据说八叉手而成八韵，因此被人称为“温八叉”，后世又尊他为“花间派”的鼻祖。\n生平经历：他出身没落贵族，才高却屡试不第，一生仕宦不顺，只做过随县尉、方城尉、国子助教一类低微官职；他精通音律，常在酒宴歌席之间填词，诗与李商隐齐名，时称“温李”；晚年落魄，约卒于唐懿宗咸通年间。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗写羁旅早行的所见所感。首联点明「早行」，以「悲故乡」奠定全诗感情基调；颔联「鸡声茅店月，人迹板桥霜」是千古名句，纯用名词组合（意象叠加），未用一个动词、一个虚词，却画出了一幅凄清早行的图画，声、色、情俱备，被誉为「状难写之景，如在目前」；颈联续写山路景色，「槲叶落」「枳花明」一暗一明，暗示时令与行程；尾联以梦中故乡的温暖景象对照现实旅途的寒冷艰辛，虚实相生，思乡之情更见深切。中考常考：颔联的名词叠加手法与画面描述、虚实结合与对比的作用、「明」字的炼字效果。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"晨起动征铎，客行悲故乡。","n":"","cn":"清晨起来，车马的铃铎已经响动，远行在外的旅人心中悲叹思念故乡。","parts":[{"t":"晨起动"},{"t":"征铎","k":1},{"t":"，客行悲故乡。"}]},{"t":"鸡声茅店月，人迹板桥霜。","n":"","cn":"鸡叫声中，茅草店沐浴着晓月的余晖；行人的足迹留在板桥的寒霜上。","parts":[{"t":"鸡声"},{"t":"茅店","k":2},{"t":"月，人"},{"t":"迹","k":11},{"t":"板桥霜。"}]},{"t":"槲叶落山路，枳花明驿墙。","n":"","cn":"槲树的叶子落满了山路，枳树的白花照亮了驿站的围墙。","parts":[{"t":"槲叶","k":3},{"t":"落山路，"},{"t":"枳花","k":4},{"t":"明"},{"t":"驿","k":7},{"t":"墙。"}]},{"t":"因思杜陵梦，凫雁满回塘。","n":"","cn":"因而想起昨夜梦见杜陵的情景：春天来了，野鸭大雁挤满了曲折的池塘。","parts":[{"t":"因思杜陵梦，"},{"t":"凫雁","k":5},{"t":"满回塘","k":0},{"t":"。"}]}],"words":[{"w":"满回塘","e":"【易错】「满回塘」的「塘」是土字旁，不要写成「唐」。"},{"w":"征铎","e":"【易错】「征铎」的「铎」是金字旁，指大铃，不要写成「驿」「泽」。"},{"w":"茅店","e":"【易错】「茅店」的「茅」是草字头，不要写成「矛」。"},{"w":"槲叶","e":"【易错】「槲叶」的「槲」是木字旁，读 hú，不要写成「斛」。"},{"w":"枳花","e":"【易错】「枳花」的「枳」是木字旁，不要写成「织」「职」。"},{"w":"凫雁","e":"【易错】「凫雁」的「凫」下面是「几」，指野鸭，不要写成「鸟」。"},{"w":"铎","e":"【易错】「征铎」的「铎」是金字旁，指大铃，不要写成「驿」「泽」。"},{"w":"驿","e":"【易错】「征铎」的「铎」是金字旁，指大铃，不要写成「驿」「泽」。"},{"w":"泽","e":"【易错】「征铎」的「铎」是金字旁，指大铃，不要写成「驿」「泽」。"},{"w":"茅","e":"【易错】「茅店」的「茅」是草字头，不要写成「矛」。"},{"w":"矛","e":"【易错】「茅店」的「茅」是草字头，不要写成「矛」。"},{"w":"迹","e":"【易错】「人迹板桥霜」的「迹」是走之底，不要写成「绩」。"},{"w":"绩","e":"【易错】「人迹板桥霜」的「迹」是走之底，不要写成「绩」。"},{"w":"槲","e":"【易错】「槲叶」的「槲」是木字旁，读 hú，不要写成「斛」。"},{"w":"斛","e":"【易错】「槲叶」的「槲」是木字旁，读 hú，不要写成「斛」。"},{"w":"枳","e":"【易错】「枳花」的「枳」是木字旁，不要写成「织」「职」。"},{"w":"织","e":"【易错】「枳花」的「枳」是木字旁，不要写成「织」「职」。"},{"w":"职","e":"【易错】「枳花」的「枳」是木字旁，不要写成「织」「职」。"},{"w":"凫","e":"【易错】「凫雁」的「凫」下面是「几」，指野鸭，不要写成「鸟」。"},{"w":"几","e":"【易错】「凫雁」的「凫」下面是「几」，指野鸭，不要写成「鸟」。"},{"w":"鸟","e":"【易错】「凫雁」的「凫」下面是「几」，指野鸭，不要写成「鸟」。"},{"w":"塘","e":"【易错】「满回塘」的「塘」是土字旁，不要写成「唐」。"},{"w":"唐","e":"【易错】「满回塘」的「塘」是土字旁，不要写成「唐」。"}]},{"type":"list","title":"名句","items":["鸡声茅店月，人迹板桥霜。"]},{"type":"list","title":"背诵提示","items":["「征铎」的「铎」是金字旁，指大铃，不要写成「驿」「泽」。","「茅店」的「茅」是草字头，不要写成「矛」。","「人迹板桥霜」的「迹」是走之底，不要写成「绩」。","「槲叶」的「槲」是木字旁，读 hú，不要写成「斛」。","「枳花」的「枳」是木字旁，不要写成「织」「职」。","「凫雁」的「凫」下面是「几」，指野鸭，不要写成「鸟」。","「满回塘」的「塘」是土字旁，不要写成「唐」。"]}],"questions":[{"id":"p-p9a-shang-shan-zao-xing-m0","type":"fill","stem":"默写填空：鸡声茅店月，______。","answer":"人迹板桥霜。","explain":"出自《商山早行》（唐·温庭筠）：鸡声茅店月，人迹板桥霜。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-shang-shan-zao-xing-u","type":"fill","stem":"理解性默写：清晨起来，车马的铃铎已经响动，远行在外的旅人心中悲叹思念故乡。","answer":"晨起动征铎，客行悲故乡。","explain":"出自《商山早行》（唐·温庭筠）。句意：清晨起来，车马的铃铎已经响动，远行在外的旅人心中悲叹思念故乡。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-wu-ti-xiang-jian-shi-nan-bie-yi-nan","title":"无题","subtitle":"唐·李商隐","grade":"9a","tags":["爱情","抒情","双关"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·李商隐"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"李商隐（约813—约858），字义山，号玉谿生，又号樊南生，怀州河内（今河南沁阳）人，晚唐诗人，与杜牧并称“小李杜”。\n生平经历：他少年时得到天平军节度使令狐楚的赏识，二十五岁考中进士；后来入泾原节度使王茂元幕府并成为其女婿，因而卷入牛李党争，被两方猜忌，一生只做过校书郎、县尉一类小官，长期辗转于各地幕府；妻子去世后他更加郁郁寡欢，四十余岁便在郑州病逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首以「无题」抒写爱情的千古名篇，情致缠绵而意境幽深。首句连用两个「难」字，一写相见之难，一写离别之难，层层递进；「东风无力百花残」以暮春衰景映衬离情。颔联「春蚕到死丝方尽，蜡炬成灰泪始干」以谐音双关（「丝」谐「思」）与比喻写对爱情的忠贞不渝，成为千古绝唱，今也常用来赞颂奉献精神。颈联设想对方晓妆夜吟的情态，由己及人，体贴入微；尾联借蓬山、青鸟的神话传说寄托希望。中考常考：颔联的双关与象征义、由己及人的想象手法、炼字（两个「难」、「改」「寒」），以及本诗情景交融、缠绵执着的感情基调。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"相见时难别亦难，东风无力百花残。","n":"","cn":"相见本就很难，离别更是难舍难分；何况东风无力，百花凋残。","parts":[{"t":"相见时"},{"t":"难","k":10},{"t":"别亦"},{"t":"难","k":10},{"t":"，东风无力"},{"t":"百花残","k":2},{"t":"。"}]},{"t":"春蚕到死丝方尽，蜡炬成灰泪始干。","n":"","cn":"春蚕直到死去，吐出的丝才终止（思念才停止）；蜡烛燃成灰烬，烛泪才干。","parts":[{"t":"春蚕到死"},{"t":"丝方尽","k":3},{"t":"，"},{"t":"蜡炬成灰","k":0},{"t":"泪始干。"}]},{"t":"晓镜但愁云鬓改，夜吟应觉月光寒。","n":"","cn":"清晨对镜梳妆，只愁如云的鬓发改变了颜色；夜里吟诗，该会觉得月光凄寒。","parts":[{"t":"晓镜但愁云"},{"t":"鬓","k":16},{"t":"改，"},{"t":"夜吟应觉","k":1},{"t":"月光寒。"}]},{"t":"蓬山此去无多路，青鸟殷勤为探看。","n":"","cn":"蓬山离这里没有多远的路程，青鸟啊，请殷勤地为我前去探看（传信）吧。","parts":[{"t":"蓬山此去无多路，青鸟"},{"t":"殷勤","k":7},{"t":"为","k":22},{"t":"探看","k":9},{"t":"。"}]}],"words":[{"w":"蜡炬成灰","e":"【易错】「蜡炬成灰」的「炬」是火字旁，不要写成「蜡烛」「腊炬」。"},{"w":"夜吟应觉","e":"【易错】「夜吟应觉」的「应」读 yīng，不要写成「因」。"},{"w":"百花残","e":"【易错】「百花残」的「残」是歹字旁，不要写成「浅」「贱」。"},{"w":"丝方尽","e":"【易错】「丝方尽」的「丝」不要写成「思方尽」（此处是谐音双关，原文用「丝」）。"},{"w":"思方尽","e":"【易错】「丝方尽」的「丝」不要写成「思方尽」（此处是谐音双关，原文用「丝」）。"},{"w":"蜡烛","e":"【易错】「蜡炬成灰」的「炬」是火字旁，不要写成「蜡烛」「腊炬」。"},{"w":"腊炬","e":"【易错】「蜡炬成灰」的「炬」是火字旁，不要写成「蜡烛」「腊炬」。"},{"w":"殷勤","e":"【易错】「殷勤」的「殷」右上是「殳」的变体，不要写成「殷情」。"},{"w":"殷情","e":"【易错】「殷勤」的「殷」右上是「殳」的变体，不要写成「殷情」。"},{"w":"探看","e":"【易错】「青鸟殷勤为探看」的「为」读 wèi，「探看」读 tàn kān。"},{"w":"难","e":"【易错】「相见时难别亦难」两个「难」字不要漏写其中一个。"},{"w":"残","e":"【易错】「百花残」的「残」是歹字旁，不要写成「浅」「贱」。"},{"w":"浅","e":"【易错】「百花残」的「残」是歹字旁，不要写成「浅」「贱」。"},{"w":"贱","e":"【易错】「百花残」的「残」是歹字旁，不要写成「浅」「贱」。"},{"w":"丝","e":"【易错】「丝方尽」的「丝」不要写成「思方尽」（此处是谐音双关，原文用「丝」）。"},{"w":"炬","e":"【易错】「蜡炬成灰」的「炬」是火字旁，不要写成「蜡烛」「腊炬」。"},{"w":"鬓","e":"【易错】「晓镜但愁云鬓改」的「鬓」是「髟」字头，不要漏写上部。"},{"w":"髟","e":"【易错】「晓镜但愁云鬓改」的「鬓」是「髟」字头，不要漏写上部。"},{"w":"应","e":"【易错】「夜吟应觉」的「应」读 yīng，不要写成「因」。"},{"w":"因","e":"【易错】「夜吟应觉」的「应」读 yīng，不要写成「因」。"},{"w":"殷","e":"【易错】「殷勤」的「殷」右上是「殳」的变体，不要写成「殷情」。"},{"w":"殳","e":"【易错】「殷勤」的「殷」右上是「殳」的变体，不要写成「殷情」。"},{"w":"为","e":"【易错】「青鸟殷勤为探看」的「为」读 wèi，「探看」读 tàn kān。"}]},{"type":"list","title":"名句","items":["春蚕到死丝方尽，蜡炬成灰泪始干。"]},{"type":"list","title":"背诵提示","items":["「相见时难别亦难」两个「难」字不要漏写其中一个。","「百花残」的「残」是歹字旁，不要写成「浅」「贱」。","「丝方尽」的「丝」不要写成「思方尽」（此处是谐音双关，原文用「丝」）。","「蜡炬成灰」的「炬」是火字旁，不要写成「蜡烛」「腊炬」。","「晓镜但愁云鬓改」的「鬓」是「髟」字头，不要漏写上部。","「夜吟应觉」的「应」读 yīng，不要写成「因」。","「殷勤」的「殷」右上是「殳」的变体，不要写成「殷情」。","「青鸟殷勤为探看」的「为」读 wèi，「探看」读 tàn kān。"]}],"questions":[{"id":"p-p9a-wu-ti-xiang-jian-shi-nan-bie-yi-nan-m0","type":"fill","stem":"默写填空：春蚕到死丝方尽，______。","answer":"蜡炬成灰泪始干。","explain":"出自《无题》（唐·李商隐）：春蚕到死丝方尽，蜡炬成灰泪始干。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-wu-ti-xiang-jian-shi-nan-bie-yi-nan-u","type":"fill","stem":"理解性默写：相见本就很难，离别更是难舍难分；何况东风无力，百花凋残。","answer":"相见时难别亦难，东风无力百花残。","explain":"出自《无题》（唐·李商隐）。句意：相见本就很难，离别更是难舍难分；何况东风无力，百花凋残。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-xian-yang-cheng-dong-lou","title":"咸阳城东楼","subtitle":"唐·许浑","grade":"9a","tags":["怀古","写景","愁思"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·许浑"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"许浑（约791—约858），字用晦（一作仲晦），润州丹阳（今江苏丹阳）人，晚唐诗人，曾任睦州、郢州刺史，世称“许郢州”。\n生平经历：他少年时体弱多病而读书刻苦；唐文宗大和六年登进士第，此后长期在幕府与州县任职，先后任当涂县令、太平县令、监察御史、润州司马等职；晚年出任睦州、郢州刺史，后因病退居润州丁卯桥村舍，自编诗集名为《丁卯集》；他一生仕途平淡，作品多为登临怀古、赠别酬答之作。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是一首登临怀古之作。首联写登楼远望，一「愁」字总领全篇，「蒹葭杨柳似汀洲」借江南风物勾起乡思；颔联「溪云初起日沉阁，山雨欲来风满楼」写景极为传神，把暴风雨将至的紧张气氛写得如在眼前，后成为人们熟知的成语，常用来比喻重大事件发生前的气氛；颈联以「鸟下绿芜」「蝉鸣黄叶」写秦汉故苑的荒凉，今昔对照，感慨深沉；尾联「渭水流」三字以景结情，把兴亡之感化为无尽流水，余韵悠长。中考常考：颔联的景物描写与比喻义、今昔对比（借古讽今）的手法、以景结情的妙处与「万里愁」的内涵。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"一上高城万里愁，蒹葭杨柳似汀洲。","n":"","cn":"一登上高高的咸阳城楼，心中便涌起万里之远的愁思；眼前的芦苇杨柳，如同江中的小洲。","parts":[{"t":"一上高城万里愁，"},{"t":"蒹葭","k":2},{"t":"杨柳似"},{"t":"汀洲","k":5},{"t":"。"}]},{"t":"溪云初起日沉阁，山雨欲来风满楼。","n":"","cn":"溪边的乌云刚刚升起，夕阳就沉落在寺阁之后；山间大雨将要来临，狂风已灌满城楼。","parts":[{"t":"溪云初起"},{"t":"日沉阁","k":0},{"t":"，山雨欲来风满楼。"}]},{"t":"鸟下绿芜秦苑夕，蝉鸣黄叶汉宫秋。","n":"","cn":"鸟儿飞落在傍晚的秦朝苑囿绿草之中，秋蝉在汉宫黄叶间哀鸣。","parts":[{"t":"鸟下"},{"t":"绿芜","k":7},{"t":"秦苑夕","k":1},{"t":"，蝉鸣黄叶汉宫秋。"}]},{"t":"行人莫问当年事，故国东来渭水流。","n":"","cn":"来往的行人不要问当年的事，故都依旧，只有渭水日夜东流。","parts":[{"t":"行人莫问当年事，故国东来"},{"t":"渭","k":17},{"t":"水流。"}]}],"words":[{"w":"日沉阁","e":"【易错】「日沉阁」的「沉」是三点水，不要写成「沈」。"},{"w":"秦苑夕","e":"【易错】「秦苑夕」的「苑」是草字头，不要写成「范」。"},{"w":"蒹葭","e":"【易错】「蒹葭」都是草字头，不要写成「兼葭」「蒹佳」。"},{"w":"兼葭","e":"【易错】「蒹葭」都是草字头，不要写成「兼葭」「蒹佳」。"},{"w":"蒹佳","e":"【易错】「蒹葭」都是草字头，不要写成「兼葭」「蒹佳」。"},{"w":"汀洲","e":"【易错】「汀洲」的「汀」是三点水，「洲」是三点水，不要写成「汀州」。"},{"w":"汀州","e":"【易错】「汀洲」的「汀」是三点水，「洲」是三点水，不要写成「汀州」。"},{"w":"绿芜","e":"【易错】「绿芜」的「芜」是草字头，不要写成「无」「抚」。"},{"w":"汀","e":"【易错】「汀洲」的「汀」是三点水，「洲」是三点水，不要写成「汀州」。"},{"w":"洲","e":"【易错】「汀洲」的「汀」是三点水，「洲」是三点水，不要写成「汀州」。"},{"w":"沉","e":"【易错】「日沉阁」的「沉」是三点水，不要写成「沈」。"},{"w":"沈","e":"【易错】「日沉阁」的「沉」是三点水，不要写成「沈」。"},{"w":"芜","e":"【易错】「绿芜」的「芜」是草字头，不要写成「无」「抚」。"},{"w":"无","e":"【易错】「绿芜」的「芜」是草字头，不要写成「无」「抚」。"},{"w":"抚","e":"【易错】「绿芜」的「芜」是草字头，不要写成「无」「抚」。"},{"w":"苑","e":"【易错】「秦苑夕」的「苑」是草字头，不要写成「范」。"},{"w":"范","e":"【易错】「秦苑夕」的「苑」是草字头，不要写成「范」。"},{"w":"渭","e":"【易错】「故国东来渭水流」的「渭」是三点水，不要写成「谓」「渭」以外的「胃」。"},{"w":"谓","e":"【易错】「故国东来渭水流」的「渭」是三点水，不要写成「谓」「渭」以外的「胃」。"},{"w":"胃","e":"【易错】「故国东来渭水流」的「渭」是三点水，不要写成「谓」「渭」以外的「胃」。"}]},{"type":"list","title":"名句","items":["溪云初起日沉阁，山雨欲来风满楼。"]},{"type":"list","title":"背诵提示","items":["「蒹葭」都是草字头，不要写成「兼葭」「蒹佳」。","「汀洲」的「汀」是三点水，「洲」是三点水，不要写成「汀州」。","「日沉阁」的「沉」是三点水，不要写成「沈」。","「山雨欲来风满楼」不要写成「山雨欲来风满搂」。","「绿芜」的「芜」是草字头，不要写成「无」「抚」。","「秦苑夕」的「苑」是草字头，不要写成「范」。","「故国东来渭水流」的「渭」是三点水，不要写成「谓」「渭」以外的「胃」。"]}],"questions":[{"id":"p-p9a-xian-yang-cheng-dong-lou-m0","type":"fill","stem":"默写填空：溪云初起日沉阁，______。","answer":"山雨欲来风满楼。","explain":"出自《咸阳城东楼》（唐·许浑）：溪云初起日沉阁，山雨欲来风满楼。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-xian-yang-cheng-dong-lou-u","type":"fill","stem":"理解性默写：一登上高高的咸阳城楼，心中便涌起万里之远的愁思；眼前的芦苇杨柳，如同江中的小洲。","answer":"一上高城万里愁，蒹葭杨柳似汀洲。","explain":"出自《咸阳城东楼》（唐·许浑）。句意：一登上高高的咸阳城楼，心中便涌起万里之远的愁思；眼前的芦苇杨柳，如同江中的小洲。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-xing-xiang-zi-shu-rao-cun-zhuang","title":"行香子（树绕村庄）","subtitle":"宋·秦观","grade":"9a","tags":["田园","写景","春景"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·秦观"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"秦观（1049—1100），字少游，又字太虚，号淮海居士，北宋词人，扬州高邮（今江苏高邮）人。\n生平经历：元丰八年中进士，曾任太学博士、秘书省正字等职；因新旧党争屡遭贬谪，先后被贬往处州、郴州、横州、雷州等地；元符三年遇赦北归，途中病逝于藤州。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词以白描手法描绘一幅明丽动人的田园春景图。上片写静景：树绕村庄、水满陂塘，接着用「有桃花红，李花白，菜花黄」三个短句排比，色彩鲜明，节奏轻快，把满园春光写得热闹而有序；下片由远及近又有流动感：围墙、茅堂、青旗、流水桥，再以「正莺儿啼，燕儿舞，蝶儿忙」三句排比收束，一静一动，声色俱佳。全词语言浅近自然，格调明朗欢快，表现了词人游春的愉悦与对田园生活的喜爱。中考常考：排比句的艺术效果、色彩词的运用、动静结合的写景层次，以及「徜徉」「飏」等词语的读音与含义。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"树绕村庄，水满陂塘。倚东风，豪兴徜徉。","n":"","cn":"绿树环绕着村庄，春水涨满了池塘。我沐浴着东风，兴致豪迈地信步闲游。","parts":[{"t":"树绕村庄，"},{"t":"水满陂塘","k":0},{"t":"。倚东风，豪兴"},{"t":"徜徉","k":6},{"t":"。"}]},{"t":"小园几许，收尽春光。有桃花红，李花白，菜花黄。","n":"","cn":"小园虽只有那么一点大，却收尽了满园春光：有桃花红，李花白，菜花黄。","parts":[{"t":"小园几许","k":1},{"t":"，收尽春光。有桃花红，李花白，菜花黄。"}]},{"t":"远远围墙，隐隐茅堂。飏青旗，流水桥旁。","n":"","cn":"远远一带围墙，隐隐约约几间茅草屋。青色的酒旗在流水桥旁随风飘扬。","parts":[{"t":"远远围墙，"},{"t":"隐隐茅堂","k":2},{"t":"。"},{"t":"飏青旗","k":4},{"t":"，流水桥旁。"}]},{"t":"偶然乘兴，步过东冈。正莺儿啼，燕儿舞，蝶儿忙。","n":"","cn":"偶然乘着兴致，走过东边的高冈。只见黄莺啼鸣，燕子飞舞，蝴蝶奔忙。","parts":[{"t":"偶然乘兴，"},{"t":"步过东冈","k":3},{"t":"。正"},{"t":"莺儿啼","k":5},{"t":"，燕儿舞，蝶儿忙。"}]}],"words":[{"w":"水满陂塘","e":"【易错】「水满陂塘」的「陂」读 bēi，是池塘，不要写成「坡」「波」。"},{"w":"小园几许","e":"【易错】「小园几许」的「几」读 jǐ，不要写成「己」「已」。"},{"w":"隐隐茅堂","e":"【易错】「隐隐茅堂」的「茅」是草字头，不要写成「矛」。"},{"w":"步过东冈","e":"【易错】「步过东冈」的「冈」是「冂」内「乂」，不要写成「岗」「网」。"},{"w":"飏青旗","e":"【易错】「飏青旗」的「飏」读 yáng，是飞扬，不要写成「扬」（课文作「飏」）。"},{"w":"莺儿啼","e":"【易错】「莺儿啼」的「莺」是草字头，不要写成「鹰」。"},{"w":"徜徉","e":"【易错】「徜徉」两字都是双人旁，不要写成「倘佯」。"},{"w":"倘佯","e":"【易错】「徜徉」两字都是双人旁，不要写成「倘佯」。"},{"w":"陂","e":"【易错】「水满陂塘」的「陂」读 bēi，是池塘，不要写成「坡」「波」。"},{"w":"坡","e":"【易错】「水满陂塘」的「陂」读 bēi，是池塘，不要写成「坡」「波」。"},{"w":"波","e":"【易错】「水满陂塘」的「陂」读 bēi，是池塘，不要写成「坡」「波」。"},{"w":"几","e":"【易错】「小园几许」的「几」读 jǐ，不要写成「己」「已」。"},{"w":"己","e":"【易错】「小园几许」的「几」读 jǐ，不要写成「己」「已」。"},{"w":"已","e":"【易错】「小园几许」的「几」读 jǐ，不要写成「己」「已」。"},{"w":"茅","e":"【易错】「隐隐茅堂」的「茅」是草字头，不要写成「矛」。"},{"w":"矛","e":"【易错】「隐隐茅堂」的「茅」是草字头，不要写成「矛」。"},{"w":"飏","e":"【易错】「飏青旗」的「飏」读 yáng，是飞扬，不要写成「扬」（课文作「飏」）。"},{"w":"扬","e":"【易错】「飏青旗」的「飏」读 yáng，是飞扬，不要写成「扬」（课文作「飏」）。"},{"w":"冈","e":"【易错】「步过东冈」的「冈」是「冂」内「乂」，不要写成「岗」「网」。"},{"w":"冂","e":"【易错】「步过东冈」的「冈」是「冂」内「乂」，不要写成「岗」「网」。"},{"w":"乂","e":"【易错】「步过东冈」的「冈」是「冂」内「乂」，不要写成「岗」「网」。"},{"w":"岗","e":"【易错】「步过东冈」的「冈」是「冂」内「乂」，不要写成「岗」「网」。"},{"w":"网","e":"【易错】「步过东冈」的「冈」是「冂」内「乂」，不要写成「岗」「网」。"},{"w":"莺","e":"【易错】「莺儿啼」的「莺」是草字头，不要写成「鹰」。"},{"w":"鹰","e":"【易错】「莺儿啼」的「莺」是草字头，不要写成「鹰」。"}]},{"type":"list","title":"名句","items":["有桃花红，李花白，菜花黄。","正莺儿啼，燕儿舞，蝶儿忙。"]},{"type":"list","title":"背诵提示","items":["「水满陂塘」的「陂」读 bēi，是池塘，不要写成「坡」「波」。","「徜徉」两字都是双人旁，不要写成「倘佯」。","「小园几许」的「几」读 jǐ，不要写成「己」「已」。","「隐隐茅堂」的「茅」是草字头，不要写成「矛」。","「飏青旗」的「飏」读 yáng，是飞扬，不要写成「扬」（课文作「飏」）。","「步过东冈」的「冈」是「冂」内「乂」，不要写成「岗」「网」。","「莺儿啼」的「莺」是草字头，不要写成「鹰」。"]}],"questions":[{"id":"p-p9a-xing-xiang-zi-shu-rao-cun-zhuang-m0","type":"fill","stem":"默写填空：有桃花红，______。","answer":"李花白。","explain":"出自《行香子（树绕村庄）》（宋·秦观）：有桃花红，李花白，菜花黄。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-xing-xiang-zi-shu-rao-cun-zhuang-m1","type":"fill","stem":"默写填空：正莺儿啼，______。","answer":"燕儿舞。","explain":"出自《行香子（树绕村庄）》（宋·秦观）：正莺儿啼，燕儿舞，蝶儿忙。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-xing-xiang-zi-shu-rao-cun-zhuang-u","type":"fill","stem":"理解性默写：绿树环绕着村庄，春水涨满了池塘。我沐浴着东风，兴致豪迈地信步闲游。","answer":"树绕村庄，水满陂塘。倚东风，豪兴徜徉。","explain":"出自《行香子（树绕村庄）》（宋·秦观）。句意：绿树环绕着村庄，春水涨满了池塘。我沐浴着东风，兴致豪迈地信步闲游。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9a-chou-nu-er-shu-bo-shan-dao-zhong-bi","title":"丑奴儿·书博山道中壁","subtitle":"宋·辛弃疾","grade":"9a","tags":["言志","对比","忧国"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·辛弃疾"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"辛弃疾（1140—1207），字幼安，号稼轩，历城（今山东济南）人，南宋豪放派词人，与苏轼并称“苏辛”，与李清照并称“济南二安”。\n生平经历：他出生时中原已被金人占领，二十一岁便组织义军抗金，曾率五十骑闯入敌营擒拿叛将，一时声名大振；南归后长期不受重用，只做过地方官职，多次上书陈述抗金方略都未被采纳；他先后闲居江西上饶、铅山近二十年，把报国无门的悲愤都写进词里，晚年虽再被起用，不久便抱憾辞世。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词以「愁」为线索，通过少年与而今的对比，抒写饱经忧患后难以言说的深沉愁苦。上片写少年「不识愁滋味」却「强说愁」，是无愁找愁的幼稚；「爱上层楼」的反复，写出少年故作姿态的情态。下片写而今「识尽愁滋味」反而「欲说还休」，一「尽」一「休」，饱含无限辛酸；结尾「却道天凉好个秋」以看似平淡的闲话收束，把满腹家国之愁、报国无门之痛压在言外，是「以淡语写深情」的典范。中考常考：上下片的对比手法、「爱上层楼」「欲说还休」的反复作用、结句的言外之意与「愁」的深层内涵（不只是个人愁绪，更有忧国伤时之痛）。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"少年不识愁滋味，爱上层楼。","n":"","cn":"年少时不懂得愁的滋味，喜欢登上高楼。","parts":[{"t":"少年不识愁滋味，"},{"t":"爱上层楼","k":0},{"t":"。"}]},{"t":"爱上层楼，为赋新词强说愁。","n":"","cn":"喜欢登上高楼，为了写出新词，勉强地诉说愁苦。","parts":[{"t":"爱上层楼","k":0},{"t":"，为赋新词"},{"t":"强说愁","k":2},{"t":"。"}]},{"t":"而今识尽愁滋味，欲说还休。","n":"","cn":"如今尝尽了愁的滋味，想诉说却又停住了。","parts":[{"t":"而今识"},{"t":"尽","k":8},{"t":"愁滋味，"},{"t":"欲说还休","k":1},{"t":"。"}]},{"t":"欲说还休，却道“天凉好个秋”。","n":"","cn":"想诉说却又停住了，最后只说一句“天气凉了，好一个秋天啊”。","parts":[{"t":"欲说还休","k":1},{"t":"，却道“"},{"t":"天凉","k":4},{"t":"好个秋”。"}]}],"words":[{"w":"爱上层楼","e":"【易错】「爱上层楼」的「层」是尸字头，不要写成「曾」。"},{"w":"欲说还休","e":"【易错】「欲说还休」的「还」读 huán，不要写成「环」。"},{"w":"强说愁","e":"【易错】「强说愁」的「强」读 qiǎng，是勉强，不要读成 qiáng。"},{"w":"尝尽","e":"【易错】「识尽愁滋味」的「尽」是「尝尽」，不要写成「进」。"},{"w":"天凉","e":"【易错】「却道天凉好个秋」引号内是一个完整句子，默写时不要漏写「天凉」二字。"},{"w":"强","e":"【易错】「强说愁」的「强」读 qiǎng，是勉强，不要读成 qiáng。"},{"w":"层","e":"【易错】「爱上层楼」的「层」是尸字头，不要写成「曾」。"},{"w":"曾","e":"【易错】「爱上层楼」的「层」是尸字头，不要写成「曾」。"},{"w":"尽","e":"【易错】「识尽愁滋味」的「尽」是「尝尽」，不要写成「进」。"},{"w":"进","e":"【易错】「识尽愁滋味」的「尽」是「尝尽」，不要写成「进」。"},{"w":"还","e":"【易错】「欲说还休」的「还」读 huán，不要写成「环」。"},{"w":"环","e":"【易错】「欲说还休」的「还」读 huán，不要写成「环」。"}]},{"type":"list","title":"名句","items":["少年不识愁滋味，爱上层楼。","而今识尽愁滋味，欲说还休。"]},{"type":"list","title":"背诵提示","items":["「强说愁」的「强」读 qiǎng，是勉强，不要读成 qiáng。","「爱上层楼」的「层」是尸字头，不要写成「曾」。","「识尽愁滋味」的「尽」是「尝尽」，不要写成「进」。","「欲说还休」的「还」读 huán，不要写成「环」。","「却道天凉好个秋」引号内是一个完整句子，默写时不要漏写「天凉」二字。"]}],"questions":[{"id":"p-p9a-chou-nu-er-shu-bo-shan-dao-zhong-bi-m0","type":"fill","stem":"默写填空：少年不识愁滋味，______。","answer":"爱上层楼。","explain":"出自《丑奴儿·书博山道中壁》（宋·辛弃疾）：少年不识愁滋味，爱上层楼。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-chou-nu-er-shu-bo-shan-dao-zhong-bi-m1","type":"fill","stem":"默写填空：而今识尽愁滋味，______。","answer":"欲说还休。","explain":"出自《丑奴儿·书博山道中壁》（宋·辛弃疾）：而今识尽愁滋味，欲说还休。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9a-chou-nu-er-shu-bo-shan-dao-zhong-bi-u","type":"fill","stem":"理解性默写：年少时不懂得愁的滋味，喜欢登上高楼。","answer":"少年不识愁滋味，爱上层楼。","explain":"出自《丑奴儿·书博山道中壁》（宋·辛弃疾）。句意：年少时不懂得愁的滋味，喜欢登上高楼。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-yu-jia-ao-qiu-si","title":"渔家傲·秋思","subtitle":"宋·范仲淹","grade":"9b","tags":["边塞","思乡","爱国"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·范仲淹"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"范仲淹（989—1052），字希文，谥号“文正”，苏州吴县（今江苏苏州）人，北宋政治家、文学家，后人尊称他为“范文正公”。\n生平经历：他两岁丧父，少年时家贫而刻苦读书，“划粥断齑”的苦读故事流传至今；考中进士后历任地方与朝廷官职，为官清正敢言，曾因直言进谏而多次被贬；庆历年间官至参知政事，主持“庆历新政”，推行整顿吏治、改革科举等主张，因守旧派反对而失败；晚年出任地方官，在赴颍州途中病逝。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词是范仲淹戍守西北边陲时所作。上片写景，一个「异」字总领全篇：雁去无留意、边声连角起、千嶂孤城闭，视听结合，勾勒出边塞荒凉肃杀、戒备森严的独特景象；下片抒情，「浊酒一杯家万里」写思乡，「燕然未勒归无计」用窦宪勒石燕然的典故写建功立业的未竟之志，思乡之情与报国之志交织。结句「将军白发征夫泪」以白发与泪作结，苍凉悲壮，情调沉郁。中考常考：「异」字领起的具体内容、上片写景与下片抒情的关系、典故「燕然未勒」的作用，以及「羌管悠悠霜满地」的视听描写与全词悲壮苍凉的风格。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"塞下秋来风景异，衡阳雁去无留意。","n":"","cn":"边境上秋天一来风景就全然不同，大雁向衡阳飞去，毫无留恋之意。","parts":[{"t":"塞下秋来风景异，"},{"t":"衡阳雁去","k":0},{"t":"无留意。"}]},{"t":"四面边声连角起，千嶂里，长烟落日孤城闭。","n":"","cn":"四面的边塞声响随着号角声响起，在层层山峦环抱之中，长烟直上、落日西沉，一座孤城城门紧闭。","parts":[{"t":"四面边声连角起，"},{"t":"千嶂里","k":3},{"t":"，长烟落日"},{"t":"孤","k":12},{"t":"城闭。"}]},{"t":"浊酒一杯家万里，燕然未勒归无计。","n":"","cn":"饮一杯浊酒，思念万里之外的家乡；可是功业未成，归乡之计无从谈起。","parts":[{"t":"浊酒","k":6},{"t":"一杯家万里，"},{"t":"燕然未勒","k":1},{"t":"归无计。"}]},{"t":"羌管悠悠霜满地，人不寐，将军白发征夫泪。","n":"","cn":"羌笛声悠扬，寒霜铺满大地，征人无法入睡，将军白了头发，士兵落下眼泪。","parts":[{"t":"羌管悠悠","k":2},{"t":"霜满地，"},{"t":"人不寐","k":4},{"t":"，将军白发征夫泪。"}]}],"words":[{"w":"衡阳雁去","e":"【易错】「衡阳雁去」的「雁」不要写成「燕」（「燕然」才是「燕」）。"},{"w":"燕然未勒","e":"【易错】「燕然未勒」的「勒」是革字旁，不要写成「勤」。"},{"w":"羌管悠悠","e":"【易错】「羌管悠悠」的「羌」不要写成「姜」「枪」。"},{"w":"千嶂里","e":"【易错】「千嶂里」的「嶂」是山字旁，不要写成「障」「章」。"},{"w":"人不寐","e":"【易错】「人不寐」的「寐」是宝盖头下「爿」，不要写成「寝」。"},{"w":"燕然","e":"【易错】「衡阳雁去」的「雁」不要写成「燕」（「燕然」才是「燕」）。"},{"w":"浊酒","e":"【易错】「浊酒」的「浊」是三点水，不要写成「独」。"},{"w":"雁","e":"【易错】「衡阳雁去」的「雁」不要写成「燕」（「燕然」才是「燕」）。"},{"w":"燕","e":"【易错】「衡阳雁去」的「雁」不要写成「燕」（「燕然」才是「燕」）。"},{"w":"嶂","e":"【易错】「千嶂里」的「嶂」是山字旁，不要写成「障」「章」。"},{"w":"障","e":"【易错】「千嶂里」的「嶂」是山字旁，不要写成「障」「章」。"},{"w":"章","e":"【易错】「千嶂里」的「嶂」是山字旁，不要写成「障」「章」。"},{"w":"孤","e":"【易错】「长烟落日孤城闭」的「孤」是子字旁，不要写成「狐」「弧」。"},{"w":"狐","e":"【易错】「长烟落日孤城闭」的「孤」是子字旁，不要写成「狐」「弧」。"},{"w":"弧","e":"【易错】「长烟落日孤城闭」的「孤」是子字旁，不要写成「狐」「弧」。"},{"w":"浊","e":"【易错】「浊酒」的「浊」是三点水，不要写成「独」。"},{"w":"独","e":"【易错】「浊酒」的「浊」是三点水，不要写成「独」。"},{"w":"勒","e":"【易错】「燕然未勒」的「勒」是革字旁，不要写成「勤」。"},{"w":"勤","e":"【易错】「燕然未勒」的「勒」是革字旁，不要写成「勤」。"},{"w":"羌","e":"【易错】「羌管悠悠」的「羌」不要写成「姜」「枪」。"},{"w":"姜","e":"【易错】「羌管悠悠」的「羌」不要写成「姜」「枪」。"},{"w":"枪","e":"【易错】「羌管悠悠」的「羌」不要写成「姜」「枪」。"},{"w":"寐","e":"【易错】「人不寐」的「寐」是宝盖头下「爿」，不要写成「寝」。"},{"w":"爿","e":"【易错】「人不寐」的「寐」是宝盖头下「爿」，不要写成「寝」。"},{"w":"寝","e":"【易错】「人不寐」的「寐」是宝盖头下「爿」，不要写成「寝」。"}]},{"type":"list","title":"名句","items":["浊酒一杯家万里，燕然未勒归无计。","人不寐，将军白发征夫泪。"]},{"type":"list","title":"背诵提示","items":["「衡阳雁去」的「雁」不要写成「燕」（「燕然」才是「燕」）。","「千嶂里」的「嶂」是山字旁，不要写成「障」「章」。","「长烟落日孤城闭」的「孤」是子字旁，不要写成「狐」「弧」。","「浊酒」的「浊」是三点水，不要写成「独」。","「燕然未勒」的「勒」是革字旁，不要写成「勤」。","「羌管悠悠」的「羌」不要写成「姜」「枪」。","「人不寐」的「寐」是宝盖头下「爿」，不要写成「寝」。"]}],"questions":[{"id":"p-p9b-yu-jia-ao-qiu-si-m0","type":"fill","stem":"默写填空：浊酒一杯家万里，______。","answer":"燕然未勒归无计。","explain":"出自《渔家傲·秋思》（宋·范仲淹）：浊酒一杯家万里，燕然未勒归无计。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-yu-jia-ao-qiu-si-m1","type":"fill","stem":"默写填空：人不寐，______。","answer":"将军白发征夫泪。","explain":"出自《渔家傲·秋思》（宋·范仲淹）：人不寐，将军白发征夫泪。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-yu-jia-ao-qiu-si-u","type":"fill","stem":"理解性默写：边境上秋天一来风景就全然不同，大雁向衡阳飞去，毫无留恋之意。","answer":"塞下秋来风景异，衡阳雁去无留意。","explain":"出自《渔家傲·秋思》（宋·范仲淹）。句意：边境上秋天一来风景就全然不同，大雁向衡阳飞去，毫无留恋之意。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-jiang-cheng-zi-mi-zhou-chu-lie","title":"江城子·密州出猎","subtitle":"宋·苏轼","grade":"9b","tags":["出猎","爱国","用典"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·苏轼"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"苏轼（1037—1101），字子瞻，号东坡居士，北宋著名文学家、书画家，眉州眉山（今四川眉山）人。他与父亲苏洵、弟弟苏辙合称“三苏”，父子三人同列“唐宋八大家”。\n生平经历：嘉祐二年中进士，因反对王安石变法的某些做法而自请外任，先后任杭州、密州、徐州、湖州等地知州；“乌台诗案”后被贬黄州，写下大量名篇；此后又相继被贬惠州、儋州，遇赦北归途中病逝于常州。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词是苏轼豪放词的代表作。上片写出猎盛况，「老夫聊发少年狂」一「狂」字统摄全篇，「左牵黄，右擎苍」「千骑卷平冈」写场面的壮阔，「亲射虎，看孙郎」以孙权自比，豪气逼人；下片由出猎转入言志，「鬓微霜，又何妨」表现不服老、愿效命的雄心，「持节云中，何日遣冯唐」用冯唐持节赦魏尚的典故，委婉表达希望朝廷重用自己的愿望，结句「会挽雕弓如满月，西北望，射天狼」以「天狼」喻侵扰边境的西夏，抒发了杀敌报国、建功立业的壮志。中考常考：典故（孙权射虎、冯唐、天狼）的含义与作用、「狂」字的内涵、全词豪放的风格特点。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"老夫聊发少年狂，左牵黄，右擎苍，锦帽貂裘，千骑卷平冈。","n":"","cn":"老夫姑且抒发一下少年的豪情：左手牵着黄犬，右臂托着苍鹰，头戴锦帽、身穿貂裘，千骑奔驰，席卷平坦的山冈。","parts":[{"t":"老夫"},{"t":"聊","k":6},{"t":"发少年狂，左牵黄，"},{"t":"右擎苍","k":2},{"t":"，"},{"t":"锦帽貂裘","k":0},{"t":"，千"},{"t":"骑","k":16},{"t":"卷平"},{"t":"冈","k":17},{"t":"。"}]},{"t":"为报倾城随太守，亲射虎，看孙郎。","n":"","cn":"为了报答全城百姓跟随太守出猎的盛意，我要亲自射虎，像当年的孙权那样。","parts":[{"t":"为报"},{"t":"倾","k":21},{"t":"城随太守，亲射虎，看孙郎。"}]},{"t":"酒酣胸胆尚开张。鬓微霜，又何妨！","n":"","cn":"酒意正浓，胸怀开阔、胆气豪壮。鬓角虽已微白，又有什么关系！","parts":[{"t":"酒酣","k":5},{"t":"胸胆尚开张。"},{"t":"鬓微霜","k":3},{"t":"，又何妨！"}]},{"t":"持节云中，何日遣冯唐？","n":"","cn":"什么时候朝廷能像汉文帝派遣冯唐去云中赦免魏尚那样，也派人来重用我呢？","parts":[{"t":"持节云中，何日遣冯唐？"}]},{"t":"会挽雕弓如满月，西北望，射天狼。","n":"","cn":"那时我定要拉开雕花的强弓，把弓拉得像满月一样圆，朝着西北方向，射下那凶残的天狼星。","parts":[{"t":"会挽雕弓","k":1},{"t":"如满月，西北望，射天狼。"}]}],"words":[{"w":"锦帽貂裘","e":"【易错】「锦帽貂裘」的「貂」右旁是「召」，不要写成「绍」「招」。"},{"w":"会挽雕弓","e":"【易错】「会挽雕弓」的「挽」是提手旁，不要写成「晚」「挽」以外的「免」。"},{"w":"右擎苍","e":"【易错】「右擎苍」的「擎」下面是「手」，不要写成「警」「惊」。"},{"w":"鬓微霜","e":"【易错】「鬓微霜」的「鬓」上部是「髟」，不要漏写。"},{"w":"姑且","e":"【易错】「聊发少年狂」的「聊」是「姑且」，不要写成「了」。"},{"w":"酒酣","e":"【易错】「酒酣」的「酣」是酉字旁，不要写成「甘」「甜」。"},{"w":"聊","e":"【易错】「聊发少年狂」的「聊」是「姑且」，不要写成「了」。"},{"w":"了","e":"【易错】「聊发少年狂」的「聊」是「姑且」，不要写成「了」。"},{"w":"擎","e":"【易错】「右擎苍」的「擎」下面是「手」，不要写成「警」「惊」。"},{"w":"手","e":"【易错】「右擎苍」的「擎」下面是「手」，不要写成「警」「惊」。"},{"w":"警","e":"【易错】「右擎苍」的「擎」下面是「手」，不要写成「警」「惊」。"},{"w":"惊","e":"【易错】「右擎苍」的「擎」下面是「手」，不要写成「警」「惊」。"},{"w":"貂","e":"【易错】「锦帽貂裘」的「貂」右旁是「召」，不要写成「绍」「招」。"},{"w":"召","e":"【易错】「锦帽貂裘」的「貂」右旁是「召」，不要写成「绍」「招」。"},{"w":"绍","e":"【易错】「锦帽貂裘」的「貂」右旁是「召」，不要写成「绍」「招」。"},{"w":"招","e":"【易错】「锦帽貂裘」的「貂」右旁是「召」，不要写成「绍」「招」。"},{"w":"骑","e":"【易错】「千骑卷平冈」的「骑」读 jì，「冈」是「冂」内「乂」，不要写成「岗」。"},{"w":"冈","e":"【易错】「千骑卷平冈」的「骑」读 jì，「冈」是「冂」内「乂」，不要写成「岗」。"},{"w":"冂","e":"【易错】「千骑卷平冈」的「骑」读 jì，「冈」是「冂」内「乂」，不要写成「岗」。"},{"w":"乂","e":"【易错】「千骑卷平冈」的「骑」读 jì，「冈」是「冂」内「乂」，不要写成「岗」。"},{"w":"岗","e":"【易错】「千骑卷平冈」的「骑」读 jì，「冈」是「冂」内「乂」，不要写成「岗」。"},{"w":"倾","e":"【易错】「倾城随太守」的「倾」是单人旁，不要写成「顷」。"},{"w":"顷","e":"【易错】「倾城随太守」的「倾」是单人旁，不要写成「顷」。"},{"w":"酣","e":"【易错】「酒酣」的「酣」是酉字旁，不要写成「甘」「甜」。"},{"w":"甘","e":"【易错】「酒酣」的「酣」是酉字旁，不要写成「甘」「甜」。"},{"w":"甜","e":"【易错】「酒酣」的「酣」是酉字旁，不要写成「甘」「甜」。"},{"w":"鬓","e":"【易错】「鬓微霜」的「鬓」上部是「髟」，不要漏写。"},{"w":"髟","e":"【易错】「鬓微霜」的「鬓」上部是「髟」，不要漏写。"},{"w":"挽","e":"【易错】「会挽雕弓」的「挽」是提手旁，不要写成「晚」「挽」以外的「免」。"},{"w":"晚","e":"【易错】「会挽雕弓」的「挽」是提手旁，不要写成「晚」「挽」以外的「免」。"},{"w":"免","e":"【易错】「会挽雕弓」的「挽」是提手旁，不要写成「晚」「挽」以外的「免」。"}]},{"type":"list","title":"名句","items":["会挽雕弓如满月，西北望，射天狼。"]},{"type":"list","title":"背诵提示","items":["「聊发少年狂」的「聊」是「姑且」，不要写成「了」。","「右擎苍」的「擎」下面是「手」，不要写成「警」「惊」。","「锦帽貂裘」的「貂」右旁是「召」，不要写成「绍」「招」。","「千骑卷平冈」的「骑」读 jì，「冈」是「冂」内「乂」，不要写成「岗」。","「倾城随太守」的「倾」是单人旁，不要写成「顷」。","「酒酣」的「酣」是酉字旁，不要写成「甘」「甜」。","「鬓微霜」的「鬓」上部是「髟」，不要漏写。","「会挽雕弓」的「挽」是提手旁，不要写成「晚」「挽」以外的「免」。"]}],"questions":[{"id":"p-p9b-jiang-cheng-zi-mi-zhou-chu-lie-m0","type":"fill","stem":"默写填空：会挽雕弓如满月，______。","answer":"西北望。","explain":"出自《江城子·密州出猎》（宋·苏轼）：会挽雕弓如满月，西北望，射天狼。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-jiang-cheng-zi-mi-zhou-chu-lie-u","type":"fill","stem":"理解性默写：老夫姑且抒发一下少年的豪情：左手牵着黄犬，右臂托着苍鹰，头戴锦帽、身穿貂裘，千骑奔驰，席卷平坦的山冈。","answer":"老夫聊发少年狂，左牵黄，右擎苍，锦帽貂裘，千骑卷平冈。","explain":"出自《江城子·密州出猎》（宋·苏轼）。句意：老夫姑且抒发一下少年的豪情：左手牵着黄犬，右臂托着苍鹰，头戴锦帽、身穿貂裘，千骑奔驰，席卷平坦的山冈。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-po-zhen-zi-wei-chen-tong-fu-fu-zhuang-ci-yi-ji-zhi","title":"破阵子·为陈同甫赋壮词以寄之","subtitle":"宋·辛弃疾","grade":"9b","tags":["军旅","爱国","壮志难酬"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·辛弃疾"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"辛弃疾（1140—1207），字幼安，号稼轩，历城（今山东济南）人，南宋豪放派词人，与苏轼并称“苏辛”，与李清照并称“济南二安”。\n生平经历：他出生时中原已被金人占领，二十一岁便组织义军抗金，曾率五十骑闯入敌营擒拿叛将，一时声名大振；南归后长期不受重用，只做过地方官职，多次上书陈述抗金方略都未被采纳；他先后闲居江西上饶、铅山近二十年，把报国无门的悲愤都写进词里，晚年虽再被起用，不久便抱憾辞世。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词是辛弃疾寄给好友陈亮（字同甫）的壮词。全篇前九句都是醉里梦中的回忆与想象：看剑、连营号角、分炙、奏乐、点兵、飞马、惊弦、了却天下事、赢得身后名，一句一景，气势雄壮，把军营生活与战斗场面写得酣畅淋漓；最后一句「可怜白发生」陡然转折，梦境破碎，回到壮志难酬、年华已老的现实，全词由壮转悲，形成强烈的反差，正是「壮词」中饱含的悲愤。中考常考：虚实结合（梦境与现实）的结构、末句转折的表达效果、「八百里」「的卢」「霹雳」等典故与比喻的理解，以及作者杀敌报国、壮志难酬的爱国情怀。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"醉里挑灯看剑，梦回吹角连营。","n":"","cn":"醉梦里挑亮油灯细看宝剑，梦醒时仿佛还听到各个军营接连响起的号角声。","parts":[{"t":"醉里"},{"t":"挑灯看剑","k":0},{"t":"，梦回"},{"t":"吹角连营","k":1},{"t":"。"}]},{"t":"八百里分麾下炙，五十弦翻塞外声。沙场秋点兵。","n":"","cn":"把烤熟的牛肉分给部下享用，让乐器奏起雄壮的塞外军乐。这是秋天在战场上检阅军队。","parts":[{"t":"八百里","k":3},{"t":"分"},{"t":"麾下","k":4},{"t":"炙，五十弦"},{"t":"翻","k":17},{"t":"塞外声。沙"},{"t":"场","k":19},{"t":"秋点兵。"}]},{"t":"马作的卢飞快，弓如霹雳弦惊。","n":"","cn":"战马像的卢马一样飞奔驰骋，弓弦发出雷鸣般的响声令人心惊。","parts":[{"t":"马作"},{"t":"的卢","k":5},{"t":"飞快，"},{"t":"弓如霹雳","k":2},{"t":"弦惊。"}]},{"t":"了却君王天下事，赢得生前身后名。可怜白发生！","n":"","cn":"了结君王收复失地的大业，赢得生前身后的美名。可惜壮志未酬，白发已生！","parts":[{"t":"了却君王天下事，赢得生前身后名。可怜白发生！"}]}],"words":[{"w":"挑灯看剑","e":"【易错】「挑灯看剑」的「挑」读 tiǎo，是挑亮，不要写成「眺」。"},{"w":"吹角连营","e":"【易错】「吹角连营」的「角」指号角，不要写成「脚」。"},{"w":"弓如霹雳","e":"【易错】「弓如霹雳」的「霹雳」两字都是雨字头，不要写成「劈历」。"},{"w":"八百里","e":"【易错】「八百里」指牛，不要误解为距离；「麾下」的「麾」是麻字头下「毛」，不要写成「摩」。"},{"w":"麾下","e":"【易错】「八百里」指牛，不要误解为距离；「麾下」的「麾」是麻字头下「毛」，不要写成「摩」。"},{"w":"的卢","e":"【易错】「马作的卢飞快」的「的」读 dí，「的卢」是良马名。"},{"w":"霹雳","e":"【易错】「弓如霹雳」的「霹雳」两字都是雨字头，不要写成「劈历」。"},{"w":"劈历","e":"【易错】「弓如霹雳」的「霹雳」两字都是雨字头，不要写成「劈历」。"},{"w":"嬴得","e":"【易错】「赢得生前身后名」不要写成「嬴得」「羸得」。"},{"w":"羸得","e":"【易错】「赢得生前身后名」不要写成「嬴得」「羸得」。"},{"w":"挑","e":"【易错】「挑灯看剑」的「挑」读 tiǎo，是挑亮，不要写成「眺」。"},{"w":"眺","e":"【易错】「挑灯看剑」的「挑」读 tiǎo，是挑亮，不要写成「眺」。"},{"w":"角","e":"【易错】「吹角连营」的「角」指号角，不要写成「脚」。"},{"w":"脚","e":"【易错】「吹角连营」的「角」指号角，不要写成「脚」。"},{"w":"麾","e":"【易错】「八百里」指牛，不要误解为距离；「麾下」的「麾」是麻字头下「毛」，不要写成「摩」。"},{"w":"毛","e":"【易错】「八百里」指牛，不要误解为距离；「麾下」的「麾」是麻字头下「毛」，不要写成「摩」。"},{"w":"摩","e":"【易错】「八百里」指牛，不要误解为距离；「麾下」的「麾」是麻字头下「毛」，不要写成「摩」。"},{"w":"翻","e":"【易错】「五十弦翻塞外声」的「翻」是演奏，不要写成「番」。"},{"w":"番","e":"【易错】「五十弦翻塞外声」的「翻」是演奏，不要写成「番」。"},{"w":"场","e":"【易错】「沙场秋点兵」的「场」是土字旁，不要写成「埸」。"},{"w":"埸","e":"【易错】「沙场秋点兵」的「场」是土字旁，不要写成「埸」。"},{"w":"的","e":"【易错】「马作的卢飞快」的「的」读 dí，「的卢」是良马名。"}]},{"type":"list","title":"名句","items":["了却君王天下事，赢得生前身后名。可怜白发生！"]},{"type":"list","title":"背诵提示","items":["「挑灯看剑」的「挑」读 tiǎo，是挑亮，不要写成「眺」。","「吹角连营」的「角」指号角，不要写成「脚」。","「八百里」指牛，不要误解为距离；「麾下」的「麾」是麻字头下「毛」，不要写成「摩」。","「五十弦翻塞外声」的「翻」是演奏，不要写成「番」。","「沙场秋点兵」的「场」是土字旁，不要写成「埸」。","「马作的卢飞快」的「的」读 dí，「的卢」是良马名。","「弓如霹雳」的「霹雳」两字都是雨字头，不要写成「劈历」。","「赢得生前身后名」不要写成「嬴得」「羸得」。"]}],"questions":[{"id":"p-p9b-po-zhen-zi-wei-chen-tong-fu-fu-zhuang-ci-yi-ji-zhi-m0","type":"fill","stem":"默写填空：了却君王天下事，______。","answer":"赢得生前身后名。可怜白发生！。","explain":"出自《破阵子·为陈同甫赋壮词以寄之》（宋·辛弃疾）：了却君王天下事，赢得生前身后名。可怜白发生！","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-po-zhen-zi-wei-chen-tong-fu-fu-zhuang-ci-yi-ji-zhi-u","type":"fill","stem":"理解性默写：醉梦里挑亮油灯细看宝剑，梦醒时仿佛还听到各个军营接连响起的号角声。","answer":"醉里挑灯看剑，梦回吹角连营。","explain":"出自《破阵子·为陈同甫赋壮词以寄之》（宋·辛弃疾）。句意：醉梦里挑亮油灯细看宝剑，梦醒时仿佛还听到各个军营接连响起的号角声。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-man-jiang-hong-xiao-zhu-jing-hua","title":"满江红（小住京华）","subtitle":"清·秋瑾","grade":"9b","tags":["言志","爱国","女子豪情"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"清·秋瑾"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"秋瑾（1875—1907），字竞雄，号鉴湖女侠，清末女革命家、诗人，浙江山阴（今浙江绍兴）人。\n生平经历：她冲破封建家庭的束缚，东渡日本留学，先后加入光复会、同盟会；回国后在上海创办《中国女报》，宣传妇女解放；后又回绍兴主持大通学堂，与徐锡麟筹划皖浙起义，事败被捕，就义于绍兴轩亭口。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词是秋瑾冲破家庭束缚、投身革命前夕所作。上片写中秋景物与身世之感：黄花如拭的明丽秋容反衬内心的激荡；「四面歌残终破楚」借项羽四面楚歌的典故暗写国势危亡，「八年风味徒思浙」写婚后八年寄居北京、思念故乡的苦闷；「苦将侬强派作蛾眉，殊未屑」直抒对封建礼教安排女子命运的不屑与反抗。下片「身不得，男儿列，心却比，男儿烈」以对比与反复写出巾帼不让须眉的豪情，「俗子胸襟谁识我」是知音难觅的孤愤，末句「青衫湿」化用白居易《琵琶行》，以泪作结，慷慨悲凉。中考常考：典故的作用、对比手法、抒情主人公的形象及词中表现的革命豪情与忧国之心。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"小住京华，早又是中秋佳节。","n":"","cn":"我客居北京不久，转眼又到了中秋佳节。","parts":[{"t":"小住京华，早又是中秋佳节。"}]},{"t":"为篱下黄花开遍，秋容如拭。","n":"","cn":"因为篱笆下的菊花开遍了，秋天的容貌像刚刚擦洗过一样明净。","parts":[{"t":"为篱下黄花开遍，"},{"t":"秋容如拭","k":0},{"t":"。"}]},{"t":"四面歌残终破楚，八年风味徒思浙。","n":"","cn":"四面的歌声唱尽，终于突破了楚国的重围（暗指国势危亡）；八年来只空自思念浙江故乡。","parts":[{"t":"四面歌残终破"},{"t":"楚","k":13},{"t":"，八年风味徒思浙。"}]},{"t":"苦将侬强派作蛾眉，殊未屑！","n":"","cn":"苦苦地硬把我强派作女子之身（要我安守女子本分），我实在是不屑！","parts":[{"t":"苦将"},{"t":"侬","k":16},{"t":"强派作"},{"t":"蛾眉","k":6},{"t":"，"},{"t":"殊未屑","k":3},{"t":"！"}]},{"t":"身不得，男儿列，心却比，男儿烈。","n":"","cn":"我这身子不能列入男子的行列，但我的心却比男子还要刚烈。","parts":[{"t":"身不得，"},{"t":"男儿列","k":4},{"t":"，心却比，男儿"},{"t":"烈","k":23},{"t":"。"}]},{"t":"算平生肝胆，因人常热。","n":"","cn":"想来我平生的侠肝义胆，常因他人而热血沸腾。","parts":[{"t":"算平生肝胆，"},{"t":"因人常热","k":1},{"t":"。"}]},{"t":"俗子胸襟谁识我？英雄末路当磨折。","n":"","cn":"凡俗之人的狭隘心胸，谁能了解我呢？英雄走到末路，本来就该受尽磨难挫折。","parts":[{"t":"俗子胸襟","k":2},{"t":"谁识我？英雄末路当磨折。"}]},{"t":"莽红尘何处觅知音？青衫湿！","n":"","cn":"茫茫红尘之中到哪里去寻找知音呢？泪水沾湿了我的衣裳！","parts":[{"t":"莽红尘","k":5},{"t":"何处觅知音？青衫湿！"}]}],"words":[{"w":"秋容如拭","e":"【易错】「秋容如拭」的「拭」是提手旁，不要写成「试」「恃」。"},{"w":"因人常热","e":"【易错】「因人常热」的「因」是「因为」，不要写成「应」。"},{"w":"俗子胸襟","e":"【易错】「俗子胸襟」的「襟」是衣字旁，不要写成「禁」「噤」。"},{"w":"殊未屑","e":"【易错】「殊未屑」的「屑」是尸字头下「肖」，不要写成「消」「雪」。"},{"w":"男儿列","e":"【易错】「男儿列」的「列」是「行列」，不要写成「烈」。"},{"w":"莽红尘","e":"【易错】「莽红尘」的「莽」是草字头下「犬」的变体，不要写成「茫」。"},{"w":"蛾眉","e":"【易错】「苦将侬强派作蛾眉」的「侬」是单人旁，「蛾眉」的「蛾」是虫字旁，不要写成「娥眉」。"},{"w":"娥眉","e":"【易错】「苦将侬强派作蛾眉」的「侬」是单人旁，「蛾眉」的「蛾」是虫字旁，不要写成「娥眉」。"},{"w":"行列","e":"【易错】「男儿列」的「列」是「行列」，不要写成「烈」。"},{"w":"因为","e":"【易错】「因人常热」的「因」是「因为」，不要写成「应」。"},{"w":"拭","e":"【易错】「秋容如拭」的「拭」是提手旁，不要写成「试」「恃」。"},{"w":"试","e":"【易错】「秋容如拭」的「拭」是提手旁，不要写成「试」「恃」。"},{"w":"恃","e":"【易错】「秋容如拭」的「拭」是提手旁，不要写成「试」「恃」。"},{"w":"楚","e":"【易错】「四面歌残终破楚」的「楚」下面是「疋」，不要写成「梦」。"},{"w":"疋","e":"【易错】「四面歌残终破楚」的「楚」下面是「疋」，不要写成「梦」。"},{"w":"梦","e":"【易错】「四面歌残终破楚」的「楚」下面是「疋」，不要写成「梦」。"},{"w":"侬","e":"【易错】「苦将侬强派作蛾眉」的「侬」是单人旁，「蛾眉」的「蛾」是虫字旁，不要写成「娥眉」。"},{"w":"蛾","e":"【易错】「苦将侬强派作蛾眉」的「侬」是单人旁，「蛾眉」的「蛾」是虫字旁，不要写成「娥眉」。"},{"w":"屑","e":"【易错】「殊未屑」的「屑」是尸字头下「肖」，不要写成「消」「雪」。"},{"w":"肖","e":"【易错】「殊未屑」的「屑」是尸字头下「肖」，不要写成「消」「雪」。"},{"w":"消","e":"【易错】「殊未屑」的「屑」是尸字头下「肖」，不要写成「消」「雪」。"},{"w":"雪","e":"【易错】「殊未屑」的「屑」是尸字头下「肖」，不要写成「消」「雪」。"},{"w":"列","e":"【易错】「男儿列」的「列」是「行列」，不要写成「烈」。"},{"w":"烈","e":"【易错】「男儿列」的「列」是「行列」，不要写成「烈」。"},{"w":"因","e":"【易错】「因人常热」的「因」是「因为」，不要写成「应」。"},{"w":"应","e":"【易错】「因人常热」的「因」是「因为」，不要写成「应」。"},{"w":"襟","e":"【易错】「俗子胸襟」的「襟」是衣字旁，不要写成「禁」「噤」。"},{"w":"禁","e":"【易错】「俗子胸襟」的「襟」是衣字旁，不要写成「禁」「噤」。"},{"w":"噤","e":"【易错】「俗子胸襟」的「襟」是衣字旁，不要写成「禁」「噤」。"},{"w":"莽","e":"【易错】「莽红尘」的「莽」是草字头下「犬」的变体，不要写成「茫」。"},{"w":"犬","e":"【易错】「莽红尘」的「莽」是草字头下「犬」的变体，不要写成「茫」。"},{"w":"茫","e":"【易错】「莽红尘」的「莽」是草字头下「犬」的变体，不要写成「茫」。"}]},{"type":"list","title":"名句","items":["身不得，男儿列，心却比，男儿烈。","莽红尘何处觅知音？青衫湿！"]},{"type":"list","title":"背诵提示","items":["「秋容如拭」的「拭」是提手旁，不要写成「试」「恃」。","「四面歌残终破楚」的「楚」下面是「疋」，不要写成「梦」。","「苦将侬强派作蛾眉」的「侬」是单人旁，「蛾眉」的「蛾」是虫字旁，不要写成「娥眉」。","「殊未屑」的「屑」是尸字头下「肖」，不要写成「消」「雪」。","「男儿列」的「列」是「行列」，不要写成「烈」。","「因人常热」的「因」是「因为」，不要写成「应」。","「俗子胸襟」的「襟」是衣字旁，不要写成「禁」「噤」。","「莽红尘」的「莽」是草字头下「犬」的变体，不要写成「茫」。"]}],"questions":[{"id":"p-p9b-man-jiang-hong-xiao-zhu-jing-hua-m0","type":"fill","stem":"默写填空：身不得，______。","answer":"男儿列。","explain":"出自《满江红（小住京华）》（清·秋瑾）：身不得，男儿列，心却比，男儿烈。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-man-jiang-hong-xiao-zhu-jing-hua-u","type":"fill","stem":"理解性默写：我客居北京不久，转眼又到了中秋佳节。","answer":"小住京华，早又是中秋佳节。","explain":"出自《满江红（小住京华）》（清·秋瑾）。句意：我客居北京不久，转眼又到了中秋佳节。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-ding-feng-bo-mo-ting-chuan-lin-da-ye-sheng","title":"定风波（莫听穿林打叶声）","subtitle":"宋·苏轼","grade":"9b","tags":["旷达","哲理","写景"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·苏轼"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"苏轼（1037—1101），字子瞻，号东坡居士，北宋著名文学家、书画家，眉州眉山（今四川眉山）人。他与父亲苏洵、弟弟苏辙合称“三苏”，父子三人同列“唐宋八大家”。\n生平经历：嘉祐二年中进士，因反对王安石变法的某些做法而自请外任，先后任杭州、密州、徐州、湖州等地知州；“乌台诗案”后被贬黄州，写下大量名篇；此后又相继被贬惠州、儋州，遇赦北归途中病逝于常州。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词借途中遇雨的小事，抒写苏轼旷达超脱的人生态度。上片写雨中，「莫听」「何妨」「谁怕」三处语气层层递进，「竹杖芒鞋轻胜马」以对比写心境的轻松，「一蓑烟雨任平生」是全词名句，表现不惧风雨、随遇而安的胸襟。下片写雨后，「料峭春风」「山头斜照」暗示境遇由冷转暖，结句「也无风雨也无晴」以双关收束，把自然界的晴雨与人生的顺逆祸福融为一体，达到宠辱不惊、物我两忘的境界。中考常考：小序与词作的关系、「一蓑烟雨任平生」的象征义、结句的哲理与双关，以及词中表现的人生态度。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"莫听穿林打叶声，何妨吟啸且徐行。","n":"","cn":"不要去听那穿林打叶的雨声，不妨一边吟诗长啸，一边从容慢行。","parts":[{"t":"莫听穿林打叶声，何妨吟"},{"t":"啸","k":6},{"t":"且徐行。"}]},{"t":"竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。","n":"","cn":"拄着竹杖、穿着草鞋，比骑马还要轻快，怕什么？披一件蓑衣，任凭一生风吹雨打。","parts":[{"t":"竹杖芒鞋","k":0},{"t":"轻胜马，谁怕？"},{"t":"一蓑烟雨","k":1},{"t":"任平生。"}]},{"t":"料峭春风吹酒醒，微冷，山头斜照却相迎。","n":"","cn":"微寒的春风把我的酒意吹醒，感到有些冷，山头初晴的斜阳却迎面而来。","parts":[{"t":"料峭春风","k":2},{"t":"吹酒醒，微冷，"},{"t":"山头斜照","k":3},{"t":"却相迎。"}]},{"t":"回首向来萧瑟处，归去，也无风雨也无晴。","n":"","cn":"回头看看刚才风雨萧瑟的地方，回去吧，那里既无所谓风雨，也无所谓天晴。","parts":[{"t":"回首向来"},{"t":"萧瑟处","k":4},{"t":"，归去，也无风雨也无晴。"}]}],"words":[{"w":"竹杖芒鞋","e":"【易错】「竹杖芒鞋」的「芒」是草字头，不要写成「茫」。"},{"w":"一蓑烟雨","e":"【易错】「一蓑烟雨」的「蓑」是草字头，不要写成「衰」「梭」。"},{"w":"料峭春风","e":"【易错】「料峭春风」两字都是「山」旁（原文作「料峭」），「峭」不要写成「俏」。"},{"w":"山头斜照","e":"【易错】「山头斜照」的「斜」不要写成「邪」。"},{"w":"萧瑟处","e":"【易错】「萧瑟处」的「萧」是草字头，不要写成「箫」。"},{"w":"料峭","e":"【易错】「料峭春风」两字都是「山」旁（原文作「料峭」），「峭」不要写成「俏」。"},{"w":"啸","e":"【易错】「吟啸且徐行」的「啸」是口字旁，不要写成「肃」「箫」。"},{"w":"肃","e":"【易错】「吟啸且徐行」的「啸」是口字旁，不要写成「肃」「箫」。"},{"w":"箫","e":"【易错】「吟啸且徐行」的「啸」是口字旁，不要写成「肃」「箫」。"},{"w":"芒","e":"【易错】「竹杖芒鞋」的「芒」是草字头，不要写成「茫」。"},{"w":"茫","e":"【易错】「竹杖芒鞋」的「芒」是草字头，不要写成「茫」。"},{"w":"蓑","e":"【易错】「一蓑烟雨」的「蓑」是草字头，不要写成「衰」「梭」。"},{"w":"衰","e":"【易错】「一蓑烟雨」的「蓑」是草字头，不要写成「衰」「梭」。"},{"w":"梭","e":"【易错】「一蓑烟雨」的「蓑」是草字头，不要写成「衰」「梭」。"},{"w":"山","e":"【易错】「料峭春风」两字都是「山」旁（原文作「料峭」），「峭」不要写成「俏」。"},{"w":"峭","e":"【易错】「料峭春风」两字都是「山」旁（原文作「料峭」），「峭」不要写成「俏」。"},{"w":"俏","e":"【易错】「料峭春风」两字都是「山」旁（原文作「料峭」），「峭」不要写成「俏」。"},{"w":"斜","e":"【易错】「山头斜照」的「斜」不要写成「邪」。"},{"w":"邪","e":"【易错】「山头斜照」的「斜」不要写成「邪」。"},{"w":"萧","e":"【易错】「萧瑟处」的「萧」是草字头，不要写成「箫」。"}]},{"type":"list","title":"名句","items":["竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。","回首向来萧瑟处，归去，也无风雨也无晴。"]},{"type":"list","title":"背诵提示","items":["「吟啸且徐行」的「啸」是口字旁，不要写成「肃」「箫」。","「竹杖芒鞋」的「芒」是草字头，不要写成「茫」。","「一蓑烟雨」的「蓑」是草字头，不要写成「衰」「梭」。","「料峭春风」两字都是「山」旁（原文作「料峭」），「峭」不要写成「俏」。","「山头斜照」的「斜」不要写成「邪」。","「萧瑟处」的「萧」是草字头，不要写成「箫」。"]}],"questions":[{"id":"p-p9b-ding-feng-bo-mo-ting-chuan-lin-da-ye-sheng-m0","type":"fill","stem":"默写填空：竹杖芒鞋轻胜马，______。","answer":"谁怕？一蓑烟雨任平生。","explain":"出自《定风波（莫听穿林打叶声）》（宋·苏轼）：竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-ding-feng-bo-mo-ting-chuan-lin-da-ye-sheng-m1","type":"fill","stem":"默写填空：回首向来萧瑟处，______。","answer":"归去。","explain":"出自《定风波（莫听穿林打叶声）》（宋·苏轼）：回首向来萧瑟处，归去，也无风雨也无晴。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-ding-feng-bo-mo-ting-chuan-lin-da-ye-sheng-u","type":"fill","stem":"理解性默写：不要去听那穿林打叶的雨声，不妨一边吟诗长啸，一边从容慢行。","answer":"莫听穿林打叶声，何妨吟啸且徐行。","explain":"出自《定风波（莫听穿林打叶声）》（宋·苏轼）。句意：不要去听那穿林打叶的雨声，不妨一边吟诗长啸，一边从容慢行。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-lin-jiang-xian-ye-deng-xiao-ge-yi-luo-zhong-jiu-you","title":"临江仙·夜登小阁忆洛中旧游","subtitle":"宋·陈与义","grade":"9b","tags":["怀旧","伤今","家国之痛"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·陈与义"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"陈与义（1090—1139），字去非，号简斋，洛阳（今河南洛阳）人，两宋之交的诗人，江西诗派的代表作家之一。\n生平经历：他早年因《墨梅》诗受到宋徽宗赏识而步入仕途；靖康之变后中原沦陷，他辗转南奔，历尽艰险，先后避乱于襄阳、湖南、广东等地；南宋初年他历任要职，官至参知政事，晚年病逝于临安。南渡的流离与国破之痛，使他的诗风由早年的清新明快转为沉郁悲壮。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词是陈与义追忆洛阳旧游、感伤国事之作。上片全写回忆：午桥宴饮、坐中豪英、长沟流月、杏花疏影、吹笛到天明，用清丽的意象勾勒出少年时代豪宕欢乐的生活画面，「杏花疏影里，吹笛到天明」是千古名句，写景如画而韵味悠长。下片回到现实，「二十余年如一梦，此身虽在堪惊」写靖康之变后国破家亡、劫后余生的惊悸与沉痛；结句「古今多少事，渔唱起三更」把个人身世之感与家国兴亡之痛一并托付给渔歌，以淡语收束，苍凉旷远。中考常考：上下片今昔对比（昔盛今衰）的结构、名句的画面感与意境、结句的以景结情与言外之意。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"忆昔午桥桥上饮，坐中多是豪英。","n":"","cn":"回忆从前在午桥上饮宴，在座的多是英雄豪杰。","parts":[{"t":"忆昔"},{"t":"午桥","k":1},{"t":"桥上饮，坐中多是"},{"t":"豪","k":5},{"t":"英。"}]},{"t":"长沟流月去无声。杏花疏影里，吹笛到天明。","n":"","cn":"长长的河沟里流水载着月影悄然流去。在杏花稀疏的影子里，我们吹笛一直吹到天亮。","parts":[{"t":"长"},{"t":"沟","k":8},{"t":"流月去无声。"},{"t":"杏花疏影","k":0},{"t":"里，吹笛到天明。"}]},{"t":"二十余年如一梦，此身虽在堪惊。","n":"","cn":"二十多年过去，就像一场梦，我这个人虽然还在，回想起来却令人心惊。","parts":[{"t":"二十余年如一梦，此身虽在"},{"t":"堪","k":13},{"t":"惊。"}]},{"t":"闲登小阁看新晴。古今多少事，渔唱起三更。","n":"","cn":"如今闲来登上小阁，看雨后初晴的景色。古往今来多少兴亡之事，都化作三更时分渔人的歌声。","parts":[{"t":"闲登小阁看新晴。古今多少事，"},{"t":"渔","k":15},{"t":"唱起三更。"}]}],"words":[{"w":"杏花疏影","e":"【易错】「杏花疏影」的「疏」左旁是「疋」，不要写成「蔬」。"},{"w":"午桥","e":"【易错】「午桥」的「午」不要写成「牛」「伍」。"},{"w":"午","e":"【易错】「午桥」的「午」不要写成「牛」「伍」。"},{"w":"牛","e":"【易错】「午桥」的「午」不要写成「牛」「伍」。"},{"w":"伍","e":"【易错】「午桥」的「午」不要写成「牛」「伍」。"},{"w":"豪","e":"【易错】「坐中多是豪英」的「豪」下面是「豕」，不要写成「毫」。"},{"w":"豕","e":"【易错】「坐中多是豪英」的「豪」下面是「豕」，不要写成「毫」。"},{"w":"毫","e":"【易错】「坐中多是豪英」的「豪」下面是「豕」，不要写成「毫」。"},{"w":"沟","e":"【易错】「长沟流月去无声」的「沟」是三点水，不要写成「钩」。"},{"w":"钩","e":"【易错】「长沟流月去无声」的「沟」是三点水，不要写成「钩」。"},{"w":"疏","e":"【易错】「杏花疏影」的「疏」左旁是「疋」，不要写成「蔬」。"},{"w":"疋","e":"【易错】「杏花疏影」的「疏」左旁是「疋」，不要写成「蔬」。"},{"w":"蔬","e":"【易错】「杏花疏影」的「疏」左旁是「疋」，不要写成「蔬」。"},{"w":"堪","e":"【易错】「此身虽在堪惊」的「堪」是土字旁，不要写成「勘」。"},{"w":"勘","e":"【易错】「此身虽在堪惊」的「堪」是土字旁，不要写成「勘」。"},{"w":"渔","e":"【易错】「渔唱起三更」的「渔」是三点水，不要写成「鱼」。"},{"w":"鱼","e":"【易错】「渔唱起三更」的「渔」是三点水，不要写成「鱼」。"}]},{"type":"list","title":"名句","items":["杏花疏影里，吹笛到天明。"]},{"type":"list","title":"背诵提示","items":["「午桥」的「午」不要写成「牛」「伍」。","「坐中多是豪英」的「豪」下面是「豕」，不要写成「毫」。","「长沟流月去无声」的「沟」是三点水，不要写成「钩」。","「杏花疏影」的「疏」左旁是「疋」，不要写成「蔬」。","「此身虽在堪惊」的「堪」是土字旁，不要写成「勘」。","「渔唱起三更」的「渔」是三点水，不要写成「鱼」。"]}],"questions":[{"id":"p-p9b-lin-jiang-xian-ye-deng-xiao-ge-yi-luo-zhong-jiu-you-m0","type":"fill","stem":"默写填空：杏花疏影里，______。","answer":"吹笛到天明。","explain":"出自《临江仙·夜登小阁忆洛中旧游》（宋·陈与义）：杏花疏影里，吹笛到天明。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-lin-jiang-xian-ye-deng-xiao-ge-yi-luo-zhong-jiu-you-u","type":"fill","stem":"理解性默写：回忆从前在午桥上饮宴，在座的多是英雄豪杰。","answer":"忆昔午桥桥上饮，坐中多是豪英。","explain":"出自《临江仙·夜登小阁忆洛中旧游》（宋·陈与义）。句意：回忆从前在午桥上饮宴，在座的多是英雄豪杰。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-tai-chang-yin-jian-kang-zhong-qiu-ye-wei-lv-shu-qian-fu","title":"太常引·建康中秋夜为吕叔潜赋","subtitle":"宋·辛弃疾","grade":"9b","tags":["中秋","言志","象征"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·辛弃疾"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"辛弃疾（1140—1207），字幼安，号稼轩，历城（今山东济南）人，南宋豪放派词人，与苏轼并称“苏辛”，与李清照并称“济南二安”。\n生平经历：他出生时中原已被金人占领，二十一岁便组织义军抗金，曾率五十骑闯入敌营擒拿叛将，一时声名大振；南归后长期不受重用，只做过地方官职，多次上书陈述抗金方略都未被采纳；他先后闲居江西上饶、铅山近二十年，把报国无门的悲愤都写进词里，晚年虽再被起用，不久便抱憾辞世。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词是辛弃疾在建康任上中秋夜为友人吕叔潜所作。上片以「转金波」「飞镜重磨」写中秋明月，比喻新巧；「把酒问姮娥：被白发、欺人奈何」化用李白问月的意境，抒发功业未成、年华易老的苦闷。下片想象奇伟，「乘风好去，长空万里，直下看山河」境界开阔，寄托收复中原的壮志；结句「斫去桂婆娑，人道是、清光更多」用桂树遮蔽月光的传说，以「桂婆娑」喻把持朝政、阻碍抗金的投降派，借砍桂求光表达铲除奸佞、澄清天下的政治理想，寓意深曲。中考常考：结尾的象征义（托物言志）、想象与用典的手法、上下片由问月到言志的情感脉络。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"一轮秋影转金波，飞镜又重磨。","n":"","cn":"一轮秋月洒下金色的波光流转，像一面重新磨亮的飞镜挂在天上。","parts":[{"t":"一轮秋影转"},{"t":"金波","k":0},{"t":"，飞镜又"},{"t":"重","k":10},{"t":"磨。"}]},{"t":"把酒问姮娥：被白发、欺人奈何？","n":"","cn":"我端起酒杯询问嫦娥：被白发这样欺人，该怎么办呢？","parts":[{"t":"把酒问"},{"t":"姮娥","k":1},{"t":"："},{"t":"被","k":14},{"t":"白发、欺人奈何？"}]},{"t":"乘风好去，长空万里，直下看山河。","n":"","cn":"我要乘着长风飞去，在万里长空中，俯瞰祖国山河。","parts":[{"t":"乘风好去，长空万里，直下看山河。"}]},{"t":"斫去桂婆娑，人道是、清光更多。","n":"","cn":"砍去月中那株婆娑的桂树，人们说，这样洒下的清光会更多。","parts":[{"t":"斫","k":16},{"t":"去桂"},{"t":"婆娑","k":5},{"t":"，人道是、清光更多。"}]}],"words":[{"w":"金波","e":"【易错】「金波」的「波」是三点水，不要写成「坡」。"},{"w":"姮娥","e":"【易错】「姮娥」的「姮」左边是「女」，不要写成「恒娥」「嫦蛾」。"},{"w":"恒娥","e":"【易错】「姮娥」的「姮」左边是「女」，不要写成「恒娥」「嫦蛾」。"},{"w":"嫦蛾","e":"【易错】「姮娥」的「姮」左边是「女」，不要写成「恒娥」「嫦蛾」。"},{"w":"遭受","e":"【易错】「被白发欺人奈何」的「被」读 bèi，是「遭受」，不要写成「披」。"},{"w":"婆娑","e":"【易错】「婆娑」两字都是女字底，不要写成「娑婆」以外的「婆沙」。"},{"w":"娑婆","e":"【易错】「婆娑」两字都是女字底，不要写成「娑婆」以外的「婆沙」。"},{"w":"婆沙","e":"【易错】「婆娑」两字都是女字底，不要写成「娑婆」以外的「婆沙」。"},{"w":"波","e":"【易错】「金波」的「波」是三点水，不要写成「坡」。"},{"w":"坡","e":"【易错】「金波」的「波」是三点水，不要写成「坡」。"},{"w":"重","e":"【易错】「飞镜又重磨」的「重」读 chóng，是重新，不要写成「从」。"},{"w":"从","e":"【易错】「飞镜又重磨」的「重」读 chóng，是重新，不要写成「从」。"},{"w":"姮","e":"【易错】「姮娥」的「姮」左边是「女」，不要写成「恒娥」「嫦蛾」。"},{"w":"女","e":"【易错】「姮娥」的「姮」左边是「女」，不要写成「恒娥」「嫦蛾」。"},{"w":"被","e":"【易错】「被白发欺人奈何」的「被」读 bèi，是「遭受」，不要写成「披」。"},{"w":"披","e":"【易错】「被白发欺人奈何」的「被」读 bèi，是「遭受」，不要写成「披」。"},{"w":"斫","e":"【易错】「斫去桂婆娑」的「斫」是石字旁加「斤」，读 zhuó，不要写成「砍」「斫」以外的「折」。"},{"w":"斤","e":"【易错】「斫去桂婆娑」的「斫」是石字旁加「斤」，读 zhuó，不要写成「砍」「斫」以外的「折」。"},{"w":"砍","e":"【易错】「斫去桂婆娑」的「斫」是石字旁加「斤」，读 zhuó，不要写成「砍」「斫」以外的「折」。"},{"w":"折","e":"【易错】「斫去桂婆娑」的「斫」是石字旁加「斤」，读 zhuó，不要写成「砍」「斫」以外的「折」。"}]},{"type":"list","title":"名句","items":["斫去桂婆娑，人道是、清光更多。"]},{"type":"list","title":"背诵提示","items":["「金波」的「波」是三点水，不要写成「坡」。","「飞镜又重磨」的「重」读 chóng，是重新，不要写成「从」。","「姮娥」的「姮」左边是「女」，不要写成「恒娥」「嫦蛾」。","「被白发欺人奈何」的「被」读 bèi，是「遭受」，不要写成「披」。","「斫去桂婆娑」的「斫」是石字旁加「斤」，读 zhuó，不要写成「砍」「斫」以外的「折」。","「婆娑」两字都是女字底，不要写成「娑婆」以外的「婆沙」。"]}],"questions":[{"id":"p-p9b-tai-chang-yin-jian-kang-zhong-qiu-ye-wei-lv-shu-qian-fu-m0","type":"fill","stem":"默写填空：斫去桂婆娑，______。","answer":"人道是、清光更多。","explain":"出自《太常引·建康中秋夜为吕叔潜赋》（宋·辛弃疾）：斫去桂婆娑，人道是、清光更多。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-tai-chang-yin-jian-kang-zhong-qiu-ye-wei-lv-shu-qian-fu-u","type":"fill","stem":"理解性默写：一轮秋月洒下金色的波光流转，像一面重新磨亮的飞镜挂在天上。","answer":"一轮秋影转金波，飞镜又重磨。","explain":"出自《太常引·建康中秋夜为吕叔潜赋》（宋·辛弃疾）。句意：一轮秋月洒下金色的波光流转，像一面重新磨亮的飞镜挂在天上。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-huan-xi-sha-shen-xiang-yun-shan-na-pan-xing","title":"浣溪沙（身向云山那畔行）","subtitle":"清·纳兰性德","grade":"9b","tags":["边塞","羁旅","怀古"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"清·纳兰性德"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"纳兰性德（1655—1685），字容若，号楞伽山人，清代词人，满洲正黄旗人，大学士明珠的长子。\n生平经历：康熙十五年中进士，授一等侍卫，常随皇帝出巡塞外，见惯了关山风霜；他年仅三十一岁便病逝，却留下大量情真意切的词作。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词写边塞行役的凄清与历史的苍茫之感。上片写行进途中：身向云山、北风断马嘶，视听交错，一个「断」字既写风声之大，又暗含行程之苦；「深秋远塞若为情」直抒不堪之情。下片写所见之景，「一抹晚烟」「半竿斜日」以极简的笔触勾勒荒戍旧关的萧索，「一抹」「半竿」两个量词写尽苍凉，且与「荒」「旧」相应；结句「古今幽恨几时平」由眼前景物推及古今兴亡，把个人羁旅之愁升华为历史沧桑之叹，意境深远。中考常考：写景的画面与意境、「断」字的炼字效果、由景入情（以景结情）的写法及全词悲凉苍茫的情感基调。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"身向云山那畔行，北风吹断马嘶声，深秋远塞若为情。","n":"","cn":"我向着云山那边一路前行，北风把马的嘶鸣声都吹断了，深秋时节身处遥远的边塞，这情味叫人如何承受。","parts":[{"t":"身向云山那"},{"t":"畔","k":4},{"t":"行，北风吹断马"},{"t":"嘶","k":7},{"t":"声，深秋远塞"},{"t":"若为情","k":2},{"t":"。"}]},{"t":"一抹晚烟荒戍垒，半竿斜日旧关城。古今幽恨几时平。","n":"","cn":"一抹晚烟笼罩着荒凉破败的戍守营垒，半竿高的斜阳照在旧日的关城上；古往今来，这深沉的幽恨什么时候才能平息呢。","parts":[{"t":"一抹晚烟","k":0},{"t":"荒戍垒","k":3},{"t":"，"},{"t":"半竿斜日","k":1},{"t":"旧关城。古今幽恨几时平。"}]}],"words":[{"w":"一抹晚烟","e":"【易错】「一抹晚烟」的「抹」是提手旁，不要写成「沫」。"},{"w":"半竿斜日","e":"【易错】「半竿斜日」的「竿」是竹字头，不要写成「杆」。"},{"w":"若为情","e":"【易错】「若为情」的「若」是「怎堪、如何」，不要写成「苦」。"},{"w":"荒戍垒","e":"【易错】「荒戍垒」的「戍」不要写成「戌」「戊」；「垒」是三个「厶」下「土」，不要写成「磊」。"},{"w":"畔","e":"【易错】「云山那畔行」的「畔」是田字旁，不要写成「判」「叛」。"},{"w":"判","e":"【易错】「云山那畔行」的「畔」是田字旁，不要写成「判」「叛」。"},{"w":"叛","e":"【易错】「云山那畔行」的「畔」是田字旁，不要写成「判」「叛」。"},{"w":"嘶","e":"【易错】「北风吹断马嘶声」的「嘶」是口字旁，不要写成「撕」。"},{"w":"撕","e":"【易错】「北风吹断马嘶声」的「嘶」是口字旁，不要写成「撕」。"},{"w":"若","e":"【易错】「若为情」的「若」是「怎堪、如何」，不要写成「苦」。"},{"w":"苦","e":"【易错】「若为情」的「若」是「怎堪、如何」，不要写成「苦」。"},{"w":"抹","e":"【易错】「一抹晚烟」的「抹」是提手旁，不要写成「沫」。"},{"w":"沫","e":"【易错】「一抹晚烟」的「抹」是提手旁，不要写成「沫」。"},{"w":"戍","e":"【易错】「荒戍垒」的「戍」不要写成「戌」「戊」；「垒」是三个「厶」下「土」，不要写成「磊」。"},{"w":"戌","e":"【易错】「荒戍垒」的「戍」不要写成「戌」「戊」；「垒」是三个「厶」下「土」，不要写成「磊」。"},{"w":"戊","e":"【易错】「荒戍垒」的「戍」不要写成「戌」「戊」；「垒」是三个「厶」下「土」，不要写成「磊」。"},{"w":"垒","e":"【易错】「荒戍垒」的「戍」不要写成「戌」「戊」；「垒」是三个「厶」下「土」，不要写成「磊」。"},{"w":"厶","e":"【易错】「荒戍垒」的「戍」不要写成「戌」「戊」；「垒」是三个「厶」下「土」，不要写成「磊」。"},{"w":"土","e":"【易错】「荒戍垒」的「戍」不要写成「戌」「戊」；「垒」是三个「厶」下「土」，不要写成「磊」。"},{"w":"磊","e":"【易错】「荒戍垒」的「戍」不要写成「戌」「戊」；「垒」是三个「厶」下「土」，不要写成「磊」。"},{"w":"竿","e":"【易错】「半竿斜日」的「竿」是竹字头，不要写成「杆」。"},{"w":"杆","e":"【易错】「半竿斜日」的「竿」是竹字头，不要写成「杆」。"}]},{"type":"list","title":"名句","items":["一抹晚烟荒戍垒，半竿斜日旧关城。"]},{"type":"list","title":"背诵提示","items":["「云山那畔行」的「畔」是田字旁，不要写成「判」「叛」。","「北风吹断马嘶声」的「嘶」是口字旁，不要写成「撕」。","「若为情」的「若」是「怎堪、如何」，不要写成「苦」。","「一抹晚烟」的「抹」是提手旁，不要写成「沫」。","「荒戍垒」的「戍」不要写成「戌」「戊」；「垒」是三个「厶」下「土」，不要写成「磊」。","「半竿斜日」的「竿」是竹字头，不要写成「杆」。"]}],"questions":[{"id":"p-p9b-huan-xi-sha-shen-xiang-yun-shan-na-pan-xing-m0","type":"fill","stem":"默写填空：一抹晚烟荒戍垒，______。","answer":"半竿斜日旧关城。","explain":"出自《浣溪沙（身向云山那畔行）》（清·纳兰性德）：一抹晚烟荒戍垒，半竿斜日旧关城。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-huan-xi-sha-shen-xiang-yun-shan-na-pan-xing-u","type":"fill","stem":"理解性默写：我向着云山那边一路前行，北风把马的嘶鸣声都吹断了，深秋时节身处遥远的边塞，这情味叫人如何承受。","answer":"身向云山那畔行，北风吹断马嘶声，深秋远塞若为情。","explain":"出自《浣溪沙（身向云山那畔行）》（清·纳兰性德）。句意：我向着云山那边一路前行，北风把马的嘶鸣声都吹断了，深秋时节身处遥远的边塞，这情味叫人如何承受。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-yu-wo-suo-yu-ye","title":"鱼我所欲也","subtitle":"先秦·孟子","grade":"9b","tags":["文言文","议论","舍生取义"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·孟子"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"孟子（约前372—前289），名轲，字子舆，战国时期邹国（今山东邹城）人，儒家学派的代表人物，与孔子并称“孔孟”，后世尊为“亚圣”。\n生平经历：他幼年丧父，由母亲教养成人，相传“孟母三迁”“断机教子”讲的就是他幼时受教的故事；他师承子思一派，曾游说齐、宋、滕、魏等国，宣扬“仁政”“王道”，但当时诸侯忙于攻战，他的主张被视为迂阔而不被采纳；晚年退居乡里，与弟子一起著书立说。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文选自《孟子·告子上》，以「舍生取义」为中心论点，是孟子性善论与道德观的集中体现。开篇以「鱼」与「熊掌」设喻，引出「生」与「义」的抉择，得出「舍生而取义」的结论，比喻论证通俗有力；接着从正反两面推理，说明「所欲有甚于生」「所恶有甚于死者」，指出「非独贤者有是心也，人皆有之」；再用「不食嗟来之食」与「不辩礼义而受万钟」对比，批判见利忘义，归结为「失其本心」。中考常考：比喻论证与对比论证的作用、「本心」的含义、通假字（辟—避、辩—辨、得—德、乡—向）与古今异义（如「万钟」「加」「已」），以及「舍生取义」在今天的价值。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"鱼，我所欲也；熊掌，亦我所欲也。二者不可得兼，舍鱼而取熊掌者也。","n":"","cn":"鱼是我所喜爱的，熊掌也是我所喜爱的；如果两者不能同时得到，那就舍弃鱼而选取熊掌。","parts":[{"t":"鱼，我所欲也；熊掌，亦我所欲也。二者不可"},{"t":"得","k":5},{"t":"兼，舍鱼而取熊掌者也。"}]},{"t":"生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。","n":"","cn":"生命是我所喜爱的，道义也是我所喜爱的；如果两者不能同时得到，那就舍弃生命而选取道义。","parts":[{"t":"生，亦我所欲也；义，亦我所欲也。二者不可"},{"t":"得","k":5},{"t":"兼，舍生而取义者也。"}]},{"t":"生亦我所欲，所欲有甚于生者，故不为苟得也；死亦我所恶，所恶有甚于死者，故患有所不辟也。","n":"","cn":"生命是我所喜爱的，但我所喜爱的还有超过生命的，所以我不做苟且偷生的事；死亡是我所厌恶的，但我所厌恶的还有超过死亡的，所以有的祸患我不躲避。","parts":[{"t":"生亦我所欲，所欲有甚于生者，故不为苟"},{"t":"得","k":5},{"t":"也；死亦我"},{"t":"所恶","k":0},{"t":"，"},{"t":"所恶","k":0},{"t":"有甚于死者，故患有所不"},{"t":"辟","k":1},{"t":"也。"}]},{"t":"如使人之所欲莫甚于生，则凡可以得生者何不用也？","n":"","cn":"假如人们所喜爱的没有超过生命的，那么凡是可以保全生命的手段，有什么不能用呢？","parts":[{"t":"如使人之所欲莫甚于生，则凡可以"},{"t":"得","k":5},{"t":"生者何不用也？"}]},{"t":"使人之所恶莫甚于死者，则凡可以辟患者何不为也？","n":"","cn":"假如人们所厌恶的没有超过死亡的，那么凡是可以躲避祸患的事情，有什么不能做呢？","parts":[{"t":"使人之"},{"t":"所恶","k":0},{"t":"莫甚于死者，则凡可以"},{"t":"辟","k":1},{"t":"患者何不为也？"}]},{"t":"由是则生而有不用也，由是则可以辟患而有不为也。","n":"","cn":"由此可知，有的办法可以保全生命却不用，有的办法可以躲避祸患却不做。","parts":[{"t":"由是则生而有不用也，由是则可以"},{"t":"辟","k":1},{"t":"患而有不为也。"}]},{"t":"是故所欲有甚于生者，所恶有甚于死者。","n":"","cn":"所以，有比生命更值得喜爱的东西，有比死亡更令人厌恶的东西。","parts":[{"t":"是故所欲有甚于生者，"},{"t":"所恶","k":0},{"t":"有甚于死者。"}]},{"t":"非独贤者有是心也，人皆有之，贤者能勿丧耳。","n":"","cn":"不仅贤人有这种心，人人都有，只不过贤人能够不丧失它罢了。","parts":[{"t":"非独贤者有是心也，人皆有之，贤者能勿"},{"t":"丧","k":15},{"t":"耳。"}]},{"t":"一箪食，一豆羹，得之则生，弗得则死。","n":"","cn":"一竹筐饭，一碗汤，得到它就能活下去，得不到就会饿死。","parts":[{"t":"一"},{"t":"箪","k":9},{"t":"食，一豆"},{"t":"羹","k":10},{"t":"，"},{"t":"得","k":5},{"t":"之则生，弗"},{"t":"得","k":5},{"t":"则死。"}]},{"t":"呼尔而与之，行道之人弗受；蹴尔而与之，乞人不屑也。","n":"","cn":"没有礼貌地吆喝着给人吃，过路的饥饿之人不会接受；用脚踢着给人吃，乞丐也认为不值得一顾。","parts":[{"t":"呼尔而与之，行道之人弗受；"},{"t":"蹴","k":12},{"t":"尔而与之，乞人不屑也。"}]},{"t":"万钟则不辩礼义而受之，万钟于我何加焉！","n":"","cn":"可是有人对优厚的俸禄却不辨别是否合乎礼义就接受了，这优厚的俸禄对我有什么益处呢！","parts":[{"t":"万钟则不"},{"t":"辩","k":3},{"t":"礼义而受之，万钟于我何加焉！"}]},{"t":"为宫室之美，妻妾之奉，所识穷乏者得我与？","n":"","cn":"是为了住宅的华美、妻妾的侍奉，还是为了所认识的贫困的人感激我呢？","parts":[{"t":"为宫室之"},{"t":"美","k":11},{"t":"，妻妾之奉，所识穷乏者"},{"t":"得","k":5},{"t":"我与？"}]},{"t":"乡为身死而不受，今为宫室之美为之；","n":"","cn":"从前为了礼义，宁可死也不接受，如今却为了住宅的华美而接受了；","parts":[{"t":"乡","k":7},{"t":"为身死而不受，今为宫室之"},{"t":"美","k":11},{"t":"为之；"}]},{"t":"乡为身死而不受，今为妻妾之奉为之；","n":"","cn":"从前为了礼义，宁可死也不接受，如今却为了妻妾的侍奉而接受了；","parts":[{"t":"乡","k":7},{"t":"为身死而不受，今为妻妾之奉为之；"}]},{"t":"乡为身死而不受，今为所识穷乏者得我而为之：是亦不可以已乎？此之谓失其本心。","n":"","cn":"从前为了礼义，宁可死也不接受，如今却为了所认识的贫困的人感激自己而接受了：这种做法不是可以停止了吗？这就叫做丧失了他的本性。","parts":[{"t":"乡","k":7},{"t":"为身死而不受，今为所识穷乏者"},{"t":"得","k":5},{"t":"我而为之：是亦不可以已乎？此之谓失其本心。"}]}],"words":[{"w":"所恶","e":"【易错】「所恶」的「恶」读 wù，是厌恶，不要读成 è。"},{"w":"辟","e":"【易错】「故患有所不辟也」的「辟」通「避」，不要写成「避」。"},{"w":"避","e":"【易错】「故患有所不辟也」的「辟」通「避」，不要写成「避」。"},{"w":"辩","e":"【易错】「万钟则不辩礼义」的「辩」通「辨」，不要写成「辨」。"},{"w":"辨","e":"【易错】「万钟则不辩礼义」的「辩」通「辨」，不要写成「辨」。"},{"w":"得","e":"【易错】「所识穷乏者得我与」的「得」通「德」，是感恩之意。"},{"w":"德","e":"【易错】「所识穷乏者得我与」的「得」通「德」，是感恩之意。"},{"w":"乡","e":"【易错】「乡为身死而不受」的「乡」通「向」，从前之意，不要写成「向」。"},{"w":"向","e":"【易错】「乡为身死而不受」的「乡」通「向」，从前之意，不要写成「向」。"},{"w":"箪","e":"【易错】「一箪食，一豆羹」的「箪」是竹字头，「羹」下面是「美」，不要写错。"},{"w":"羹","e":"【易错】「一箪食，一豆羹」的「箪」是竹字头，「羹」下面是「美」，不要写错。"},{"w":"美","e":"【易错】「一箪食，一豆羹」的「箪」是竹字头，「羹」下面是「美」，不要写错。"},{"w":"蹴","e":"【易错】「蹴尔而与之」的「蹴」是足字旁，不要写成「就」。"},{"w":"就","e":"【易错】「蹴尔而与之」的「蹴」是足字旁，不要写成「就」。"},{"w":"恶","e":"【易错】「所恶」的「恶」读 wù，是厌恶，不要读成 è。"},{"w":"丧","e":"【易错】「贤者能勿丧耳」的「丧」读 sàng，不要写成「表」「哀」。"},{"w":"表","e":"【易错】「贤者能勿丧耳」的「丧」读 sàng，不要写成「表」「哀」。"},{"w":"哀","e":"【易错】「贤者能勿丧耳」的「丧」读 sàng，不要写成「表」「哀」。"}]},{"type":"list","title":"名句","items":["生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。"]},{"type":"list","title":"背诵提示","items":["「故患有所不辟也」的「辟」通「避」，不要写成「避」。","「万钟则不辩礼义」的「辩」通「辨」，不要写成「辨」。","「所识穷乏者得我与」的「得」通「德」，是感恩之意。","「乡为身死而不受」的「乡」通「向」，从前之意，不要写成「向」。","「一箪食，一豆羹」的「箪」是竹字头，「羹」下面是「美」，不要写错。","「蹴尔而与之」的「蹴」是足字旁，不要写成「就」。","「所恶」的「恶」读 wù，是厌恶，不要读成 è。","「贤者能勿丧耳」的「丧」读 sàng，不要写成「表」「哀」。"]}],"questions":[{"id":"p-p9b-yu-wo-suo-yu-ye-m0","type":"fill","stem":"默写填空：生，______。","answer":"亦我所欲也。","explain":"出自《鱼我所欲也》（先秦·孟子）：生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-yu-wo-suo-yu-ye-u","type":"fill","stem":"理解性默写：鱼是我所喜爱的，熊掌也是我所喜爱的；如果两者不能同时得到，那就舍弃鱼而选取熊掌。","answer":"鱼，我所欲也；熊掌，亦我所欲也。二者不可得兼，舍鱼而取熊掌者也。","explain":"出自《鱼我所欲也》（先秦·孟子）。句意：鱼是我所喜爱的，熊掌也是我所喜爱的；如果两者不能同时得到，那就舍弃鱼而选取熊掌。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-tang-ju-bu-ru-shi-ming","title":"唐雎不辱使命","subtitle":"西汉·刘向","grade":"9b","tags":["文言文","叙事","不畏强暴"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"西汉·刘向"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"刘向（约前77—前6），字子政，原名更生，西汉沛人，汉皇族楚元王刘交的后代，经学家、目录学家、文学家；他历任光禄大夫、中垒校尉等职，长期主持校理皇家藏书，撰有我国第一部目录学著作《别录》，是目录学与校雠学的奠基人之一。\n成书背景：《战国策》所收本是战国时期各国史官与策士辑录的资料汇编，名称不一，有《国策》《国事》《短长》《事语》《长书》《修书》等；西汉末年刘向奉诏整理宫廷藏书，把这类材料分别部居、删繁去重，按东周、西周、秦、齐、楚、赵、魏、韩、燕、宋卫、中山十二国次序编排成三十三篇，并定名为《战国策》。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文选自《战国策·魏策四》，记叙唐雎奉安陵君之命出使秦国、以无畏的胆气和机智的言辞折服秦王、保全国土的故事。文章最突出的成就是人物刻画：秦王先以「易地」相诱，继以「灭韩亡魏」相胁，再以「天子之怒」相吓，而唐雎从容应对，先以「岂直五百里哉」反问，再以「布衣之怒」反驳，最后「挺剑而起」，以「伏尸二人，流血五步」相抗，凛然不可侵犯；人物的语言与动作（怫然怒、色挠、长跪而谢）前后对比，突显唐雎不畏强暴、有胆有识的爱国形象。中考常考：对话描写与对比衬托的手法、秦王与唐雎的形象分析、三个典故（专诸、聂政、要离）的作用，以及「错意」「广」「逆」「直」「挠」等词义。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"秦王使人谓安陵君曰：“寡人欲以五百里之地易安陵，安陵君其许寡人！”","n":"","cn":"秦王派人对安陵君说：“我想用五百里的土地交换安陵，安陵君可要答应我！”","parts":[{"t":"秦王使人谓安陵君曰：“寡人欲以五百里之地"},{"t":"易安陵","k":9},{"t":"，安陵君其许寡人！”"}]},{"t":"安陵君曰：“大王加惠，以大易小，甚善；虽然，受地于先王，愿终守之，弗敢易！”","n":"安陵君说：“大王给予恩惠，用大的换小的，很好；虽然如此，我从先王那里继承了这块封地，愿意永远守住它，不敢交换！”","cn":"","parts":[{"t":"安陵君曰：“大王加惠，以大"},{"t":"易","k":12},{"t":"小，甚善；虽然，受地于先王，愿终守之，弗敢"},{"t":"易","k":12},{"t":"！”"}]},{"t":"秦王不悦。安陵君因使唐雎使于秦。","n":"","cn":"秦王很不高兴。安陵君于是派唐雎出使到秦国去。","parts":[{"t":"秦王不悦。安陵君因使唐雎使于秦。"}]},{"t":"秦王谓唐雎曰：“寡人以五百里之地易安陵，安陵君不听寡人，何也？且秦灭韩亡魏，而君以五十里之地存者，以君为长者，故不错意也。今吾以十倍之地，请广于君，而君逆寡人者，轻寡人与？”","n":"秦王对唐雎说：“我用五百里的土地交换安陵，安陵君不听从我，为什么呢？况且秦国灭掉韩国、魏国，而安陵君凭着五十里的地方保存下来，是因为我把安陵君看作忠厚长者，所以不放在心上。如今我用十倍的土地，让安陵君扩大领土，可他违抗我，是轻视我吗？”","cn":"","parts":[{"t":"秦王谓唐雎曰：“寡人以五百里之地"},{"t":"易安陵","k":9},{"t":"，安陵君不听寡人，何也？且秦灭韩亡魏，而君以五十里之地存者，以君为长者，故不"},{"t":"错","k":13},{"t":"意也。今吾以十倍之地，"},{"t":"请广于君","k":3},{"t":"，而君逆寡人者，轻寡人与？”"}]},{"t":"唐雎对曰：“否，非若是也。安陵君受地于先王而守之，虽千里不敢易也，岂直五百里哉？”","n":"唐雎回答说：“不，不是这样的。安陵君从先王那里承受封地而守护它，即使是千里之地也不敢交换，哪里只是五百里呢？”","cn":"","parts":[{"t":"唐雎对曰：“否，非若是也。安陵君受地于先王而守之，虽千里不敢"},{"t":"易","k":12},{"t":"也，岂直五百里哉？”"}]},{"t":"秦王怫然怒，谓唐雎曰：“公亦尝闻天子之怒乎？”","n":"","cn":"秦王勃然大怒，对唐雎说：“你也曾听说过天子发怒吗？”","parts":[{"t":"秦王"},{"t":"怫","k":16},{"t":"然怒，谓唐雎曰：“公亦尝闻天子之怒乎？”"}]},{"t":"唐雎对曰：“臣未尝闻也。”","n":"唐雎回答说：“我没有听说过。”","cn":"","parts":[{"t":"唐雎对曰：“臣未尝闻也。”"}]},{"t":"秦王曰：“天子之怒，伏尸百万，流血千里。”","n":"秦王说：“天子发怒，将使百万尸体倒下，血流千里。”","cn":"","parts":[{"t":"秦王曰：“天子之怒，"},{"t":"伏尸百万","k":4},{"t":"，流血千里。”"}]},{"t":"唐雎曰：“大王尝闻布衣之怒乎？”","n":"唐雎说：“大王曾听说过平民发怒吗？”","cn":"","parts":[{"t":"唐雎曰：“大王尝闻布衣之怒乎？”"}]},{"t":"唐雎曰：“此庸夫之怒也，非士之怒也。夫专诸之刺王僚也，彗星袭月；聂政之刺韩傀也，白虹贯日；要离之刺庆忌也，仓鹰击于殿上。此三子者，皆布衣之士也，怀怒未发，休祲降于天，与臣而将四矣。若士必怒，伏尸二人，流血五步，天下缟素，今日是也。”挺剑而起。","n":"唐雎说：“这是平庸无能的人发怒，不是有胆识的人发怒。专诸刺杀王僚时，彗星的光芒扫过月亮；聂政刺杀韩傀时，一道白虹直冲太阳；要离刺杀庆忌时，苍鹰扑击在宫殿上。这三个人都是平民中有胆识的人，心里的愤怒还没发作出来，上天就降下征兆，现在加上我将成为四个人了。如果有胆识的人一定要发怒，那么将有两具尸体倒下，血流五步，天下的人都穿白戴孝，今天就是这样。”说着拔出宝剑站了起来。","cn":"","parts":[{"t":"唐雎曰：“此庸夫之怒也，非士之怒也。夫专诸之刺王僚也，彗星袭月；聂政之刺韩"},{"t":"傀","k":21},{"t":"也，白虹贯日；要离之刺庆忌也，"},{"t":"仓","k":24},{"t":"鹰击于殿上。此三子者，皆布衣之士也，怀怒未发，休"},{"t":"祲","k":26},{"t":"降于天，与臣而将四矣。若士必怒，"},{"t":"伏","k":19},{"t":"尸二人，流血五步，"},{"t":"天下缟素","k":5},{"t":"，今日是也。”挺剑而起。"}]},{"t":"秦王色挠，长跪而谢之曰：“先生坐！何至于此！寡人谕矣：夫韩、魏灭亡，而安陵以五十里之地存者，徒以有先生也。”","n":"","cn":"秦王变了脸色，直身而跪向唐雎道歉说：“先生请坐！怎么会到这种地步！我明白了：韩国、魏国灭亡，而安陵却凭着五十里的地方保全下来，只是因为有先生您啊。”","parts":[{"t":"秦王色挠","k":6},{"t":"，长跪而谢之曰：“先生坐！何至于此！寡人谕矣：夫韩、魏灭亡，而安陵以五十里之地存者，徒以有先生也。”"}]}],"words":[{"w":"秦王对唐雎说","e":"“我用五百里的土地交换安陵，安陵君不听从我，为什么呢？况且秦国灭掉韩国、魏国，而安陵君凭着五十里的地方保存下来，是因为我把安陵君看作忠厚长者，所以不放在心上"},{"w":"唐雎回答说","e":"“不，不是这样的"},{"w":"安陵君说","e":"“大王给予恩惠，用大的换小的，很好"},{"w":"请广于君","e":"【易错】「请广于君」的「广」是形容词用作动词，扩大领土。"},{"w":"伏尸百万","e":"【易错】「伏尸百万」的「伏」是单人旁，不要写成「服」。"},{"w":"天下缟素","e":"【易错】「天下缟素」的「缟」是绞丝旁，指白色丧服，不要写成「稿」「嗥」。"},{"w":"秦王色挠","e":"【易错】「秦王色挠」的「挠」是提手旁，是「屈服」之意，不要写成「饶」「绕」。"},{"w":"秦王说","e":"“天子发怒，将使百万尸体倒下，血流千里"},{"w":"唐雎说","e":"“大王曾听说过平民发怒吗？”"},{"w":"易安陵","e":"【易错】「易安陵」的「易」是交换，不要理解为「容易」。"},{"w":"容易","e":"【易错】「易安陵」的「易」是交换，不要理解为「容易」。"},{"w":"屈服","e":"【易错】「秦王色挠」的「挠」是提手旁，是「屈服」之意，不要写成「饶」「绕」。"},{"w":"易","e":"【易错】「易安陵」的「易」是交换，不要理解为「容易」。"},{"w":"错","e":"【易错】「故不错意也」的「错」通「措」，是安放、施行之意，不要写成「措」。"},{"w":"措","e":"【易错】「故不错意也」的「错」通「措」，是安放、施行之意，不要写成「措」。"},{"w":"广","e":"【易错】「请广于君」的「广」是形容词用作动词，扩大领土。"},{"w":"怫","e":"【易错】「秦王怫然怒」的「怫」是竖心旁，读 fú，不要写成「佛」「拂」。"},{"w":"佛","e":"【易错】「秦王怫然怒」的「怫」是竖心旁，读 fú，不要写成「佛」「拂」。"},{"w":"拂","e":"【易错】「秦王怫然怒」的「怫」是竖心旁，读 fú，不要写成「佛」「拂」。"},{"w":"伏","e":"【易错】「伏尸百万」的「伏」是单人旁，不要写成「服」。"},{"w":"服","e":"【易错】「伏尸百万」的「伏」是单人旁，不要写成「服」。"},{"w":"傀","e":"【易错】「聂政之刺韩傀也」的「傀」是单人旁，不要写成「隗」「魅」。"},{"w":"隗","e":"【易错】「聂政之刺韩傀也」的「傀」是单人旁，不要写成「隗」「魅」。"},{"w":"魅","e":"【易错】「聂政之刺韩傀也」的「傀」是单人旁，不要写成「隗」「魅」。"},{"w":"仓","e":"【易错】「仓鹰击于殿上」的「仓」通「苍」，不要写成「苍」。"},{"w":"苍","e":"【易错】「仓鹰击于殿上」的「仓」通「苍」，不要写成「苍」。"},{"w":"祲","e":"【易错】「休祲降于天」的「祲」是示字旁，读 jìn，不要写成「侵」。"},{"w":"侵","e":"【易错】「休祲降于天」的「祲」是示字旁，读 jìn，不要写成「侵」。"},{"w":"缟","e":"【易错】「天下缟素」的「缟」是绞丝旁，指白色丧服，不要写成「稿」「嗥」。"},{"w":"稿","e":"【易错】「天下缟素」的「缟」是绞丝旁，指白色丧服，不要写成「稿」「嗥」。"},{"w":"嗥","e":"【易错】「天下缟素」的「缟」是绞丝旁，指白色丧服，不要写成「稿」「嗥」。"},{"w":"挠","e":"【易错】「秦王色挠」的「挠」是提手旁，是「屈服」之意，不要写成「饶」「绕」。"},{"w":"饶","e":"【易错】「秦王色挠」的「挠」是提手旁，是「屈服」之意，不要写成「饶」「绕」。"},{"w":"绕","e":"【易错】「秦王色挠」的「挠」是提手旁，是「屈服」之意，不要写成「饶」「绕」。"}]},{"type":"h","text":"译文"},{"type":"p","text":"秦王派人对安陵君说：“我想用五百里土地换安陵，安陵君可要答应我！”安陵君说：“大王施恩，以大换小，很好；虽如此，我从先王那里继承封地，愿永远守着它，不敢交换！”秦王不高兴，安陵君便派唐雎出使秦国。秦王对唐雎说：“我用五百里换安陵，安陵君不听，为什么？秦已灭韩亡魏，安陵君凭五十里地存留下来，是我把他看作长者，才不打他的主意。如今我用十倍之地请他扩地，他却违抗我，是轻视我吗？”唐雎答：“不，不是这样。安陵君受地于先王而守护它，虽千里也不敢换，岂止五百里！”秦王勃然大怒：“你听说过天子发怒吗？”唐雎答：“没听说过。”秦王说：“天子发怒，伏尸百万，流血千里。”唐雎说：“大王听说过百姓发怒吗？”唐雎说：“这是庸人发怒，不是志士发怒。专诸刺王僚，彗星袭月；聂政刺韩傀，白虹贯日；要离刺庆忌，苍鹰击殿。这三人都是布衣之士，怒气未发，上天先降征兆；加上我将是第四个。若志士必怒，则伏尸二人、流血五步，天下缟素，今天就是这样！”拔剑而起。秦王变了脸色，长跪道歉：“先生请坐！何至于此！我明白了：韩魏灭亡而安陵以五十里存者，只因为有先生啊。”"},{"type":"list","title":"名句","items":["若士必怒，伏尸二人，流血五步，天下缟素，今日是也。"]},{"type":"list","title":"背诵提示","items":["「易安陵」的「易」是交换，不要理解为「容易」。","「故不错意也」的「错」通「措」，是安放、施行之意，不要写成「措」。","「请广于君」的「广」是形容词用作动词，扩大领土。","「秦王怫然怒」的「怫」是竖心旁，读 fú，不要写成「佛」「拂」。","「伏尸百万」的「伏」是单人旁，不要写成「服」。","「聂政之刺韩傀也」的「傀」是单人旁，不要写成「隗」「魅」。","「仓鹰击于殿上」的「仓」通「苍」，不要写成「苍」。","「休祲降于天」的「祲」是示字旁，读 jìn，不要写成「侵」。","「天下缟素」的「缟」是绞丝旁，指白色丧服，不要写成「稿」「嗥」。","「秦王色挠」的「挠」是提手旁，是「屈服」之意，不要写成「饶」「绕」。"]}],"questions":[{"id":"p-p9b-tang-ju-bu-ru-shi-ming-m0","type":"fill","stem":"默写填空：若士必怒，______。","answer":"伏尸二人。","explain":"出自《唐雎不辱使命》（西汉·刘向）：若士必怒，伏尸二人，流血五步，天下缟素，今日是也。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-tang-ju-bu-ru-shi-ming-u","type":"fill","stem":"理解性默写：秦王派人对安陵君说：我想用五百里的土地交换安陵，安陵君可要答应我！","answer":"秦王使人谓安陵君曰：“寡人欲以五百里之地易安陵，安陵君其许寡人！”","explain":"出自《唐雎不辱使命》（西汉·刘向）。句意：秦王派人对安陵君说：“我想用五百里的土地交换安陵，安陵君可要答应我！”","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-song-dong-yang-ma-sheng-xu","title":"送东阳马生序","subtitle":"明·宋濂","grade":"9b","tags":["文言文","劝学","对比"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"明·宋濂"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"宋濂（1310—1381），字景濂，号潜溪，浦江（今属浙江）人，明初文学家、史学家。他学识渊博，被明太祖朱元璋称为“开国文臣之首”，与刘基、高启并称“明初诗文三大家”；官至翰林学士承旨、知制诰，曾主持修撰《元史》，死后谥号文宪。\n生平经历：他幼时家境贫寒而酷爱读书，常向有书人家借书亲手抄录，即使“天大寒，砚冰坚，手指不可屈伸”也不懈怠；成年后曾远行百里向名师求教，态度谦恭；入明后深受朱元璋器重，参与制定典章制度，并曾为太子讲经；洪武十三年（1380）因长孙被牵入胡惟庸案而获罪，贬谪途中于夔州去世。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文是宋濂写给同乡后学马君则的赠序。作者以现身说法的方式，依次叙述自己幼时借书抄书之难、成年求师叩问之艰、负箧远行受冻之苦，再与太学生们衣食无忧、书籍齐备、名师在侧的条件作对比，得出「其业有不精、德有不成者，非天质之卑，则心不若余之专耳」的结论，最后勉励马生勤奋学习。文章以记叙为主而寓议论，细节描写（砚冰坚、足肤皲裂、四支僵劲）真切感人，对比手法贯穿全篇，语言质朴恳切。中考常考：对比手法的作用、细节描写与作者勤学精神的概括，以及「嗜」「假借」「援疑质理」「叱咄」「俟」「汤」等词义与通假字（支—肢）。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"余幼时即嗜学。家贫，无从致书以观，每假借于藏书之家，手自笔录，计日以还。","n":"","cn":"我小时候就酷爱读书。家里穷，没有办法买书来看，常常向藏书的人家借，亲手用笔抄录，计算着日子按时归还。","parts":[{"t":"余幼时即"},{"t":"嗜","k":12},{"t":"学。家贫，无从致书以观，每假借于藏书之家，手自笔录，计日以还。"}]},{"t":"天大寒，砚冰坚，手指不可屈伸，弗之怠。","n":"","cn":"天气非常寒冷，砚台里的墨水结成坚冰，手指冻得不能弯曲伸直，也不懈怠（抄书）。","parts":[{"t":"天大寒，"},{"t":"砚冰坚","k":4},{"t":"，手指不可屈伸，"},{"t":"弗之怠","k":5},{"t":"。"}]},{"t":"录毕，走送之，不敢稍逾约。以是人多以书假余，余因得遍观群书。","n":"","cn":"抄完后，赶紧跑去送还，不敢稍微超过约定的期限。因此人们大多愿意把书借给我，我也因此能够读遍各种书籍。","parts":[{"t":"录毕，"},{"t":"走送之","k":6},{"t":"，不敢稍逾约。以是人多以书假余，余因得遍观群书。"}]},{"t":"既加冠，益慕圣贤之道。又患无硕师名人与游，尝趋百里外，从乡之先达执经叩问。","n":"","cn":"成年以后，我更加仰慕圣贤的学说。又担心没有学问渊博的老师和名人可以交往请教，曾经跑到百里之外，拿着经书向当地有学问的前辈请教。","parts":[{"t":"既加冠","k":7},{"t":"，益慕圣贤之道。又患无硕师名人与游，尝趋百里外，从乡之先达执经叩问。"}]},{"t":"先达德隆望尊，门人弟子填其室，未尝稍降辞色。","n":"","cn":"那位前辈德高望重，门人学生挤满了他的屋子，他从不曾把言辞和脸色放温和些。","parts":[{"t":"先达德隆望尊，门人弟子填其室，未尝稍降辞色。"}]},{"t":"余立侍左右，援疑质理，俯身倾耳以请；","n":"","cn":"我站在他身边侍候，提出疑难，询问道理，弯下身子侧着耳朵请教；","parts":[{"t":"余立侍左右，援疑质理，俯身倾耳以请；"}]},{"t":"或遇其叱咄，色愈恭，礼愈至，不敢出一言以复；","n":"","cn":"有时遇到他训斥呵责，我的表情更加恭敬，礼节更加周到，不敢多说一句辩解的话；","parts":[{"t":"或遇其"},{"t":"叱咄","k":8},{"t":"，色愈恭，礼愈至，不敢出一言以复；"}]},{"t":"俟其欣悦，则又请焉。故余虽愚，卒获有所闻。","n":"","cn":"等到他高兴了，就再去请教。所以我虽然愚笨，最终还是有所收获。","parts":[{"t":"俟其欣悦，则又请焉。故余虽愚，卒获有所闻。"}]},{"t":"当余之从师也，负箧曳屣行深山巨谷中，穷冬烈风，大雪深数尺，足肤皲裂而不知。","n":"","cn":"当我外出求师的时候，背着书箱、拖着鞋子走在深山大谷之中，隆冬寒风凛冽，大雪深达数尺，脚上的皮肤冻裂了都不知道。","parts":[{"t":"当余之从师也，"},{"t":"负箧曳屣","k":0},{"t":"行深山巨谷中，穷冬烈风，大雪深数尺，"},{"t":"足肤皲裂","k":2},{"t":"而不知。"}]},{"t":"至舍，四支僵劲不能动，媵人持汤沃灌，以衾拥覆，久而乃和。","n":"","cn":"到了学舍，四肢冻得僵硬不能动弹，服侍的人拿来热水浇洗，用被子围盖住我，很久才暖和过来。","parts":[{"t":"至舍，"},{"t":"四支僵劲","k":3},{"t":"不能动，"},{"t":"媵","k":29},{"t":"人持"},{"t":"汤","k":30},{"t":"沃灌，以衾拥覆，久而乃和。"}]}],"words":[{"w":"负箧曳屣","e":"【易错】「负箧曳屣」的「箧」是竹字头，「屣」是尸字头，不要写成「负箧曳履」。"},{"w":"负箧曳履","e":"【易错】「负箧曳屣」的「箧」是竹字头，「屣」是尸字头，不要写成「负箧曳履」。"},{"w":"足肤皲裂","e":"【易错】「足肤皲裂」的「皲」是「军」加「皮」，不要写成「龟裂」。"},{"w":"四支僵劲","e":"【易错】「四支僵劲」的「支」通「肢」，不要写成「肢」。"},{"w":"砚冰坚","e":"【易错】「砚冰坚」的「砚」是石字旁，不要写成「现」。"},{"w":"弗之怠","e":"【易错】「弗之怠」的「怠」是心字底，不要写成「殆」；这是宾语前置句，语序不要写错。"},{"w":"走送之","e":"【易错】「走送之」的「走」是「跑」，不要按现代义理解。"},{"w":"既加冠","e":"【易错】「既加冠」的「冠」读 guān，指二十岁行冠礼。"},{"w":"叱咄","e":"【易错】「叱咄」两字都是口字旁，不要写成「斥咄」「叱拙」。"},{"w":"斥咄","e":"【易错】「叱咄」两字都是口字旁，不要写成「斥咄」「叱拙」。"},{"w":"叱拙","e":"【易错】「叱咄」两字都是口字旁，不要写成「斥咄」「叱拙」。"},{"w":"龟裂","e":"【易错】「足肤皲裂」的「皲」是「军」加「皮」，不要写成「龟裂」。"},{"w":"嗜","e":"【易错】「余幼时即嗜学」的「嗜」是口字旁，不要写成「耆」「奢」。"},{"w":"耆","e":"【易错】「余幼时即嗜学」的「嗜」是口字旁，不要写成「耆」「奢」。"},{"w":"奢","e":"【易错】「余幼时即嗜学」的「嗜」是口字旁，不要写成「耆」「奢」。"},{"w":"砚","e":"【易错】「砚冰坚」的「砚」是石字旁，不要写成「现」。"},{"w":"现","e":"【易错】「砚冰坚」的「砚」是石字旁，不要写成「现」。"},{"w":"怠","e":"【易错】「弗之怠」的「怠」是心字底，不要写成「殆」；这是宾语前置句，语序不要写错。"},{"w":"殆","e":"【易错】「弗之怠」的「怠」是心字底，不要写成「殆」；这是宾语前置句，语序不要写错。"},{"w":"走","e":"【易错】「走送之」的「走」是「跑」，不要按现代义理解。"},{"w":"跑","e":"【易错】「走送之」的「走」是「跑」，不要按现代义理解。"},{"w":"冠","e":"【易错】「既加冠」的「冠」读 guān，指二十岁行冠礼。"},{"w":"箧","e":"【易错】「负箧曳屣」的「箧」是竹字头，「屣」是尸字头，不要写成「负箧曳履」。"},{"w":"屣","e":"【易错】「负箧曳屣」的「箧」是竹字头，「屣」是尸字头，不要写成「负箧曳履」。"},{"w":"皲","e":"【易错】「足肤皲裂」的「皲」是「军」加「皮」，不要写成「龟裂」。"},{"w":"军","e":"【易错】「足肤皲裂」的「皲」是「军」加「皮」，不要写成「龟裂」。"},{"w":"皮","e":"【易错】「足肤皲裂」的「皲」是「军」加「皮」，不要写成「龟裂」。"},{"w":"支","e":"【易错】「四支僵劲」的「支」通「肢」，不要写成「肢」。"},{"w":"肢","e":"【易错】「四支僵劲」的「支」通「肢」，不要写成「肢」。"},{"w":"媵","e":"【易错】「媵人持汤沃灌」的「媵」是月字旁，「汤」指热水，不要理解为汤汁。"},{"w":"汤","e":"【易错】「媵人持汤沃灌」的「媵」是月字旁，「汤」指热水，不要理解为汤汁。"}]},{"type":"list","title":"名句","items":["余立侍左右，援疑质理，俯身倾耳以请。"]},{"type":"list","title":"背诵提示","items":["「余幼时即嗜学」的「嗜」是口字旁，不要写成「耆」「奢」。","「砚冰坚」的「砚」是石字旁，不要写成「现」。","「弗之怠」的「怠」是心字底，不要写成「殆」；这是宾语前置句，语序不要写错。","「走送之」的「走」是「跑」，不要按现代义理解。","「既加冠」的「冠」读 guān，指二十岁行冠礼。","「叱咄」两字都是口字旁，不要写成「斥咄」「叱拙」。","「负箧曳屣」的「箧」是竹字头，「屣」是尸字头，不要写成「负箧曳履」。","「足肤皲裂」的「皲」是「军」加「皮」，不要写成「龟裂」。","「四支僵劲」的「支」通「肢」，不要写成「肢」。","「媵人持汤沃灌」的「媵」是月字旁，「汤」指热水，不要理解为汤汁。"]}],"questions":[{"id":"p-p9b-song-dong-yang-ma-sheng-xu-m0","type":"fill","stem":"默写填空：余立侍左右，______。","answer":"援疑质理。","explain":"出自《送东阳马生序》（明·宋濂）：余立侍左右，援疑质理，俯身倾耳以请。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-song-dong-yang-ma-sheng-xu-u","type":"fill","stem":"理解性默写：我小时候就酷爱读书。家里穷，没有办法买书来看，常常向藏书的人家借，亲手用笔抄录，计算着日子按时归还。","answer":"余幼时即嗜学。家贫，无从致书以观，每假借于藏书之家，手自笔录，计日以还。","explain":"出自《送东阳马生序》（明·宋濂）。句意：我小时候就酷爱读书。家里穷，没有办法买书来看，常常向藏书的人家借，亲手用笔抄录，计算着日子按时归还。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-cao-gui-lun-zhan","title":"曹刿论战","subtitle":"先秦·左丘明","grade":"9a","tags":["文言文","叙事","军事"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·左丘明"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"左丘明，春秋时期鲁国人，相传曾为鲁国史官；司马迁在《史记》中说“左丘失明，厥有《国语》”，后世多把他视为《左传》的作者。他是我国古代重要的史学家，其名与《左传》始终连在一起。\n成书背景：《左传》又称《春秋左氏传》《左氏春秋》，相传为左丘明解释《春秋》而作，是我国第一部叙事详备的编年体史书，记事大体起于鲁隐公元年，止于鲁哀公二十七年；它与《公羊传》《谷梁传》合称“春秋三传”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文选自《左传·庄公十年》，记齐鲁长勺之战，重点不在写战争过程，而在「论战」，通过战前准备与战后分析的对话，塑造了曹刿深谋远虑、有政治远见与军事才能的形象。文章以「远谋」二字为眼：战前论「何以战」，指出取信于民是战争取胜的政治基础；战时以「未可」「可矣」的简省描写表现其沉着与把握战机；战后「一鼓作气」的精辟分析揭示以逸待劳、后发制人的军事思想。写法上详略得当，对话为主，对比鲜明（曹刿的远谋与乡人的漠然、鲁庄公的浅陋）。中考常考：详略安排与详略的原因、「肉食者鄙」「一鼓作气」等语句的理解、人物形象分析及「何以战」的宾语前置句式。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"十年春，齐师伐我。公将战，曹刿请见。","n":"","cn":"鲁庄公十年的春天，齐国的军队攻打我们鲁国。庄公准备迎战，曹刿请求进见。","parts":[{"t":"十年春，"},{"t":"齐师伐我","k":2},{"t":"。公将战，曹刿请见。"}]},{"t":"其乡人曰：“肉食者谋之，又何间焉？”","n":"他的同乡人说：“当权的人自会谋划这件事，你又何必参与呢？”","cn":"","parts":[{"t":"其乡人曰：“肉食者谋之，"},{"t":"又何间焉","k":3},{"t":"？”"}]},{"t":"刿曰：“肉食者鄙，未能远谋。”乃入见。","n":"曹刿说：“当权的人目光短浅，不能深谋远虑。”于是入朝进见庄公。","cn":"","parts":[{"t":"刿曰：“"},{"t":"肉食者鄙","k":4},{"t":"，未能远谋。”乃入见。"}]},{"t":"问：“何以战？”公曰：“衣食所安，弗敢专也，必以分人。”","n":"曹刿问：“凭什么作战？”庄公说：“衣食这类养生的东西，我不敢独自享用，一定把它分给别人。”","cn":"","parts":[{"t":"问：“何以战？”公曰：“衣食所安，弗敢专也，必以分人。”"}]},{"t":"对曰：“小惠未遍，民弗从也。”","n":"曹刿回答说：“这种小恩小惠不能遍及百姓，百姓不会听从您的。”","cn":"","parts":[{"t":"对曰：“"},{"t":"小惠未遍","k":5},{"t":"，民弗从也。”"}]},{"t":"公曰：“牺牲玉帛，弗敢加也，必以信。”","n":"庄公说：“祭祀用的猪牛羊、玉器和丝织品，我从来不敢虚报数目，一定要做到诚实可信。”","cn":"","parts":[{"t":"公曰：“"},{"t":"牺牲玉帛","k":6},{"t":"，弗敢加也，必以信。”"}]},{"t":"对曰：“小信未孚，神弗福也。”","n":"曹刿回答说：“小的信用未能使神信任，神是不会保佑您的。”","cn":"","parts":[{"t":"对曰：“"},{"t":"小信未孚","k":7},{"t":"，神弗福也。”"}]},{"t":"公曰：“小大之狱，虽不能察，必以情。”","n":"庄公说：“大大小小的案件，虽然不能一一明察，但一定根据实情合理裁决。”","cn":"","parts":[{"t":"公曰：“"},{"t":"小大之狱","k":9},{"t":"，虽不能察，必以情。”"}]},{"t":"对曰：“忠之属也。可以一战。战则请从。”","n":"曹刿回答说：“这是尽了职分之内的事。可以凭这个条件打一仗。如果作战，请允许我跟随您。”","cn":"","parts":[{"t":"对曰：“忠之属也。可以一战。战则请从。”"}]},{"t":"公与之乘，战于长勺。公将鼓之。","n":"","cn":"庄公和他同乘一辆战车，在长勺交战。庄公将要击鼓进军。","parts":[{"t":"公与之乘","k":10},{"t":"，战于长勺。公将鼓之。"}]},{"t":"刿曰：“未可。”齐人三鼓。","n":"曹刿说：“不可以。”齐军三次击鼓进军。","cn":"","parts":[{"t":"刿曰：“未可。”齐人三鼓。"}]},{"t":"刿曰：“可矣。”齐师败绩。","n":"曹刿说：“可以了。”齐军大败。","cn":"","parts":[{"t":"刿曰：“可矣。”"},{"t":"齐师败绩","k":11},{"t":"。"}]},{"t":"既克，公问其故。","n":"","cn":"战胜齐军以后，庄公问他取胜的缘故。","parts":[{"t":"既克，公问其故。"}]},{"t":"对曰：“夫战，勇气也。一鼓作气，再而衰，三而竭。彼竭我盈，故克之。夫大国，难测也，惧有伏焉。吾视其辙乱，望其旗靡，故逐之。”","n":"曹刿回答说：“作战，靠的是勇气。第一次击鼓能振作士气，第二次击鼓士气就衰减了，第三次击鼓士气就耗尽了。对方的士气耗尽而我方的士气正旺盛，所以打败了他们。大国，难以推测，怕有埋伏。我看到他们的车轮印混乱，望见他们的旗帜倒下了，所以追击他们。”","cn":"","parts":[{"t":"对曰：“夫战，勇气也。一鼓作气，再而衰，三而竭。彼竭我盈，故克之。夫大国，难测也，惧有伏焉。吾视其辙乱，"},{"t":"望其旗靡","k":12},{"t":"，故逐之。”"}]}],"words":[{"w":"他的同乡人说","e":"“当权的人自会谋划这件事，你又何必参与呢？”"},{"w":"曹刿回答说","e":"“这种小恩小惠不能遍及百姓，百姓不会听从您的"},{"w":"齐师伐我","e":"【易错】「齐师伐我」的「伐」是讨伐，不要写成「代」。"},{"w":"又何间焉","e":"【易错】「又何间焉」的「间」读 jiàn，是参与，不要读成 jiān。"},{"w":"肉食者鄙","e":"【易错】「肉食者鄙」的「鄙」是浅陋，不要写成「蔽」。"},{"w":"小惠未遍","e":"【易错】「小惠未遍」的「遍」是「普遍」，不要写成「偏」；旧版本作「徧」。"},{"w":"牺牲玉帛","e":"【易错】「牺牲玉帛」的「牺牲」指祭祀用的猪牛羊，属古今异义。"},{"w":"小信未孚","e":"【易错】「小信未孚」的「孚」是「使人信服」，不要写成「浮」「俘」。"},{"w":"使人信服","e":"【易错】「小信未孚」的「孚」是「使人信服」，不要写成「浮」「俘」。"},{"w":"小大之狱","e":"【易错】「小大之狱」的「狱」指案件，不要理解为监狱。"},{"w":"公与之乘","e":"【易错】「公与之乘」的「乘」读 chéng，是共乘一车，不要写成「乖」。"},{"w":"齐师败绩","e":"【易错】「齐师败绩」的「绩」是绞丝旁，指大败，不要写成「迹」。"},{"w":"望其旗靡","e":"【易错】「望其旗靡」的「靡」读 mǐ，是倒下，不要写成「糜」「摩」。"},{"w":"曹刿说","e":"“当权的人目光短浅，不能深谋远虑"},{"w":"曹刿问","e":"“凭什么作战？”庄公说：“衣食这类养生的东西，我不敢独自享用，一定把它分给别人"},{"w":"庄公说","e":"“祭祀用的猪牛羊、玉器和丝织品，我从来不敢虚报数目，一定要做到诚实可信"},{"w":"普遍","e":"【易错】「小惠未遍」的「遍」是「普遍」，不要写成「偏」；旧版本作「徧」。"},{"w":"牺牲","e":"【易错】「牺牲玉帛」的「牺牲」指祭祀用的猪牛羊，属古今异义。"},{"w":"伐","e":"【易错】「齐师伐我」的「伐」是讨伐，不要写成「代」。"},{"w":"代","e":"【易错】「齐师伐我」的「伐」是讨伐，不要写成「代」。"},{"w":"间","e":"【易错】「又何间焉」的「间」读 jiàn，是参与，不要读成 jiān。"},{"w":"鄙","e":"【易错】「肉食者鄙」的「鄙」是浅陋，不要写成「蔽」。"},{"w":"蔽","e":"【易错】「肉食者鄙」的「鄙」是浅陋，不要写成「蔽」。"},{"w":"遍","e":"【易错】「小惠未遍」的「遍」是「普遍」，不要写成「偏」；旧版本作「徧」。"},{"w":"偏","e":"【易错】「小惠未遍」的「遍」是「普遍」，不要写成「偏」；旧版本作「徧」。"},{"w":"徧","e":"【易错】「小惠未遍」的「遍」是「普遍」，不要写成「偏」；旧版本作「徧」。"},{"w":"孚","e":"【易错】「小信未孚」的「孚」是「使人信服」，不要写成「浮」「俘」。"},{"w":"浮","e":"【易错】「小信未孚」的「孚」是「使人信服」，不要写成「浮」「俘」。"},{"w":"俘","e":"【易错】「小信未孚」的「孚」是「使人信服」，不要写成「浮」「俘」。"},{"w":"狱","e":"【易错】「小大之狱」的「狱」指案件，不要理解为监狱。"},{"w":"乘","e":"【易错】「公与之乘」的「乘」读 chéng，是共乘一车，不要写成「乖」。"},{"w":"乖","e":"【易错】「公与之乘」的「乘」读 chéng，是共乘一车，不要写成「乖」。"},{"w":"绩","e":"【易错】「齐师败绩」的「绩」是绞丝旁，指大败，不要写成「迹」。"},{"w":"迹","e":"【易错】「齐师败绩」的「绩」是绞丝旁，指大败，不要写成「迹」。"},{"w":"靡","e":"【易错】「望其旗靡」的「靡」读 mǐ，是倒下，不要写成「糜」「摩」。"},{"w":"糜","e":"【易错】「望其旗靡」的「靡」读 mǐ，是倒下，不要写成「糜」「摩」。"},{"w":"摩","e":"【易错】「望其旗靡」的「靡」读 mǐ，是倒下，不要写成「糜」「摩」。"}]},{"type":"h","text":"译文"},{"type":"p","text":"鲁庄公十年春，齐军攻鲁。庄公将要迎战，曹刿请求进见。同乡人说：“当权者自会谋划，你何必参与？”曹刿说：“当权者目光短浅，不能深谋远虑。”于是入见。他问：“凭什么作战？”庄公说：“衣食这类养生的东西，我不敢独自享用，一定分给别人。”曹刿答：“小恩小惠不能遍及百姓，百姓不会听从。”庄公说：“祭祀的牺牲玉帛，我不敢虚报，一定诚实。”曹刿答：“小信未使神信服，神不会保佑。”庄公说：“大小案件，虽不能一一明察，一定按实情处理。”曹刿答：“这是尽职之事，可以一战。作战时请让我跟从。”庄公与他同乘，战于长勺。庄公要击鼓，曹刿说：“不可。”齐军三鼓，曹刿说：“可以了。”齐军大败。战胜后庄公问缘故，曹刿答：“作战靠勇气。一鼓振作士气，二鼓士气衰减，三鼓士气耗尽。彼竭我盈，故能克敌。大国难测，怕有埋伏。我见其车辙混乱、旗帜倒下，所以追击。”"},{"type":"list","title":"名句","items":["一鼓作气，再而衰，三而竭。"]},{"type":"list","title":"背诵提示","items":["「齐师伐我」的「伐」是讨伐，不要写成「代」。","「又何间焉」的「间」读 jiàn，是参与，不要读成 jiān。","「肉食者鄙」的「鄙」是浅陋，不要写成「蔽」。","「小惠未遍」的「遍」是「普遍」，不要写成「偏」；旧版本作「徧」。","「牺牲玉帛」的「牺牲」指祭祀用的猪牛羊，属古今异义。","「小信未孚」的「孚」是「使人信服」，不要写成「浮」「俘」。","「小大之狱」的「狱」指案件，不要理解为监狱。","「公与之乘」的「乘」读 chéng，是共乘一车，不要写成「乖」。","「齐师败绩」的「绩」是绞丝旁，指大败，不要写成「迹」。","「望其旗靡」的「靡」读 mǐ，是倒下，不要写成「糜」「摩」。"]}],"questions":[{"id":"p-p9b-cao-gui-lun-zhan-m0","type":"fill","stem":"默写填空：一鼓作气，______。","answer":"再而衰。","explain":"出自《曹刿论战》（先秦·左丘明）：一鼓作气，再而衰，三而竭。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-cao-gui-lun-zhan-u","type":"fill","stem":"理解性默写：鲁庄公十年的春天，齐国的军队攻打我们鲁国。庄公准备迎战，曹刿请求进见。","answer":"十年春，齐师伐我。公将战，曹刿请见。","explain":"出自《曹刿论战》（先秦·左丘明）。句意：鲁庄公十年的春天，齐国的军队攻打我们鲁国。庄公准备迎战，曹刿请求进见。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-zou-ji-feng-qi-wang-na-jian","title":"邹忌讽齐王纳谏","subtitle":"西汉·刘向","grade":"9a","tags":["文言文","讽谏","类比"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"西汉·刘向"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"刘向（约前77—前6），字子政，原名更生，西汉沛人，汉皇族楚元王刘交的后代，经学家、目录学家、文学家；他历任光禄大夫、中垒校尉等职，长期主持校理皇家藏书，撰有我国第一部目录学著作《别录》，是目录学与校雠学的奠基人之一。\n成书背景：《战国策》所收本是战国时期各国史官与策士辑录的资料汇编，名称不一，有《国策》《国事》《短长》《事语》《长书》《修书》等；西汉末年刘向奉诏整理宫廷藏书，把这类材料分别部居、删繁去重，按东周、西周、秦、齐、楚、赵、魏、韩、燕、宋卫、中山十二国次序编排成三十三篇，并定名为《战国策》。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文选自《战国策·齐策一》，写邹忌以自己与徐公比美的切身感受设喻，委婉讽谏齐威王纳谏除蔽，终使齐国强盛的故事。文章最见功力的是设喻说理：邹忌先在家中反复询问妻、妾、客，再以「私我」「畏我」「有求于我」三句分析受蒙蔽的原因，继而类推到「宫妇左右」「朝廷之臣」「四境之内」，由家事推及国事，层层递进，把抽象的道理讲得具体生动，使威王易于接受。此外，三问三答的排比结构与「门庭若市」「时时而间进」「无可进者」的三段变化，写出了纳谏的成效，剪裁极简。中考常考：类比（设喻）说理的方法、三问三答的句式变化与人物心理、「王之蔽甚矣」的推论逻辑及「孰」「私」「畏」「面刺」「间」「期年」等词义。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"邹忌修八尺有余，而形貌昳丽。","n":"","cn":"邹忌身高八尺多，而且容貌光艳美丽。","parts":[{"t":"邹忌修八尺有余，而"},{"t":"形貌昳丽","k":1},{"t":"。"}]},{"t":"朝服衣冠，窥镜，谓其妻曰：“我孰与城北徐公美？”","n":"","cn":"早晨他穿戴好衣帽，照着镜子，对他的妻子说：“我同城北徐公相比，谁更美？”","parts":[{"t":"朝服衣冠","k":2},{"t":"，窥镜，谓其妻曰：“我"},{"t":"孰","k":14},{"t":"与城北徐公美？”"}]},{"t":"其妻曰：“君美甚，徐公何能及君也！”","n":"他的妻子说：“您美极了，徐公怎么能比得上您呢！”","cn":"","parts":[{"t":"其妻曰：“君美甚，徐公何能及君也！”"}]},{"t":"城北徐公，齐国之美丽者也。","n":"","cn":"城北的徐公，是齐国的美男子。","parts":[{"t":"城北徐公，齐国之美丽者也。"}]},{"t":"忌不自信，而复问其妾曰：“吾孰与徐公美？”","n":"","cn":"邹忌不相信自己（比徐公美），于是又问他的妾说：“我同徐公相比，谁更美？”","parts":[{"t":"忌不自信，而复问其妾曰：“吾"},{"t":"孰","k":14},{"t":"与徐公美？”"}]},{"t":"妾曰：“徐公何能及君也！”","n":"妾说：“徐公怎么能比得上您呢！”","cn":"","parts":[{"t":"妾曰：“徐公何能及君也！”"}]},{"t":"旦日，客从外来，与坐谈，问之客曰：“吾与徐公孰美？”","n":"","cn":"第二天，有客人从外面来，邹忌同他坐着谈话，问客人说：“我和徐公相比，谁更美？”","parts":[{"t":"旦日，客从外来，与坐谈，问之客曰：“吾与徐公"},{"t":"孰","k":14},{"t":"美？”"}]},{"t":"客曰：“徐公不若君之美也。”","n":"客人说：“徐公不如您美。”","cn":"","parts":[{"t":"客曰：“徐公不若君之美也。”"}]},{"t":"明日徐公来，孰视之，自以为不如；窥镜而自视，又弗如远甚。","n":"","cn":"第二天徐公来了，邹忌仔细地看他，自认为不如他；再照镜子看看自己，更觉得远远不如。","parts":[{"t":"明日徐公来，"},{"t":"孰视之","k":7},{"t":"，自以为不如；窥镜而自视，又弗如远甚。"}]},{"t":"暮寝而思之，曰：“吾妻之美我者，私我也；妾之美我者，畏我也；客之美我者，欲有求于我也。”","n":"","cn":"晚上躺在床上思考这件事，说：“我的妻子认为我美，是偏爱我；妾认为我美，是害怕我；客人认为我美，是想有求于我。”","parts":[{"t":"暮寝而思之，曰：“吾妻之美我者，"},{"t":"私我也","k":8},{"t":"；妾之美我者，畏我也；客之美我者，欲有求于我也。”"}]},{"t":"于是入朝见威王，曰：“臣诚知不如徐公美。臣之妻私臣，臣之妾畏臣，臣之客欲有求于臣，皆以美于徐公。","n":"","cn":"于是邹忌上朝去见齐威王，说：“我确实知道自己不如徐公美。可是我的妻子偏爱我，我的妾害怕我，我的客人想有求于我，都认为我比徐公美。","parts":[{"t":"于是入"},{"t":"朝","k":13},{"t":"见威王，曰：“臣诚知不如徐公美。臣之妻"},{"t":"私","k":16},{"t":"臣，臣之妾畏臣，臣之客欲有求于臣，皆以美于徐公。"}]},{"t":"今齐地方千里，百二十城，宫妇左右莫不私王，朝廷之臣莫不畏王，四境之内莫不有求于王：由此观之，王之蔽甚矣。”","n":"","cn":"如今齐国的土地方圆千里，有一百二十座城池，宫中的嫔妃和身边的近臣没有不偏爱大王的，朝中的大臣没有不害怕大王的，全国范围内的人没有不对大王有所求的：由此看来，大王所受的蒙蔽一定很深了。”","parts":[{"t":"今齐地方千里，百二十城，宫妇左右莫不"},{"t":"私","k":16},{"t":"王，"},{"t":"朝","k":13},{"t":"廷之臣莫不畏王，四境之内莫不有求于王：由此观之，王之"},{"t":"蔽","k":17},{"t":"甚矣。”"}]},{"t":"王曰：“善。”乃下令：“群臣吏民能面刺寡人之过者，受上赏；上书谏寡人者，受中赏；能谤讥于市朝，闻寡人之耳者，受下赏。”","n":"威王说：“好。”于是下令：“所有大臣、官吏、百姓能够当面指责我过错的，可得上等奖赏；上书劝谏我的，可得中等奖赏；能够在公共场所批评议论我的过失、传到我耳朵里的，可得下等奖赏。”","cn":"","parts":[{"t":"王曰：“善。”乃下令：“群臣吏民能面"},{"t":"刺","k":20},{"t":"寡人之过者，受上赏；上书谏寡人者，受中赏；能"},{"t":"谤","k":22},{"t":"讥于市"},{"t":"朝","k":13},{"t":"，闻寡人之耳者，受下赏。”"}]},{"t":"令初下，群臣进谏，门庭若市；数月之后，时时而间进；期年之后，虽欲言，无可进者。","n":"","cn":"命令刚下达时，群臣都来进谏，门前和庭院像集市一样热闹；几个月以后，还偶尔有人来进谏；满一年以后，即使想说什么，也没有什么可说的了。","parts":[{"t":"令初下，群臣进谏，门庭若市；数月之后，时时而"},{"t":"间","k":23},{"t":"进；"},{"t":"期年之后","k":3},{"t":"，虽欲言，无可进者。"}]},{"t":"燕、赵、韩、魏闻之，皆朝于齐。此所谓战胜于朝廷。","n":"","cn":"燕、赵、韩、魏等国听说了这件事，都到齐国来朝见。这就是人们所说的在朝廷上战胜了别国。","parts":[{"t":"燕、赵、韩、魏闻之，"},{"t":"皆朝于齐","k":4},{"t":"。此所谓战胜于"},{"t":"朝","k":13},{"t":"廷。"}]}],"words":[{"w":"他的妻子说","e":"“您美极了，徐公怎么能比得上您呢！”"},{"w":"形貌昳丽","e":"【易错】「形貌昳丽」的「昳」是日字旁，读 yì，不要写成「佚」「跌」。"},{"w":"朝服衣冠","e":"【易错】「朝服衣冠」的「朝」读 zhāo，是早晨，不要读成 cháo。"},{"w":"期年之后","e":"【易错】「期年之后」的「期」读 jī，是满一年，不要读成 qī。"},{"w":"皆朝于齐","e":"【易错】「皆朝于齐」的「朝」读 cháo，是朝见。"},{"w":"客人说","e":"“徐公不如您美"},{"w":"威王说","e":"“好"},{"w":"孰视之","e":"【易错】「孰视之」的「孰」通「熟」，是仔细，不要写成「熟」。"},{"w":"私我也","e":"【易错】「私我也」的「私」是偏爱，不要理解为自私。"},{"w":"妾说","e":"“徐公怎么能比得上您呢！”"},{"w":"昳","e":"【易错】「形貌昳丽」的「昳」是日字旁，读 yì，不要写成「佚」「跌」。"},{"w":"佚","e":"【易错】「形貌昳丽」的「昳」是日字旁，读 yì，不要写成「佚」「跌」。"},{"w":"跌","e":"【易错】「形貌昳丽」的「昳」是日字旁，读 yì，不要写成「佚」「跌」。"},{"w":"朝","e":"【易错】「朝服衣冠」的「朝」读 zhāo，是早晨，不要读成 cháo。"},{"w":"孰","e":"【易错】「孰视之」的「孰」通「熟」，是仔细，不要写成「熟」。"},{"w":"熟","e":"【易错】「孰视之」的「孰」通「熟」，是仔细，不要写成「熟」。"},{"w":"私","e":"【易错】「私我也」的「私」是偏爱，不要理解为自私。"},{"w":"蔽","e":"【易错】「王之蔽甚矣」的「蔽」是受蒙蔽，不要写成「敝」「弊」。"},{"w":"敝","e":"【易错】「王之蔽甚矣」的「蔽」是受蒙蔽，不要写成「敝」「弊」。"},{"w":"弊","e":"【易错】「王之蔽甚矣」的「蔽」是受蒙蔽，不要写成「敝」「弊」。"},{"w":"刺","e":"【易错】「面刺寡人之过」的「刺」是指责，不要写成「剌」。"},{"w":"剌","e":"【易错】「面刺寡人之过」的「刺」是指责，不要写成「剌」。"},{"w":"谤","e":"【易错】「谤讥于市朝」的「谤」不是诽谤，是指责议论，属古今异义。"},{"w":"间","e":"【易错】「时时而间进」的「间」读 jiàn，是间或、偶然。"},{"w":"期","e":"【易错】「期年之后」的「期」读 jī，是满一年，不要读成 qī。"}]},{"type":"h","text":"译文"},{"type":"p","text":"邹忌身高八尺多，容貌光艳美丽。早晨穿戴好衣帽照镜，问妻子：“我与城北徐公谁美？”妻子说：“您美极了，徐公怎能比得上您！”城北徐公是齐国美男子。邹忌不信，又问妾：“我与徐公谁美？”妾说：“徐公怎能比得上您！”第二天客人来，邹忌问他：“我与徐公谁美？”客人说：“徐公不如您美。”次日徐公来，邹忌仔细看他，自认不如；照镜自视，更觉远不如。夜里躺下思量：“妻子说我美，是偏爱我；妾说我美，是怕我；客人说我美，是有求于我。”于是入朝见威王说：“我确实不如徐公美。但妻子偏爱我，妾怕我，客人有求于我，都说我比徐公美。如今齐地方圆千里，一百二十城，宫妇左右无不偏爱大王，朝廷之臣无不畏惧大王，四境之内无不有求于大王：由此看来，大王受蒙蔽太深了。”威王说：“好。”于是下令：“能当面指责我过错的受上赏；上书劝谏的受中赏；能谤讥于市朝、传到我耳中的受下赏。”令初下，群臣进谏，门庭若市；数月后，时时而间进；一年后，虽欲言而无可进者。燕赵韩魏听说后，都来朝见齐国。这就是所谓战胜于朝廷。"},{"type":"list","title":"名句","items":["群臣进谏，门庭若市。","此所谓战胜于朝廷。"]},{"type":"list","title":"背诵提示","items":["「形貌昳丽」的「昳」是日字旁，读 yì，不要写成「佚」「跌」。","「朝服衣冠」的「朝」读 zhāo，是早晨，不要读成 cháo。","「孰视之」的「孰」通「熟」，是仔细，不要写成「熟」。","「私我也」的「私」是偏爱，不要理解为自私。","「王之蔽甚矣」的「蔽」是受蒙蔽，不要写成「敝」「弊」。","「面刺寡人之过」的「刺」是指责，不要写成「剌」。","「谤讥于市朝」的「谤」不是诽谤，是指责议论，属古今异义。","「时时而间进」的「间」读 jiàn，是间或、偶然。","「期年之后」的「期」读 jī，是满一年，不要读成 qī。","「皆朝于齐」的「朝」读 cháo，是朝见。"]}],"questions":[{"id":"p-p9b-zou-ji-feng-qi-wang-na-jian-m0","type":"fill","stem":"默写填空：群臣进谏，______。","answer":"门庭若市。","explain":"出自《邹忌讽齐王纳谏》（西汉·刘向）：群臣进谏，门庭若市。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-zou-ji-feng-qi-wang-na-jian-u","type":"fill","stem":"理解性默写：邹忌身高八尺多，而且容貌光艳美丽。","answer":"邹忌修八尺有余，而形貌昳丽。","explain":"出自《邹忌讽齐王纳谏》（西汉·刘向）。句意：邹忌身高八尺多，而且容貌光艳美丽。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-chu-shi-biao","title":"出师表","subtitle":"三国·诸葛亮","grade":"9a","tags":["文言文","表文","忠诚"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"三国·诸葛亮"},{"k":"体裁","v":"文"}]},{"type":"note","title":"作者简介","text":"诸葛亮（181—234），字孔明，号卧龙，琅琊阳都（今山东沂南）人，三国时期蜀汉丞相，杰出的政治家、军事家；因封武乡侯，谥号忠武，后世尊称“武侯”。\n生平经历：他早年隐居隆中躬耕陇亩，自比管仲、乐毅；建安十二年（207）刘备三顾茅庐，他提出占据荆益、联孙抗曹的方略，从此出山辅佐刘备建立蜀汉；章武三年（223）刘备白帝城托孤，他辅佐后主刘禅，先后五次北伐（小说戏曲中称为“六出祁山”），建兴十二年（234）病逝于五丈原军中，一生“鞠躬尽瘁，死而后已”。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"本文是诸葛亮北伐前写给后主刘禅的表文。全文以「报先帝、忠陛下」的感情为线索：先分析当前危急形势，提出「开张圣听」「陟罚臧否，不宜异同」「亲贤臣，远小人」三条建议；再追叙自身身世与先帝三顾之恩、临危受命之艰，表明以身许国的忠诚；最后说明北伐的决心与责任，并以「临表涕零」作结。文章寓情于议、寓情于事，议论、叙事、抒情融为一体，语言恳切质朴，多四字句与对偶，读来感人至深。中考常考：三条建议的内容与用意、作者「报先帝、忠陛下」的思想感情、古今异义词（卑鄙、痛恨、开张、感激）及「妄自菲薄」「三顾茅庐」「计日而待」等成语的出处。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"先帝创业未半而中道崩殂，今天下三分，益州疲弊，此诚危急存亡之秋也。","n":"","cn":"先帝开创的大业还没完成一半就中途去世了，如今天下分成三国，我们益州人力疲惫、民生凋敝，这实在是国家危急存亡的时刻啊。","parts":[{"t":"先帝创业未半而"},{"t":"中道崩殂","k":0},{"t":"，今天下三分，"},{"t":"益州疲弊","k":1},{"t":"，此诚危急存亡之秋也。"}]},{"t":"然侍卫之臣不懈于内，忠志之士忘身于外者，盖追先帝之殊遇，欲报之于陛下也。","n":"","cn":"然而宫廷里侍卫大臣不懈怠，战场上忠诚有志的将士舍身忘死，是因为他们追念先帝的特殊恩遇，想报答给陛下啊。","parts":[{"t":"然侍卫之臣不懈于内，忠志之士忘身于外者，盖追先帝之殊遇，欲报之于陛下也。"}]},{"t":"诚宜开张圣听，以光先帝遗德，恢弘志士之气，不宜妄自菲薄，引喻失义，以塞忠谏之路也。","n":"","cn":"（陛下）实在应该广泛地听取意见，来发扬先帝留下的美德，振奋志士的勇气，不应该随便看轻自己，说话不恰当，以致堵塞忠臣进谏的道路。","parts":[{"t":"诚宜开张圣听，以光先帝遗德，恢弘志士之气，不宜"},{"t":"妄自菲薄","k":3},{"t":"，"},{"t":"引喻失义","k":4},{"t":"，以塞忠谏之路也。"}]},{"t":"宫中府中，俱为一体，陟罚臧否，不宜异同。","n":"","cn":"皇宫中和朝廷中，都是一个整体，升降官职、评定褒贬，不应该有差别。","parts":[{"t":"宫中府中，俱为一体，"},{"t":"陟罚臧否","k":2},{"t":"，不宜异同。"}]},{"t":"亲贤臣，远小人，此先汉所以兴隆也；亲小人，远贤臣，此后汉所以倾颓也。","n":"","cn":"亲近贤臣，疏远小人，这是先汉兴旺发达的原因；亲近小人，疏远贤臣，这是后汉衰败的原因。","parts":[{"t":"亲贤臣，远小人，此先汉所以兴隆也；亲小人，远贤臣，此后汉所以"},{"t":"倾颓","k":9},{"t":"也。"}]},{"t":"先帝在时，每与臣论此事，未尝不叹息痛恨于桓、灵也。","n":"","cn":"先帝在世时，每次和我谈论这件事，没有不为桓帝、灵帝的所作所为叹息、痛心遗憾的。","parts":[{"t":"先帝在时，每与臣论此事，未尝不叹息痛恨于桓、灵也。"}]},{"t":"臣本布衣，躬耕于南阳，苟全性命于乱世，不求闻达于诸侯。","n":"","cn":"我本来是个平民，在南阳亲自耕田，只求在乱世中苟且保全性命，不谋求在诸侯中扬名显达。","parts":[{"t":"臣本布衣，"},{"t":"躬","k":26},{"t":"耕于南阳，苟全性命于乱世，不求闻达于诸侯。"}]},{"t":"先帝不以臣卑鄙，猥自枉屈，三顾臣于草庐之中，咨臣以当世之事，由是感激，遂许先帝以驱驰。","n":"","cn":"先帝不因为我地位低微、见识短浅，屈尊就卑，三次到草庐来拜访我，向我询问当世大事，我因此十分感动，就答应为先帝奔走效劳。","parts":[{"t":"先帝不以臣卑鄙，"},{"t":"猥自枉屈","k":5},{"t":"，三顾臣于草庐之中，咨臣以当世之事，由是感激，遂许先帝以驱驰。"}]},{"t":"后值倾覆，受任于败军之际，奉命于危难之间，尔来二十有一年矣。","n":"","cn":"后来遇到兵败，我在战败的时候接受重任，在危难的时候奉命出使，从那时到现在已经二十一年了。","parts":[{"t":"后值倾覆，受任于败军之际，奉命于危难之间，尔来二十有一年矣。"}]},{"t":"今南方已定，兵甲已足，当奖率三军，北定中原，庶竭驽钝，攘除奸凶，兴复汉室，还于旧都。","n":"","cn":"如今南方已经平定，武器装备已经充足，应当勉励并率领三军，北上平定中原，希望用尽我平庸的才能，铲除奸邪凶恶的敌人，复兴汉室，迁回旧都洛阳。","parts":[{"t":"今南方已定，兵甲已足，当奖率三军，北定中原，"},{"t":"庶竭驽钝","k":6},{"t":"，"},{"t":"攘除奸凶","k":7},{"t":"，兴复汉室，还于旧都。"}]},{"t":"愿陛下托臣以讨贼兴复之效；不效，则治臣之罪，以告先帝之灵。","n":"","cn":"希望陛下把讨伐曹魏、复兴汉室的重任交给我；如果不能成功，就治我的罪，来告慰先帝的在天之灵。","parts":[{"t":"愿陛下托臣以讨贼兴复之效；不效，则治臣之罪，以告先帝之灵。"}]},{"t":"今当远离，临表涕零，不知所言。","n":"","cn":"如今我就要远离陛下，面对这篇表章泪流满面，不知说了些什么。","parts":[{"t":"今当远离，"},{"t":"临表涕零","k":8},{"t":"，不知所言。"}]}],"words":[{"w":"中道崩殂","e":"【易错】「中道崩殂」的「殂」是歹字旁，读 cú，不要写成「阻」「租」。"},{"w":"益州疲弊","e":"【易错】「益州疲弊」的「弊」不要写成「敝」「毙」。"},{"w":"陟罚臧否","e":"【易错】「陟罚臧否」的「陟」是双耳旁，读 zhì，是提拔；「否」读 pǐ，不要读成 fǒu。"},{"w":"妄自菲薄","e":"【易错】「妄自菲薄」的「菲」是草字头，不要写成「诽」。"},{"w":"引喻失义","e":"【易错】「引喻失义」的「喻」是口字旁，不要写成「渝」「愉」。"},{"w":"猥自枉屈","e":"【易错】「猥自枉屈」的「猥」是反犬旁，不要写成「畏」「委」。"},{"w":"庶竭驽钝","e":"【易错】「庶竭驽钝」的「驽」是马字头下「弓」，指劣马，不要写成「弩」。"},{"w":"攘除奸凶","e":"【易错】「攘除奸凶」的「攘」是提手旁，不要写成「壤」「嚷」。"},{"w":"临表涕零","e":"【易错】「临表涕零」的「涕」是三点水，指眼泪，不要写成「梯」。"},{"w":"倾颓","e":"【易错】「倾颓」的「颓」左旁是「秃」，不要写成「隤」。"},{"w":"殂","e":"【易错】「中道崩殂」的「殂」是歹字旁，读 cú，不要写成「阻」「租」。"},{"w":"阻","e":"【易错】「中道崩殂」的「殂」是歹字旁，读 cú，不要写成「阻」「租」。"},{"w":"租","e":"【易错】「中道崩殂」的「殂」是歹字旁，读 cú，不要写成「阻」「租」。"},{"w":"弊","e":"【易错】「益州疲弊」的「弊」不要写成「敝」「毙」。"},{"w":"敝","e":"【易错】「益州疲弊」的「弊」不要写成「敝」「毙」。"},{"w":"毙","e":"【易错】「益州疲弊」的「弊」不要写成「敝」「毙」。"},{"w":"陟","e":"【易错】「陟罚臧否」的「陟」是双耳旁，读 zhì，是提拔；「否」读 pǐ，不要读成 fǒu。"},{"w":"否","e":"【易错】「陟罚臧否」的「陟」是双耳旁，读 zhì，是提拔；「否」读 pǐ，不要读成 fǒu。"},{"w":"菲","e":"【易错】「妄自菲薄」的「菲」是草字头，不要写成「诽」。"},{"w":"诽","e":"【易错】「妄自菲薄」的「菲」是草字头，不要写成「诽」。"},{"w":"喻","e":"【易错】「引喻失义」的「喻」是口字旁，不要写成「渝」「愉」。"},{"w":"渝","e":"【易错】「引喻失义」的「喻」是口字旁，不要写成「渝」「愉」。"},{"w":"愉","e":"【易错】「引喻失义」的「喻」是口字旁，不要写成「渝」「愉」。"},{"w":"颓","e":"【易错】「倾颓」的「颓」左旁是「秃」，不要写成「隤」。"},{"w":"秃","e":"【易错】「倾颓」的「颓」左旁是「秃」，不要写成「隤」。"},{"w":"隤","e":"【易错】「倾颓」的「颓」左旁是「秃」，不要写成「隤」。"},{"w":"躬","e":"【易错】「躬耕于南阳」的「躬」是身字旁，不要写成「弓」。"},{"w":"弓","e":"【易错】「躬耕于南阳」的「躬」是身字旁，不要写成「弓」。"},{"w":"猥","e":"【易错】「猥自枉屈」的「猥」是反犬旁，不要写成「畏」「委」。"},{"w":"畏","e":"【易错】「猥自枉屈」的「猥」是反犬旁，不要写成「畏」「委」。"},{"w":"委","e":"【易错】「猥自枉屈」的「猥」是反犬旁，不要写成「畏」「委」。"},{"w":"驽","e":"【易错】「庶竭驽钝」的「驽」是马字头下「弓」，指劣马，不要写成「弩」。"},{"w":"弩","e":"【易错】「庶竭驽钝」的「驽」是马字头下「弓」，指劣马，不要写成「弩」。"},{"w":"攘","e":"【易错】「攘除奸凶」的「攘」是提手旁，不要写成「壤」「嚷」。"},{"w":"壤","e":"【易错】「攘除奸凶」的「攘」是提手旁，不要写成「壤」「嚷」。"},{"w":"嚷","e":"【易错】「攘除奸凶」的「攘」是提手旁，不要写成「壤」「嚷」。"},{"w":"涕","e":"【易错】「临表涕零」的「涕」是三点水，指眼泪，不要写成「梯」。"},{"w":"梯","e":"【易错】「临表涕零」的「涕」是三点水，指眼泪，不要写成「梯」。"}]},{"type":"list","title":"名句","items":["受任于败军之际，奉命于危难之间。","亲贤臣，远小人，此先汉所以兴隆也。"]},{"type":"list","title":"背诵提示","items":["「中道崩殂」的「殂」是歹字旁，读 cú，不要写成「阻」「租」。","「益州疲弊」的「弊」不要写成「敝」「毙」。","「陟罚臧否」的「陟」是双耳旁，读 zhì，是提拔；「否」读 pǐ，不要读成 fǒu。","「妄自菲薄」的「菲」是草字头，不要写成「诽」。","「引喻失义」的「喻」是口字旁，不要写成「渝」「愉」。","「倾颓」的「颓」左旁是「秃」，不要写成「隤」。","「躬耕于南阳」的「躬」是身字旁，不要写成「弓」。","「猥自枉屈」的「猥」是反犬旁，不要写成「畏」「委」。","「庶竭驽钝」的「驽」是马字头下「弓」，指劣马，不要写成「弩」。","「攘除奸凶」的「攘」是提手旁，不要写成「壤」「嚷」。","「临表涕零」的「涕」是三点水，指眼泪，不要写成「梯」。"]}],"questions":[{"id":"p-p9b-chu-shi-biao-m0","type":"fill","stem":"默写填空：受任于败军之际，______。","answer":"奉命于危难之间。","explain":"出自《出师表》（三国·诸葛亮）：受任于败军之际，奉命于危难之间。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-chu-shi-biao-m1","type":"fill","stem":"默写填空：亲贤臣，______。","answer":"远小人。","explain":"出自《出师表》（三国·诸葛亮）：亲贤臣，远小人，此先汉所以兴隆也。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-chu-shi-biao-u","type":"fill","stem":"理解性默写：先帝开创的大业还没完成一半就中途去世了，如今天下分成三国，我们益州人力疲惫、民生凋敝，这实在是国家危急存亡的时刻啊。","answer":"先帝创业未半而中道崩殂，今天下三分，益州疲弊，此诚危急存亡之秋也。","explain":"出自《出师表》（三国·诸葛亮）。句意：先帝开创的大业还没完成一半就中途去世了，如今天下分成三国，我们益州人力疲惫、民生凋敝，这实在是国家危急存亡的时刻啊。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-shi-wu-cong-jun-zheng","title":"十五从军征","subtitle":"汉·佚名","grade":"9a","tags":["乐府","叙事","反战"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"汉·佚名"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者与出处","text":"汉佚名作品，作者与生平不详。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首汉代乐府民歌选自《乐府诗集》，写一位少年从军、白头归来的老兵返乡后的悲惨遭遇。全诗用白描手法，不着一句议论而悲愤自见：开头「十五」「八十」两个数字对举，概括了终身服役的残酷；「松柏冢累累」以乡邻之口点出家人尽亡；「兔从狗窦入，雉从梁上飞。中庭生旅谷，井上生旅葵」四句由远及近写家园荒废，以动物的自在反衬人烟的断绝；「羹饭一时熟，不知贻阿谁」以极平常的生活细节写出无亲可奉的孤苦，最为沉痛；结尾「出门东向看，泪落沾我衣」以动作与泪收束，无言而尽悲。中考常考：白描与景物烘托的手法、数字对比的作用、「不知贻阿谁」的深层情感，以及本诗对战争与兵役制度的揭露。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"十五从军征，八十始得归。","n":"","cn":"十五岁就应征从军，直到八十岁才得以回家。","parts":[{"t":"十五从军征，八十"},{"t":"始","k":0},{"t":"得归。"}]},{"t":"道逢乡里人：“家中有阿谁？”","n":"","cn":"在路上遇到家乡的人，问：“我家里还有什么人？”","parts":[{"t":"道逢乡里人：“"},{"t":"家","k":6},{"t":"中有"},{"t":"阿","k":3},{"t":"谁？”"}]},{"t":"“遥看是君家，松柏冢累累。”","n":"","cn":"“远远看去那就是你家，松柏树下一片坟墓重重叠叠。”","parts":[{"t":"“遥看是君"},{"t":"家","k":6},{"t":"，松柏"},{"t":"冢","k":4},{"t":"累累。”"}]},{"t":"兔从狗窦入，雉从梁上飞。","n":"","cn":"野兔从狗洞里钻进钻出，野鸡从屋梁上飞起。","parts":[{"t":"兔从狗"},{"t":"窦","k":7},{"t":"入，"},{"t":"雉","k":9},{"t":"从梁上飞。"}]},{"t":"中庭生旅谷，井上生旅葵。","n":"","cn":"庭院里长满了野生的谷子，井台边生满了野生的葵菜。","parts":[{"t":"中庭生"},{"t":"旅","k":14},{"t":"谷，井上生"},{"t":"旅","k":14},{"t":"葵。"}]},{"t":"舂谷持作饭，采葵持作羹。","n":"","cn":"捣掉谷壳拿来做饭，采摘葵菜做成汤。","parts":[{"t":"舂","k":15},{"t":"谷持作饭，采葵持作羹。"}]},{"t":"羹饭一时熟，不知贻阿谁。","n":"","cn":"饭和汤一会儿就做好了，却不知道送给谁吃。","parts":[{"t":"羹饭一时熟，不知"},{"t":"贻","k":18},{"t":"阿","k":3},{"t":"谁。"}]},{"t":"出门东向看，泪落沾我衣。","n":"","cn":"走出家门向东望去，老泪纵横，沾湿了我的衣裳。","parts":[{"t":"出门东向看，泪落沾我衣。"}]}],"words":[{"w":"始","e":"【易错】「八十始得归」的「始」是「才」，不要写成「使」。"},{"w":"才","e":"【易错】「八十始得归」的「始」是「才」，不要写成「使」。"},{"w":"使","e":"【易错】「八十始得归」的「始」是「才」，不要写成「使」。"},{"w":"阿","e":"【易错】「家中有阿谁」的「阿」读 ā，是语助词，不要漏写。"},{"w":"冢","e":"【易错】「松柏冢累累」的「冢」是宝盖头下「豕」，指坟墓，不要写成「家」。"},{"w":"豕","e":"【易错】「松柏冢累累」的「冢」是宝盖头下「豕」，指坟墓，不要写成「家」。"},{"w":"家","e":"【易错】「松柏冢累累」的「冢」是宝盖头下「豕」，指坟墓，不要写成「家」。"},{"w":"窦","e":"【易错】「兔从狗窦入」的「窦」是穴字头，指洞，不要写成「突」。"},{"w":"突","e":"【易错】「兔从狗窦入」的「窦」是穴字头，指洞，不要写成「突」。"},{"w":"雉","e":"【易错】「雉从梁上飞」的「雉」是「矢」旁「隹」，指野鸡，不要写成「稚」「雁」。"},{"w":"矢","e":"【易错】「雉从梁上飞」的「雉」是「矢」旁「隹」，指野鸡，不要写成「稚」「雁」。"},{"w":"隹","e":"【易错】「雉从梁上飞」的「雉」是「矢」旁「隹」，指野鸡，不要写成「稚」「雁」。"},{"w":"稚","e":"【易错】「雉从梁上飞」的「雉」是「矢」旁「隹」，指野鸡，不要写成「稚」「雁」。"},{"w":"雁","e":"【易错】「雉从梁上飞」的「雉」是「矢」旁「隹」，指野鸡，不要写成「稚」「雁」。"},{"w":"旅","e":"【易错】「中庭生旅谷」的「旅」指野生的，不要按现代义理解。"},{"w":"舂","e":"【易错】「舂谷持作饭」的「舂」下面是「臼」，不要写成「春」。"},{"w":"臼","e":"【易错】「舂谷持作饭」的「舂」下面是「臼」，不要写成「春」。"},{"w":"春","e":"【易错】「舂谷持作饭」的「舂」下面是「臼」，不要写成「春」。"},{"w":"贻","e":"【易错】「不知贻阿谁」的「贻」是贝字旁，是赠送，不要写成「遗」「怡」。"},{"w":"遗","e":"【易错】「不知贻阿谁」的「贻」是贝字旁，是赠送，不要写成「遗」「怡」。"},{"w":"怡","e":"【易错】「不知贻阿谁」的「贻」是贝字旁，是赠送，不要写成「遗」「怡」。"}]},{"type":"list","title":"名句","items":["十五从军征，八十始得归。","出门东向看，泪落沾我衣。"]},{"type":"list","title":"背诵提示","items":["「八十始得归」的「始」是「才」，不要写成「使」。","「家中有阿谁」的「阿」读 ā，是语助词，不要漏写。","「松柏冢累累」的「冢」是宝盖头下「豕」，指坟墓，不要写成「家」。","「兔从狗窦入」的「窦」是穴字头，指洞，不要写成「突」。","「雉从梁上飞」的「雉」是「矢」旁「隹」，指野鸡，不要写成「稚」「雁」。","「中庭生旅谷」的「旅」指野生的，不要按现代义理解。","「舂谷持作饭」的「舂」下面是「臼」，不要写成「春」。","「不知贻阿谁」的「贻」是贝字旁，是赠送，不要写成「遗」「怡」。"]}],"questions":[{"id":"p-p9b-shi-wu-cong-jun-zheng-m0","type":"fill","stem":"默写填空：十五从军征，______。","answer":"八十始得归。","explain":"出自《十五从军征》（汉·佚名）：十五从军征，八十始得归。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-shi-wu-cong-jun-zheng-m1","type":"fill","stem":"默写填空：出门东向看，______。","answer":"泪落沾我衣。","explain":"出自《十五从军征》（汉·佚名）：出门东向看，泪落沾我衣。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-shi-wu-cong-jun-zheng-u","type":"fill","stem":"理解性默写：十五岁就应征从军，直到八十岁才得以回家。","answer":"十五从军征，八十始得归。","explain":"出自《十五从军征》（汉·佚名）。句意：十五岁就应征从军，直到八十岁才得以回家。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-shi-wei","title":"式微","subtitle":"先秦·《诗经》","grade":"8b","tags":["诗经","邶风","劳役","重章叠句","怨愤"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·《诗经》"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者与出处","text":"选自《诗经》，作者不详。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"《式微》选自《诗经·邶风》，是一首劳役者的怨歌。全诗只有两章，每章都以「式微式微，胡不归」的反复设问开篇：天色已晚，为何还不能回家？这一问既是实写收工不得归的处境，也暗含对役使者的责问。每章后两句给出答案：「微君之故，胡为乎中露」「微君之躬，胡为乎泥中」，把「不归」的原因归结到「君」身上，语气由疑问转为怨愤，不平之气溢于言表。「中露」「泥中」两个具体场景，写尽露宿泥淖的劳役之苦，比空说「苦」更为真切。两章结构相同而只换「故」与「躬」、「中露」与「泥中」，属于典型的重章叠句，在回环往复中加重了情感分量"},{"type":"list","title":"中考考点","items":["「式微」的「微」与「微君之故」的「微」的不同含义","重章叠句的作用","反问句式所抒发的怨愤之情","「中露」的倒装与「躬」的解释。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"式微式微，胡不归？","n":"","cn":"天黑了，天黑了，为什么还不回家呢？「式」是语气助词，「微」指昏暗。","parts":[{"t":"式微式微","k":3},{"t":"，"},{"t":"胡不归","k":4},{"t":"？"}]},{"t":"微君之故，胡为乎中露？","n":"","cn":"如果不是为了君主的缘故，怎么会在露水中受苦呢？「微」是「非，不是」，「中露」是「露中」的倒装。","parts":[{"t":"微君之故","k":0},{"t":"，"},{"t":"胡","k":12},{"t":"为乎"},{"t":"中露","k":7},{"t":"？"}]},{"t":"式微式微，胡不归？","n":"","cn":"天黑了，天黑了，为什么还不回家呢？这是两章共用的起句，反复设问，一唱三叹。","parts":[{"t":"式微式微","k":3},{"t":"，"},{"t":"胡不归","k":4},{"t":"？"}]},{"t":"微君之躬，胡为乎泥中？","n":"","cn":"如果不是为了君主自身的事，怎么会在泥浆中受苦呢？「躬」指身体、自身，与上章的「故」相对。","parts":[{"t":"微君之躬","k":2},{"t":"，"},{"t":"胡","k":12},{"t":"为乎泥中？"}]}],"words":[{"w":"微君之故","e":"【易错】「式微」的「微」指昏暗；「微君之故」的「微」是「非，不是」，都不译作「微小」，「式」是语气助词。"},{"w":"中间的露","e":"【易错】「胡为乎中露」的「中露」是「露中」的倒装，指露水之中，不按现代语序理解为「中间的露」。"},{"w":"微君之躬","e":"【易错】「微君之躬」的「躬」指身体、自身，是身字旁，不写「弓」。"},{"w":"式微式微","e":"【易错】两章首句完全相同，默写时容易漏写第二遍，注意「式微式微」要连写两次。"},{"w":"胡不归","e":"【易错】「胡不归」的「胡」是疑问代词，意为「何、为什么」，不写「湖」「糊」。"},{"w":"式微","e":"【易错】「式微」的「微」指昏暗；「微君之故」的「微」是「非，不是」，都不译作「微小」，「式」是语气助词。"},{"w":"微小","e":"【易错】「式微」的「微」指昏暗；「微君之故」的「微」是「非，不是」，都不译作「微小」，「式」是语气助词。"},{"w":"中露","e":"【易错】「胡为乎中露」的「中露」是「露中」的倒装，指露水之中，不按现代语序理解为「中间的露」。"},{"w":"露中","e":"【易错】「胡为乎中露」的「中露」是「露中」的倒装，指露水之中，不按现代语序理解为「中间的露」。"},{"w":"式","e":"是语气助词"},{"w":"微","e":"是「非，不是」"},{"w":"躬","e":"指身体、自身"},{"w":"胡","e":"【易错】「胡不归」的「胡」是疑问代词，意为「何、为什么」，不写「湖」「糊」。"},{"w":"湖","e":"【易错】「胡不归」的「胡」是疑问代词，意为「何、为什么」，不写「湖」「糊」。"},{"w":"糊","e":"【易错】「胡不归」的「胡」是疑问代词，意为「何、为什么」，不写「湖」「糊」。"},{"w":"弓","e":"【易错】「微君之躬」的「躬」指身体、自身，是身字旁，不写「弓」。"}]},{"type":"list","title":"名句","items":["微君之故，胡为乎中露？"]},{"type":"list","title":"背诵提示","items":["「式微」的「微」指昏暗；「微君之故」的「微」是「非，不是」，都不译作「微小」，「式」是语气助词。","「胡为乎中露」的「中露」是「露中」的倒装，指露水之中，不按现代语序理解为「中间的露」。","「胡不归」的「胡」是疑问代词，意为「何、为什么」，不写「湖」「糊」。","「微君之躬」的「躬」指身体、自身，是身字旁，不写「弓」。","两章首句完全相同，默写时容易漏写第二遍，注意「式微式微」要连写两次。"]}],"questions":[{"id":"p-p8b-shi-wei-m0","type":"fill","stem":"默写填空：微君之故，______。","answer":"胡为乎中露？。","explain":"出自《式微》（先秦·《诗经》）：微君之故，胡为乎中露？","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-shi-wei-u","type":"fill","stem":"理解性默写：天黑了，天黑了，为什么还不回家呢？「式」是语气助词，「微」指昏暗。","answer":"式微式微，胡不归？","explain":"出自《式微》（先秦·《诗经》）。句意：天黑了，天黑了，为什么还不回家呢？「式」是语气助词，「微」指昏暗。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-zi-jin","title":"子衿","subtitle":"先秦·《诗经》","grade":"8b","tags":["诗经","郑风","相思","重章叠句","反问","夸张"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"先秦·《诗经》"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者与出处","text":"选自《诗经》，作者不详。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"《子衿》选自《诗经·郑风》，是一首女子思念心上人的情诗。全诗三章：前两章均以「青青子衿」「青青子佩」起句，从对方的衣领、佩带着笔，由物及人，思念之情油然而生；「悠悠我心」「悠悠我思」两个叠词，把绵长不能自已的相思写得可见可感。「纵我不往，子宁不嗣音」「子宁不来」连用两个反问句，表面是责怪对方不来，实则是思念之极的婉转吐露，可谓「怨」由「思」生。末章转写自己的行动与心理：「挑兮达兮，在城阙兮」以来回走动、登楼张望的动作，写尽等待中的焦躁不安；「一日不见，如三月兮」用夸张手法把一日之短与三月之长相对比，相思之苦一语道尽，成为后世「一日不见，如隔三秋」的源头。全诗重章叠句、一唱三叹，曹操《短歌行》即引「青青子衿，悠悠我心」以表思慕贤才之意"},{"type":"list","title":"中考考点","items":["起兴与重章叠句的表达效果","反问句的抒情作用","「一日不见，如三月兮」的夸张手法赏析","「衿」「嗣」「挑」「达」「阙」的读音与释义。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"青青子衿，悠悠我心。","n":"","cn":"你的衣领青又青，我的思念长又长。「衿」指衣领，一说指衣领的交领处。","parts":[{"t":"青青子衿","k":0},{"t":"，悠悠我心。"}]},{"t":"纵我不往，子宁不嗣音？","n":"","cn":"纵然我不曾去找你，难道你就不接着传个音信给我吗？「嗣」是接续、继续，「音」指音信。","parts":[{"t":"纵我不往","k":3},{"t":"，"},{"t":"子宁","k":4},{"t":"不"},{"t":"嗣","k":7},{"t":"音？"}]},{"t":"青青子佩，悠悠我思。","n":"","cn":"你的佩带青又青，我的思念深又深。此章与首章句式相同，只换「衿」为「佩」、「心」为「思」。","parts":[{"t":"青青子佩，悠悠我思。"}]},{"t":"纵我不往，子宁不来？","n":"","cn":"纵然我不曾去找你，难道你就不能来吗？两章连用反问，把思念中的埋怨说得婉转而深切。","parts":[{"t":"纵我不往","k":3},{"t":"，"},{"t":"子宁","k":4},{"t":"不来？"}]},{"t":"挑兮达兮，在城阙兮。","n":"","cn":"（我）独自来回走动，心神不宁啊，在城门两边的观楼上（张望）啊。「挑」「达」形容独自走动、心绪不宁的样子。","parts":[{"t":"挑兮达兮","k":1},{"t":"，"},{"t":"在城阙兮","k":2},{"t":"。"}]},{"t":"一日不见，如三月兮。","n":"","cn":"一天见不到你的面，就好像隔了三个月那么长久啊。以夸张写相思之深。","parts":[{"t":"一日不见，如三月兮。"}]}],"words":[{"w":"青青子衿","e":"【易错】「青青子衿」的「衿」读 jīn，是衣字旁，指衣领，不写「矜」「吟」。"},{"w":"挑兮达兮","e":"【易错】「挑兮达兮」的「挑」「达」分别读 tāo、tà，形容独自来回走动、心神不宁，不按今音读 tiāo、dá，也不写「挞」。"},{"w":"在城阙兮","e":"【易错】「在城阙兮」的「阙」读 què，指城门两边的观楼，不写「阕」。"},{"w":"纵我不往","e":"【易错】「纵我不往」的「纵」是「纵然、即使」之意，不写「从」。"},{"w":"子宁","e":"【易错】两个「子宁」的「宁」都读 nìng，意为「难道」，不读 níng。"},{"w":"难道","e":"【易错】两个「子宁」的「宁」都读 nìng，意为「难道」，不读 níng。"},{"w":"衿","e":"指衣领"},{"w":"嗣","e":"是接续、继续"},{"w":"矜","e":"【易错】「青青子衿」的「衿」读 jīn，是衣字旁，指衣领，不写「矜」「吟」。"},{"w":"吟","e":"【易错】「青青子衿」的「衿」读 jīn，是衣字旁，指衣领，不写「矜」「吟」。"},{"w":"饲","e":"【易错】「子宁不嗣音」的「嗣」读 sì，是接续、继续的意思，不写「饲」「祠」。"},{"w":"祠","e":"【易错】「子宁不嗣音」的「嗣」读 sì，是接续、继续的意思，不写「饲」「祠」。"},{"w":"挑","e":"【易错】「挑兮达兮」的「挑」「达」分别读 tāo、tà，形容独自来回走动、心神不宁，不按今音读 tiāo、dá，也不写「挞」。"},{"w":"达","e":"【易错】「挑兮达兮」的「挑」「达」分别读 tāo、tà，形容独自来回走动、心神不宁，不按今音读 tiāo、dá，也不写「挞」。"},{"w":"挞","e":"【易错】「挑兮达兮」的「挑」「达」分别读 tāo、tà，形容独自来回走动、心神不宁，不按今音读 tiāo、dá，也不写「挞」。"},{"w":"阙","e":"【易错】「在城阙兮」的「阙」读 què，指城门两边的观楼，不写「阕」。"},{"w":"阕","e":"【易错】「在城阙兮」的「阙」读 què，指城门两边的观楼，不写「阕」。"},{"w":"纵","e":"【易错】「纵我不往」的「纵」是「纵然、即使」之意，不写「从」。"},{"w":"从","e":"【易错】「纵我不往」的「纵」是「纵然、即使」之意，不写「从」。"},{"w":"宁","e":"【易错】两个「子宁」的「宁」都读 nìng，意为「难道」，不读 níng。"}]},{"type":"list","title":"名句","items":["青青子衿，悠悠我心。","一日不见，如三月兮。"]},{"type":"list","title":"背诵提示","items":["「青青子衿」的「衿」读 jīn，是衣字旁，指衣领，不写「矜」「吟」。","「子宁不嗣音」的「嗣」读 sì，是接续、继续的意思，不写「饲」「祠」。","「挑兮达兮」的「挑」「达」分别读 tāo、tà，形容独自来回走动、心神不宁，不按今音读 tiāo、dá，也不写「挞」。","「在城阙兮」的「阙」读 què，指城门两边的观楼，不写「阕」。","「纵我不往」的「纵」是「纵然、即使」之意，不写「从」。","两个「子宁」的「宁」都读 nìng，意为「难道」，不读 níng。"]}],"questions":[{"id":"p-p8b-zi-jin-m0","type":"fill","stem":"默写填空：青青子衿，______。","answer":"悠悠我心。","explain":"出自《子衿》（先秦·《诗经》）：青青子衿，悠悠我心。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-zi-jin-m1","type":"fill","stem":"默写填空：一日不见，______。","answer":"如三月兮。","explain":"出自《子衿》（先秦·《诗经》）：一日不见，如三月兮。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-zi-jin-u","type":"fill","stem":"理解性默写：你的衣领青又青，我的思念长又长。「衿」指衣领，一说指衣领的交领处。","answer":"青青子衿，悠悠我心。","explain":"出自《子衿》（先秦·《诗经》）。句意：你的衣领青又青，我的思念长又长。「衿」指衣领，一说指衣领的交领处。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8b-wang-dong-ting-hu","title":"望洞庭湖赠张丞相","subtitle":"唐·孟浩然","grade":"8b","tags":["干谒诗","写景","用典","炼字","求荐","孟浩然"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·孟浩然"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"孟浩然（689—740），字浩然，襄州襄阳（今湖北襄阳）人，世称“孟襄阳”，唐代山水田园诗派的代表诗人。\n生平经历：他早年隐居家乡鹿门山读书，此后长期漫游江湘、吴越之间，一生大部分时间在隐居中度过；他曾赴长安应进士举而不第，在太学赋诗而名动公卿；后来张九龄镇守荆州，他入其幕府为从事；晚年归隐襄阳，因病去世。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是孟浩然写给时任丞相张九龄的一首干谒诗，借观湖抒怀，表达希望得到引荐、出仕用世的心愿。前四句写洞庭湖的壮阔景象：首联「八月湖水平，涵虚混太清」写秋水盛涨、水天相接，境界开阔；颔联「气蒸云梦泽，波撼岳阳城」是千古名句，「蒸」字写水汽蒸腾、弥漫无际，「撼」字写波涛汹涌、撼动城郭，一静一动，从视觉与声势两方面把洞庭湖的磅礴气象写足，历来与杜甫写洞庭的名句并称。后四句由景入情：「欲济无舟楫」以渡湖无船比喻出仕无人引荐，「端居耻圣明」写不甘闲居、欲有为于盛世；「坐观垂钓者，徒有羡鱼情」化用《淮南子》「临河而羡鱼，不如归家织网」的典故，把求荐之意说得含蓄得体，不卑不亢。全诗写景气势雄浑，言志委婉含蓄，是唐代干谒诗中的名篇"},{"type":"list","title":"中考考点","items":["颔联「蒸」「撼」二字的炼字赏析","「舟楫」「垂钓者」的比喻义","结尾用典的用意","由景入情、以景衬情的写法。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"八月湖水平，涵虚混太清。","n":"","cn":"八月洞庭湖水盛涨，水面与湖岸齐平；湖水涵容着天空，水色与天色浑然一片。「涵虚」指水映天空，「太清」指天空。","parts":[{"t":"八月湖水平，"},{"t":"涵虚","k":2},{"t":"混","k":11},{"t":"太清","k":3},{"t":"。"}]},{"t":"气蒸云梦泽，波撼岳阳城。","n":"","cn":"云梦泽的水汽蒸腾弥漫，洞庭湖的波涛汹涌，仿佛摇撼着岳阳城。「云梦泽」是古代大泽名。","parts":[{"t":"气"},{"t":"蒸","k":7},{"t":"云梦泽","k":0},{"t":"，波"},{"t":"撼","k":9},{"t":"岳阳城。"}]},{"t":"欲济无舟楫，端居耻圣明。","n":"","cn":"想要渡过湖去却没有船只，闲居不仕又有愧于这圣明的时代。「济」是渡，「楫」是船桨，代指船，「端居」指闲居。","parts":[{"t":"欲"},{"t":"济","k":6},{"t":"无舟"},{"t":"楫","k":12},{"t":"，端居"},{"t":"耻","k":14},{"t":"圣明。"}]},{"t":"坐观垂钓者，徒有羡鱼情。","n":"","cn":"坐着看别人垂钓，只能白白地产生羡慕鱼儿上钩的心情。这里以垂钓者喻已入仕之人，以「羡鱼」喻自己希望出仕却无人引荐。","parts":[{"t":"坐观垂钓者，徒有"},{"t":"羡鱼","k":5},{"t":"情。"}]}],"words":[{"w":"云梦泽","e":"是古代大泽名"},{"w":"太清静","e":"【易错】「涵虚混太清」的「混」读 hùn，是混同、融为一体之意；「太清」指天空，不可解作「太清静」。"},{"w":"涵虚","e":"指水映天空"},{"w":"太清","e":"【易错】「涵虚混太清」的「混」读 hùn，是混同、融为一体之意；「太清」指天空，不可解作「太清静」。"},{"w":"耻辱","e":"【易错】「端居耻圣明」的「耻」是意动用法，意为「以……为耻」，不能只解作「耻辱」。"},{"w":"羡鱼","e":"【易错】「徒有羡鱼情」的「羡鱼」典出《淮南子》「临河而羡鱼，不如归家织网」，喻指空想不如行动，此处指自己空有出仕之愿而无人引荐。"},{"w":"济","e":"是渡"},{"w":"蒸","e":"【易错】「气蒸云梦泽」的「蒸」是草字头，指水汽蒸腾，不写成「烝」。"},{"w":"烝","e":"【易错】「气蒸云梦泽」的「蒸」是草字头，指水汽蒸腾，不写成「烝」。"},{"w":"撼","e":"【易错】「波撼岳阳城」的「撼」是提手旁，指摇动、震动，不写「憾」。"},{"w":"憾","e":"【易错】「波撼岳阳城」的「撼」是提手旁，指摇动、震动，不写「憾」。"},{"w":"混","e":"【易错】「涵虚混太清」的「混」读 hùn，是混同、融为一体之意；「太清」指天空，不可解作「太清静」。"},{"w":"楫","e":"【易错】「欲济无舟楫」的「楫」读 jí，是木字旁，指船桨，代指船，不写「揖」。"},{"w":"揖","e":"【易错】「欲济无舟楫」的「楫」读 jí，是木字旁，指船桨，代指船，不写「揖」。"},{"w":"耻","e":"【易错】「端居耻圣明」的「耻」是意动用法，意为「以……为耻」，不能只解作「耻辱」。"}]},{"type":"list","title":"名句","items":["气蒸云梦泽，波撼岳阳城。","坐观垂钓者，徒有羡鱼情。"]},{"type":"list","title":"背诵提示","items":["「气蒸云梦泽」的「蒸」是草字头，指水汽蒸腾，不写成「烝」。","「波撼岳阳城」的「撼」是提手旁，指摇动、震动，不写「憾」。","「涵虚混太清」的「混」读 hùn，是混同、融为一体之意；「太清」指天空，不可解作「太清静」。","「欲济无舟楫」的「楫」读 jí，是木字旁，指船桨，代指船，不写「揖」。","「端居耻圣明」的「耻」是意动用法，意为「以……为耻」，不能只解作「耻辱」。","「徒有羡鱼情」的「羡鱼」典出《淮南子》「临河而羡鱼，不如归家织网」，喻指空想不如行动，此处指自己空有出仕之愿而无人引荐。"]}],"questions":[{"id":"p-p8b-wang-dong-ting-hu-m0","type":"fill","stem":"默写填空：气蒸云梦泽，______。","answer":"波撼岳阳城。","explain":"出自《望洞庭湖赠张丞相》（唐·孟浩然）：气蒸云梦泽，波撼岳阳城。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-wang-dong-ting-hu-m1","type":"fill","stem":"默写填空：坐观垂钓者，______。","answer":"徒有羡鱼情。","explain":"出自《望洞庭湖赠张丞相》（唐·孟浩然）：坐观垂钓者，徒有羡鱼情。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8b-wang-dong-ting-hu-u","type":"fill","stem":"理解性默写：八月洞庭湖水盛涨，水面与湖岸齐平；湖水涵容着天空，水色与天色浑然一片。「涵虚」指水映天空，「太清」指天空。","answer":"八月湖水平，涵虚混太清。","explain":"出自《望洞庭湖赠张丞相》（唐·孟浩然）。句意：八月洞庭湖水盛涨，水面与湖岸齐平；湖水涵容着天空，水色与天色浑然一片。「涵虚」指水映天空，「太清」指天空。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p-extra-song-du-shaofu","title":"送杜少府之任蜀州","subtitle":"唐·王勃","grade":"8b","tags":["送别","友情","赠别","豁达"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·王勃"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"王勃（650—676），字子安，绛州龙门（今山西河津）人，唐代诗人、骈文家，“初唐四杰”之首，与杨炯、卢照邻、骆宾王并称。\n生平经历：他少年时便以文才知名，未满二十岁即应举及第，先后任朝散郎、虢州参军；因戏作讨伐英王鸡的檄文而被逐出沛王府，又因擅杀官奴获罪免官，父亲也受牵连被贬到交趾；上元二年他南下探父，次年渡海溺水，惊悸而死，年仅二十七岁，是文学史上著名的英年早逝者。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是王勃在长安送友人赴蜀地任职时所作，是初唐五言律诗的名篇。首联「城阙辅三秦，风烟望五津」一在长安、一在蜀地，用「望」字把相隔千里的两地纳入同一画面，气象开阔，一个「辅」字写出长安地势的雄壮；颔联「与君离别意，同是宦游人」由景入情，以「同是宦游人」的共感宽慰友人，把个人离愁放进共同境遇中化解；颈联「海内存知己，天涯若比邻」一反送别诗的低回悲酸，以哲理化的襟怀把友情提升到超越空间的高度，成为千古名句；尾联「无为在歧路，儿女共沾巾」以劝勉作结，豪迈而不作悲声。中考常考：颈联的哲理与豁达胸襟、全诗一改传统送别诗悲凉基调的写法、「辅」「望」的炼字，以及「阙」「宦」「己」「歧」等易错字形。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"城阙辅三秦，风烟望五津。","n":"","cn":"三秦之地护卫着巍峨的长安城，透过迷蒙的风烟遥望蜀地的五个渡口。","parts":[{"t":"城阙","k":1},{"t":"辅","k":13},{"t":"三秦","k":2},{"t":"，"},{"t":"风烟","k":10},{"t":"望"},{"t":"五津","k":3},{"t":"。"}]},{"t":"与君离别意，同是宦游人。","n":"","cn":"你我同是远离家乡、在外做官的人，此刻怀着同样的离别愁绪。","parts":[{"t":"与"},{"t":"君","k":14},{"t":"离别意，同是"},{"t":"宦游人","k":0},{"t":"。"}]},{"t":"海内存知己，天涯若比邻。","n":"","cn":"只要四海之内还有你这样的知心朋友，即使远在天边，也像近邻一样亲近。","parts":[{"t":"海内","k":4},{"t":"存"},{"t":"知己","k":5},{"t":"，天"},{"t":"涯","k":28},{"t":"若"},{"t":"比邻","k":6},{"t":"。"}]},{"t":"无为在歧路，儿女共沾巾。","n":"","cn":"不必在分手的岔路口上，像小儿女那样让泪水沾湿了手巾。","parts":[{"t":"无为","k":7},{"t":"在"},{"t":"歧路","k":8},{"t":"，儿女共"},{"t":"沾巾","k":9},{"t":"。"}]}],"words":[{"w":"宦游人","e":"为求官而漂泊在外的人"},{"w":"城阙","e":"指长安城"},{"w":"三秦","e":"指关中一带"},{"w":"五津","e":"岷江上的五个渡口，代指友人要去的蜀地"},{"w":"海内","e":"四海之内，指全国"},{"w":"知己","e":"知心朋友"},{"w":"比邻","e":"紧挨着的邻居"},{"w":"无为","e":"不要"},{"w":"歧路","e":"岔路口，指分手之处"},{"w":"沾巾","e":"泪水沾湿手巾"},{"w":"风烟","e":"【易错】「风烟望五津」的「风烟」指迷蒙的风尘烟雾，不要写成「烽烟」（烽烟指战火）；「津」是三点水，指渡口。"},{"w":"烽烟","e":"【易错】「风烟望五津」的「风烟」指迷蒙的风尘烟雾，不要写成「烽烟」（烽烟指战火）；「津」是三点水，指渡口。"},{"w":"彼邻","e":"【易错】「天涯若比邻」的「涯」是三点水，不要写成「崖」；「比邻」指近邻，不要写成「彼邻」。"},{"w":"辅","e":"护卫、拱卫"},{"w":"君","e":"对人的尊称，指杜少府"},{"w":"阙","e":"【易错】「城阙辅三秦」的「阙」是「门」内「欮」，不要写成「阕」；「辅」是「车」字旁，指护卫，不要写成「抚」。"},{"w":"门","e":"【易错】「城阙辅三秦」的「阙」是「门」内「欮」，不要写成「阕」；「辅」是「车」字旁，指护卫，不要写成「抚」。"},{"w":"欮","e":"【易错】「城阙辅三秦」的「阙」是「门」内「欮」，不要写成「阕」；「辅」是「车」字旁，指护卫，不要写成「抚」。"},{"w":"阕","e":"【易错】「城阙辅三秦」的「阙」是「门」内「欮」，不要写成「阕」；「辅」是「车」字旁，指护卫，不要写成「抚」。"},{"w":"车","e":"【易错】「城阙辅三秦」的「阙」是「门」内「欮」，不要写成「阕」；「辅」是「车」字旁，指护卫，不要写成「抚」。"},{"w":"抚","e":"【易错】「城阙辅三秦」的「阙」是「门」内「欮」，不要写成「阕」；「辅」是「车」字旁，指护卫，不要写成「抚」。"},{"w":"津","e":"【易错】「风烟望五津」的「风烟」指迷蒙的风尘烟雾，不要写成「烽烟」（烽烟指战火）；「津」是三点水，指渡口。"},{"w":"宦","e":"【易错】「同是宦游人」的「宦」是宝盖头下「臣」，指做官，不要写成「官」「臣」。"},{"w":"臣","e":"【易错】「同是宦游人」的「宦」是宝盖头下「臣」，指做官，不要写成「官」「臣」。"},{"w":"官","e":"【易错】「同是宦游人」的「宦」是宝盖头下「臣」，指做官，不要写成「官」「臣」。"},{"w":"己","e":"【易错】「海内存知己」的「己」是自己的「己」，不要写成「已」「巳」。"},{"w":"已","e":"【易错】「海内存知己」的「己」是自己的「己」，不要写成「已」「巳」。"},{"w":"巳","e":"【易错】「海内存知己」的「己」是自己的「己」，不要写成「已」「巳」。"},{"w":"涯","e":"【易错】「天涯若比邻」的「涯」是三点水，不要写成「崖」；「比邻」指近邻，不要写成「彼邻」。"},{"w":"崖","e":"【易错】「天涯若比邻」的「涯」是三点水，不要写成「崖」；「比邻」指近邻，不要写成「彼邻」。"},{"w":"歧","e":"【易错】「无为在歧路」的「歧」是「止」旁加「支」，不要写成「岐」（课文中作「歧路」）。"},{"w":"止","e":"【易错】「无为在歧路」的「歧」是「止」旁加「支」，不要写成「岐」（课文中作「歧路」）。"},{"w":"支","e":"【易错】「无为在歧路」的「歧」是「止」旁加「支」，不要写成「岐」（课文中作「歧路」）。"},{"w":"岐","e":"【易错】「无为在歧路」的「歧」是「止」旁加「支」，不要写成「岐」（课文中作「歧路」）。"},{"w":"沾","e":"【易错】「儿女共沾巾」的「沾」是三点水，指沾湿，不要写成「粘」「毡」。"},{"w":"粘","e":"【易错】「儿女共沾巾」的「沾」是三点水，指沾湿，不要写成「粘」「毡」。"},{"w":"毡","e":"【易错】「儿女共沾巾」的「沾」是三点水，指沾湿，不要写成「粘」「毡」。"}]},{"type":"list","title":"名句","items":["海内存知己，天涯若比邻。"]},{"type":"list","title":"背诵提示","items":["「城阙辅三秦」的「阙」是「门」内「欮」，不要写成「阕」；「辅」是「车」字旁，指护卫，不要写成「抚」。","「风烟望五津」的「风烟」指迷蒙的风尘烟雾，不要写成「烽烟」（烽烟指战火）；「津」是三点水，指渡口。","「同是宦游人」的「宦」是宝盖头下「臣」，指做官，不要写成「官」「臣」。","「海内存知己」的「己」是自己的「己」，不要写成「已」「巳」。","「天涯若比邻」的「涯」是三点水，不要写成「崖」；「比邻」指近邻，不要写成「彼邻」。","「无为在歧路」的「歧」是「止」旁加「支」，不要写成「岐」（课文中作「歧路」）。","「儿女共沾巾」的「沾」是三点水，指沾湿，不要写成「粘」「毡」。"]}],"questions":[{"id":"p-p-extra-song-du-shaofu-m0","type":"fill","stem":"默写填空：海内存知己，______。","answer":"天涯若比邻。","explain":"出自《送杜少府之任蜀州》（唐·王勃）：海内存知己，天涯若比邻。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p-extra-song-du-shaofu-u","type":"fill","stem":"理解性默写：三秦之地护卫着巍峨的长安城，透过迷蒙的风烟遥望蜀地的五个渡口。","answer":"城阙辅三秦，风烟望五津。","explain":"出自《送杜少府之任蜀州》（唐·王勃）。句意：三秦之地护卫着巍峨的长安城，透过迷蒙的风烟遥望蜀地的五个渡口。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p-extra-baixuege","title":"白雪歌送武判官归京","subtitle":"唐·岑参","grade":"9a","tags":["送别","边塞","咏雪","写景"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"唐·岑参"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"岑参（约715—770），荆州江陵（今湖北江陵）人，唐代边塞诗派代表诗人。他与高适并称“高岑”，因官至嘉州刺史，世称“岑嘉州”。\n生平经历：天宝年间中进士，曾两次出塞，先后在安西节度使高仙芝、封常清幕府中任职，长年往来于轮台、雪海之间；安史之乱后回朝任右补阙等职，后出任嘉州刺史，罢官后客死成都。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是一首咏雪兼送别的七言歌行，以「雪」为线索贯穿全篇。前十句写边塞奇寒：「北风卷地白草折」写风之猛；「忽如一夜春风来，千树万树梨花开」以春花喻冬雪，比喻新奇，化苦寒为明丽，是千古咏雪名句；「散入珠帘」「狐裘不暖」由外景转入帐内，写军营酷寒；「瀚海阑干百丈冰，愁云惨淡万里凝」以夸张、对偶写沙漠冰封、阴云密布，为送别渲染气氛。后八句写送别：「中军置酒饮归客」写饯别之盛，「风掣红旗冻不翻」以红旗冻住的细节反衬极寒；结句「山回路转不见君，雪上空留马行处」以景结情，含蓄传出惜别之深。中考常考：比喻、夸张的写景手法，以雪衬别的情景交融，结句「空留」的表达效果，以及「衾」「瀚」「阑干」「羌」「掣」等字的音形。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"北风卷地白草折，胡天八月即飞雪。","n":"","cn":"北风席卷大地，把白草都吹断了；塞北的天空在八月就飘起了大雪。","parts":[{"t":"北风卷地"},{"t":"白草折","k":4},{"t":"，"},{"t":"胡天","k":6},{"t":"八月即飞雪。"}]},{"t":"忽如一夜春风来，千树万树梨花开。","n":"","cn":"忽然像一夜之间春风吹来，千树万树的白花一齐盛开（以梨花喻雪）。","parts":[{"t":"忽如","k":7},{"t":"一夜春风来，千树万树梨花开。"}]},{"t":"散入珠帘湿罗幕，狐裘不暖锦衾薄。","n":"","cn":"雪花飘进珠帘，打湿了丝织的帐幕；狐皮袍子不觉得暖和，锦缎被子也显得单薄。","parts":[{"t":"散入"},{"t":"珠帘","k":8},{"t":"湿"},{"t":"罗幕","k":9},{"t":"，"},{"t":"狐裘","k":10},{"t":"不暖"},{"t":"锦衾","k":11},{"t":"薄。"}]},{"t":"将军角弓不得控，都护铁衣冷难着。","n":"","cn":"将军的角弓冻得拉不开，都护的铁甲冷得难以穿上。","parts":[{"t":"将军"},{"t":"角弓","k":12},{"t":"不得"},{"t":"控","k":28},{"t":"，"},{"t":"都护","k":13},{"t":"铁衣","k":14},{"t":"冷难"},{"t":"着","k":44},{"t":"。"}]},{"t":"瀚海阑干百丈冰，愁云惨淡万里凝。","n":"","cn":"沙漠上纵横交错地结着百丈坚冰，万里长空凝结着昏暗惨淡的愁云。","parts":[{"t":"瀚海","k":15},{"t":"阑干","k":16},{"t":"百丈冰，愁云"},{"t":"惨淡","k":17},{"t":"万里"},{"t":"凝","k":29},{"t":"。"}]},{"t":"中军置酒饮归客，胡琴琵琶与羌笛。","n":"","cn":"在主帅的营帐里摆下酒宴，为回京的客人饯行，胡琴、琵琶和羌笛一齐奏响。","parts":[{"t":"中军","k":18},{"t":"置酒","k":19},{"t":"饮归客","k":1},{"t":"，胡琴"},{"t":"琵","k":54},{"t":"琶","k":55},{"t":"与"},{"t":"羌笛","k":20},{"t":"。"}]},{"t":"纷纷暮雪下辕门，风掣红旗冻不翻。","n":"","cn":"傍晚时分，大雪纷纷飘落辕门，红旗被风扯动却因冻硬而不能翻卷。","parts":[{"t":"纷纷"},{"t":"暮","k":35},{"t":"雪下"},{"t":"辕门","k":21},{"t":"，风"},{"t":"掣","k":30},{"t":"红旗"},{"t":"冻不翻","k":2},{"t":"。"}]},{"t":"轮台东门送君去，去时雪满天山路。","n":"","cn":"在轮台东门送你离去，你走的时候大雪铺满了天山的道路。","parts":[{"t":"轮台","k":22},{"t":"东门送"},{"t":"君","k":31},{"t":"去，去时雪满"},{"t":"天山","k":23},{"t":"路。"}]},{"t":"山回路转不见君，雪上空留马行处。","n":"","cn":"山势回环、道路曲折，转眼就看不见你了，雪地上只空留着一行马蹄印。","parts":[{"t":"山回路转","k":0},{"t":"不见"},{"t":"君","k":31},{"t":"，雪上"},{"t":"空","k":43},{"t":"留","k":59},{"t":"马行处","k":3},{"t":"。"}]}],"words":[{"w":"山回路转","e":"山势回环、道路跟着转弯"},{"w":"饮归客","e":"宴请归京的客人，饮读 yìn"},{"w":"冻不翻","e":"冻得僵硬不能飘动"},{"w":"马行处","e":"马走过留下的蹄印"},{"w":"白草折","e":"【易错】「白草折」的「折」读 zhé，指折断，不要写成「拆」。"},{"w":"白草","e":"西域的一种牧草，干枯后呈白色"},{"w":"胡天","e":"塞北的天空"},{"w":"忽如","e":"忽然好像"},{"w":"珠帘","e":"用珠子串成的帘子"},{"w":"罗幕","e":"丝织的帐幕"},{"w":"狐裘","e":"狐皮袍子"},{"w":"锦衾","e":"锦缎被子，衾读 qīn"},{"w":"角弓","e":"用兽角装饰的硬弓"},{"w":"都护","e":"唐代镇守边疆的最高长官"},{"w":"铁衣","e":"铠甲"},{"w":"瀚海","e":"沙漠"},{"w":"阑干","e":"纵横交错的样子"},{"w":"惨淡","e":"昏暗无光"},{"w":"中军","e":"主帅的营帐"},{"w":"置酒","e":"摆设酒宴"},{"w":"羌笛","e":"羌族的管乐器"},{"w":"辕门","e":"军营的大门"},{"w":"轮台","e":"地名，在今新疆"},{"w":"天山","e":"横贯新疆的山脉"},{"w":"都督","e":"【易错】「都护铁衣冷难着」的「着」读 zhuó，指穿，教材作「着」，不要写成「著」；「都护」不要写成「都督」。"},{"w":"栏干","e":"【易错】「瀚海阑干百丈冰」的「瀚海」指沙漠，两字都是三点水；「阑干」是纵横交错的样子，不要写成「栏干」。"},{"w":"比巴","e":"【易错】「胡琴琵琶与羌笛」的「羌」上部是「羊」，不要写成「姜」；「琵」「琶」上面都是两个「王」，不要写成「比巴」。"},{"w":"折","e":"折断"},{"w":"控","e":"拉开（弓）"},{"w":"凝","e":"凝结"},{"w":"掣","e":"拉、扯，读 chè"},{"w":"君","e":"指武判官"},{"w":"拆","e":"【易错】「白草折」的「折」读 zhé，指折断，不要写成「拆」。"},{"w":"幕","e":"【易错】「散入珠帘湿罗幕」的「幕」下面是「巾」，不要写成「暮」「墓」；「帘」是穴宝盖，不要写成「莲」。"},{"w":"巾","e":"【易错】「散入珠帘湿罗幕」的「幕」下面是「巾」，不要写成「暮」「墓」；「帘」是穴宝盖，不要写成「莲」。"},{"w":"暮","e":"【易错】「散入珠帘湿罗幕」的「幕」下面是「巾」，不要写成「暮」「墓」；「帘」是穴宝盖，不要写成「莲」。"},{"w":"墓","e":"【易错】「散入珠帘湿罗幕」的「幕」下面是「巾」，不要写成「暮」「墓」；「帘」是穴宝盖，不要写成「莲」。"},{"w":"帘","e":"【易错】「散入珠帘湿罗幕」的「幕」下面是「巾」，不要写成「暮」「墓」；「帘」是穴宝盖，不要写成「莲」。"},{"w":"莲","e":"【易错】「散入珠帘湿罗幕」的「幕」下面是「巾」，不要写成「暮」「墓」；「帘」是穴宝盖，不要写成「莲」。"},{"w":"衾","e":"【易错】「狐裘不暖锦衾薄」的「衾」读 qīn，上面是「今」下面是「衣」，指被子，不要与「裘」（皮衣）混用。"},{"w":"今","e":"【易错】「狐裘不暖锦衾薄」的「衾」读 qīn，上面是「今」下面是「衣」，指被子，不要与「裘」（皮衣）混用。"},{"w":"衣","e":"【易错】「狐裘不暖锦衾薄」的「衾」读 qīn，上面是「今」下面是「衣」，指被子，不要与「裘」（皮衣）混用。"},{"w":"裘","e":"【易错】「狐裘不暖锦衾薄」的「衾」读 qīn，上面是「今」下面是「衣」，指被子，不要与「裘」（皮衣）混用。"},{"w":"空","e":"【易错】「将军角弓不得控」的「控」是提手旁，指拉开（弓），不要写成「空」。"},{"w":"着","e":"【易错】「都护铁衣冷难着」的「着」读 zhuó，指穿，教材作「着」，不要写成「著」；「都护」不要写成「都督」。"},{"w":"著","e":"【易错】「都护铁衣冷难着」的「着」读 zhuó，指穿，教材作「着」，不要写成「著」；「都护」不要写成「都督」。"},{"w":"惨","e":"【易错】「愁云惨淡万里凝」的「惨」是竖心旁，不要写成「残」；「凝」是两点水，不要写成「疑」。"},{"w":"残","e":"【易错】「愁云惨淡万里凝」的「惨」是竖心旁，不要写成「残」；「凝」是两点水，不要写成「疑」。"},{"w":"疑","e":"【易错】「愁云惨淡万里凝」的「惨」是竖心旁，不要写成「残」；「凝」是两点水，不要写成「疑」。"},{"w":"饮","e":"【易错】「中军置酒饮归客」的「饮」读 yìn，是拿酒给人喝、宴请，不要写成「引」。"},{"w":"引","e":"【易错】「中军置酒饮归客」的「饮」读 yìn，是拿酒给人喝、宴请，不要写成「引」。"},{"w":"羌","e":"【易错】「胡琴琵琶与羌笛」的「羌」上部是「羊」，不要写成「姜」；「琵」「琶」上面都是两个「王」，不要写成「比巴」。"},{"w":"羊","e":"【易错】「胡琴琵琶与羌笛」的「羌」上部是「羊」，不要写成「姜」；「琵」「琶」上面都是两个「王」，不要写成「比巴」。"},{"w":"姜","e":"【易错】「胡琴琵琶与羌笛」的「羌」上部是「羊」，不要写成「姜」；「琵」「琶」上面都是两个「王」，不要写成「比巴」。"},{"w":"琵","e":"【易错】「胡琴琵琶与羌笛」的「羌」上部是「羊」，不要写成「姜」；「琵」「琶」上面都是两个「王」，不要写成「比巴」。"},{"w":"琶","e":"【易错】「胡琴琵琶与羌笛」的「羌」上部是「羊」，不要写成「姜」；「琵」「琶」上面都是两个「王」，不要写成「比巴」。"},{"w":"王","e":"【易错】「胡琴琵琶与羌笛」的「羌」上部是「羊」，不要写成「姜」；「琵」「琶」上面都是两个「王」，不要写成「比巴」。"},{"w":"挚","e":"【易错】「风掣红旗冻不翻」的「掣」读 chè，是拉、扯，不要写成「挚」「制」。"},{"w":"制","e":"【易错】「风掣红旗冻不翻」的「掣」读 chè，是拉、扯，不要写成「挚」「制」。"},{"w":"留","e":"【易错】「雪上空留马行处」的「留」不要写成「流」。"},{"w":"流","e":"【易错】「雪上空留马行处」的「留」不要写成「流」。"}]},{"type":"list","title":"名句","items":["忽如一夜春风来，千树万树梨花开。","山回路转不见君，雪上空留马行处。"]},{"type":"list","title":"背诵提示","items":["「白草折」的「折」读 zhé，指折断，不要写成「拆」。","「忽如一夜春风来」教材作「忽如」，不要写成「忽然一夜春风来」。","「散入珠帘湿罗幕」的「幕」下面是「巾」，不要写成「暮」「墓」；「帘」是穴宝盖，不要写成「莲」。","「狐裘不暖锦衾薄」的「衾」读 qīn，上面是「今」下面是「衣」，指被子，不要与「裘」（皮衣）混用。","「将军角弓不得控」的「控」是提手旁，指拉开（弓），不要写成「空」。","「都护铁衣冷难着」的「着」读 zhuó，指穿，教材作「着」，不要写成「著」；「都护」不要写成「都督」。","「瀚海阑干百丈冰」的「瀚海」指沙漠，两字都是三点水；「阑干」是纵横交错的样子，不要写成「栏干」。","「愁云惨淡万里凝」的「惨」是竖心旁，不要写成「残」；「凝」是两点水，不要写成「疑」。","「中军置酒饮归客」的「饮」读 yìn，是拿酒给人喝、宴请，不要写成「引」。","「胡琴琵琶与羌笛」的「羌」上部是「羊」，不要写成「姜」；「琵」「琶」上面都是两个「王」，不要写成「比巴」。","「风掣红旗冻不翻」的「掣」读 chè，是拉、扯，不要写成「挚」「制」。","「雪上空留马行处」的「留」不要写成「流」。"]}],"questions":[{"id":"p-p-extra-baixuege-m0","type":"fill","stem":"默写填空：忽如一夜春风来，______。","answer":"千树万树梨花开。","explain":"出自《白雪歌送武判官归京》（唐·岑参）：忽如一夜春风来，千树万树梨花开。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p-extra-baixuege-m1","type":"fill","stem":"默写填空：山回路转不见君，______。","answer":"雪上空留马行处。","explain":"出自《白雪歌送武判官归京》（唐·岑参）：山回路转不见君，雪上空留马行处。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p-extra-baixuege-u","type":"fill","stem":"理解性默写：北风席卷大地，把白草都吹断了；塞北的天空在八月就飘起了大雪。","answer":"北风卷地白草折，胡天八月即飞雪。","explain":"出自《白雪歌送武判官归京》（唐·岑参）。句意：北风席卷大地，把白草都吹断了；塞北的天空在八月就飘起了大雪。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p-extra-xiangjianhuan","title":"相见欢（无言独上西楼）","subtitle":"五代·李煜","grade":"8a","tags":["离愁","婉约","亡国","抒情"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"五代·李煜"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"李煜（937—978），字重光，号钟隐、莲峰居士，五代时期南唐最后一位国君，世称“李后主”，是婉约词的代表词人。\n生平经历：二十五岁即位，在位十五年；宋军攻破金陵后出降，被俘至汴京，被封为违命侯，过了两年多囚居生活，后被赐毒酒而死。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是李煜亡国被囚于汴京时所作，写亡国之君的孤寂与离愁。「无言独上西楼」点出人物与动作，「无言」二字写透无人可诉的凄凉；「寂寞梧桐深院锁清秋」中一个「锁」字最为传神，既写深院锁住秋色，更暗写自身被幽囚的处境，情景交融。下片「剪不断，理还乱，是离愁」以丝喻愁，把无形的愁绪化为可触可感的形象，是写愁的千古妙笔；结句「别是一般滋味在心头」不直说愁苦，只说「别是一般滋味」，含蓄深沉。全词白描如话，字字含泪，是婉约词名篇。中考常考：「锁」字的表达效果、以丝喻愁的比喻及其作用、亡国之痛与离愁交织的情感，注意「钩」「锁」「断」的字形，以及「别是一般」不作「别是一番」。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"无言独上西楼，月如钩。","n":"","cn":"我默默无言，独自登上西楼，一弯新月像银钩一样挂在天上。","parts":[{"t":"无言独上"},{"t":"西楼","k":5},{"t":"，"},{"t":"月如钩","k":0},{"t":"。"}]},{"t":"寂寞梧桐深院锁清秋。","n":"","cn":"寂寞的梧桐树，幽深的庭院，把这一片清冷的秋色紧紧锁住。","parts":[{"t":"寂寞","k":6},{"t":"梧桐深院"},{"t":"锁清秋","k":3},{"t":"。"}]},{"t":"剪不断，理还乱，是离愁。","n":"","cn":"那剪也剪不断、理了还是乱的，正是离别的愁绪。","parts":[{"t":"剪不断","k":1},{"t":"，"},{"t":"理还乱","k":2},{"t":"，是"},{"t":"离愁","k":8},{"t":"。"}]},{"t":"别是一般滋味在心头。","n":"","cn":"那别有一番难以言说的滋味，久久地留在心头。","parts":[{"t":"别是","k":9},{"t":"一般","k":10},{"t":"滋味","k":11},{"t":"在心头","k":4},{"t":"。"}]}],"words":[{"w":"月如钩","e":"形容残月弯弯如钩"},{"w":"剪不断","e":"用剪刀也剪不断"},{"w":"理还乱","e":"梳理之后依旧纷乱"},{"w":"锁清秋","e":"【易错】「寂寞梧桐深院锁清秋」的「锁」是金字旁，不要写成「琐」「销」；教材作「锁清秋」，不要写成「深秋」。"},{"w":"在心头","e":"【易错】「别是一般滋味」的「滋味」不要写成「知味」；不要漏写句末的「在心头」。"},{"w":"西楼","e":"指词人当时的居所"},{"w":"寂寞","e":"冷清孤单"},{"w":"清秋","e":"清冷的秋色"},{"w":"离愁","e":"离别的愁苦"},{"w":"别是","e":"另是、别有一番"},{"w":"一般","e":"一种（这番）"},{"w":"滋味","e":"感受、况味"},{"w":"深秋","e":"【易错】「寂寞梧桐深院锁清秋」的「锁」是金字旁，不要写成「琐」「销」；教材作「锁清秋」，不要写成「深秋」。"},{"w":"一种","e":"【易错】「别是一般滋味在心头」的「一般」意为「一种」，教材作「一般」，不要写成「一番」。"},{"w":"一番","e":"【易错】「别是一般滋味在心头」的「一般」意为「一种」，教材作「一般」，不要写成「一番」。"},{"w":"知味","e":"【易错】「别是一般滋味」的「滋味」不要写成「知味」；不要漏写句末的「在心头」。"},{"w":"锁","e":"锁住、囚锁，既写深院锁住秋色，也暗写自己被幽囚的处境"},{"w":"钩","e":"【易错】「月如钩」的「钩」是金字旁，指弯月如钩，不要写成「勾」。"},{"w":"勾","e":"【易错】「月如钩」的「钩」是金字旁，指弯月如钩，不要写成「勾」。"},{"w":"琐","e":"【易错】「寂寞梧桐深院锁清秋」的「锁」是金字旁，不要写成「琐」「销」；教材作「锁清秋」，不要写成「深秋」。"},{"w":"销","e":"【易错】「寂寞梧桐深院锁清秋」的「锁」是金字旁，不要写成「琐」「销」；教材作「锁清秋」，不要写成「深秋」。"},{"w":"剪","e":"【易错】「剪不断」的「剪」下面是「刀」，不要写成「箭」；「断」不要写成「段」。"},{"w":"刀","e":"【易错】「剪不断」的「剪」下面是「刀」，不要写成「箭」；「断」不要写成「段」。"},{"w":"箭","e":"【易错】「剪不断」的「剪」下面是「刀」，不要写成「箭」；「断」不要写成「段」。"},{"w":"断","e":"【易错】「剪不断」的「剪」下面是「刀」，不要写成「箭」；「断」不要写成「段」。"},{"w":"段","e":"【易错】「剪不断」的「剪」下面是「刀」，不要写成「箭」；「断」不要写成「段」。"},{"w":"还","e":"【易错】「理还乱」的「还」是「仍旧、依然」的意思，不要写成「环」；「乱」不要写成「乩」。"},{"w":"环","e":"【易错】「理还乱」的「还」是「仍旧、依然」的意思，不要写成「环」；「乱」不要写成「乩」。"},{"w":"乱","e":"【易错】「理还乱」的「还」是「仍旧、依然」的意思，不要写成「环」；「乱」不要写成「乩」。"},{"w":"乩","e":"【易错】「理还乱」的「还」是「仍旧、依然」的意思，不要写成「环」；「乱」不要写成「乩」。"}]},{"type":"list","title":"名句","items":["剪不断，理还乱，是离愁。","别是一般滋味在心头。"]},{"type":"list","title":"背诵提示","items":["「月如钩」的「钩」是金字旁，指弯月如钩，不要写成「勾」。","「寂寞梧桐深院锁清秋」的「锁」是金字旁，不要写成「琐」「销」；教材作「锁清秋」，不要写成「深秋」。","「剪不断」的「剪」下面是「刀」，不要写成「箭」；「断」不要写成「段」。","「理还乱」的「还」是「仍旧、依然」的意思，不要写成「环」；「乱」不要写成「乩」。","「别是一般滋味在心头」的「一般」意为「一种」，教材作「一般」，不要写成「一番」。","「别是一般滋味」的「滋味」不要写成「知味」；不要漏写句末的「在心头」。"]}],"questions":[{"id":"p-p-extra-xiangjianhuan-m0","type":"fill","stem":"默写填空：剪不断，______。","answer":"理还乱。","explain":"出自《相见欢（无言独上西楼）》（五代·李煜）：剪不断，理还乱，是离愁。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p-extra-xiangjianhuan-u","type":"fill","stem":"理解性默写：我默默无言，独自登上西楼，一弯新月像银钩一样挂在天上。","answer":"无言独上西楼，月如钩。","explain":"出自《相见欢（无言独上西楼）》（五代·李煜）。句意：我默默无言，独自登上西楼，一弯新月像银钩一样挂在天上。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p-extra-huanshaxi-yanshu","title":"浣溪沙（一曲新词酒一杯）","subtitle":"宋·晏殊","grade":"8a","tags":["伤春","惜时","怀旧","哲理"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·晏殊"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"晏殊（991—1055），字同叔，北宋政治家、文学家，抚州临川（今江西抚州）人，谥号元献，与其子晏几道并称“二晏”。\n生平经历：十四岁以神童被推荐参加廷试，赐同进士出身；此后仕途较为顺达，官至同平章事，也曾多次被贬外任；他重视兴办学校与选拔人才，范仲淹、欧阳修等都曾受其赏识。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是晏殊的代表作，写伤春怀旧之情。「一曲新词酒一杯，去年天气旧亭台」以「新」与「旧」相对照：词曲与新酒是当下的，天气与亭台依旧如昨，在闲雅的宴饮中引出时光不居的怅惘；「夕阳西下几时回？」以疑问句直问落日，把对时光流逝的惋惜写得含蓄悠长。下片「无可奈何花落去，似曾相识燕归来」对仗工巧，花落写消逝的惋惜，燕归写重现的欣慰，在「变」与「不变」的交织中道出哲理，被誉为「天然奇偶」，是千古名句；结句「小园香径独徘徊」以人物孤独的身影与徘徊的动作收束全词，情在言外。中考常考：名句所含的哲理、「新」「旧」对照的作用、以景结情与含蓄抒情的手法，注意「奈」「曾」「燕」「徘徊」等字的音形。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"一曲新词酒一杯，去年天气旧亭台。","n":"","cn":"唱一曲新填的词，饮一杯美酒；天气还是去年那样的天气，亭台也还是旧日的亭台。","parts":[{"t":"一曲"},{"t":"新词","k":6},{"t":"酒一"},{"t":"杯","k":29},{"t":"，去年天气"},{"t":"旧亭台","k":4},{"t":"。"}]},{"t":"夕阳西下几时回？","n":"","cn":"夕阳向西边落下，什么时候才能再回来呢？几时回：什么时候回来，以问句写对时光流逝的惋惜。","parts":[{"t":"夕阳西下"},{"t":"几时","k":12},{"t":"回？"}]},{"t":"无可奈何花落去，似曾相识燕归来。","n":"","cn":"花儿无可奈何地凋落，那似曾相识的燕子又飞回来了。","parts":[{"t":"无可奈何","k":0},{"t":"花落去，"},{"t":"似曾相识","k":1},{"t":"燕归来","k":5},{"t":"。"}]},{"t":"小园香径独徘徊。","n":"","cn":"我独自在花园中满是落花香气的幽径上徘徊。","parts":[{"t":"小园"},{"t":"香径","k":7},{"t":"独"},{"t":"徘徊","k":8},{"t":"。"}]}],"words":[{"w":"无可奈何","e":"没有办法、无法挽回"},{"w":"似曾相识","e":"好像曾经见过"},{"w":"什么时候","e":"【易错】「夕阳西下几时回」的「几时」是「什么时候」，不要写成「及时」。"},{"w":"无可耐何","e":"【易错】「无可奈何」的「奈」是「大」下「示」，不要写成「耐」，也不要写成「无可耐何」。"},{"w":"旧亭台","e":"往日的亭台"},{"w":"燕归来","e":"【易错】「燕归来」的「燕」指燕子，不要写成「雁」（大雁）。"},{"w":"新词","e":"新填写的词"},{"w":"香径","e":"落花飘香的花园小径"},{"w":"徘徊","e":"来回走动，写出内心的怅惘"},{"w":"亭台","e":"【易错】「去年天气旧亭台」的「亭台」不要写成「停台」「亭苔」。"},{"w":"停台","e":"【易错】「去年天气旧亭台」的「亭台」不要写成「停台」「亭苔」。"},{"w":"亭苔","e":"【易错】「去年天气旧亭台」的「亭台」不要写成「停台」「亭苔」。"},{"w":"几时","e":"【易错】「夕阳西下几时回」的「几时」是「什么时候」，不要写成「及时」。"},{"w":"及时","e":"【易错】「夕阳西下几时回」的「几时」是「什么时候」，不要写成「及时」。"},{"w":"曾经","e":"【易错】「似曾相识」的「曾」读 céng，是「曾经」，不要写成「层」；「识」不要写成「织」。"},{"w":"俳徊","e":"【易错】「小园香径独徘徊」的「径」是双人旁，不要写成「经」；「徘徊」两字都是双人旁，不要写成「俳徊」「裴回」。"},{"w":"裴回","e":"【易错】「小园香径独徘徊」的「径」是双人旁，不要写成「经」；「徘徊」两字都是双人旁，不要写成「俳徊」「裴回」。"},{"w":"奈","e":"【易错】「无可奈何」的「奈」是「大」下「示」，不要写成「耐」，也不要写成「无可耐何」。"},{"w":"大","e":"【易错】「无可奈何」的「奈」是「大」下「示」，不要写成「耐」，也不要写成「无可耐何」。"},{"w":"示","e":"【易错】「无可奈何」的「奈」是「大」下「示」，不要写成「耐」，也不要写成「无可耐何」。"},{"w":"耐","e":"【易错】「无可奈何」的「奈」是「大」下「示」，不要写成「耐」，也不要写成「无可耐何」。"},{"w":"曾","e":"【易错】「似曾相识」的「曾」读 céng，是「曾经」，不要写成「层」；「识」不要写成「织」。"},{"w":"层","e":"【易错】「似曾相识」的「曾」读 céng，是「曾经」，不要写成「层」；「识」不要写成「织」。"},{"w":"识","e":"【易错】「似曾相识」的「曾」读 céng，是「曾经」，不要写成「层」；「识」不要写成「织」。"},{"w":"织","e":"【易错】「似曾相识」的「曾」读 céng，是「曾经」，不要写成「层」；「识」不要写成「织」。"},{"w":"燕","e":"【易错】「燕归来」的「燕」指燕子，不要写成「雁」（大雁）。"},{"w":"雁","e":"【易错】「燕归来」的「燕」指燕子，不要写成「雁」（大雁）。"},{"w":"径","e":"【易错】「小园香径独徘徊」的「径」是双人旁，不要写成「经」；「徘徊」两字都是双人旁，不要写成「俳徊」「裴回」。"},{"w":"经","e":"【易错】「小园香径独徘徊」的「径」是双人旁，不要写成「经」；「徘徊」两字都是双人旁，不要写成「俳徊」「裴回」。"},{"w":"杯","e":"【易错】「一曲新词酒一杯」的「杯」是木字旁，不要写成「怀」「抔」。"},{"w":"怀","e":"【易错】「一曲新词酒一杯」的「杯」是木字旁，不要写成「怀」「抔」。"},{"w":"抔","e":"【易错】「一曲新词酒一杯」的「杯」是木字旁，不要写成「怀」「抔」。"}]},{"type":"list","title":"名句","items":["无可奈何花落去，似曾相识燕归来。"]},{"type":"list","title":"背诵提示","items":["「去年天气旧亭台」的「亭台」不要写成「停台」「亭苔」。","「夕阳西下几时回」的「几时」是「什么时候」，不要写成「及时」。","「无可奈何」的「奈」是「大」下「示」，不要写成「耐」，也不要写成「无可耐何」。","「似曾相识」的「曾」读 céng，是「曾经」，不要写成「层」；「识」不要写成「织」。","「燕归来」的「燕」指燕子，不要写成「雁」（大雁）。","「小园香径独徘徊」的「径」是双人旁，不要写成「经」；「徘徊」两字都是双人旁，不要写成「俳徊」「裴回」。","「一曲新词酒一杯」的「杯」是木字旁，不要写成「怀」「抔」。"]}],"questions":[{"id":"p-p-extra-huanshaxi-yanshu-m0","type":"fill","stem":"默写填空：无可奈何花落去，______。","answer":"似曾相识燕归来。","explain":"出自《浣溪沙（一曲新词酒一杯）》（宋·晏殊）：无可奈何花落去，似曾相识燕归来。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p-extra-huanshaxi-yanshu-u","type":"fill","stem":"理解性默写：唱一曲新填的词，饮一杯美酒；天气还是去年那样的天气，亭台也还是旧日的亭台。","answer":"一曲新词酒一杯，去年天气旧亭台。","explain":"出自《浣溪沙（一曲新词酒一杯）》（宋·晏殊）。句意：唱一曲新填的词，饮一杯美酒；天气还是去年那样的天气，亭台也还是旧日的亭台。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p-extra-nanxiangzi","title":"南乡子·登京口北固亭有怀","subtitle":"宋·辛弃疾","grade":"9a","tags":["怀古","爱国","豪放","咏史"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·辛弃疾"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"辛弃疾（1140—1207），字幼安，号稼轩，历城（今山东济南）人，南宋豪放派词人，与苏轼并称“苏辛”，与李清照并称“济南二安”。\n生平经历：他出生时中原已被金人占领，二十一岁便组织义军抗金，曾率五十骑闯入敌营擒拿叛将，一时声名大振；南归后长期不受重用，只做过地方官职，多次上书陈述抗金方略都未被采纳；他先后闲居江西上饶、铅山近二十年，把报国无门的悲愤都写进词里，晚年虽再被起用，不久便抱憾辞世。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首词是辛弃疾任镇江知府时登北固亭所作，借怀古抒发报国情怀。上片以问句「何处望神州」开篇，「满眼风光北固楼」以乐景写哀情——风光虽好，中原却已沦陷；「千古兴亡多少事？悠悠。不尽长江滚滚流」化用杜甫诗句，以悠悠不尽的长江写历史兴亡之慨，境界阔大。下片专写孙权：「年少万兜鍪，坐断东南战未休」赞其年少统兵、称雄东南；「天下英雄谁敌手？曹刘。生子当如孙仲谋」连用问答，借曹操之语极赞孙权，实为借古讽今，讽刺南宋朝廷苟安无能，寄寓自己收复失地的壮志。全词三问三答，层层推进，风格明快豪放。中考常考：三问三答的结构、借古讽今的手法、颂扬孙权这一形象的用意，以及「兜鍪」「坐断」等词语的理解。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"何处望神州？满眼风光北固楼。","n":"","cn":"什么地方可以望见中原故土呢？登上北固楼，满眼都是眼前的美好风光。","parts":[{"t":"何处望"},{"t":"神州","k":4},{"t":"？满眼风光"},{"t":"北固楼","k":0},{"t":"。"}]},{"t":"千古兴亡多少事？悠悠。不尽长江滚滚流。","n":"","cn":"千百年来的兴盛衰亡，有多少往事？真是遥远漫长啊，（只有那）流不尽的江水滚滚东流。","parts":[{"t":"千古","k":5},{"t":"兴亡","k":14},{"t":"多少事？"},{"t":"悠悠","k":6},{"t":"。"},{"t":"不尽","k":7},{"t":"长江"},{"t":"滚滚","k":18},{"t":"流。"}]},{"t":"年少万兜鍪，坐断东南战未休。","n":"","cn":"孙权年纪轻轻就统率千军万马，占据东南一方，战斗从未停止。","parts":[{"t":"年少","k":8},{"t":"万兜鍪","k":1},{"t":"，"},{"t":"坐断","k":9},{"t":"东南战"},{"t":"未休","k":10},{"t":"。"}]},{"t":"天下英雄谁敌手？曹刘。生子当如孙仲谋。","n":"","cn":"天下的英雄谁是他的对手？只有曹操、刘备。生儿子就应当像孙仲谋那样。","parts":[{"t":"天下英雄谁"},{"t":"敌手","k":11},{"t":"？"},{"t":"曹刘","k":12},{"t":"。生子当如"},{"t":"孙仲谋","k":2},{"t":"。"}]}],"words":[{"w":"北固楼","e":"在今江苏镇江北固山上，登临可俯瞰长江"},{"w":"万兜鍪","e":"借代众多士兵，兜鍪读 dōu móu，是古代的头盔"},{"w":"孙仲谋","e":"孙权，字仲谋，这句本是曹操称赞孙权的话"},{"w":"北顾楼","e":"【易错】「满眼风光北固楼」的「固」不要写成「故」；「北固楼」不要写成「北顾楼」。"},{"w":"神州","e":"指中原地区"},{"w":"千古","e":"久远的年代"},{"w":"悠悠","e":"漫长、遥远的样子"},{"w":"不尽","e":"流不尽"},{"w":"年少","e":"指孙权年轻（十九岁即继位掌权）"},{"w":"坐断","e":"占据、占据一方"},{"w":"未休","e":"不停"},{"w":"敌手","e":"对手"},{"w":"曹刘","e":"曹操和刘备"},{"w":"神洲","e":"【易错】「何处望神州」的「神州」指中原故土，不要写成「神洲」。"},{"w":"兴亡","e":"【易错】「千古兴亡多少事」的「兴亡」不要写成「兴旺」。"},{"w":"兴旺","e":"【易错】「千古兴亡多少事」的「兴亡」不要写成「兴旺」。"},{"w":"幽幽","e":"【易错】「悠悠」是漫长遥远的样子，不要写成「幽幽」「攸攸」。"},{"w":"攸攸","e":"【易错】「悠悠」是漫长遥远的样子，不要写成「幽幽」「攸攸」。"},{"w":"滚滚","e":"【易错】「不尽长江滚滚流」的「滚滚」是三点水，不要写成「衮衮」；「尽」不要写成「仅」。"},{"w":"衮衮","e":"【易错】「不尽长江滚滚流」的「滚滚」是三点水，不要写成「衮衮」；「尽」不要写成「仅」。"},{"w":"兜鍪","e":"【易错】「年少万兜鍪」的「兜鍪」读 dōu móu，指头盔，这里借代士兵：「鍪」上面是「敄」，下面是「金」，不要写成「兜矛」。"},{"w":"兜矛","e":"【易错】「年少万兜鍪」的「兜鍪」读 dōu móu，指头盔，这里借代士兵：「鍪」上面是「敄」，下面是「金」，不要写成「兜矛」。"},{"w":"仲谋","e":"【易错】「生子当如孙仲谋」的「仲谋」是孙权的字，两字都不能写错；此句本是曹操的话，不要误记为刘备所说。"},{"w":"对手","e":"【易错】「天下英雄谁敌手」的「敌手」是「对手」，不要写成「低手」。"},{"w":"低手","e":"【易错】「天下英雄谁敌手」的「敌手」是「对手」，不要写成「低手」。"},{"w":"固","e":"【易错】「满眼风光北固楼」的「固」不要写成「故」；「北固楼」不要写成「北顾楼」。"},{"w":"故","e":"【易错】「满眼风光北固楼」的「固」不要写成「故」；「北固楼」不要写成「北顾楼」。"},{"w":"尽","e":"【易错】「不尽长江滚滚流」的「滚滚」是三点水，不要写成「衮衮」；「尽」不要写成「仅」。"},{"w":"仅","e":"【易错】「不尽长江滚滚流」的「滚滚」是三点水，不要写成「衮衮」；「尽」不要写成「仅」。"},{"w":"鍪","e":"【易错】「年少万兜鍪」的「兜鍪」读 dōu móu，指头盔，这里借代士兵：「鍪」上面是「敄」，下面是「金」，不要写成「兜矛」。"},{"w":"敄","e":"【易错】「年少万兜鍪」的「兜鍪」读 dōu móu，指头盔，这里借代士兵：「鍪」上面是「敄」，下面是「金」，不要写成「兜矛」。"},{"w":"金","e":"【易错】「年少万兜鍪」的「兜鍪」读 dōu móu，指头盔，这里借代士兵：「鍪」上面是「敄」，下面是「金」，不要写成「兜矛」。"},{"w":"休","e":"【易错】「坐断东南战未休」的「坐断」是占据（一方），不要理解成坐着不动；「休」是停止，不要写成「修」。"},{"w":"修","e":"【易错】「坐断东南战未休」的「坐断」是占据（一方），不要理解成坐着不动；「休」是停止，不要写成「修」。"}]},{"type":"list","title":"名句","items":["千古兴亡多少事？悠悠。不尽长江滚滚流。","天下英雄谁敌手？曹刘。生子当如孙仲谋。"]},{"type":"list","title":"背诵提示","items":["「何处望神州」的「神州」指中原故土，不要写成「神洲」。","「满眼风光北固楼」的「固」不要写成「故」；「北固楼」不要写成「北顾楼」。","「千古兴亡多少事」的「兴亡」不要写成「兴旺」。","「悠悠」是漫长遥远的样子，不要写成「幽幽」「攸攸」。","「不尽长江滚滚流」的「滚滚」是三点水，不要写成「衮衮」；「尽」不要写成「仅」。","「年少万兜鍪」的「兜鍪」读 dōu móu，指头盔，这里借代士兵：「鍪」上面是「敄」，下面是「金」，不要写成「兜矛」。","「坐断东南战未休」的「坐断」是占据（一方），不要理解成坐着不动；「休」是停止，不要写成「修」。","「生子当如孙仲谋」的「仲谋」是孙权的字，两字都不能写错；此句本是曹操的话，不要误记为刘备所说。","「天下英雄谁敌手」的「敌手」是「对手」，不要写成「低手」。"]}],"questions":[{"id":"p-p-extra-nanxiangzi-u","type":"fill","stem":"理解性默写：什么地方可以望见中原故土呢？登上北固楼，满眼都是眼前的美好风光。","answer":"何处望神州？满眼风光北固楼。","explain":"出自《南乡子·登京口北固亭有怀》（宋·辛弃疾）。句意：什么地方可以望见中原故土呢？登上北固楼，满眼都是眼前的美好风光。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p-extra-guolingdingyang","title":"过零丁洋","subtitle":"宋·文天祥","grade":"9a","tags":["爱国","言志","抒怀","气节"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·文天祥"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"文天祥（1236—1283），字宋瑞，又字履善，号文山，南宋末年政治家、文学家、民族英雄，吉州庐陵（今江西吉安）人。\n生平经历：宝祐四年考中状元；元军南下时，他散尽家财起兵抗元，转战东南多年；兵败被俘后押解北上，途经零丁洋写下《过零丁洋》以明志；被囚大都三年，始终拒绝降元，最终从容就义。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是文天祥兵败被俘后过零丁洋时所作，是宋末爱国诗的代表。「辛苦遭逢起一经，干戈寥落四周星」回顾身世：由科举入仕到起兵抗元四年，语含艰难。颔联「山河破碎风飘絮，身世浮沉雨打萍」以「风飘絮」喻国势危亡、以「雨打萍」喻身世飘零，比喻贴切、对仗工整，家国之痛交织。颈联「惶恐滩头说惶恐，零丁洋里叹零丁」巧借两个地名构成双关，写出昔日的惊惧与今日的孤苦，是地名双关的典范。尾联「人生自古谁无死？留取丹心照汗青」以设问直抒胸臆，把生死置于民族大义之下，慷慨悲壮，是千古绝唱。中考常考：颔联比喻的作用、颈联双关的妙处、尾联所表现的民族气节与舍生取义的精神，注意「寥」「絮」「萍」「汗青」等字的写法与含义。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"辛苦遭逢起一经，干戈寥落四周星。","n":"","cn":"我历尽艰辛，因精通一种经书考中进士而走上仕途，起兵抗元以来，战争已冷落稀疏地过了四年。","parts":[{"t":"辛苦"},{"t":"遭逢","k":6},{"t":"起一经","k":1},{"t":"，"},{"t":"干戈","k":7},{"t":"寥落","k":8},{"t":"四周星","k":2},{"t":"。"}]},{"t":"山河破碎风飘絮，身世浮沉雨打萍。","n":"","cn":"山河破碎得像被狂风吹散的柳絮，我一生身世飘摇沉浮，像被急雨抽打的水上浮萍。","parts":[{"t":"山河破碎风飘"},{"t":"絮","k":23},{"t":"，"},{"t":"身世","k":9},{"t":"浮沉","k":10},{"t":"雨打"},{"t":"萍","k":24},{"t":"。"}]},{"t":"惶恐滩头说惶恐，零丁洋里叹零丁。","n":"","cn":"去年在惶恐滩头我曾诉说内心的惶恐，如今在零丁洋里又感叹自己的孤苦零丁。","parts":[{"t":"惶恐滩","k":3},{"t":"头说"},{"t":"惶恐","k":19},{"t":"，"},{"t":"零丁洋","k":4},{"t":"里叹"},{"t":"零丁","k":11},{"t":"。"}]},{"t":"人生自古谁无死？留取丹心照汗青。","n":"","cn":"自古以来人生在世谁能不死呢？只求留下这一片赤诚之心光照史册。","parts":[{"t":"人生自古谁无死？"},{"t":"留取","k":12},{"t":"丹心","k":13},{"t":"照"},{"t":"汗青","k":14},{"t":"。"}]}],"words":[{"w":"四个星期","e":"【易错】「四周星」的「周星」指岁星运行一周，即四年，不要理解成「四个星期」。"},{"w":"起一经","e":"指因通晓一部经书（科举考试）而做官"},{"w":"四周星","e":"四年（岁星运行一周为一年，四周星即四年）"},{"w":"惶恐滩","e":"在今江西万安，滩险水急"},{"w":"零丁洋","e":"在今广东珠江口外"},{"w":"皇恐滩","e":"【易错】「惶恐滩头说惶恐」两个「惶恐」都要写，不要漏写一个；「惶恐滩」不要写成「皇恐滩」。"},{"w":"遭逢","e":"遭遇"},{"w":"干戈","e":"兵器，代指战争"},{"w":"寥落","e":"稀疏、冷落"},{"w":"身世","e":"一生的境遇"},{"w":"浮沉","e":"飘摇不定"},{"w":"零丁","e":"孤苦无依的样子"},{"w":"留取","e":"留得"},{"w":"丹心","e":"赤诚之心"},{"w":"汗青","e":"指史册（古代用竹简记事，先以火烤青竹使水分渗出如汗，故称）"},{"w":"糟逢","e":"【易错】「辛苦遭逢起一经」的「遭逢」不要写成「糟逢」；「起一经」指凭一部经书考中做官，不是「起兵」。"},{"w":"起兵","e":"【易错】「辛苦遭逢起一经」的「遭逢」不要写成「糟逢」；「起一经」指凭一部经书考中做官，不是「起兵」。"},{"w":"周星","e":"【易错】「四周星」的「周星」指岁星运行一周，即四年，不要理解成「四个星期」。"},{"w":"浮尘","e":"【易错】「身世浮沉雨打萍」的「浮沉」不要写成「浮尘」；「萍」是草字头，不要写成「平」。"},{"w":"惶恐","e":"【易错】「惶恐滩头说惶恐」两个「惶恐」都要写，不要漏写一个；「惶恐滩」不要写成「皇恐滩」。"},{"w":"伶仃","e":"【易错】「零丁洋里叹零丁」两个「零丁」都要写，教材作「零丁」，不要写成「伶仃」。"},{"w":"汉青","e":"【易错】「留取丹心照汗青」的「汗青」指史册，不要写成「汉青」；「丹心」不要写成「担心」。"},{"w":"担心","e":"【易错】「留取丹心照汗青」的「汗青」指史册，不要写成「汉青」；「丹心」不要写成「担心」。"},{"w":"絮","e":"柳絮"},{"w":"萍","e":"浮萍"},{"w":"寥","e":"【易错】「干戈寥落四周星」的「寥」是宝盖头下「翏」，不要写成「廖」「缭」；「戈」不要写成「弋」。"},{"w":"翏","e":"【易错】「干戈寥落四周星」的「寥」是宝盖头下「翏」，不要写成「廖」「缭」；「戈」不要写成「弋」。"},{"w":"廖","e":"【易错】「干戈寥落四周星」的「寥」是宝盖头下「翏」，不要写成「廖」「缭」；「戈」不要写成「弋」。"},{"w":"缭","e":"【易错】「干戈寥落四周星」的「寥」是宝盖头下「翏」，不要写成「廖」「缭」；「戈」不要写成「弋」。"},{"w":"戈","e":"【易错】「干戈寥落四周星」的「寥」是宝盖头下「翏」，不要写成「廖」「缭」；「戈」不要写成「弋」。"},{"w":"弋","e":"【易错】「干戈寥落四周星」的「寥」是宝盖头下「翏」，不要写成「廖」「缭」；「戈」不要写成「弋」。"},{"w":"如","e":"【易错】「山河破碎风飘絮」的「絮」是「如」下加「糸」，不要写成「恕」「绪」。"},{"w":"糸","e":"【易错】「山河破碎风飘絮」的「絮」是「如」下加「糸」，不要写成「恕」「绪」。"},{"w":"恕","e":"【易错】「山河破碎风飘絮」的「絮」是「如」下加「糸」，不要写成「恕」「绪」。"},{"w":"绪","e":"【易错】「山河破碎风飘絮」的「絮」是「如」下加「糸」，不要写成「恕」「绪」。"},{"w":"平","e":"【易错】「身世浮沉雨打萍」的「浮沉」不要写成「浮尘」；「萍」是草字头，不要写成「平」。"}]},{"type":"list","title":"名句","items":["人生自古谁无死？留取丹心照汗青。","山河破碎风飘絮，身世浮沉雨打萍。"]},{"type":"list","title":"背诵提示","items":["「辛苦遭逢起一经」的「遭逢」不要写成「糟逢」；「起一经」指凭一部经书考中做官，不是「起兵」。","「干戈寥落四周星」的「寥」是宝盖头下「翏」，不要写成「廖」「缭」；「戈」不要写成「弋」。","「四周星」的「周星」指岁星运行一周，即四年，不要理解成「四个星期」。","「山河破碎风飘絮」的「絮」是「如」下加「糸」，不要写成「恕」「绪」。","「身世浮沉雨打萍」的「浮沉」不要写成「浮尘」；「萍」是草字头，不要写成「平」。","「惶恐滩头说惶恐」两个「惶恐」都要写，不要漏写一个；「惶恐滩」不要写成「皇恐滩」。","「零丁洋里叹零丁」两个「零丁」都要写，教材作「零丁」，不要写成「伶仃」。","「留取丹心照汗青」的「汗青」指史册，不要写成「汉青」；「丹心」不要写成「担心」。"]}],"questions":[{"id":"p-p-extra-guolingdingyang-m0","type":"fill","stem":"默写填空：山河破碎风飘絮，______。","answer":"身世浮沉雨打萍。","explain":"出自《过零丁洋》（宋·文天祥）：山河破碎风飘絮，身世浮沉雨打萍。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p-extra-guolingdingyang-u","type":"fill","stem":"理解性默写：我历尽艰辛，因精通一种经书考中进士而走上仕途，起兵抗元以来，战争已冷落稀疏地过了四年。","answer":"辛苦遭逢起一经，干戈寥落四周星。","explain":"出自《过零丁洋》（宋·文天祥）。句意：我历尽艰辛，因精通一种经书考中进士而走上仕途，起兵抗元以来，战争已冷落稀疏地过了四年。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p-extra-shanpoyang","title":"山坡羊·潼关怀古","subtitle":"元·张养浩","grade":"9a","tags":["怀古","讽喻","民生","咏史"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"元·张养浩"},{"k":"体裁","v":"曲"}]},{"type":"note","title":"作者简介","text":"张养浩（1270—1329），字希孟，号云庄，元代散曲家、政治家，济南（今山东济南）人。\n生平经历：他历任监察御史、礼部尚书等职，因上疏直言、得罪权贵而辞官归隐云庄；天历二年关中大旱，他被召为陕西行台中丞前往赈灾，到官仅四个月便积劳成疾而卒。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是张养浩赴陕西赈灾途经潼关时所作的怀古散曲。前三句写景，以「聚」字化静为动写群峰奔涌之势，以「怒」字拟人写黄河波涛汹涌；「山河表里潼关路」点出潼关内外山河相依、地势险要，暗示其为兵家必争之地，为下文张本。「望西都，意踌躇」由景入情，「伤心秦汉经行处，宫阙万间都做了土」以昔日宫阙的壮丽与今日泥土的荒凉相对照，写尽朝代更替的沧桑。结尾「兴，百姓苦；亡，百姓苦」由怀古转为议论，一语道破封建王朝无论兴亡都以百姓苦难为代价的本质，同情人民、鞭挞统治者，是全曲的曲眼。中考常考：「聚」「怒」的炼字、写景—怀古—议论的结构、末句的思想内涵与对比手法，注意「峦」「潼」「踌躇」「阙」「做了土」等字形。"},{"type":"list","title":"中考考点","items":["直接默写与理解性默写","诗句赏析（修辞、炼字、画面）","思想感情与主旨","意象与意境"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"峰峦如聚，波涛如怒，山河表里潼关路。","n":"","cn":"山峰像是聚集在一起，黄河的波涛像在发怒，潼关一带外有黄河、内有华山，地势险要。","parts":[{"t":"峰峦如聚","k":1},{"t":"，"},{"t":"波涛如怒","k":2},{"t":"，"},{"t":"山河表里","k":0},{"t":"潼","k":27},{"t":"关","k":33},{"t":"路。"}]},{"t":"望西都，意踌躇。","n":"","cn":"遥望西边的故都长安，心中感慨万千、徘徊不定。","parts":[{"t":"望"},{"t":"西都","k":8},{"t":"，"},{"t":"意踌躇","k":3},{"t":"。"}]},{"t":"伤心秦汉经行处，宫阙万间都做了土。","n":"","cn":"令人伤心的是途经秦汉故都的遗址，当年千万间华美的宫殿如今都化作了泥土。","parts":[{"t":"伤心","k":16},{"t":"秦汉"},{"t":"经行处","k":4},{"t":"，"},{"t":"宫阙","k":9},{"t":"万间都"},{"t":"做了土","k":5},{"t":"。"}]},{"t":"兴，百姓苦；亡，百姓苦。","n":"","cn":"朝代兴盛，百姓受苦；朝代灭亡，百姓还是受苦。","parts":[{"t":"兴","k":19},{"t":"，百姓苦；"},{"t":"亡","k":20},{"t":"，百姓苦。"}]}],"words":[{"w":"山河表里","e":"外有黄河、内有华山，互为表里"},{"w":"峰峦如聚","e":"【易错】「峰峦如聚」的「峦」是山字底，不要写成「恋」「栾」；「聚」不要写成「骤」。"},{"w":"波涛如怒","e":"【易错】「波涛如怒」的「怒」是拟人写法，不要写成「恕」「努」。"},{"w":"意踌躇","e":"心绪起伏、感慨犹豫，踌躇读 chóu chú"},{"w":"经行处","e":"经过的地方，指秦汉故都遗址"},{"w":"做了土","e":"化成了泥土"},{"w":"作了土","e":"【易错】「宫阙万间都做了土」的「阙」是「门」内「欮」，不要写成「阕」「关」；教材作「做了土」，不要写成「作了土」。"},{"w":"峰峦","e":"山峰"},{"w":"西都","e":"指长安"},{"w":"宫阙","e":"宫殿，阙读 què"},{"w":"表里","e":"【易错】「山河表里潼关路」的「潼」是三点水，不要写成「童」；「表里」指外有黄河、内有华山，不要理解成「表面和里面」。"},{"w":"踌躇","e":"【易错】「望西都，意踌躇」的「西都」指长安，「踌躇」两字都是足字旁，不要写成「筹躇」「惆怅」。"},{"w":"筹躇","e":"【易错】「望西都，意踌躇」的「西都」指长安，「踌躇」两字都是足字旁，不要写成「筹躇」「惆怅」。"},{"w":"惆怅","e":"【易错】「望西都，意踌躇」的「西都」指长安，「踌躇」两字都是足字旁，不要写成「筹躇」「惆怅」。"},{"w":"经行","e":"【易错】「伤心秦汉经行处」的「经行」指经过（秦汉故地），不要写成「行经」；「伤心」是「为……而伤心」。"},{"w":"行经","e":"【易错】「伤心秦汉经行处」的「经行」指经过（秦汉故地），不要写成「行经」；「伤心」是「为……而伤心」。"},{"w":"伤心","e":"【易错】「伤心秦汉经行处」的「经行」指经过（秦汉故地），不要写成「行经」；「伤心」是「为……而伤心」。"},{"w":"聚","e":"聚集，化静为动，写出峰峦众多、向潼关奔涌之势"},{"w":"怒","e":"拟人，写波涛汹涌澎湃"},{"w":"兴","e":"兴盛、兴起"},{"w":"亡","e":"灭亡"},{"w":"峦","e":"【易错】「峰峦如聚」的「峦」是山字底，不要写成「恋」「栾」；「聚」不要写成「骤」。"},{"w":"恋","e":"【易错】「峰峦如聚」的「峦」是山字底，不要写成「恋」「栾」；「聚」不要写成「骤」。"},{"w":"栾","e":"【易错】「峰峦如聚」的「峦」是山字底，不要写成「恋」「栾」；「聚」不要写成「骤」。"},{"w":"骤","e":"【易错】「峰峦如聚」的「峦」是山字底，不要写成「恋」「栾」；「聚」不要写成「骤」。"},{"w":"恕","e":"【易错】「波涛如怒」的「怒」是拟人写法，不要写成「恕」「努」。"},{"w":"努","e":"【易错】「波涛如怒」的「怒」是拟人写法，不要写成「恕」「努」。"},{"w":"潼","e":"【易错】「山河表里潼关路」的「潼」是三点水，不要写成「童」；「表里」指外有黄河、内有华山，不要理解成「表面和里面」。"},{"w":"童","e":"【易错】「山河表里潼关路」的「潼」是三点水，不要写成「童」；「表里」指外有黄河、内有华山，不要理解成「表面和里面」。"},{"w":"阙","e":"【易错】「宫阙万间都做了土」的「阙」是「门」内「欮」，不要写成「阕」「关」；教材作「做了土」，不要写成「作了土」。"},{"w":"门","e":"【易错】「宫阙万间都做了土」的「阙」是「门」内「欮」，不要写成「阕」「关」；教材作「做了土」，不要写成「作了土」。"},{"w":"欮","e":"【易错】「宫阙万间都做了土」的「阙」是「门」内「欮」，不要写成「阕」「关」；教材作「做了土」，不要写成「作了土」。"},{"w":"阕","e":"【易错】「宫阙万间都做了土」的「阙」是「门」内「欮」，不要写成「阕」「关」；教材作「做了土」，不要写成「作了土」。"},{"w":"关","e":"【易错】「宫阙万间都做了土」的「阙」是「门」内「欮」，不要写成「阕」「关」；教材作「做了土」，不要写成「作了土」。"}]},{"type":"list","title":"名句","items":["峰峦如聚，波涛如怒，山河表里潼关路。","兴，百姓苦；亡，百姓苦。"]},{"type":"list","title":"背诵提示","items":["「峰峦如聚」的「峦」是山字底，不要写成「恋」「栾」；「聚」不要写成「骤」。","「波涛如怒」的「怒」是拟人写法，不要写成「恕」「努」。","「山河表里潼关路」的「潼」是三点水，不要写成「童」；「表里」指外有黄河、内有华山，不要理解成「表面和里面」。","「望西都，意踌躇」的「西都」指长安，「踌躇」两字都是足字旁，不要写成「筹躇」「惆怅」。","「伤心秦汉经行处」的「经行」指经过（秦汉故地），不要写成「行经」；「伤心」是「为……而伤心」。","「宫阙万间都做了土」的「阙」是「门」内「欮」，不要写成「阕」「关」；教材作「做了土」，不要写成「作了土」。","「兴，百姓苦；亡，百姓苦」两个分句句式相同、缺一不可，不要漏写或写反「兴」「亡」，中间的分号不要写成逗号。"]}],"questions":[{"id":"p-p-extra-shanpoyang-m0","type":"fill","stem":"默写填空：峰峦如聚，______。","answer":"波涛如怒。","explain":"出自《山坡羊·潼关怀古》（元·张养浩）：峰峦如聚，波涛如怒，山河表里潼关路。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p-extra-shanpoyang-m1","type":"fill","stem":"默写填空：兴，______。","answer":"百姓苦。","explain":"出自《山坡羊·潼关怀古》（元·张养浩）：兴，百姓苦；亡，百姓苦。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p-extra-shanpoyang-u","type":"fill","stem":"理解性默写：山峰像是聚集在一起，黄河的波涛像在发怒，潼关一带外有黄河、内有华山，地势险要。","answer":"峰峦如聚，波涛如怒，山河表里潼关路。","explain":"出自《山坡羊·潼关怀古》（元·张养浩）。句意：山峰像是聚集在一起，黄河的波涛像在发怒，潼关一带外有黄河、内有华山，地势险要。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-guo-song-yuan-chen-chui-qi-gong-dian","title":"过松源晨炊漆公店（其五）","subtitle":"宋·杨万里","grade":"7b","tags":["哲理","写景","行旅","理趣"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·杨万里"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"杨万里（1127—1206），字廷秀，号诚斋，吉州吉水（今江西吉水）人，南宋诗人，与陆游、范成大、尤袤并称“中兴四大诗人”。\n生平经历：绍兴二十四年考中进士，此后历任零陵丞、太常博士、广东提举等职，官至宝谟阁直学士；他为官清正敢言，主张抗金，曾多次上疏议论朝政得失；晚年辞官归隐吉水故里，长期闲居乡间，在田园山水中写诗自遣。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是杨万里的一首七言哲理诗，写清晨路过松源、漆公店一带山区时翻山越岭的切身感受。首句“莫言下岭便无难”以否定告诫起笔，点出人们常有的错觉——以为下山省力便再无难处；第二句“赚得行人错喜欢”以「赚」「错」二字写尽行人被群山骗得空欢喜的情态，语气诙谐而含警醒。三四句“政入万山围子里，一山放出一山拦”是全诗的警策：刚翻过一山，又有一山拦路，山山相连如同重重围子，把困难接踵而至的处境写得生动形象。诗人由具体的行路感受生发哲理，说明无论做什么事，都要对前进路上的困难有充分的估计，不要被眼前的顺境所迷惑，而要放眼长远、不断克服困难。全诗语言通俗活泼，寓理于事，是宋诗以理趣见长的代表"},{"type":"list","title":"中考考点","items":["「政」同「正」的通假与「赚得」「错喜欢」的含义","“一山放出一山拦”的拟人与比喻作用","名句默写及其中蕴含的困难重重、不可松劲的哲理","诗人由事及理、寓理于事的写法。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"莫言下岭便无难，赚得行人错喜欢。","n":"","cn":"不要说下了山岭就没有困难了，这一说反倒把赶路的人骗得空欢喜一场。「莫言」是不要说；「赚得」是骗得；「错喜欢」是空欢喜一场。","parts":[{"t":"莫言","k":4},{"t":"下岭便无难，"},{"t":"赚得","k":5},{"t":"行人"},{"t":"错喜欢","k":1},{"t":"。"}]},{"t":"政入万山围子里，一山放出一山拦。","n":"","cn":"正好走进万山环抱的圈子里，刚放你翻过一座山，又有一座山拦住去路。「政」同「正」，正好；「万山围子」指四周群山环抱如围子；「放出」是放行、让过；「拦」是阻挡。","parts":[{"t":"政","k":10},{"t":"入"},{"t":"万山围子","k":0},{"t":"里，一山"},{"t":"放出","k":6},{"t":"一山"},{"t":"拦","k":11},{"t":"。"}]}],"words":[{"w":"万山围子","e":"指四周群山环抱如围子"},{"w":"错喜欢","e":"是空欢喜一场"},{"w":"空喜欢","e":"【易错】“赚得行人错喜欢”教材作「错喜欢」，意为空欢喜一场，不要写成「空喜欢」。"},{"w":"漆公店","e":"【易错】诗题中的「松源」「漆公店」都是地名，「漆」是三点水，不写「膝」「柒」。"},{"w":"莫言","e":"是不要说"},{"w":"赚得","e":"是骗得"},{"w":"放出","e":"是放行、让过"},{"w":"政治","e":"【易错】“政入万山围子里”的「政」同「正」，是正好、恰好的意思，属通假字，不能按「政治」理解，也不要擅自写成「正」。"},{"w":"围子","e":"【易错】「万山围子」指四周群山环抱、如同围子，「围子」是比喻的说法，不是实指围墙、栏圈。"},{"w":"松源","e":"【易错】诗题中的「松源」「漆公店」都是地名，「漆」是三点水，不写「膝」「柒」。"},{"w":"政","e":"同「正」"},{"w":"拦","e":"是阻挡"},{"w":"正","e":"【易错】“政入万山围子里”的「政」同「正」，是正好、恰好的意思，属通假字，不能按「政治」理解，也不要擅自写成「正」。"},{"w":"赚","e":"【易错】“赚得行人错喜欢”的「赚」在这里是哄骗、骗得的意思，不要理解为「赚钱、赚取」的「赚」。"},{"w":"漆","e":"【易错】诗题中的「松源」「漆公店」都是地名，「漆」是三点水，不写「膝」「柒」。"},{"w":"膝","e":"【易错】诗题中的「松源」「漆公店」都是地名，「漆」是三点水，不写「膝」「柒」。"},{"w":"柒","e":"【易错】诗题中的「松源」「漆公店」都是地名，「漆」是三点水，不写「膝」「柒」。"},{"w":"栏","e":"【易错】“一山放出一山拦”的「拦」是提手旁，指阻挡，不写「栏」。"}]},{"type":"list","title":"名句","items":["政入万山围子里，一山放出一山拦。"]},{"type":"list","title":"背诵提示","items":["“政入万山围子里”的「政」同「正」，是正好、恰好的意思，属通假字，不能按「政治」理解，也不要擅自写成「正」。","“赚得行人错喜欢”的「赚」在这里是哄骗、骗得的意思，不要理解为「赚钱、赚取」的「赚」。","“赚得行人错喜欢”教材作「错喜欢」，意为空欢喜一场，不要写成「空喜欢」。","「万山围子」指四周群山环抱、如同围子，「围子」是比喻的说法，不是实指围墙、栏圈。","诗题中的「松源」「漆公店」都是地名，「漆」是三点水，不写「膝」「柒」。","“一山放出一山拦”的「拦」是提手旁，指阻挡，不写「栏」。"]}],"questions":[{"id":"p-p7b-guo-song-yuan-chen-chui-qi-gong-dian-m0","type":"fill","stem":"默写填空：政入万山围子里，______。","answer":"一山放出一山拦。","explain":"出自《过松源晨炊漆公店（其五）》（宋·杨万里）：政入万山围子里，一山放出一山拦。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-guo-song-yuan-chen-chui-qi-gong-dian-u","type":"fill","stem":"理解性默写：不要说下了山岭就没有困难了，这一说反倒把赶路的人骗得空欢喜一场。「莫言」是不要说；「赚得」是骗得；「错喜欢」是空欢喜一场。","answer":"莫言下岭便无难，赚得行人错喜欢。","explain":"出自《过松源晨炊漆公店（其五）》（宋·杨万里）。句意：不要说下了山岭就没有困难了，这一说反倒把赶路的人骗得空欢喜一场。「莫言」是不要说；「赚得」是骗得；「错喜欢」是空欢喜一场。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p7b-yue-ke","title":"约客","subtitle":"宋·赵师秀","grade":"7b","tags":["写景","闲适","等待","夏夜"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·赵师秀"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"赵师秀（1170—1219），字紫芝，号灵秀，永嘉（今浙江温州）人，南宋诗人，“永嘉四灵”之一。\n生平经历：他中进士后长期担任地方小官，一生仕途不显，生活较为清苦；与同乡徐照、徐玑、翁卷往来唱和，四人字号中都带一个“灵”字，故合称“永嘉四灵”；他作诗讲究锤炼字句，尤长于五言律诗。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是赵师秀的一首七言绝句，写江南梅雨之夜等候友人不至的情景。前两句写环境：首句“黄梅时节家家雨”点明时令与天气，「家家雨」写雨落之广；第二句“青草池塘处处蛙”写声音，「处处蛙」写蛙鸣之盛；一写雨、一写蛙，一见闻、一听觉，绘出一幅清新恬静的江南夏夜图。「家家」「处处」两组叠字兼用对偶，音韵和谐，也以声衬静，反衬出环境的幽静。后两句写人事与心境：“有约不来过夜半”点出候客而不至的缘由，「过夜半」说明等待之久；结句“闲敲棋子落灯花”最为精妙，诗人不直说焦躁或落寞，只写「闲敲棋子」这一细微动作，棋子轻敲、灯花震落，把夜深候客的无聊、惆怅与淡淡孤寂尽在不言之中，以景结情，余味悠长。全诗写景抒情自然，动静相衬，语言平易，是宋诗中写景抒情的名篇"},{"type":"list","title":"中考考点","items":["「黄梅时节」「灯花」等词释义","“家家”“处处”叠字与对偶的表达效果及其以声衬静的作用","“闲敲棋子落灯花”的动作描写与以景结情，及所抒发的孤寂怅惘之情","前两句景物描写的作用（渲染氛围、反衬寂静与心绪）。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"黄梅时节家家雨，青草池塘处处蛙。","n":"","cn":"黄梅时节，家家户户都笼罩在连绵的阴雨之中；长满青草的池塘边，处处传来青蛙的鸣叫声。「黄梅时节」指江南初夏梅子黄熟、阴雨连绵的时节；「家家雨」写雨落之普遍；「处处蛙」写蛙声之喧盛。","parts":[{"t":"黄梅时节","k":0},{"t":"家家","k":9},{"t":"雨，青草池塘"},{"t":"处处","k":10},{"t":"蛙","k":18},{"t":"。"}]},{"t":"有约不来过夜半，闲敲棋子落灯花。","n":"","cn":"约好的客人过了半夜还没有来，我只好无聊地轻轻敲着棋子，灯芯结成的灯花也被震落下来。「有约」指与人有约；「过」是超过；「夜半」即半夜；「闲敲」写无聊中随手的动作；「灯花」指灯芯燃烧后结成的花状余烬。","parts":[{"t":"有约","k":6},{"t":"不来"},{"t":"过夜半","k":4},{"t":"，闲"},{"t":"敲","k":12},{"t":"棋子落"},{"t":"灯花","k":8},{"t":"。"}]}],"words":[{"w":"黄梅时节","e":"指江南初夏梅子黄熟、阴雨连绵的时节"},{"w":"灯上的花","e":"【易错】「灯花」指灯芯燃烧后结成的花状余烬，因棋子轻敲而震落，不是「灯上的花」，也不能解作「灯火明亮」。"},{"w":"灯火明亮","e":"【易错】「灯花」指灯芯燃烧后结成的花状余烬，因棋子轻敲而震落，不是「灯上的花」，也不能解作「灯火明亮」。"},{"w":"黄梅戏","e":"【易错】「黄梅时节」指江南初夏梅子黄熟、阴雨连绵的时节，不是指「黄色的梅子」，也与「黄梅戏」无关。"},{"w":"过夜半","e":"【易错】「有约不来过夜半」的「过夜半」意为过了半夜，「过」是超过，不要写成「过夜伴」。"},{"w":"过夜伴","e":"【易错】「有约不来过夜半」的「过夜半」意为过了半夜，「过」是超过，不要写成「过夜伴」。"},{"w":"有约","e":"指与人有约"},{"w":"夜半","e":"即半夜"},{"w":"灯花","e":"指灯芯燃烧后结成的花状余烬"},{"w":"家家","e":"【易错】“黄梅时节家家雨，青草池塘处处蛙”中「家家」「处处」是叠词相对，默写时容易漏写一个，或误写成「家」「处」。"},{"w":"处处","e":"【易错】“黄梅时节家家雨，青草池塘处处蛙”中「家家」「处处」是叠词相对，默写时容易漏写一个，或误写成「家」「处」。"},{"w":"过","e":"是超过"},{"w":"敲","e":"【易错】“闲敲棋子落灯花”的「敲」右边是「高」的变形，是轻轻敲击的意思，不写「搞」「稿」等形近字。"},{"w":"高","e":"【易错】“闲敲棋子落灯花”的「敲」右边是「高」的变形，是轻轻敲击的意思，不写「搞」「稿」等形近字。"},{"w":"搞","e":"【易错】“闲敲棋子落灯花”的「敲」右边是「高」的变形，是轻轻敲击的意思，不写「搞」「稿」等形近字。"},{"w":"稿","e":"【易错】“闲敲棋子落灯花”的「敲」右边是「高」的变形，是轻轻敲击的意思，不写「搞」「稿」等形近字。"},{"w":"家","e":"【易错】“黄梅时节家家雨，青草池塘处处蛙”中「家家」「处处」是叠词相对，默写时容易漏写一个，或误写成「家」「处」。"},{"w":"处","e":"【易错】“黄梅时节家家雨，青草池塘处处蛙”中「家家」「处处」是叠词相对，默写时容易漏写一个，或误写成「家」「处」。"},{"w":"蛙","e":"【易错】“青草池塘处处蛙”的「蛙」是虫字旁，指青蛙的鸣叫声，不写「洼」「娃」。"},{"w":"洼","e":"【易错】“青草池塘处处蛙”的「蛙」是虫字旁，指青蛙的鸣叫声，不写「洼」「娃」。"},{"w":"娃","e":"【易错】“青草池塘处处蛙”的「蛙」是虫字旁，指青蛙的鸣叫声，不写「洼」「娃」。"}]},{"type":"list","title":"名句","items":["有约不来过夜半，闲敲棋子落灯花。"]},{"type":"list","title":"背诵提示","items":["「黄梅时节」指江南初夏梅子黄熟、阴雨连绵的时节，不是指「黄色的梅子」，也与「黄梅戏」无关。","“闲敲棋子落灯花”的「敲」右边是「高」的变形，是轻轻敲击的意思，不写「搞」「稿」等形近字。","「灯花」指灯芯燃烧后结成的花状余烬，因棋子轻敲而震落，不是「灯上的花」，也不能解作「灯火明亮」。","“黄梅时节家家雨，青草池塘处处蛙”中「家家」「处处」是叠词相对，默写时容易漏写一个，或误写成「家」「处」。","「有约不来过夜半」的「过夜半」意为过了半夜，「过」是超过，不要写成「过夜伴」。","“青草池塘处处蛙”的「蛙」是虫字旁，指青蛙的鸣叫声，不写「洼」「娃」。"]}],"questions":[{"id":"p-p7b-yue-ke-m0","type":"fill","stem":"默写填空：有约不来过夜半，______。","answer":"闲敲棋子落灯花。","explain":"出自《约客》（宋·赵师秀）：有约不来过夜半，闲敲棋子落灯花。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p7b-yue-ke-u","type":"fill","stem":"理解性默写：黄梅时节，家家户户都笼罩在连绵的阴雨之中；长满青草的池塘边，处处传来青蛙的鸣叫声。「黄梅时节」指江南初夏梅子黄熟、阴雨连绵的时节；「家家雨」写雨落之普遍；「处处蛙」写蛙声之喧盛。","answer":"黄梅时节家家雨，青草池塘处处蛙。","explain":"出自《约客》（宋·赵师秀）。句意：黄梅时节，家家户户都笼罩在连绵的阴雨之中；长满青草的池塘边，处处传来青蛙的鸣叫声。「黄梅时节」指江南初夏梅子黄熟、阴雨连绵的时节；「家家雨」写雨落之普遍；「处处蛙」写蛙声之喧盛。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-cai-sang-zi","title":"采桑子（轻舟短棹西湖好）","subtitle":"宋·欧阳修","grade":"8a","tags":["写景","西湖","闲适","泛舟"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·欧阳修"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"欧阳修（1007—1072），字永叔，号醉翁，晚年又号六一居士，吉州永丰（今江西永丰）人，北宋文学家、史学家、政治家，谥号“文忠”。\n生平经历：他四岁丧父，家境贫寒，母亲郑氏以芦荻画地教他识字，“画荻教子”传为佳话；天圣八年考中进士，为官刚直敢言，因支持范仲淹新政而屡遭贬谪，先后任滁州、扬州、颍州等地知州；晚年官至参知政事，主持编修《新唐书》，并独自撰写《新五代史》。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是欧阳修《采桑子》十首中的第一首，写泛舟颍州西湖所见的明丽风光与从容游赏之乐。上片写水上行舟所见：首句“轻舟短棹西湖好”以「好」字总提全篇，是全词的词眼，轻舟短棹、从容荡漾，一个「好」字奠定欢愉的基调；“绿水逶迤”写湖水之曲折绵长，“芳草长堤”写堤岸之芳草萋萋，“隐隐笙歌处处随”转从听觉落笔，写乐声歌声若有若无、处处相随，视听结合，境界清丽而富有生趣。下片写水面之静与船行之轻：“无风水面琉璃滑”以「琉璃」比喻无风水面的澄澈光滑，比喻新颖贴切；“不觉船移”以主观感受写船行之轻缓平稳，静中有动；结句“微动涟漪，惊起沙禽掠岸飞”由静转动，一丝微澜惊起沙洲水鸟，掠岸而飞，动静相衬，画面灵动。全词笔调轻松淡雅，色调清丽，善用叠字与比喻，表现词人恬淡闲适的心境与对西湖春色的由衷喜爱"},{"type":"list","title":"中考考点","items":["「短棹」「逶迤」「琉璃」「涟漪」等词释义及「棹」「逶迤」的读音","「好」字作为词眼的作用","比喻（琉璃）与动静结合、视听结合的写景手法","名句默写及词中所表现的闲适愉悦之情。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"轻舟短棹西湖好，绿水逶迤。","n":"","cn":"轻便的小舟、短短的船桨，西湖的风光多么美好；碧绿的湖水曲折绵延。「短棹」指短小的船桨，棹读 zhào；「西湖」指颍州西湖；「逶迤」读 wēi yí，形容曲折绵延的样子。","parts":[{"t":"轻舟"},{"t":"短棹","k":5},{"t":"西湖","k":6},{"t":"好，"},{"t":"绿水逶迤","k":0},{"t":"。"}]},{"t":"芳草长堤，隐隐笙歌处处随。","n":"","cn":"长长的堤岸上长满芬芳的青草，隐隐约约的笙歌乐声处处跟随着小船。「芳草」指芬芳的青草；「隐隐」形容声音隐约不分明；「笙歌」泛指奏乐唱歌。","parts":[{"t":"芳草","k":7},{"t":"长堤，"},{"t":"隐隐","k":15},{"t":"笙歌","k":14},{"t":"处处随。"}]},{"t":"无风水面琉璃滑，不觉船移。","n":"","cn":"没有风的水面像琉璃一样澄澈光滑，让人感觉不到船在移动。「琉璃」是一种光滑透明的釉料，这里比喻水面的澄澈平滑；「不觉船移」以主观感受写船行之轻缓平稳。","parts":[{"t":"无风水面"},{"t":"琉璃","k":8},{"t":"滑，不觉船移。"}]},{"t":"微动涟漪，惊起沙禽掠岸飞。","n":"","cn":"水面微微泛起细小的波纹，惊起了沙洲上的水鸟，它们擦着岸边飞掠而去。「涟漪」读 lián yī，指细小的波纹；「沙禽」指沙洲、沙滩上的水鸟；「掠岸飞」是擦过岸边飞起。","parts":[{"t":"微动涟漪","k":1},{"t":"，惊起"},{"t":"沙禽","k":9},{"t":"掠岸飞","k":2},{"t":"。"}]}],"words":[{"w":"绿水逶迤","e":"【易错】「绿水逶迤」的「逶迤」读 wēi yí，形容河道曲折绵延，不要读成 wěi yí，也不要写成「委蛇」。"},{"w":"微动涟漪","e":"【易错】「微动涟漪」的「涟漪」读 lián yī，指细小的波纹，两个字都是三点水，不写「连衣」。"},{"w":"掠岸飞","e":"是擦过岸边飞起"},{"w":"水很滑","e":"【易错】“无风水面琉璃滑”的「琉璃」比喻水面澄澈光滑如琉璃，不是实指琉璃瓦，也不能解作「水很滑」。"},{"w":"采桑子","e":"【易错】词牌「采桑子」的「采」不写「彩」；「采桑子」是词牌名，与采桑的内容并无必然关系。"},{"w":"短棹","e":"指短小的船桨"},{"w":"西湖","e":"指颍州西湖"},{"w":"芳草","e":"指芬芳的青草"},{"w":"琉璃","e":"是一种光滑透明的釉料"},{"w":"沙禽","e":"指沙洲、沙滩上的水鸟"},{"w":"逶迤","e":"【易错】「绿水逶迤」的「逶迤」读 wēi yí，形容河道曲折绵延，不要读成 wěi yí，也不要写成「委蛇」。"},{"w":"委蛇","e":"【易错】「绿水逶迤」的「逶迤」读 wēi yí，形容河道曲折绵延，不要读成 wěi yí，也不要写成「委蛇」。"},{"w":"涟漪","e":"【易错】「微动涟漪」的「涟漪」读 lián yī，指细小的波纹，两个字都是三点水，不写「连衣」。"},{"w":"连衣","e":"【易错】「微动涟漪」的「涟漪」读 lián yī，指细小的波纹，两个字都是三点水，不写「连衣」。"},{"w":"笙歌","e":"【易错】「隐隐笙歌处处随」的「笙歌」泛指奏乐唱歌，不只是「笙这种乐器」；「隐隐」写声音隐约，不写「影影」。"},{"w":"隐隐","e":"【易错】「隐隐笙歌处处随」的「笙歌」泛指奏乐唱歌，不只是「笙这种乐器」；「隐隐」写声音隐约，不写「影影」。"},{"w":"影影","e":"【易错】「隐隐笙歌处处随」的「笙歌」泛指奏乐唱歌，不只是「笙这种乐器」；「隐隐」写声音隐约，不写「影影」。"},{"w":"棹","e":"【易错】“轻舟短棹西湖好”的「棹」读 zhào，是船桨，木字旁，不写「掉」「桌」。"},{"w":"掉","e":"【易错】“轻舟短棹西湖好”的「棹」读 zhào，是船桨，木字旁，不写「掉」「桌」。"},{"w":"桌","e":"【易错】“轻舟短棹西湖好”的「棹」读 zhào，是船桨，木字旁，不写「掉」「桌」。"},{"w":"采","e":"【易错】词牌「采桑子」的「采」不写「彩」；「采桑子」是词牌名，与采桑的内容并无必然关系。"},{"w":"彩","e":"【易错】词牌「采桑子」的「采」不写「彩」；「采桑子」是词牌名，与采桑的内容并无必然关系。"}]},{"type":"list","title":"名句","items":["轻舟短棹西湖好，绿水逶迤。","微动涟漪，惊起沙禽掠岸飞。"]},{"type":"list","title":"背诵提示","items":["“轻舟短棹西湖好”的「棹」读 zhào，是船桨，木字旁，不写「掉」「桌」。","「绿水逶迤」的「逶迤」读 wēi yí，形容河道曲折绵延，不要读成 wěi yí，也不要写成「委蛇」。","“无风水面琉璃滑”的「琉璃」比喻水面澄澈光滑如琉璃，不是实指琉璃瓦，也不能解作「水很滑」。","「微动涟漪」的「涟漪」读 lián yī，指细小的波纹，两个字都是三点水，不写「连衣」。","「隐隐笙歌处处随」的「笙歌」泛指奏乐唱歌，不只是「笙这种乐器」；「隐隐」写声音隐约，不写「影影」。","词牌「采桑子」的「采」不写「彩」；「采桑子」是词牌名，与采桑的内容并无必然关系。"]}],"questions":[{"id":"p-p8a-cai-sang-zi-m0","type":"fill","stem":"默写填空：轻舟短棹西湖好，______。","answer":"绿水逶迤。","explain":"出自《采桑子（轻舟短棹西湖好）》（宋·欧阳修）：轻舟短棹西湖好，绿水逶迤。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-cai-sang-zi-m1","type":"fill","stem":"默写填空：微动涟漪，______。","answer":"惊起沙禽掠岸飞。","explain":"出自《采桑子（轻舟短棹西湖好）》（宋·欧阳修）：微动涟漪，惊起沙禽掠岸飞。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-cai-sang-zi-u","type":"fill","stem":"理解性默写：轻便的小舟、短短的船桨，西湖的风光多么美好；碧绿的湖水曲折绵延。「短棹」指短小的船桨，棹读 zhào；「西湖」指颍州西湖；「逶迤」读 wēi yí，形容曲折绵延的样子。","answer":"轻舟短棹西湖好，绿水逶迤。","explain":"出自《采桑子（轻舟短棹西湖好）》（宋·欧阳修）。句意：轻便的小舟、短短的船桨，西湖的风光多么美好；碧绿的湖水曲折绵延。「短棹」指短小的船桨，棹读 zhào；「西湖」指颍州西湖；「逶迤」读 wēi yí，形容曲折绵延的样子。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-xiang-jian-huan-zhu-dun-ru","title":"相见欢（金陵城上西楼）","subtitle":"宋·朱敦儒","grade":"8a","tags":["亡国之痛","爱国","思乡","登临"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·朱敦儒"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"朱敦儒（1081—1159），字希真，号岩壑，洛阳（今河南洛阳）人，两宋之交的词人，词集名《樵歌》。\n生平经历：北宋末年他隐居不仕，以清高自许，词作多写山水闲适之趣；靖康之变后中原沦陷，他南渡流寓两浙、江西一带，词风由此一变；南宋初年曾应召入朝任职，后再度归隐。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是朱敦儒南渡后客居金陵时所作的一首词，写登楼远望而生的亡国之痛与忧国之情。上片写景：首句“金陵城上西楼，倚清秋”点明登临的地点与时令，一个「倚」字写词人久久倚楼凝望的身影，「清秋」二字一出便定下苍凉基调；接着“万里夕阳垂地大江流”以壮阔之笔写眼前景象，万里夕阳沉沉下垂，长江浩荡东流，境界阔大而气象衰飒，「垂地」二字既写落日之低，又暗喻国势之衰，为下片抒情蓄势。下片直抒胸臆：“中原乱，簪缨散，几时收”三句短促有力，一句一顿，写中原沦陷、官员士人流离失散、国土不知何时收复的惨痛现实，其中「簪缨」以官员冠饰借代达官贵人，指代明确，「乱」「散」二字字字沉痛；结句“试倩悲风吹泪过扬州”以一个「倩」（请、央求）字写无可奈何中的痴想，请悲风把自己的泪水吹到抗金前线的扬州，寄托对故土的怀念与对国事的忧愤，语极沉痛。全词上片借景抒情，下片议论抒情、直抒胸臆，风格苍凉沉郁，是南渡爱国词中的名篇"},{"type":"list","title":"中考考点","items":["「簪缨」「倩」的含义及「倩」的读音（qìng）","「簪缨」的借代手法与“万里夕阳垂地”的夸张","“几时收”的反问及结句所表达的亡国之痛、爱国之情","上片写景与下片抒情的关系（借景抒情、情景交融）。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"金陵城上西楼，倚清秋。","n":"","cn":"我登上金陵城西的城楼，倚楼而望，满眼是清冷的秋色。「金陵」即今江苏南京；「西楼」指城西的城楼；「倚清秋」是说倚楼远眺，眼前一派清秋景象。","parts":[{"t":"金陵","k":5},{"t":"城上"},{"t":"西楼","k":6},{"t":"，"},{"t":"倚清秋","k":0},{"t":"。"}]},{"t":"万里夕阳垂地大江流。","n":"","cn":"万里长空，夕阳沉沉下垂仿佛要挨到地面，长江浩浩荡荡地向东流去。「垂地」写落日低垂、贴近地面；「大江」指长江。","parts":[{"t":"万里夕阳垂地"},{"t":"大江","k":7},{"t":"流。"}]},{"t":"中原乱，簪缨散，几时收？","n":"","cn":"中原战乱纷起，官员士大夫流离失散，什么时候才能收复失地呢？「中原乱」指金兵南下、中原沦陷的靖康之乱；「簪缨」本是古代官员的冠饰，这里借代指达官贵人；「收」指收复失地。","parts":[{"t":"中原乱","k":1},{"t":"，"},{"t":"簪缨散","k":2},{"t":"，"},{"t":"几时收","k":3},{"t":"？"}]},{"t":"试倩悲风吹泪过扬州。","n":"","cn":"请让这悲凉的秋风把我的泪水吹过扬州去吧。「倩」读 qìng，是请、央求的意思；「悲风」指悲凉的秋风；「扬州」在当时是抗金的前线。","parts":[{"t":"试"},{"t":"倩","k":13},{"t":"悲风","k":8},{"t":"吹泪过扬州。"}]}],"words":[{"w":"倚清秋","e":"是说倚楼远眺"},{"w":"中原乱","e":"指金兵南下、中原沦陷的靖康之乱"},{"w":"簪缨散","e":"【易错】「簪缨散」的「簪缨」本是古代官员的冠饰（簪与帽带），这里借代指达官贵人，不是真的「簪子和带子散落一地」。"},{"w":"几时收","e":"【易错】“几时收”的「收」是收复（失地）的意思，不是「收起来」「收割」。"},{"w":"收起来","e":"【易错】“几时收”的「收」是收复（失地）的意思，不是「收起来」「收割」。"},{"w":"金陵","e":"即今江苏南京"},{"w":"西楼","e":"指城西的城楼"},{"w":"大江","e":"指长江"},{"w":"悲风","e":"指悲凉的秋风"},{"w":"簪缨","e":"【易错】「簪缨散」的「簪缨」本是古代官员的冠饰（簪与帽带），这里借代指达官贵人，不是真的「簪子和带子散落一地」。"},{"w":"收割","e":"【易错】“几时收”的「收」是收复（失地）的意思，不是「收起来」「收割」。"},{"w":"清秋","e":"【易错】“金陵城上西楼，倚清秋”的「倚」是靠着、倚楼而望，不写「依」；「清秋」指清冷的秋天。"},{"w":"收","e":"指收复失地"},{"w":"倩","e":"【易错】“试倩悲风吹泪过扬州”的「倩」读 qìng，是请、央求的意思，不读 qiàn，也不写「清」「晴」。"},{"w":"清","e":"【易错】“试倩悲风吹泪过扬州”的「倩」读 qìng，是请、央求的意思，不读 qiàn，也不写「清」「晴」。"},{"w":"晴","e":"【易错】“试倩悲风吹泪过扬州”的「倩」读 qìng，是请、央求的意思，不读 qiàn，也不写「清」「晴」。"},{"w":"簪","e":"【易错】「簪缨」的「簪」是竹字头，不写「赞」；「缨」是绞丝旁，不写「樱」「鹰」。"},{"w":"赞","e":"【易错】「簪缨」的「簪」是竹字头，不写「赞」；「缨」是绞丝旁，不写「樱」「鹰」。"},{"w":"缨","e":"【易错】「簪缨」的「簪」是竹字头，不写「赞」；「缨」是绞丝旁，不写「樱」「鹰」。"},{"w":"樱","e":"【易错】「簪缨」的「簪」是竹字头，不写「赞」；「缨」是绞丝旁，不写「樱」「鹰」。"},{"w":"鹰","e":"【易错】「簪缨」的「簪」是竹字头，不写「赞」；「缨」是绞丝旁，不写「樱」「鹰」。"},{"w":"倚","e":"【易错】“金陵城上西楼，倚清秋”的「倚」是靠着、倚楼而望，不写「依」；「清秋」指清冷的秋天。"},{"w":"依","e":"【易错】“金陵城上西楼，倚清秋”的「倚」是靠着、倚楼而望，不写「依」；「清秋」指清冷的秋天。"}]},{"type":"list","title":"名句","items":["万里夕阳垂地大江流。","试倩悲风吹泪过扬州。"]},{"type":"list","title":"背诵提示","items":["「簪缨散」的「簪缨」本是古代官员的冠饰（簪与帽带），这里借代指达官贵人，不是真的「簪子和带子散落一地」。","“试倩悲风吹泪过扬州”的「倩」读 qìng，是请、央求的意思，不读 qiàn，也不写「清」「晴」。","「簪缨」的「簪」是竹字头，不写「赞」；「缨」是绞丝旁，不写「樱」「鹰」。","“几时收”的「收」是收复（失地）的意思，不是「收起来」「收割」。","“金陵城上西楼，倚清秋”的「倚」是靠着、倚楼而望，不写「依」；「清秋」指清冷的秋天。","本词作者是朱敦儒，不要与库内李煜的《相见欢（无言独上西楼）》相混，两首词牌相同而作者、内容、情感完全不同。"]}],"questions":[{"id":"p-p8a-xiang-jian-huan-zhu-dun-ru-u","type":"fill","stem":"理解性默写：我登上金陵城西的城楼，倚楼而望，满眼是清冷的秋色。「金陵」即今江苏南京；「西楼」指城西的城楼；「倚清秋」是说倚楼远眺，眼前一派清秋景象。","answer":"金陵城上西楼，倚清秋。","explain":"出自《相见欢（金陵城上西楼）》（宋·朱敦儒）。句意：我登上金陵城西的城楼，倚楼而望，满眼是清冷的秋色。「金陵」即今江苏南京；「西楼」指城西的城楼；「倚清秋」是说倚楼远眺，眼前一派清秋景象。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p8a-ru-meng-ling","title":"如梦令（常记溪亭日暮）","subtitle":"宋·李清照","grade":"8a","tags":["闺情","游赏","欢快","白描"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·李清照"},{"k":"体裁","v":"词"}]},{"type":"note","title":"作者简介","text":"李清照（1084—约1155），号易安居士，齐州章丘（今山东济南）人，宋代婉约词派的代表词人，她在《词论》中提出词“别是一家”之说，与辛弃疾并称“济南二安”。\n生平经历：她出身书香门第，早年与丈夫赵明诚共同收藏金石书画，生活优裕，词作多写闺中生活与离情别绪；靖康之变后中原沦陷，她随夫南渡，不久丈夫病逝，此后辗转江浙一带，晚境孤苦凄凉。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是李清照追忆少女时代一次荡舟游赏的小令，全词仅三十三字，却写出一段曲折生动的往事。首句“常记溪亭日暮”以「常记」二字点明所写是回忆，溪边亭中饮酒游赏直至日暮；“沉醉不知归路”既写酒醉，也写为美景所陶醉而流连忘返，写出少女的天真烂漫。次句“兴尽晚回舟，误入藕花深处”写游兴已尽、乘舟晚归，却因醉意与暮色而误入荷花丛中，一个「误」字生出下文波澜，行文顿起跌宕。末句连用两个「争渡」，写急切划桨、争相竞渡的情态，叠句节奏急促，与慌乱而欢快的心绪相合；“惊起一滩鸥鹭”以鸥鹭惊飞的动景收束全篇，动静相生，画面明丽飞动，余味无穷。全词以白描手法写景叙事，语言自然清新，节奏明快，表现出词人热爱生活、热爱自然的欢快心情和少女的活泼天真"},{"type":"list","title":"中考考点","items":["「常记」「沉醉」「藕花」「争渡」等词释义，注意「争」是竞相、抢着而非「怎么」","两个「争渡」叠句的表达效果","“惊起一滩鸥鹭”中「惊」字的赏析与动静结合的写法","全词所表现的少女情怀与欢快的生活情趣。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"常记溪亭日暮，沉醉不知归路。","n":"","cn":"常常记起在溪边亭中游赏的那个黄昏，我沉醉其中，认不得回去的路。「常记」是常常记起；「溪亭」指溪边的亭子；「日暮」是天色黄昏；「沉醉」写饮酒而醉，也含为美景所陶醉之意。","parts":[{"t":"常记","k":2},{"t":"溪亭","k":3},{"t":"日暮","k":4},{"t":"，"},{"t":"沉醉","k":15},{"t":"不知归"},{"t":"路","k":22},{"t":"。"}]},{"t":"兴尽晚回舟，误入藕花深处。","n":"","cn":"游兴尽了，天色已晚才划船返回，却不小心闯进了荷花丛的深处。「兴尽」指游兴已尽；「晚回舟」是天色晚了才往回划船；「误入」是不小心进入；「藕花」指荷花。","parts":[{"t":"兴尽","k":5},{"t":"晚回舟","k":0},{"t":"，"},{"t":"误入","k":6},{"t":"藕花","k":7},{"t":"深处。"}]},{"t":"争渡，争渡，惊起一滩鸥鹭。","n":"","cn":"抢着划呀，抢着划呀，惊起了满滩的鸥鸟和白鹭。「争渡」是竞相划船、抢着划船，「争」不是「怎么」的意思；「一滩」指满滩；「鸥鹭」指鸥鸟和白鹭。","parts":[{"t":"争渡","k":8},{"t":"，"},{"t":"争渡","k":8},{"t":"，惊起"},{"t":"一滩","k":9},{"t":"鸥鹭","k":10},{"t":"。"}]}],"words":[{"w":"晚回舟","e":"是天色晚了才往回划船"},{"w":"怎么渡","e":"【易错】「争渡，争渡」的「争」是竞相、抢着（划船）的意思，不是「怎么渡」，也不是「争夺」，「争渡」即抢着划船、奋力划船。"},{"w":"常记","e":"是常常记起"},{"w":"溪亭","e":"指溪边的亭子"},{"w":"日暮","e":"是天色黄昏"},{"w":"兴尽","e":"指游兴已尽"},{"w":"误入","e":"是不小心进入"},{"w":"藕花","e":"指荷花"},{"w":"争渡","e":"是竞相划船、抢着划船"},{"w":"一滩","e":"指满滩"},{"w":"鸥鹭","e":"指鸥鸟和白鹭"},{"w":"争夺","e":"【易错】「争渡，争渡」的「争」是竞相、抢着（划船）的意思，不是「怎么渡」，也不是「争夺」，「争渡」即抢着划船、奋力划船。"},{"w":"耦花","e":"【易错】「误入藕花深处」的「藕花」指荷花，不要写成「耦花」「偶花」。"},{"w":"偶花","e":"【易错】「误入藕花深处」的「藕花」指荷花，不要写成「耦花」「偶花」。"},{"w":"长记","e":"【易错】「常记溪亭日暮」教材作「常记」，是常常记起，不要写成「长记」。"},{"w":"沉醉","e":"【易错】「沉醉不知归路」的「沉醉」写饮酒而醉，也含为美景陶醉之意，不要理解为「沉睡」「沉没」。"},{"w":"沉睡","e":"【易错】「沉醉不知归路」的「沉醉」写饮酒而醉，也含为美景陶醉之意，不要理解为「沉睡」「沉没」。"},{"w":"沉没","e":"【易错】「沉醉不知归路」的「沉醉」写饮酒而醉，也含为美景陶醉之意，不要理解为「沉睡」「沉没」。"},{"w":"争","e":"是竞相、抢着而非「怎么」"},{"w":"鹭","e":"【易错】「惊起一滩鸥鹭」的「鸥鹭」是鸥鸟和白鹭，「鹭」下面是「鸟」，不写「露」「路」。"},{"w":"鸟","e":"【易错】「惊起一滩鸥鹭」的「鸥鹭」是鸥鸟和白鹭，「鹭」下面是「鸟」，不写「露」「路」。"},{"w":"露","e":"【易错】「惊起一滩鸥鹭」的「鸥鹭」是鸥鸟和白鹭，「鹭」下面是「鸟」，不写「露」「路」。"},{"w":"路","e":"【易错】「惊起一滩鸥鹭」的「鸥鹭」是鸥鸟和白鹭，「鹭」下面是「鸟」，不写「露」「路」。"}]},{"type":"list","title":"名句","items":["争渡，争渡，惊起一滩鸥鹭。"]},{"type":"list","title":"背诵提示","items":["「争渡，争渡」的「争」是竞相、抢着（划船）的意思，不是「怎么渡」，也不是「争夺」，「争渡」即抢着划船、奋力划船。","「误入藕花深处」的「藕花」指荷花，不要写成「耦花」「偶花」。","两个「争渡」是叠句，默写时容易漏写一遍，须连写两次，中间用逗号隔开。","「惊起一滩鸥鹭」的「鸥鹭」是鸥鸟和白鹭，「鹭」下面是「鸟」，不写「露」「路」。","「常记溪亭日暮」教材作「常记」，是常常记起，不要写成「长记」。","「沉醉不知归路」的「沉醉」写饮酒而醉，也含为美景陶醉之意，不要理解为「沉睡」「沉没」。"]}],"questions":[{"id":"p-p8a-ru-meng-ling-m0","type":"fill","stem":"默写填空：争渡，______。","answer":"争渡。","explain":"出自《如梦令（常记溪亭日暮）》（宋·李清照）：争渡，争渡，惊起一滩鸥鹭。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p8a-ru-meng-ling-u","type":"fill","stem":"理解性默写：常常记起在溪边亭中游赏的那个黄昏，我沉醉其中，认不得回去的路。「常记」是常常记起；「溪亭」指溪边的亭子；「日暮」是天色黄昏；「沉醉」写饮酒而醉，也含为美景所陶醉之意。","answer":"常记溪亭日暮，沉醉不知归路。","explain":"出自《如梦令（常记溪亭日暮）》（宋·李清照）。句意：常常记起在溪边亭中游赏的那个黄昏，我沉醉其中，认不得回去的路。「常记」是常常记起；「溪亭」指溪边的亭子；「日暮」是天色黄昏；「沉醉」写饮酒而醉，也含为美景所陶醉之意。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-nan-an-jun","title":"南安军","subtitle":"宋·文天祥","grade":"9b","tags":["爱国","坚贞","用典","气节"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"宋·文天祥"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"文天祥（1236—1283），字宋瑞，又字履善，号文山，南宋末年政治家、文学家、民族英雄，吉州庐陵（今江西吉安）人。\n生平经历：宝祐四年考中状元；元军南下时，他散尽家财起兵抗元，转战东南多年；兵败被俘后押解北上，途经零丁洋写下《过零丁洋》以明志；被囚大都三年，始终拒绝降元，最终从容就义。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这首诗作于文天祥被俘押解北上、途经江西南安军（今江西大余）之时，诗人曾在此绝食，以死明志。首联写行程与景物，以「风雨」「湿征衣」营造凄冷沉重的氛围，景中含情，暗写身陷囚系、国破家亡的处境。颔联连用问句与感叹句：“出岭同谁出？”写当年一同起兵抗元的战友或死或散，如今孤身被押，孤独悲愤；“归乡如不归！”写途经故乡而身为囚徒，虽归犹不归，语极沉痛。颈联是全诗名句，以“山河千古在”与“城郭一时非”对举，一永恒、一易主，又化用杜甫“国破山河在”与丁令威“城郭犹是人民非”之意，把亡国之痛放在时间的对比中，更显深挚。尾联“饿死真吾志”直抒胸臆，以伯夷、叔齐采薇首阳山的典故表明宁死不食周粟、以身殉国的决心，与《过零丁洋》“留取丹心照汗青”同一旨趣，全诗于质朴中见至情，是用血泪写成的作品"},{"type":"list","title":"中考考点","items":["“归乡如不归”的含义与“出岭同谁出”所抒发的孤独悲愤","颈联的对比手法与化用古人诗句的作用","“采薇”典故的出处与用以明志的用意","尾联表现的民族气节与爱国精神","常考默写句“山河千古在，城郭一时非”“饿死真吾志，梦中行采薇”。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"梅花南北路，风雨湿征衣。","n":"","cn":"梅花岭上南北往来的道路上，风雨打湿了我这远行之人的衣服。「梅花」指梅岭，又称大庾岭，是江西与广东之间的通道；「征衣」指出行、出征之人所穿的衣服。","parts":[{"t":"梅花","k":4},{"t":"南北路，风雨湿"},{"t":"征衣","k":5},{"t":"。"}]},{"t":"出岭同谁出？归乡如不归！","n":"","cn":"翻越梅岭时还有谁与我同行呢？回到故乡却如同没有归去一样。「出岭」指翻过梅岭；「同谁出」以问句写当年一同抗元的战友或牺牲或离散，如今只剩自己孤身被押；「归乡如不归」指诗人被俘押解北上，虽经过家乡却身为囚徒，与没有归去无异。","parts":[{"t":"出岭","k":6},{"t":"同谁"},{"t":"出","k":19},{"t":"？"},{"t":"归乡如不归","k":0},{"t":"！"}]},{"t":"山河千古在，城郭一时非。","n":"","cn":"山河千年万代依旧存在，城郭却在一时之间已不是原来的样子（沦陷于元）。这两句以山河的永恒反衬国破城非之痛，化用了杜甫“国破山河在”与丁令威“城郭犹是人民非”之意。","parts":[{"t":"山河千古在，"},{"t":"城郭","k":12},{"t":"一时非","k":3},{"t":"。"}]},{"t":"饿死真吾志，梦中行采薇。","n":"","cn":"饿死正是我的志愿，我只能在梦中采薇而食了。「饿死真吾志」直抒以身殉国的决心，教材作「饿死」，一作「饥死」；「采薇」用伯夷、叔齐不食周粟、隐居首阳山采薇而食终于饿死的典故。","parts":[{"t":"饿死","k":8},{"t":"真"},{"t":"吾志","k":10},{"t":"，梦中行"},{"t":"采薇","k":11},{"t":"。"}]}],"words":[{"w":"归乡如不归","e":"指诗人被俘押解北上"},{"w":"不如不归","e":"【易错】“南冠”是囚徒的代称（典出《左传》楚囚戴南冠），不能按字面理解为「南方的帽子」；「归乡如不归」是「回到故乡却如同没有归去」，不要写成「归乡如此归」，也不译作「不如不归」。"},{"w":"一时不对","e":"【易错】「城郭一时非」的「城郭」指城池（内城为城，外城为郭），不写「城阔」；「一时非」指一时之间已不是原来的山河，不要理解为「一时不对」。"},{"w":"一时非","e":"【易错】「城郭一时非」的「城郭」指城池（内城为城，外城为郭），不写「城阔」；「一时非」指一时之间已不是原来的山河，不要理解为「一时不对」。"},{"w":"梅花","e":"指梅岭"},{"w":"征衣","e":"指出行、出征之人所穿的衣服"},{"w":"出岭","e":"指翻过梅岭"},{"w":"南冠","e":"【易错】“南冠”是囚徒的代称（典出《左传》楚囚戴南冠），不能按字面理解为「南方的帽子」；「归乡如不归」是「回到故乡却如同没有归去」，不要写成「归乡如此归」，也不译作「不如不归」。"},{"w":"饿死","e":"【易错】「饿死真吾志」教材作「饿死」，不要写成「饥死」；「吾志」的「吾」不写「吴」。"},{"w":"饥死","e":"【易错】「饿死真吾志」教材作「饿死」，不要写成「饥死」；「吾志」的「吾」不写「吴」。"},{"w":"吾志","e":"【易错】「饿死真吾志」教材作「饿死」，不要写成「饥死」；「吾志」的「吾」不写「吴」。"},{"w":"采薇","e":"【易错】「梦中行采薇」的「采薇」用伯夷、叔齐不食周粟、采薇首阳山的典故，不可只理解为采野菜；「薇」是草字头，不写成「微」。"},{"w":"城郭","e":"【易错】「城郭一时非」的「城郭」指城池（内城为城，外城为郭），不写「城阔」；「一时非」指一时之间已不是原来的山河，不要理解为「一时不对」。"},{"w":"城阔","e":"【易错】「城郭一时非」的「城郭」指城池（内城为城，外城为郭），不写「城阔」；「一时非」指一时之间已不是原来的山河，不要理解为「一时不对」。"},{"w":"征依","e":"【易错】「梅花南北路」的「梅花」指梅岭（大庾岭）这一地名，不是梅花树；「征衣」指出行者的衣服，不写「征依」。"},{"w":"吾","e":"【易错】「饿死真吾志」教材作「饿死」，不要写成「饥死」；「吾志」的「吾」不写「吴」。"},{"w":"吴","e":"【易错】「饿死真吾志」教材作「饿死」，不要写成「饥死」；「吾志」的「吾」不写「吴」。"},{"w":"薇","e":"【易错】「梦中行采薇」的「采薇」用伯夷、叔齐不食周粟、采薇首阳山的典故，不可只理解为采野菜；「薇」是草字头，不写成「微」。"},{"w":"微","e":"【易错】「梦中行采薇」的「采薇」用伯夷、叔齐不食周粟、采薇首阳山的典故，不可只理解为采野菜；「薇」是草字头，不写成「微」。"},{"w":"出","e":"【易错】「出岭同谁出」是问句，句末的「？」与第二个「出」都不要漏；与其下「归乡如不归」句式相近，注意两个「归」都要写。"},{"w":"归","e":"【易错】「出岭同谁出」是问句，句末的「？」与第二个「出」都不要漏；与其下「归乡如不归」句式相近，注意两个「归」都要写。"}]},{"type":"list","title":"名句","items":["山河千古在，城郭一时非。","饿死真吾志，梦中行采薇。"]},{"type":"list","title":"背诵提示","items":["“南冠”是囚徒的代称（典出《左传》楚囚戴南冠），不能按字面理解为「南方的帽子」；「归乡如不归」是「回到故乡却如同没有归去」，不要写成「归乡如此归」，也不译作「不如不归」。","「饿死真吾志」教材作「饿死」，不要写成「饥死」；「吾志」的「吾」不写「吴」。","「梦中行采薇」的「采薇」用伯夷、叔齐不食周粟、采薇首阳山的典故，不可只理解为采野菜；「薇」是草字头，不写成「微」。","「城郭一时非」的「城郭」指城池（内城为城，外城为郭），不写「城阔」；「一时非」指一时之间已不是原来的山河，不要理解为「一时不对」。","「梅花南北路」的「梅花」指梅岭（大庾岭）这一地名，不是梅花树；「征衣」指出行者的衣服，不写「征依」。","「出岭同谁出」是问句，句末的「？」与第二个「出」都不要漏；与其下「归乡如不归」句式相近，注意两个「归」都要写。"]}],"questions":[{"id":"p-p9b-nan-an-jun-m0","type":"fill","stem":"默写填空：山河千古在，______。","answer":"城郭一时非。","explain":"出自《南安军》（宋·文天祥）：山河千古在，城郭一时非。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-nan-an-jun-m1","type":"fill","stem":"默写填空：饿死真吾志，______。","answer":"梦中行采薇。","explain":"出自《南安军》（宋·文天祥）：饿死真吾志，梦中行采薇。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-nan-an-jun-u","type":"fill","stem":"理解性默写：梅花岭上南北往来的道路上，风雨打湿了我这远行之人的衣服。「梅花」指梅岭，又称大庾岭，是江西与广东之间的通道；「征衣」指出行、出征之人所穿的衣服。","answer":"梅花南北路，风雨湿征衣。","explain":"出自《南安军》（宋·文天祥）。句意：梅花岭上南北往来的道路上，风雨打湿了我这远行之人的衣服。「梅花」指梅岭，又称大庾岭，是江西与广东之间的通道；「征衣」指出行、出征之人所穿的衣服。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-bie-yun-jian","title":"别云间","subtitle":"明·夏完淳","grade":"9b","tags":["爱国","坚贞","气节","思乡"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"明·夏完淳"},{"k":"体裁","v":"诗"}]},{"type":"note","title":"作者简介","text":"夏完淳（1631—1647），字存古，松江华亭（今上海松江）人，明末诗人、少年抗清英雄。\n生平经历：他自幼聪慧，少年时便随父亲夏允彝、老师陈子龙投身抗清斗争；父亲与老师相继殉国后，他仍坚持在江南一带联络义军；被捕后押解南京，面对劝降痛骂不屈，慷慨就义，年仅十七岁。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是夏完淳十七岁被捕后写下的绝命诗，诗题「别云间」意为告别故乡（云间是松江的古称）。首联“三年羁旅客，今日又南冠”以「三年」与「今日」对举，概括三年抗清漂泊与此刻身陷囚牢的处境，一个「又」字含无尽愤慨与悲凉。颔联“无限河山泪，谁言天地宽”以反问抒情：山河破碎，泪洒无限，天地虽阔却不容志士立身，悲慨喷薄而出。颈联“已知泉路近，欲别故乡难”直写死别之痛，一「近」一「难」，视死如归与眷恋故乡两种情感并存，真切而不作悲声。尾联“毅魄归来日，灵旗空际看”由悲转壮，以浪漫的想象写死后魂魄归来、仍要在长空看到抗清战旗，把民族气节写到极处，与文天祥“留取丹心照汗青”同样掷地有声。全诗直抒胸臆，语言朴素而情感沉痛，是明末爱国诗中的名篇"},{"type":"list","title":"中考考点","items":["「南冠」「泉路」「毅魄」「灵旗」等词语的含义","颔联反问句的表达效果","颈联「近」与「难」所抒发的复杂情感","尾联想象（虚写）手法的浪漫色彩与视死如归的爱国精神。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"三年羁旅客，今日又南冠。","n":"","cn":"（我）做了三年漂泊在外的客子，今天又成了囚徒。「羁旅客」指长期寄居他乡、漂泊不定的人；「南冠」是囚徒的代称，典出《左传》，写被俘的楚人仍戴南方的帽子，这里指自己被清兵逮捕。","parts":[{"t":"三年"},{"t":"羁旅客","k":0},{"t":"，今日又"},{"t":"南冠","k":3},{"t":"。"}]},{"t":"无限河山泪，谁言天地宽。","n":"","cn":"为无限沦陷的河山流下眼泪，谁还能说天地是宽广的呢？「河山」指沦陷的明朝国土；「谁言天地宽」以反问抒发天地虽大却无处容身的悲愤。","parts":[{"t":"无限"},{"t":"河山","k":4},{"t":"泪，谁言天地宽。"}]},{"t":"已知泉路近，欲别故乡难。","n":"","cn":"已经知道自己离黄泉之路越来越近了，可要与故乡分别实在难以割舍。「泉路」指黄泉之路，即死亡；一「近」一「难」，把视死如归与眷恋故土两种情感交织在一起。","parts":[{"t":"已知"},{"t":"泉路","k":5},{"t":"近，"},{"t":"欲","k":32},{"t":"别故乡难。"}]},{"t":"毅魄归来日，灵旗空际看。","n":"","cn":"等到我坚毅的魂魄归来那一天，将在天空中看到抗清的旗帜。「毅魄」指刚毅不屈的魂魄；「灵旗」指战旗，这里指抗清的旗帜；「空际看」即在空中相看，写出至死不渝的抗清复国之志。","parts":[{"t":"毅魄","k":6},{"t":"归来日，"},{"t":"灵旗","k":7},{"t":"空际看","k":1},{"t":"。"}]}],"words":[{"w":"羁旅客","e":"指长期寄居他乡、漂泊不定的人"},{"w":"空际看","e":"即在空中相看"},{"w":"别云间","e":"意为告别故乡（云间是松江的古称）"},{"w":"南冠","e":"是囚徒的代称"},{"w":"河山","e":"指沦陷的明朝国土"},{"w":"泉路","e":"指黄泉之路"},{"w":"毅魄","e":"指刚毅不屈的魂魄"},{"w":"灵旗","e":"指战旗"},{"w":"南官","e":"【易错】「今日又南冠」的「南冠」是囚徒的代称，不要按字面写成「南方的帽子」，也不要写成「南官」「男冠」。"},{"w":"男冠","e":"【易错】「今日又南冠」的「南冠」是囚徒的代称，不要按字面写成「南方的帽子」，也不要写成「南官」「男冠」。"},{"w":"空际","e":"【易错】「灵旗空际看」的「旗」是方字旁加「其」，不写「棋」「琪」；「空际」指天空、空中，不要写成「空寂」。"},{"w":"空寂","e":"【易错】「灵旗空际看」的「旗」是方字旁加「其」，不写「棋」「琪」；「空际」指天空、空中，不要写成「空寂」。"},{"w":"旅客","e":"【易错】「三年羁旅客」的「羁」上半是「罒」、下半由「革」「马」构成，不要写成「冀」「寄」；「旅客」指漂泊在外的人，不是今天的「游客」。"},{"w":"游客","e":"【易错】「三年羁旅客」的「羁」上半是「罒」、下半由「革」「马」构成，不要写成「冀」「寄」；「旅客」指漂泊在外的人，不是今天的「游客」。"},{"w":"毅","e":"【易错】「毅魄归来日」的「毅」是刚毅、坚决之意，不写成「意」「义」；「魄」的右半是「鬼」，不写成「愧」。"},{"w":"意","e":"【易错】「毅魄归来日」的「毅」是刚毅、坚决之意，不写成「意」「义」；「魄」的右半是「鬼」，不写成「愧」。"},{"w":"义","e":"【易错】「毅魄归来日」的「毅」是刚毅、坚决之意，不写成「意」「义」；「魄」的右半是「鬼」，不写成「愧」。"},{"w":"魄","e":"【易错】「毅魄归来日」的「毅」是刚毅、坚决之意，不写成「意」「义」；「魄」的右半是「鬼」，不写成「愧」。"},{"w":"鬼","e":"【易错】「毅魄归来日」的「毅」是刚毅、坚决之意，不写成「意」「义」；「魄」的右半是「鬼」，不写成「愧」。"},{"w":"愧","e":"【易错】「毅魄归来日」的「毅」是刚毅、坚决之意，不写成「意」「义」；「魄」的右半是「鬼」，不写成「愧」。"},{"w":"旗","e":"【易错】「灵旗空际看」的「旗」是方字旁加「其」，不写「棋」「琪」；「空际」指天空、空中，不要写成「空寂」。"},{"w":"其","e":"【易错】「灵旗空际看」的「旗」是方字旁加「其」，不写「棋」「琪」；「空际」指天空、空中，不要写成「空寂」。"},{"w":"棋","e":"【易错】「灵旗空际看」的「旗」是方字旁加「其」，不写「棋」「琪」；「空际」指天空、空中，不要写成「空寂」。"},{"w":"琪","e":"【易错】「灵旗空际看」的「旗」是方字旁加「其」，不写「棋」「琪」；「空际」指天空、空中，不要写成「空寂」。"},{"w":"羁","e":"【易错】「三年羁旅客」的「羁」上半是「罒」、下半由「革」「马」构成，不要写成「冀」「寄」；「旅客」指漂泊在外的人，不是今天的「游客」。"},{"w":"罒","e":"【易错】「三年羁旅客」的「羁」上半是「罒」、下半由「革」「马」构成，不要写成「冀」「寄」；「旅客」指漂泊在外的人，不是今天的「游客」。"},{"w":"革","e":"【易错】「三年羁旅客」的「羁」上半是「罒」、下半由「革」「马」构成，不要写成「冀」「寄」；「旅客」指漂泊在外的人，不是今天的「游客」。"},{"w":"马","e":"【易错】「三年羁旅客」的「羁」上半是「罒」、下半由「革」「马」构成，不要写成「冀」「寄」；「旅客」指漂泊在外的人，不是今天的「游客」。"},{"w":"冀","e":"【易错】「三年羁旅客」的「羁」上半是「罒」、下半由「革」「马」构成，不要写成「冀」「寄」；「旅客」指漂泊在外的人，不是今天的「游客」。"},{"w":"寄","e":"【易错】「三年羁旅客」的「羁」上半是「罒」、下半由「革」「马」构成，不要写成「冀」「寄」；「旅客」指漂泊在外的人，不是今天的「游客」。"},{"w":"泉","e":"【易错】「已知泉路近」的「泉路」指黄泉之路，即死亡，不要理解为「泉水边的路」；「泉」不写「全」。"},{"w":"全","e":"【易错】「已知泉路近」的「泉路」指黄泉之路，即死亡，不要理解为「泉水边的路」；「泉」不写「全」。"},{"w":"欲","e":"【易错】「欲别故乡难」的「欲」是「将要、想要」，不写「愈」「浴」；本篇与《南安军》同为绝命之作，注意两首诗的诗句不要串写。"},{"w":"愈","e":"【易错】「欲别故乡难」的「欲」是「将要、想要」，不写「愈」「浴」；本篇与《南安军》同为绝命之作，注意两首诗的诗句不要串写。"},{"w":"浴","e":"【易错】「欲别故乡难」的「欲」是「将要、想要」，不写「愈」「浴」；本篇与《南安军》同为绝命之作，注意两首诗的诗句不要串写。"}]},{"type":"list","title":"名句","items":["无限河山泪，谁言天地宽。","毅魄归来日，灵旗空际看。"]},{"type":"list","title":"背诵提示","items":["「今日又南冠」的「南冠」是囚徒的代称，不要按字面写成「南方的帽子」，也不要写成「南官」「男冠」。","「毅魄归来日」的「毅」是刚毅、坚决之意，不写成「意」「义」；「魄」的右半是「鬼」，不写成「愧」。","「灵旗空际看」的「旗」是方字旁加「其」，不写「棋」「琪」；「空际」指天空、空中，不要写成「空寂」。","「三年羁旅客」的「羁」上半是「罒」、下半由「革」「马」构成，不要写成「冀」「寄」；「旅客」指漂泊在外的人，不是今天的「游客」。","「已知泉路近」的「泉路」指黄泉之路，即死亡，不要理解为「泉水边的路」；「泉」不写「全」。","「欲别故乡难」的「欲」是「将要、想要」，不写「愈」「浴」；本篇与《南安军》同为绝命之作，注意两首诗的诗句不要串写。"]}],"questions":[{"id":"p-p9b-bie-yun-jian-m0","type":"fill","stem":"默写填空：无限河山泪，______。","answer":"谁言天地宽。","explain":"出自《别云间》（明·夏完淳）：无限河山泪，谁言天地宽。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-bie-yun-jian-m1","type":"fill","stem":"默写填空：毅魄归来日，______。","answer":"灵旗空际看。","explain":"出自《别云间》（明·夏完淳）：毅魄归来日，灵旗空际看。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-bie-yun-jian-u","type":"fill","stem":"理解性默写：（我）做了三年漂泊在外的客子，今天又成了囚徒。「羁旅客」指长期寄居他乡、漂泊不定的人；「南冠」是囚徒的代称，典出《左传》，写被俘的楚人仍戴南方的帽子，这里指自己被清兵逮捕。","answer":"三年羁旅客，今日又南冠。","explain":"出自《别云间》（明·夏完淳）。句意：（我）做了三年漂泊在外的客子，今天又成了囚徒。「羁旅客」指长期寄居他乡、漂泊不定的人；「南冠」是囚徒的代称，典出《左传》，写被俘的楚人仍戴南方的帽子，这里指自己被清兵逮捕。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-shan-po-yang-li-shan","title":"山坡羊·骊山怀古","subtitle":"元·张养浩","grade":"9b","tags":["怀古","兴亡","咏史","讽喻"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"元·张养浩"},{"k":"体裁","v":"曲"}]},{"type":"note","title":"作者简介","text":"张养浩（1270—1329），字希孟，号云庄，元代散曲家、政治家，济南（今山东济南）人。\n生平经历：他历任监察御史、礼部尚书等职，因上疏直言、得罪权贵而辞官归隐云庄；天历二年关中大旱，他被召为陕西行台中丞前往赈灾，到官仅四个月便积劳成疾而卒。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是张养浩的怀古散曲，与库中《山坡羊·潼关怀古》同用「山坡羊」曲牌，但为两篇不同作品：此曲写骊山古迹、叹王朝兴亡，彼曲写潼关形势、叹百姓苦难。开篇“骊山四顾，阿房一炬”用杜牧《阿房宫赋》所写项羽焚烧阿房宫的典故，一起笔就把昔日宫阙的奢华与今日的一炬成灰放在一起，用典精当；紧接着以“当时奢侈今何处？”的反问把历史巨变的感慨逼出，再以“只见草萧疏，水萦纡”的眼前景物作答，借景抒情，以荒草、曲水的冷寂反衬当年宫室的繁华。“至今遗恨迷烟树”由景入情，写历代败亡的遗恨如烟树迷茫，暗含借古讽今——后人并未真正记取前朝亡国的教训。“列国周齐秦汉楚”把视野从秦扩及历代，末句“赢，都变做了土；输，都变做了土”以对比与反复收束，斩钉截铁。两曲的比较阅读是中考常见考点：二者同曲牌、同属怀古题材，同以“都变做了土”式的对举句收束，都表现出对王朝兴亡的清醒认识；但《潼关怀古》的着眼点在百姓，以“兴，百姓苦；亡，百姓苦”揭示无论兴亡都以百姓苦难为代价，同情人民、鞭挞统治者；《骊山怀古》的着眼点在争权夺利的统治者自身，讽刺他们无论胜败都难逃与宫阙共化泥土的结局，讽刺中见冷峻"},{"type":"list","title":"中考考点","items":["与《山坡羊·潼关怀古》的比较（同曲牌、同怀古、同以对举收束，一叹百姓苦难、一叹王朝兴亡）","“阿房一炬”的用典与“当时奢侈今何处”的反问、借景抒情手法","“草萧疏”“水萦纡”的景物描写及其作用","“赢，都变做了土","输，都变做了土”的思想内涵与对比手法。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"骊山四顾，阿房一炬，当时奢侈今何处？","n":"","cn":"在骊山上四处眺望，当年宏伟的阿房宫被一把大火烧毁，那时的繁华奢侈如今到哪里去了呢？「骊山」在今陕西临潼，是秦始皇陵与唐代华清宫所在；「阿房一炬」指项羽入关后焚烧阿房宫，用杜牧《阿房宫赋》所写的史事；「奢侈」指统治者的豪华奢靡；此句以反问逼出历史巨变的感慨。","parts":[{"t":"骊山四顾","k":2},{"t":"，"},{"t":"阿房一炬","k":0},{"t":"，当时"},{"t":"奢侈","k":7},{"t":"今何处？"}]},{"t":"只见草萧疏，水萦纡。","n":"","cn":"只见荒草稀疏零落，河水曲折回绕。「萧疏」指草木稀疏、零落冷寂；「萦纡」指水流盘旋曲折，读 yíng yū。两句以眼前荒凉景物作答，借景抒情，反衬当年宫室的繁华。","parts":[{"t":"只见草"},{"t":"萧疏","k":8},{"t":"，"},{"t":"水萦纡","k":5},{"t":"。"}]},{"t":"至今遗恨迷烟树。","n":"","cn":"直到今天，那亡国的遗恨依然笼罩在烟雾迷蒙的树林之间。「遗恨」指前朝败亡留下的遗憾；「迷烟树」写遗恨如烟雾弥漫于树林，迷蒙而不见教训，暗含借古讽今之意。","parts":[{"t":"至今"},{"t":"遗恨","k":10},{"t":"迷烟树","k":6},{"t":"。"}]},{"t":"列国周齐秦汉楚。","n":"","cn":"从列国时代到周、齐、秦、汉、楚，哪一个朝代不是如此呢？「列国」指春秋战国时期的各诸侯国；「周齐秦汉楚」泛指历代王朝，把视野由秦一代扩展到历朝，写尽朝代更替之频繁。","parts":[{"t":"列国","k":11},{"t":"周齐秦汉楚。"}]},{"t":"赢，都变做了土；输，都变做了土。","n":"","cn":"赢了的，都变成了泥土；输了的，也都变成了泥土。「赢」「输」指争权夺利的胜败双方（如项羽与秦王朝）；两句句式相同、以对比收束，指出无论胜败兴亡最终都归于尘土，是对封建王朝历史规律的冷峻概括。","parts":[{"t":"赢，"},{"t":"都","k":23},{"t":"变做了土","k":4},{"t":"；"},{"t":"输","k":18},{"t":"，"},{"t":"都","k":23},{"t":"变做了土","k":4},{"t":"。"}]}],"words":[{"w":"阿房一炬","e":"指项羽入关后焚烧阿房宫"},{"w":"一所房子","e":"【易错】“阿房一炬”的「阿房」读 ē páng，指阿房宫，不要读成「ā fáng」并理解为「一所房子」；「一炬」指一把大火。"},{"w":"骊山四顾","e":"【易错】本篇与库中《山坡羊·潼关怀古》是同一曲牌的两篇，默写时不要把「骊山四顾」与「峰峦如聚」混记，也不要把末句写成「兴，百姓苦；亡，百姓苦」。"},{"w":"峰峦如聚","e":"【易错】本篇与库中《山坡羊·潼关怀古》是同一曲牌的两篇，默写时不要把「骊山四顾」与「峰峦如聚」混记，也不要把末句写成「兴，百姓苦；亡，百姓苦」。"},{"w":"变做了土","e":"【易错】“列国周齐秦汉楚”按顺序列举历代王朝，五个朝代名缺一不可，不要漏写或颠倒；末句两个「都」与「变做了土」都要写，中间的「；」不要写成「，」。"},{"w":"水萦纡","e":"【易错】“水萦纡”的「萦纡」指水流盘旋曲折，两字都是绞丝旁，不要写成「萦迁」「莹纡」，读 yíng yū。"},{"w":"迷烟树","e":"【易错】“至今遗恨迷烟树”的「遗恨」指前朝败亡留下的遗憾，不写「遗撼」；「迷烟树」的「迷」是弥漫、迷蒙之意，不写「谜」。"},{"w":"奢侈","e":"指统治者的豪华奢靡"},{"w":"萧疏","e":"指草木稀疏、零落冷寂"},{"w":"萦纡","e":"指水流盘旋曲折"},{"w":"遗恨","e":"指前朝败亡留下的遗憾"},{"w":"列国","e":"指春秋战国时期的各诸侯国"},{"w":"萦迁","e":"【易错】“水萦纡”的「萦纡」指水流盘旋曲折，两字都是绞丝旁，不要写成「萦迁」「莹纡」，读 yíng yū。"},{"w":"莹纡","e":"【易错】“水萦纡”的「萦纡」指水流盘旋曲折，两字都是绞丝旁，不要写成「萦迁」「莹纡」，读 yíng yū。"},{"w":"阿房","e":"【易错】“阿房一炬”的「阿房」读 ē páng，指阿房宫，不要读成「ā fáng」并理解为「一所房子」；「一炬」指一把大火。"},{"w":"一炬","e":"【易错】“阿房一炬”的「阿房」读 ē páng，指阿房宫，不要读成「ā fáng」并理解为「一所房子」；「一炬」指一把大火。"},{"w":"箫疏","e":"【易错】“只见草萧疏”的「萧疏」指荒草稀疏零落，不写「箫疏」；「疏」不写「蔬」。"},{"w":"遗撼","e":"【易错】“至今遗恨迷烟树”的「遗恨」指前朝败亡留下的遗憾，不写「遗撼」；「迷烟树」的「迷」是弥漫、迷蒙之意，不写「谜」。"},{"w":"输","e":"指争权夺利的胜败双方（如项羽与秦王朝）"},{"w":"疏","e":"【易错】“只见草萧疏”的「萧疏」指荒草稀疏零落，不写「箫疏」；「疏」不写「蔬」。"},{"w":"蔬","e":"【易错】“只见草萧疏”的「萧疏」指荒草稀疏零落，不写「箫疏」；「疏」不写「蔬」。"},{"w":"迷","e":"【易错】“至今遗恨迷烟树”的「遗恨」指前朝败亡留下的遗憾，不写「遗撼」；「迷烟树」的「迷」是弥漫、迷蒙之意，不写「谜」。"},{"w":"谜","e":"【易错】“至今遗恨迷烟树”的「遗恨」指前朝败亡留下的遗憾，不写「遗撼」；「迷烟树」的「迷」是弥漫、迷蒙之意，不写「谜」。"},{"w":"都","e":"【易错】“列国周齐秦汉楚”按顺序列举历代王朝，五个朝代名缺一不可，不要漏写或颠倒；末句两个「都」与「变做了土」都要写，中间的「；」不要写成「，」。"}]},{"type":"list","title":"名句","items":["当时奢侈今何处？","赢，都变做了土；输，都变做了土。"]},{"type":"list","title":"背诵提示","items":["“水萦纡”的「萦纡」指水流盘旋曲折，两字都是绞丝旁，不要写成「萦迁」「莹纡」，读 yíng yū。","“阿房一炬”的「阿房」读 ē páng，指阿房宫，不要读成「ā fáng」并理解为「一所房子」；「一炬」指一把大火。","“只见草萧疏”的「萧疏」指荒草稀疏零落，不写「箫疏」；「疏」不写「蔬」。","本篇与库中《山坡羊·潼关怀古》是同一曲牌的两篇，默写时不要把「骊山四顾」与「峰峦如聚」混记，也不要把末句写成「兴，百姓苦；亡，百姓苦」。","“至今遗恨迷烟树”的「遗恨」指前朝败亡留下的遗憾，不写「遗撼」；「迷烟树」的「迷」是弥漫、迷蒙之意，不写「谜」。","“列国周齐秦汉楚”按顺序列举历代王朝，五个朝代名缺一不可，不要漏写或颠倒；末句两个「都」与「变做了土」都要写，中间的「；」不要写成「，」。"]}],"questions":[{"id":"p-p9b-shan-po-yang-li-shan-m0","type":"fill","stem":"默写填空：赢，______。","answer":"都变做了土。","explain":"出自《山坡羊·骊山怀古》（元·张养浩）：赢，都变做了土；输，都变做了土。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-shan-po-yang-li-shan-u","type":"fill","stem":"理解性默写：在骊山上四处眺望，当年宏伟的阿房宫被一把大火烧毁，那时的繁华奢侈如今到哪里去了呢？「骊山」在今陕西临潼，是秦始皇陵与唐代华清宫所在；「阿房一炬」指项羽入关后焚烧阿房宫，用杜牧《阿房宫赋》所写的史事；「奢侈」指统治者的豪华奢靡；此句以反问逼出历史巨变的感慨。","answer":"骊山四顾，阿房一炬，当时奢侈今何处？","explain":"出自《山坡羊·骊山怀古》（元·张养浩）。句意：在骊山上四处眺望，当年宏伟的阿房宫被一把大火烧毁，那时的繁华奢侈如今到哪里去了呢？「骊山」在今陕西临潼，是秦始皇陵与唐代华清宫所在；「阿房一炬」指项羽入关后焚烧阿房宫，用杜牧《阿房宫赋》所写的史事；「奢侈」指统治者的豪华奢靡；此句以反问逼出历史巨变的感慨。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]},{"id":"p9b-chao-tian-zi-yong-la-ba","title":"朝天子·咏喇叭","subtitle":"明·王磐","grade":"9b","tags":["讽喻","民生","咏物","讽刺"],"blocks":[{"type":"meta","items":[{"k":"作者","v":"明·王磐"},{"k":"体裁","v":"曲"}]},{"type":"note","title":"作者简介","text":"王磐（约1470—1530），字鸿渐，号西楼，高邮（今江苏高邮）人，明代散曲家，散曲集名《西楼乐府》。\n生平经历：他出身富家却厌弃功名，一生不曾应举做官，喜好读书、游览与词曲创作；正德年间宦官当权，官船往来地方、骚扰百姓，他目睹此弊而写下讽刺之作；晚年隐居故里，以吟咏自娱。"},{"type":"h","text":"写作背景与赏析"},{"type":"p","text":"这是明代散曲家王磐借咏喇叭讽刺宦官的作品，是散曲中小题大做、借物讽喻的名篇。王磐生活于明正德年间，当时宦官专权，常乘官船往来各地，吹吹打打、骚扰百姓、横索财物，作者便以喇叭、唢呐为题，用一副笔墨写两种对象。全曲抓住喇叭“曲儿小腔儿大”的特点——本事不大、声响极大，与宦官依仗皇权、装腔作势的形象妙相吻合，咏物即在写人，是典型的托物讽喻（借物咏人）。“官船来往乱如麻，全仗你抬声价”把喇叭与宦官的威风直接扣合，揭露其狐假虎威；“军听了军愁，民听了民怕”以句式相同的对句写军民共同的恐惧，从侧面烘托宦官扰民之烈。“哪里去辨甚么真共假”用反问揭出宦官假借圣旨、真假难辨的横蛮。“眼见的吹翻了这家，吹伤了那家，只吹的水尽鹅飞罢”连用三个「吹」字，层层递进，以夸张与形象的比喻写百姓被搜刮殆尽、倾家荡产的惨状，语气由冷嘲转为愤慨。全曲语言通俗、多用口语与衬字，幽默中见辛辣，讽刺意味极强"},{"type":"list","title":"中考考点","items":["托物讽喻的写法与“曲儿小腔儿大”的双关讽刺效果","对偶句“军听了军愁，民听了民怕”的作用","三个「吹」字与“水尽鹅飞”的表达效果","“哪里去辨甚么真共假”的反问所揭露的宦官横蛮","全曲对宦官横行的批判与对百姓的同情。"]},{"type":"lines","title":"原文 · 点字词看释义","items":[{"t":"喇叭，唢呐，曲儿小腔儿大。","n":"","cn":"喇叭，唢呐，曲子短小，声音却很大。「唢呐」是一种管乐器；「曲儿小腔儿大」表面写乐器，实则讽刺宦官本事不大而气焰嚣张，咏物即写人。","parts":[{"t":"喇叭","k":8},{"t":"，"},{"t":"唢呐","k":3},{"t":"，"},{"t":"曲","k":14},{"t":"儿小"},{"t":"腔","k":15},{"t":"儿大。"}]},{"t":"官船来往乱如麻，全仗你抬声价。","n":"","cn":"官船来来往往，乱得像一团麻，全仗着你（喇叭）来抬高身价。「官船」指宦官乘坐的船只；「仗」是倚仗、依靠；「抬声价」指抬高身价、显摆威风，讽刺宦官狐假虎威。","parts":[{"t":"官船","k":4},{"t":"来往乱如麻，全"},{"t":"仗","k":12},{"t":"你"},{"t":"抬声价","k":0},{"t":"。"}]},{"t":"军听了军愁，民听了民怕。","n":"","cn":"军队听了军队发愁，百姓听了百姓害怕。两句句式相同，从军民共同的恐惧侧面写宦官借吹打骚扰、勒索，令人闻声色变。","parts":[{"t":"军听了军愁，民听了民怕。"}]},{"t":"哪里去辨甚么真共假？","n":"","cn":"到哪里去分辨什么是真、什么是假呢？「甚么」即「什么」；「真共假」是「真与假」。以反问讽刺宦官假借圣旨、真假难辨而任意横索。","parts":[{"t":"哪里去"},{"t":"辨","k":19},{"t":"甚么","k":5},{"t":"真共假","k":1},{"t":"？"}]},{"t":"眼见的吹翻了这家，吹伤了那家，只吹的水尽鹅飞罢！","n":"","cn":"眼看着吹翻了这一家，吹伤了那一家，只吹得水干了、鹅也飞光了才肯罢休。「眼见的」即「眼见得」，分明看见；「水尽鹅飞」比喻百姓被搜刮得一干二净、倾家荡产；「罢」是罢休、完结。连用三个「吹」字，层层递进，写尽扰民之烈。","parts":[{"t":"眼见的","k":2},{"t":"吹","k":25},{"t":"翻了这家，"},{"t":"吹","k":25},{"t":"伤了那家，只"},{"t":"吹","k":25},{"t":"的","k":22},{"t":"水尽鹅飞"},{"t":"罢","k":13},{"t":"！"}]}],"words":[{"w":"抬声价","e":"指抬高身价、显摆威风"},{"w":"真共假","e":"是「真与假」"},{"w":"眼见的","e":"即「眼见得」"},{"w":"唢呐","e":"是一种管乐器"},{"w":"官船","e":"指宦官乘坐的船只"},{"w":"甚么","e":"即「什么」"},{"w":"锁呐","e":"【易错】“唢呐”是管乐器，两字都是口字旁，不要写成「锁呐」「唢哪」；「喇叭」两字也都是口字旁。"},{"w":"唢哪","e":"【易错】“唢呐”是管乐器，两字都是口字旁，不要写成「锁呐」「唢哪」；「喇叭」两字也都是口字旁。"},{"w":"喇叭","e":"【易错】“唢呐”是管乐器，两字都是口字旁，不要写成「锁呐」「唢哪」；「喇叭」两字也都是口字旁。"},{"w":"声价","e":"【易错】“全仗你抬声价”的「仗」是单人旁，指倚仗、依靠，不写「丈」「杖」；「声价」指身价、名声地位，不是「声音的价格」。"},{"w":"什么","e":"【易错】“哪里去辨甚么真共假”的「辨」是分辨，不要写成「辩」「辫」；「甚么」即「什么」，不要写成「什吗」。"},{"w":"什吗","e":"【易错】“哪里去辨甚么真共假”的「辨」是分辨，不要写成「辩」「辫」；「甚么」即「什么」，不要写成「什吗」。"},{"w":"仗","e":"是倚仗、依靠"},{"w":"罢","e":"是罢休、完结"},{"w":"曲","e":"【易错】“曲儿小腔儿大”的「曲」读 qǔ，指曲子，不读 qū；「腔」是月字旁，指声音、腔调，不写「空」。"},{"w":"腔","e":"【易错】“曲儿小腔儿大”的「曲」读 qǔ，指曲子，不读 qū；「腔」是月字旁，指声音、腔调，不写「空」。"},{"w":"空","e":"【易错】“曲儿小腔儿大”的「曲」读 qǔ，指曲子，不读 qū；「腔」是月字旁，指声音、腔调，不写「空」。"},{"w":"丈","e":"【易错】“全仗你抬声价”的「仗」是单人旁，指倚仗、依靠，不写「丈」「杖」；「声价」指身价、名声地位，不是「声音的价格」。"},{"w":"杖","e":"【易错】“全仗你抬声价”的「仗」是单人旁，指倚仗、依靠，不写「丈」「杖」；「声价」指身价、名声地位，不是「声音的价格」。"},{"w":"辨","e":"【易错】“哪里去辨甚么真共假”的「辨」是分辨，不要写成「辩」「辫」；「甚么」即「什么」，不要写成「什吗」。"},{"w":"辩","e":"【易错】“哪里去辨甚么真共假”的「辨」是分辨，不要写成「辩」「辫」；「甚么」即「什么」，不要写成「什吗」。"},{"w":"辫","e":"【易错】“哪里去辨甚么真共假”的「辨」是分辨，不要写成「辩」「辫」；「甚么」即「什么」，不要写成「什吗」。"},{"w":"的","e":"【易错】“眼见的吹翻了这家”与“只吹的水尽鹅飞罢”两句的「的」都不写成「得」；「罢」是罢休，不写「吧」。"},{"w":"得","e":"【易错】“眼见的吹翻了这家”与“只吹的水尽鹅飞罢”两句的「的」都不写成「得」；「罢」是罢休，不写「吧」。"},{"w":"吧","e":"【易错】“眼见的吹翻了这家”与“只吹的水尽鹅飞罢”两句的「的」都不写成「得」；「罢」是罢休，不写「吧」。"},{"w":"吹","e":"【易错】“军听了军愁，民听了民怕”两句句式相同、缺一不可，不要只写一句；末句三个「吹」字也要都写，不要漏写。"}]},{"type":"list","title":"名句","items":["官船来往乱如麻，全仗你抬声价。","眼见的吹翻了这家，吹伤了那家，只吹的水尽鹅飞罢！"]},{"type":"list","title":"背诵提示","items":["“唢呐”是管乐器，两字都是口字旁，不要写成「锁呐」「唢哪」；「喇叭」两字也都是口字旁。","“曲儿小腔儿大”的「曲」读 qǔ，指曲子，不读 qū；「腔」是月字旁，指声音、腔调，不写「空」。","“全仗你抬声价”的「仗」是单人旁，指倚仗、依靠，不写「丈」「杖」；「声价」指身价、名声地位，不是「声音的价格」。","“哪里去辨甚么真共假”的「辨」是分辨，不要写成「辩」「辫」；「甚么」即「什么」，不要写成「什吗」。","“眼见的吹翻了这家”与“只吹的水尽鹅飞罢”两句的「的」都不写成「得」；「罢」是罢休，不写「吧」。","“军听了军愁，民听了民怕”两句句式相同、缺一不可，不要只写一句；末句三个「吹」字也要都写，不要漏写。"]}],"questions":[{"id":"p-p9b-chao-tian-zi-yong-la-ba-m0","type":"fill","stem":"默写填空：官船来往乱如麻，______。","answer":"全仗你抬声价。","explain":"出自《朝天子·咏喇叭》（明·王磐）：官船来往乱如麻，全仗你抬声价。","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-chao-tian-zi-yong-la-ba-m1","type":"fill","stem":"默写填空：眼见的吹翻了这家，______。","answer":"吹伤了那家。","explain":"出自《朝天子·咏喇叭》（明·王磐）：眼见的吹翻了这家，吹伤了那家，只吹的水尽鹅飞罢！","difficulty":1,"tags":["直接默写"],"rubric":["上下句衔接准确","不写错别字"]},{"id":"p-p9b-chao-tian-zi-yong-la-ba-u","type":"fill","stem":"理解性默写：喇叭，唢呐，曲子短小，声音却很大。「唢呐」是一种管乐器；「曲儿小腔儿大」表面写乐器，实则讽刺宦官本事不大而气焰嚣张，咏物即写人。","answer":"喇叭，唢呐，曲儿小腔儿大。","explain":"出自《朝天子·咏喇叭》（明·王磐）。句意：喇叭，唢呐，曲子短小，声音却很大。「唢呐」是一种管乐器；「曲儿小腔儿大」表面写乐器，实则讽刺宦官本事不大而气焰嚣张，咏物即写人。","difficulty":2,"tags":["理解性默写"],"rubric":["句意对应准确","不写错别字"]}]}];
